  --cor-texto: #e8eaff;
  --cor-texto-suave: #9aa0c8;
  --cor-ciano: #00f0ff;
  --cor-magenta: #ff2bd6;
  --cor-violeta: #7b3cff;
  --cor-cartao: rgba(16, 10, 40, 0.62);
  --raio-cartao: 16px;
  --fonte-titulo: "Orbitron", "Segoe UI", sans-serif;
  --fonte-dados: "Share Tech Mono", "Consolas", monospace;
  --espaco: 24px;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100vh;
  color: var(--cor-texto);
  font-family: var(--fonte-dados);
  background:
    radial-gradient(ellipse at 15% 10%, rgba(123, 60, 255, 0.35), transparent 55%),
    radial-gradient(ellipse at 85% 90%, rgba(255, 43, 214, 0.25), transparent 55%),
    var(--cor-fundo);
  overflow-x: hidden;
}

.grade-fundo {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(0, 240, 255, 0.07) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 240, 255, 0.07) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: radial-gradient(ellipse at center, #000 30%, transparent 85%);
}

.varredura {
  position: fixed;
  left: 0;
  right: 0;
  top: 0;
  height: 3px;
  z-index: 1;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, var(--cor-ciano), transparent);
  box-shadow: 0 0 18px var(--cor-ciano);
  animation: varrer 7s linear infinite;
}

.pagina {
  position: relative;
  z-index: 2;
  max-width: 1500px;
  min-height: 100vh;
  margin: 0 auto;
  padding: 20px var(--espaco);
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.topo {
  text-align: center;
  margin-bottom: 24px;
}

.topo__rede {
  width: 100%;
  max-width: 300px;
  height: 56px;
  margin-bottom: 4px;
}

.rede__linha {
  stroke: var(--cor-ciano);
  stroke-width: 1.2;
  stroke-dasharray: 6 6;
  opacity: 0.7;
  animation: fluir 2.4s linear infinite;
}

.rede__no {
  fill: var(--cor-magenta);
  filter: drop-shadow(0 0 6px var(--cor-magenta));
  animation: pulsar 2.2s ease-in-out infinite;
}

.rede__no--alt {
  fill: var(--cor-ciano);
  filter: drop-shadow(0 0 6px var(--cor-ciano));
  animation-delay: 0.8s;
}

.topo__etiqueta {
  display: inline-block;
  padding: 4px 14px;
  border: 1px solid var(--cor-ciano);
  border-radius: 999px;
  color: var(--cor-ciano);
  font-size: 0.8rem;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  box-shadow: 0 0 12px rgba(0, 240, 255, 0.35);
}

.topo__titulo {
  margin: 10px 0 8px;
  font-family: var(--fonte-titulo);
  font-weight: 900;
  font-size: clamp(1.6rem, 4vw, 2.6rem);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  background: linear-gradient(90deg, var(--cor-ciano), var(--cor-violeta), var(--cor-magenta));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 14px rgba(123, 60, 255, 0.6));
}

.topo__subtitulo {
  margin: 0 auto;
  max-width: 560px;
  color: var(--cor-texto-suave);
  font-size: 1.05rem;
  line-height: 1.6;
}

.lista-cartoes {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: var(--espaco);
}

.cartao {
  --cor-destaque: var(--cor-ciano);
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 20px;
  color: inherit;
  text-decoration: none;
  background: var(--cor-cartao);
  border: 1px solid color-mix(in srgb, var(--cor-destaque) 55%, transparent);
  border-radius: var(--raio-cartao);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 0 22px color-mix(in srgb, var(--cor-destaque) 25%, transparent);
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
  overflow: hidden;
}

.cartao::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--cor-destaque), transparent);
}

.cartao:hover,
.cartao:focus-visible {
  transform: translateY(-6px);
  border-color: var(--cor-destaque);
  box-shadow:
    0 0 34px color-mix(in srgb, var(--cor-destaque) 55%, transparent),
    inset 0 0 24px color-mix(in srgb, var(--cor-destaque) 12%, transparent);
}

.cartao:focus-visible {
  outline: 2px solid var(--cor-magenta);
  outline-offset: 3px;
}

.cartao--ciano { --cor-destaque: var(--cor-ciano); }
.cartao--magenta { --cor-destaque: var(--cor-magenta); }
.cartao--violeta { --cor-destaque: #a678ff; }
.cartao--verde { --cor-destaque: #3dffa8; }
.cartao--ambar { --cor-destaque: #ffb02b; }

.cartao__numero {
  font-family: var(--fonte-titulo);
  font-size: 0.85rem;
  letter-spacing: 0.3em;
  color: var(--cor-destaque);
  text-shadow: 0 0 10px var(--cor-destaque);
}

.cartao__icone {
  width: 42px;
  height: 42px;
  fill: none;
  stroke: var(--cor-destaque);
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 0 6px var(--cor-destaque));
}

.cartao__titulo {
  margin: 0;
  font-family: var(--fonte-titulo);
  font-size: 1.2rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.cartao__texto {
  margin: 0;
  flex: 1;
  color: var(--cor-texto-suave);
  font-size: 0.9rem;
  line-height: 1.45;
}

.cartao__telemetria {
  width: 100%;
  height: 6px;
  border: 0;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
  appearance: none;
  -webkit-appearance: none;
}

.cartao__telemetria::-webkit-progress-bar {
  background: rgba(255, 255, 255, 0.08);
}

.cartao__telemetria::-webkit-progress-value {
  background: linear-gradient(90deg, var(--cor-destaque), #fff);
  box-shadow: 0 0 10px var(--cor-destaque);
}

.cartao__telemetria::-moz-progress-bar {
  background: linear-gradient(90deg, var(--cor-destaque), #fff);
}

.cartao__acao {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--cor-destaque);
  font-family: var(--fonte-titulo);
  font-size: 0.8rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.rodape {
  margin-top: 24px;
  text-align: center;
  color: var(--cor-texto-suave);
  font-size: 0.85rem;
  letter-spacing: 0.15em;
}

@keyframes varrer {
  from { transform: translateY(-10px); }
  to { transform: translateY(100vh); }
}

@keyframes fluir {
  to { stroke-dashoffset: -24; }
}

@keyframes pulsar {
  0%, 100% { opacity: 0.55; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.35); }
}

.rede__no {
  transform-box: fill-box;
  transform-origin: center;
}

@media (prefers-reduced-motion: reduce) {
  .varredura,
  .rede__linha,
  .rede__no {
    animation: none;
  }

  .cartao {
    transition: none;
  }

  .cartao:hover,
  .cartao:focus-visible {
    transform: none;
  }
}

@media (max-width: 720px) {
  .pagina {
    justify-content: flex-start;
    padding-top: 24px;
  }

  .lista-cartoes {
    grid-template-columns: 1fr;
  }
}

.cartao--rosa { --cor-destaque: #ff6ba8; }
.cartao--azul { --cor-destaque: #4d8dff; }

.lista-cartoes--sete {
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
}

.projeto__voltar {
  display: inline-block;
  margin-bottom: 20px;
  color: var(--cor-ciano);
  text-decoration: none;
  letter-spacing: 0.15em;
}

.projeto__voltar:focus-visible {
  outline: 2px solid var(--cor-magenta);
  outline-offset: 3px;
}

.projeto__bloco {
  margin-bottom: 20px;
  padding: 22px;
  background: var(--cor-cartao);
  border: 1px solid rgba(0, 240, 255, 0.35);
  border-radius: var(--raio-cartao);
  backdrop-filter: blur(12px);
}

.projeto__bloco h2 {
  margin: 0 0 10px;
  font-family: var(--fonte-titulo);
  font-size: 1rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--cor-ciano);
}

.projeto__bloco p,
.projeto__bloco li {
  color: var(--cor-texto);
  line-height: 1.6;
}

/*
 * markdown.css — estilo futurista para blocos de prompt/Markdown.
 * Reutilizável: basta vincular este arquivo e usar as classes abaixo.
 * Depende das variáveis de :root definidas em estilo.css.
 */

/* ---------- Barra do bloco (título + botão copiar) ---------- */
.prompt__barra {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.prompt__barra h2 {
  margin: 0;
}

.botao-copiar {
  padding: 8px 18px;
  border: 1px solid var(--cor-ciano);
  border-radius: 10px;
  background: rgba(0, 240, 255, 0.08);
  color: var(--cor-ciano);
  font-family: var(--fonte-titulo);
  font-size: 0.75rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);
  transition: background 0.2s ease, box-shadow 0.2s ease, color 0.2s ease;
}

.botao-copiar:hover {
  background: rgba(0, 240, 255, 0.2);
  box-shadow: 0 0 20px rgba(0, 240, 255, 0.5);
}

.botao-copiar:focus-visible {
  outline: 2px solid var(--cor-magenta);
  outline-offset: 3px;
}

.botao-copiar--ok {
  border-color: #3dffa8;
  color: #3dffa8;
  background: rgba(61, 255, 168, 0.12);
  box-shadow: 0 0 16px rgba(61, 255, 168, 0.4);
}

/* ---------- Bloco do prompt ---------- */
.projeto__prompt {
  margin: 0;
  padding: 20px;
  max-height: 70vh;
  overflow: auto;
  white-space: pre-wrap;
  font-family: var(--fonte-dados);
  font-size: 0.9rem;
  line-height: 1.65;
  color: var(--cor-texto);
  background: rgba(0, 0, 0, 0.5);
  border: 1px solid rgba(123, 60, 255, 0.35);
  border-left: 3px solid var(--cor-magenta);
  border-radius: 10px;
  scrollbar-color: var(--cor-violeta) transparent;
  scrollbar-width: thin;
}

.projeto__prompt::-webkit-scrollbar {
  width: 8px;
}

.projeto__prompt::-webkit-scrollbar-thumb {
  background: var(--cor-violeta);
  border-radius: 8px;
}

/* ---------- Realce de sintaxe (gerado por copiar.js) ---------- */
.pt-titulo {
  display: block;
  margin-top: 8px;
  color: var(--cor-ciano);
  font-weight: 700;
  text-shadow: 0 0 8px rgba(0, 240, 255, 0.5);
}

.pt-marcador {
  color: var(--cor-magenta);
  font-weight: 700;
}

.pt-rotulo {
  color: #a678ff;
  font-weight: 700;
}

.pt-var {
  padding: 0 4px;
  border-radius: 4px;
  background: rgba(255, 176, 43, 0.15);
  color: #ffb02b;
}

.pt-forte {
  color: #fff;
  font-weight: 700;
}

.pt-citacao {
  color: #3dffa8;
}

.pt-alerta {
  color: #ff6b6b;
  font-weight: 700;
}

.pt-json {
  display: block;
  color: #3dffa8;
}

@media (prefers-reduced-motion: reduce) {
  .botao-copiar {
    transition: none;
  }
}

