const SPIN = ['◐', '◓', '◑', '◒']
const PULSE = ['●∙∙', '∙●∙', '∙∙●', '∙●∙']

const KIND_COLOR: Record<StepKind, string> = {
  Command: '#ffb000',
  Connector: '#3b82ff',
  'File read': '#39ff88',
  'File write': '#00f0ff',
  Skill: '#b15cff',
