/* ============================================================================
   dashboard.css — cards da página Dashboard
   ========================================================================== */

.dashboard-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}

.dashboard-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 18px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(180, 110, 255, 0.28);
  box-shadow: var(--shadow-card, none);
}

.dashboard-card-titulo {
  margin: 0;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--txt-soft);
}

.dashboard-card-valor {
  margin: 0;
  font-size: 15px;
  color: var(--txt-dim);
}

@media (max-width: 640px) {
  .dashboard-cards { grid-template-columns: 1fr; }
}

/* Botões do card */
.dashboard-card-acoes {
  display: flex;
  gap: 10px;
  margin-top: auto;
}
.dashboard-card-acoes .ideia-detalhes { flex: 1; margin-top: 0; }

/* Modal de cálculos */
.calculos-formulario {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  margin: 16px 0;
}
.calculos-campo { display: grid; gap: 4px; font-size: 12px; color: var(--txt-soft); }
.calculos-campo input[type="text"] {
  min-height: 44px;
  padding: 8px 12px;
  border-radius: 10px;
  border: 1px solid rgba(180, 110, 255, 0.3);
  background: rgba(255, 255, 255, 0.05);
  color: var(--txt);
  font-family: inherit;
  font-size: 15px;
}
.calculos-campo input[type="text"]:focus { border-color: var(--h2); outline: none; }
.calculos-campo-check {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 8px;
}

.calculos-lista { margin: 0; display: grid; gap: 4px; }
.calculos-linha {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 6px 0;
  border-bottom: 1px solid rgba(180, 110, 255, 0.15);
  font-size: 14px;
}
.calculos-linha dt { color: var(--txt-dim); }
.calculos-linha dd { margin: 0; font-weight: 700; color: var(--txt); white-space: nowrap; }

@media (max-width: 640px) {
  .calculos-formulario { grid-template-columns: 1fr; }
  .calculos-linha { flex-direction: column; gap: 2px; }
}

/* Link com aparência de botão (ex.: "Abrir site") */
a.ideia-detalhes {
  display: flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
}

/* Modal de documentos (iframe) */
.dashboard-card-acoes { flex-wrap: wrap; }
.dashboard-card-acoes .ideia-detalhes { min-width: 110px; }

.ideia-modal--largo { width: min(1100px, calc(100vw - 24px)); }
.ideia-modal--largo[open] { display: flex; flex-direction: column; height: calc(100dvh - 40px); }

.documentos-barra {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 20px;
  border-bottom: 1px solid rgba(180, 110, 255, 0.2);
}
.documentos-abas { display: flex; gap: 8px; flex-wrap: wrap; }
.documentos-aba {
  min-height: 40px;
  padding: 0 16px;
  border-radius: 10px;
  border: 1px solid rgba(180, 110, 255, 0.3);
  background: rgba(255, 255, 255, 0.05);
  color: var(--txt-dim);
  font-family: inherit;
  font-weight: 600;
  cursor: pointer;
}
.documentos-aba[aria-selected="true"] {
  color: var(--txt);
  border-color: var(--h2);
  background: rgba(52, 224, 215, 0.12);
}
.documentos-link { font-size: 13px; color: var(--h2); white-space: nowrap; }

.documentos-iframe {
  flex: 1;
  width: 100%;
  min-height: 0;
  border: 0;
  background: #fff;
}

@media (max-width: 640px) {
  .documentos-barra { flex-direction: column; align-items: stretch; }
}

.documentos-aviso { margin: 0; padding: 24px 20px; font-size: 14px; color: var(--txt-dim); }

/* Loading global: barra no topo, spinner central e spinner nos botões de ação */
.app-loading-barra {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  z-index: 99999;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s ease;
}
.app-loading-barra.visivel { opacity: 1; }
.app-loading-barra::before {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: 40%;
  background: linear-gradient(90deg, var(--h1), var(--h3), var(--h2));
  animation: app-loading-barra 1.1s ease-in-out infinite;
}

.app-loading-fundo {
  position: fixed;
  inset: 0;
  z-index: 99998;
  display: none;
  align-items: center;
  justify-content: center;
  background: rgba(8, 6, 22, 0.72);
  backdrop-filter: blur(2px);
  cursor: progress;
}
.app-loading-fundo.visivel { display: flex; }

.app-loading-caixa {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 18px 28px;
  border-radius: 14px;
  background: var(--bg-1);
  border: 1px solid rgba(180, 110, 255, 0.28);
  color: var(--txt);
  font-size: 16px;
  font-weight: 600;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
}

.app-loading-spinner,
body.app-carregando .btn-activate:disabled::after,
body.app-carregando .btn-primary:disabled::after {
  content: '';
  display: inline-block;
  width: 16px;
  height: 16px;
  margin-left: 8px;
  vertical-align: -3px;
  border: 2px solid rgba(255, 255, 255, 0.25);
  border-top-color: var(--h2);
  border-radius: 50%;
  animation: app-loading-giro 0.7s linear infinite;
}
.app-loading-caixa .app-loading-spinner { margin-left: 0; width: 20px; height: 20px; }

@keyframes app-loading-giro { to { transform: rotate(360deg); } }
@keyframes app-loading-barra {
  from { transform: translateX(-100%); }
  to   { transform: translateX(260%); }
}

@media (prefers-reduced-motion: reduce) {
  .app-loading-barra::before { animation-duration: 2.4s; }
  .app-loading-spinner,
  body.app-carregando .btn-activate:disabled::after,
  body.app-carregando .btn-primary:disabled::after { animation-duration: 1.8s; }
}

/* Visualização de Markdown (modal Storage) */
.md-view {
  font-size: 14px;
  line-height: 1.65;
  color: var(--txt);
  word-wrap: break-word;
}

.md-view > *:first-child {
  margin-top: 0;
}

.md-view > *:last-child {
  margin-bottom: 0;
}

.md-view h1 {
  margin: 1.4em 0 0.6em;
  font-size: 1.65rem;
  font-weight: 700;
  color: var(--h1);
  text-shadow: 0 0 24px rgba(255, 79, 163, 0.25);
}

.md-view h2 {
  margin: 1.25em 0 0.5em;
  font-size: 1.3rem;
  font-weight: 600;
  color: var(--h2);
}

.md-view h3 {
  margin: 1em 0 0.45em;
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--h3);
}

.md-view h4,
.md-view h5,
.md-view h6 {
  margin: 0.9em 0 0.4em;
  font-size: 1rem;
  color: var(--txt);
}

.md-view p {
  margin: 0 0 0.85em;
}

.md-view a {
  color: var(--link);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.md-view a:hover {
  color: var(--link-hov);
}

.md-view strong {
  font-weight: 600;
  color: #fff;
}

.md-view em {
  color: var(--txt-dim);
}

.md-view ul,
.md-view ol {
  margin: 0 0 0.85em;
  padding-left: 1.5em;
}

.md-view li {
  margin: 0.25em 0;
}

.md-view li > ul,
.md-view li > ol {
  margin-bottom: 0.25em;
}

.md-view blockquote {
  margin: 0 0 1em;
  padding: 10px 14px;
  border-left: 3px solid var(--h2);
  background: rgba(52, 224, 215, 0.06);
  border-radius: 0 10px 10px 0;
  color: var(--txt-dim);
}

.md-view blockquote p:last-child {
  margin-bottom: 0;
}

.md-view hr {
  border: none;
  height: 1px;
  margin: 1.5em 0;
  background: linear-gradient(90deg, transparent, rgba(180, 110, 255, 0.35), transparent);
}

.md-view code {
  font-family: 'JetBrains Mono', Consolas, monospace;
  font-size: 0.88em;
  padding: 2px 6px;
  border-radius: 6px;
  background: var(--inline-bg);
  color: var(--inline-txt);
}

.md-view pre {
  margin: 0 0 1em;
  padding: 14px 16px;
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.35);
  border: 1px solid rgba(180, 110, 255, 0.2);
  overflow-x: auto;
}

.md-view pre code {
  padding: 0;
  background: none;
  color: var(--txt);
  font-size: 12.5px;
  line-height: 1.5;
}

.md-view table {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 1em;
  font-size: 13px;
}

.md-view th,
.md-view td {
  padding: 8px 12px;
  border: 1px solid rgba(180, 110, 255, 0.2);
  text-align: left;
}

.md-view th {
  background: rgba(52, 224, 215, 0.08);
  color: var(--h2);
  font-weight: 600;
}

.md-view tr:nth-child(even) td {
  background: rgba(255, 255, 255, 0.02);
}

.md-view img {
  max-width: 100%;
  height: auto;
  border-radius: 8px;
}

.modal.modal-md-view {
  max-width: 820px;
}

.modal.modal-md-edit {
  max-width: 900px;
}

.md-edit-body {
  width: 100%;
  min-height: 360px;
  font-family: 'JetBrains Mono', Consolas, monospace;
  font-size: 13px;
  line-height: 1.5;
  tab-size: 2;
}

.md-view-wrap {
  max-height: min(70vh, 640px);
  overflow: auto;
  padding: 4px 2px;
  border-radius: 10px;
  border: 1px solid rgba(180, 110, 255, 0.12);
  background: rgba(0, 0, 0, 0.15);
}

.md-view-wrap .md-view {
  padding: 16px 18px;
}

.btn-view {
  background: rgba(90, 184, 255, 0.12);
  color: var(--link);
  border: 1px solid rgba(90, 184, 255, 0.35);
}

.btn-view:hover {
  background: rgba(90, 184, 255, 0.22);
}

.st-actions .btn {
  margin-left: 4px;
}

.st-actions .btn:first-child {
  margin-left: 0;
}

/* ============================================================================
   menu.css — barra de menu superior (links entre as páginas do sistema)
   Carregado DEPOIS de mobile.css: a barra fica acima da navbar do dashboard.
   ========================================================================== */

:root {
  --menu-h: 44px;
}

/* O corpo abre espaço para a barra fixa; a navbar desce o mesmo tanto */
body { padding-top: calc(var(--menu-h) + var(--sat, 0px)); }

.menu-bar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 102;
  height: calc(var(--menu-h) + var(--sat, 0px));
  padding-top: var(--sat, 0px);
  padding-left: max(24px, var(--sal, 0px));
  padding-right: max(24px, var(--sar, 0px));
  display: flex;
  align-items: center;
  background: rgba(7, 5, 18, 0.98);
  border-bottom: 1px solid rgba(180, 110, 255, 0.2);
  backdrop-filter: blur(8px);
}

.menu-bar nav { flex: 1; min-width: 0; }

.menu-bar-lista {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  overflow-x: auto;
  white-space: nowrap;
  scrollbar-width: none;
}
.menu-bar-lista::-webkit-scrollbar { display: none; }

.menu-link {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  padding: 0 14px;
  border-radius: 8px;
  color: var(--txt-dim);
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
  border: 1px solid transparent;
  transition: background 0.15s, color 0.15s;
}
.menu-link:hover,
.menu-link:focus-visible {
  background: rgba(255, 255, 255, 0.07);
  color: var(--txt);
  outline: none;
}
.menu-link[aria-current="page"] {
  color: var(--txt);
  background: rgba(180, 110, 255, 0.16);
  border-color: rgba(180, 110, 255, 0.35);
}

.menu-bar-separador {
  width: 1px;
  height: 18px;
  margin: 0 6px;
  background: rgba(180, 110, 255, 0.25);
  flex-shrink: 0;
}

/* Navbar do dashboard e avisos do PWA passam a ficar abaixo da barra de menu */
.navbar {
  top: calc(var(--menu-h) + var(--sat, 0px));
  padding-top: 0;
  height: var(--navbar-h, 56px);
}
.pwa-banners.below-navbar {
  top: calc(var(--navbar-h, 56px) + var(--menu-h) + var(--sat, 0px));
}

/* Páginas de conteúdo (Finanças Pessoais, Gestão Financeira, Novos Negócios) */
.pagina-conteudo {
  max-width: 1200px;
  margin: 0 auto;
  padding: 32px 24px 56px;
}
.pagina-conteudo h1 {
  margin: 0 0 12px;
  font-size: 26px;
  font-weight: 700;
  background: linear-gradient(90deg, var(--h1), var(--h3), var(--h2));
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
.pagina-conteudo p {
  margin: 0;
  font-size: 15px;
  color: var(--txt-dim);
}

@media (max-width: 768px) {
  .menu-bar {
    padding-left: max(12px, var(--sal, 0px));
    padding-right: max(12px, var(--sar, 0px));
  }
  .pagina-conteudo { padding: 24px 12px 40px; }
}

/* Link da página atual: sem destino, então clicar nele não recarrega a página */
.menu-link[aria-current="page"] { cursor: default; }

/* ============================================================================
   mobile.css — camada celular / PWA
   Carregado POR ÚLTIMO em index.html e login.html: sobrescreve (mesma
   especificidade, ordem decide) as regras responsivas antigas do styles.css e
   do <style> do index.html.
   ========================================================================== */

:root {
  --navbar-h: 56px;
  --action-bar-h: 68px;
  --sat: env(safe-area-inset-top, 0px);
  --sab: env(safe-area-inset-bottom, 0px);
  --sal: env(safe-area-inset-left, 0px);
  --sar: env(safe-area-inset-right, 0px);
}

[hidden] { display: none !important; }

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  background: #0d0b1f; /* evita flash branco no overscroll / abertura do app */
}

body {
  min-height: 100vh;
  min-height: 100dvh;
  -webkit-tap-highlight-color: transparent;
}

/* Sem o atraso de 300 ms e sem zoom por duplo toque nos controles */
button, a, select, label, input, summary, [role="button"] {
  touch-action: manipulation;
}

/* Instalado: sem "puxar para recarregar" acidental (há botão de atualizar) */
@media (display-mode: standalone) {
  body { overscroll-behavior-y: none; }
}

/* ── Safe areas (notch, barra de gestos) ───────────────────────────────── */
.navbar {
  padding-top: var(--sat);
  padding-left: max(24px, var(--sal));
  padding-right: max(24px, var(--sar));
  height: calc(var(--navbar-h) + var(--sat));
}

.page-wrap {
  padding-top: calc(var(--navbar-h) + var(--sat) + 20px);
  padding-left: max(24px, var(--sal));
  padding-right: max(24px, var(--sar));
}

body.splash {
  min-height: 100vh;
  min-height: 100dvh;
  padding-top: calc(24px + var(--sat));
  padding-bottom: calc(24px + var(--sab));
  padding-left: max(16px, var(--sal));
  padding-right: max(16px, var(--sar));
}

/* ── Navbar: botão de atualizar ────────────────────────────────────────── */
.btn-icon {
  width: 44px;
  min-width: 44px;
  padding: 0;
  justify-content: center;
  font-size: 18px;
  line-height: 1;
}
.btn-icon.spinning { animation: spin 0.8s linear infinite; }
.btn-icon:disabled { opacity: 0.6; cursor: progress; }

.only-mobile { display: none; }

/* ── Banners (offline / atualização) — criados por src/pwa.js ──────────── */
.pwa-banners {
  position: fixed;
  top: var(--sat);
  left: 0;
  right: 0;
  z-index: 150;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px max(12px, var(--sar)) 0 max(12px, var(--sal));
  pointer-events: none;
}
.pwa-banners.below-navbar { top: calc(var(--navbar-h) + var(--sat)); }

.pwa-banner {
  pointer-events: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 14px;
  border-radius: 12px;
  font-size: 13px;
  line-height: 1.35;
  color: var(--txt);
  background: rgba(26, 22, 64, 0.97);
  border: 1px solid rgba(255, 184, 77, 0.45);
  box-shadow: var(--shadow-soft);
}
.pwa-banner--update { border-color: rgba(52, 224, 215, 0.45); }

/* Offline: empurra o conteúdo para o banner não cobrir o seletor de mês */
html.is-offline .page-wrap { margin-top: 52px; }
.pwa-banner button {
  flex-shrink: 0;
  min-height: 36px;
  padding: 6px 12px;
  border-radius: 8px;
  border: 1px solid rgba(52, 224, 215, 0.45);
  background: rgba(52, 224, 215, 0.14);
  color: var(--h2);
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

/* ── Instalar app (modal de configurações) ─────────────────────────────── */
.cfg-install {
  margin-top: 16px;
  padding: 14px;
  border-radius: 12px;
  text-align: center;
  background: rgba(52, 224, 215, 0.07);
  border: 1px solid rgba(52, 224, 215, 0.25);
}
.cfg-install .btn { min-height: 44px; justify-content: center; }
.cfg-install p {
  margin: 8px 0 0;
  font-size: 12px;
  line-height: 1.5;
  color: var(--txt-dim);
}

/* ── Feedback de toque (só em telas touch) ─────────────────────────────── */
@media (hover: none) {
  .btn-action:active,
  .btn-nova:active,
  .filter-btn:active,
  .month-nav-btn:active,
  .btn:active,
  .scope-btn:active {
    transform: scale(0.97);
    filter: brightness(1.15);
  }
}

/* ============================================================================
   Celular
   ========================================================================== */
@media (max-width: 768px) {

  .only-mobile { display: flex; }
  .hide-sm { display: none !important; }

  /* Navbar de uma linha só (antes quebrava em duas e cobria o conteúdo) */
  .navbar {
    flex-wrap: nowrap;
    gap: 8px;
    min-height: 0;
    padding-top: var(--sat);
    padding-bottom: 0;
    padding-left: max(12px, var(--sal));
    padding-right: max(12px, var(--sar));
    height: calc(var(--navbar-h) + var(--sat));
  }
  .navbar h1 { font-size: 17px; white-space: nowrap; flex-shrink: 0; }
  .header-right {
    width: auto;
    flex-wrap: nowrap;
    justify-content: flex-end;
    gap: 6px;
    margin-left: auto;
  }
  #nav-user, #month-label, #btn-logout, .btn-label { display: none; }
  #btn-config {
    background: rgba(255, 255, 255, 0.05);
    -webkit-text-fill-color: currentColor;
    color: var(--txt-dim);
    width: 44px;
    min-width: 44px;
    padding: 0;
    justify-content: center;
    font-size: 18px;
    margin-left: 0 !important;
  }
  #btn-refresh { margin-left: 0 !important; }

  /* Conteúdo: libera espaço para a barra de ações fixa embaixo */
  .page-wrap {
    padding-top: calc(var(--navbar-h) + var(--sat) + 14px);
    padding-bottom: calc(var(--action-bar-h) + var(--sab) + 20px);
    padding-left: max(12px, var(--sal));
    padding-right: max(12px, var(--sar));
  }

  /* Resumo: 2 × 2 compacto (antes virava 4 cards empilhados) */
  .summary-cards { grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 12px; }
  .summary-card { padding: 10px 12px; gap: 2px; border-radius: 12px; }
  .summary-card-icon { display: none; }
  .summary-card-label { font-size: 10px; }
  .summary-card-value { font-size: clamp(14px, 4.6vw, 18px); }
  .summary-card-sub { font-size: 10px; }

  /* Filtros: uma linha rolável por grupo, em vez de blocos empilhados */
  .filter-bar { gap: 6px; padding: 10px 12px; margin-bottom: 12px; flex-wrap: nowrap; }
  .filter-group {
    min-width: 0;
    flex-wrap: nowrap;
    overflow-x: auto;
    gap: 6px;
    padding: 2px;
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
  }
  .filter-group::-webkit-scrollbar { display: none; }
  .filter-label { width: auto; flex: 0 0 auto; margin: 0 4px 0 0; }
  .filter-btn { flex: 1 0 auto; min-height: 40px; padding: 8px 14px; }

  /* Barra de ações fixa no rodapé, ao alcance do polegar */
  .action-bar {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 90;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    margin: 0;
    padding: 10px max(12px, var(--sar)) calc(10px + var(--sab)) max(12px, var(--sal));
    background: rgba(13, 11, 31, 0.92);
    border-top: 1px solid rgba(180, 110, 255, 0.18);
    -webkit-backdrop-filter: blur(12px);
    backdrop-filter: blur(12px);
  }
  .btn-nova { min-height: 48px; padding: 10px 8px; font-size: 14px; }

  .page-wrap ~ #toast {
    left: max(12px, var(--sal));
    right: max(12px, var(--sar));
    bottom: calc(var(--action-bar-h) + var(--sab) + 12px);
  }

  /* Cards da lista: ação principal larga + secundárias lado a lado */
  .lanc-card-actions { display: flex; flex-wrap: wrap; gap: 8px; }
  .lanc-card-actions .btn-action { flex: 1 1 0; min-width: 0; min-height: 44px; order: 1; }
  .lanc-card-actions .btn-pagar,
  .lanc-card-actions .btn-receber { flex: 1 1 100%; order: 0; }
  .lanc-card-actions .btn-cancelar { order: 2; }
  .lanc-card-actions .btn-action[data-action="encerrar-fixa"] { flex: 1 1 auto; padding: 10px; }
  .lanc-card-actions .btn-excluir  { order: 3; }
  .lanc-card-actions .btn-action:disabled { display: none; } /* pago/cancelado: sem botões mortos */

  .load-error { padding: 28px 12px; }
  .load-error code { display: block; margin: 8px 0 14px; font-size: 12px; color: var(--h3); }

  /* Modais viram "bottom sheet" */
  .modal-back { align-items: flex-end; padding: 0; }
  .modal,
  .modal-wide,
  #modal-confirm .modal,
  #modal-scope .modal {
    max-width: none !important;
    width: 100%;
    max-height: 92vh;
    max-height: 92dvh;
    padding: 20px max(16px, var(--sar)) calc(16px + var(--sab)) max(16px, var(--sal));
    border-radius: 20px 20px 0 0;
    border-bottom: none;
    animation: sheet-up 0.22s ease-out;
  }
  .modal::before {
    content: '';
    display: block;
    width: 40px;
    height: 4px;
    margin: -8px auto 14px;
    border-radius: 2px;
    background: rgba(180, 110, 255, 0.35);
  }
  /* Formulários longos: Gravar/Cancelar sempre visíveis */
  .fin-modal .modal { padding-bottom: 0; }
  .fin-modal .modal-actions-pair {
    position: sticky;
    bottom: 0;
    margin-top: 14px;
    padding: 12px 0 calc(12px + var(--sab));
    background: linear-gradient(180deg, rgba(20, 17, 46, 0), var(--bg-1) 16px);
  }
  .modal-actions-pair .btn { flex: 1 1 0; }
}

@keyframes sheet-up {
  from { transform: translateY(40px); opacity: 0; }
  to   { transform: translateY(0);    opacity: 1; }
}

@media (max-width: 430px) {
  .summary-cards { grid-template-columns: 1fr 1fr; }
  .page-wrap { padding-top: calc(var(--navbar-h) + var(--sat) + 12px); }
}

@media (prefers-reduced-motion: reduce) {
  .modal, .btn-icon.spinning { animation: none !important; }
}

/* Modais de alerta/confirmação — centralizados, paleta do theme.css */
.app-modal-back {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(0, 0, 0, 0.62);
  animation: app-modal-fade-in 0.18s ease-out;
}

.app-modal {
  width: 100%;
  max-width: 420px;
  padding: 22px 24px;
  border-radius: 14px;
  background: var(--bg-1);
  border: 1px solid rgba(180, 110, 255, 0.28);
  box-shadow: var(--shadow-card);
  animation: app-modal-scale-in 0.2s ease-out;
}

.app-modal-title {
  margin: 0 0 12px;
  font-size: 17px;
  font-weight: 600;
  color: var(--h2);
}

.app-modal-body {
  margin: 0 0 20px;
  font-size: 14px;
  line-height: 1.55;
  color: var(--txt);
}

.app-modal-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: flex-end;
}

.app-modal-actions-confirm {
  justify-content: center;
}

/* Verde claro: use .btn-activate em theme.css */

.btn-modal-cancel {
  background: rgba(255, 91, 110, 0.18);
  color: #ffc4cb;
  border: 1px solid rgba(255, 91, 110, 0.48);
  box-shadow: 0 2px 12px rgba(255, 91, 110, 0.1);
}
.btn-modal-cancel:hover {
  background: rgba(255, 91, 110, 0.28);
  color: #ffe0e4;
}

@keyframes app-modal-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes app-modal-scale-in {
  from {
    opacity: 0;
    transform: scale(0.94) translateY(6px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

:root {
  --txt: #e6e3ff;
  --txt-dim: #a09bc7;
  --h1: #ff4fa3;
  --h2: #34e0d7;
  --h3: #ffb84d;
}

/* Top Navbar */
.navbar {
  width: 100%;
  background: linear-gradient(180deg, rgba(10, 8, 24, 0.97), rgba(17, 9, 42, 0.95));
  color: var(--txt);
  padding: 0 24px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-bottom: 1px solid rgba(180, 110, 255, 0.2);
  backdrop-filter: blur(8px);
  z-index: 100;
}

.navbar h1 {
  font-size: 20px;
  font-weight: 600;
  letter-spacing: 0.5px;
  background: linear-gradient(90deg, var(--h1), var(--h3), var(--h2));
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.navbar .nav-links {
  display: flex;
  gap: 18px;
}

.navbar .nav-links a {
  color: var(--txt-dim);
  text-decoration: none;
  font-size: 14px;
  padding: 6px 14px;
  border-radius: 6px;
  transition: 0.2s;
  border: 1px solid transparent;
}

.navbar .nav-links a:hover,
.navbar .nav-links a.active {
  background: rgba(255, 255, 255, 0.08);
  color: var(--txt);
  border-color: rgba(180, 110, 255, 0.2);
}

.navbar .nav-links a.nav-card {
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  gap: 6px;
  flex-wrap: nowrap;
  white-space: nowrap;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(180, 110, 255, 0.25);
  border-radius: 8px;
  padding: 6px 12px;
  font-size: 13px;
  font-weight: 600;
  color: var(--txt-dim);
}

.navbar .nav-links a.nav-card:hover {
  background: rgba(255, 255, 255, 0.12);
  color: var(--txt);
  border-color: rgba(180, 110, 255, 0.45);
}

.navbar .nav-card-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  line-height: 1;
  flex-shrink: 0;
}

.navbar .nav-card-title {
  display: inline;
  line-height: 1;
  white-space: nowrap;
}

.navbar .btn-logout {
  background: rgba(255, 91, 110, 0.1);
  color: #ff8a97;
  border: 1px solid rgba(255, 91, 110, 0.3);
  padding: 6px 14px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 14px;
  transition: 0.2s;
  font-family: inherit;
}

.navbar .btn-logout:hover {
  background: rgba(255, 91, 110, 0.2);
}

/* ============================================================================
   novos-negocios.css — cards das ideias e modal de detalhes
   ========================================================================== */

.ideias-cabecalho { margin-bottom: 20px; }

.ideias-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 16px;
}

.ideia-card {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 18px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(180, 110, 255, 0.28);
  box-shadow: var(--shadow-card, none);
}

.ideia-topo { display: flex; align-items: center; justify-content: space-between; gap: 8px; }

.ideia-status {
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  border: 1px solid;
}
.ideia-status[data-estado="analisar"] {
  color: #ffd28a;
  border-color: rgba(255, 184, 77, 0.6);
  background: rgba(255, 184, 77, 0.12);
}
.ideia-status[data-estado="analisado"] {
  color: #7dff9f;
  border-color: rgba(93, 212, 93, 0.6);
  background: rgba(93, 212, 93, 0.12);
}

.ideia-analise {
  margin: 0;
  padding: 12px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.04);
  font-family: inherit;
  font-size: 13px;
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
  color: var(--txt-dim);
}

.ideia-codigo {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--h2);
}

.ideia-nome {
  margin: 0;
  font-size: 19px;
  font-weight: 700;
  color: var(--txt);
}

.ideia-dados { display: grid; gap: 10px; margin: 6px 0; }
.ideia-dado { display: grid; gap: 2px; }
.ideia-dado-rotulo {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: var(--txt-soft);
}
.ideia-dado-valor { margin: 0; font-size: 14px; color: var(--txt); }

.ideia-detalhes {
  margin-top: auto;
  min-height: 44px;
  border-radius: 12px;
  border: 1px solid rgba(52, 224, 215, 0.4);
  background: rgba(52, 224, 215, 0.1);
  color: var(--h2);
  font-family: inherit;
  font-weight: 600;
  cursor: pointer;
}
.ideia-detalhes:hover,
.ideia-detalhes:focus-visible {
  background: rgba(52, 224, 215, 0.2);
  outline: none;
}

/* Modal */
.ideia-modal {
  /* o reset global zera a margem; sem "auto" o <dialog> gruda no canto */
  margin: auto;
  width: min(720px, calc(100vw - 24px));
  max-height: calc(100dvh - 40px);
  padding: 0;
  border: 1px solid rgba(180, 110, 255, 0.35);
  border-radius: 16px;
  background: var(--bg-1, #120f2b);
  color: var(--txt);
}
.ideia-modal::backdrop { background: rgba(8, 6, 22, 0.75); backdrop-filter: blur(2px); }

.ideia-modal-topo {
  position: sticky;
  top: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 20px;
  background: var(--bg-1, #120f2b);
  border-bottom: 1px solid rgba(180, 110, 255, 0.2);
}
.ideia-modal-topo h2 { margin: 0; font-size: 18px; }

.ideia-modal-fechar {
  min-width: 44px;
  min-height: 44px;
  border-radius: 12px;
  border: 1px solid rgba(180, 110, 255, 0.25);
  background: rgba(255, 255, 255, 0.05);
  color: var(--txt);
  font-size: 20px;
  cursor: pointer;
}

.ideia-modal-corpo { padding: 8px 20px 20px; }
.ideia-secao h3 { margin: 18px 0 8px; font-size: 14px; color: var(--h2); }
.ideia-secao p { margin: 0 0 8px; font-size: 14px; line-height: 1.55; color: var(--txt-dim); }
.ideia-lista { margin: 0; padding-left: 18px; font-size: 14px; line-height: 1.55; color: var(--txt-dim); }
.ideia-aviso { margin: 18px 0 0; font-size: 12px; color: var(--txt-soft); }

.ideia-tabela { width: 100%; border-collapse: collapse; font-size: 13px; }
.ideia-tabela th,
.ideia-tabela td {
  padding: 8px;
  text-align: left;
  border-bottom: 1px solid rgba(180, 110, 255, 0.15);
}
.ideia-tabela th { font-size: 11px; text-transform: uppercase; color: var(--txt-soft); }

@media (max-width: 640px) {
  .ideias-cards { grid-template-columns: 1fr; }
  .ideia-tabela { display: block; overflow-x: auto; white-space: nowrap; }
}

/* Ações do card e selo clicável */
.ideia-acoes { display: grid; gap: 8px; margin-top: auto; }
.ideia-acoes .ideia-detalhes { margin-top: 0; }
.ideia-status--clicavel { cursor: pointer; }
.ideia-status--clicavel:hover,
.ideia-status--clicavel:focus-visible { filter: brightness(1.25); outline: none; }

/* Modal de regras de análise */
.parametros-ideia { margin: 12px 0 0; font-size: 14px; font-weight: 700; color: var(--h2); }
.parametros-formulario {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin: 12px 0;
}
.parametros-largo { grid-column: 1 / -1; }
.parametros-formulario textarea {
  width: 100%;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid rgba(180, 110, 255, 0.3);
  background: rgba(255, 255, 255, 0.05);
  color: var(--txt);
  font-family: inherit;
  font-size: 13px;
  line-height: 1.5;
  resize: vertical;
}
.parametros-formulario textarea:focus { border-color: var(--h2); outline: none; }
.parametros-formulario textarea[readonly] { color: var(--txt-dim); }
.parametros-mensagem { grid-column: 1 / -1; margin: 0; min-height: 18px; font-size: 13px; color: var(--txt-dim); }
.parametros-mensagem[data-erro="sim"] { color: var(--warn-red, #ff5b6e); }
.parametros-acoes { display: flex; justify-content: space-between; gap: 10px; }
.parametros-acoes .ideia-detalhes { flex: 1; margin-top: 0; }

@media (max-width: 640px) {
  .parametros-formulario { grid-template-columns: 1fr; }
}

.parametros-formulario .calculos-campo { display: grid; gap: 4px; font-size: 12px; color: var(--txt-soft); }
.parametros-formulario input[type="text"] {
  min-height: 44px;
  padding: 8px 12px;
  border-radius: 10px;
  border: 1px solid rgba(180, 110, 255, 0.3);
  background: rgba(255, 255, 255, 0.05);
  color: var(--txt);
  font-family: inherit;
  font-size: 15px;
}
.parametros-formulario input[type="text"]:focus { border-color: var(--h2); outline: none; }

:root {
  --bg-0: #0d0b1f;
  --bg-1: #14112e;
  --bg-2: #1a1640;
  --bg-3: #221c52;
  --txt: #e6e3ff;
  --txt-dim: #a09bc7;
  --txt-soft: #7e7aa3;
  --h1: #ff4fa3;
  --h2: #34e0d7;
  --h3: #ffb84d;
  --link: #5ab8ff;
  --link-hov: #a3d6ff;
  --warn-red: #ff5b6e;
  --warn-green: #5dd45d;
  --shadow-soft: 0 8px 24px rgba(0, 0, 0, 0.45);
  --shadow-card: 0 12px 36px rgba(0, 0, 0, 0.55);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: radial-gradient(ellipse at top left, #1c1240 0%, #0d0b1f 55%) fixed,
    radial-gradient(ellipse at bottom right, #261540 0%, transparent 60%) fixed;
  color: var(--txt);
  min-height: 100vh;
}

.cursor-pointer { cursor: pointer; }

/* Top Navbar */
.navbar {
  background: linear-gradient(180deg, rgba(10, 8, 24, 0.97), rgba(17, 9, 42, 0.95));
  color: var(--txt);
  padding: 0 24px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid rgba(180, 110, 255, 0.2);
  backdrop-filter: blur(8px);
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
}

.navbar h1 {
  font-size: 20px;
  font-weight: 600;
  letter-spacing: 0.5px;
  background: linear-gradient(90deg, var(--h1), var(--h3), var(--h2));
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.navbar .nav-links {
  display: flex;
  gap: 18px;
}

.navbar .nav-links a {
  color: var(--txt-dim);
  text-decoration: none;
  font-size: 14px;
  padding: 6px 14px;
  border-radius: 6px;
  transition: 0.2s;
}

.navbar .nav-links a:hover,
.navbar .nav-links a.active {
  background: rgba(255, 255, 255, 0.08);
  color: var(--txt);
}

/* Layout */
.app-container {
  display: flex;
  margin-top: 56px;
  min-height: calc(100vh - 56px);
}

/* Sidebar */
.sidebar {
  width: 280px;
  min-width: 280px;
  background: rgba(14, 11, 30, 0.85);
  border-right: 1px solid rgba(180, 110, 255, 0.15);
  padding: 16px 0;
  overflow-y: auto;
  height: calc(100vh - 56px);
  position: fixed;
  top: 56px;
}

.sidebar .menu-group { margin-bottom: 8px; }

.sidebar .menu-group-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  color: var(--txt-soft);
  padding: 12px 20px 6px;
  font-weight: 700;
}

.sidebar .menu-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 20px;
  cursor: pointer;
  transition: 0.15s;
  font-size: 14px;
  color: var(--txt-dim);
  border-left: 3px solid transparent;
}

.sidebar .menu-item:hover {
  background: rgba(255, 255, 255, 0.05);
  color: var(--txt);
}

.sidebar .menu-item.active {
  background: rgba(255, 79, 163, 0.1);
  color: var(--h1);
  border-left-color: var(--h1);
  font-weight: 600;
}

.sidebar .menu-item .method-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 3px;
  min-width: 46px;
  text-align: center;
  color: #fff;
  flex-shrink: 0;
}

.method-GET  { background: rgba(93, 212, 93, 0.7); }
.method-POST { background: rgba(90, 184, 255, 0.7); }
.method-PUT  { background: rgba(255, 184, 77, 0.7); }
.method-DELETE { background: rgba(255, 91, 110, 0.7); }

/* Main Content */
.main-content {
  flex: 1;
  margin-left: 280px;
  padding: 28px 32px;
}

/* Welcome */
.welcome {
  text-align: center;
  padding: 60px 20px;
}

.welcome h2 {
  font-size: 28px;
  color: var(--h2);
  margin-bottom: 12px;
}

.welcome p {
  color: var(--txt-dim);
  font-size: 16px;
  max-width: 500px;
  margin: 0 auto;
}

.welcome .stats {
  display: flex;
  gap: 24px;
  justify-content: center;
  margin-top: 32px;
}

.welcome .stat-card {
  background: rgba(20, 17, 46, 0.65);
  border: 1px solid rgba(180, 110, 255, 0.15);
  border-radius: 12px;
  padding: 20px 28px;
  box-shadow: var(--shadow-soft);
  text-align: center;
}

.welcome .stat-card .num {
  font-size: 32px;
  font-weight: 700;
  color: var(--h2);
}

.welcome .stat-card .label {
  font-size: 13px;
  color: var(--txt-soft);
  margin-top: 4px;
}

/* Endpoint Panel */
.endpoint-panel { display: none; }
.endpoint-panel.active { display: block; }

.endpoint-panel .panel-header {
  background: rgba(20, 17, 46, 0.65);
  border: 1px solid rgba(180, 110, 255, 0.15);
  border-radius: 12px;
  padding: 24px 28px;
  box-shadow: var(--shadow-soft);
  margin-bottom: 20px;
}

.endpoint-panel .panel-header h2 {
  font-size: 22px;
  margin-bottom: 6px;
  color: var(--h3);
}

.endpoint-panel .panel-header .route-info {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 10px;
}

.endpoint-panel .panel-header .route-info .method {
  font-size: 13px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 4px;
  color: #fff;
}

.endpoint-panel .panel-header .route-info .path {
  font-family: 'Courier New', monospace;
  font-size: 14px;
  color: var(--txt-dim);
  background: rgba(255, 255, 255, 0.05);
  padding: 4px 10px;
  border-radius: 4px;
  border: 1px solid rgba(180, 110, 255, 0.15);
}

/* Form */
.form-section {
  background: rgba(20, 17, 46, 0.65);
  border: 1px solid rgba(180, 110, 255, 0.15);
  border-radius: 12px;
  padding: 24px 28px;
  box-shadow: var(--shadow-soft);
  margin-bottom: 20px;
}

.form-section h3 {
  font-size: 16px;
  margin-bottom: 16px;
  color: var(--txt-soft);
}

.form-row {
  display: flex;
  gap: 16px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}

.form-group {
  flex: 1;
  min-width: 200px;
}

.form-group label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--txt-soft);
  margin-bottom: 4px;
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 9px 12px;
  border: 1px solid rgba(180, 110, 255, 0.25);
  border-radius: 6px;
  font-size: 14px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--txt);
  transition: 0.2s;
  font-family: inherit;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--h2);
}

.form-group textarea {
  resize: vertical;
  min-height: 80px;
}

.btn {
  padding: 10px 24px;
  border: none;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: 0.2s;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: inherit;
}

.btn-primary {
  background: linear-gradient(90deg, var(--h1), var(--h3));
  color: #fff;
  box-shadow: 0 4px 16px rgba(255, 79, 163, 0.3);
}

.btn-primary:hover { box-shadow: 0 6px 22px rgba(255, 79, 163, 0.45); }

.btn-secondary {
  background: rgba(255, 255, 255, 0.06);
  color: var(--txt-dim);
  border: 1px solid rgba(180, 110, 255, 0.22);
}

.btn-secondary:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--txt);
}

/* Response Area */
.response-section {
  background: rgba(20, 17, 46, 0.65);
  border: 1px solid rgba(180, 110, 255, 0.15);
  border-radius: 12px;
  padding: 24px 28px;
  box-shadow: var(--shadow-soft);
}

.response-section h3 {
  font-size: 16px;
  margin-bottom: 12px;
  color: var(--txt-soft);
  display: flex;
  align-items: center;
  gap: 10px;
}

.response-section .status-badge {
  font-size: 12px;
  padding: 2px 8px;
  border-radius: 10px;
  color: #fff;
}

.status-success { background: rgba(93, 212, 93, 0.6); }
.status-error   { background: rgba(255, 91, 110, 0.6); }
.status-pending { background: rgba(180, 110, 255, 0.4); }

.response-body {
  background: #1e1e1e;
  color: #d4d4d4;
  padding: 16px;
  border-radius: 8px;
  font-family: 'Courier New', monospace;
  font-size: 13px;
  white-space: pre-wrap;
  max-height: 500px;
  overflow-y: auto;
  line-height: 1.5;
  border: 1px solid rgba(180, 110, 255, 0.15);
}

.response-body .json-key    { color: #9cdcfe; }
.response-body .json-string { color: #ce9178; }
.response-body .json-number { color: #b5cea8; }
.response-body .json-bool   { color: #569cd6; }
.response-body .json-null   { color: #569cd6; }

/* Loading */
.loading {
  text-align: center;
  padding: 20px;
  color: var(--txt-soft);
}

.spinner {
  display: inline-block;
  width: 24px;
  height: 24px;
  border: 3px solid rgba(180, 110, 255, 0.2);
  border-top-color: var(--h1);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* Disabled inputs */
input.disabled,
input:disabled {
  opacity: 0.55;
  background: rgba(255, 255, 255, 0.03);
  color: var(--txt-soft);
  cursor: not-allowed;
}

/* Config Button */
#btn-config {
  background: linear-gradient(90deg, var(--h1), var(--h3), var(--h2));
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  font-weight: 600;
}

#btn-config:hover {
  opacity: 0.8;
}

/* Responsive */
@media (max-width: 768px) {
  .sidebar { width: 220px; min-width: 220px; }
  .main-content { margin-left: 220px; padding: 20px 16px; }
}

/* ── Header right (dashboard navbar) ─────────────────────────────── */
.header-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
  min-width: 0;
}

.btn-small {
  padding: 8px 12px;
  font-size: 13px;
  min-height: 40px;
}

.btn-ghost {
  background: rgba(255, 255, 255, 0.05);
  color: var(--txt-dim);
  border: 1px solid rgba(180, 110, 255, 0.22);
}

.btn-ghost:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--txt);
}

.btn-cancel-light {
  background: rgba(255, 91, 110, 0.14);
  color: #ffc4cb;
  border: 1px solid rgba(255, 91, 110, 0.4);
}

.btn-cancel-light:hover {
  background: rgba(255, 91, 110, 0.24);
  color: #ffe0e4;
}

.btn-activate {
  background: rgba(93, 212, 93, 0.18);
  color: var(--warn-green);
  border: 1px solid rgba(93, 212, 93, 0.35);
}

.btn-activate:hover {
  background: rgba(93, 212, 93, 0.28);
}

/* ── Modal (usado por index + login) ─────────────────────────────── */
.modal-back {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: rgba(0, 0, 0, 0.62);
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

.modal {
  width: 100%;
  max-width: 420px;
  max-height: calc(100vh - 32px);
  overflow-y: auto;
  padding: 22px 24px;
  border-radius: 14px;
  background: var(--bg-1);
  border: 1px solid rgba(180, 110, 255, 0.28);
  box-shadow: var(--shadow-card);
}

.modal-wide {
  max-width: 560px;
}

.modal h3 {
  margin: 0 0 14px;
  font-size: 17px;
  font-weight: 600;
  color: var(--h2);
}

.modal-actions-center {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}

.modal-actions-pair .btn {
  min-width: 120px;
  min-height: 44px;
  justify-content: center;
}

/* ── Login ───────────────────────────────────────────────────────── */
body.splash {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 24px 16px;
  overflow-x: hidden;
}

.login-box {
  width: 100%;
  max-width: 400px;
  padding: 28px 24px 24px;
  border-radius: 16px;
  background: rgba(20, 17, 46, 0.88);
  border: 1px solid rgba(180, 110, 255, 0.22);
  box-shadow: var(--shadow-card);
}

.login-tagline {
  text-align: center;
  color: var(--txt-soft);
  font-size: 14px;
  margin: 0 0 22px;
}

.login-form .field {
  margin-bottom: 14px;
}

.login-form .field label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--txt-soft);
  margin-bottom: 6px;
}

.login-form .field input {
  width: 100%;
  min-height: 48px;
  padding: 12px 14px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(180, 110, 255, 0.25);
  color: var(--txt);
  font-family: inherit;
  font-size: 16px; /* evita zoom no iOS */
  outline: none;
  box-sizing: border-box;
  transition: border-color 0.15s;
}

.login-form .field input:focus {
  border-color: var(--h2);
}

.login-form .err {
  color: var(--warn-red);
  font-size: 13px;
  min-height: 18px;
  margin: 0 0 10px;
  text-align: center;
}

.btn-auth-submit {
  width: 100%;
  min-height: 48px;
  justify-content: center;
  font-size: 15px;
  border-radius: 12px;
}

.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  max-width: calc(100vw - 32px);
  padding: 12px 20px;
  border-radius: 10px;
  background: rgba(26, 22, 64, 0.96);
  border: 1px solid rgba(52, 224, 215, 0.38);
  color: var(--txt);
  font-size: 13px;
  font-weight: 500;
  z-index: 300;
  box-shadow: var(--shadow-card);
}

/* ── Mobile list (cards) ─────────────────────────────────────────── */
.mobile-list {
  display: none;
  flex-direction: column;
  gap: 10px;
}

.lanc-card {
  background: rgba(20, 17, 46, 0.78);
  border: 1px solid rgba(180, 110, 255, 0.18);
  border-radius: 14px;
  padding: 14px;
  box-shadow: var(--shadow-soft);
}

.lanc-card.row-s0 { border-color: rgba(255, 91, 110, 0.28); }
.lanc-card.row-s1 { border-color: rgba(93, 212, 93, 0.28); }
.lanc-card.row-s3 { border-color: rgba(255, 184, 77, 0.28); }

.lanc-card-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 10px;
}

.lanc-card-desc {
  color: var(--txt);
  font-weight: 600;
  font-size: 15px;
  line-height: 1.35;
  word-break: break-word;
  min-width: 0;
}

.lanc-card-valor {
  font-family: 'JetBrains Mono', Consolas, monospace;
  font-weight: 700;
  font-size: 15px;
  color: var(--txt);
  white-space: nowrap;
  flex-shrink: 0;
}

.lanc-card-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 8px;
  align-items: center;
  margin-bottom: 12px;
  font-size: 12px;
  color: var(--txt-soft);
}

.lanc-card-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.lanc-card-actions .btn-action {
  width: 100%;
  min-height: 44px;
  padding: 10px 8px;
  font-size: 13px;
}

/* ── Mobile / phone ──────────────────────────────────────────────── */
@media (max-width: 768px) {
  html, body {
    overflow-x: hidden;
    max-width: 100vw;
  }

  .navbar {
    padding: 0 12px;
    height: auto;
    min-height: 56px;
    flex-wrap: wrap;
    gap: 6px;
    padding-top: 8px;
    padding-bottom: 8px;
  }

  .navbar h1 {
    font-size: 17px;
  }

  .header-right {
    width: 100%;
    justify-content: space-between;
  }

  #month-label {
    display: none; /* mês principal fica na barra central */
  }

  #nav-user {
    font-size: 11px;
    max-width: 42vw;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .btn-small {
    min-height: 44px;
    padding: 10px 14px;
  }

  .sidebar { width: 100%; min-width: 0; position: static; height: auto; }
  .main-content { margin-left: 0; padding: 16px 12px; }

  .table-wrap { display: none; }
  .mobile-list { display: flex; }

  .modal {
    padding: 18px 16px;
    border-radius: 16px;
  }

  .modal-wide {
    max-width: 100%;
  }
}

@media (max-width: 430px) {
  .login-box {
    padding: 24px 16px 20px;
  }

  .lanc-card-actions {
    grid-template-columns: 1fr 1fr;
  }
}

