body.visual-futurista .ideia-status[data-estado="analisado"] {
  color: #7dff9f;
  box-shadow: 0 0 10px rgba(93, 212, 93, 0.45);
}
body.visual-futurista .ideia-analise { color: var(--cor-texto-suave); }
body.visual-futurista .ideia-nome {
