  email TEXT,
  telefone TEXT,
  ativo SMALLINT NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ── cli_loja (N:N) ───────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.cli_loja (
