}

@inject()
export class BenchmarkService {
  private currentBenchmarkId: string | null = null
  private currentStatus: BenchmarkStatus = 'idle'
  private currentStages: BenchmarkStageDescriptor[] = []
  private telemetry: BenchmarkTelemetrySampler | null = null

  constructor(private dockerService: DockerService) {}

  /**
   * Build the ordered stage plan for a run so the live UI can render a rail of
   * pending/active/complete nodes. Mirrors exactly the stages `_runBenchmark`
   * emits for the given type.
   */
  private _buildStageList(type: BenchmarkType, includeAI: boolean): BenchmarkStageDescriptor[] {
    const stages: BenchmarkStatus[] = ['detecting_hardware']
    if (type === 'full' || type === 'system') {
      stages.push('running_cpu', 'running_memory', 'running_disk_read', 'running_disk_write')
    }
    if (includeAI && (type === 'full' || type === 'ai')) {
      stages.push('running_ai')
    }
    stages.push('calculating_score')
    return stages.map((status) => ({ status, label: this._getStageLabel(status) }))
  }

  /**
   * Run a full benchmark suite
   */
  async runFullBenchmark(): Promise<BenchmarkResult> {
    return this._runBenchmark('full', true)
  }

  /**
   * Run system benchmarks only (CPU, memory, disk)
   */
  async runSystemBenchmarks(): Promise<BenchmarkResult> {
    return this._runBenchmark('system', false)
  }

  /**
   * Run AI benchmark only
   */
  async runAIBenchmark(): Promise<BenchmarkResult> {
    return this._runBenchmark('ai', true)
  }

  /**
   * Get the latest benchmark result
   */
  async getLatestResult(): Promise<BenchmarkResult | null> {
    return await BenchmarkResult.query().orderBy('created_at', 'desc').first()
  }

  /**
   * Get all benchmark results
   */
  async getAllResults(): Promise<BenchmarkResult[]> {
    return await BenchmarkResult.query().orderBy('created_at', 'desc')
  }

  /**
   * Get a specific benchmark result by ID
   */
  async getResultById(benchmarkId: string): Promise<BenchmarkResult | null> {
    return await BenchmarkResult.findBy('benchmark_id', benchmarkId)
  }

  /**
   * Whether to show the dashboard "re-run under Score v2" banner. Shown to users
   * who have a v1 leaderboard submission but no Score v2 result yet, and who
   * haven't dismissed it. Self-clears two ways: dismiss sets the KV flag, and any
   * result carrying a nomad_score_v2 (i.e. a v2 run happened) flips (b) false.
   */
  async shouldShowRerunBanner(): Promise<boolean> {
    const dismissed = await KVStore.getValue('benchmark.rerunBannerDismissed')
    if (dismissed === true) return false

    const hasV2Run = await BenchmarkResult.query().whereNotNull('nomad_score_v2').first()
    if (hasV2Run) return false

    const hasSubmittedV1 = await BenchmarkResult.query()
      .where('submitted_to_repository', true)
      .first()
    return hasSubmittedV1 !== null
  }

  /**
   * Submit benchmark results to central repository
   */
  async submitToRepository(benchmarkId?: string, anonymous?: boolean): Promise<RepositorySubmitResponse> {
    const result = benchmarkId
      ? await this.getResultById(benchmarkId)
      : await this.getLatestResult()

    if (!result) {
      throw new Error('No benchmark result found to submit')
    }

    // Only allow full benchmarks with AI data to be submitted to repository
    if (result.benchmark_type !== 'full') {
      throw new Error('Only full benchmarks can be shared with the community. Run a Full Benchmark to share your results.')
    }

    if (!result.ai_tokens_per_second || result.ai_tokens_per_second <= 0) {
      throw new Error('Benchmark must include AI performance data. Ensure AI Assistant is installed and run a Full Benchmark.')
    }

    if (result.submitted_to_repository) {
      throw new Error('Benchmark result has already been submitted')
    }

    // Remote inference cannot be attributed to this machine.
    //
    // DockerService.getServiceURL() resolves ai.remoteOllamaUrl ahead of the
    // local container, so when a remote host is configured the AI channel
    // measures THAT machine while every other channel measures this one. The
    // submission would report someone else's tok/s under this hardware, and AI
    // carries 0.30 of an uncapped v2 score, so the distortion is large.
    //
    // Blocks submission only — running the benchmark locally is still useful to
    // the operator, it just isn't a result about this box.
    // A "remote" host that points back at this same machine is not remote. The
    // AI ran on the hardware being submitted, so blocking it is a false
    // positive — see isSelfHostedOllamaUrl for which forms qualify and why a
    // LAN address deliberately does not.
    const remoteOllamaUrl = await KVStore.getValue('ai.remoteOllamaUrl')
    if (remoteOllamaUrl && isSelfHostedOllamaUrl(remoteOllamaUrl)) {
      logger.info(
        `[BenchmarkService] ai.remoteOllamaUrl (${remoteOllamaUrl}) points at this machine; treating the AI result as local for submission purposes`
      )
    } else if (remoteOllamaUrl) {
      throw new Error(
        // Name the setting and where it lives. The previous wording told the
        // user to install the AI Assistant, but configuring a remote host
        // already marks it installed — so it sent them looking for something
        // they believe they have, and never mentioned the one thing that fixes
        // it.
        'This NOMAD is set to use a remote AI host, so the AI portion of this benchmark measured that machine, not this one. ' +
          'Leaderboard results have to be measured entirely on the hardware being submitted. ' +
          'To share a result, clear the remote host under Settings → Models so AI runs locally, then run a Full Benchmark.'
      )
    }

    // Build the v2 payload (raw channels; server recomputes the score). Throws a
    // user-facing error if the row predates v2 and lacks the raw channels.
    const submission = this._buildV2Submission(result, anonymous ?? false)

    try {
      // Generate HMAC signature for submission verification
      const timestamp = Date.now().toString()
      const payload = timestamp + JSON.stringify(submission)
      const signature = createHmac('sha256', BENCHMARK_HMAC_SECRET)
        .update(payload)
        .digest('hex')

      const response = await axios.post(
        'https://benchmark.projectnomad.us/api/v1/submit',
        submission,
        {
          timeout: 30000,
          headers: {
            'X-NOMAD-Timestamp': timestamp,
            'X-NOMAD-Signature': signature,
          },
        }
      )

      if (response.data.success) {
        result.submitted_to_repository = true
        result.submitted_at = DateTime.now()
        result.repository_id = response.data.repository_id
        await result.save()

        await BenchmarkSetting.setValue('last_benchmark_run', new Date().toISOString())
      }

      return response.data as RepositorySubmitResponse
    } catch (error: any) {
      const detail = error.response?.data?.error || error.message || 'Unknown error'
      const statusCode = error.response?.status
      logger.error(`Failed to submit benchmark to repository: ${detail} (Status: ${statusCode})`)

      // Create an error with the status code and raw detail attached for proper
      // handling upstream (the controller surfaces `detail` as the user-facing reason).
      const err: any = new Error(`Failed to submit benchmark: ${detail}`)
      err.statusCode = statusCode
      err.detail = detail
      throw err
    }
  }

  /**
   * Build the NOMAD Score v2 submission payload from a stored result, validating
   * that every required raw channel + companion + provenance field is present.
   *
   * A row produced before this benchmark_version (or an interrupted run) won't
   * carry the v2 raws — rather than send a payload the leaderboard will reject
   * with a terse validator error, we throw a clear "re-run" message here.
   *
   * ai_time_to_first_token is stored in milliseconds but the leaderboard's v2 API
   * treats it as SECONDS, so it is divided by 1000 here.
   */
  private _buildV2Submission(result: BenchmarkResult, anonymous: boolean): RepositorySubmissionV2 {
    const reRun = 'Re-run a Full Benchmark to share your results.'

    // Required raw channels — all must be present and > 0.
    const requiredRaws: Array<[string, number | null]> = [
      ['CPU single-thread', result.cpu_events_single],
      ['CPU multi-thread', result.cpu_events_multi],
      ['memory', result.memory_ops_per_sec],
      ['disk read', result.disk_read_mb_per_sec],
      ['disk write', result.disk_write_mb_per_sec],
    ]
    for (const [label, value] of requiredRaws) {
      if (value == null || !(value > 0)) {
        throw new Error(`This benchmark is missing the ${label} raw measurement needed for the v2 leaderboard. ${reRun}`)
      }
    }

    if (result.ai_time_to_first_token == null || !(result.ai_time_to_first_token > 0)) {
      throw new Error(`This benchmark is missing AI time-to-first-token data. ${reRun}`)
    }
    if (
      result.cpu_benchmark_threads == null ||
      result.memory_threads == null ||
      result.cpu_total_events == null ||
      result.cpu_total_time == null
    ) {
      throw new Error(`This benchmark is missing CPU test parameters needed for the v2 leaderboard. ${reRun}`)
    }
    if (!result.sysbench_digest || !result.ollama_version) {
      throw new Error(`This benchmark is missing harness provenance (sysbench/Ollama version). ${reRun}`)
    }

    const submission: RepositorySubmissionV2 = {
      cpu_model: result.cpu_model,
      cpu_cores: result.cpu_cores,
      cpu_threads: result.cpu_threads,
      ram_gb: Math.round(result.ram_bytes / (1024 * 1024 * 1024)),
      disk_type: result.disk_type,
      gpu_model: result.gpu_model,
      ai_tokens_per_second: result.ai_tokens_per_second!,
      cpu_events_single: result.cpu_events_single!,
      cpu_events_multi: result.cpu_events_multi!,
      memory_ops_per_sec: result.memory_ops_per_sec!,
      disk_read_mb_per_sec: result.disk_read_mb_per_sec!,
      disk_write_mb_per_sec: result.disk_write_mb_per_sec!,
      cpu_benchmark_threads: result.cpu_benchmark_threads,
      memory_threads: result.memory_threads,
      // Stored in ms; the v2 API expects seconds.
      ai_time_to_first_token: result.ai_time_to_first_token / 1000,
      cpu_total_events: result.cpu_total_events,
      cpu_total_time: result.cpu_total_time,
      ollama_version: result.ollama_version,
      sysbench_digest: result.sysbench_digest,
      nomad_version: SystemService.getAppVersion(),
      benchmark_version: BENCHMARK_VERSION,
    }

    // Optional environment metadata — only send fields we actually have.
    if (result.run_environment) submission.run_environment = result.run_environment
    if (result.storage_path_type) submission.storage_path_type = result.storage_path_type
    if (result.gpu_compute_detected != null) submission.gpu_compute_detected = result.gpu_compute_detected

    // Platform metadata. Optional rather than required so results recorded
    // before this shipped remain submittable.
    if (result.cpu_architecture) submission.cpu_architecture = result.cpu_architecture
    if (result.os_name) submission.os_name = result.os_name
    if (result.os_version) submission.os_version = result.os_version

    // Builder tag: omit entirely when anonymous or unset (validator rejects null).
    if (!anonymous && result.builder_tag) submission.builder_tag = result.builder_tag

    return submission
  }

  /**
   * Get comparison stats from central repository
   */
  async getComparisonStats(): Promise<RepositoryStats | null> {
    try {
      const response = await axios.get('https://benchmark.projectnomad.us/api/v1/stats', {
        timeout: 10000,
      })
      return response.data as RepositoryStats
    } catch (error: any) {
      logger.warn(`Failed to fetch comparison stats: ${error.message}`)
      return null
    }
  }

  /**
   * Get current benchmark status
   */
  getStatus(): { status: BenchmarkStatus; benchmarkId: string | null } {
    return {
      status: this.currentStatus,
      benchmarkId: this.currentBenchmarkId,
    }
  }

  /**
   * Detect system hardware information
   */
  async getHardwareInfo(): Promise<HardwareInfo> {
    this._updateStatus('detecting_hardware', 'Detecting system hardware...')

    try {
      const [cpu, mem, diskLayout, graphics] = await Promise.all([
        si.cpu(),
        si.mem(),
        si.diskLayout(),
        si.graphics(),
      ])

      // Determine disk type from primary disk
      let diskType: DiskType = 'unknown'
      if (diskLayout.length > 0) {
        const primaryDisk = diskLayout[0]
        if (primaryDisk.type?.toLowerCase().includes('nvme')) {
          diskType = 'nvme'
        } else if (primaryDisk.type?.toLowerCase().includes('ssd')) {
          diskType = 'ssd'
        } else if (primaryDisk.type?.toLowerCase().includes('hdd') || primaryDisk.interfaceType === 'SATA') {
          // SATA could be SSD or HDD, check if it's rotational
          diskType = 'hdd'
        }
      }

      // Get GPU model (prefer discrete GPU with dedicated VRAM)
      let gpuModel: string | null = null
      if (graphics.controllers && graphics.controllers.length > 0) {
        // First, look for discrete GPUs (NVIDIA, AMD discrete, or any with significant VRAM)
        const discreteGpu = graphics.controllers.find((g) => {
          const vendor = g.vendor?.toLowerCase() || ''
          const model = g.model?.toLowerCase() || ''
          // NVIDIA GPUs are always discrete
          if (vendor.includes('nvidia') || model.includes('geforce') || model.includes('rtx') || model.includes('quadro')) {
            return true
          }
          // AMD discrete GPUs (Radeon, not integrated APU graphics)
          if ((vendor.includes('amd') || vendor.includes('ati')) &&
              (model.includes('radeon') || model.includes('rx ') || model.includes('vega')) &&
              !model.includes('graphics')) {
            return true
          }
          // Any GPU with dedicated VRAM > 512MB is likely discrete
          if (g.vram && g.vram > 512) {
            return true
          }
          return false
        })
        gpuModel = discreteGpu?.model || graphics.controllers[0]?.model || null
      }

      // si.graphics() resolves PCI IDs against the container's pci.ids database,
      // which ages out. A card newer than that file comes back as the literal
      // "Device <pciid>" — an RTX 5060 reports vendor "NVIDIA Corporation",
      // model "Device 2d05", vram 32. The vendor string still matches, so the
      // discrete-GPU finder above accepts it and the authoritative nvidia-smi
      // path below is skipped by its `if (!gpuModel)` guard.
      //
      // That put "Device 2d05" on the public leaderboard, and it is exactly the
      // newest hardware — the results people most want to show off, and the ones
      // that anchor the top of the board — that hits this. Treat a placeholder
      // as no answer so the real detection runs.
      if (gpuModel && isUnresolvedGpuModel(gpuModel)) {
        logger.info(
          `[BenchmarkService] si.graphics() returned an unresolved PCI id ("${gpuModel}"); falling through to authoritative GPU detection`
        )
        gpuModel = null
      }

      // Fallback: Check Docker for nvidia runtime and query GPU model via nvidia-smi
      if (!gpuModel) {
        try {
          const dockerInfo = await this.dockerService.docker.info()
          const runtimes = dockerInfo.Runtimes || {}
          if ('nvidia' in runtimes) {
            logger.info('[BenchmarkService] NVIDIA container runtime detected, querying GPU model via nvidia-smi')

            const systemService = new (await import('./system_service.js')).SystemService(this.dockerService)
            const nvidiaInfo = await systemService.getNvidiaSmiInfo()
            if (Array.isArray(nvidiaInfo) && nvidiaInfo.length > 0) {
              gpuModel = nvidiaInfo[0].model
            } else {
              logger.warn(`[BenchmarkService] NVIDIA runtime detected but failed to get GPU info: ${typeof nvidiaInfo === 'string' ? nvidiaInfo : JSON.stringify(nvidiaInfo)}`)
            }
          }
        } catch (dockerError: any) {
          logger.warn(`[BenchmarkService] Could not query Docker info for GPU detection: ${dockerError.message}`)
        }
      }

      // Fallback: Extract integrated GPU from CPU model name
      if (!gpuModel) {
        const cpuFullName = `${cpu.manufacturer} ${cpu.brand}`

        // AMD APUs: e.g., "AMD Ryzen AI 9 HX 370 w/ Radeon 890M" -> "Radeon 890M"
        const radeonMatch = cpuFullName.match(/w\/\s*(Radeon\s+\d+\w*)/i)
        if (radeonMatch) {
          gpuModel = radeonMatch[1]
        }

        // Intel Core Ultra: These have Intel Arc Graphics integrated
        // e.g., "Intel Core Ultra 9 285HX" -> "Intel Arc Graphics (Integrated)"
        if (!gpuModel && cpu.manufacturer?.toLowerCase().includes('intel')) {
          if (cpu.brand?.toLowerCase().includes('core ultra')) {
            gpuModel = 'Intel Arc Graphics (Integrated)'
          }
        }
      }

      // Fallback: AMD discrete cards. si.graphics() returns empty inside Docker for AMD,
      // the nvidia-smi path doesn't apply, and the APU regex only catches integrated parts.
      // SystemService.getSystemInfo() already handles AMD via the marker file + Ollama log
      // probe added in PR #804, so reuse that plumbing rather than duplicating it here.
      if (!gpuModel) {
        try {
          const systemService = new (await import('./system_service.js')).SystemService(this.dockerService)
          const sysInfo = await systemService.getSystemInfo()
          const sysGpuModel = sysInfo?.graphics?.controllers?.[0]?.model
          // Same si.graphics() source as above, so it can carry the same
          // placeholder — don't launder an unresolved PCI id in through the
          // back door.
          if (sysGpuModel && !isUnresolvedGpuModel(sysGpuModel)) {
            gpuModel = sysGpuModel
          }
        } catch (sysError: any) {
          logger.warn(`[BenchmarkService] system_service AMD fallback failed: ${sysError.message}`)
        }
      }

      return {
        cpu_model: `${cpu.manufacturer} ${cpu.brand}`,
        cpu_cores: cpu.physicalCores,
        cpu_threads: cpu.cores,
        ram_bytes: mem.total,
        disk_type: diskType,
        gpu_model: gpuModel,
      }
    } catch (error: any) {
      logger.error(`Error detecting hardware: ${error.message}`)
      throw new Error(`Failed to detect hardware: ${error.message}`)
    }
  }

  /**
   * Main benchmark execution method
   */
  private async _runBenchmark(type: BenchmarkType, includeAI: boolean): Promise<BenchmarkResult> {
    if (this.currentStatus !== 'idle') {
      throw new Error('A benchmark is already running')
    }

    this.currentBenchmarkId = randomUUID()
    this.currentStages = this._buildStageList(type, includeAI)

    // Start live host-telemetry sampling for the duration of the run. This runs
    // in the orchestration process, not inside the sysbench container, so it
    // cannot influence the scored numbers.
    this.telemetry = new BenchmarkTelemetrySampler(this.currentBenchmarkId)
    this.telemetry.start()

    this._updateStatus('starting', 'Starting benchmark...')

    try {
      // Fail fast: if this run will download the (large) AI model, make sure there's
      // room BEFORE spending minutes on the system benchmarks.
      if (includeAI && (type === 'full' || type === 'ai')) {
        await this._preflightModelDiskSpace()
      }

      // Detect hardware
      const hardware = await this.getHardwareInfo()

      // Run system benchmarks
      let systemScores: SystemScores = {
        cpu_score: 0,
        memory_score: 0,
        disk_read_score: 0,
        disk_write_score: 0,
      }
      let systemRaws: SystemBenchmarkRawsV2 | null = null

      if (type === 'full' || type === 'system') {
        const systemOutput = await this._runSystemBenchmarks(hardware.cpu_threads)
        systemScores = systemOutput.scores
        systemRaws = systemOutput.raws
      }

      // Run AI benchmark if requested and Ollama is available
      let aiScores: Partial<AIScores> = {}
      if (includeAI && (type === 'full' || type === 'ai')) {
        try {
          aiScores = await this._runAIBenchmark()
          if (aiScores.ai_tokens_per_second !== undefined && aiScores.ai_tokens_per_second !== null) {
            this._emitPartialResult({
              status: 'running_ai',
              label: 'AI',
              value: Math.round(aiScores.ai_tokens_per_second),
              unit: 'tok/s',
            })
          }
        } catch (error: any) {
          // For AI-only benchmarks, failing is fatal - don't save useless results with all zeros
          if (type === 'ai') {
            throw new Error(`AI benchmark failed: ${error.message}. Make sure AI Assistant is installed and running.`)
          }
          // For full benchmarks, AI is optional - continue without it
          logger.warn(`AI benchmark skipped: ${error.message}`)
        }
      }

      // Record the sysbench digest that actually ran, not the compiled-in
      // constant. Only meaningful when the system benchmarks ran at all — an
      // AI-only benchmark never pulls the image.
      const sysbenchDigest = systemRaws ? await this._resolveSysbenchDigest() : null

      // Calculate NOMAD scores (v1 legacy + v2 uncapped)
      this._updateStatus('calculating_score', 'Calculating NOMAD score...')
      const nomadScore = this._calculateNomadScore(systemScores, aiScores)

      // v2 requires a complete run of every channel (system raws + AI). Only a
      // full benchmark with AI qualifies; otherwise nomad_score_v2 stays null.
      let nomadScoreV2: number | null = null
      if (systemRaws && aiScores.ai_tokens_per_second && aiScores.ai_tokens_per_second > 0) {
        try {
          nomadScoreV2 = this._calculateNomadScoreV2({
            ai_tokens_per_second: aiScores.ai_tokens_per_second,
            cpu_events_single: systemRaws.cpu_events_single,
            cpu_events_multi: systemRaws.cpu_events_multi,
            memory_ops_per_sec: systemRaws.memory_ops_per_sec,
            disk_read_mb_per_sec: systemRaws.disk_read_mb_per_sec,
            disk_write_mb_per_sec: systemRaws.disk_write_mb_per_sec,
          })
        } catch (error: any) {
          // A non-positive channel shouldn't reach here (each sysbench step throws
          // on a bad parse), but never let a v2 math error sink the whole run.
          logger.warn(`NOMAD Score v2 not computed: ${error.message}`)
        }
      }

      // Best-effort environment metadata (never fails the run).
      const env = await this._detectRunEnvironment()

      // Save result
      const result = await BenchmarkResult.create({
        benchmark_id: this.currentBenchmarkId,
        benchmark_type: type,
        cpu_model: hardware.cpu_model,
        cpu_cores: hardware.cpu_cores,
        cpu_threads: hardware.cpu_threads,
        ram_bytes: hardware.ram_bytes,
        disk_type: hardware.disk_type,
        gpu_model: hardware.gpu_model,
        cpu_score: systemScores.cpu_score,
        memory_score: systemScores.memory_score,
        disk_read_score: systemScores.disk_read_score,
        disk_write_score: systemScores.disk_write_score,
        ai_tokens_per_second: aiScores.ai_tokens_per_second || null,
        ai_model_used: aiScores.ai_model_used || null,
        ai_time_to_first_token: aiScores.ai_time_to_first_token || null,
        nomad_score: nomadScore,
        submitted_to_repository: false,
        sysbench_digest: sysbenchDigest,
        ollama_version: aiScores.ai_ollama_version ?? null,
        // v2 raw channels + score (null on system-only / AI-less runs)
        cpu_events_single: systemRaws?.cpu_events_single ?? null,
        cpu_events_multi: systemRaws?.cpu_events_multi ?? null,
        cpu_benchmark_threads: systemRaws?.cpu_benchmark_threads ?? null,
        cpu_total_events: systemRaws?.cpu_total_events ?? null,
        cpu_total_time: systemRaws?.cpu_total_time ?? null,
        memory_ops_per_sec: systemRaws?.memory_ops_per_sec ?? null,
        memory_threads: systemRaws?.memory_threads ?? null,
        disk_read_mb_per_sec: systemRaws?.disk_read_mb_per_sec ?? null,
        disk_write_mb_per_sec: systemRaws?.disk_write_mb_per_sec ?? null,
        nomad_score_v2: nomadScoreV2,
        run_environment: env.run_environment,
        storage_path_type: env.storage_path_type,
        gpu_compute_detected: env.gpu_compute_detected,
        cpu_architecture: env.cpu_architecture,
        os_name: env.os_name,
        os_version: env.os_version,
      })

      this._updateStatus('completed', 'Benchmark completed successfully')
      this.currentStatus = 'idle'
      this.currentBenchmarkId = null

      return result
    } catch (error: any) {
      this._updateStatus('error', `Benchmark failed: ${error.message}`)
      this.currentStatus = 'idle'
      this.currentBenchmarkId = null
      throw error
    } finally {
      this.telemetry?.stop()
      this.telemetry = null
      this.currentStages = []
    }
  }

  /**
   * Run system benchmarks using sysbench in Docker.
   *
   * Produces both the legacy v1 0-1 sub-scores AND the v2 raw channels from the
   * same runs. CPU runs twice: 1 thread (single-core index) and all logical
   * threads (multi-core index); the v1 cpu_score keys off the multi pass to stay
   * comparable with historical results.
   *
   * @param multiThreads number of threads for the multi-core CPU pass (all logical CPUs)
   */
  private async _runSystemBenchmarks(multiThreads: number): Promise<SystemBenchmarkOutput> {
    // Ensure sysbench image is available
    await this._ensureSysbenchImage()

    // Run CPU benchmarks: single-thread then all-thread.
    this._updateStatus('running_cpu', 'Running CPU benchmark (single-thread)...')
    const cpuSingle = await this._runSysbenchCpu(1)

    this._updateStatus('running_cpu', `Running CPU benchmark (${multiThreads}-thread)...`)
    const cpuMulti = await this._runSysbenchCpu(multiThreads)

    // Run memory benchmark
    this._updateStatus('running_memory', 'Running memory benchmark...')
    const memoryResult = await this._runSysbenchMemory()
    this._emitPartialResult({
      status: 'running_memory',
      label: 'Memory',
      value: Math.round(memoryResult.operations_per_second),
      unit: 'ops/s',
    })

    // Run disk benchmarks
    this._updateStatus('running_disk_read', 'Running disk read benchmark...')
    const diskReadResult = await this._runSysbenchDiskRead()
    this._emitPartialResult({
      status: 'running_disk_read',
      label: 'Read',
      value: Math.round(diskReadResult.read_mb_per_sec),
      unit: 'MB/s',
    })

    this._updateStatus('running_disk_write', 'Running disk write benchmark...')
    const diskWriteResult = await this._runSysbenchDiskWrite()
    this._emitPartialResult({
      status: 'running_disk_write',
      label: 'Write',
      value: Math.round(diskWriteResult.write_mb_per_sec),
      unit: 'MB/s',
    })

    // Legacy v1 sub-scores (0-1), normalized against the v1 references. cpu_score
    // uses the multi-thread pass to match historical (4-thread) behaviour closely.
    const scores: SystemScores = {
      cpu_score: this._normalizeScore(cpuMulti.events_per_second, REFERENCE_SCORES.cpu_events_per_second),
      memory_score: this._normalizeScore(memoryResult.operations_per_second, REFERENCE_SCORES.memory_ops_per_second),
      disk_read_score: this._normalizeScore(diskReadResult.read_mb_per_sec, REFERENCE_SCORES.disk_read_mb_per_sec),
      disk_write_score: this._normalizeScore(diskWriteResult.write_mb_per_sec, REFERENCE_SCORES.disk_write_mb_per_sec),
    }

    // v2 raw channels — the payload of record for the leaderboard.
    const raws: SystemBenchmarkRawsV2 = {
      cpu_events_single: cpuSingle.events_per_second,
      cpu_events_multi: cpuMulti.events_per_second,
      cpu_benchmark_threads: multiThreads,
      cpu_total_events: cpuMulti.total_events,
      cpu_total_time: cpuMulti.total_time,
      memory_ops_per_sec: memoryResult.operations_per_second,
      memory_threads: MEMORY_BENCHMARK_THREADS,
      disk_read_mb_per_sec: diskReadResult.read_mb_per_sec,
      disk_write_mb_per_sec: diskWriteResult.write_mb_per_sec,
    }

    return { scores, raws }
  }

  /**
   * Probe live NVIDIA GPU stats by exec-ing nvidia-smi inside the Ollama
   * container (same approach as SystemService.getNvidiaSmiInfo). Telemetry-only:
   * returns null on any failure (no Ollama container, no NVIDIA GPU / AMD,
   * unparseable output) and must never affect the scored benchmark numbers.
   */
  private async _probeGpuStats(): Promise<NonNullable<BenchmarkTelemetry['gpu']> | null> {
    try {
      const containers = await this.dockerService.docker.listContainers({ all: false })
      const ollamaContainer = containers.find((c) => c.Names.includes(`/${SERVICE_NAMES.OLLAMA}`))
      if (!ollamaContainer) return null

      const container = this.dockerService.docker.getContainer(ollamaContainer.Id)
      const exec = await container.exec({
        Cmd: [
          'nvidia-smi',
          '--query-gpu=utilization.gpu,memory.used,memory.total',
          '--format=csv,noheader,nounits',
        ],
        AttachStdout: true,
        AttachStderr: true,
        Tty: true,
      })

      // Read the output stream with a timeout to prevent hanging if nvidia-smi fails
      const stream = await exec.start({ Tty: true })
      const output = await new Promise<string>((resolve) => {
        let data = ''
        const timeout = setTimeout(() => resolve(data), 3000)
        stream.on('data', (chunk: Buffer) => {
          data += chunk.toString()
        })
        stream.on('end', () => {
          clearTimeout(timeout)
          resolve(data)
        })
      })

      // Remove any non-printable characters and trim the output
      const cleaned = Array.from(output)
        .filter((character) => character.charCodeAt(0) > 8)
        .join('')
        .trim()
      if (!cleaned || cleaned.toLowerCase().includes('error') || cleaned.toLowerCase().includes('not found')) {
        return null
      }

      // First GPU only: "<util>, <used>, <total>"
      const parts = cleaned.split('\n')[0].split(',').map((s) => s.trim())
      if (parts.length < 3) return null
      const util = Number.parseInt(parts[0], 10)
      const used = Number.parseInt(parts[1], 10)
      const total = Number.parseInt(parts[2], 10)
      if (!Number.isFinite(util) || !Number.isFinite(used) || !Number.isFinite(total)) return null

      return { util, vram_used_mb: used, vram_total_mb: total }
    } catch {
      return null
    }
  }

  /**
   * Run AI benchmark using Ollama
   */
  private async _runAIBenchmark(): Promise<AIScores> {
    let gpuPollTimer: NodeJS.Timeout | null = null
    try {
      // Live GPU-util overlay poller. Side-effect-only: it feeds telemetry frames
      // and is cleared in the finally below so it never outlives the AI stage.

      this._updateStatus('running_ai', 'Running AI benchmark...')

      const ollamaAPIURL = await this.dockerService.getServiceURL(SERVICE_NAMES.OLLAMA)
      if (!ollamaAPIURL) {
        throw new Error('AI Assistant service location could not be determined. Ensure AI Assistant is installed and running.')
      }

      // Check if Ollama is available
      try {
        await axios.get(`${ollamaAPIURL}/api/tags`, { timeout: 5000 })
      } catch (error: any) {
        const errorCode = error.code || error.response?.status || 'unknown'
        throw new Error(`Ollama is not running or not accessible (${errorCode}). Ensure AI Assistant is installed and running.`)
      }

      // Record the Ollama version for forensics (null-tolerant — never fail the run on this)
      const versionResp = await axios.get(`${ollamaAPIURL}/api/version`, { timeout: 5000 }).catch(() => null)
      const ollamaVersion: string | null = versionResp?.data?.version ?? null

      // GPU-util overlay (NVIDIA only): probe once; if a GPU answers, poll for the
      // duration of the AI stage. If the probe returns null (no GPU / AMD), the
      // overlay simply never appears. Best-effort: failures never affect the run.
      try {
        const initialGpu = await this._probeGpuStats()
        if (initialGpu) {
          this.telemetry?.setGpuStats(initialGpu)
          let gpuProbeInFlight = false
          gpuPollTimer = setInterval(() => {
            if (gpuProbeInFlight) return
            gpuProbeInFlight = true
            this._probeGpuStats()
              .then((stats) => this.telemetry?.setGpuStats(stats))
              .catch(() => this.telemetry?.setGpuStats(null))
              .finally(() => {
                gpuProbeInFlight = false
              })
          }, 1000)
        }
      } catch {
        // GPU overlay is cosmetic; ignore probe failures entirely.
      }

      // Check if the benchmark model is available, pull if not
      const ollamaService = new (await import('./ollama_service.js')).OllamaService()
      const modelResponse = await ollamaService.downloadModel(AI_BENCHMARK_MODEL)
      if (!modelResponse.success) {
        throw new Error(`Model does not exist and failed to download: ${modelResponse.message}`)
      }

      // Evict any other models resident in VRAM/RAM before benchmarking. With an 8B
      // reference model, a chat model left loaded can starve it of VRAM → Ollama
      // offloads layers to CPU → a low, non-comparable score. Give the benchmark
      // model the whole GPU. Best-effort: never fail the run on an eviction hiccup.
      await this._unloadResidentModels(ollamaAPIURL)

      // Warm-up pass (result discarded). The eviction above forces the benchmark
      // model cold, so without this the first *timed* inference would pay the full
      // model-load + GPU spin-up cost. On a cold box that lands as a huge outlier
      // (observed: 173s TTFT / 5.83 tok/s on a run whose warm steady-state was
      // ~80 tok/s), and since the AI channel is uncapped and ~30% of the composite
      // it swings the whole NOMAD Score ~2x between a cold first run and a warm
      // re-run of the same machine. Measure warm, steady-state throughput instead:
      // load the model and warm the context here, then time the median-of-N below.
      // Best-effort — a warm-up hiccup must not fail the run (the timed loop will
      // surface any real inference error). See issue #1139.
      // Log the swallowed failure. Silently discarding it makes a run whose
      // reproducibility guarantee did not actually apply indistinguishable from
      // a clean one after the fact. Matches _unloadResidentModels, the sibling
      // best-effort helper, which already warns on every swallowed error.
      this._updateStatus('running_ai', 'Warming up AI model...')
      await this._runSingleAIInference(ollamaAPIURL).catch((error) => {
        logger.warn(
          `[BenchmarkService] AI warm-up failed (${error?.message ?? error}); the first timed run may be cold.`
        )
        return null
      })

      // Run inference AI_BENCHMARK_RUNS times and take the median run by tok/s (W7).
      // A single inference is noisy (scheduler, thermal, cache); the median damps
      // outliers. The model is already warm (see the warm-up pass above), so every
      // timed run measures steady-state throughput. TTFT is reported from the same
      // run that is the tok/s median, so the two figures always describe one real
      // inference.
      const runs: { tps: number; ttft: number }[] = []
      for (let i = 0; i < AI_BENCHMARK_RUNS; i++) {
        this._updateStatus('running_ai', `Running AI benchmark (${i + 1}/${AI_BENCHMARK_RUNS})...`)
        runs.push(await this._runSingleAIInference(ollamaAPIURL))
      }

      // Median by tok/s (odd count → middle element).
      runs.sort((a, b) => a.tps - b.tps)
      const median = runs[Math.floor(runs.length / 2)]

      // Leave the GPU as clean as we found it: unload our benchmark model so the
      // user's next chat loads their model into a free GPU (Ollama reloads on demand;
      // we deliberately don't try to restore whichever model they had before).
      await this._unloadResidentModels(ollamaAPIURL)

      return {
        ai_tokens_per_second: Math.round(median.tps * 100) / 100,
        ai_model_used: AI_BENCHMARK_MODEL,
        ai_time_to_first_token: Math.round(median.ttft * 100) / 100,
        ai_ollama_version: ollamaVersion,
      }
    } catch (error: any) {
      throw new Error(`AI benchmark failed: ${error.message}`)
    } finally {
      if (gpuPollTimer) {
        clearInterval(gpuPollTimer)
      }
      this.telemetry?.setGpuStats(null)
    }
  }

  /**
   * Run a single Ollama inference and return its tokens/sec and time-to-first-token
   * (TTFT in milliseconds). Extracted so the AI benchmark can run it N times for a
   * median. Prefers Ollama's eval_count/eval_duration; falls back to wall-clock
   * word-count estimation if those fields are absent.
   */
  private async _runSingleAIInference(
    ollamaAPIURL: string
  ): Promise<{ tps: number; ttft: number }> {
    const startTime = Date.now()

    const response = await axios.post(
      `${ollamaAPIURL}/api/generate`,
      {
        model: AI_BENCHMARK_MODEL,
        prompt: AI_BENCHMARK_PROMPT,
        stream: false,
        options: { num_predict: AI_BENCHMARK_NUM_PREDICT },
      },
      { timeout: 120000 }
    )

    const endTime = Date.now()
    const totalTime = (endTime - startTime) / 1000 // seconds

    // Ollama returns eval_count (tokens generated) and eval_duration (nanoseconds)
    if (response.data.eval_count && response.data.eval_duration) {
      const tokenCount = response.data.eval_count
      const evalDurationSeconds = response.data.eval_duration / 1e9
      const tokensPerSecond = tokenCount / evalDurationSeconds

      // Time to first token from prompt_eval_duration
      const ttft = response.data.prompt_eval_duration
        ? response.data.prompt_eval_duration / 1e6 // Convert to ms
        : (totalTime * 1000) / 2 // Estimate if not available

      return { tps: tokensPerSecond, ttft }
    }

    // Fallback calculation
    const estimatedTokens = response.data.response?.split(' ').length * 1.3 || 100
    const tokensPerSecond = estimatedTokens / totalTime
    return { tps: tokensPerSecond, ttft: (totalTime * 1000) / 2 }
  }

  /**
   * Fail fast if the AI model will need downloading and there isn't room for it.
   *
   * Only relevant on first run: if the model is already pulled, no download happens
   * and we skip the check. Best-effort throughout — if Ollama isn't reachable or free
   * space can't be determined, we do NOT block (the AI stage will surface its own
   * error), because a false "insufficient disk" is worse than letting the pull try.
   */
  private async _preflightModelDiskSpace(): Promise<void> {
    let ollamaAPIURL: string | null = null
    try {
      ollamaAPIURL = await this.dockerService.getServiceURL(SERVICE_NAMES.OLLAMA)
    } catch {
      return // AI stage will report Ollama problems
    }
    if (!ollamaAPIURL) return

    // If the model is already present, no download → no disk need.
    try {
      const tags = await axios.get(`${ollamaAPIURL}/api/tags`, { timeout: 5000 })
      const models: string[] = (tags.data?.models ?? []).map((m: { name?: string }) => m.name)
      if (models.includes(AI_BENCHMARK_MODEL)) return
    } catch {
      return // can't reach Ollama; let the AI stage handle it
    }

    // Model not cached → a pull is coming. Require headroom on the root FS.
    let freeBytes: number | null = null
    try {
      const systemService = new (await import('./system_service.js')).SystemService(this.dockerService)
      freeBytes = await getFreeBytes(systemService)
    } catch {
      return // couldn't measure free space — don't block on uncertainty
    }
    if (freeBytes === null) return

    if (freeBytes < AI_BENCHMARK_MODEL_MIN_FREE_BYTES) {
      const gib = (b: number) => `${(b / 1024 / 1024 / 1024).toFixed(1)} GB`
      throw new Error(
        `Not enough free disk space to download the AI benchmark model (${AI_BENCHMARK_MODEL}). ` +
          `About ${gib(AI_BENCHMARK_MODEL_MIN_FREE_BYTES)} is required but only ${gib(freeBytes)} is free. ` +
          `Free up some space and try again.`
      )
    }
  }

  /**
   * Evict every model currently resident in Ollama (VRAM/RAM) so the benchmark
   * model gets the whole GPU. Queries /api/ps for loaded models and unloads each
   * via a keep_alive:0 request. Entirely best-effort: any failure (older Ollama
   * without /api/ps, a model mid-stream) is logged and swallowed — a clean-VRAM
   * optimization must never block the benchmark itself.
   */
  private async _unloadResidentModels(ollamaAPIURL: string): Promise<void> {
    try {
      const ps = await axios.get(`${ollamaAPIURL}/api/ps`, { timeout: 5000 })
      const loaded: string[] = (ps.data?.models ?? [])
        .map((m: { name?: string; model?: string }) => m.name || m.model)
        .filter((n: string | undefined): n is string => !!n)

      if (loaded.length === 0) return

      logger.info(`[BenchmarkService] Evicting ${loaded.length} resident model(s) before AI benchmark: ${loaded.join(', ')}`)
      for (const model of loaded) {
        // keep_alive:0 tells Ollama to unload immediately (no prompt needed).
        await axios
          .post(`${ollamaAPIURL}/api/generate`, { model, keep_alive: 0 }, { timeout: 15000 })
          .catch((e) => logger.warn(`[BenchmarkService] Failed to unload ${model}: ${e.message}`))
      }
    } catch (error: any) {
      logger.warn(`[BenchmarkService] Could not enumerate/unload resident models (continuing): ${error.message}`)
    }
  }

  /**
   * Calculate weighted NOMAD score
   */
  private _calculateNomadScore(
    systemScores: SystemScores | null,
    aiScores: Partial<AIScores>
  ): number {
    let totalWeight = 0
    let weightedSum = 0

    // System scores (only when the system benchmarks actually ran). Passing null
    // for an AI-only run keeps the system weights OUT of the denominator so the
    // score renormalizes to just the AI portion's 0-100 range, rather than being
    // scaled against the full NOMAD 100 (where an excellent AI setup would cap
    // at ~40). System-only already renormalizes correctly because aiScores is
    // empty and its weights are likewise skipped below.
    if (systemScores) {
      // CPU score
      weightedSum += systemScores.cpu_score * SCORE_WEIGHTS.cpu
      totalWeight += SCORE_WEIGHTS.cpu

      // Memory score
      weightedSum += systemScores.memory_score * SCORE_WEIGHTS.memory
      totalWeight += SCORE_WEIGHTS.memory

      // Disk scores
      weightedSum += systemScores.disk_read_score * SCORE_WEIGHTS.disk_read
      totalWeight += SCORE_WEIGHTS.disk_read
      weightedSum += systemScores.disk_write_score * SCORE_WEIGHTS.disk_write
      totalWeight += SCORE_WEIGHTS.disk_write
    }

    // AI scores (if available)
    if (aiScores.ai_tokens_per_second !== undefined && aiScores.ai_tokens_per_second !== null) {
      const aiScore = this._normalizeScore(
        aiScores.ai_tokens_per_second,
        REFERENCE_SCORES.ai_tokens_per_second
      )
      weightedSum += aiScore * SCORE_WEIGHTS.ai_tokens_per_second
      totalWeight += SCORE_WEIGHTS.ai_tokens_per_second
    }

    if (aiScores.ai_time_to_first_token !== undefined && aiScores.ai_time_to_first_token !== null) {
      // For TTFT, lower is better, so we invert the score
      const ttftScore = this._normalizeScoreInverse(
        aiScores.ai_time_to_first_token,
        REFERENCE_SCORES.ai_ttft_ms
      )
      weightedSum += ttftScore * SCORE_WEIGHTS.ai_ttft
      totalWeight += SCORE_WEIGHTS.ai_ttft
    }

    // Normalize by actual weight used (in case AI benchmarks were skipped)
    const nomadScore = totalWeight > 0 ? (weightedSum / totalWeight) * 100 : 0

    return Math.round(Math.min(100, Math.max(0, nomadScore)) * 100) / 100
  }

  /**
   * Calculate the NOMAD Score v2 from raw channel values.
   *
   * Byte-identical to the leaderboard's computeNomadScoreV2 (score_service.ts):
   * the weighted geometric mean vs the frozen Reference Build, computed in the
   * log domain, rounded to one decimal. NO clamps. Throws if any channel is
   * <= 0 — a full v2 run measures every channel, and log2 of a non-positive
   * ratio is undefined, so a non-positive value here is a programming error, not
   * a user input to clamp. Every scored channel (incl. AI) is required; callers
   * only invoke this for a complete full-benchmark run.
   */
  private _calculateNomadScoreV2(raws: ScoreRawsV2): number {
    let logSum = 0
    for (const channel of SCORE_CHANNELS_V2) {
      const raw = raws[channel]
      if (!(raw > 0)) {
        throw new Error(`_calculateNomadScoreV2: channel "${channel}" must be > 0 (got ${raw})`)
      }
      const ratio = raw / REFERENCE_SCORES_V2[channel]
      logSum += SCORE_WEIGHTS_V2[channel] * Math.log2(ratio)
    }
    const score = 1000 * Math.pow(2, logSum)
    // One decimal, matching the leaderboard's display convention.
    return Math.round(score * 10) / 10
  }

  /**
   * Detect best-effort run-environment metadata for the leaderboard (issue #1016).
   * Every probe is independently guarded — this never throws and never fails a run;
   * any field it can't determine stays null.
   */
  private async _detectRunEnvironment(): Promise<RunEnvironmentInfo> {
    const info: RunEnvironmentInfo = {
      run_environment: null,
      storage_path_type: null,
      gpu_compute_detected: null,
      cpu_architecture: null,
      os_name: null,
      os_version: null,
    }

    // run_environment: WSL2 vs native Linux, from the host kernel string.
    try {
      const procVersion = await readFile('/proc/version', 'utf8')
      info.run_environment = /microsoft|wsl/i.test(procVersion) ? 'wsl2' : 'native-linux'
    } catch {
      // /proc/version unreadable — leave null
    }

    // storage_path_type: the Docker storage driver backing the benchmarked FS.
    try {
      const dockerInfo = await this.dockerService.docker.info()
      if (dockerInfo?.Driver) info.storage_path_type = String(dockerInfo.Driver)

      // Platform metadata from the same call. The Docker daemon reports the
      // HOST, which is the whole point — os.arch() and si.osInfo() inside the
      // admin container describe the container instead.
      //
      // Observed: Architecture 'x86_64' | 'aarch64', OSVersion '24.04',
      // OperatingSystem 'Ubuntu 24.04.4 LTS'.
      if (dockerInfo?.Architecture) {
        info.cpu_architecture = normalizeArchitecture(String(dockerInfo.Architecture))
      }
      if (dockerInfo?.OperatingSystem) {
        const osVersion = dockerInfo.OSVersion ? String(dockerInfo.OSVersion) : null
        info.os_version = osVersion
        info.os_name = deriveOsName(String(dockerInfo.OperatingSystem), osVersion)
      }
    } catch {
      // docker info failed — leave null
    }

    // gpu_compute_detected: whether a GPU compute type was detected + persisted.
    try {
      const gpuType = await KVStore.getValue('gpu.type')
      info.gpu_compute_detected = gpuType === 'nvidia' || gpuType === 'amd'
    } catch {
      // KV read failed — leave null
    }

    return info
  }

  /**
   * Normalize a raw score to 0-100 scale using log scaling
   * This provides diminishing returns for very high scores
   */
  private _normalizeScore(value: number, reference: number): number {
    if (value <= 0) return 0
    // Log scale with widened range: dividing log2 by 3 prevents scores from
    // clamping to 0% for below-average hardware. Gives 50% at reference value.
    const ratio = value / reference
    const score = 50 * (1 + Math.log2(Math.max(0.01, ratio)) / 3)
    return Math.min(100, Math.max(0, score)) / 100
  }

  /**
   * Normalize a score where lower is better (like latency)
   */
  private _normalizeScoreInverse(value: number, reference: number): number {
    if (value <= 0) return 1
    // Inverse: lower values = higher scores, with widened log range
    const ratio = reference / value
    const score = 50 * (1 + Math.log2(Math.max(0.01, ratio)) / 3)
    return Math.min(100, Math.max(0, score)) / 100
  }

  /**
   * Ensure sysbench Docker image is available
   */
  private async _ensureSysbenchImage(): Promise<void> {
    try {
      await this.dockerService.docker.getImage(SYSBENCH_IMAGE).inspect()
    } catch {
      this._updateStatus('starting', `Pulling sysbench image...`)
      await this.dockerService.pullImage(SYSBENCH_IMAGE)
    }
  }

  /**
   * The sysbench digest actually resolved on this machine.
   *
   * Previously the submission reported SYSBENCH_DIGEST — the constant the client
   * was compiled with. The leaderboard validates that field against an allowlist,
   * but a constant attests to how the client was BUILT, not to what it RAN, so
   * any build inherits a valid value simply by carrying the same source.
   *
   * Reading it back from the image means a divergent build has to actively
   * falsify the field rather than passively inherit it. Still forgeable — the
   * client is open source and always will be — but it moves the bar from "no
   * effort" to "deliberate", which is the distinction that matters when judging
   * whether a submission is a mistake or a choice.
   *
   * Uses RepoDigests (the manifest digest we pulled by), NOT Id — Id is the
   * config digest, which differs per architecture and would never match the
   * allowlist. Falls back to the constant if inspection gives us nothing usable,
   * so a benchmark never fails over provenance metadata.
   */
  private async _resolveSysbenchDigest(): Promise<string> {
    try {
      const info = await this.dockerService.docker.getImage(SYSBENCH_IMAGE).inspect()
      const repoDigest = (info?.RepoDigests ?? []).find((d: string) => d.includes('@sha256:'))
      const digest = repoDigest?.split('@')[1]
      if (digest) return digest
      logger.warn('[BenchmarkService] No RepoDigest on the sysbench image; reporting the pinned constant.')
    } catch (error: any) {
      logger.warn(`[BenchmarkService] Could not inspect the sysbench image (${error.message}); reporting the pinned constant.`)
    }
    return SYSBENCH_DIGEST
  }

  /**
   * Run sysbench CPU benchmark at the given thread count.
   *
   * v2 runs this twice: 1 thread (single-core index) and all threads (multi-core
   * index). The multi pass also supplies the W6 consistency companions
   * (total_events / total_time) the leaderboard cross-checks against events/sec.
   */
  private async _runSysbenchCpu(threads: number): Promise<SysbenchCpuResult> {
    const output = await this._runSysbenchCommand([
      'sysbench',
      'cpu',
      '--cpu-max-prime=20000',
      `--threads=${threads}`,
      '--time=30',
      'run',
    ])

    // Parse output for events per second
    const eventsMatch = output.match(/events per second:\s*([\d.]+)/i)
    const totalTimeMatch = output.match(/total time:\s*([\d.]+)s/i)
    const totalEventsMatch = output.match(/total number of events:\s*(\d+)/i)
    logger.debug(`[BenchmarkService] CPU output parsing (${threads}T) - events/s: ${eventsMatch?.[1]}, total_time: ${totalTimeMatch?.[1]}, total_events: ${totalEventsMatch?.[1]}`)

    // Scored primary metric: fail loudly instead of silently scoring zero on a parse miss
    const eventsPerSecond = eventsMatch ? parseFloat(eventsMatch[1]) : Number.NaN
    if (!eventsMatch || !Number.isFinite(eventsPerSecond) || eventsPerSecond <= 0) {
      throw new Error('sysbench CPU benchmark produced no parseable events/sec — aborting (output may have changed or the test failed)')
    }

    const totalTime = totalTimeMatch ? parseFloat(totalTimeMatch[1]) : 30
    // total_events feeds the leaderboard's W6 cross-check (events/sec must equal
    // total_events/total_time within 2%). If the count line ever fails to parse,
    // derive it from the rate so we submit a self-consistent payload rather than
    // a zero that would be rejected as "internally inconsistent".
    const parsedTotalEvents = totalEventsMatch ? parseInt(totalEventsMatch[1]) : Number.NaN
    const totalEvents =
      Number.isFinite(parsedTotalEvents) && parsedTotalEvents > 0
        ? parsedTotalEvents
        : Math.round(eventsPerSecond * totalTime)

    return {
      events_per_second: eventsPerSecond,
      total_time: totalTime,
      total_events: totalEvents,
    }
  }

  /**
   * Run sysbench memory benchmark
   */
  private async _runSysbenchMemory(): Promise<SysbenchMemoryResult> {
    const output = await this._runSysbenchCommand([
      'sysbench',
      'memory',
      '--memory-block-size=1K',
      '--memory-total-size=10G',
      `--threads=${MEMORY_BENCHMARK_THREADS}`,
      'run',
    ])

    // Parse output
    const opsMatch = output.match(/Total operations:\s*\d+\s*\(([\d.]+)\s*per second\)/i)
    const transferMatch = output.match(/([\d.]+)\s*MiB\/sec/i)
    const timeMatch = output.match(/total time:\s*([\d.]+)s/i)

    // Scored primary metric: fail loudly instead of silently scoring zero on a parse miss
    const opsPerSecond = opsMatch ? parseFloat(opsMatch[1]) : Number.NaN
    if (!opsMatch || !Number.isFinite(opsPerSecond) || opsPerSecond <= 0) {
      throw new Error('sysbench memory benchmark produced no parseable ops/sec — aborting')
    }

    return {
      operations_per_second: opsPerSecond,
      transfer_rate_mb_per_sec: transferMatch ? parseFloat(transferMatch[1]) : 0,
      total_time: timeMatch ? parseFloat(timeMatch[1]) : 0,
    }
  }

  /**
   * Run sysbench disk read benchmark
   */
  private async _runSysbenchDiskRead(): Promise<SysbenchDiskResult> {
    // Run prepare, test, and cleanup in a single container
    // This is necessary because each container has its own filesystem
    // --file-extra-flags=direct (O_DIRECT) on the run bypasses the page cache so
    // we measure real device throughput, not RAM (W4). Only the run needs it;
    // prepare/cleanup are plain file ops. v2 reference disk numbers are O_DIRECT.
    const output = await this._runSysbenchCommand([
      'sh',
      '-c',
      'sysbench fileio --file-total-size=1G --file-num=4 prepare && ' +
        'sysbench fileio --file-total-size=1G --file-num=4 --file-test-mode=seqrd --file-extra-flags=direct --time=30 run && ' +
        'sysbench fileio --file-total-size=1G --file-num=4 cleanup',
    ])

    // Parse output - look for the Throughput section
    const readMatch = output.match(/read,\s*MiB\/s:\s*([\d.]+)/i)
    const readsPerSecMatch = output.match(/reads\/s:\s*([\d.]+)/i)

    logger.debug(`[BenchmarkService] Disk read output parsing - read: ${readMatch?.[1]}, reads/s: ${readsPerSecMatch?.[1]}`)

    // Scored primary metric: fail loudly instead of silently scoring zero on a parse miss
    const readMbPerSec = readMatch ? parseFloat(readMatch[1]) : Number.NaN
    if (!readMatch || !Number.isFinite(readMbPerSec) || readMbPerSec <= 0) {
      throw new Error('sysbench disk-read benchmark produced no parseable MiB/s — aborting')
    }

    return {
      reads_per_second: readsPerSecMatch ? parseFloat(readsPerSecMatch[1]) : 0,
      writes_per_second: 0,
      read_mb_per_sec: readMbPerSec,
      write_mb_per_sec: 0,
      total_time: 30,
    }
  }

  /**
   * Run sysbench disk write benchmark
   */
  private async _runSysbenchDiskWrite(): Promise<SysbenchDiskResult> {
    // Run prepare, test, and cleanup in a single container
    // This is necessary because each container has its own filesystem
    // --file-extra-flags=direct (O_DIRECT) on the run bypasses the page cache (W4).
    const output = await this._runSysbenchCommand([
      'sh',
      '-c',
      'sysbench fileio --file-total-size=1G --file-num=4 prepare && ' +
        'sysbench fileio --file-total-size=1G --file-num=4 --file-test-mode=seqwr --file-extra-flags=direct --time=30 run && ' +
        'sysbench fileio --file-total-size=1G --file-num=4 cleanup',
    ])

    // Parse output - look for the Throughput section
    const writeMatch = output.match(/written,\s*MiB\/s:\s*([\d.]+)/i)
    const writesPerSecMatch = output.match(/writes\/s:\s*([\d.]+)/i)

    logger.debug(`[BenchmarkService] Disk write output parsing - written: ${writeMatch?.[1]}, writes/s: ${writesPerSecMatch?.[1]}`)

    // Scored primary metric: fail loudly instead of silently scoring zero on a parse miss
    const writeMbPerSec = writeMatch ? parseFloat(writeMatch[1]) : Number.NaN
    if (!writeMatch || !Number.isFinite(writeMbPerSec) || writeMbPerSec <= 0) {
      throw new Error('sysbench disk-write benchmark produced no parseable MiB/s — aborting')
    }

    return {
      reads_per_second: 0,
      writes_per_second: writesPerSecMatch ? parseFloat(writesPerSecMatch[1]) : 0,
      read_mb_per_sec: 0,
      write_mb_per_sec: writeMbPerSec,
      total_time: 30,
    }
  }

  /**
   * Run a sysbench command in a Docker container
   */
  private async _runSysbenchCommand(cmd: string[]): Promise<string> {
    let container: Dockerode.Container | null = null
    try {
      // Create container with TTY to avoid multiplexed output
      container = await this.dockerService.docker.createContainer({
        Image: SYSBENCH_IMAGE,
        Cmd: cmd,
        name: `${SYSBENCH_CONTAINER_NAME}_${Date.now()}`,
        Tty: true, // Important: prevents multiplexed stdout/stderr headers
        HostConfig: {
          AutoRemove: false, // Don't auto-remove to avoid race condition with fetching logs
        },
      })

      // Start container
      await container.start()

      // Wait for completion
      await container.wait()

      // Get logs after container has finished
      const logs = await container.logs({
        stdout: true,
        stderr: true,
      })

      // Parse logs (Docker logs include header bytes)
      const output = logs.toString('utf8')
        .replace(/[\x00-\x08]/g, '') // Remove control characters
        .trim()

      // Manually remove the container after getting logs
      try {
        await container.remove()
      } catch (removeError: any) {
        // Log but don't fail if removal fails (container might already be gone)
        logger.warn(`Failed to remove sysbench container: ${removeError.message}`)
      }

      return output
    } catch (error: any) {
      // Clean up container on error if it exists
      if (container) {
        try {
          await container.remove({ force: true })
        } catch (removeError: any) {
          // Ignore removal errors
        }
      }
      logger.error(`Sysbench command failed: ${error.message}`)
      throw new Error(`Sysbench command failed: ${error.message}`)
    }
  }

  /**
   * Like _runSysbenchCommand but attaches to the container's output stream and
   * invokes onLine for every complete line as it arrives, so interim
   * --report-interval lines can drive live telemetry. Still returns the full
   * accumulated stdout so the caller's final-report regexes (the SCORED numbers)
   * parse exactly as before. onLine parsing must never throw.
   */
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  // @ts-ignore TS6133: Reserved for future live sysbench telemetry mode.
  private async _runSysbenchCommandStreaming(
    cmd: string[],
    onLine: (line: string) => void
  ): Promise<string> {
    let container: Dockerode.Container | null = null
    try {
      container = await this.dockerService.docker.createContainer({
        Image: SYSBENCH_IMAGE,
        Cmd: cmd,
        name: `${SYSBENCH_CONTAINER_NAME}_${Date.now()}`,
        Tty: true, // Important: prevents multiplexed stdout/stderr headers
        HostConfig: {
          AutoRemove: false, // Don't auto-remove to avoid race condition with output capture
        },
      })

      // Attach BEFORE starting so no early output is missed. With Tty: true the
      // attach stream is raw (non-multiplexed), so no demuxing is needed.
      const stream = await container.attach({ stream: true, stdout: true, stderr: true })

      // The attach stream drives the live onLine callbacks only (best-effort
      // telemetry). A missed trailing line here is harmless — it never feeds the
      // scored numbers, which come from container.logs() after exit below.
      let buffer = ''
      stream.on('data', (chunk: Buffer) => {
        buffer += chunk.toString('utf8')
        let newlineIdx: number
        while ((newlineIdx = buffer.indexOf('\n')) >= 0) {
          const line = buffer.slice(0, newlineIdx)
          buffer = buffer.slice(newlineIdx + 1)
          try {
            onLine(line)
          } catch {
            // Live-parse failures must never affect the benchmark itself.
          }
        }
      })

      await container.start()
      await container.wait()

      // Flush any trailing partial line through onLine (best-effort).
      if (buffer.length > 0) {
        try {
          onLine(buffer)
        } catch {
          // Live-parse failures must never affect the benchmark itself.
        }
      }

      // Authoritative output for the SCORED parse. Fetch the complete captured
      // log AFTER exit, exactly like _runSysbenchCommand does, rather than
      // trusting the live attach stream — attach 'data' events can flush after
      // container.wait() resolves, which would truncate the final report and
      // break the scoring regexes. This makes the returned output byte-identical
      // to the non-streaming path.
      const logs = await container.logs({
        stdout: true,
        stderr: true,
      })
      const cleaned = logs
        .toString('utf8')
        .replace(/[\x00-\x08]/g, '') // Remove control characters
        .trim()

      // Manually remove the container after capturing output
      try {
        await container.remove()
      } catch (removeError: any) {
        // Log but don't fail if removal fails (container might already be gone)
        logger.warn(`Failed to remove sysbench container: ${removeError.message}`)
      }

      return cleaned
    } catch (error: any) {
      // Clean up container on error if it exists
      if (container) {
        try {
          await container.remove({ force: true })
        } catch (removeError: any) {
          // Ignore removal errors
        }
      }
      logger.error(`Sysbench command failed: ${error.message}`)
      throw new Error(`Sysbench command failed: ${error.message}`)
    }
  }

  /**
   * Broadcast a progress frame carrying a just-finished stage's raw result.
   * Reuses the current status/progress so the StageRail is undisturbed; the
   * partial_result field fills the "results so far" strip in the live UI.
   */
  private _emitPartialResult(result: BenchmarkPartialResult) {
    const progress: BenchmarkProgress = {
      status: this.currentStatus,
      progress: this._getProgressPercent(this.currentStatus),
      message: this._getStageLabel(this.currentStatus),
      current_stage: this._getStageLabel(this.currentStatus),
      timestamp: new Date().toISOString(),
      stages: this.currentStages,
      stage_index: this.currentStages.findIndex((s) => s.status === this.currentStatus),
      stage_count: this.currentStages.length,
      partial_result: result,
    }

    transmit.broadcast(BROADCAST_CHANNELS.BENCHMARK_PROGRESS, {
      benchmark_id: this.currentBenchmarkId,
      ...progress,
    })
  }

  /**
   * Broadcast benchmark progress update
   */
  private _updateStatus(status: BenchmarkStatus, message: string) {
    this.currentStatus = status
    this.telemetry?.setStage(status)

    const progress: BenchmarkProgress = {
      status,
      progress: this._getProgressPercent(status),
      message,
      current_stage: this._getStageLabel(status),
      timestamp: new Date().toISOString(),
      stages: this.currentStages,
      stage_index: this.currentStages.findIndex((s) => s.status === status),
      stage_count: this.currentStages.length,
    }

    transmit.broadcast(BROADCAST_CHANNELS.BENCHMARK_PROGRESS, {
      benchmark_id: this.currentBenchmarkId,
      ...progress,
    })

    logger.info(`[BenchmarkService] ${status}: ${message}`)
  }

  /**
   * Get progress percentage for a given status
   */
  private _getProgressPercent(status: BenchmarkStatus): number {
    const progressMap: Record<BenchmarkStatus, number> = {
      idle: 0,
      starting: 5,
      detecting_hardware: 10,
      running_cpu: 25,
      running_memory: 40,
      running_disk_read: 55,
      running_disk_write: 70,
      downloading_ai_model: 80,
      running_ai: 85,
      calculating_score: 95,
      completed: 100,
      error: 0,
    }
    return progressMap[status] || 0
  }

  /**
   * Get human-readable stage label
   */
  private _getStageLabel(status: BenchmarkStatus): string {
    const labelMap: Record<BenchmarkStatus, string> = {
      idle: 'Idle',
      starting: 'Starting',
      detecting_hardware: 'Detecting Hardware',
      running_cpu: 'CPU Benchmark',
      running_memory: 'Memory Benchmark',
      running_disk_read: 'Disk Read Test',
      running_disk_write: 'Disk Write Test',
      downloading_ai_model: 'Downloading AI Model',
      running_ai: 'AI Inference Test',
      calculating_score: 'Calculating Score',
      completed: 'Complete',
      error: 'Error',
    }
    return labelMap[status] || status
  }
}

import transmit from '@adonisjs/transmit/services/main'
import si from 'systeminformation'
import logger from '@adonisjs/core/services/logger'
import { BROADCAST_CHANNELS } from '../../constants/broadcast.js'
import type { BenchmarkStatus, BenchmarkTelemetry } from '../../types/benchmark.js'

const SAMPLE_INTERVAL_MS = 1000

/**
 * Samples host telemetry (per-core CPU load, temperature, disk throughput) on a
 * timer and broadcasts it over SSE while a benchmark runs. Read-only: the sampler
 * runs in the orchestration process, never inside the sysbench container, so it
 * cannot influence the scored numbers.
 *
 * Signals come from `systeminformation`, which reads the host's /proc and /sys
 * (not namespaced for these counters), so this works from inside a container too.
 * Temperature legitimately isn't available on every host (VMs, some hwmon-less
 * boards) and is reported as null rather than faked.
 */
export class BenchmarkTelemetrySampler {
  private timer: NodeJS.Timeout | null = null
  private readonly benchmarkId: string | null
  private status: BenchmarkStatus = 'starting'
  private startedAt = Date.now()
  private stageMetric: BenchmarkTelemetry['stage_metric'] | undefined
  private gpu: BenchmarkTelemetry['gpu'] | undefined
  private sampling = false

  constructor(benchmarkId: string | null) {
    this.benchmarkId = benchmarkId
  }

  start() {
    if (this.timer) return
    this.startedAt = Date.now()
    // Prime systeminformation's per-second deltas and emit an initial frame,
    // then continue on the interval.
    void this._sample()
    this.timer = setInterval(() => void this._sample(), SAMPLE_INTERVAL_MS)
  }

  /** Tag subsequent frames with the current stage; clears any prior in-test state. */
  setStage(status: BenchmarkStatus) {
    this.status = status
    this.stageMetric = undefined
    this.gpu = undefined
  }

  /** Inject an in-test metric (e.g. live AI tokens/sec) into subsequent frames. */
  setStageMetric(kind: NonNullable<BenchmarkTelemetry['stage_metric']>['kind'], value: number, ttftMs?: number) {
    this.stageMetric = { kind, value, ...(ttftMs !== undefined ? { ttft_ms: ttftMs } : {}) }
  }

  /** Inject NVIDIA GPU stats into subsequent frames (null clears them). */
  setGpuStats(gpu: NonNullable<BenchmarkTelemetry['gpu']> | null) {
    this.gpu = gpu ?? undefined
  }

  stop() {
    if (this.timer) {
      clearInterval(this.timer)
      this.timer = null
    }
  }

  private async _sample() {
    // Skip if the previous sample is still in flight (currentLoad can take a
    // couple hundred ms); never let samples pile up.
    if (this.sampling) return
    this.sampling = true
    try {
      const [load, temp, fs] = await Promise.all([
        si.currentLoad().catch(() => null),
        si.cpuTemperature().catch(() => null),
        si.fsStats().catch(() => null),
      ])

      const overall = load ? Math.max(0, Math.round(load.currentLoad)) : 0
      const perCore = load?.cpus?.map((c) => Math.max(0, Math.round(c.load))) ?? []
      const tempC = temp && typeof temp.main === 'number' && temp.main > 0 ? Math.round(temp.main) : null
      const readMb = fs && typeof fs.rx_sec === 'number' && fs.rx_sec >= 0 ? Number((fs.rx_sec / 1e6).toFixed(1)) : 0
      const writeMb = fs && typeof fs.wx_sec === 'number' && fs.wx_sec >= 0 ? Number((fs.wx_sec / 1e6).toFixed(1)) : 0

      const payload: BenchmarkTelemetry = {
        benchmark_id: this.benchmarkId,
        status: this.status,
        t: Date.now() - this.startedAt,
        cpu: { overall, per_core: perCore },
        temp_c: tempC,
        disk: { read_mb_s: readMb, write_mb_s: writeMb },
        ...(this.stageMetric ? { stage_metric: this.stageMetric } : {}),
        ...(this.gpu ? { gpu: this.gpu } : {}),
      }

      transmit.broadcast(BROADCAST_CHANNELS.BENCHMARK_TELEMETRY, payload)
    } catch (err) {
      logger.debug(`[BenchmarkTelemetry] sample failed: ${err.message}`)
    } finally {
      this.sampling = false
    }
  }
}

import ChatSession from '#models/chat_session'
import ChatMessage from '#models/chat_message'
import KVStore from '#models/kv_store'
import logger from '@adonisjs/core/services/logger'
import { DateTime } from 'luxon'
import { inject } from '@adonisjs/core'
import { OllamaService } from './ollama_service.js'
import { SYSTEM_PROMPTS } from '../../constants/ollama.js'
import { toTitleCase } from '../utils/misc.js'
import { resolveTasksModel } from '../utils/tasks_model.js'
import {
  SUGGESTIONS_SCHEMA,
  TITLE_SCHEMA,
  pickSuggestions,
  pickTitle,
  resolveStructured,
} from '../utils/structured_output.js'
import type { ChatSource } from '../../types/chat.js'

/** Sidebar width, near enough. Applied once, to whichever candidate title won. */
const TITLE_MAX_LENGTH = 57

function truncateTitle(value: string): string {
  return value.length > TITLE_MAX_LENGTH ? value.slice(0, TITLE_MAX_LENGTH) + '...' : value
}

@inject()
export class ChatService {
  constructor(private ollamaService: OllamaService) {}

  /**
   * The model to use for ancillary work — chat titles and chat suggestions.
   *
   * Prefers the user's `ai.tasksModel` setting so a 30B reasoning model isn't
   * spending seconds "thinking" to produce a three-word sidebar title. Falls
   * back to `fallback` when the setting is unset (the default, which preserves
   * the previous behaviour) or when the configured model is no longer
   * installed. `installed` is passed in by callers that already listed models,
   * to avoid a second round-trip.
   */
  private async resolveTasksModel(
    fallback: string | null,
    installed?: { name: string }[]
  ): Promise<string | null> {
    return resolveTasksModel(this.ollamaService, fallback, installed, '[ChatService]')
  }

  async getAllSessions() {
    try {
      const sessions = await ChatSession.query().orderBy('updated_at', 'desc')
      return sessions.map((session) => ({
        id: session.id.toString(),
        title: session.title,
        model: session.model,
        timestamp: session.updated_at.toJSDate(),
        lastMessage: null, // Will be populated from messages if needed
      }))
    } catch (error) {
      logger.error(
        `[ChatService] Failed to get sessions: ${error instanceof Error ? error.message : error}`
      )
      return []
    }
  }

  async getChatSuggestions() {
    try {
      const models = await this.ollamaService.getModels()
      if (!models || models.length === 0) {
        return [] // If no models are available, return empty suggestions
      }

      // The user's dedicated tasks model wins when set — suggestions are short
      // aesthetic prompts that don't benefit from a flagship model. Otherwise
      // prefer the user's selected chat model, and fall back to the smallest
      // installed model — picking the largest by file size is unsafe: if any
      // installed model exceeds available VRAM (e.g. llama3.1:405b on a 96 GB
      // GPU), Ollama spends minutes trying to load it and the request 500s.
      const lastModel = await KVStore.getValue('chat.lastModel')
      const preferred = lastModel ? models.find((m) => m.name === lastModel) : undefined
      const chosen =
        preferred ??
        models.reduce((prev, current) => (prev.size < current.size ? prev : current))

      if (!chosen) {
        return []
      }

      const model = (await this.resolveTasksModel(chosen.name, models)) ?? chosen.name

      // Suggestions are a formatting task, not a reasoning one. A reasoning tasks model
      // would spend the whole response thinking and leave nothing to parse, so suppress
      // it at the source; `thinkingCapable` is what lets the compat transport pick
      // reasoning_effort:'none' rather than sending nothing. Memoized per model name.
      const thinkingCapable = await this.ollamaService.checkModelHasThinking(model)

      const response = await this.ollamaService.chat({
        model,
        messages: [
          {
            role: 'user',
            content: SYSTEM_PROMPTS.chat_suggestions,
          }
        ],
        stream: false,
        think: false,
        thinkingCapable,
        // Grammar-constrained on the native transport, so the response is three
        // strings in an array rather than whatever prose the model felt like.
        format: SUGGESTIONS_SCHEMA,
        // The default of 0.8 is actively hostile to format stability, and there is
        // nothing creative about picking three canned opening questions.
        temperature: 0,
      })

      if (response && response.message && response.message.content) {
        const content = response.message.content.trim()

        const structured = resolveStructured(content, pickSuggestions, response.structured === true)
        if (structured.ok) {
          return structured.value.map((s) => toTitleCase(s))
        }
        if (structured.reason === 'constrained-parse-failed') {
          // The grammar was applied and the model broke it anyway, so what came back
          // is a broken JSON object rather than prose. Splitting that on commas would
          // surface `{"suggestions": ["How Do I` as a chip. No chips is the better
          // failure — they are decorative, and the empty state is already designed.
          logger.warn(
            `[ChatService] Model "${model}" broke the suggestion grammar; returning no suggestions`
          )
          return []
        }
        logger.warn(
          `[ChatService] Model "${model}" returned no suggestion JSON; falling back to text parsing`
        )

        // Handle both comma-separated and newline-separated formats
        let suggestions: string[] = []

        // Try splitting by commas first
        if (content.includes(',')) {
          suggestions = content.split(',').map((s) => s.trim())
        } 
        // Fall back to newline separation
        else {
          suggestions = content
            .split(/\r?\n/)
            .map((s) => s.trim())
            // Remove numbered list markers (1., 2., 3., etc.) and bullet points
            .map((s) => s.replace(/^\d+\.\s*/, '').replace(/^[-*•]\s*/, ''))
            // Remove surrounding quotes if present
            .map((s) => s.replace(/^["']|["']$/g, ''))
        }

        // Filter out empty strings and limit to 3 suggestions
        const filtered =  suggestions
          .filter((s) => s.length > 0)
          .slice(0, 3)

        return filtered.map((s) => toTitleCase(s))
      } else {
        // Empty content after the <think> split means the model produced reasoning and
        // nothing else. Log it rather than silently returning no chips.
        logger.warn(`[ChatService] Model "${model}" returned no usable suggestion text`)
        return []
      }
    } catch (error) {
      logger.error(
        `[ChatService] Failed to get chat suggestions: ${
          error instanceof Error ? error.message : error
        }`
      )
      return []
    }
  }

  async getSession(sessionId: number) {
    try {
      const session = await ChatSession.query().where('id', sessionId).preload('messages').first()

      if (!session) {
        return null
      }

      return {
        id: session.id.toString(),
        title: session.title,
        model: session.model,
        timestamp: session.updated_at.toJSDate(),
        messages: session.messages.map((msg) => ({
          id: msg.id.toString(),
          role: msg.role,
          content: msg.content,
          timestamp: msg.created_at.toJSDate(),
          sources: msg.sources ? JSON.parse(msg.sources) : undefined,
        })),
      }
    } catch (error) {
      logger.error(
        `[ChatService] Failed to get session ${sessionId}: ${
          error instanceof Error ? error.message : error
        }`
      )
      return null
    }
  }

  async createSession(title: string, model?: string) {
    try {
      const session = await ChatSession.create({
        title,
        model: model || null,
      })

      return {
        id: session.id.toString(),
        title: session.title,
        model: session.model,
        timestamp: session.created_at.toJSDate(),
      }
    } catch (error) {
      logger.error(
        `[ChatService] Failed to create session: ${error instanceof Error ? error.message : error}`
      )
      throw new Error('Failed to create chat session')
    }
  }

  async updateSession(sessionId: number, data: { title?: string; model?: string }) {
    try {
      const session = await ChatSession.findOrFail(sessionId)

      if (data.title) {
        session.title = data.title
      }
      if (data.model !== undefined) {
        session.model = data.model
      }

      await session.save()

      return {
        id: session.id.toString(),
        title: session.title,
        model: session.model,
        timestamp: session.updated_at.toJSDate(),
      }
    } catch (error) {
      logger.error(
        `[ChatService] Failed to update session ${sessionId}: ${
          error instanceof Error ? error.message : error
        }`
      )
      throw new Error('Failed to update chat session')
    }
  }

  async addMessage(
    sessionId: number,
    role: 'system' | 'user' | 'assistant',
    content: string,
    sources?: ChatSource[]
  ) {
    try {
      const message = await ChatMessage.create({
        session_id: sessionId,
        role,
        content,
        sources: sources && sources.length > 0 ? JSON.stringify(sources) : null,
      })

      // Update session's updated_at timestamp
      const session = await ChatSession.findOrFail(sessionId)
      session.updated_at = DateTime.now()
      await session.save()

      return {
        id: message.id.toString(),
        role: message.role,
        content: message.content,
        timestamp: message.created_at.toJSDate(),
        sources: sources && sources.length > 0 ? sources : undefined,
      }
    } catch (error) {
      logger.error(
        `[ChatService] Failed to add message to session ${sessionId}: ${
          error instanceof Error ? error.message : error
        }`
      )
      throw new Error('Failed to add message')
    }
  }

  async deleteSession(sessionId: number) {
    try {
      const session = await ChatSession.findOrFail(sessionId)
      await session.delete()
      return { success: true }
    } catch (error) {
      logger.error(
        `[ChatService] Failed to delete session ${sessionId}: ${
          error instanceof Error ? error.message : error
        }`
      )
      throw new Error('Failed to delete chat session')
    }
  }

  async getMessageCount(sessionId: number): Promise<number> {
    try {
      const count = await ChatMessage.query().where('session_id', sessionId).count('* as total')
      return Number(count[0].$extras.total)
    } catch (error) {
      logger.error(
        `[ChatService] Failed to get message count for session ${sessionId}: ${error instanceof Error ? error.message : error}`
      )
      return 0
    }
  }

  async generateTitle(sessionId: number, userMessage: string, assistantMessage: string, model: string) {
    try {
      // Titles are aesthetic work; route them to the tasks model when one is
      // configured rather than the chat model that just answered.
      const titleModel = (await this.resolveTasksModel(model)) ?? model

      // Naming a chat needs no reasoning; see the note in getChatSuggestions.
      const thinkingCapable = await this.ollamaService.checkModelHasThinking(titleModel)

      const response = await this.ollamaService.chat({
        model: titleModel,
        messages: [
          { role: 'system', content: SYSTEM_PROMPTS.title_generation },
          { role: 'user', content: userMessage },
          { role: 'assistant', content: assistantMessage },
        ],
        think: false,
        thinkingCapable,
        format: TITLE_SCHEMA,
        // See the note on suggestions: naming a chat is not a creative task, and
        // the backend default of 0.8 makes the format wobble.
        temperature: 0,
      })

      const content = response?.message?.content?.trim() ?? ''
      const structured = resolveStructured(content, pickTitle, response?.structured === true)

      let title: string
      if (!content) {
        // Nothing left once reasoning was split out. Checked before the grammar branch
        // so the log says what actually happened rather than blaming the schema.
        logger.warn(
          `[ChatService] Model "${titleModel}" returned no usable title text; using the user message`
        )
        title = userMessage
      } else if (structured.ok) {
        title = structured.value
      } else if (structured.reason === 'constrained-parse-failed') {
        // A truncated object would otherwise be stored verbatim, leaving `{"title": ...`
        // in the sidebar. The user's own words are a worse title than the model's but a
        // far better one than a JSON fragment.
        logger.warn(
          `[ChatService] Model "${titleModel}" broke the title grammar; using the user message`
        )
        title = userMessage
      } else {
        // Unconstrained backend: the response is meant to be the bare title.
        title = content
      }

      if (!title) {
        // An unconstrained response that was pure punctuation or whitespace.
        logger.warn(
          `[ChatService] Model "${titleModel}" returned no usable title text; using the user message`
        )
        title = userMessage
      }

      // Applied once, to whichever string won: "under 50 characters" is a request the
      // model can ignore on the schema path and the text path alike.
      title = truncateTitle(title)

      await this.updateSession(sessionId, { title })
      logger.info(`[ChatService] Generated title for session ${sessionId}: "${title}"`)
    } catch (error) {
      logger.error(
        `[ChatService] Failed to generate title for session ${sessionId}: ${error instanceof Error ? error.message : error}`
      )
      // Fall back to truncated user message
      try {
        await this.updateSession(sessionId, { title: truncateTitle(userMessage) })
      } catch {
        // Silently fail - session keeps "New Chat" title
      }
    }
  }

  async deleteAllSessions() {
    try {
      await ChatSession.query().delete()
      return { success: true, message: 'All chat sessions deleted' }
    } catch (error) {
      logger.error(
        `[ChatService] Failed to delete all sessions: ${
          error instanceof Error ? error.message : error
        }`
      )
      throw new Error('Failed to delete all chat sessions')
    }
  }
}

import axios from 'axios'
import vine from '@vinejs/vine'
import logger from '@adonisjs/core/services/logger'
import { DateTime } from 'luxon'
import { join } from 'path'
import CollectionManifest from '#models/collection_manifest'
import InstalledResource from '#models/installed_resource'
import WikipediaSelection from '#models/wikipedia_selection'
import { QueueService } from './queue_service.js'
import { RunDownloadJob } from '#jobs/run_download_job'
import { zimCategoriesSpecSchema, mapsSpecSchema, wikipediaSpecSchema, creatorPacksSpecSchema } from '#validators/curated_collections'
import { isGatedResource } from '../utils/hosted_content.js'
import {
  ensureDirectoryExists,
  listDirectoryContents,
  getFileStatsIfExists,
  ZIM_STORAGE_PATH,
} from '../utils/fs.js'
import type {
  ManifestType,
  ZimCategoriesSpec,
  MapsSpec,
  CreatorPacksSpec,
  CategoryWithStatus,
  CollectionWithStatus,
  CreatorPackWithStatus,
  SpecResource,
  SpecTier,
} from '../../types/collections.js'

const SPEC_URLS: Record<ManifestType, string> = {
  zim_categories: 'https://raw.githubusercontent.com/Crosstalk-Solutions/project-nomad/refs/heads/main/collections/kiwix-categories.json',
  maps: 'https://github.com/Crosstalk-Solutions/project-nomad/raw/refs/heads/main/collections/maps.json',
  wikipedia: 'https://raw.githubusercontent.com/Crosstalk-Solutions/project-nomad/refs/heads/main/collections/wikipedia.json',
  creator_packs: 'https://raw.githubusercontent.com/Crosstalk-Solutions/project-nomad/refs/heads/main/collections/creator-packs.json',
}

const VALIDATORS: Record<ManifestType, any> = {
  zim_categories: zimCategoriesSpecSchema,
  maps: mapsSpecSchema,
  wikipedia: wikipediaSpecSchema,
  creator_packs: creatorPacksSpecSchema,
}

export class CollectionManifestService {
  private readonly mapStoragePath = '/storage/maps'

  // ---- Spec management ----

  async fetchAndCacheSpec(type: ManifestType): Promise<boolean> {
    try {
      const response = await axios.get(SPEC_URLS[type], { timeout: 15000 })

      const validated = await vine.validate({
        schema: VALIDATORS[type],
        data: response.data,
      })

      const existing = await CollectionManifest.find(type)
      const specVersion = validated.spec_version

      if (existing) {
        const changed = existing.spec_version !== specVersion
        existing.spec_version = specVersion
        existing.spec_data = validated
        existing.fetched_at = DateTime.now()
        await existing.save()
        return changed
      }

      await CollectionManifest.create({
        type,
        spec_version: specVersion,
        spec_data: validated,
        fetched_at: DateTime.now(),
      })

      return true
    } catch (error) {
      logger.error(`[CollectionManifestService] Failed to fetch spec for ${type}:`, error?.message || error)
      return false
    }
  }

  async getCachedSpec<T>(type: ManifestType): Promise<T | null> {
    const manifest = await CollectionManifest.find(type)
    if (!manifest) return null
    return manifest.spec_data as T
  }

  async getSpecWithFallback<T>(type: ManifestType): Promise<T | null> {
    try {
      await this.fetchAndCacheSpec(type)
    } catch {
      // Fetch failed, will fall back to cache
    }
    return this.getCachedSpec<T>(type)
  }

  // ---- Status computation ----

  async getCategoriesWithStatus(): Promise<CategoryWithStatus[]> {
    const spec = await this.getSpecWithFallback<ZimCategoriesSpec>('zim_categories')
    if (!spec) return []

    // Include 'dataset' rows alongside 'zim' so a curated tier carrying the FDA
    // drug dataset reads "installed" once the ingest writes its row (the tier-
    // status math below treats every resolved resource id uniformly — a dataset
    // resource is just another id to account for).
    const installedResources = await InstalledResource.query().whereIn('resource_type', [
      'zim',
      'dataset',
    ])
    const installedMap = new Map(installedResources.map((r) => [r.resource_id, r]))

    // In-flight ZIM + dataset download resource IDs from the BullMQ queues. Used
    // to surface the user's tier intent immediately on submit, before any single
    // file has finished downloading. Failed jobs are excluded so a stuck queue
    // entry doesn't keep claiming the user's pick forever.
    const inFlightIds = await this.getInFlightZimResourceIds()

    // Whether the in-flight drug dataset is in its INGEST (indexing) phase — the
    // download finished and the heavy ingest is running. Lets the wizard card
    // flip "(downloading)" → "(indexing)" at the handoff (Req 7) instead of
    // showing a stale "downloading" through the long index.
    const drugIndexing = await this.isDrugDatasetIndexing()

    return spec.categories.map((category) => {
      const installedTierSlug = this.getInstalledTierForCategory(category.tiers, installedMap)
      const downloadingTierSlug = this.getDownloadingTierForCategory(
        category.tiers,
        installedMap,
        inFlightIds,
        installedTierSlug
      )
      // Only mark "indexing" when this category's downloading tier actually
      // carries a dataset resource that is the one indexing.
      const downloadingTierIndexing =
        drugIndexing && downloadingTierSlug
          ? CollectionManifestService.resolveTierResources(
              category.tiers.find((t) => t.slug === downloadingTierSlug)!,
              category.tiers
            ).some((r) => r.type === 'dataset')
          : false
      return { ...category, installedTierSlug, downloadingTierSlug, downloadingTierIndexing }
    })
  }

  /**
   * True when the FDA drug dataset's INGEST is in flight while its DOWNLOAD is
   * not — i.e. the handoff into the indexing phase. Drives the wizard card's
   * "(indexing)" label. Defensive: any queue read failure returns false (the card
   * just keeps showing "(downloading)") rather than breaking the categories list.
   */
  private async isDrugDatasetIndexing(): Promise<boolean> {
    try {
      const { DownloadDrugDataJob } = await import('#jobs/download_drug_data_job')
      const { IngestDrugDataJob } = await import('#jobs/ingest_drug_data_job')
      const queueService = QueueService.getInstance()

      const ingestQueue = queueService.getQueue(IngestDrugDataJob.queue)
      const ingestJobs = await ingestQueue.getJobs(['active', 'waiting', 'delayed'])
      if (ingestJobs.length === 0) return false

      const downloadQueue = queueService.getQueue(DownloadDrugDataJob.queue)
      const downloadJobs = await downloadQueue.getJobs(['active', 'waiting', 'delayed'])
      return downloadJobs.length === 0
    } catch (error: any) {
      logger.warn(
        '[CollectionManifestService] Could not determine drug indexing state:',
        error?.message || error
      )
      return false
    }
  }

  private async getInFlightZimResourceIds(): Promise<Set<string>> {
    const ids = new Set<string>()
    try {
      const queue = QueueService.getInstance().getQueue(RunDownloadJob.queue)
      const jobs = await queue.getJobs(['waiting', 'active', 'delayed'])
      for (const job of jobs) {
        if (job.data?.filetype !== 'zim') continue
        const resourceId = job.data?.resourceMetadata?.resource_id
        if (typeof resourceId === 'string') ids.add(resourceId)
      }
    } catch (error) {
      // Don't fail the whole categories endpoint if the queue is briefly
      // unreachable — just report no in-flight downloads.
      logger.warn('[CollectionManifestService] Could not read download queue:', error?.message || error)
    }

    // Also surface an in-flight curated-tier drug-dataset install. The drug
    // download/ingest run on their own queues (not RunDownloadJob), carrying the
    // dataset's resource id in resourceMeta — read it so the wizard shows the
    // Medicine tier as "downloading" the moment the user opts in, mirroring the
    // ZIM behaviour. Scanned independently so a missing drug queue can't blank
    // the ZIM in-flight set above.
    await this.addInFlightDrugDatasetId(ids)

    return ids
  }

  /**
   * Add the FDA drug dataset's manifest resource id to `ids` when its download or
   * ingest is in flight. The dataset only counts as "downloading" while no
   * install-state row exists yet — once ingest writes the row it is "installed"
   * (handled by the installedMap), so a still-running ingest correctly reads as
   * the in-flight tier intent here. resourceMeta is only present on a curated-tier
   * install, so a manual (non-tier) drug download never claims a tier slug.
   */
  private async addInFlightDrugDatasetId(ids: Set<string>): Promise<void> {
    try {
      const { DownloadDrugDataJob } = await import('#jobs/download_drug_data_job')
      const { IngestDrugDataJob } = await import('#jobs/ingest_drug_data_job')
      const queueService = QueueService.getInstance()
      for (const queueName of [DownloadDrugDataJob.queue, IngestDrugDataJob.queue]) {
        const queue = queueService.getQueue(queueName)
        const jobs = await queue.getJobs(['waiting', 'active', 'delayed'])
        for (const job of jobs) {
          const resourceId = job.data?.resourceMeta?.resourceId
          if (typeof resourceId === 'string') ids.add(resourceId)
        }
      }
    } catch (error: any) {
      logger.warn(
        '[CollectionManifestService] Could not read drug dataset queue:',
        error?.message || error
      )
    }
  }

  /**
   * Highest tier whose every resource is installed OR has an in-flight
   * download. Returns undefined when there are no in-flight downloads for this
   * category, or when the result would just duplicate installedTierSlug (i.e.
   * everything that's downloading is already installed — nothing new to show).
   */
  getDownloadingTierForCategory(
    tiers: SpecTier[],
    installedMap: Map<string, InstalledResource>,
    inFlightIds: Set<string>,
    installedTierSlug: string | undefined
  ): string | undefined {
    if (inFlightIds.size === 0) return undefined

    // Cheap pre-check: any of this category's resources actually in flight?
    const anyInFlight = tiers.some((tier) =>
      CollectionManifestService.resolveTierResources(tier, tiers).some((r) => inFlightIds.has(r.id))
    )
    if (!anyInFlight) return undefined

    const reversedTiers = [...tiers].reverse()
    for (const tier of reversedTiers) {
      const resolved = CollectionManifestService.resolveTierResources(tier, tiers)
      if (resolved.length === 0) continue
      const allAccountedFor = resolved.every(
        (r) => installedMap.has(r.id) || inFlightIds.has(r.id)
      )
      if (allAccountedFor) {
        return tier.slug === installedTierSlug ? undefined : tier.slug
      }
    }
    return undefined
  }

  async getMapCollectionsWithStatus(): Promise<CollectionWithStatus[]> {
    const spec = await this.getSpecWithFallback<MapsSpec>('maps')
    if (!spec) return []

    const installedResources = await InstalledResource.query().where('resource_type', 'map')
    const installedIds = new Set(installedResources.map((r) => r.resource_id))

    return spec.collections.map((collection) => {
      const installedCount = collection.resources.filter((r) => installedIds.has(r.id)).length
      return {
        ...collection,
        all_installed: installedCount === collection.resources.length,
        installed_count: installedCount,
        total_count: collection.resources.length,
      }
    })
  }

  /**
   * Per-pack install status for Creator Packs. Packs are single ZIMs, so this is
   * a one-resource-per-pack join (simpler than the tiered category logic):
   * catalog ⋈ InstalledResource (resource_type 'zim', matched on resource_id) ⋈
   * the in-flight download queue. `available_update_version` is set when an
   * installed pack's version trails the catalog (a creator published a rebuild).
   */
  async getCreatorPacksWithStatus(): Promise<CreatorPackWithStatus[]> {
    const spec = await this.getSpecWithFallback<CreatorPacksSpec>('creator_packs')
    if (!spec) return []

    const installedResources = await InstalledResource.query().where('resource_type', 'zim')
    const installedMap = new Map(installedResources.map((r) => [r.resource_id, r]))
    const inFlightIds = await this.getInFlightZimResourceIds()

    return spec.packs.map((pack) => {
      const installed = installedMap.get(pack.resource_id)
      if (installed) {
        const hasUpdate = installed.version !== pack.version
        return {
          ...pack,
          status: 'installed' as const,
          installed_version: installed.version,
          ...(hasUpdate ? { available_update_version: pack.version } : {}),
        }
      }
      if (inFlightIds.has(pack.resource_id)) {
        return { ...pack, status: 'downloading' as const }
      }
      return { ...pack, status: 'available' as const }
    })
  }

  /**
   * Resource ids in the ZIM manifest that we host ourselves behind the
   * entitlement Worker (`auth: 'nomad_app_key'`).
   *
   * Used to keep gated content out of the Kiwix-catalog update path. Those
   * resources are not in the openzim catalog, so they can never legitimately
   * match there — but a resource-id collision would otherwise let a third-party
   * mirror present itself as a newer version and overwrite our content. Their
   * versions come from the manifest instead.
   *
   * Reads the CACHED spec rather than refetching: this sits on the scheduled
   * update-check path and does not need a network round-trip. A gated resource
   * cannot be installed without the manifest having been fetched first, so the
   * cache is always populated by the time it matters.
   *
   * Returns an empty set if the manifest has never been cached, which correctly
   * degrades to current behaviour rather than skipping every update.
   */
  async getGatedZimResourceIds(): Promise<Set<string>> {
    const ids = new Set<string>()
    const spec = await this.getCachedSpec<ZimCategoriesSpec>('zim_categories')
    if (!spec) return ids

    for (const category of spec.categories) {
      for (const tier of category.tiers) {
        for (const resource of tier.resources) {
          if (isGatedResource(resource)) ids.add(resource.id)
        }
      }
    }
    return ids
  }

  // ---- Tier resolution ----

  static resolveTierResources(tier: SpecTier, allTiers: SpecTier[]): SpecResource[] {
    const visited = new Set<string>()
    return CollectionManifestService._resolveTierResourcesInner(tier, allTiers, visited)
  }

  private static _resolveTierResourcesInner(
    tier: SpecTier,
    allTiers: SpecTier[],
    visited: Set<string>
  ): SpecResource[] {
    if (visited.has(tier.slug)) return [] // cycle detection
    visited.add(tier.slug)

    const resources: SpecResource[] = []

    if (tier.includesTier) {
      const included = allTiers.find((t) => t.slug === tier.includesTier)
      if (included) {
        resources.push(...CollectionManifestService._resolveTierResourcesInner(included, allTiers, visited))
      }
    }

    resources.push(...tier.resources)
    return resources
  }

  getInstalledTierForCategory(
    tiers: SpecTier[],
    installedMap: Map<string, InstalledResource>
  ): string | undefined {
    // Check from highest tier to lowest (tiers are ordered low to high in spec)
    const reversedTiers = [...tiers].reverse()

    for (const tier of reversedTiers) {
      const resolved = CollectionManifestService.resolveTierResources(tier, tiers)
      if (resolved.length === 0) continue

      const allInstalled = resolved.every((r) => installedMap.has(r.id))
      if (allInstalled) {
        return tier.slug
      }
    }

    return undefined
  }

  // ---- Filename parsing ----

  static parseZimFilename(filename: string): { resource_id: string; version: string } | null {
    const name = filename.replace(/\.zim$/, '')
    const match = name.match(/^(.+)_(\d{4}-\d{2})$/)
    if (!match) return null
    return { resource_id: match[1], version: match[2] }
  }

  static parseMapFilename(filename: string): { resource_id: string; version: string } | null {
    const name = filename.replace(/\.pmtiles$/, '')
    const match = name.match(/^(.+)_(\d{4}-\d{2})$/)
    if (!match) return null
    return { resource_id: match[1], version: match[2] }
  }

  // ---- Filesystem reconciliation ----

  async reconcileFromFilesystem(): Promise<{ zim: number; map: number }> {
    let zimCount = 0
    let mapCount = 0

    console.log("RECONCILING FILESYSTEM MANIFESTS...")

    // Reconcile ZIM files
    try {
      const zimDir = join(process.cwd(), ZIM_STORAGE_PATH)
      await ensureDirectoryExists(zimDir)
      const zimItems = await listDirectoryContents(zimDir)
      const zimFiles = zimItems.filter((f) => f.name.endsWith('.zim'))

      console.log(`Found ${zimFiles.length} ZIM files on disk. Reconciling with database...`)

      // Get spec for URL lookup
      const zimSpec = await this.getCachedSpec<ZimCategoriesSpec>('zim_categories')
      const specResourceMap = new Map<string, SpecResource>()
      if (zimSpec) {
        for (const cat of zimSpec.categories) {
          for (const tier of cat.tiers) {
            for (const res of tier.resources) {
              specResourceMap.set(res.id, res)
            }
          }
        }
      }

      const seenZimIds = new Set<string>()

      // Only skip the single Wikipedia file tracked by WikipediaSelection — not every file
      // starting with `wikipedia_en_`. Curated category tiers (e.g. Medicine → Comprehensive)
      // ship Wikipedia-themed ZIMs like `wikipedia_en_medicine_maxi` that must reconcile
      // normally; otherwise their InstalledResource row gets wiped on every restart and the
      // tier detection silently downgrades.
      const wikipediaSelection = await WikipediaSelection.query().first()
      const managedWikipediaFilename = wikipediaSelection?.filename ?? null

      for (const file of zimFiles) {
        console.log(`Processing ZIM file: ${file.name}`)
        if (managedWikipediaFilename && file.name === managedWikipediaFilename) continue

        const parsed = CollectionManifestService.parseZimFilename(file.name)
        console.log(`Parsed ZIM filename:`, parsed)
        if (!parsed) continue

        seenZimIds.add(parsed.resource_id)

        const specRes = specResourceMap.get(parsed.resource_id)
        const filePath = join(zimDir, file.name)
        const stats = await getFileStatsIfExists(filePath)

        await InstalledResource.updateOrCreate(
          { resource_id: parsed.resource_id, resource_type: 'zim' },
          {
            version: parsed.version,
            url: specRes?.url || '',
            file_path: filePath,
            file_size_bytes: stats ? Number(stats.size) : null,
            installed_at: DateTime.now(),
          }
        )
        zimCount++
      }

      // Remove entries for ZIM files no longer on disk
      const existingZim = await InstalledResource.query().where('resource_type', 'zim')
      for (const entry of existingZim) {
        if (!seenZimIds.has(entry.resource_id)) {
          await entry.delete()
        }
      }
    } catch (error) {
      logger.error('[CollectionManifestService] Error reconciling ZIM files:', error)
    }

    // Reconcile map files
    try {
      const mapDir = join(process.cwd(), this.mapStoragePath, 'pmtiles')
      await ensureDirectoryExists(mapDir)
      const mapItems = await listDirectoryContents(mapDir)
      const mapFiles = mapItems.filter((f) => f.name.endsWith('.pmtiles'))

      // Get spec for URL/version lookup
      const mapSpec = await this.getCachedSpec<MapsSpec>('maps')
      const mapResourceMap = new Map<string, SpecResource>()
      if (mapSpec) {
        for (const col of mapSpec.collections) {
          for (const res of col.resources) {
            mapResourceMap.set(res.id, res)
          }
        }
      }

      const seenMapIds = new Set<string>()

      for (const file of mapFiles) {
        const parsed = CollectionManifestService.parseMapFilename(file.name)
        if (!parsed) continue

        seenMapIds.add(parsed.resource_id)

        const specRes = mapResourceMap.get(parsed.resource_id)
        const filePath = join(mapDir, file.name)
        const stats = await getFileStatsIfExists(filePath)

        await InstalledResource.updateOrCreate(
          { resource_id: parsed.resource_id, resource_type: 'map' },
          {
            version: parsed.version,
            url: specRes?.url || '',
            file_path: filePath,
            file_size_bytes: stats ? Number(stats.size) : null,
            installed_at: DateTime.now(),
          }
        )
        mapCount++
      }

      // Remove entries for map files no longer on disk
      const existingMaps = await InstalledResource.query().where('resource_type', 'map')
      for (const entry of existingMaps) {
        if (!seenMapIds.has(entry.resource_id)) {
          await entry.delete()
        }
      }
    } catch (error) {
      logger.error('[CollectionManifestService] Error reconciling map files:', error)
    }

    logger.info(`[CollectionManifestService] Reconciled ${zimCount} ZIM files, ${mapCount} map files`)
    return { zim: zimCount, map: mapCount }
  }
}

import logger from '@adonisjs/core/services/logger'
import axios from 'axios'
import { DateTime } from 'luxon'
import InstalledResource from '#models/installed_resource'
import { RunDownloadJob } from '../jobs/run_download_job.js'
import { ZIM_STORAGE_PATH } from '../utils/fs.js'
import { join } from 'path'
import type {
  ResourceUpdateInfo,
  ContentUpdateCheckResult,
} from '../../types/collections.js'
import { KiwixCatalogService, reconcileResourceUpdateState } from './kiwix_catalog_service.js'
import { CollectionManifestService } from './collection_manifest_service.js'

const MAP_STORAGE_PATH = '/storage/maps'

const ZIM_MIME_TYPES = ['application/x-zim', 'application/x-openzim', 'application/octet-stream']
const PMTILES_MIME_TYPES = ['application/vnd.pmtiles', 'application/octet-stream']

export class CollectionUpdateService {
  /**
   * Check every installed resource against the upstream catalogs locally (Kiwix
   * OPDS for ZIMs, GitHub for maps) — no longer routed through the external
   * project-nomad-api. Side-effect: persists each resource's available-update
   * state (version + cool-off anchor) so the auto-updater can act on it later.
   */
  async checkForUpdates(): Promise<ContentUpdateCheckResult> {
    // ZIM/map catalog update path only — exclude `dataset` resources (e.g. the
    // FDA drug labels), which are not filename-versioned and get their own
    // freshness path. No-op today (no dataset rows are written in this slice).
    const allInstalled = await InstalledResource.query().whereNot('resource_type', 'dataset')

    // Content we host ourselves is versioned by the manifest, not by the Kiwix
    // catalog, so it has no business in this check. Excluding it also means a
    // resource-id collision can't let a third-party mirror present itself as a
    // newer version and overwrite our content. See resolveZimDownload, which
    // pins the same resources to their manifest URL on the install path.
    const gatedIds = await new CollectionManifestService().getGatedZimResourceIds()
    const installed = allInstalled.filter(
      (r) => !(r.resource_type === 'zim' && gatedIds.has(r.resource_id))
    )

    if (installed.length === 0) {
      return {
        updates: [],
        checked_at: new Date().toISOString(),
      }
    }

    try {
      const catalog = new KiwixCatalogService()
      const latestByKey = await catalog.getLatestForResources(
        // `dataset` rows are filtered out above, so the type narrows to ZIM/map.
        installed.map((r) => ({
          resource_id: r.resource_id,
          resource_type: r.resource_type as 'zim' | 'map',
        }))
      )

      const now = DateTime.now()
      const updates: ResourceUpdateInfo[] = []
      for (const resource of installed) {
        const latest = latestByKey.get(`${resource.resource_type}:${resource.resource_id}`) ?? null
        await reconcileResourceUpdateState(resource, latest, now)

        if (latest && latest.version > resource.version) {
          updates.push({
            resource_id: resource.resource_id,
            resource_type: resource.resource_type as 'zim' | 'map',
            installed_version: resource.version,
            latest_version: latest.version,
            download_url: latest.download_url,
            size_bytes: latest.size_bytes || undefined,
          })
        }
      }

      logger.info(
        `[CollectionUpdateService] Local update check complete: ${updates.length} update(s) available`
      )

      const enriched = await this.enrichWithSizes(updates)
      return {
        updates: enriched,
        checked_at: new Date().toISOString(),
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error during update check'
      logger.error(`[CollectionUpdateService] Failed to check for updates: ${message}`)
      return {
        updates: [],
        checked_at: new Date().toISOString(),
        error: 'Failed to check for content updates. Please try again later.',
      }
    }
  }

  async applyUpdate(
    update: ResourceUpdateInfo,
    options?: { auto?: boolean }
  ): Promise<{ success: boolean; jobId?: string; error?: string }> {
    // Only block when a download is genuinely in progress. getActiveByUrl
    // removes any terminal (failed/completed) job for this URL first, so a
    // previous failed attempt doesn't leave a stale job that blocks the
    // re-dispatch below. Using the raw getByUrl here (unlike every other
    // dispatch site) meant a failed download stuck the resource forever: the
    // failed job survived under the deterministic jobId, dispatch hit "job
    // already exists" and returned it, and applyUpdate reported success while
    // nothing was re-downloaded.
    const existingJob = await RunDownloadJob.getActiveByUrl(update.download_url)
    if (existingJob) {
      return {
        success: false,
        error: `A download is already in progress for ${update.resource_id}`,
      }
    }

    const filename = this.buildFilename(update)
    const filepath = this.buildFilepath(update, filename)

    const result = await RunDownloadJob.dispatch({
      url: update.download_url,
      filepath,
      timeout: 30000,
      allowedMimeTypes:
        update.resource_type === 'zim' ? ZIM_MIME_TYPES : PMTILES_MIME_TYPES,
      filetype: update.resource_type,
      title: update.resource_id,
      totalBytes: update.size_bytes,
      resourceMetadata: {
        resource_id: update.resource_id,
        version: update.latest_version,
        collection_ref: null,
        auto: options?.auto ?? false,
      },
    })

    if (!result || !result.job) {
      return { success: false, error: 'Failed to dispatch download job' }
    }

    logger.info(
      `[CollectionUpdateService] Dispatched update download for ${update.resource_id}: ${update.installed_version} → ${update.latest_version}`
    )

    return { success: true, jobId: result.job.id }
  }

  async applyAllUpdates(
    updates: ResourceUpdateInfo[]
  ): Promise<{ results: Array<{ resource_id: string; success: boolean; jobId?: string; error?: string }> }> {
    const results = await Promise.all(
      updates.map(async (update) => {
        const result = await this.applyUpdate(update)
        return { resource_id: update.resource_id, ...result }
      })
    )

    return { results }
  }

  /**
   * Fetch Content-Length for each update URL in parallel. HEAD failures are non-fatal —
   * the update row just renders without a size. Bounded to HEAD_TIMEOUT_MS so a slow
   * mirror doesn't block the whole check.
   */
  private async enrichWithSizes(updates: ResourceUpdateInfo[]): Promise<ResourceUpdateInfo[]> {
    const HEAD_TIMEOUT_MS = 5000

    return await Promise.all(
      updates.map(async (update) => {
        if (update.size_bytes) return update // Trust upstream if it already gave us one
        try {
          const head = await axios.head(update.download_url, {
            timeout: HEAD_TIMEOUT_MS,
            maxRedirects: 5,
            validateStatus: (s) => s >= 200 && s < 400,
          })
          const len = Number(head.headers['content-length'])
          return Number.isFinite(len) && len > 0 ? { ...update, size_bytes: len } : update
        } catch {
          return update
        }
      })
    )
  }

  private buildFilename(update: ResourceUpdateInfo): string {
    if (update.resource_type === 'zim') {
      return `${update.resource_id}_${update.latest_version}.zim`
    }
    return `${update.resource_id}_${update.latest_version}.pmtiles`
  }

  private buildFilepath(update: ResourceUpdateInfo, filename: string): string {
    if (update.resource_type === 'zim') {
      return join(process.cwd(), ZIM_STORAGE_PATH, filename)
    }
    return join(process.cwd(), MAP_STORAGE_PATH, 'pmtiles', filename)
  }
}

import db from '@adonisjs/lucid/services/db'
import logger from '@adonisjs/core/services/logger'
import { CONDITIONS_FILE } from '../data/conditions.js'
import { NATURAL_REMEDIES_FILE } from '../data/natural_remedies.js'
import { HOME_REMEDIES_FILE } from '../data/home_remedies.js'
import {
  parseConditionsFile,
  parseNaturalRemediesFile,
  findConditionBySlug,
  toConditionSummary,
  buildIndicationQuery,
  orderOtcFirst,
  remediesForCondition,
  remediesForFreeText,
} from '../../util/conditions.js'
import { PRODUCT_TYPES } from '../../types/drug_reference.js'
import type {
  Condition,
  ConditionSummary,
  ConditionDrugsResult,
  NaturalRemedy,
  NaturalRemediesFile,
} from '../../types/conditions.js'
import type { DrugSearchResult } from '../../types/drug_reference.js'

/**
 * "When to use what" — condition-first service (Phase 1 + Phase 2).
 *
 * Resolves a curated condition (or a free-text situation) to the OTC drugs whose
 * FDA label indications match it, plus the natural remedies (NCCIH) whose curated
 * condition mapping includes the resolved slug.
 *
 * Reuses the Drug Reference indication-search machinery: the same combined-FULLTEXT
 * index (ft_drug_labels_name_indications), the same MAX(MATCH …) aggregate pattern
 * required under MySQL 8 ONLY_FULL_GROUP_BY, and the same brand+generic collapse —
 * then re-buckets results OTC-first.
 *
 * Natural remedies are in-memory (no DB table, no migration) — one module-level
 * parse of NATURAL_REMEDIES_FILE, reused across all requests.
 */

/**
 * Module-level merged remedies corpus (fail-soft): the NCCIH herbs plus the
 * non-herbal home-care measures (CDC/NIH/FDA), each entry tagged with its kind
 * so the UI can badge them apart. Slugs are disjoint between the two files
 * (validated at curation time).
 */
const HERB_FILE = parseNaturalRemediesFile(NATURAL_REMEDIES_FILE)
const HOME_FILE = parseNaturalRemediesFile(HOME_REMEDIES_FILE)
const REMEDIES_FILE: NaturalRemediesFile = {
  version: HERB_FILE.version,
  source: HERB_FILE.source,
  remedies: [
    ...HERB_FILE.remedies.map((r) => ({ ...r, kind: 'herb' as const })),
    ...HOME_FILE.remedies.map((r) => ({ ...r, kind: 'self-care' as const })),
  ],
}

export class ConditionService {
  /** Parsed (fail-soft) curated spine — bad entries are dropped, not fatal. */
  private get spine(): Condition[] {
    return parseConditionsFile(CONDITIONS_FILE).conditions
  }

  /** All curated conditions as client-facing summaries (no searchTerms). */
  listConditions(): ConditionSummary[] {
    return this.spine.map(toConditionSummary)
  }

  /**
   * The full curated natural-remedies list (NCCIH herbs). Small enough to ship
   * as page props, which lets the Drug Reference search match remedies by name
   * client-side and offer a "Natural" browse with no extra round trip.
   */
  listRemedies(): NaturalRemedy[] {
    return REMEDIES_FILE.remedies
  }

  /**
   * The full curated spine (WITH searchTerms) for server-side matching such as
   * the drug-detail reverse link (situationsForIndications). Stays server-only —
   * searchTerms are a search-implementation detail the client never receives.
   */
  allConditions(): Condition[] {
    return this.spine
  }

  /** Find a curated condition by slug. Returns null when absent. */
  findCondition(slug: string): Condition | null {
    return findConditionBySlug(this.spine, slug)
  }

  /**
   * Resolve a curated condition (by slug) to its matching OTC drugs and natural
   * remedies. Returns null when the slug is not in the curated spine so the
   * controller can 404. Drugs are OTC-only and OTC-first-ordered.
   */
  async drugsForSlug(
    slug: string,
    limit = 50,
    opts?: { route?: string; sort?: 'relevance' | 'name' }
  ): Promise<ConditionDrugsResult | null> {
    const condition = this.findCondition(slug)
    if (!condition) return null

    const drugs = await this.searchIndications(condition.searchTerms, limit, opts)
    const remedies: NaturalRemedy[] = remediesForCondition(REMEDIES_FILE, slug)
    return { condition: toConditionSummary(condition), drugs, remedies }
  }

  /**
   * Resolve a free-text situation (off-list condition) to matching OTC drugs and
   * natural remedies. Treats the raw query as a single search term. Returns a
   * synthetic condition summary echoing the query so the UI can render a consistent
   * header.
   *
   * Remedy resolution for free text:
   *   1. Try to resolve the query to a curated condition slug (exact or substring
   *      match on slug/label). If found, use remediesForCondition — this is the
   *      primary path (e.g. "burns" typed free-form still finds aloe/tea-tree).
   *   2. Secondary fallback: remediesForFreeText searches remedy name/uses by
   *      substring so an unmapped query ("athlete's foot") can still surface a
   *      relevant remedy. Results from both paths are unioned and de-duped by slug.
   */
  async drugsForFreeText(
    query: string,
    limit = 50,
    opts?: { route?: string; sort?: 'relevance' | 'name' }
  ): Promise<ConditionDrugsResult> {
    const trimmed = query.trim()
    const drugs = trimmed.length > 0 ? await this.searchIndications([trimmed], limit, opts) : []

    // Phase 2: union condition-mapped + free-text-matched remedies.
    const remedyMap = new Map<string, NaturalRemedy>()
    if (trimmed.length > 0) {
      // Primary: resolve to a curated condition slug the same way the client-side
      // matchSituation helper does (case-insensitive exact/substring on slug+label).
      const q = trimmed.toLowerCase()
      const matchedCondition =
        this.spine.find((c) => c.slug.toLowerCase() === q || c.label.toLowerCase() === q) ??
        this.spine.find(
          (c) =>
            c.label.toLowerCase().includes(q) || c.slug.replace(/-/g, ' ').toLowerCase().includes(q)
        ) ??
        null
      if (matchedCondition) {
        for (const r of remediesForCondition(REMEDIES_FILE, matchedCondition.slug)) {
          remedyMap.set(r.slug, r)
        }
      }
      // Secondary: name/uses substring fallback.
      for (const r of remediesForFreeText(REMEDIES_FILE, trimmed)) {
        if (!remedyMap.has(r.slug)) remedyMap.set(r.slug, r)
      }
    }

    return {
      condition: { slug: '', label: trimmed, category: 'Search' },
      drugs,
      remedies: Array.from(remedyMap.values()),
    }
  }

  /**
   * Core search: FULLTEXT over (searchable_name, indications) for the OR-expanded
   * searchTerms, OTC-filtered, collapsed by brand+generic, OTC-first-ordered.
   *
   * Strategy mirrors DrugReferenceService:
   *   1. FULLTEXT NATURAL LANGUAGE MODE on the built query (requires the query
   *      to have a >= 3-char token; innodb_ft_min_token_size = 3).
   *   2. LIKE fallback when the built query is empty/too short OR FULLTEXT throws
   *      (e.g. the index is absent) — runs each term as a LIKE clause.
   * Both paths force product_type = OTC and then orderOtcFirst (a no-op on the
   * already-OTC set, but kept so a future relaxation of the OTC filter stays
   * correctly ordered).
   */
  async searchIndications(
    searchTerms: string[],
    limit = 50,
    opts?: { route?: string; sort?: 'relevance' | 'name' }
  ): Promise<DrugSearchResult[]> {
    const ftQuery = buildIndicationQuery(searchTerms)
    // A FULLTEXT query needs a token >= innodb_ft_min_token_size (3). If the
    // longest bare token is shorter, NATURAL LANGUAGE MODE returns nothing, so
    // go straight to LIKE.
    const longestToken = ftQuery
      .replace(/"/g, ' ')
      .split(/\s+/)
      .reduce((max, t) => Math.max(max, t.length), 0)
    const useFulltext = ftQuery.length > 0 && longestToken >= 3

    if (useFulltext) {
      try {
        const rows = await this.searchIndicationFulltext(ftQuery, limit, opts)
        return orderOtcFirst(rows)
      } catch (err) {
        logger.warn(
          `[ConditionService] FULLTEXT indication search failed, falling back to LIKE: ${
            err instanceof Error ? err.message : String(err)
          }`
        )
      }
    }

    const rows = await this.searchIndicationLike(searchTerms, limit, opts)
    return orderOtcFirst(rows)
  }

  /**
   * FULLTEXT OTC indication search.
   *
   * MATCHes over (searchable_name, indications) — must exactly match the
   * ft_drug_labels_name_indications index column list. The MAX(MATCH …) wrapper
   * is LOAD-BEARING: MySQL 8 ONLY_FULL_GROUP_BY rejects a bare MATCH() in SELECT
   * under GROUP BY; wrapping it in MAX() makes it an aggregate. Copied verbatim
   * from DrugReferenceService.searchIndicationFulltext, with a fixed OTC filter.
   */
  private async searchIndicationFulltext(
    ftQuery: string,
    limit: number,
    opts?: { route?: string; sort?: 'relevance' | 'name' }
  ): Promise<DrugSearchResult[]> {
    let sql = `
      SELECT
        MIN(id) AS id,
        brand_name,
        generic_name,
        MIN(manufacturer) AS manufacturer,
        MIN(route) AS route,
        MIN(product_type) AS product_type,
        COUNT(*) AS labelCount,
        MAX(MATCH(searchable_name, indications) AGAINST(? IN NATURAL LANGUAGE MODE)) AS relevance
      FROM drug_labels
      WHERE MATCH(searchable_name, indications) AGAINST(? IN NATURAL LANGUAGE MODE)
        AND product_type = ?
    `
    const bindings: unknown[] = [ftQuery, ftQuery, PRODUCT_TYPES.OTC]

    if (opts?.route) {
      sql += ' AND route LIKE ?'
      bindings.push(`%${opts.route.toUpperCase()}%`)
    }

    sql += `
      GROUP BY brand_name, generic_name
      ORDER BY ${opts?.sort === 'name' ? 'COALESCE(brand_name, generic_name) ASC' : 'relevance DESC'}
      LIMIT ?
    `
    bindings.push(limit)

    const rows = await db.rawQuery(sql, bindings)
    return this.mapSearchRows(rows[0])
  }

  /**
   * LIKE OTC indication fallback (FULLTEXT unavailable or query too short).
   *
   * ORs a LIKE clause per search term over `indications` so any synonym can
   * surface a match. OTC-filtered and collapsed identically to the FULLTEXT path.
   */
  private async searchIndicationLike(
    searchTerms: string[],
    limit: number,
    opts?: { route?: string; sort?: 'relevance' | 'name' }
  ): Promise<DrugSearchResult[]> {
    const terms = searchTerms.map((t) => t.trim()).filter((t) => t.length > 0)
    if (terms.length === 0) return []

    const likeClauses = terms.map(() => 'indications LIKE ?').join(' OR ')
    let sql = `
      SELECT
        MIN(id) AS id,
        brand_name,
        generic_name,
        MIN(manufacturer) AS manufacturer,
        MIN(route) AS route,
        MIN(product_type) AS product_type,
        COUNT(*) AS labelCount
      FROM drug_labels
      WHERE (${likeClauses})
        AND product_type = ?
    `
    const bindings: unknown[] = [...terms.map((t) => `%${t}%`), PRODUCT_TYPES.OTC]

    if (opts?.route) {
      sql += ' AND route LIKE ?'
      bindings.push(`%${opts.route.toUpperCase()}%`)
    }

    sql += `
      GROUP BY brand_name, generic_name
      ORDER BY ${opts?.sort === 'name' ? 'COALESCE(brand_name, generic_name) ASC' : 'brand_name ASC'}
      LIMIT ?
    `
    bindings.push(limit)

    const rows = await db.rawQuery(sql, bindings)
    return this.mapSearchRows(rows[0])
  }

  /** Map raw collapsed rows to DrugSearchResult — mirrors DrugReferenceService. */
  private mapSearchRows(rows: any[]): DrugSearchResult[] {
    if (!Array.isArray(rows)) return []
    return rows.map((row) => ({
      id: Number(row.id),
      brand_name: row.brand_name ?? null,
      generic_name: row.generic_name ?? null,
      manufacturer: row.manufacturer ?? null,
      route: row.route ?? null,
      product_type: row.product_type ?? null,
      labelCount: Number(row.labelCount ?? row.labelcount ?? 1),
    }))
  }

  /**
   * Current drug_labels row count — drives the index page empty-state (no data →
   * point the user to Drug Reference to download first). Mirrors
   * DrugReferenceService.rowCount; returns 0 on any error.
   */
  async drugRowCount(): Promise<number> {
    try {
      const result = await db.rawQuery('SELECT COUNT(*) AS cnt FROM drug_labels')
      const rows = result[0] as Array<{ cnt: number | string }>
      return Number(rows[0]?.cnt ?? 0)
    } catch {
      return 0
    }
  }
}

import logger from '@adonisjs/core/services/logger'
import { isNewerVersion, parseMajorVersion } from '../utils/version.js'

export interface ParsedImageReference {
  registry: string
  namespace: string
  repo: string
  tag: string
  /** Full name for registry API calls: namespace/repo */
  fullName: string
}

export interface AvailableUpdate {
  tag: string
  isLatest: boolean
  releaseUrl?: string
}

interface TokenCacheEntry {
  token: string
  expiresAt: number
}

const SEMVER_TAG_PATTERN = /^v?(\d+\.\d+(?:\.\d+)?)$/
const PLATFORM_SUFFIXES = ['-arm64', '-amd64', '-alpine', '-slim', '-cuda', '-rocm']
const REJECTED_TAGS = new Set(['latest', 'nightly', 'edge', 'dev', 'beta', 'alpha', 'canary', 'rc', 'test', 'debug'])

export class ContainerRegistryService {
  private tokenCache = new Map<string, TokenCacheEntry>()
  private sourceUrlCache = new Map<string, string | null>()
  private releaseTagPrefixCache = new Map<string, string>()

  /**
   * Parse a Docker image reference string into its components.
   */
  parseImageReference(image: string): ParsedImageReference {
    let registry: string
    let remainder: string
    let tag = 'latest'

    // Split off the tag
    const lastColon = image.lastIndexOf(':')
    if (lastColon > -1 && !image.substring(lastColon).includes('/')) {
      tag = image.substring(lastColon + 1)
      image = image.substring(0, lastColon)
    }

    // Determine registry vs image path
    const parts = image.split('/')

    if (parts.length === 1) {
      // e.g. "nginx" → Docker Hub library image
      registry = 'registry-1.docker.io'
      remainder = `library/${parts[0]}`
    } else if (parts.length === 2 && !parts[0].includes('.') && !parts[0].includes(':')) {
      // e.g. "ollama/ollama" → Docker Hub user image
      registry = 'registry-1.docker.io'
      remainder = image
    } else {
      // e.g. "ghcr.io/kiwix/kiwix-serve" → custom registry
      registry = parts[0]
      remainder = parts.slice(1).join('/')
    }

    const namespaceParts = remainder.split('/')
    const repo = namespaceParts.pop()!
    const namespace = namespaceParts.join('/')

    return {
      registry,
      namespace,
      repo,
      tag,
      fullName: remainder,
    }
  }

  /**
   * Get an anonymous auth token for the given registry and repository.
   * NOTE: This could be expanded in the future to support private repo authentication
   */
  private async getToken(registry: string, fullName: string): Promise<string> {
    const cacheKey = `${registry}/${fullName}`
    const cached = this.tokenCache.get(cacheKey)
    if (cached && cached.expiresAt > Date.now()) {
      return cached.token
    }

    let tokenUrl: string
    if (registry === 'registry-1.docker.io') {
      tokenUrl = `https://auth.docker.io/token?service=registry.docker.io&scope=repository:${fullName}:pull`
    } else if (registry === 'ghcr.io') {
      tokenUrl = `https://ghcr.io/token?service=ghcr.io&scope=repository:${fullName}:pull`
    } else {
      // For other registries, try the standard v2 token endpoint
      tokenUrl = `https://${registry}/token?service=${registry}&scope=repository:${fullName}:pull`
    }

    const response = await this.fetchWithRetry(tokenUrl)
    if (!response.ok) {
      throw new Error(`Failed to get auth token from ${registry}: ${response.status}`)
    }

    const data = (await response.json()) as { token?: string; access_token?: string }
    const token = data.token || data.access_token || ''

    if (!token) {
      throw new Error(`No token returned from ${registry}`)
    }

    // Cache for 5 minutes (tokens usually last longer, but be conservative)
    this.tokenCache.set(cacheKey, {
      token,
      expiresAt: Date.now() + 5 * 60 * 1000,
    })

    return token
  }

  /**
   * List all tags for a given image from the registry.
   */
  async listTags(parsed: ParsedImageReference): Promise<string[]> {
    const token = await this.getToken(parsed.registry, parsed.fullName)
    const allTags: string[] = []
    let url = `https://${parsed.registry}/v2/${parsed.fullName}/tags/list?n=1000`

    while (url) {
      const response = await this.fetchWithRetry(url, {
        headers: { Authorization: `Bearer ${token}` },
      })

      if (!response.ok) {
        throw new Error(`Failed to list tags for ${parsed.fullName}: ${response.status}`)
      }

      const data = (await response.json()) as { tags?: string[] }
      if (data.tags) {
        allTags.push(...data.tags)
      }

      // Handle pagination via Link header. Per the OCI/Docker registry spec the next-page
      // URL is relative (e.g. "/v2/<repo>/tags/list?last=<tag>&n=1000"), so it must be
      // resolved against the registry origin before re-fetching — assigning the raw relative
      // path to `url` makes fetch() throw "Failed to parse URL". This silently broke update
      // checks for any repo with >1000 tags (e.g. ollama/ollama, filebrowser/filebrowser),
      // which is the root cause of #945. new URL(relative, base) also passes absolute
      // next-URLs through unchanged, so it's safe for registries that return those.
      const linkHeader = response.headers.get('link')
      if (linkHeader) {
        const match = linkHeader.match(/<([^>]+)>;\s*rel="next"/)
        url = match ? new URL(match[1], `https://${parsed.registry}`).toString() : ''
      } else {
        url = ''
      }
    }

    return allTags
  }

  /**
   * Check if a specific tag supports the given architecture by fetching its manifest.
   */
  async checkArchSupport(parsed: ParsedImageReference, tag: string, hostArch: string): Promise<boolean> {
    try {
      const token = await this.getToken(parsed.registry, parsed.fullName)
      const url = `https://${parsed.registry}/v2/${parsed.fullName}/manifests/${tag}`

      const response = await this.fetchWithRetry(url, {
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: [
            'application/vnd.oci.image.index.v1+json',
            'application/vnd.docker.distribution.manifest.list.v2+json',
            'application/vnd.oci.image.manifest.v1+json',
            'application/vnd.docker.distribution.manifest.v2+json',
          ].join(', '),
        },
      })

      if (!response.ok) return true // If we can't check, assume it's compatible

      const manifest = (await response.json()) as {
        mediaType?: string
        manifests?: Array<{ platform?: { architecture?: string } }>
      }
      const mediaType = manifest.mediaType || response.headers.get('content-type') || ''

      // Manifest list — check if any platform matches
      if (
        mediaType.includes('manifest.list') ||
        mediaType.includes('image.index') ||
        manifest.manifests
      ) {
        const manifests = manifest.manifests || []
        return manifests.some(
          (m: any) => m.platform && m.platform.architecture === hostArch
        )
      }

      // Single manifest — assume compatible (can't easily determine arch without fetching config blob)
      return true
    } catch (error) {
      logger.warn(`[ContainerRegistryService] Error checking arch for ${tag}: ${error.message}`)
      return true // Assume compatible on error
    }
  }

  /**
   * Estimate the compressed download size (in bytes) of an image tag for the
   * given host architecture by summing its layer sizes from the manifest.
   *
   * Resolves a multi-arch manifest list/index down to the platform-specific
   * manifest before summing `layers[].size`. Returns null on any failure so
   * callers can fall back to a conservative fixed threshold rather than
   * silently skipping a disk pre-flight check.
   */
  async getImageDownloadSize(
    parsed: ParsedImageReference,
    tag: string,
    hostArch: string
  ): Promise<number | null> {
    try {
      const token = await this.getToken(parsed.registry, parsed.fullName)
      const manifestAccept = [
        'application/vnd.oci.image.index.v1+json',
        'application/vnd.docker.distribution.manifest.list.v2+json',
        'application/vnd.oci.image.manifest.v1+json',
        'application/vnd.docker.distribution.manifest.v2+json',
      ].join(', ')

      const fetchManifest = async (ref: string) =>
        this.fetchWithRetry(`https://${parsed.registry}/v2/${parsed.fullName}/manifests/${ref}`, {
          headers: { Authorization: `Bearer ${token}`, Accept: manifestAccept },
        })

      const topRes = await fetchManifest(tag)
      if (!topRes.ok) return null

      let manifest = (await topRes.json()) as {
        mediaType?: string
        layers?: Array<{ size?: number }>
        manifests?: Array<{ digest?: string; platform?: { architecture?: string } }>
      }

      // Multi-arch manifest list/index — resolve to the host-arch child manifest.
      if (manifest.manifests?.length) {
        const match =
          manifest.manifests.find((m) => m.platform?.architecture === hostArch) ||
          manifest.manifests[0]
        if (!match?.digest) return null

        const childRes = await fetchManifest(match.digest)
        if (!childRes.ok) return null
        manifest = (await childRes.json()) as { layers?: Array<{ size?: number }> }
      }

      if (!manifest.layers?.length) return null

      return manifest.layers.reduce((total, layer) => total + (layer.size || 0), 0)
    } catch (error) {
      logger.warn(
        `[ContainerRegistryService] Failed to get image size for ${parsed.fullName}:${tag}: ${error.message}`
      )
      return null
    }
  }

  /**
   * Extract the source repository URL from an image's OCI labels.
   * Uses the standardized `org.opencontainers.image.source` label.
   * Result is cached per image (not per tag).
   */
  async getSourceUrl(parsed: ParsedImageReference): Promise<string | null> {
    const cacheKey = `${parsed.registry}/${parsed.fullName}`
    if (this.sourceUrlCache.has(cacheKey)) {
      return this.sourceUrlCache.get(cacheKey)!
    }

    try {
      const token = await this.getToken(parsed.registry, parsed.fullName)

      // First get the manifest to find the config blob digest
      const manifestUrl = `https://${parsed.registry}/v2/${parsed.fullName}/manifests/${parsed.tag}`
      const manifestRes = await this.fetchWithRetry(manifestUrl, {
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: [
            'application/vnd.oci.image.manifest.v1+json',
            'application/vnd.docker.distribution.manifest.v2+json',
            'application/vnd.oci.image.index.v1+json',
            'application/vnd.docker.distribution.manifest.list.v2+json',
          ].join(', '),
        },
      })

      if (!manifestRes.ok) {
        this.sourceUrlCache.set(cacheKey, null)
        return null
      }

      const manifest = (await manifestRes.json()) as {
        config?: { digest?: string }
        manifests?: Array<{ digest?: string; mediaType?: string; platform?: { architecture?: string } }>
      }

      // If this is a manifest list, pick the first manifest to get the config
      let configDigest = manifest.config?.digest
      if (!configDigest && manifest.manifests?.length) {
        const firstManifest = manifest.manifests[0]
        if (firstManifest.digest) {
          const childRes = await this.fetchWithRetry(
            `https://${parsed.registry}/v2/${parsed.fullName}/manifests/${firstManifest.digest}`,
            {
              headers: {
                Authorization: `Bearer ${token}`,
                Accept: 'application/vnd.oci.image.manifest.v1+json, application/vnd.docker.distribution.manifest.v2+json',
              },
            }
          )
          if (childRes.ok) {
            const childManifest = (await childRes.json()) as { config?: { digest?: string } }
            configDigest = childManifest.config?.digest
          }
        }
      }

      if (!configDigest) {
        this.sourceUrlCache.set(cacheKey, null)
        return null
      }

      // Fetch the config blob to read labels
      const blobUrl = `https://${parsed.registry}/v2/${parsed.fullName}/blobs/${configDigest}`
      const blobRes = await this.fetchWithRetry(blobUrl, {
        headers: { Authorization: `Bearer ${token}` },
      })

      if (!blobRes.ok) {
        this.sourceUrlCache.set(cacheKey, null)
        return null
      }

      const config = (await blobRes.json()) as {
        config?: { Labels?: Record<string, string> }
      }

      const sourceUrl = config.config?.Labels?.['org.opencontainers.image.source'] || null
      this.sourceUrlCache.set(cacheKey, sourceUrl)
      return sourceUrl
    } catch (error) {
      logger.warn(`[ContainerRegistryService] Failed to get source URL for ${cacheKey}: ${error.message}`)
      this.sourceUrlCache.set(cacheKey, null)
      return null
    }
  }

  /**
   * Detect whether a GitHub/GitLab repo uses a 'v' prefix on release tags.
   * Probes the GitHub API with the current tag to determine the convention,
   * then caches the result per source URL.
   */
  async detectReleaseTagPrefix(sourceUrl: string, sampleTag: string): Promise<string> {
    if (this.releaseTagPrefixCache.has(sourceUrl)) {
      return this.releaseTagPrefixCache.get(sourceUrl)!
    }

    try {
      const url = new URL(sourceUrl)
      if (url.hostname !== 'github.com') {
        this.releaseTagPrefixCache.set(sourceUrl, '')
        return ''
      }

      const cleanPath = url.pathname.replace(/\.git$/, '').replace(/\/$/, '')
      const strippedTag = sampleTag.replace(/^v/, '')
      const vTag = `v${strippedTag}`

      // Try both variants against GitHub's API — the one that 200s tells us the convention
      // Try v-prefixed first since it's more common
      const vRes = await this.fetchWithRetry(
        `https://api.github.com/repos${cleanPath}/releases/tags/${vTag}`,
        { headers: { Accept: 'application/vnd.github.v3+json', 'User-Agent': 'ProjectNomad' } },
        1
      )
      if (vRes.ok) {
        this.releaseTagPrefixCache.set(sourceUrl, 'v')
        return 'v'
      }

      const plainRes = await this.fetchWithRetry(
        `https://api.github.com/repos${cleanPath}/releases/tags/${strippedTag}`,
        { headers: { Accept: 'application/vnd.github.v3+json', 'User-Agent': 'ProjectNomad' } },
        1
      )
      if (plainRes.ok) {
        this.releaseTagPrefixCache.set(sourceUrl, '')
        return ''
      }
    } catch {
      // On error, fall through to default
    }

    // Default: no prefix modification
    this.releaseTagPrefixCache.set(sourceUrl, '')
    return ''
  }

  /**
   * Build a release URL for a specific tag given a source repository URL and
   * the detected release tag prefix convention.
   * Supports GitHub and GitLab URL patterns.
   */
  buildReleaseUrl(sourceUrl: string, tag: string, releaseTagPrefix: string): string | undefined {
    try {
      const url = new URL(sourceUrl)
      if (url.hostname === 'github.com' || url.hostname.includes('gitlab')) {
        const cleanPath = url.pathname.replace(/\.git$/, '').replace(/\/$/, '')
        const strippedTag = tag.replace(/^v/, '')
        const releaseTag = releaseTagPrefix ? `${releaseTagPrefix}${strippedTag}` : strippedTag
        return `${url.origin}${cleanPath}/releases/tag/${releaseTag}`
      }
    } catch {
      // Invalid URL, skip
    }
    return undefined
  }

  /**
   * Filter and sort tags to find compatible updates for a service.
   */
  filterCompatibleUpdates(
    tags: string[],
    currentTag: string,
    majorVersion: number
  ): string[] {
    return tags
      .filter((tag) => {
        // Must match semver pattern
        if (!SEMVER_TAG_PATTERN.test(tag)) return false

        // Reject known non-version tags
        if (REJECTED_TAGS.has(tag.toLowerCase())) return false

        // Reject platform suffixes
        if (PLATFORM_SUFFIXES.some((suffix) => tag.toLowerCase().endsWith(suffix))) return false

        // Must be same major version
        if (parseMajorVersion(tag) !== majorVersion) return false

        // Must be newer than current
        return isNewerVersion(tag, currentTag)
      })
      .sort((a, b) => (isNewerVersion(a, b) ? -1 : 1)) // Newest first
  }

  /**
   * High-level method to get available updates for a service.
   * Returns a sorted list of compatible newer versions (newest first).
   */
  async getAvailableUpdates(
    containerImage: string,
    hostArch: string,
    fallbackSourceRepo?: string | null
  ): Promise<AvailableUpdate[]> {
    const parsed = this.parseImageReference(containerImage)
    const currentTag = parsed.tag

    if (currentTag === 'latest') {
      logger.warn(
        `[ContainerRegistryService] Cannot check updates for ${containerImage} — using :latest tag`
      )
      return []
    }

    const majorVersion = parseMajorVersion(currentTag)

    // Fetch tags and source URL in parallel
    const [tags, ociSourceUrl] = await Promise.all([
      this.listTags(parsed),
      this.getSourceUrl(parsed),
    ])

    // OCI label takes precedence, fall back to DB-stored source_repo
    const sourceUrl = ociSourceUrl || fallbackSourceRepo || null

    const compatible = this.filterCompatibleUpdates(tags, currentTag, majorVersion)

    // Detect release tag prefix convention (e.g. 'v' vs no prefix) if we have a source URL
    let releaseTagPrefix = ''
    if (sourceUrl) {
      releaseTagPrefix = await this.detectReleaseTagPrefix(sourceUrl, currentTag)
    }

    // Check architecture support for the top candidates (limit checks to save API calls)
    const maxArchChecks = 10
    const results: AvailableUpdate[] = []

    for (const tag of compatible.slice(0, maxArchChecks)) {
      const supported = await this.checkArchSupport(parsed, tag, hostArch)
      if (supported) {
        results.push({
          tag,
          isLatest: results.length === 0,
          releaseUrl: sourceUrl ? this.buildReleaseUrl(sourceUrl, tag, releaseTagPrefix) : undefined,
        })
      }
    }

    // For remaining tags (beyond arch check limit), include them but mark as not latest
    for (const tag of compatible.slice(maxArchChecks)) {
      results.push({
        tag,
        isLatest: false,
        releaseUrl: sourceUrl ? this.buildReleaseUrl(sourceUrl, tag, releaseTagPrefix) : undefined,
      })
    }

    return results
  }

  /**
   * Fetch with retry and exponential backoff for rate limiting.
   */
  private async fetchWithRetry(
    url: string,
    init?: RequestInit,
    maxRetries = 3
  ): Promise<Response> {
    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      const response = await fetch(url, init)

      if (response.status === 429 && attempt < maxRetries) {
        const retryAfter = response.headers.get('retry-after')
        const delay = retryAfter
          ? parseInt(retryAfter, 10) * 1000
          : Math.pow(2, attempt) * 1000
        logger.warn(
          `[ContainerRegistryService] Rate limited on ${url}, retrying in ${delay}ms`
        )
        await new Promise((resolve) => setTimeout(resolve, delay))
        continue
      }

      return response
    }

    throw new Error(`Failed to fetch ${url} after ${maxRetries} retries`)
  }
}

import logger from '@adonisjs/core/services/logger'
import { DateTime } from 'luxon'
import KVStore from '#models/kv_store'
import InstalledResource from '#models/installed_resource'
import { DownloadService } from '#services/download_service'
import { CollectionUpdateService } from '#services/collection_update_service'
import { DrugReferenceService } from '#services/drug_reference_service'
import {
  KiwixCatalogService,
  reconcileResourceUpdateState,
  type CatalogResult,
} from '#services/kiwix_catalog_service'
import { isWithinWindow, parseWindowMinutes } from '../utils/update_window.js'
import { recordResourceUpdateFailure } from '../utils/content_auto_update_backoff.js'
import type { Blocker, PreflightResult } from '../utils/image_disk_preflight.js'

/**
 * Content auto-update is opt-in via a single global master switch and runs on
 * its OWN window + per-window data cap (deliberately separate from the core/app
 * `autoUpdate.*` window, since ZIM downloads are multi-GB and bandwidth
 * sensitive). Defaults err toward an overnight window with no cap; the UI
 * strongly recommends setting a cap.
 */
const DEFAULT_WINDOW_START = '02:00'
const DEFAULT_WINDOW_END = '05:00'
const DEFAULT_COOLOFF_HOURS = 72

/** Whole-feature failures (e.g. catalog unreachable) before it self-disables. */
const MAX_FEATURE_FAILURES = 3

export interface ContentAutoUpdateConfig {
  /** Global master switch (`contentAutoUpdate.enabled`). */
  enabled: boolean
  windowStart: string
  windowEnd: string
  cooloffHours: number
  /** Max NEW bytes initiated per window instance. 0 = unlimited. */
  maxBytesPerWindow: number
}

/** Per-resource eligibility verdict (drives both selection and the status UI). */
export interface ContentEligibility {
  eligible: boolean
  reason: string
  cooloffRemainingHours: number | null
}

/** An eligible resource paired with the catalog facts needed to download it. */
export interface ContentCandidate {
  resource: InstalledResource
  version: string
  download_url: string
  size_bytes: number
  installed_at: DateTime
}

/** Outcome of the cap-bounded greedy selection. */
export interface ContentSelection {
  selected: ContentCandidate[]
  /** Single files larger than the whole cap — never auto-started (manual only). */
  skippedOversize: ContentCandidate[]
  /** Fit the cap but not this window's remaining budget — retried next window. */
  deferred: ContentCandidate[]
}

export interface ContentAutoUpdateResourceStatus {
  resource_id: string
  resource_type: 'zim' | 'map'
  current_version: string
  available_update_version: string | null
  size_bytes: number | null
  eligible: boolean
  reason: string
  cooloff_remaining_hours: number | null
  exceeds_cap: boolean
  consecutive_failures: number
  auto_disabled_reason: string | null
}

export interface ContentAutoUpdateStatus extends ContentAutoUpdateConfig {
  withinWindow: boolean
  windowBytesUsed: number
  lastAttemptAt: string | null
  lastResult: string | null
  lastError: string | null
  autoDisabledReason: string | null
  resources: ContentAutoUpdateResourceStatus[]
}

/**
 * Decision + safety layer for automatic content (ZIM/map) updates. This is the
 * content-side counterpart to {@link AppAutoUpdateService}: it decides *whether*
 * each installed resource with an available update should be downloaded now
 * (master switch on + in the content window + past cool-off + within the data
 * cap) and then drives the existing manual download path
 * ({@link CollectionUpdateService.applyUpdate} → {@link RunDownloadJob}).
 *
 * It never installs synchronously — it dispatches resumable download jobs and
 * lets the existing job-completion path advance the installed version and
 * rebuild the Kiwix library.
 */
export class ContentAutoUpdateService {
  constructor(
    private downloadService: DownloadService,
    private catalog: KiwixCatalogService = new KiwixCatalogService(),
    private collectionUpdateService: CollectionUpdateService = new CollectionUpdateService()
  ) {}

  /** Read the master switch plus the content-specific window/cool-off/cap. */
  async getConfig(): Promise<ContentAutoUpdateConfig> {
    const [enabled, windowStart, windowEnd, cooloffHours, maxBytes] = await Promise.all([
      KVStore.getValue('contentAutoUpdate.enabled'),
      KVStore.getValue('contentAutoUpdate.windowStart'),
      KVStore.getValue('contentAutoUpdate.windowEnd'),
      KVStore.getValue('contentAutoUpdate.cooloffHours'),
      KVStore.getValue('contentAutoUpdate.maxBytesPerWindow'),
    ])

    const parsedCooloff = Number(cooloffHours)
    const parsedCap = Number(maxBytes)
    return {
      enabled: enabled ?? false,
      windowStart: windowStart || DEFAULT_WINDOW_START,
      windowEnd: windowEnd || DEFAULT_WINDOW_END,
      // `Number(null) === 0`, so an unset value must fall through to the default
      // rather than silently resolving to a zero cool-off. An explicit 0 is honored.
      cooloffHours:
        cooloffHours !== null && Number.isFinite(parsedCooloff) && parsedCooloff >= 0
          ? parsedCooloff
          : DEFAULT_COOLOFF_HOURS,
      maxBytesPerWindow:
        maxBytes !== null && Number.isFinite(parsedCap) && parsedCap >= 0 ? parsedCap : 0,
    }
  }

  /**
   * Pure per-resource eligibility verdict. A resource is eligible when it has a
   * detected newer version, is not self-disabled, and is past its cool-off
   * (measured from first-detected). Version comparison is a lexicographic
   * compare of the YYYY-MM stamps, which sorts chronologically.
   */
  resourceEligibility(
    resource: InstalledResource,
    cooloffHours: number,
    now: DateTime
  ): ContentEligibility {
    if (!resource.available_update_version) {
      return { eligible: false, reason: 'Up to date', cooloffRemainingHours: null }
    }
    if (resource.auto_update_disabled_reason) {
      return {
        eligible: false,
        reason: 'Auto-update disabled after repeated failures',
        cooloffRemainingHours: null,
      }
    }
    if (!(resource.available_update_version > resource.version)) {
      return { eligible: false, reason: 'Up to date', cooloffRemainingHours: null }
    }
    if (!resource.available_update_first_seen_at) {
      return { eligible: false, reason: 'Cool-off pending', cooloffRemainingHours: cooloffHours }
    }

    const ageHours = now.diff(resource.available_update_first_seen_at, 'hours').hours
    const remaining = cooloffHours - ageHours
    if (remaining > 0) {
      const rounded = Math.ceil(remaining)
      return {
        eligible: false,
        reason: `In cool-off (${rounded}h remaining)`,
        cooloffRemainingHours: rounded,
      }
    }

    return {
      eligible: true,
      reason: `Eligible → ${resource.available_update_version}`,
      cooloffRemainingHours: 0,
    }
  }

  /**
   * Pure cap-bounded greedy selection. Oldest-installed first (stale content is
   * prioritized), tie-broken smallest-first for predictability.
   *
   * - size unknown (0) → deferred (can't budget safely)
   * - size > the WHOLE cap → skippedOversize (never auto-started; manual only)
   * - size ≤ remaining budget → selected
   * - otherwise → deferred (fits the cap, not this window)
   */
  selectUnderCap(
    candidates: ContentCandidate[],
    capBytes: number,
    usedBytes: number
  ): ContentSelection {
    const cap = capBytes > 0 ? capBytes : Number.POSITIVE_INFINITY
    let remaining = Math.max(0, cap - usedBytes)

    const selected: ContentCandidate[] = []
    const skippedOversize: ContentCandidate[] = []
    const deferred: ContentCandidate[] = []

    const ordered = [...candidates].sort((a, b) => {
      const at = a.installed_at?.toMillis?.() ?? 0
      const bt = b.installed_at?.toMillis?.() ?? 0
      if (at !== bt) return at - bt
      return a.size_bytes - b.size_bytes
    })

    for (const candidate of ordered) {
      if (candidate.size_bytes <= 0) {
        deferred.push(candidate)
      } else if (candidate.size_bytes > cap) {
        skippedOversize.push(candidate)
      } else if (candidate.size_bytes <= remaining) {
        selected.push(candidate)
        remaining -= candidate.size_bytes
      } else {
        deferred.push(candidate)
      }
    }

    return { selected, skippedOversize, deferred }
  }

  /**
   * Run-wide pre-flight: never auto-update content while ANY download is already
   * running. Because content downloads are multi-GB and resumable, an in-flight
   * download from a prior window naturally blocks new starts here — exactly the
   * "let in-flight finish, don't start new" behavior we want. Transient → `skip`.
   */
  async runGlobalPreflight(): Promise<PreflightResult> {
    const blockers: Blocker[] = []
    try {
      const downloads = await this.downloadService.listDownloadJobs()
      const active = downloads.filter(
        (d) => !!d.status && ['waiting', 'active', 'delayed'].includes(d.status)
      )
      if (active.length > 0) {
        blockers.push({ reason: `${active.length} download(s) in progress`, severity: 'skip' })
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      logger.warn(`[ContentAutoUpdateService] Could not check active downloads: ${message}`)
    }
    return { ok: blockers.length === 0, blockers }
  }

  /**
   * Entry point invoked by ContentAutoUpdateJob. Gates on the master switch +
   * window, runs the local catalog check, then downloads as many eligible
   * resources as fit under the per-window data cap.
   */
  async attempt(): Promise<{ started: number; reason: string }> {
    const config = await this.getConfig()
    const now = DateTime.now()

    if (!config.enabled) {
      return { started: 0, reason: 'Content auto-update is disabled' }
    }
    if (!isWithinWindow(config.windowStart, config.windowEnd, now)) {
      const reason = `Outside update window (${config.windowStart}-${config.windowEnd})`
      await this.recordRun(reason)
      return { started: 0, reason }
    }

    try {
      // Reset the per-window budget once per window instance (the cron fires
      // hourly but a window can span several hours).
      await this.maybeResetWindowBudget(config, now)

      // Local catalog check + persist available-update state for every resource.
      // ZIM/map catalog path only — `dataset` resources are excluded here because
      // their freshness key (openFDA `export_date`) and apply path (the drug
      // download/ingest chain) don't fit the catalog-version model. They refresh
      // via `attemptDrugDataset()`, which the same content-update job runs under
      // the same master switch + window.
      const installed = await InstalledResource.query().whereNot('resource_type', 'dataset')
      const latestByKey = await this.catalog.getLatestForResources(
        // `dataset` rows are filtered out above, so the type narrows to ZIM/map.
        installed.map((r) => ({
          resource_id: r.resource_id,
          resource_type: r.resource_type as 'zim' | 'map',
        }))
      )
      for (const resource of installed) {
        const latest = latestByKey.get(`${resource.resource_type}:${resource.resource_id}`) ?? null
        await reconcileResourceUpdateState(resource, latest, now)
      }

      const eligible = installed.filter(
        (r) => this.resourceEligibility(r, config.cooloffHours, now).eligible
      )
      if (eligible.length === 0) {
        await this.recordFeatureSuccess()
        const reason = 'No eligible content updates'
        await this.recordRun(reason)
        return { started: 0, reason }
      }

      const global = await this.runGlobalPreflight()
      if (!global.ok) {
        await this.recordFeatureSuccess()
        const reason = `Pre-flight blocked: ${global.blockers.map((b) => b.reason).join('; ')}`
        await this.recordRun(reason)
        return { started: 0, reason }
      }

      const candidates: ContentCandidate[] = eligible.map((r) => {
        const latest = latestByKey.get(`${r.resource_type}:${r.resource_id}`) as CatalogResult
        return {
          resource: r,
          version: latest.version,
          download_url: latest.download_url,
          size_bytes: r.available_update_size_bytes ?? latest.size_bytes ?? 0,
          installed_at: r.installed_at,
        }
      })

      const usedBytes = await this.getWindowBytesUsed()
      const { selected, skippedOversize, deferred } = this.selectUnderCap(
        candidates,
        config.maxBytesPerWindow,
        usedBytes
      )

      let started = 0
      let failed = 0
      let initiatedBytes = 0
      for (const candidate of selected) {
        const result = await this.collectionUpdateService.applyUpdate(
          {
            resource_id: candidate.resource.resource_id,
            // `dataset` rows are filtered out of `installed` above, so ZIM/map.
            resource_type: candidate.resource.resource_type as 'zim' | 'map',
            installed_version: candidate.resource.version,
            latest_version: candidate.version,
            download_url: candidate.download_url,
            size_bytes: candidate.size_bytes || undefined,
          },
          { auto: true }
        )

        if (result.success) {
          // Success is NOT recorded here: applyUpdate only enqueues a resumable
          // download. The per-resource backoff is cleared once the download
          // actually completes (RunDownloadJob.onComplete) and incremented when it
          // fails terminally (the worker `failed` handler). Recording success on
          // dispatch would reset the counter every window and defeat self-disable.
          initiatedBytes += candidate.size_bytes
          started++
          logger.info(
            `[ContentAutoUpdateService] Started ${candidate.resource.resource_id} → ${candidate.version}`
          )
        } else {
          // A failure to even enqueue is a genuine auto-update failure; no job runs,
          // so no terminal `failed` event will follow — count it here.
          await recordResourceUpdateFailure(candidate.resource, result.error ?? 'dispatch failed')
          failed++
        }
      }

      if (initiatedBytes > 0) {
        await this.addWindowBytesUsed(initiatedBytes)
      }

      const parts = [`${started} started`]
      if (failed) parts.push(`${failed} failed`)
      if (skippedOversize.length) parts.push(`${skippedOversize.length} skipped (exceeds cap)`)
      if (deferred.length) parts.push(`${deferred.length} deferred (over budget)`)
      const reason = parts.join(', ')

      await this.recordFeatureSuccess()
      await this.recordRun(reason)
      logger.info(`[ContentAutoUpdateService] Run complete: ${reason}`)
      return { started, reason }
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      await this.recordFeatureFailure(message)
      await this.recordRun(`Failed: ${message}`)
      logger.error(`[ContentAutoUpdateService] Run failed: ${message}`)
      return { started: 0, reason: `Failed: ${message}` }
    }
  }

  /**
   * Freshness pass for the FDA drug dataset (`resource_type` 'dataset'), run by
   * the same hourly ContentAutoUpdateJob as the ZIM/map `attempt()` and gated on
   * the SAME master switch + window. The dataset's apply path differs from the
   * catalog loop (openFDA `export_date` + the drug download/ingest chain rather
   * than an InstalledResource catalog-version row), so it runs as its own step
   * instead of through `selectUnderCap` — but sharing `contentAutoUpdate.*` means
   * it never updates while content auto-update is off, and refreshes alongside
   * ZIMs and maps when it is on. Isolated so a drug-side failure can't affect the
   * catalog run.
   */
  async attemptDrugDataset(): Promise<{ started: number; reason: string }> {
    const config = await this.getConfig()
    if (!config.enabled) {
      return { started: 0, reason: 'Content auto-update is disabled' }
    }
    if (!isWithinWindow(config.windowStart, config.windowEnd, DateTime.now())) {
      return {
        started: 0,
        reason: `Outside update window (${config.windowStart}-${config.windowEnd})`,
      }
    }

    try {
      const result = await new DrugReferenceService().attemptAutoUpdate()
      return { started: result.started ? 1 : 0, reason: `drug dataset: ${result.reason}` }
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      logger.warn(`[ContentAutoUpdateService] Drug dataset freshness check failed: ${message}`)
      return { started: 0, reason: `drug dataset check failed: ${message}` }
    }
  }

  /**
   * Evaluate what the next run *would* do, without hitting the network,
   * persisting state, or dispatching anything. Operates on the available-update
   * state already persisted by the last check (manual or auto), so run a "Check
   * for Content Updates" first if you want fresh catalog data. Used by the
   * `content-auto-update:dry-run` command.
   */
  async dryRun(
    overrides: {
      now?: DateTime
      forceEnabled?: boolean
      cooloffHours?: number
      windowStart?: string
      windowEnd?: string
      maxBytesPerWindow?: number
      windowBytesUsed?: number
    } = {}
  ): Promise<{
    enabled: boolean
    withinWindow: boolean
    config: ContentAutoUpdateConfig
    eligibleCount: number
    selection: ContentSelection
  }> {
    const base = await this.getConfig()
    const config: ContentAutoUpdateConfig = {
      enabled: overrides.forceEnabled ? true : base.enabled,
      windowStart: overrides.windowStart ?? base.windowStart,
      windowEnd: overrides.windowEnd ?? base.windowEnd,
      cooloffHours: overrides.cooloffHours ?? base.cooloffHours,
      maxBytesPerWindow: overrides.maxBytesPerWindow ?? base.maxBytesPerWindow,
    }
    const now = overrides.now ?? DateTime.now()
    const withinWindow = isWithinWindow(config.windowStart, config.windowEnd, now)

    const pending = await InstalledResource.query()
      .whereNotNull('available_update_version')
      .whereNot('resource_type', 'dataset')
    const eligible = pending.filter(
      (r) => this.resourceEligibility(r, config.cooloffHours, now).eligible
    )
    const candidates: ContentCandidate[] = eligible.map((r) => ({
      resource: r,
      version: r.available_update_version!,
      download_url: '(dry-run)',
      size_bytes: r.available_update_size_bytes ?? 0,
      installed_at: r.installed_at,
    }))

    const usedBytes = overrides.windowBytesUsed ?? (await this.getWindowBytesUsed())
    const selection = this.selectUnderCap(candidates, config.maxBytesPerWindow, usedBytes)

    return {
      enabled: config.enabled,
      withinWindow,
      config,
      eligibleCount: eligible.length,
      selection,
    }
  }

  // ── Per-window budget ─────────────────────────────────────────────────────────

  /** Most-recent window-open boundary as an absolute timestamp (handles wrap). */
  windowStartBoundary(windowStart: string, now: DateTime): DateTime {
    const minutes = parseWindowMinutes(windowStart) ?? 0
    const todayStart = now.startOf('day').plus({ minutes })
    return now >= todayStart ? todayStart : todayStart.minus({ days: 1 })
  }

  /** Reset the window budget exactly once per entry into the window. */
  private async maybeResetWindowBudget(
    config: ContentAutoUpdateConfig,
    now: DateTime
  ): Promise<void> {
    const boundary = this.windowStartBoundary(config.windowStart, now)
    const resetAtRaw = await KVStore.getValue('contentAutoUpdate.windowResetAt')
    const resetAt = resetAtRaw ? DateTime.fromISO(resetAtRaw) : null
    if (!resetAt || !resetAt.isValid || resetAt < boundary) {
      await KVStore.setValue('contentAutoUpdate.windowBytesUsed', '0')
      await KVStore.setValue('contentAutoUpdate.windowResetAt', now.toISO()!)
    }
  }

  private async getWindowBytesUsed(): Promise<number> {
    const raw = await KVStore.getValue('contentAutoUpdate.windowBytesUsed')
    const num = Number(raw)
    return Number.isFinite(num) && num > 0 ? num : 0
  }

  private async addWindowBytesUsed(bytes: number): Promise<void> {
    const used = await this.getWindowBytesUsed()
    await KVStore.setValue('contentAutoUpdate.windowBytesUsed', String(used + bytes))
  }

  // ── Backoff + run recording ───────────────────────────────────────────────────
  // Per-resource backoff lives in ../utils/content_auto_update_backoff.ts so the
  // job-completion path and the worker `failed` handler can share it without an
  // import cycle. The feature-level backoff below stays here.

  /** Clear the feature-level backoff after a clean run. */
  private async recordFeatureSuccess(): Promise<void> {
    await KVStore.setValue('contentAutoUpdate.consecutiveFailures', '0')
    await KVStore.clearValue('contentAutoUpdate.lastError')
  }

  /** Record a whole-feature failure and self-disable the feature at the threshold. */
  private async recordFeatureFailure(reason: string): Promise<void> {
    const raw = await KVStore.getValue('contentAutoUpdate.consecutiveFailures')
    const failures = (Number(raw) || 0) + 1
    await KVStore.setValue('contentAutoUpdate.consecutiveFailures', String(failures))
    await KVStore.setValue('contentAutoUpdate.lastError', reason)
    if (failures >= MAX_FEATURE_FAILURES) {
      await KVStore.setValue('contentAutoUpdate.enabled', false)
      await KVStore.setValue(
        'contentAutoUpdate.autoDisabledReason',
        `Content auto-update disabled after ${failures} consecutive failures. Last error: ${reason}`
      )
      logger.error(
        `[ContentAutoUpdateService] Feature auto-disabled after ${failures} consecutive failures`
      )
    }
  }

  private async recordRun(reason: string): Promise<void> {
    await KVStore.setValue('contentAutoUpdate.lastAttemptAt', DateTime.now().toISO()!)
    await KVStore.setValue('contentAutoUpdate.lastResult', reason)
  }

  // ── Status snapshot ───────────────────────────────────────────────────────────

  /** Full state snapshot for the settings UI (resources with pending updates). */
  async getStatus(): Promise<ContentAutoUpdateStatus> {
    const config = await this.getConfig()
    const now = DateTime.now()

    const pending = await InstalledResource.query()
      .whereNotNull('available_update_version')
      .whereNot('resource_type', 'dataset')
    const resources: ContentAutoUpdateResourceStatus[] = pending.map((resource) => {
      const verdict = this.resourceEligibility(resource, config.cooloffHours, now)
      const size = resource.available_update_size_bytes ?? null
      const exceedsCap =
        config.maxBytesPerWindow > 0 && size !== null && size > config.maxBytesPerWindow
      return {
        resource_id: resource.resource_id,
        // `dataset` rows are filtered out of `pending` above, so ZIM/map.
        resource_type: resource.resource_type as 'zim' | 'map',
        current_version: resource.version,
        available_update_version: resource.available_update_version,
        size_bytes: size,
        eligible: verdict.eligible && !exceedsCap,
        reason: exceedsCap ? 'Exceeds data cap — update manually' : verdict.reason,
        cooloff_remaining_hours: verdict.cooloffRemainingHours,
        exceeds_cap: exceedsCap,
        consecutive_failures: resource.auto_update_consecutive_failures || 0,
        auto_disabled_reason: resource.auto_update_disabled_reason,
      }
    })

    const [lastAttemptAt, lastResult, lastError, autoDisabledReason, windowBytesUsed] =
      await Promise.all([
        KVStore.getValue('contentAutoUpdate.lastAttemptAt'),
        KVStore.getValue('contentAutoUpdate.lastResult'),
        KVStore.getValue('contentAutoUpdate.lastError'),
        KVStore.getValue('contentAutoUpdate.autoDisabledReason'),
        this.getWindowBytesUsed(),
      ])

    return {
      ...config,
      withinWindow: isWithinWindow(config.windowStart, config.windowEnd, now),
      windowBytesUsed,
      lastAttemptAt: lastAttemptAt || null,
      lastResult: lastResult || null,
      lastError: lastError || null,
      autoDisabledReason: autoDisabledReason || null,
      resources,
    }
  }
}

import { inject } from '@adonisjs/core'
import logger from '@adonisjs/core/services/logger'
import os from 'node:os'
import KVStore from '#models/kv_store'
import { OllamaService } from '#services/ollama_service'
import { SystemService } from '#services/system_service'
import {
  UNKNOWN_BACKEND_CONTEXT,
  computeKvBytesPerToken,
  estimateKvBytesPerToken,
  parseParameterBillions,
  parseUserContextCap,
  resolveContextWindow,
  type ContextWindowDecision,
} from '../utils/context_window.js'

/**
 * Decides how large a context window each chat model gets, and then holds that
 * answer still.
 *
 * The "holds it still" part is the whole point. Ollama unloads and reloads a
 * model whenever a request asks for a different `num_ctx` than the loaded
 * instance — so a window that grew with the conversation would stall a turn and
 * throw away the KV cache exactly when the conversation got interesting. The
 * decision is therefore made once per model and memoized for the process
 * lifetime; it is a property of (model, hardware), not of the current prompt.
 *
 * Inputs, in decreasing order of authority:
 *   - the user's cap (`ai.contextWindow`), which can only lower the result
 *   - the model's trained context length, from /api/show `model_info`
 *   - what the hardware can actually afford, from the exact per-token KV cost in
 *     the GGUF metadata against detected VRAM (or a share of system RAM)
 */
@inject()
export class ContextWindowService {
  private decisions: Map<string, Promise<ContextWindowDecision>> = new Map()
  private availableBytes: Promise<number | undefined> | null = null

  constructor(
    private ollamaService: OllamaService,
    private systemService: SystemService
  ) {}

  /**
   * The context window to request for `model`. Memoized — repeat calls within a
   * process return the identical number, which is what keeps the model loaded.
   */
  async windowFor(model: string): Promise<number> {
    return (await this.decisionFor(model)).contextWindow
  }

  async decisionFor(model: string): Promise<ContextWindowDecision> {
    const cached = this.decisions.get(model)
    if (cached) return cached

    const pending = this._resolve(model).catch((error) => {
      logger.warn(
        `[ContextWindow] Falling back to ${UNKNOWN_BACKEND_CONTEXT} for ${model}: ${error instanceof Error ? error.message : error}`
      )
      return { contextWindow: UNKNOWN_BACKEND_CONTEXT, limitedBy: 'default' as const }
    })
    this.decisions.set(model, pending)
    return pending
  }

  private async _resolve(model: string): Promise<ContextWindowDecision> {
    const [info, userCapRaw] = await Promise.all([
      this.ollamaService.getModelInfo(model),
      KVStore.getValue('ai.contextWindow'),
    ])
    const userCap = parseUserContextCap(userCapRaw)

    // No /api/show means a non-Ollama backend, which sets its context at server
    // start and ignores anything we send. Budget against a conservative value so
    // the prompt planner still bounds itself rather than trusting the backend to
    // truncate gracefully — it won't; it will truncate silently.
    if (!info.contextLength && !info.rawModelInfo) {
      const decision: ContextWindowDecision = {
        contextWindow: userCap ?? UNKNOWN_BACKEND_CONTEXT,
        limitedBy: userCap ? 'user' : 'default',
      }
      logger.info(
        `[ContextWindow] ${model}: no model metadata available, budgeting at ${decision.contextWindow}`
      )
      return decision
    }

    const kvBytesPerToken =
      computeKvBytesPerToken(info.rawModelInfo) ??
      estimateKvBytesPerToken(parseParameterBillions(info.parameterSize, model))

    const decision = resolveContextWindow({
      modelMaxCtx: info.contextLength,
      modelfileNumCtx: info.modelfileNumCtx,
      kvBytesPerToken,
      availableBytes: await this._availableBytes(),
      modelBytes: await this._modelBytes(model),
      userCap,
    })

    logger.info(
      `[ContextWindow] ${model}: ${decision.contextWindow} tokens (limited by ${decision.limitedBy}; ` +
        `${(kvBytesPerToken / 1024).toFixed(0)} KiB/token KV` +
        `${decision.affordableTokens !== undefined ? `, ~${decision.affordableTokens} affordable` : ''})`
    )
    return decision
  }

  /**
   * Memory available for inference, in bytes.
   *
   * Prefers the VRAM figure Ollama itself reports at startup — it is the number
   * that actually governs whether a window fits, and it already accounts for
   * whichever device Ollama chose. Falls back to a conservative share of system
   * RAM for CPU-only hosts, which is the low end of the hardware NOMAD targets
   * and precisely where getting this wrong hurts most.
   */
  private async _availableBytes(): Promise<number | undefined> {
    if (!this.availableBytes) {
      this.availableBytes = (async () => {
        try {
          const compute = await this.systemService.getOllamaInferenceComputeFromLogs()
          if (compute && compute.vramMiB > 0) {
            return compute.vramMiB * 1024 * 1024
          }
        } catch (error) {
          logger.debug(
            `[ContextWindow] GPU probe failed, assuming CPU inference: ${error instanceof Error ? error.message : error}`
          )
        }
        // CPU inference shares host RAM with MySQL, Redis, Qdrant and every other
        // container on the box, so claim only a modest slice of it.
        return os.totalmem() * CPU_RAM_SHARE
      })()
    }
    return this.availableBytes
  }

  private async _modelBytes(model: string): Promise<number | undefined> {
    try {
      const models = await this.ollamaService.getModels(true)
      return models.find((m) => m.name === model)?.size || undefined
    } catch {
      return undefined
    }
  }

  /** Drop memoized decisions — call when the backend or the user's cap changes. */
  invalidate(): void {
    this.decisions.clear()
    this.availableBytes = null
  }
}

/**
 * Share of system RAM assumed available for CPU inference. The rest of the NOMAD
 * stack (MySQL, Redis, Qdrant, Kiwix, the admin app itself) lives in the same
 * pool, and a machine that starts swapping is worse than one with a small window.
 */
const CPU_RAM_SHARE = 0.5

import { access, readFile, writeFile, mkdir } from 'fs/promises'
import { join, resolve } from 'path'
import { createHash } from 'crypto'
import { tmpdir } from 'os'
import logger from '@adonisjs/core/services/logger'
import type { Country, CountryCode, CountryGroup } from '../../types/maps.js'

interface NEFeature {
  type: 'Feature'
  properties: Record<string, any>
  geometry: unknown
}

interface NEFeatureCollection {
  type: 'FeatureCollection'
  features: NEFeature[]
}

const COUNTRY_GEOJSON_PATH = join(
  process.cwd(),
  'resources',
  'geodata',
  'ne_50m_admin_0_countries.geojson'
)

// Natural Earth country polygons are land-only (no territorial waters), so a
// strict intersect leaves tiles fully over the ocean out of the extract —
// coastal cities render as grey off their coast. Inflate each polygon outward
// by ~11 km to pull in adjacent tiles without ballooning the extract size.
const REGION_BUFFER_DEGREES = 0.1

const GROUP_ORDER = [
  'north-america',
  'south-america',
  'europe',
  'africa',
  'asia',
  'oceania',
]

const GROUP_META: Record<string, { id: string; name: string; description: string }> = {
  'North America': {
    id: 'north-america',
    name: 'North America',
    description: 'All countries in North America and the Caribbean.',
  },
  'South America': {
    id: 'south-america',
    name: 'South America',
    description: 'All countries in South America.',
  },
  Europe: {
    id: 'europe',
    name: 'Europe',
    description: 'All countries in Europe.',
  },
  Africa: {
    id: 'africa',
    name: 'Africa',
    description: 'All countries in Africa.',
  },
  Asia: {
    id: 'asia',
    name: 'Asia',
    description: 'All countries in Asia.',
  },
  Oceania: {
    id: 'oceania',
    name: 'Oceania',
    description: 'Australia, New Zealand, and Pacific island nations.',
  },
}

export class CountriesService {
  private static instance: CountriesService | null = null
  private loadPromise: Promise<void> | null = null
  private countries: Country[] = []
  private byCode: Map<CountryCode, { country: Country; feature: NEFeature }> = new Map()
  private groups: CountryGroup[] = []

  static getInstance(): CountriesService {
    if (!this.instance) {
      this.instance = new CountriesService()
    }
    return this.instance
  }

  private async ensureLoaded(): Promise<void> {
    if (this.byCode.size > 0) return
    if (!this.loadPromise) {
      this.loadPromise = this.load()
    }
    await this.loadPromise
  }

  private async load(): Promise<void> {
    const raw = await readFile(COUNTRY_GEOJSON_PATH, 'utf8')
    const fc = JSON.parse(raw) as NEFeatureCollection

    // Natural Earth reuses a sovereign state's ISO_A2 for its dependencies
    // (e.g. AU covers both Australia and Australian territories). Sort so the
    // sovereign mainland wins the ISO-code slot, and skip any subsequent
    // same-code dependency — otherwise the "AU" entry ends up being some tiny
    // island territory.
    const sortedFeatures = [...fc.features].sort((a, b) => typeRank(a) - typeRank(b))

    const countries: Country[] = []
    const byCode = new Map<CountryCode, { country: Country; feature: NEFeature }>()
    const groupCodes: Record<string, CountryCode[]> = {}

    for (const feature of sortedFeatures) {
      const p = feature.properties
      const code = resolveIso2(p)
      if (!code) continue
      if (byCode.has(code)) continue

      const continent = typeof p.CONTINENT === 'string' ? p.CONTINENT : 'Other'
      if (continent === 'Antarctica' || continent === 'Seven seas (open ocean)') continue

      const country: Country = {
        code,
        code3: resolveIso3(p) ?? code,
        name: typeof p.NAME === 'string' ? p.NAME : code,
        continent,
        subregion: typeof p.SUBREGION === 'string' ? p.SUBREGION : continent,
        population: typeof p.POP_EST === 'number' ? p.POP_EST : 0,
      }

      countries.push(country)
      byCode.set(code, { country, feature })

      if (GROUP_META[continent]) {
        const groupId = GROUP_META[continent].id
        if (!groupCodes[groupId]) groupCodes[groupId] = []
        groupCodes[groupId].push(code)
      }
    }

    countries.sort((a, b) => a.name.localeCompare(b.name))

    const groups: CountryGroup[] = GROUP_ORDER.flatMap((groupId) => {
      const meta = Object.values(GROUP_META).find((m) => m.id === groupId)
      if (!meta) return []
      const codes = (groupCodes[groupId] ?? []).slice().sort()
      if (codes.length === 0) return []
      return [{ id: meta.id, name: meta.name, description: meta.description, countries: codes }]
    })

    this.countries = countries
    this.byCode = byCode
    this.groups = groups

    logger.info(
      `[CountriesService] Loaded ${countries.length} countries across ${groups.length} groups`
    )
  }

  async list(): Promise<Country[]> {
    await this.ensureLoaded()
    return this.countries
  }

  async listGroups(): Promise<CountryGroup[]> {
    await this.ensureLoaded()
    return this.groups
  }

  /** Throws when a supplied code does not map to a known country. */
  async resolveCodes(codes: CountryCode[]): Promise<CountryCode[]> {
    await this.ensureLoaded()
    const normalized = [...new Set(codes.map((c) => c.toUpperCase()))].sort()
    const unknown = normalized.filter((c) => !this.byCode.has(c))
    if (unknown.length > 0) {
      throw new Error(`Unknown country code(s): ${unknown.join(', ')}`)
    }
    return normalized
  }

  /**
   * Filename is keyed on a hash of the sorted ISO codes + buffer size so
   * repeated calls with the same selection reuse the same path, and bumping
   * the buffer auto-invalidates stale files.
   */
  async writeRegionFile(codes: CountryCode[]): Promise<string> {
    await this.ensureLoaded()
    const resolved = await this.resolveCodes(codes)
    const key = `b${REGION_BUFFER_DEGREES}:${resolved.join(',')}`
    const hash = createHash('sha1').update(key).digest('hex').slice(0, 12)

    const dir = resolve(tmpdir(), 'nomad-pmtiles-regions')
    await mkdir(dir, { recursive: true })
    const filepath = join(dir, `region-${hash}.geojson`)

    try {
      await access(filepath)
      return filepath
    } catch {}

    const fc = {
      type: 'FeatureCollection',
      features: resolved.map((code) => {
        const entry = this.byCode.get(code)!
        return {
          type: 'Feature',
          properties: { iso: code, name: entry.country.name },
          geometry: bufferGeometry(entry.feature.geometry, REGION_BUFFER_DEGREES),
        }
      }),
    }

    await writeFile(filepath, JSON.stringify(fc))
    return filepath
  }
}

function typeRank(f: NEFeature): number {
  const t = typeof f.properties.TYPE === 'string' ? f.properties.TYPE : ''
  if (t === 'Sovereign country') return 0
  if (t === 'Country') return 1
  if (t === 'Sovereignty') return 2
  if (t === 'Disputed') return 3
  if (t === 'Dependency') return 4
  return 5
}

function resolveIso2(p: Record<string, any>): CountryCode | null {
  // Natural Earth's ISO_A2 sometimes holds political escapes like "CN-TW" for
  // Taiwan or "-99" for countries involved in disputes. Only accept clean
  // 2-letter codes; fall back to ISO_A2_EH (which reliably has the real code).
  const primary = typeof p.ISO_A2 === 'string' ? p.ISO_A2 : null
  if (primary && /^[A-Z]{2}$/i.test(primary)) return primary.toUpperCase()
  const fallback = typeof p.ISO_A2_EH === 'string' ? p.ISO_A2_EH : null
  if (fallback && /^[A-Z]{2}$/i.test(fallback)) return fallback.toUpperCase()
  return null
}

/**
 * Inflate each polygon ring outward by `buffer` degrees via per-vertex
 * averaged-normal offset. Not geodesically accurate — but at small buffers
 * (<= 0.2°) it's within a few percent of a proper geodesic buffer at
 * country scale, which is plenty for tile-inclusion purposes.
 */
function bufferGeometry(geometry: unknown, buffer: number): unknown {
  const geom = geometry as { type: string; coordinates: any }
  if (geom?.type === 'Polygon') {
    return { type: 'Polygon', coordinates: bufferPolygonRings(geom.coordinates, buffer) }
  }
  if (geom?.type === 'MultiPolygon') {
    return {
      type: 'MultiPolygon',
      coordinates: geom.coordinates.map((poly: number[][][]) =>
        bufferPolygonRings(poly, buffer)
      ),
    }
  }
  return geometry
}

function bufferPolygonRings(rings: number[][][], buffer: number): number[][][] {
  return rings.map((ring) => bufferRing(ring, buffer))
}

function bufferRing(ring: number[][], buffer: number): number[][] {
  if (ring.length < 4) return ring
  const sign = signedArea(ring) > 0 ? 1 : -1
  const n = ring.length - 1
  const out: number[][] = []
  for (let i = 0; i < n; i++) {
    const prev = ring[(i - 1 + n) % n]
    const curr = ring[i]
    const next = ring[(i + 1) % n]
    const e1x = curr[0] - prev[0]
    const e1y = curr[1] - prev[1]
    const e2x = next[0] - curr[0]
    const e2y = next[1] - curr[1]
    const l1 = Math.hypot(e1x, e1y) || 1
    const l2 = Math.hypot(e2x, e2y) || 1
    const n1x = (e1y / l1) * sign
    const n1y = (-e1x / l1) * sign
    const n2x = (e2y / l2) * sign
    const n2y = (-e2x / l2) * sign
    const sumX = n1x + n2x
    const sumY = n1y + n2y
    const sl = Math.hypot(sumX, sumY) || 1
    out.push([curr[0] + (sumX / sl) * buffer, curr[1] + (sumY / sl) * buffer])
  }
  out.push(out[0])
  return out
}

function signedArea(ring: number[][]): number {
  let a = 0
  for (let i = 0; i < ring.length - 1; i++) {
    a += ring[i][0] * ring[i + 1][1] - ring[i + 1][0] * ring[i][1]
  }
  return a / 2
}

function resolveIso3(p: Record<string, any>): string | null {
  const primary = typeof p.ISO_A3 === 'string' ? p.ISO_A3 : null
  if (primary && primary !== '-99') return primary.toUpperCase()
  const fallback = typeof p.ISO_A3_EH === 'string' ? p.ISO_A3_EH : null
  if (fallback && fallback !== '-99') return fallback.toUpperCase()
  const adm = typeof p.ADM0_A3 === 'string' ? p.ADM0_A3 : null
  if (adm && adm !== '-99') return adm.toUpperCase()
  return null
}

import env from '#start/env'
import logger from '@adonisjs/core/services/logger'
import { join } from 'node:path'
import { DockerService } from '#services/docker_service'
import { ZimService } from '#services/zim_service'
import { CollectionManifestService } from '#services/collection_manifest_service'
import { RunDownloadJob } from '#jobs/run_download_job'
import { ZIM_STORAGE_PATH } from '../utils/fs.js'
import { SERVICE_NAMES } from '../../constants/service_names.js'
import type { CreatorPacksSpec, CreatorPackWithStatus } from '../../types/collections.js'

// ZIMs report as octet-stream from the Worker (Content-Type is set explicitly to
// application/octet-stream in worker/src/index.js). Mirror the ZimService allowlist.
const ZIM_MIME_TYPES = ['application/x-zim', 'application/x-openzim', 'application/octet-stream']

// Default entitlement Worker origin. Overridable via CREATOR_PACKS_WORKER_BASE so
// we can move to a branded packs.projectnomad.us domain without a code change.
const DEFAULT_WORKER_BASE = 'https://nomad-packs-worker.chris-556.workers.dev'

/**
 * Outcome of an install request. Discriminated on `code` so the controller can
 * map each case to an HTTP status without string-matching thrown messages.
 * (See feedback: typed failure codes over ad-hoc Error parsing.)
 */
export type InstallPackResult =
  | { code: 'dispatched'; filename: string }
  | { code: 'already_installed' }
  | { code: 'already_downloading' }
  | { code: 'not_found' }
  | { code: 'not_configured' }

export type UninstallPackResult =
  | { code: 'uninstalled'; filename: string }
  | { code: 'not_installed' }

/**
 * Creator Packs install rail. Diverges from the curated-collections rail in
 * exactly one way: instead of a static manifest URL, the ZIM is fetched from the
 * entitlement Worker with a bearer `Authorization` header. From RunDownloadJob
 * onward everything is the shared rail (resumable download → InstalledResource →
 * Kiwix rebuildFromDisk). Video ZIMs opt out of KB embedding via skip_embedding.
 */
export class CreatorPackService {
  private dockerService: DockerService
  private manifestService: CollectionManifestService

  constructor(dockerService?: DockerService, manifestService?: CollectionManifestService) {
    this.dockerService = dockerService ?? new DockerService()
    this.manifestService = manifestService ?? new CollectionManifestService()
  }

  private get workerBase(): string {
    return (env.get('CREATOR_PACKS_WORKER_BASE') || DEFAULT_WORKER_BASE).replace(/\/+$/, '')
  }

  /**
   * Whether this build can actually install packs — i.e. the release-injected
   * app key is present. Forks built from source have no key; the UI uses this to
   * HIDE the Creator Packs surfaces entirely rather than show install buttons
   * that would 503. The public catalog still lists, but nothing is installable.
   */
  isConfigured(): boolean {
    return !!env.get('CREATOR_PACKS_APP_KEY')
  }

  /** Stable, per-version download URL. Not signed — the gate is the auth header. */
  packUrl(id: string, version: string): string {
    return `${this.workerBase}/packs/${id}_${version}.zim`
  }

  async listPacksWithStatus(): Promise<CreatorPackWithStatus[]> {
    return this.manifestService.getCreatorPacksWithStatus()
  }

  /**
   * Install a pack by catalog id: ensure Kiwix is present (auto-install if not),
   * then dispatch the gated ZIM download onto the shared rail.
   */
  async installPack(packId: string): Promise<InstallPackResult> {
    const appKey = env.get('CREATOR_PACKS_APP_KEY')
    if (!appKey) {
      logger.error('[CreatorPackService] CREATOR_PACKS_APP_KEY is not set; cannot install packs')
      return { code: 'not_configured' }
    }

    const spec = await this.manifestService.getSpecWithFallback<CreatorPacksSpec>('creator_packs')
    const pack = spec?.packs.find((p) => p.id === packId)
    if (!pack) {
      return { code: 'not_found' }
    }

    const { default: InstalledResource } = await import('#models/installed_resource')
    const existing = await InstalledResource.query()
      .where('resource_type', 'zim')
      .where('resource_id', pack.resource_id)
      .first()
    if (existing && existing.version === pack.version) {
      return { code: 'already_installed' }
    }

    const url = this.packUrl(pack.id, pack.version)
    if (await RunDownloadJob.getActiveByUrl(url)) {
      return { code: 'already_downloading' }
    }

    // Kiwix is a hard prerequisite — it's what serves the pack. Auto-install it if
    // absent (its own preinstall bootstraps a mini-wiki ZIM so the container can
    // start). Best-effort: if the install can't be kicked off we still download the
    // pack so the bytes are on disk; Kiwix hot-reloads it once installed.
    await this.ensureKiwixInstalled()

    const filename = `${pack.id}_${pack.version}.zim`
    const filepath = join(process.cwd(), ZIM_STORAGE_PATH, filename)

    await RunDownloadJob.dispatch({
      url,
      filepath,
      timeout: 30000,
      allowedMimeTypes: ZIM_MIME_TYPES,
      filetype: 'zim',
      title: pack.name,
      totalBytes: pack.size_mb ? pack.size_mb * 1024 * 1024 : undefined,
      requestHeaders: { Authorization: `Bearer ${appKey}` },
      resourceMetadata: {
        resource_id: pack.resource_id,
        version: pack.version,
        collection_ref: 'creator-packs',
        skip_embedding: true,
      },
    })

    logger.info(`[CreatorPackService] Dispatched download for pack ${pack.id} (${filename})`)
    return { code: 'dispatched', filename }
  }

  /**
   * Uninstall an installed pack: delete the ZIM (which via ZimService.delete also
   * removes it from the Kiwix library and clears its InstalledResource row).
   * Uses the INSTALLED version (not the catalog's) so we remove the file that's
   * actually on disk even if a newer version has since been published.
   */
  async uninstallPack(packId: string): Promise<UninstallPackResult> {
    const { default: InstalledResource } = await import('#models/installed_resource')
    const installed = await InstalledResource.query()
      .where('resource_type', 'zim')
      .where('resource_id', packId)
      .first()
    if (!installed) {
      return { code: 'not_installed' }
    }

    const filename = `${packId}_${installed.version}.zim`
    const zimService = new ZimService(this.dockerService)
    await zimService.delete(filename)

    logger.info(`[CreatorPackService] Uninstalled pack ${packId} (${filename})`)
    return { code: 'uninstalled', filename }
  }

  private async ensureKiwixInstalled(): Promise<void> {
    try {
      const kiwixUrl = await this.dockerService.getServiceURL(SERVICE_NAMES.KIWIX)
      if (kiwixUrl) return // already installed and resolvable

      logger.info('[CreatorPackService] Kiwix not installed; auto-installing before pack download')
      const result = await this.dockerService.createContainerPreflight(SERVICE_NAMES.KIWIX)
      if (!result.success) {
        // e.g. "already installing" — not fatal, the pack download proceeds regardless.
        logger.warn(`[CreatorPackService] Kiwix preflight did not start: ${result.message}`)
      }
    } catch (error: any) {
      logger.warn(
        `[CreatorPackService] Kiwix auto-install failed (continuing with pack download): ${error?.message || error}`
      )
    }
  }
}

import { dirname, normalize } from 'node:path'
import env from '#start/env'

/**
 * Security guardrails for user-defined ("custom app") containers.
 *
 * project-nomad runs containers as host siblings via the mounted Docker socket (DooD), so a
 * misconfigured bind mount or image is a real host-takeover vector. The posture here is
 * "guardrails with warnings": hard-block the genuinely catastrophic, warn-but-allow the merely
 * risky so a trusted admin keeps their power without an easy foot-gun.
 */

export interface GuardEvaluation {
  /** Hard rejections — the install cannot proceed until these are fixed. */
  blocked: string[]
  /** Advisory warnings — overridable via the "install anyway" force flag. */
  warnings: string[]
}

/** Absolute host directories that must never be bind-mounted into a custom container. */
const SYSTEM_BLOCK_PREFIXES = ['/etc', '/proc', '/sys', '/boot', '/dev', '/run', '/var/run']

/** Registries we ship curated apps from; anything else is allowed but warned on. */
const TRUSTED_REGISTRIES = ['docker.io', 'registry-1.docker.io', 'ghcr.io', 'lscr.io', 'quay.io']

/** Resolve the managed storage root (where bind mounts are expected to live). */
export function getStorageRoot(): string {
  return normalize(env.get('NOMAD_STORAGE_PATH', '/opt/project-nomad/storage')).replace(/\/+$/, '')
}

/** Normalize an absolute path: collapse `..`/`.` segments and strip any trailing slash. */
function normalizeHostPath(p: string): string {
  return normalize(p).replace(/\/+$/, '') || '/'
}

/** True when `child` equals `ancestor` or sits beneath it. */
function isWithin(child: string, ancestor: string): boolean {
  return child === ancestor || child.startsWith(ancestor + '/')
}

/**
 * Evaluate user-supplied bind mounts. Hard-blocks the Docker socket, core system directories,
 * and any mount at or above project-nomad's own install tree (which would expose its code/data).
 * Warns on any host path outside the managed storage root.
 */
export function evaluateBindMounts(
  volumes: { host_path: string; container_path: string }[]
): GuardEvaluation {
  const blocked: string[] = []
  const warnings: string[] = []

  const storageRoot = getStorageRoot()
  // The install tree is the parent of the storage root (e.g. /opt/project-nomad). Mounting it —
  // or any ancestor, up to and including `/` — would hand a container project-nomad's own files.
  const installRoot = dirname(storageRoot)

  for (const { host_path: hostPath, container_path: containerPath } of volumes) {
    const host = normalizeHostPath(hostPath)

    if (!hostPath.startsWith('/')) {
      blocked.push(`Volume host path "${hostPath}" must be an absolute path.`)
      continue
    }
    if (!containerPath.startsWith('/')) {
      blocked.push(`Volume container path "${containerPath}" must be an absolute path.`)
      continue
    }

    // A colon is Docker's bind delimiter (host:container:options). A path containing one would be
    // re-split by Docker into a different mount than the one validated here — reject it outright so
    // the checks below can't be bypassed by a parse-differential. (The validator blocks this too;
    // this keeps the guard self-defending for any caller that skips validation.)
    if (hostPath.includes(':') || containerPath.includes(':')) {
      blocked.push(`Volume paths must not contain a colon (":"): "${hostPath}" → "${containerPath}".`)
      continue
    }

    // The Docker socket is the most dangerous mount of all — full control of the host daemon.
    if (host.endsWith('docker.sock') || /\/docker\.sock$/.test(host)) {
      blocked.push(
        `Mounting the Docker socket ("${hostPath}") is not allowed — it grants full host control.`
      )
      continue
    }

    // Core system directories.
    if (host === '/' || SYSTEM_BLOCK_PREFIXES.some((p) => isWithin(host, p))) {
      blocked.push(`Mounting system directory "${hostPath}" is not allowed.`)
      continue
    }

    // At or above project-nomad's own install tree (covers `/`, `/opt`, `/opt/project-nomad`).
    if (host === installRoot || isWithin(installRoot, host)) {
      blocked.push(
        `Mounting "${hostPath}" would expose project-nomad's own files and is not allowed.`
      )
      continue
    }

    // Anything outside the managed storage root is allowed but flagged.
    if (!isWithin(host, storageRoot)) {
      warnings.push(
        `Volume "${hostPath}" is outside the managed storage root (${storageRoot}). Make sure you trust this image with access to that path.`
      )
    }
  }

  return { blocked, warnings }
}

/**
 * Evaluate a Docker image reference. Hard-blocks malformed references; warns on moving tags
 * (`:latest`/untagged) and images from registries outside the trusted set.
 */
export function evaluateImageReference(image: string): GuardEvaluation {
  const blocked: string[] = []
  const warnings: string[] = []

  const ref = image.trim()
  // Loose validity check: no whitespace/control chars, and a sane character set for an image ref.
  if (!ref || /\s/.test(ref) || !/^[\w./:@-]+$/.test(ref)) {
    blocked.push(`"${image}" is not a valid image reference.`)
    return { blocked, warnings }
  }

  // Split off any digest, then any tag, to inspect the registry and tag.
  const [nameAndTag] = ref.split('@')
  const firstSegment = nameAndTag.split('/')[0]
  const hasRegistryHost =
    nameAndTag.includes('/') && (firstSegment.includes('.') || firstSegment.includes(':'))
  const registry = hasRegistryHost ? firstSegment.split(':')[0] : 'docker.io'

  if (!TRUSTED_REGISTRIES.includes(registry)) {
    warnings.push(
      `Image is from "${registry}", which is outside project-nomad's trusted registries. Only install images you trust.`
    )
  }

  // Determine the tag (ignore a colon that's part of a registry host:port in the first segment).
  const remainder = hasRegistryHost ? nameAndTag.slice(firstSegment.length + 1) : nameAndTag
  const tag = remainder.includes(':') ? remainder.split(':').pop() : undefined
  const hasDigest = ref.includes('@sha256:')
  if (!hasDigest && (!tag || tag === 'latest')) {
    warnings.push(
      `Image "${image}" uses a moving tag (${tag ? ':latest' : 'no tag'}). Pin a specific version for reproducible installs.`
    )
  }

  return { blocked, warnings }
}

/** Combine bind-mount and image evaluations into a single result. */
export function evaluateCustomApp(input: {
  image?: string
  volumes?: { host_path: string; container_path: string }[]
}): GuardEvaluation {
  const bind = evaluateBindMounts(input.volumes ?? [])
  const img = input.image ? evaluateImageReference(input.image) : { blocked: [], warnings: [] }
  return {
    blocked: [...bind.blocked, ...img.blocked],
    warnings: [...bind.warnings, ...img.warnings],
  }
}

/** Default resource caps applied to custom containers unless the user overrides them. */
export const DEFAULT_MEMORY_MB = 1024
export const DEFAULT_CPUS = 1

import Service from '#models/service'
import Docker from 'dockerode'
import logger from '@adonisjs/core/services/logger'
import { inject } from '@adonisjs/core'
import transmit from '@adonisjs/transmit/services/main'
import { doResumableDownloadWithRetry } from '../utils/downloads.js'
import { pickAmdHsaOverride } from '../utils/amd_hsa_override.js'
import { join } from 'path'
import os from 'node:os'
import env from '#start/env'
import {
  ZIM_STORAGE_PATH,
  BOOKS_STORAGE_PATH,
  CALIBRE_EMPTY_LIBRARY_ASSET_PATH,
  VAULTWARDEN_STORAGE_PATH,
  MESHCORE_WEB_STORAGE_PATH,
  MEDIA_STORAGE_PATH,
  JELLYFIN_MEDIA_SUBFOLDERS,
} from '../utils/fs.js'
import { KiwixLibraryService } from './kiwix_library_service.js'
import { SERVICE_NAMES } from '../../constants/service_names.js'
import { exec } from 'child_process'
import { promisify } from 'util'
import { readFile, mkdir, copyFile, chown, chmod, access, writeFile } from 'node:fs/promises'
import { randomBytes } from 'node:crypto'
import KVStore from '#models/kv_store'
import { BROADCAST_CHANNELS } from '../../constants/broadcast.js'
import { KIWIX_LIBRARY_CMD } from '../../constants/kiwix.js'
import { DEFAULT_OLLAMA_CONTEXT_LENGTH } from '../../constants/ollama.js'

// Written by install_nomad.sh with the host AMD GPU's gfx target.
const AMD_GFX_MARKER_PATH = '/app/storage/.nomad-amd-gfx'

@inject()
export class DockerService {
  public docker: Docker
  private activeInstallations: Set<string> = new Set()
  public static NOMAD_NETWORK = 'project-nomad_default'
  public static ADMIN_CONTAINER_NAME = 'nomad_admin'
  // The admin's own storage mount destination inside its container (compose maps
  // <hostPath>:/app/storage). Used to locate the backing host path (#938).
  public static ADMIN_STORAGE_DEST = '/app/storage'
  // Hardcoded production default host storage root. A seeded/frozen child bind can
  // still carry this prefix even after NOMAD_STORAGE_PATH is set elsewhere, so it's
  // matched alongside the env value when relocating binds (#938).
  public static DEFAULT_HOST_STORAGE_ROOT = '/opt/project-nomad/storage'

  // Resolved once: the host filesystem path backing the admin's /app/storage mount.
  // Child-service binds are rewritten to live under this so relocating the admin
  // storage volume relocates every child app too (#938). null = not yet resolved.
  private _hostStorageRoot: string | null = null

  private _servicesStatusCache: { data: { service_name: string; status: string }[]; expiresAt: number } | null = null
  private _servicesStatusInflight: Promise<{ service_name: string; status: string }[]> | null = null

  constructor() {
    // Support both Linux (production) and Windows (development with Docker Desktop)
    const isWindows = process.platform === 'win32'
    if (isWindows) {
      // Windows Docker Desktop uses named pipe
      this.docker = new Docker({ socketPath: '//./pipe/docker_engine' })
    } else {
      // Linux uses Unix socket
      this.docker = new Docker({ socketPath: '/var/run/docker.sock' })
    }
  }

  /**
   * Pull a Docker image and resolve only when the pull genuinely completes.
   *
   * dockerode's `followProgress(stream, onFinished)` reports failures via the
   * first argument of onFinished. Every call site used to pass the Promise's
   * `resolve` directly as that callback, so a failed pull (dropped/metered
   * connection, bad manifest, registry error, disk full mid-pull) resolved as
   * if it had succeeded — and the code then tried to create/start a container
   * from a missing or partial image, surfacing a confusing downstream error.
   * Rejecting on that error here lets callers fail fast with the real cause (#790).
   */
  async pullImage(imageName: string): Promise<void> {
    const pullStream = await this.docker.pull(imageName)
    await new Promise<void>((resolve, reject) => {
      this.docker.modem.followProgress(pullStream, (error: Error | null) => {
        if (error) reject(error)
        else resolve()
      })
    })
  }

  async affectContainer(
    serviceName: string,
    action: 'start' | 'stop' | 'restart'
  ): Promise<{ success: boolean; message: string }> {
    try {
      const service = await Service.query().where('service_name', serviceName).first()
      if (!service || !service.installed) {
        return {
          success: false,
          message: `Service ${serviceName} not found or not installed`,
        }
      }

      const containers = await this.docker.listContainers({ all: true })
      const container = containers.find((c) => c.Names.includes(`/${serviceName}`))
      if (!container) {
        return {
          success: false,
          message: `Container for service ${serviceName} not found`,
        }
      }

      const dockerContainer = this.docker.getContainer(container.Id)
      if (action === 'stop') {
        await dockerContainer.stop()
        this.invalidateServicesStatusCache()
        return {
          success: true,
          message: `Service ${serviceName} stopped successfully`,
        }
      }

      if (action === 'restart') {
        if (serviceName === SERVICE_NAMES.KIWIX) {
          const isLegacy = await this.isKiwixOnLegacyConfig()
          if (isLegacy) {
            logger.info('[DockerService] Kiwix on legacy glob config — running migration instead of restart.')
            await this.migrateKiwixToLibraryMode()
            this.invalidateServicesStatusCache()
            return { success: true, message: 'Kiwix migrated to library mode successfully.' }
          }
        }

        await dockerContainer.restart()
        this.invalidateServicesStatusCache()

        return {
          success: true,
          message: `Service ${serviceName} restarted successfully`,
        }
      }

      if (action === 'start') {
        if (container.State === 'running') {
          return {
            success: true,
            message: `Service ${serviceName} is already running`,
          }
        }

        await dockerContainer.start()
        this.invalidateServicesStatusCache()

        return {
          success: true,
          message: `Service ${serviceName} started successfully`,
        }
      }

      return {
        success: false,
        message: `Invalid action: ${action}. Use 'start', 'stop', or 'restart'.`,
      }
    } catch (error: any) {
      logger.error({ err: error }, `[DockerService] Error controlling service ${serviceName}`)
      return {
        success: false,
        message: `Failed to ${action} service ${serviceName}. Check server logs for details.`,
      }
    }
  }

  /**
   * Fetches the status of all Docker containers related to Nomad services. (those prefixed with 'nomad_')
   * Results are cached for 5 seconds and concurrent callers share a single in-flight request,
   * preventing Docker socket congestion during rapid page navigation.
   */
  async getServicesStatus(): Promise<{ service_name: string; status: string }[]> {
    const now = Date.now()
    if (this._servicesStatusCache && now < this._servicesStatusCache.expiresAt) {
      return this._servicesStatusCache.data
    }
    if (this._servicesStatusInflight) return this._servicesStatusInflight

    this._servicesStatusInflight = this._fetchServicesStatus().then((data) => {
      this._servicesStatusCache = { data, expiresAt: Date.now() + 5000 }
      this._servicesStatusInflight = null
      return data
    }).catch((err) => {
      this._servicesStatusInflight = null
      throw err
    })
    return this._servicesStatusInflight
  }

  /**
   * Invalidates the services status cache. Call this after any container state change
   * (start, stop, restart, install, uninstall) so the next read reflects reality.
   */
  invalidateServicesStatusCache() {
    this._servicesStatusCache = null
    this._servicesStatusInflight = null
  }

  private async _fetchServicesStatus(): Promise<{ service_name: string; status: string }[]> {
    try {
      const containers = await this.docker.listContainers({ all: true })
      const containerMap = new Map<string, Docker.ContainerInfo>()
      containers.forEach((container) => {
        const name = container.Names[0]?.replace('/', '')
        if (name && name.startsWith('nomad_')) {
          containerMap.set(name, container)
        }
      })

      return Array.from(containerMap.entries()).map(([name, container]) => ({
        service_name: name,
        status: container.State,
      }))
    } catch (error: any) {
      logger.error(`Error fetching services status: ${error.message}`)
      return []
    }
  }

  /**
   * Get the URL to access a service based on its configuration.
   * Attempts to return a docker-internal URL using the service name and exposed port.
   * @param serviceName - The name of the service to get the URL for.
   * @returns - The URL as a string, or null if it cannot be determined.
   */
  async getServiceURL(serviceName: string): Promise<string | null> {
    if (!serviceName || serviceName.trim() === '') {
      return null
    }

    if (serviceName === SERVICE_NAMES.OLLAMA) {
      const remoteUrl = await KVStore.getValue('ai.remoteOllamaUrl')
      if (remoteUrl) return remoteUrl
    }

    const service = await Service.query()
      .where('service_name', serviceName)
      .andWhere('installed', true)
      .first()

    if (!service) {
      return null
    }

    const hostname = process.env.NODE_ENV === 'production' ? serviceName : 'localhost'

    // "https:8480" / "http:8480" — explicit scheme + port (e.g. an app serving its own TLS).
    const schemePort = service.ui_location?.match(/^(https?):(\d+)$/)
    if (schemePort) {
      return `${schemePort[1]}://${hostname}:${schemePort[2]}`
    }

    // First, check if ui_location is set and is a valid port number
    if (service.ui_location && parseInt(service.ui_location, 10)) {
      return `http://${hostname}:${service.ui_location}`
    }

    // Next, try to extract a host port from container_config
    const parsedConfig = this._parseContainerConfig(service.container_config)
    if (parsedConfig?.HostConfig?.PortBindings) {
      const portBindings = parsedConfig.HostConfig.PortBindings
      const hostPorts = Object.values(portBindings)
      if (!hostPorts || !Array.isArray(hostPorts) || hostPorts.length === 0) {
        return null
      }

      const hostPortsArray = hostPorts.flat() as { HostPort: string }[]
      const hostPortsStrings = hostPortsArray.map((binding) => binding.HostPort)
      if (hostPortsStrings.length > 0) {
        return `http://${hostname}:${hostPortsStrings[0]}`
      }
    }

    // Otherwise, return null if we can't determine a URL
    return null
  }

  async createContainerPreflight(
    serviceName: string
  ): Promise<{ success: boolean; message: string }> {
    const service = await Service.query().where('service_name', serviceName).first()
    if (!service) {
      return {
        success: false,
        message: `Service ${serviceName} not found`,
      }
    }

    if (service.installed) {
      return {
        success: false,
        message: `Service ${serviceName} is already installed`,
      }
    }

    // Check if installation is already in progress (database-level)
    if (service.installation_status === 'installing') {
      return {
        success: false,
        message: `Service ${serviceName} installation is already in progress`,
      }
    }

    // Double-check with in-memory tracking (race condition protection)
    if (this.activeInstallations.has(serviceName)) {
      return {
        success: false,
        message: `Service ${serviceName} installation is already in progress`,
      }
    }

    // Mark installation as in progress
    this.activeInstallations.add(serviceName)
    service.installation_status = 'installing'
    await service.save()

    // Check if a service wasn't marked as installed but has an existing container
    // This can happen if the service was created but not properly installed
    // or if the container was removed manually without updating the service status.
    // if (await this._checkIfServiceContainerExists(serviceName)) {
    //   const removeResult = await this._removeServiceContainer(serviceName);
    //   if (!removeResult.success) {
    //     return {
    //       success: false,
    //       message: `Failed to remove existing container for service ${serviceName}: ${removeResult.message}`,
    //     };
    //   }
    // }

    const containerConfig = this._parseContainerConfig(service.container_config)

    // Execute installation asynchronously and handle cleanup
    this._createContainer(service, containerConfig).catch(async (error) => {
      logger.error(`Installation failed for ${serviceName}: ${error.message}`)
      await this._cleanupFailedInstallation(serviceName)
    })

    return {
      success: true,
      message: `Service ${serviceName} installation initiated successfully. You can receive updates via server-sent events.`,
    }
  }

  /**
   * Force reinstall a service by stopping, removing, and recreating its container.
   *
   * Volume handling: removes Docker-managed named volumes whose name equals
   * `serviceName`, starts with `${serviceName}_`, or carries a `service=${serviceName}`
   * label. Host bind mounts are NOT touched — any data living on a bind-mounted
   * host path (ZIM stores, model caches, MySQL data dir, etc.) survives the reinstall.
   * Anonymous volumes (random hash names) are also not matched.
   */
  async forceReinstall(serviceName: string): Promise<{ success: boolean; message: string }> {
    try {
      const service = await Service.query().where('service_name', serviceName).first()
      if (!service) {
        return {
          success: false,
          message: `Service ${serviceName} not found`,
        }
      }

      // Check if installation is already in progress
      if (this.activeInstallations.has(serviceName)) {
        return {
          success: false,
          message: `Service ${serviceName} installation is already in progress`,
        }
      }

      // Mark as installing to prevent concurrent operations
      this.activeInstallations.add(serviceName)
      service.installation_status = 'installing'
      await service.save()

      this._broadcast(
        serviceName,
        'reinstall-starting',
        `Starting force reinstall for ${serviceName}...`
      )

      // Step 1: Try to stop and remove the container if it exists
      try {
        const containers = await this.docker.listContainers({ all: true })
        const container = containers.find((c) => c.Names.includes(`/${serviceName}`))

        if (container) {
          const dockerContainer = this.docker.getContainer(container.Id)

          if (serviceName === SERVICE_NAMES.OLLAMA) {
            // The recreate builds env from scratch, so capture a working HSA override
            // before this container, the only place it lives, is removed (#1377).
            try {
              const inspect = await dockerContainer.inspect()
              await this._adoptContainerHsaOverride(inspect.Config?.Env)
            } catch (error: any) {
              logger.warn(`[DockerService] Could not preserve the Ollama HSA override: ${error.message}`)
            }
          }

          // Only try to stop if it's running
          if (container.State === 'running') {
            this._broadcast(serviceName, 'stopping', `Stopping container...`)
            await dockerContainer.stop({ t: 10 }).catch((error) => {
              // If already stopped, continue
              if (!error.message.includes('already stopped')) {
                logger.warn(`Error stopping container: ${error.message}`)
              }
            })
          }

          // Step 2: Remove the container
          this._broadcast(serviceName, 'removing', `Removing container...`)
          await dockerContainer.remove({ force: true }).catch((error) => {
            logger.warn(`Error removing container: ${error.message}`)
          })
        } else {
          this._broadcast(
            serviceName,
            'no-container',
            `No existing container found, proceeding with installation...`
          )
        }
      } catch (error: any) {
        logger.warn({ err: error }, `[DockerService] Error during container cleanup for ${serviceName}`)
        this._broadcast(serviceName, 'cleanup-warning', 'Warning during container cleanup. Check server logs for details.')
      }

      // Step 3: Clear volumes/data if needed
      try {
        this._broadcast(serviceName, 'clearing-volumes', `Checking for volumes to clear...`)
        const volumes = await this.docker.listVolumes()
        const serviceVolumes =
          volumes.Volumes?.filter(
            (v) =>
              v.Name === serviceName ||
              v.Name.startsWith(`${serviceName}_`) ||
              v.Labels?.service === serviceName
          ) || []

        for (const vol of serviceVolumes) {
          try {
            const volume = this.docker.getVolume(vol.Name)
            await volume.remove({ force: true })
            this._broadcast(serviceName, 'volume-removed', `Removed volume: ${vol.Name}`)
          } catch (error: any) {
            logger.warn(`Failed to remove volume ${vol.Name}: ${error.message}`)
          }
        }

        if (serviceVolumes.length === 0) {
          this._broadcast(serviceName, 'no-volumes', `No volumes found to clear`)
        }
      } catch (error: any) {
        logger.warn({ err: error }, `[DockerService] Error during volume cleanup for ${serviceName}`)
        this._broadcast(
          serviceName,
          'volume-cleanup-warning',
          'Warning during volume cleanup. Check server logs for details.'
        )
      }

      // Step 4: Mark service as uninstalled
      service.installed = false
      service.installation_status = 'installing'
      await service.save()
      this.invalidateServicesStatusCache()

      // Step 5: Recreate the container
      this._broadcast(serviceName, 'recreating', `Recreating container...`)
      const containerConfig = this._parseContainerConfig(service.container_config)

      // Execute installation asynchronously and handle cleanup
      this._createContainer(service, containerConfig).catch(async (error) => {
        logger.error(`Reinstallation failed for ${serviceName}: ${error.message}`)
        await this._cleanupFailedInstallation(serviceName)
      })

      return {
        success: true,
        message: `Service ${serviceName} force reinstall initiated successfully. You can receive updates via server-sent events.`,
      }
    } catch (error: any) {
      logger.error({ err: error }, `[DockerService] Force reinstall failed for ${serviceName}`)
      await this._cleanupFailedInstallation(serviceName)
      return {
        success: false,
        message: `Failed to force reinstall service ${serviceName}. Check server logs for details.`,
      }
    }
  }

  /**
   * Translate low-level dockerode errors into something a non-technical user can
   * act on. Currently handles host port conflicts — the most common install
   * failure, where a service can't bind its port because something on the host
   * already holds it (classic case: a native Ollama install owns 11434). Returns
   * the original message unchanged for anything we don't recognize. (#934)
   */
  private _humanizeDockerError(error: any, serviceName: string): string {
    const raw: string = error?.message ?? String(error)
    // dockerode surfaces port conflicts as e.g.
    //   "...Bind for 0.0.0.0:11434 failed: port is already allocated"
    //   "...listen tcp 0.0.0.0:8090: bind: address already in use"
    const portMatch = raw.match(/(?:Bind for [^:]+:(\d+) failed: port is already allocated|:(\d+): bind: address already in use)/i)
    if (portMatch) {
      const port = portMatch[1] || portMatch[2]
      const portText = port ? `port ${port}` : 'a required port'
      if (port === '11434' || serviceName === SERVICE_NAMES.OLLAMA) {
        return `Couldn't start because ${portText} is already in use on this machine. This usually means Ollama is already installed and running directly on the host (outside NOMAD). Stop and disable the host Ollama service (e.g. "sudo systemctl stop ollama" then "sudo systemctl disable ollama"), then try again.`
      }
      return `Couldn't start because ${portText} is already in use on this machine. Stop whatever is using ${portText} on the host, then try again.`
    }
    return raw
  }

  /**
   * Resolve the host filesystem path that backs the admin container's storage
   * directory (`/app/storage`). Child services are created via the Docker socket,
   * so their bind mounts need the path on the *host*, not inside the admin
   * container. Deriving it from the admin's own mount means whatever host path
   * the admin storage volume is mapped to in compose, child apps follow it
   * automatically (#938).
   *
   * Falls back to NOMAD_STORAGE_PATH / the production default if the admin
   * container or its storage mount can't be inspected.
   */
  /**
   * Public accessor for the resolved host path backing `/app/storage`. Used by the
   * Debug Info bundle so support can see where content actually lives on the host
   * (the #1050 class of "moved my data, admin doesn't see it" reports).
   */
  async getHostStorageRoot(): Promise<string> {
    return this._resolveHostStorageRoot()
  }

  private async _resolveHostStorageRoot(): Promise<string> {
    if (this._hostStorageRoot) return this._hostStorageRoot
    const fallback = env.get('NOMAD_STORAGE_PATH', DockerService.DEFAULT_HOST_STORAGE_ROOT)
    try {
      const adminStorageDest = DockerService.ADMIN_STORAGE_DEST
      const containers = await this.docker.listContainers({ all: true })
      // Prefer the well-known admin container name; fall back to matching this
      // process's own container by hostname (Docker defaults it to the short id).
      let adminInfo = containers.find((c) =>
        c.Names.includes(`/${DockerService.ADMIN_CONTAINER_NAME}`)
      )
      if (!adminInfo) {
        const hn = os.hostname()
        adminInfo = containers.find((c) => c.Id.startsWith(hn))
      }
      if (!adminInfo) return (this._hostStorageRoot = fallback)

      const inspected = await this.docker.getContainer(adminInfo.Id).inspect()
      const mount = (inspected.Mounts ?? []).find(
        (m: any) => m.Type === 'bind' && m.Destination === adminStorageDest
      )
      if (mount?.Source) {
        logger.info(`[DockerService] Resolved host storage root from admin mount: ${mount.Source}`)
        return (this._hostStorageRoot = mount.Source)
      }
      return (this._hostStorageRoot = fallback)
    } catch (err: any) {
      logger.warn(
        `[DockerService] Could not resolve host storage root, using fallback ${fallback}: ${err.message}`
      )
      // Deliberately NOT cached: a transient Docker error (e.g. socket not ready at
      // early boot) shouldn't lock this process into the fallback for its lifetime —
      // caching here could permanently re-hide #938 after Docker recovers. Retry next call.
      return fallback
    }
  }

  /**
   * Rewrite the host side of a service's storage bind mounts so they point at the
   * resolved host storage root. If the admin storage actually lives elsewhere on the
   * host, swap a known storage-root prefix so the child container mounts the same
   * physical location (#938).
   *
   * A bind's prefix may be the current NOMAD_STORAGE_PATH *or* the hardcoded default:
   * curated services re-bake their config from the env every boot, but user-modified
   * curated services and custom apps freeze their binds at edit time and can still
   * carry the default prefix even after NOMAD_STORAGE_PATH is changed. Matching both
   * (rather than only the current env, and short-circuiting when env == root) means
   * the documented "set NOMAD_STORAGE_PATH and relocate the volume" path also fixes
   * those frozen-prefix apps instead of leaving them mounting an empty directory.
   * Idempotent: binds already under `root` match no other prefix and are left alone.
   */
  private async _applyHostStorageRoot(containerConfig: any): Promise<void> {
    const binds: string[] | undefined = containerConfig?.HostConfig?.Binds
    if (!binds?.length) return
    const root = await this._resolveHostStorageRoot()
    // Known host-side prefixes a seeded/frozen bind might carry. Exclude `root` itself
    // so binds already pointing at the resolved location are never rewritten.
    const seededRoots = [
      env.get('NOMAD_STORAGE_PATH', DockerService.DEFAULT_HOST_STORAGE_ROOT),
      DockerService.DEFAULT_HOST_STORAGE_ROOT,
    ].filter((r) => r !== root)
    if (!seededRoots.length) return
    containerConfig.HostConfig.Binds = binds.map((b) => {
      // bind format: "<hostSrc>:<containerDest>[:opts]" — hostSrc is a Linux abs path.
      const firstColon = b.indexOf(':')
      if (firstColon < 0) return b
      const hostSrc = b.slice(0, firstColon)
      const rest = b.slice(firstColon) // includes leading ':'
      const seededRoot = seededRoots.find(
        (r) => hostSrc === r || hostSrc.startsWith(r + '/')
      )
      if (seededRoot) {
        return `${root}${hostSrc.slice(seededRoot.length)}${rest}`
      }
      return b
    })
  }

  /**
   * Handles the long-running process of creating a Docker container for a service.
   * NOTE: This method should not be called directly. Instead, use `createContainerPreflight` to check prerequisites first
   * This method will also transmit server-sent events to the client to notify of progress.
   * @param serviceName
   * @returns
    */
  async _createContainer(
    service: Service & { dependencies?: Service[] },
    containerConfig: any
  ): Promise<void> {
    try {
      this._broadcast(service.service_name, 'initializing', '')

      // Point storage binds at wherever the admin's storage volume actually lives
      // on the host (covers dependency installs too — they recurse through here).
      await this._applyHostStorageRoot(containerConfig)

      let dependencies = []
      if (service.depends_on) {
        const dependency = await Service.query().where('service_name', service.depends_on).first()
        if (dependency) {
          dependencies.push(dependency)
        }
      }

      // First, check if the service has any dependencies that need to be installed first
      if (dependencies && dependencies.length > 0) {
        this._broadcast(
          service.service_name,
          'checking-dependencies',
          `Checking dependencies for service ${service.service_name}...`
        )
        for (const dependency of dependencies) {
          if (!dependency.installed) {
            this._broadcast(
              service.service_name,
              'dependency-not-installed',
              `Dependency service ${dependency.service_name} is not installed. Installing it first...`
            )
            await this._createContainer(
              dependency,
              this._parseContainerConfig(dependency.container_config)
            )
          } else {
            this._broadcast(
              service.service_name,
              'dependency-installed',
              `Dependency service ${dependency.service_name} is already installed.`
            )
          }
        }
      }

      const imageExists = await this._checkImageExists(service.container_image)
      if (imageExists) {
        this._broadcast(
          service.service_name,
          'image-exists',
          `Docker image ${service.container_image} already exists locally. Skipping pull...`
        )
      } else {
        // Start pulling the Docker image and wait for it to complete
        this._broadcast(
          service.service_name,
          'pulling',
          `Pulling Docker image ${service.container_image}...`
        )
        await this.pullImage(service.container_image)
      }

      if (service.service_name === SERVICE_NAMES.KIWIX) {
        await this._runPreinstallActions__KiwixServe()
        this._broadcast(
          service.service_name,
          'preinstall-complete',
          `Pre-install actions for Kiwix Serve completed successfully.`
        )
      }

      if (service.service_name === SERVICE_NAMES.CALIBREWEB) {
        await this._runPreinstallActions__CalibreWeb()
        this._broadcast(
          service.service_name,
          'preinstall-complete',
          `Pre-install actions for Calibre-Web completed successfully.`
        )
      }

      if (service.service_name === SERVICE_NAMES.VAULTWARDEN) {
        await this._runPreinstallActions__Vaultwarden()
        this._broadcast(
          service.service_name,
          'preinstall-complete',
          `Pre-install actions for Vaultwarden completed successfully.`
        )
      }

      if (service.service_name === SERVICE_NAMES.JELLYFIN) {
        await this._runPreinstallActions__Jellyfin()
        this._broadcast(
          service.service_name,
          'preinstall-complete',
          `Pre-install actions for Jellyfin completed successfully.`
        )
      }

      if (service.service_name === SERVICE_NAMES.MESHCORE_WEB) {
        await this._runPreinstallActions__MeshCoreWeb()
        this._broadcast(
          service.service_name,
          'preinstall-complete',
          `Pre-install actions for MeshCore Web completed successfully.`
        )
      }

      // GPU-aware configuration for Ollama
      let finalImage = service.container_image
      let gpuHostConfig = containerConfig?.HostConfig || {}
      let amdGpuConfigured = false

      if (service.service_name === SERVICE_NAMES.OLLAMA) {
        const gpuResult = await this._detectGPUType()

        if (gpuResult.type === 'nvidia') {
          this._broadcast(
            service.service_name,
            'gpu-config',
            `NVIDIA container runtime detected. Configuring container with GPU support...`
          )

          // Add GPU support for NVIDIA
          gpuHostConfig = {
            ...gpuHostConfig,
            DeviceRequests: [
              {
                Driver: 'nvidia',
                Count: -1, // -1 means all GPUs
                Capabilities: [['gpu']],
              },
            ],
          }
        } else if (gpuResult.type === 'amd') {
          // AMD acceleration is opt-out via the 'ai.amdGpuAcceleration' KV key (default-on).
          // Per memory feedback: KV values can be string or boolean — coerce explicitly.
          const amdEnabledRaw = await KVStore.getValue('ai.amdGpuAcceleration')
          const amdAccelerationEnabled = String(amdEnabledRaw) !== 'false'

          if (amdAccelerationEnabled) {
            this._broadcast(
              service.service_name,
              'gpu-config',
              `AMD GPU detected. Using ROCm image with /dev/kfd and /dev/dri passthrough...`
            )

            finalImage = 'ollama/ollama:rocm'

            // The pull-if-missing earlier in this function used service.container_image
            // (the DB-pinned tag, e.g. ollama/ollama:0.18.2). The AMD branch overrides
            // to a different tag — so we need to pull :rocm separately if it's not local.
            const rocmImageExists = await this._checkImageExists(finalImage)
            if (!rocmImageExists) {
              this._broadcast(
                service.service_name,
                'pulling',
                `Pulling Docker image ${finalImage}...`
              )
              await this.pullImage(finalImage)
            }

            const amdDevices = await this._discoverAMDDevices()
            gpuHostConfig = {
              ...gpuHostConfig,
              Devices: amdDevices,
            }
            amdGpuConfigured = true
            logger.info(
              `[DockerService] Configured ROCm image and ${amdDevices.length} AMD device entries for Ollama`
            )
          } else {
            this._broadcast(
              service.service_name,
              'gpu-config',
              `AMD GPU detected but acceleration is disabled via ai.amdGpuAcceleration. Using CPU-only configuration.`
            )
            logger.info('[DockerService] AMD GPU acceleration disabled by KV opt-out; using CPU-only configuration.')
          }
        } else if (gpuResult.toolkitMissing) {
          this._broadcast(
            service.service_name,
            'gpu-config',
            `NVIDIA GPU detected but NVIDIA Container Toolkit is not installed. Using CPU-only configuration. Install the toolkit and reinstall AI Assistant for GPU acceleration: https://docs.nvidia.com/datacenter/cloud-native/container-toolkit/latest/install-guide.html`
          )
        } else {
          this._broadcast(
            service.service_name,
            'gpu-config',
            `No GPU detected. Using CPU-only configuration...`
          )
        }
      }

      const ollamaEnv: string[] = []
      if (service.service_name === SERVICE_NAMES.OLLAMA) {
        ollamaEnv.push('OLLAMA_NO_CLOUD=1')
        const flashAttentionEnabled = await KVStore.getValue('ai.ollamaFlashAttention')
        if (flashAttentionEnabled !== false) {
          ollamaEnv.push('OLLAMA_FLASH_ATTENTION=1')
          // KV cache quantization requires flash attention. q8_0 roughly halves the
          // memory a context window costs for a perplexity delta in the noise, which is
          // what makes an 8-16k window affordable on modest hardware. Ollama silently
          // falls back to f16 on architectures that don't support it, so this is treated
          // as headroom — the context-window resolver still budgets against f16.
          ollamaEnv.push('OLLAMA_KV_CACHE_TYPE=q8_0')
        }
        // Floor for any request that doesn't carry its own num_ctx (the OpenAI-compatible
        // path can't set one at all). Ollama's own default is 4096 on machines under 24GB
        // VRAM, and anything past the window is silently truncated with no error — so a
        // conversation that outgrows it just quietly loses its early turns.
        ollamaEnv.push(`OLLAMA_CONTEXT_LENGTH=${DEFAULT_OLLAMA_CONTEXT_LENGTH}`)
        if (amdGpuConfigured) {
          // gfx-aware HSA override — only set for cards that actually need it. See
          // _resolveAmdHsaOverride() for the resolution order and gfx → version mapping.
          const hsaOverride = await this._resolveAmdHsaOverride()
          if (hsaOverride) {
            ollamaEnv.push(`HSA_OVERRIDE_GFX_VERSION=${hsaOverride}`)
          }
          // Ollama's scheduler drops integrated GPUs unless this is set (issue #1056), so
          // AMD APUs (780M/890M/8060S) fall back to CPU-only despite correct device
          // passthrough. It's a no-op on discrete AMD cards, so it's safe to set whenever
          // AMD acceleration is configured.
          ollamaEnv.push('OLLAMA_IGPU_ENABLE=1')
        }
      }

      const appEnv: string[] = []
      if (service.service_name === SERVICE_NAMES.HOMEBOX) {
        // Homebox >= 0.26 panics at boot without a >= 32-byte pepper (#1043). Generate once,
        // persist, and reuse so updates/reinstalls don't invalidate issued API keys.
        appEnv.push(`HBOX_AUTH_API_KEY_PEPPER=${await this._resolveHomeboxPepper()}`)
      }

      this._broadcast(
        service.service_name,
        'creating',
        `Creating Docker container for service ${service.service_name}...`
      )
      // Built once and reused, so the AMD fallback below cannot drift from the
      // real payload as this config grows.
      const buildCreateOptions = (image: string, hostConfig: any, env: string[]) => ({
        Image: image,
        name: service.service_name,
        Labels: {
          ...(containerConfig?.Labels ?? {}),
          'com.docker.compose.project': 'project-nomad-managed',
          'io.project-nomad.managed': 'true',
        },
        ...(containerConfig?.User && { User: containerConfig.User }),
        HostConfig: hostConfig,
        ...(containerConfig?.WorkingDir && { WorkingDir: containerConfig.WorkingDir }),
        ...(containerConfig?.ExposedPorts && { ExposedPorts: containerConfig.ExposedPorts }),
        Env: env,
        ...(service.container_command ? { Cmd: service.container_command.split(' ') } : {}),
        // Ensure container is attached to the Nomad docker network in production
        ...(process.env.NODE_ENV === 'production' && {
          NetworkingConfig: {
            EndpointsConfig: {
              [DockerService.NOMAD_NETWORK]: {},
            },
          },
        }),
      })

      let container = await this.docker.createContainer(
        buildCreateOptions(finalImage, gpuHostConfig, [
          ...(containerConfig?.Env ?? []),
          ...ollamaEnv,
          ...appEnv,
        ])
      )

      this._broadcast(
        service.service_name,
        'starting',
        `Starting Docker container for service ${service.service_name}...`
      )
      try {
        await container.start()
      } catch (error: any) {
        // An AMD GPU whose ROCm device nodes are absent must not block the install
        // outright (#1232). GPU detection reads PCI data, so "an AMD GPU is present"
        // and "ROCm is usable" are different questions, and only the daemon can
        // answer the second. CPU-only Ollama works fine on these machines.
        //
        // This has to sit on start(), not createContainer(): the daemon accepts a
        // container whose --device path does not exist (create returns 201) and only
        // resolves devices when the container starts. Measured on Docker 29.6.2.
        //
        // Retrying rather than pre-checking is also deliberate. The admin runs in its
        // own container, so stat()ing /dev/kfd here describes the admin's namespace,
        // not the host's. Verified on NOMAD6, a working ROCm box: /dev/kfd is present
        // on the host and absent inside the admin container, so a pre-check would
        // strip GPU passthrough from a machine where it works.
        if (!amdGpuConfigured || !this._isMissingDeviceError(error)) throw error

        logger.warn(
          `[DockerService] AMD device passthrough rejected by the daemon (${error?.message}); ` +
            `recreating ${service.service_name} CPU-only on ${service.container_image}`
        )
        this._broadcast(
          service.service_name,
          'gpu-config',
          `AMD GPU detected, but this system has no usable ROCm device (/dev/kfd is missing, ` +
            `which means the amdgpu/ROCm kernel driver is not loaded or does not support this GPU). ` +
            `Installing CPU-only instead so the AI Assistant still works.`
        )

        // The created container carries the rejected device config, so it cannot be
        // started as-is and has to go before the name can be reused.
        await container.remove({ force: true }).catch((removeError: any) => {
          logger.warn(`[DockerService] Could not remove the failed container: ${removeError?.message}`)
        })

        const { Devices, ...cpuHostConfig } = gpuHostConfig as any
        // Drop the ROCm-only env along with the devices. HSA_OVERRIDE_GFX_VERSION and
        // OLLAMA_IGPU_ENABLE mean nothing to the CPU build, and leaving them behind is
        // misleading to anyone who later reads `docker inspect`.
        const cpuOllamaEnv = ollamaEnv.filter(
          (e) => !e.startsWith('HSA_OVERRIDE_GFX_VERSION=') && !e.startsWith('OLLAMA_IGPU_ENABLE=')
        )
        amdGpuConfigured = false
        // service.container_image is the CPU tag, already pulled earlier in this
        // function before the AMD branch overrode finalImage to :rocm.
        finalImage = service.container_image
        container = await this.docker.createContainer(
          buildCreateOptions(finalImage, cpuHostConfig, [
            ...(containerConfig?.Env ?? []),
            ...cpuOllamaEnv,
            ...appEnv,
          ])
        )
        await container.start()
      }

      this._broadcast(
        service.service_name,
        'finalizing',
        `Finalizing installation of service ${service.service_name}...`
      )
      service.installed = true
      service.installation_status = 'idle'
      await service.save()
      this.invalidateServicesStatusCache()

      // Remove from active installs tracking
      this.activeInstallations.delete(service.service_name)

      // If Ollama was just installed, trigger Nomad docs discovery and embedding
      if (service.service_name === SERVICE_NAMES.OLLAMA) {
        logger.info('[DockerService] Ollama installation complete. Default behavior is to not enable chat suggestions.')
        await KVStore.setValue('chat.suggestionsEnabled', false)

        logger.info('[DockerService] Ollama installation complete. Triggering Nomad docs discovery...')

        // Need to use dynamic imports here to avoid circular dependency
        const ollamaService = new (await import('./ollama_service.js')).OllamaService()
        const ragService = new (await import('./rag_service.js')).RagService(this, ollamaService)

        ragService.discoverNomadDocs().catch((error) => {
          logger.error('[DockerService] Failed to discover Nomad docs:', error)
        })
      }

      this._broadcast(
        service.service_name,
        'completed',
        `Service ${service.service_name} installation completed successfully.`
      )
    } catch (error: any) {
      const friendly = this._humanizeDockerError(error, service.service_name)
      this._broadcast(
        service.service_name,
        'error',
        `Error installing service ${service.service_name}: ${friendly}`
      )
      // Mark install as failed and cleanup
      await this._cleanupFailedInstallation(service.service_name)
      throw new Error(`Failed to install service ${service.service_name}: ${friendly}`)
    }
  }

  async _checkIfServiceContainerExists(serviceName: string): Promise<boolean> {
    try {
      const containers = await this.docker.listContainers({ all: true })
      return containers.some((container) => container.Names.includes(`/${serviceName}`))
    } catch (error: any) {
      logger.error(`Error checking if service container exists: ${error.message}`)
      return false
    }
  }

  async _removeServiceContainer(
    serviceName: string
  ): Promise<{ success: boolean; message: string }> {
    try {
      const containers = await this.docker.listContainers({ all: true })
      const container = containers.find((c) => c.Names.includes(`/${serviceName}`))
      if (!container) {
        return { success: false, message: `Container for service ${serviceName} not found` }
      }

      const dockerContainer = this.docker.getContainer(container.Id)
      await dockerContainer.remove({ force: true })

      return { success: true, message: `Service ${serviceName} container removed successfully` }
    } catch (error: any) {
      logger.error({ err: error }, `[DockerService] Error removing service container ${serviceName}`)
      return {
        success: false,
        message: `Failed to remove service ${serviceName} container. Check server logs for details.`,
      }
    }
  }

  private async _runPreinstallActions__KiwixServe(): Promise<void> {
    /**
     * At least one .zim file must be available before we can start the kiwix container.
     * We'll download the lightweight mini Wikipedia Top 100 zim file for this purpose.
     **/
    const WIKIPEDIA_ZIM_URL =
      'https://github.com/Crosstalk-Solutions/project-nomad/raw/refs/heads/main/install/wikipedia_en_100_mini_2026-01.zim'
    const filename = 'wikipedia_en_100_mini_2026-01.zim'
    const filepath = join(process.cwd(), ZIM_STORAGE_PATH, filename)
    logger.info(`[DockerService] Kiwix Serve pre-install: Downloading ZIM file to ${filepath}`)

    this._broadcast(
      SERVICE_NAMES.KIWIX,
      'preinstall',
      `Running pre-install actions for Kiwix Serve...`
    )
    this._broadcast(
      SERVICE_NAMES.KIWIX,
      'preinstall',
      `Downloading Wikipedia ZIM file from ${WIKIPEDIA_ZIM_URL}. This may take some time...`
    )

    try {
      await doResumableDownloadWithRetry({
        url: WIKIPEDIA_ZIM_URL,
        filepath,
        timeout: 60000,
        allowedMimeTypes: [
          'application/x-zim',
          'application/x-openzim',
          'application/octet-stream',
        ],
      })

      this._broadcast(
        SERVICE_NAMES.KIWIX,
        'preinstall',
        `Downloaded Wikipedia ZIM file to ${filepath}`
      )

      // Generate the initial kiwix library XML before the container is created
      const kiwixLibraryService = new KiwixLibraryService()
      await kiwixLibraryService.rebuildFromDisk()
      this._broadcast(SERVICE_NAMES.KIWIX, 'preinstall', 'Generated kiwix library XML.')
    } catch (error: any) {
      this._broadcast(
        SERVICE_NAMES.KIWIX,
        'preinstall-error',
        `Failed to download Wikipedia ZIM file: ${error.message}`
      )
      throw new Error(`Pre-install action failed: ${error.message}`)
    }
  }

  /**
   * Calibre-Web cannot create a library from scratch — without an existing Calibre database it
   * dead-ends at the "Database Configuration" page. Seed an empty library (bundled in the admin
   * image) into storage/books so the user just points Calibre-Web at /books and starts adding
   * books. Only seeds when no metadata.db already exists, so an existing library is never clobbered.
   * Ownership is handed to the container user (PUID/PGID 1000 in the seeder) so Calibre-Web can
   * write to the library and create book folders on upload.
   */
  private async _runPreinstallActions__CalibreWeb(): Promise<void> {
    // Keep in sync with the PUID/PGID set on the Calibre-Web service in the seeder.
    const CALIBRE_WEB_UID = 1000
    const CALIBRE_WEB_GID = 1000

    const booksDir = join(process.cwd(), BOOKS_STORAGE_PATH)
    const metadataPath = join(booksDir, 'metadata.db')
    const assetPath = join(process.cwd(), CALIBRE_EMPTY_LIBRARY_ASSET_PATH)

    this._broadcast(
      SERVICE_NAMES.CALIBREWEB,
      'preinstall',
      `Running pre-install actions for Calibre-Web...`
    )

    try {
      await mkdir(booksDir, { recursive: true })

      // Don't clobber an existing library — only seed when there's no metadata.db yet.
      const alreadyHasLibrary = await access(metadataPath)
        .then(() => true)
        .catch(() => false)

      if (alreadyHasLibrary) {
        this._broadcast(
          SERVICE_NAMES.CALIBREWEB,
          'preinstall',
          `Existing Calibre library found in books folder — leaving it as-is.`
        )
      } else {
        await copyFile(assetPath, metadataPath)
        this._broadcast(
          SERVICE_NAMES.CALIBREWEB,
          'preinstall',
          `Seeded an empty Calibre library into the books folder.`
        )
      }

      // Hand the books folder + library to the Calibre-Web container user so it can read/write
      // the library and create book folders on upload (Docker creates bind dirs as root otherwise).
      await chown(booksDir, CALIBRE_WEB_UID, CALIBRE_WEB_GID)
      await chown(metadataPath, CALIBRE_WEB_UID, CALIBRE_WEB_GID)
    } catch (error: any) {
      this._broadcast(
        SERVICE_NAMES.CALIBREWEB,
        'preinstall-error',
        `Failed to prepare the Calibre library: ${error.message}`
      )
      throw new Error(`Pre-install action failed: ${error.message}`)
    }
  }

  /**
   * Ensure a self-signed TLS cert (cert.pem + key.pem) exists in `certDir`, generating one if not.
   * Used by apps that need a secure (HTTPS) context but run on a LAN appliance with no public DNS to
   * get a trusted cert for. Idempotent: an existing pair is left untouched, so the cert is stable
   * across reinstalls (no fresh browser warning each time) and a cert an admin swapped in by hand is
   * never clobbered. The private key is locked to 0600; the cert stays world-readable.
   */
  private async _ensureSelfSignedCert(
    certDir: string,
    commonName: string
  ): Promise<{ certPath: string; keyPath: string }> {
    const certPath = join(certDir, 'cert.pem')
    const keyPath = join(certDir, 'key.pem')

    await mkdir(certDir, { recursive: true })

    const alreadyHasCert = await Promise.all([
      access(certPath)
        .then(() => true)
        .catch(() => false),
      access(keyPath)
        .then(() => true)
        .catch(() => false),
    ]).then(([c, k]) => c && k)

    if (alreadyHasCert) return { certPath, keyPath }

    // 10-year self-signed cert. CN/SAN are cosmetic for a self-signed cert (the browser warns
    // regardless), but a SAN keeps it structurally valid for clients that require one.
    const execAsync = promisify(exec)
    await execAsync(
      `openssl req -x509 -newkey rsa:2048 -nodes ` +
        `-keyout "${keyPath}" -out "${certPath}" -days 3650 ` +
        `-subj "/CN=${commonName}" ` +
        `-addext "subjectAltName=DNS:nomad,DNS:localhost"`
    )

    await chmod(keyPath, 0o600)
    await chmod(certPath, 0o644)

    return { certPath, keyPath }
  }

  /**
   * Vaultwarden's web vault refuses to run without a secure context — over plain HTTP it shows
   * "You need to enable HTTPS!" and you can't register or unlock. We give it a self-signed TLS
   * cert in its /data volume so it serves HTTPS out of the box (paired with the ROCKET_TLS env and
   * the `https:8480` ui_location set in the seeder). Users click through a one-time browser warning;
   * after that the vault is fully functional offline.
   */
  private async _runPreinstallActions__Vaultwarden(): Promise<void> {
    const dataDir = join(process.cwd(), VAULTWARDEN_STORAGE_PATH)

    this._broadcast(
      SERVICE_NAMES.VAULTWARDEN,
      'preinstall',
      `Running pre-install actions for Vaultwarden...`
    )

    try {
      await this._ensureSelfSignedCert(dataDir, 'Project NOMAD Vaultwarden')
      this._broadcast(
        SERVICE_NAMES.VAULTWARDEN,
        'preinstall',
        `Vaultwarden HTTPS certificate is ready.`
      )
    } catch (error: any) {
      this._broadcast(
        SERVICE_NAMES.VAULTWARDEN,
        'preinstall-error',
        `Failed to prepare the Vaultwarden certificate: ${error.message}`
      )
      throw new Error(`Pre-install action failed: ${error.message}`)
    }
  }

  /**
   * The MeshCore web client (aXistem's prebuilt image) is stock nginx serving a static Flutter build
   * over plain HTTP. The client reaches a radio over Web Bluetooth / Web Serial, which browsers only
   * permit from a secure (HTTPS) context — so over plain HTTP the app loads but can't connect to a
   * thing. We generate a self-signed cert and a small SSL nginx config here; the seeder bind-mounts
   * both into the container (the config over the image's default.conf) so it serves the same static
   * files over HTTPS instead. Same one-time-browser-warning approach as Vaultwarden.
   */
  private async _runPreinstallActions__MeshCoreWeb(): Promise<void> {
    const appDir = join(process.cwd(), MESHCORE_WEB_STORAGE_PATH)
    const certDir = join(appDir, 'certs')
    const nginxConfPath = join(appDir, 'nginx-ssl.conf')

    this._broadcast(
      SERVICE_NAMES.MESHCORE_WEB,
      'preinstall',
      `Running pre-install actions for MeshCore Web...`
    )

    try {
      await this._ensureSelfSignedCert(certDir, 'Project NOMAD MeshCore Web')

      // SSL server block bind-mounted over the image's default.conf. Serves the Flutter build that
      // already lives at /usr/share/nginx/html in the image, over HTTPS only, with the SPA fallback
      // that single-page apps need. Cert paths match the /certs bind mount set in the seeder.
      const nginxConf =
        [
          'server {',
          '    listen 443 ssl;',
          '    server_name _;',
          '    ssl_certificate     /certs/cert.pem;',
          '    ssl_certificate_key /certs/key.pem;',
          '    root /usr/share/nginx/html;',
          '    index index.html;',
          '    location / {',
          '        try_files $uri $uri/ /index.html;',
          '    }',
          '}',
        ].join('\n') + '\n'
      await writeFile(nginxConfPath, nginxConf)
      await chmod(nginxConfPath, 0o644)

      this._broadcast(
        SERVICE_NAMES.MESHCORE_WEB,
        'preinstall',
        `MeshCore Web HTTPS certificate and config are ready.`
      )
    } catch (error: any) {
      this._broadcast(
        SERVICE_NAMES.MESHCORE_WEB,
        'preinstall-error',
        `Failed to prepare MeshCore Web: ${error.message}`
      )
      throw new Error(`Pre-install action failed: ${error.message}`)
    }
  }

  /**
   * Jellyfin works best when each library points at its own subfolder. Pointing one library at the
   * whole media root and another at a subfolder inside it makes Jellyfin report a "duplicate path"
   * and silently drop the nested library's content. To steer users toward the one-folder-per-type
   * layout (and match the documentation), we pre-create the suggested subfolders under the shared
   * media root so they're ready to pick in the setup wizard. Idempotent: only missing folders are
   * created (mkdir is a no-op on existing ones) and nothing the user added is ever touched.
   */
  private async _runPreinstallActions__Jellyfin(): Promise<void> {
    const mediaDir = join(process.cwd(), MEDIA_STORAGE_PATH)

    this._broadcast(
      SERVICE_NAMES.JELLYFIN,
      'preinstall',
      `Running pre-install actions for Jellyfin...`
    )

    try {
      await mkdir(mediaDir, { recursive: true })
      for (const name of JELLYFIN_MEDIA_SUBFOLDERS) {
        await mkdir(join(mediaDir, name), { recursive: true })
      }
      this._broadcast(
        SERVICE_NAMES.JELLYFIN,
        'preinstall',
        `Prepared media folders: ${JELLYFIN_MEDIA_SUBFOLDERS.join(', ')}.`
      )
    } catch (error: any) {
      this._broadcast(
        SERVICE_NAMES.JELLYFIN,
        'preinstall-error',
        `Failed to prepare the Jellyfin media folders: ${error.message}`
      )
      throw new Error(`Pre-install action failed: ${error.message}`)
    }
  }

  private async _cleanupFailedInstallation(serviceName: string): Promise<void> {
    try {
      const service = await Service.query().where('service_name', serviceName).first()
      if (service) {
        if (service.is_custom) {
          // Custom apps have no seeder definition to fall back to — leaving the row would
          // surface a phantom, un-installable card. Remove the record entirely so a failed
          // install cleanly disappears. (The 'error' broadcast has already fired upstream.)
          await service.delete()
        } else {
          service.installation_status = 'error'
          await service.save()
        }
      }
      this.activeInstallations.delete(serviceName)

      // Ensure any partially created container is removed
      await this._removeServiceContainer(serviceName)

      logger.info(`[DockerService] Cleaned up failed installation for ${serviceName}`)
    } catch (error: any) {
      logger.error(
        `[DockerService] Failed to cleanup installation for ${serviceName}: ${error.message}`
      )
    }
  }

  /**
   * Checks whether the running kiwix container is using the legacy glob-pattern command
   * (`*.zim --address=all`) rather than the library-file command. Used to detect containers
   * that need to be migrated to library mode.
   */
  async isKiwixOnLegacyConfig(): Promise<boolean> {
    try {
      const containers = await this.docker.listContainers({ all: true })
      const info = containers.find((c) => c.Names.includes(`/${SERVICE_NAMES.KIWIX}`))
      if (!info) return false

      const inspected = await this.docker.getContainer(info.Id).inspect()
      const cmd: string[] = inspected.Config?.Cmd ?? []
      return cmd.some((arg) => arg.includes('*.zim'))
    } catch (err: any) {
      logger.warn(`[DockerService] Could not inspect kiwix container: ${err.message}`)
      return false
    }
  }

  /**
   * Migrates the kiwix container from legacy glob mode (`*.zim`) to library mode
   * (`--library /data/kiwix-library.xml --monitorLibrary`).
   *
   * This is a non-destructive recreation: ZIM files and volumes are preserved.
   * The container is stopped, removed, and recreated with the correct library-mode command.
   * This function is authoritative: it writes the correct command to the DB itself rather than
   * trusting the DB to have been pre-updated by a separate migration.
   */
  async migrateKiwixToLibraryMode(): Promise<void> {
    if (this.activeInstallations.has(SERVICE_NAMES.KIWIX)) {
      logger.warn('[DockerService] Kiwix migration already in progress, skipping duplicate call.')
      return
    }

    this.activeInstallations.add(SERVICE_NAMES.KIWIX)

    try {
      // Step 1: Build/update the XML from current disk state
      this._broadcast(SERVICE_NAMES.KIWIX, 'migrating', 'Migrating kiwix to library mode...')
      const kiwixLibraryService = new KiwixLibraryService()
      await kiwixLibraryService.rebuildFromDisk()
      this._broadcast(SERVICE_NAMES.KIWIX, 'migrating', 'Built kiwix library XML from existing ZIM files.')

      // Step 2: Stop and remove old container (leave ZIM volumes intact)
      const containers = await this.docker.listContainers({ all: true })
      const containerInfo = containers.find((c) => c.Names.includes(`/${SERVICE_NAMES.KIWIX}`))
      if (containerInfo) {
        const oldContainer = this.docker.getContainer(containerInfo.Id)
        if (containerInfo.State === 'running') {
          await oldContainer.stop({ t: 10 }).catch((e: any) =>
            logger.warn(`[DockerService] Kiwix stop warning during migration: ${e.message}`)
          )
        }
        await oldContainer.remove({ force: true }).catch((e: any) =>
          logger.warn(`[DockerService] Kiwix remove warning during migration: ${e.message}`)
        )
      }

      // Step 3: Read the service record and authoritatively set the correct command.
      // Do NOT rely on prior DB state — we write container_command here so the record
      // stays consistent regardless of whether the DB migration ran.
      const service = await Service.query().where('service_name', SERVICE_NAMES.KIWIX).first()
      if (!service) {
        throw new Error('Kiwix service record not found in DB during migration')
      }

      service.container_command = KIWIX_LIBRARY_CMD
      service.installed = false
      service.installation_status = 'installing'
      await service.save()

      const containerConfig = this._parseContainerConfig(service.container_config)
      await this._applyHostStorageRoot(containerConfig)

      // Step 4: Recreate container directly (skipping _createContainer to avoid re-downloading
      // the bootstrap ZIM — ZIM files already exist on disk)
      this._broadcast(SERVICE_NAMES.KIWIX, 'migrating', 'Recreating kiwix container with library mode config...')
      const newContainer = await this.docker.createContainer({
        Image: service.container_image,
        name: service.service_name,
        HostConfig: containerConfig?.HostConfig ?? {},
        ...(containerConfig?.ExposedPorts && { ExposedPorts: containerConfig.ExposedPorts }),
        Cmd: KIWIX_LIBRARY_CMD.split(' '),
        ...(process.env.NODE_ENV === 'production' && {
          NetworkingConfig: {
            EndpointsConfig: {
              [DockerService.NOMAD_NETWORK]: {},
            },
          },
        }),
      })

      await newContainer.start()

      service.installed = true
      service.installation_status = 'idle'
      await service.save()
      this.activeInstallations.delete(SERVICE_NAMES.KIWIX)

      this._broadcast(SERVICE_NAMES.KIWIX, 'migrated', 'Kiwix successfully migrated to library mode.')
      logger.info('[DockerService] Kiwix migration to library mode complete.')
    } catch (error: any) {
      logger.error(`[DockerService] Kiwix migration failed: ${error.message}`)
      await this._cleanupFailedInstallation(SERVICE_NAMES.KIWIX)
      throw error
    }
  }

  /**
   * Detect GPU type and toolkit availability.
   * Primary: Check Docker runtimes via docker.info() (works from inside containers).
   * Secondary: Read /app/storage/.nomad-gpu-type written by install_nomad.sh — needed
   *   for AMD detection because lspci isn't available inside the admin container and
   *   AMD has no Docker runtime registration to query.
   * Fallback: lspci for host-based installs.
   */
  private async _detectGPUType(): Promise<{ type: 'nvidia' | 'amd' | 'none'; toolkitMissing?: boolean }> {
    try {
      // Primary: Check Docker daemon for nvidia runtime (works from inside containers)
      try {
        const dockerInfo = await this.docker.info()
        const runtimes = dockerInfo.Runtimes || {}
        if ('nvidia' in runtimes) {
          logger.info('[DockerService] NVIDIA container runtime detected via Docker API')
          await this._persistGPUType('nvidia')
          return { type: 'nvidia' }
        }
      } catch (error: any) {
        logger.warn(`[DockerService] Could not query Docker info for GPU runtimes: ${error.message}`)
      }

      // Secondary: install_nomad.sh writes the host-detected GPU type to a marker file in
      // the storage volume so the admin container (which lacks lspci) can read it.
      try {
        const marker = (await readFile('/app/storage/.nomad-gpu-type', 'utf8')).trim()
        if (marker === 'nvidia') {
          // Hardware present but Docker doesn't have nvidia runtime → toolkit missing
          logger.warn('[DockerService] NVIDIA GPU recorded in marker file but NVIDIA Container Toolkit is not installed')
          return { type: 'none', toolkitMissing: true }
        }
        if (marker === 'amd') {
          logger.info('[DockerService] AMD GPU detected via install-time marker file')
          await this._persistGPUType('amd')
          return { type: 'amd' }
        }
      } catch {
        // No marker file — fall through to lspci attempt for host-based installs
      }

      // Fallback: lspci for host-based installs (not available inside Docker)
      const execAsync = promisify(exec)

      // Check for NVIDIA GPU via lspci
      try {
        const { stdout: nvidiaCheck } = await execAsync(
          'lspci 2>/dev/null | grep -i nvidia || true'
        )
        if (nvidiaCheck.trim()) {
          // GPU hardware found but no nvidia runtime — toolkit not installed
          logger.warn('[DockerService] NVIDIA GPU detected via lspci but NVIDIA Container Toolkit is not installed')
          return { type: 'none', toolkitMissing: true }
        }
      } catch (error: any) {
        // lspci not available (likely inside Docker container), continue
      }

      // Check for AMD GPU via lspci — restrict to display controller classes to avoid
      // false positives from AMD CPU host bridges, PCI bridges, and chipset devices.
      try {
        const { stdout: amdCheck } = await execAsync(
          'lspci 2>/dev/null | grep -iE "VGA|3D controller|Display" | grep -iE "amd|radeon" || true'
        )
        if (amdCheck.trim()) {
          logger.info('[DockerService] AMD GPU detected via lspci')
          await this._persistGPUType('amd')
          return { type: 'amd' }
        }
      } catch (error: any) {
        // lspci not available, continue
      }

      // Last resort: check if we previously detected a GPU and it's likely still present.
      // This handles cases where live detection fails transiently (e.g., Docker daemon
      // hiccup, runtime temporarily unavailable) but the hardware hasn't changed.
      try {
        const savedType = await KVStore.getValue('gpu.type')
        if (savedType === 'nvidia' || savedType === 'amd') {
          logger.info(`[DockerService] No GPU detected live, but KV store has '${savedType}' from previous detection. Using saved value.`)
          return { type: savedType as 'nvidia' | 'amd' }
        }
      } catch {
        // KV store not available, continue
      }

      logger.info('[DockerService] No GPU detected')
      return { type: 'none' }
    } catch (error: any) {
      logger.warn(`[DockerService] Error detecting GPU type: ${error.message}`)
      return { type: 'none' }
    }
  }

  private async _persistGPUType(type: 'nvidia' | 'amd'): Promise<void> {
    try {
      await KVStore.setValue('gpu.type', type)
      logger.info(`[DockerService] Persisted GPU type '${type}' to KV store`)
    } catch (error: any) {
      logger.warn(`[DockerService] Failed to persist GPU type: ${error.message}`)
    }
  }

  /**
   * The HSA_OVERRIDE_GFX_VERSION an AMD install or reinstall would apply right now.
   * Exposed so GpuPassthroughRemediationProvider can tell whether a reinstall would
   * change the running container.
   */
  async getAmdHsaOverride(
    options: { quiet?: boolean; containerEnv?: string[] | null } = {}
  ): Promise<string | null> {
    return this._resolveAmdHsaOverride(options)
  }

  /**
   * Resolve the HSA_OVERRIDE_GFX_VERSION value for the host's AMD GPU.
   *
   * gfx1030 (RX 6800/6700/etc.), gfx1100/1101/1102 (RX 7900/7800/7600) are on AMD's
   * official ROCm allowlist — forcing an override on these breaks GPU discovery.
   * gfx1035 / gfx1036 (RDNA 2 iGPUs like 680M) need 10.3.0 to coerce to gfx1030.
   * gfx1150 / gfx1151 (RDNA 3.5 iGPUs like 890M / Strix Halo) ARE on the bundled rocblas
   * allowlist, so they need NO override. gfx1103 (Phoenix 780M/760M) is NOT — it must be
   * coerced to 11.0.0 (gfx1100 kernels) or ollama drops it to CPU. See ../utils/amd_hsa_override.ts.
   *
   * Resolution order:
   *   1. KV `ai.amdHsaOverride` — manual user override; accepts 'none' (disable) or a semver-style value.
   *   2. Marker file `/app/storage/.nomad-amd-gfx` written by install_nomad.sh.
   *   3. The override the existing container runs with, when the caller passes its env (#1377).
   *   4. Default: none — let ROCm discover the GPU natively. Users on hardware that still
   *      needs coercion can force a value via the KV. A hardcoded default gets more wrong
   *      as ROCm adds native targets, so null is the safer forward-looking default.
   * The pure ordering lives in pickAmdHsaOverride (../utils/amd_hsa_override.ts).
   *
   * Returns null when no override should be applied.
   */
  /**
   * Resolve the Homebox API-key pepper, generating and persisting one on first use.
   *
   * Homebox >= 0.26 panics at boot unless HBOX_AUTH_API_KEY_PEPPER is set to a value of at
   * least 32 bytes (#1043). The pepper must be STABLE across updates and reinstalls:
   * rotating it invalidates every API key a user has issued from Homebox. So we generate it
   * once and persist it in the KV store, then reuse it for the life of the install.
   */
  private async _resolveHomeboxPepper(): Promise<string> {
    const existing = await KVStore.getValue('apps.homebox.apiKeyPepper')
    if (typeof existing === 'string' && existing.length >= 32) {
      return existing
    }
    // 48 raw bytes -> 64 base64 chars, comfortably over Homebox's 32-byte floor.
    const pepper = randomBytes(48).toString('base64')
    await KVStore.setValue('apps.homebox.apiKeyPepper', pepper)
    logger.info('[DockerService] Generated and persisted Homebox API key pepper')
    return pepper
  }

  private async _resolveAmdHsaOverride({
    quiet = false,
    containerEnv,
  }: { quiet?: boolean; containerEnv?: string[] | null } = {}): Promise<string | null> {
    const manual = await KVStore.getValue('ai.amdHsaOverride')
    const markerGfx = await this._readAmdGfxMarker()
    const resolved = pickAmdHsaOverride({ manual, markerGfx, containerEnv })
    if (quiet) return resolved.value

    if (resolved.invalidManual !== undefined) {
      logger.warn(`[DockerService] Ignoring invalid ai.amdHsaOverride value: ${resolved.invalidManual}`)
    }
    switch (resolved.source) {
      case 'kv-disabled':
        logger.info('[DockerService] HSA override disabled via ai.amdHsaOverride')
        break
      case 'kv':
        logger.info(`[DockerService] HSA override forced to ${resolved.value} via ai.amdHsaOverride`)
        break
      case 'marker':
        logger.info(
          `[DockerService] AMD gfx marker '${markerGfx}' → HSA override ${resolved.value ?? 'none'}`
        )
        break
      case 'container':
        logger.info(
          `[DockerService] Keeping HSA override ${resolved.value} from the existing container`
        )
        break
      case 'default':
        logger.warn(
          `[DockerService] AMD GPU configured but no gfx marker (${AMD_GFX_MARKER_PATH}) and no ` +
            'ai.amdHsaOverride KV; relying on native ROCm discovery. iGPUs not on the bundled rocblas ' +
            'allowlist (e.g. 780M/gfx1103, 680M/gfx1035) will silently fall back to CPU. Set the ' +
            'ai.amdHsaOverride KV (e.g. 11.0.0 for a 780M) and force-reinstall the AI service if so.'
        )
        break
    }
    return resolved.value
  }

  /**
   * Before a force reinstall removes nomad_ollama, persist the HSA override it runs with
   * when nothing else would supply one (#1377). The recreate builds env from scratch, so
   * without this an upgraded box with a hand-set override loses it. Persisting rather than
   * passing it along in memory keeps it through a reinstall that fails after removal, and
   * shows it in the Set GFX Override modal.
   */
  private async _adoptContainerHsaOverride(containerEnv: string[] | null | undefined): Promise<void> {
    const resolved = pickAmdHsaOverride({
      manual: await KVStore.getValue('ai.amdHsaOverride'),
      markerGfx: await this._readAmdGfxMarker(),
      containerEnv,
    })
    if (resolved.source !== 'container' || !resolved.value) return

    await KVStore.setValue('ai.amdHsaOverride', resolved.value)
    logger.info(
      `[DockerService] Persisted HSA override ${resolved.value} from the existing container to ai.amdHsaOverride`
    )
  }

  private async _readAmdGfxMarker(): Promise<string | null> {
    try {
      return (await readFile(AMD_GFX_MARKER_PATH, 'utf8')).trim()
    } catch {
      // Marker absent: most likely an existing install upgraded without re-running
      // install_nomad.sh.
      return null
    }
  }

  /**
   * Build the Docker Devices array for AMD GPU passthrough.
   *
   * Returns /dev/kfd (Kernel Fusion Driver, required by ROCm) and /dev/dri (the DRM
   * device tree). Passing /dev/dri as a single directory entry mirrors Docker CLI
   * --device behavior — the daemon expands it to all child devices (card*, renderD*)
   * regardless of how the host enumerates them. This avoids the brittle hardcoded
   * fallback (card0/renderD128) the prior implementation used, which was wrong on
   * systems where the AMD GPU enumerates as card1+ (e.g. UM890 Pro 780M iGPU).
   */
  private async _discoverAMDDevices(): Promise<
    Array<{ PathOnHost: string; PathInContainer: string; CgroupPermissions: string }>
  > {
    return [
      { PathOnHost: '/dev/kfd', PathInContainer: '/dev/kfd', CgroupPermissions: 'rwm' },
      { PathOnHost: '/dev/dri', PathInContainer: '/dev/dri', CgroupPermissions: 'rwm' },
    ]
  }

  /**
   * Whether a container-create failure was the daemon refusing a `--device` path
   * that does not exist on the host, e.g.
   *
   *   (HTTP code 500) server error - error gathering device information while
   *   adding custom device "/dev/kfd": no such file or directory
   *
   * GPU *detection* reads PCI data, which says nothing about whether the ROCm
   * kernel interface was ever loaded. An AMD card with no `/dev/kfd` is a
   * perfectly normal machine — old pre-ROCm silicon, or amdgpu not loaded — and
   * on those the create fails outright and the whole install dies (#1232).
   *
   * Deliberately keyed on the device-gathering phrase rather than a bare "no
   * such file or directory", which Docker also emits for missing bind-mount
   * sources and image layers. Falling back to CPU on one of those would hide a
   * real failure behind a degraded install.
   */
  private _isMissingDeviceError(error: any): boolean {
    const raw: string = error?.message ?? String(error)
    return /error gathering device information while adding custom device/i.test(raw)
  }

  /**
   * Update a service container to a new image version while preserving volumes and data.
   * Includes automatic rollback if the new container fails health checks.
   */
  async updateContainer(
    serviceName: string,
    targetVersion: string
  ): Promise<{ success: boolean; message: string }> {
    try {
      const service = await Service.query().where('service_name', serviceName).first()
      if (!service) {
        return { success: false, message: `Service ${serviceName} not found` }
      }
      if (!service.installed) {
        return { success: false, message: `Service ${serviceName} is not installed` }
      }
      if (this.activeInstallations.has(serviceName)) {
        return { success: false, message: `Service ${serviceName} already has an operation in progress` }
      }
      // DB-level guard mirrors the install path. Unlike the in-memory Set above, this survives a
      // page reload and is visible to other clients, so a second Update click (or one from another
      // tab) is rejected cleanly instead of racing two updateContainer runs into Docker 304/400
      // errors (stop/rename on a container the first run already moved).
      if (service.installation_status === 'installing') {
        return { success: false, message: `Service ${serviceName} already has an update in progress` }
      }

      this.activeInstallations.add(serviceName)
      // Persist the in-progress flag so the Apps page can durably disable the Update button while
      // the (often multi-GB, multi-minute) pull runs. Cleared in the finally below.
      service.installation_status = 'installing'
      await service.save()

      // newImage = the semver tag we record in the DB after the update (e.g. ollama/ollama:0.23.2).
      // runtimeImage = the tag we actually pull and run. For AMD-on-Ollama these diverge: we run
      // the rolling :rocm tag because per-version ROCm tags aren't always published, but the DB
      // must keep the semver tag so the Apps page shows the actual version (not literally "rocm")
      // and the registry update-check parses a valid tag (instead of looping on the same update).
      const currentImage = service.container_image
      const imageBase = currentImage.includes(':')
        ? currentImage.substring(0, currentImage.lastIndexOf(':'))
        : currentImage
      const newImage = `${imageBase}:${targetVersion}`
      let runtimeImage = newImage

      // GPU detection runs before the pull so AMD updates pull ollama/ollama:rocm rather
      // than the standard tag. Detection result is reused below when building the new
      // container config (devices, env). Non-Ollama services skip this entirely.
      let updatedDeviceRequests: any[] | undefined = undefined
      let updatedAmdDevices: any[] | undefined = undefined
      let updatedAmdGpuConfigured = false
      if (serviceName === SERVICE_NAMES.OLLAMA) {
        const gpuResult = await this._detectGPUType()
        if (gpuResult.type === 'nvidia') {
          this._broadcast(
            serviceName,
            'update-gpu-config',
            `NVIDIA container runtime detected. Configuring updated container with GPU support...`
          )
          updatedDeviceRequests = [
            { Driver: 'nvidia', Count: -1, Capabilities: [['gpu']] },
          ]
        } else if (gpuResult.type === 'amd') {
          const amdEnabledRaw = await KVStore.getValue('ai.amdGpuAcceleration')
          const amdAccelerationEnabled = String(amdEnabledRaw) !== 'false'
          if (amdAccelerationEnabled) {
            this._broadcast(
              serviceName,
              'update-gpu-config',
              `AMD GPU detected. Using ROCm image with /dev/kfd and /dev/dri passthrough...`
            )
            runtimeImage = 'ollama/ollama:rocm'
            updatedAmdDevices = await this._discoverAMDDevices()
            updatedAmdGpuConfigured = true
          } else {
            this._broadcast(
              serviceName,
              'update-gpu-config',
              `AMD GPU detected but acceleration is disabled via ai.amdGpuAcceleration. Using CPU-only configuration.`
            )
          }
        } else if (gpuResult.toolkitMissing) {
          this._broadcast(
            serviceName,
            'update-gpu-config',
            `NVIDIA GPU detected but NVIDIA Container Toolkit is not installed. Using CPU-only configuration. Install the toolkit and reinstall AI Assistant for GPU acceleration: https://docs.nvidia.com/datacenter/cloud-native/container-toolkit/latest/install-guide.html`
          )
        } else {
          this._broadcast(serviceName, 'update-gpu-config', `No GPU detected. Using CPU-only configuration.`)
        }
      }

      // Step 1: Pull new image (runtimeImage diverges from newImage for AMD, see above)
      this._broadcast(serviceName, 'update-pulling', `Pulling image ${runtimeImage}...`)
      await this.pullImage(runtimeImage)

      // Step 2: Find and stop existing container
      this._broadcast(serviceName, 'update-stopping', `Stopping current container...`)
      const containers = await this.docker.listContainers({ all: true })
      const existingContainer = containers.find((c) => c.Names.includes(`/${serviceName}`))

      if (!existingContainer) {
        this.activeInstallations.delete(serviceName)
        return { success: false, message: `Container for ${serviceName} not found` }
      }

      const oldContainer = this.docker.getContainer(existingContainer.Id)

      // Inspect to capture full config before stopping
      const inspectData = await oldContainer.inspect()

      if (existingContainer.State === 'running') {
        await oldContainer.stop({ t: 15 })
      }

      // Step 3: Rename old container as safety net
      const oldName = `${serviceName}_old`

      // Clear any stale rollback container left behind by a previously failed update.
      // Otherwise the rename below collides with the existing `<name>_old` and throws,
      // which wedges every subsequent retry on the same error.
      const staleOld = (await this.docker.listContainers({ all: true })).find((c) =>
        c.Names.includes(`/${oldName}`)
      )
      if (staleOld) {
        try {
          await this.docker.getContainer(staleOld.Id).remove({ force: true })
        } catch {
          // Best effort — if it can't be removed the rename below will surface the error.
        }
      }

      await oldContainer.rename({ name: oldName })

      // Restore the previous container after a failed update: rename the renamed-aside
      // old container back into place and start it, so a failure anywhere between here
      // and the health check never leaves the service down.
      const rollbackToOld = async () => {
        const containers = await this.docker.listContainers({ all: true })
        const oldRef = containers.find((c) => c.Names.includes(`/${oldName}`))
        if (oldRef) {
          const rollbackContainer = this.docker.getContainer(oldRef.Id)
          await rollbackContainer.rename({ name: serviceName }).catch(() => {})
          await rollbackContainer.start().catch(() => {})
        }
      }

      // Step 4: Create new container with inspected config + new image
      this._broadcast(serviceName, 'update-creating', `Creating updated container...`)

      const hostConfig = inspectData.HostConfig || {}

      // GPU detection already ran above (before the pull) so we know the right image, devices,
      // and whether HSA_OVERRIDE needs injection. For AMD, replace any prior HSA_OVERRIDE in
      // the inspect-captured env so updates from older containers pick up the current value.
      const baseEnv = inspectData.Config?.Env || []
      let finalEnv = baseEnv
      if (updatedAmdGpuConfigured) {
        const hsaOverride = await this._resolveAmdHsaOverride({ containerEnv: baseEnv })
        finalEnv = baseEnv.filter(
          (e: string) =>
            !e.startsWith('HSA_OVERRIDE_GFX_VERSION=') && !e.startsWith('OLLAMA_IGPU_ENABLE=')
        )
        if (hsaOverride) {
          finalEnv.push(`HSA_OVERRIDE_GFX_VERSION=${hsaOverride}`)
        }
        // Re-assert the iGPU flag so updates from a container provisioned before the
        // issue #1056 fix (which wouldn't have it in the captured env) pick it up.
        finalEnv.push('OLLAMA_IGPU_ENABLE=1')
      }

      // Heal a Homebox container that predates the #1043 fix: inject the persisted pepper on
      // update if it's missing, so an update (not just a force-reinstall) fixes the crash loop.
      if (
        serviceName === SERVICE_NAMES.HOMEBOX &&
        !finalEnv.some((e: string) => e.startsWith('HBOX_AUTH_API_KEY_PEPPER='))
      ) {
        finalEnv = [...finalEnv, `HBOX_AUTH_API_KEY_PEPPER=${await this._resolveHomeboxPepper()}`]
      }

      const newContainerConfig: any = {
        Image: runtimeImage,
        name: serviceName,
        Env: finalEnv.length > 0 ? finalEnv : undefined,
        Cmd: inspectData.Config?.Cmd || undefined,
        ExposedPorts: inspectData.Config?.ExposedPorts || undefined,
        WorkingDir: inspectData.Config?.WorkingDir || undefined,
        User: inspectData.Config?.User || undefined,
        HostConfig: {
          Binds: hostConfig.Binds || undefined,
          PortBindings: hostConfig.PortBindings || undefined,
          RestartPolicy: hostConfig.RestartPolicy || undefined,
          DeviceRequests: serviceName === SERVICE_NAMES.OLLAMA ? updatedDeviceRequests : (hostConfig.DeviceRequests || undefined),
          Devices: serviceName === SERVICE_NAMES.OLLAMA && updatedAmdDevices ? updatedAmdDevices : (hostConfig.Devices || undefined),
        },
        NetworkingConfig: inspectData.NetworkSettings?.Networks
          ? {
              EndpointsConfig: Object.fromEntries(
                Object.keys(inspectData.NetworkSettings.Networks).map((net) => [net, {}])
              ),
            }
          : undefined,
      }

      // Remove undefined values from HostConfig
      Object.keys(newContainerConfig.HostConfig).forEach((key) => {
        if (newContainerConfig.HostConfig[key] === undefined) {
          delete newContainerConfig.HostConfig[key]
        }
      })

      let newContainer: any
      try {
        newContainer = await this.docker.createContainer(newContainerConfig)
      } catch (createError: any) {
        // Rollback: rename old container back
        this._broadcast(serviceName, 'update-rollback', `Failed to create new container: ${createError.message}. Rolling back...`)
        await rollbackToOld()
        this.activeInstallations.delete(serviceName)
        return { success: false, message: `Failed to create updated container: ${createError.message}` }
      }

      // Step 5: Start new container. If the start itself throws (bad device/GPU config,
      // a host port already bound, image incompatibility), roll back to the previous
      // container instead of leaving the service stopped with no replacement running.
      this._broadcast(serviceName, 'update-starting', `Starting updated container...`)
      try {
        await newContainer.start()
      } catch (startError: any) {
        this._broadcast(
          serviceName,
          'update-rollback',
          `Updated container failed to start: ${startError.message}. Rolling back to previous version...`
        )
        try {
          await newContainer.remove({ force: true })
        } catch {
          // Best effort — leave the half-created container for manual cleanup if needed.
        }
        await rollbackToOld()
        this.activeInstallations.delete(serviceName)
        return {
          success: false,
          message: `Update failed: new container did not start (${startError.message}). Rolled back to previous version.`,
        }
      }

      // Step 6: Health check — verify container stays running for 5 seconds
      await new Promise((resolve) => setTimeout(resolve, 5000))
      const newContainerInfo = await newContainer.inspect()

      if (newContainerInfo.State?.Running) {
        // Healthy — clean up old container
        try {
          const oldContainerRef = this.docker.getContainer(
            (await this.docker.listContainers({ all: true })).find((c) =>
              c.Names.includes(`/${oldName}`)
            )?.Id || ''
          )
          await oldContainerRef.remove({ force: true })
        } catch {
          // Old container may already be gone
        }

        // Update DB
        service.container_image = newImage
        service.available_update_version = null
        await service.save()

        this.activeInstallations.delete(serviceName)
        this._broadcast(
          serviceName,
          'update-complete',
          `Successfully updated ${serviceName} to ${targetVersion}`
        )
        return { success: true, message: `Service ${serviceName} updated to ${targetVersion}` }
      } else {
        // Unhealthy — rollback
        this._broadcast(
          serviceName,
          'update-rollback',
          `New container failed health check. Rolling back to previous version...`
        )

        try {
          await newContainer.stop({ t: 5 }).catch(() => {})
          await newContainer.remove({ force: true })
        } catch {
          // Best effort cleanup
        }

        await rollbackToOld()

        this.activeInstallations.delete(serviceName)
        return {
          success: false,
          message: `Update failed: new container did not stay running. Rolled back to previous version.`,
        }
      }
    } catch (error: any) {
      this.activeInstallations.delete(serviceName)
      this._broadcast(
        serviceName,
        'update-rollback',
        'Update failed. Check server logs for details.'
      )
      logger.error({ err: error }, `[DockerService] Update failed for ${serviceName}`)
      return { success: false, message: 'Update failed. Check server logs for details.' }
    } finally {
      // Always clear the in-progress flag we set above, on every exit path (success, rollback,
      // not-found, or thrown error). The success path already persisted the new image/version on
      // this same in-memory model, so saving again with idle preserves that — it only flips the
      // status. The existing activeInstallations.delete() calls on each branch handle the
      // in-memory lock; this just keeps the durable DB flag honest.
      const svc = await Service.query().where('service_name', serviceName).first()
      if (svc && svc.installation_status === 'installing') {
        svc.installation_status = 'idle'
        try {
          await svc.save()
        } catch (saveErr: any) {
          logger.error({ err: saveErr }, `[DockerService] Failed to reset installation_status for ${serviceName}`)
        }
      }
    }
  }

  private _broadcast(service: string, status: string, message: string) {
    transmit.broadcast(BROADCAST_CHANNELS.SERVICE_INSTALLATION, {
      service_name: service,
      timestamp: new Date().toISOString(),
      status,
      message,
    })
    logger.info(`[DockerService] [${service}] ${status}: ${message}`)
  }

  private _parseContainerConfig(containerConfig: any): any {
    if (!containerConfig) {
      return {}
    }

    try {
      // Handle the case where containerConfig is returned as an object by DB instead of a string
      let toParse = containerConfig
      if (typeof containerConfig === 'object') {
        toParse = JSON.stringify(containerConfig)
      }

      return JSON.parse(toParse)
    } catch (error: any) {
      logger.error(`Failed to parse container configuration: ${error.message}`)
      throw new Error(`Invalid container configuration: ${error.message}`)
    }
  }

  /**
   * Check whether any of the supplied host ports are already bound by a running or stopped
   * Docker container. Uses the Docker API exclusively — probing ports via net.createServer()
   * would only test the admin container's own network namespace (DooD pattern), not the host.
   */
  async checkPortConflicts(
    ports: number[]
  ): Promise<{ conflicts: { port: number; usedBy: string }[] }> {
    if (!ports.length) return { conflicts: [] }

    try {
      const containers = await this.docker.listContainers({ all: true })
      const bound = new Map<number, string>()

      for (const c of containers) {
        const name = (c.Names[0] || '').replace('/', '')
        for (const p of c.Ports) {
          if (p.PublicPort) bound.set(p.PublicPort, name || c.Id.slice(0, 12))
        }
      }

      const conflicts = ports
        .filter((p) => bound.has(p))
        .map((p) => ({ port: p, usedBy: bound.get(p)! }))

      return { conflicts }
    } catch (error: any) {
      logger.warn(`[DockerService] checkPortConflicts failed: ${error.message}`)
      return { conflicts: [] }
    }
  }

  /**
   * Remove a custom-app container and, when `removeImage` is set, its backing image too. Called
   * before deleting the DB record. Image removal is best-effort: a shared/in-use image is left alone.
   */
  async removeCustomAppContainer(
    serviceName: string,
    removeImage = false
  ): Promise<{ success: boolean; message: string }> {
    try {
      const containers = await this.docker.listContainers({ all: true })
      const container = containers.find((c) => c.Names.includes(`/${serviceName}`))

      if (!container) return { success: true, message: 'No container found — nothing to remove' }

      const imageRef = container.Image
      const c = this.docker.getContainer(container.Id)
      if (container.State === 'running') await c.stop()
      await c.remove({ force: true })

      if (removeImage && imageRef) {
        try {
          await this.docker.getImage(imageRef).remove()
        } catch (imgErr: any) {
          // Non-fatal: the image may be shared with another container or already gone.
          logger.warn(`[DockerService] Could not remove image ${imageRef} for ${serviceName}: ${imgErr.message}`)
        }
      }

      this.invalidateServicesStatusCache()
      return { success: true, message: `Container ${serviceName} removed` }
    } catch (error: any) {
      logger.error({ err: error }, `[DockerService] removeCustomAppContainer failed for ${serviceName}`)
      return { success: false, message: error.message }
    }
  }

  /**
   * Uninstall a curated catalog app: stop and remove its container (and, optionally, its image),
   * then mark the record not-installed so the card returns to the available catalog. Host
   * bind-mount data is deliberately left on disk — a later reinstall picks it back up. Contrast
   * with forceReinstall, which clears volumes and immediately recreates the container.
   */
  async uninstallService(
    serviceName: string,
    removeImage = false
  ): Promise<{ success: boolean; message: string }> {
    const service = await Service.query().where('service_name', serviceName).first()
    if (!service || !service.installed) {
      return { success: false, message: `Service ${serviceName} not found or not installed` }
    }

    // Container/image removal is shared with custom-app deletion — the lookup is by container
    // name, which is the service_name for curated and custom apps alike.
    const removal = await this.removeCustomAppContainer(serviceName, removeImage)
    if (!removal.success) return removal

    service.installed = false
    service.installation_status = 'idle'
    await service.save()
    this.invalidateServicesStatusCache()

    return { success: true, message: `Service ${serviceName} uninstalled` }
  }

  /** Find a container by its managed service name (`/serviceName`), or null. */
  private async _findContainerByName(serviceName: string) {
    const containers = await this.docker.listContainers({ all: true })
    return containers.find((c) => c.Names.includes(`/${serviceName}`)) ?? null
  }

  /**
   * Decode the multiplexed stream Docker returns for non-TTY container logs. Each frame is an
   * 8-byte header ([streamType, 0,0,0, big-endian payloadSize]) followed by the payload.
   */
  private _demuxDockerLog(buf: Buffer): string {
    let out = ''
    let offset = 0
    while (offset + 8 <= buf.length) {
      const size = buf.readUInt32BE(offset + 4)
      offset += 8
      if (offset + size > buf.length) {
        out += buf.toString('utf8', offset)
        break
      }
      out += buf.toString('utf8', offset, offset + size)
      offset += size
    }
    return out
  }

  /** Return the last `tail` lines of a service container's combined stdout/stderr. */
  async getContainerLogs(
    serviceName: string,
    tail = 200
  ): Promise<{ success: boolean; logs?: string; message?: string }> {
    try {
      const info = await this._findContainerByName(serviceName)
      if (!info) return { success: false, message: `No container found for ${serviceName}` }

      const container = this.docker.getContainer(info.Id)
      const inspect = await container.inspect()
      const tty = inspect.Config?.Tty ?? false

      const buf = (await container.logs({
        stdout: true,
        stderr: true,
        follow: false,
        tail,
        timestamps: false,
      })) as unknown as Buffer

      const logs = tty ? buf.toString('utf8') : this._demuxDockerLog(buf)
      return { success: true, logs }
    } catch (error: any) {
      logger.error({ err: error }, `[DockerService] getContainerLogs failed for ${serviceName}`)
      return { success: false, message: error.message }
    }
  }

  /**
   * Return a single resource-usage snapshot (CPU %, memory) for a running service container.
   * Uses Docker's non-streaming stats, which include precpu_stats so CPU % is computable.
   */
  async getContainerStats(serviceName: string): Promise<{
    success: boolean
    running?: boolean
    stats?: { cpuPercent: number; memUsageBytes: number; memLimitBytes: number; memPercent: number }
    message?: string
  }> {
    try {
      const info = await this._findContainerByName(serviceName)
      if (!info) return { success: false, message: `No container found for ${serviceName}` }
      if (info.State !== 'running') return { success: true, running: false }

      const container = this.docker.getContainer(info.Id)
      const s: any = await container.stats({ stream: false })

      const cpuDelta =
        (s.cpu_stats?.cpu_usage?.total_usage ?? 0) - (s.precpu_stats?.cpu_usage?.total_usage ?? 0)
      const systemDelta =
        (s.cpu_stats?.system_cpu_usage ?? 0) - (s.precpu_stats?.system_cpu_usage ?? 0)
      const numCpus =
        s.cpu_stats?.online_cpus ?? s.cpu_stats?.cpu_usage?.percpu_usage?.length ?? 1
      const cpuPercent =
        systemDelta > 0 && cpuDelta > 0 ? (cpuDelta / systemDelta) * numCpus * 100 : 0

      // Subtract page cache from usage to better reflect the container's working set.
      const cache = s.memory_stats?.stats?.cache ?? s.memory_stats?.stats?.inactive_file ?? 0
      const memUsageBytes = Math.max(0, (s.memory_stats?.usage ?? 0) - cache)
      const memLimitBytes = s.memory_stats?.limit ?? 0
      const memPercent = memLimitBytes > 0 ? (memUsageBytes / memLimitBytes) * 100 : 0

      return {
        success: true,
        running: true,
        stats: {
          cpuPercent: Math.round(cpuPercent * 10) / 10,
          memUsageBytes,
          memLimitBytes,
          memPercent: Math.round(memPercent * 10) / 10,
        },
      }
    } catch (error: any) {
      logger.error({ err: error }, `[DockerService] getContainerStats failed for ${serviceName}`)
      return { success: false, message: error.message }
    }
  }

  /**
   * Wait for a freshly started container to be "ready". If the image declares a HEALTHCHECK we poll
   * its health until healthy/unhealthy (up to timeoutMs); otherwise we fall back to a 5s settle and
   * a plain Running check. Returns whether it's ready plus a reason when not.
   */
  private async _awaitContainerReady(
    container: any,
    timeoutMs = 30000
  ): Promise<{ ready: boolean; reason?: string }> {
    let inspect = await container.inspect()
    const hasHealthcheck = !!inspect.State?.Health

    if (!hasHealthcheck) {
      await new Promise((r) => setTimeout(r, 5000))
      inspect = await container.inspect()
      return inspect.State?.Running
        ? { ready: true }
        : { ready: false, reason: 'container did not stay running' }
    }

    const deadline = Date.now() + timeoutMs
    while (Date.now() < deadline) {
      inspect = await container.inspect()
      if (!inspect.State?.Running) return { ready: false, reason: 'container exited' }
      const status = inspect.State?.Health?.Status
      if (status === 'healthy') return { ready: true }
      if (status === 'unhealthy') return { ready: false, reason: 'failed its health check' }
      await new Promise((r) => setTimeout(r, 2000))
    }
    // Still in "starting" at timeout — accept it if it's at least running rather than roll back a slow boot.
    return inspect.State?.Running ? { ready: true } : { ready: false, reason: 'health check timed out' }
  }

  /**
   * Recreate a custom app's container from its (already-updated) Service record, preserving data.
   * Uses the same rename-and-rollback safety net as the update flow: the live container is renamed
   * aside, a new one is created from the new config/image, health-gated, and only then is the old one
   * removed — otherwise we roll back to it. Bind-mounted data is untouched throughout. Pass
   * `forcePull` to always re-pull the image first (used by the "update" action for moving tags).
   */
  async recreateCustomAppContainer(
    serviceName: string,
    opts: { forcePull?: boolean } = {}
  ): Promise<{ success: boolean; message: string }> {
    const service = await Service.query().where('service_name', serviceName).first()
    if (!service) return { success: false, message: `Service ${serviceName} not found` }

    const containerConfig = this._parseContainerConfig(service.container_config)
    const oldInfo = await this._findContainerByName(serviceName)
    const oldName = `${serviceName}_old`

    // Clear any stale `_old` left behind by a previous recreate that died mid-flight. Without this,
    // the rename below would fail (name in use) and the rollback path would then destroy the live
    // container and resurrect the stale one in its place.
    const staleOld = await this._findContainerByName(oldName)
    if (staleOld) {
      await this.docker.getContainer(staleOld.Id).remove({ force: true }).catch(() => {})
    }

    try {
      // Stop + rename the existing container aside as a rollback safety net.
      if (oldInfo) {
        const oldContainer = this.docker.getContainer(oldInfo.Id)
        if (oldInfo.State === 'running') await oldContainer.stop({ t: 10 }).catch(() => {})
        await oldContainer.rename({ name: oldName })
      }

      // Pull the image if it's missing locally, or always when forcePull (e.g. :latest updates).
      if (opts.forcePull || !(await this._checkImageExists(service.container_image))) {
        await this.pullImage(service.container_image)
      }

      // Runtime-injected secrets (e.g. Homebox's API-key pepper, #1043) live in the KV store, not
      // in container_config. This path rebuilds Env from container_config alone, so re-inject them
      // here — otherwise an Edit or in-place recreate drops the pepper and Homebox crash-loops again.
      let recreateEnv: string[] = containerConfig?.Env ?? []
      if (
        serviceName === SERVICE_NAMES.HOMEBOX &&
        !recreateEnv.some((e: string) => e.startsWith('HBOX_AUTH_API_KEY_PEPPER='))
      ) {
        recreateEnv = [...recreateEnv, `HBOX_AUTH_API_KEY_PEPPER=${await this._resolveHomeboxPepper()}`]
      }

      const newContainer = await this.docker.createContainer({
        Image: service.container_image,
        name: serviceName,
        Labels: {
          ...(containerConfig?.Labels ?? {}),
          'com.docker.compose.project': 'project-nomad-managed',
          'io.project-nomad.managed': 'true',
        },
        ...(containerConfig?.User && { User: containerConfig.User }),
        HostConfig: containerConfig?.HostConfig ?? {},
        ...(containerConfig?.ExposedPorts && { ExposedPorts: containerConfig.ExposedPorts }),
        ...(recreateEnv.length ? { Env: recreateEnv } : {}),
        ...(service.container_command ? { Cmd: service.container_command.split(' ') } : {}),
        ...(process.env.NODE_ENV === 'production' && {
          NetworkingConfig: { EndpointsConfig: { [DockerService.NOMAD_NETWORK]: {} } },
        }),
      })
      await newContainer.start()

      // Health gate before discarding the old container.
      const readiness = await this._awaitContainerReady(newContainer)
      if (!readiness.ready) throw new Error(`recreated container ${readiness.reason}`)

      if (oldInfo) {
        const oldRef = await this._findContainerByName(oldName)
        if (oldRef) await this.docker.getContainer(oldRef.Id).remove({ force: true })
      }
      service.installed = true
      service.installation_status = 'idle'
      await service.save()
      this.invalidateServicesStatusCache()
      return { success: true, message: `Service ${serviceName} reconfigured successfully` }
    } catch (error: any) {
      logger.error({ err: error }, `[DockerService] recreateCustomAppContainer failed for ${serviceName}`)
      // Roll back: discard the failed new container and restore the renamed original.
      try {
        const failedNew = await this._findContainerByName(serviceName)
        if (failedNew) {
          const c = this.docker.getContainer(failedNew.Id)
          await c.stop({ t: 5 }).catch(() => {})
          await c.remove({ force: true }).catch(() => {})
        }
        const renamed = await this._findContainerByName(oldName)
        if (renamed) {
          const c = this.docker.getContainer(renamed.Id)
          await c.rename({ name: serviceName })
          await c.start().catch(() => {})
        }
      } catch (rollbackError: any) {
        logger.error({ err: rollbackError }, `[DockerService] rollback failed for ${serviceName}`)
      }
      this.invalidateServicesStatusCache()
      return { success: false, message: `Reconfigure failed and was rolled back: ${error.message}` }
    }
  }

  /**
   * Check if a Docker image exists locally.
   * @param imageName - The name and tag of the image (e.g., "nginx:latest")
   * @returns - True if the image exists locally, false otherwise
   */
  private async _checkImageExists(imageName: string): Promise<boolean> {
    try {
      const images = await this.docker.listImages()

      // Check if any image has a RepoTag that matches the requested image
      return images.some((image) => image.RepoTags && image.RepoTags.includes(imageName))
    } catch (error: any) {
      logger.warn(`Error checking if image exists: ${error.message}`)
      // If run into an error, assume the image does not exist
      return false
    }
  }
}

import Markdoc from '@markdoc/markdoc'
import { streamToString } from '../../util/docs.js'
import { getFile, getFileStatsIfExists, listDirectoryContentsRecursive } from '../utils/fs.js'
import path from 'path'
import InternalServerErrorException from '#exceptions/internal_server_error_exception'
import logger from '@adonisjs/core/services/logger'

export class DocsService {
  private docsPath = path.join(process.cwd(), 'docs')

  private static readonly DOC_ORDER: Record<string, number> = {
    'home': 1,
    'getting-started': 2,
    'use-cases': 3,
    'supply-depot-apps': 4,
    'drug-reference': 5,
    'community-add-ons': 6,
    'updates': 7,
    'faq': 8,
    'about': 9,
    'release-notes': 10,
  }

  async getDocs() {
    const contents = await listDirectoryContentsRecursive(this.docsPath)
    const files: Array<{ title: string; slug: string }> = []

    for (const item of contents) {
      if (item.type === 'file' && item.name.endsWith('.md')) {
        const cleaned = this.prettify(item.name)
        files.push({
          title: cleaned,
          slug: item.name.replace(/\.md$/, ''),
        })
      }
    }

    return files.sort((a, b) => {
      const orderA = DocsService.DOC_ORDER[a.slug] ?? 999
      const orderB = DocsService.DOC_ORDER[b.slug] ?? 999
      return orderA - orderB
    })
  }

  parse(content: string) {
    try {
      const ast = Markdoc.parse(content)
      const config = this.getConfig()
      const errors = Markdoc.validate(ast, config)

      // Filter out attribute-undefined errors which may be caused by emojis and special characters
      const criticalErrors = errors.filter((e) => e.error.id !== 'attribute-undefined')
      if (criticalErrors.length > 0) {
        logger.error('Markdoc validation errors:', errors.map((e) => JSON.stringify(e.error)).join(', '))
        throw new Error('Markdoc validation failed')
      }

      return Markdoc.transform(ast, config)
    } catch (error) {
      logger.error('Error parsing Markdoc content:', error)
      throw new InternalServerErrorException(`Error parsing content: ${(error as Error).message}`)
    }
  }

  async parseFile(_filename: string) {
    try {
      if (!_filename) {
        throw new Error('Filename is required')
      }

      const filename = _filename.endsWith('.md') ? _filename : `${_filename}.md`

      // Prevent path traversal — resolved path must stay within the docs directory
      const basePath = path.resolve(this.docsPath)
      const fullPath = path.resolve(path.join(this.docsPath, filename))
      if (!fullPath.startsWith(basePath + path.sep)) {
        throw new Error('Invalid document slug')
      }

      const fileExists = await getFileStatsIfExists(fullPath)
      if (!fileExists) {
        throw new Error(`File not found: ${filename}`)
      }

      const fileStream = await getFile(fullPath, 'stream')
      if (!fileStream) {
        throw new Error(`Failed to read file stream: ${filename}`)
      }
      const content = await streamToString(fileStream)
      return this.parse(content)
    } catch (error) {
      throw new InternalServerErrorException(`Error parsing file: ${(error as Error).message}`)
    }
  }

  private static readonly TITLE_OVERRIDES: Record<string, string> = {
    'faq': 'FAQ',
    'community-add-ons': 'Community Add-Ons',
  }

  private prettify(filename: string) {
    const slug = filename.replace(/\.md$/, '')
    if (DocsService.TITLE_OVERRIDES[slug]) {
      return DocsService.TITLE_OVERRIDES[slug]
    }
    // Remove hyphens, underscores, and file extension
    const cleaned = slug.replace(/_/g, ' ').replace(/-/g, ' ')
    // Convert to Title Case
    const titleCased = cleaned.replace(/\b\w/g, (char) => char.toUpperCase())
    return titleCased.charAt(0).toUpperCase() + titleCased.slice(1)
  }

  private getConfig() {
    return {
      tags: {
        callout: {
          render: 'Callout',
          attributes: {
            type: {
              type: String,
              default: 'info',
              matches: ['info', 'warning', 'error', 'success'],
            },
            title: {
              type: String,
            },
          },
        },
      },
      nodes: {
        heading: {
          render: 'Heading',
          attributes: {
            level: { type: Number, required: true },
            id: { type: String },
          },
        },
        list: {
          render: 'List',
          attributes: {
            ordered: { type: Boolean },
            start: { type: Number },
          },
        },
        list_item: {
          render: 'ListItem',
          attributes: {
            marker: { type: String },
            className: { type: String },
            class: { type: String }
          }
        },
        table: {
          render: 'Table',
        },
        thead: {
          render: 'TableHead',
        },
        tbody: {
          render: 'TableBody',
        },
        tr: {
          render: 'TableRow',
        },
        th: {
          render: 'TableHeader',
        },
        td: {
          render: 'TableCell',
        },
        paragraph: {
          render: 'Paragraph',
        },
        image: {
          render: 'Image',
          attributes: {
            src: { type: String, required: true },
            alt: { type: String },
            title: { type: String },
          },
        },
        link: {
          render: 'Link',
          attributes: {
            href: { type: String, required: true },
            title: { type: String },
          },
        },
        fence: {
          render: 'CodeBlock',
          attributes: {
            content: { type: String },
            language: { type: String },
          },
        },
        code: {
          render: 'InlineCode',
          attributes: {
            content: { type: String },
          },
        },
        hr: {
          render: 'HorizontalRule',
        },
      },
    }
  }
}

import { inject } from '@adonisjs/core'
import { QueueService } from './queue_service.js'
import { RunDownloadJob } from '#jobs/run_download_job'
import { RunExtractPmtilesJob } from '#jobs/run_extract_pmtiles_job'
import type { RunExtractPmtilesJobParams } from '#jobs/run_extract_pmtiles_job'
import { DownloadModelJob } from '#jobs/download_model_job'
import { DownloadDrugDataJob } from '#jobs/download_drug_data_job'
import { DownloadJobWithProgress, DownloadProgressData, RunDownloadJobParams } from '../../types/downloads.js'
import type { Job, Queue } from 'bullmq'
import { normalize } from 'path'
import { deleteFileIfExists } from '../utils/fs.js'
import transmit from '@adonisjs/transmit/services/main'
import { BROADCAST_CHANNELS } from '../../constants/broadcast.js'

type FileJobState = 'waiting' | 'active' | 'delayed' | 'failed'
type TaggedJob = { job: Job; state: FileJobState }

@inject()
export class DownloadService {
  constructor(private queueService: QueueService) {}

  private parseProgress(progress: any): { percent: number; downloadedBytes?: number; totalBytes?: number; lastProgressTime?: number } {
    if (typeof progress === 'object' && progress !== null && 'percent' in progress) {
      const p = progress as DownloadProgressData
      return {
        percent: p.percent,
        downloadedBytes: p.downloadedBytes,
        totalBytes: p.totalBytes,
        lastProgressTime: p.lastProgressTime,
      }
    }
    // Backward compat: plain integer from in-flight jobs during upgrade
    return { percent: parseInt(String(progress), 10) || 0 }
  }

  /** Fetch all non-completed jobs from a queue, tagged with their current BullMQ state */
  private async fetchJobsWithStates(queueName: string): Promise<TaggedJob[]> {
    const queue = this.queueService.getQueue(queueName)
    const [waiting, active, delayed, failed] = await Promise.all([
      queue.getJobs(['waiting']),
      queue.getJobs(['active']),
      queue.getJobs(['delayed']),
      queue.getJobs(['failed']),
    ])
    return [
      ...waiting.map((j) => ({ job: j, state: 'waiting' as const })),
      ...active.map((j) => ({ job: j, state: 'active' as const })),
      ...delayed.map((j) => ({ job: j, state: 'delayed' as const })),
      ...failed.map((j) => ({ job: j, state: 'failed' as const })),
      // A job id can outlive its payload hash — BullMQ still returns an entry for
      // it, with `data` empty. One of those in the failed set used to throw on
      // every poll of this endpoint (normalize(undefined)), and because failed
      // jobs are never evicted the endpoint stayed broken until Redis was cleared
      // by hand. Drop them: with no payload there is nothing to show anyway.
    ].filter(({ job }) => job?.id != null && job.data != null)
  }

  async listDownloadJobs(filetype?: string): Promise<DownloadJobWithProgress[]> {
    const [fileTagged, extractTagged, modelTagged, drugTagged] = await Promise.all([
      this.fetchJobsWithStates(RunDownloadJob.queue),
      this.fetchJobsWithStates(RunExtractPmtilesJob.queue),
      this.fetchJobsWithStates(DownloadModelJob.queue),
      this.fetchJobsWithStates(DownloadDrugDataJob.queue),
    ])

    const fileDownloads = fileTagged.map(({ job, state }) => {
      const parsed = this.parseProgress(job.progress)
      return {
        jobId: job.id!.toString(),
        url: job.data.url,
        progress: parsed.percent,
        filepath: job.data.filepath ? normalize(job.data.filepath) : '',
        filetype: job.data.filetype,
        title: job.data.title || undefined,
        downloadedBytes: parsed.downloadedBytes,
        totalBytes: parsed.totalBytes || job.data.totalBytes || undefined,
        lastProgressTime: parsed.lastProgressTime,
        status: state,
        failedReason: job.failedReason || undefined,
      }
    })

    const extractDownloads = extractTagged.map(({ job, state }) => {
      const parsed = this.parseProgress(job.progress)
      return {
        jobId: job.id!.toString(),
        url: job.data.sourceUrl,
        progress: parsed.percent,
        filepath: job.data.outputFilepath ? normalize(job.data.outputFilepath) : '',
        filetype: job.data.filetype || 'map',
        title: job.data.title || undefined,
        downloadedBytes: parsed.downloadedBytes,
        totalBytes: parsed.totalBytes || job.data.estimatedBytes || undefined,
        lastProgressTime: parsed.lastProgressTime,
        status: state,
        failedReason: job.failedReason || undefined,
      }
    })

    const modelDownloads = modelTagged.map(({ job }) => ({
      jobId: job.id!.toString(),
      url: job.data.modelName || 'Unknown Model',
      progress: parseInt(job.progress.toString(), 10),
      filepath: job.data.modelName || 'Unknown Model',
      filetype: 'model',
      status: (job.failedReason ? 'failed' : 'active') as 'active' | 'failed',
      failedReason: job.failedReason || undefined,
    }))

    // FDA drug dataset — DOWNLOAD phase only, collapsed to ONE card. The job fans
    // the manifest's N partitions into continuations under AUTO-GENERATED jobIds
    // (only part 0 runs under the deterministic jobId), and the queue is
    // concurrency 1, so at most one part is ever in flight. Filtering to the
    // deterministic jobId would track only part 0 and then drop the card while
    // parts 2..N keep downloading. Instead represent the whole download with the
    // single in-flight job's aggregate progress (the progress emit already spans
    // all parts), and always report the deterministic jobId so the cancel/remove
    // button routes to _cancelDrugDownloadJob whichever part is active. The heavy
    // ingest is EXCLUDED here — it stays on the IngestStatus surface.
    const drugInFlight =
      drugTagged.find(({ state }) => state === 'active') ??
      drugTagged.find(({ state }) => state === 'waiting' || state === 'delayed') ??
      drugTagged.find(({ state }) => state === 'failed')
    const drugDownloads = drugInFlight
      ? [drugInFlight].map(({ job, state }) => {
          const parsed = this.parseProgress(job.progress)
          return {
            jobId: DownloadDrugDataJob.jobId,
            url: 'https://api.fda.gov/download.json',
            progress: parsed.percent,
            filepath: job.data.currentPartName || 'FDA Drug Reference',
            filetype: 'drug-data',
            title: 'FDA Drug Reference',
            downloadedBytes: parsed.downloadedBytes,
            totalBytes: parsed.totalBytes,
            lastProgressTime: parsed.lastProgressTime,
            status: state,
            failedReason: job.failedReason || undefined,
          }
        })
      : []

    const allDownloads = [...fileDownloads, ...extractDownloads, ...modelDownloads, ...drugDownloads]
    const filtered = allDownloads.filter((job) => !filetype || job.filetype === filetype)

    return filtered.sort((a, b) => {
      if (a.status === 'failed' && b.status !== 'failed') return 1
      if (a.status !== 'failed' && b.status === 'failed') return -1
      return b.progress - a.progress
    })
  }

  async removeFailedJob(jobId: string): Promise<void> {
    for (const queueName of [
      RunDownloadJob.queue,
      RunExtractPmtilesJob.queue,
      DownloadModelJob.queue,
      DownloadDrugDataJob.queue,
    ]) {
      const queue = this.queueService.getQueue(queueName)
      const job = await queue.getJob(jobId)
      if (job) {
        try {
          await job.remove()
        } catch {
          // Job may be locked by the worker after cancel. Remove the stale lock and retry.
          try {
            const client = await queue.client
            await client.del(`bull:${queueName}:${jobId}:lock`)
            await job.remove()
          } catch {
            // Last resort: already removed or truly stuck
          }
        }
        return
      }
    }
  }

  async retryFailedJob(jobId: string): Promise<{ success: boolean; message: string }> {
    // Search both the file download queue and the model download queue
    for (const queueName of [RunDownloadJob.queue, DownloadModelJob.queue]) {
      const queue = this.queueService.getQueue(queueName)
      const job = await queue.getJob(jobId)

      if (job) {
        // For Ollama model downloads, re-dispatch with the model name
        if (queueName === DownloadModelJob.queue) {
          const modelName = job.data.modelName
          if (!modelName) {
            return { success: false, message: 'Cannot retry: model name not found in job data' }
          }
          // Remove the old failed job first, then dispatch a fresh one. The
          // model jobId is a hash of the model name, so dispatching first meant
          // this remove() targeted the job we had just enqueued under that same
          // id rather than the old record, deleting the retry we were creating.
          // Matches the file-download branch below.
          await job.remove().catch(() => {})
          await DownloadModelJob.dispatch({ modelName })
          return { success: true, message: `Retrying download for model ${modelName}` }
        }

        // For file downloads (zim, map, etc.), re-dispatch with original params
        const params = job.data as RunDownloadJobParams
        if (!params.url || !params.filepath) {
          return { success: false, message: 'Cannot retry: missing URL or filepath in job data' }
        }

        // Remove the old failed job, then dispatch a fresh one
        await job.remove().catch(() => {})
        await RunDownloadJob.dispatch(params)
        return { success: true, message: `Retrying download for ${params.url}` }
      }
    }

    return { success: false, message: 'Failed job not found. It may have already been dismissed.' }
  }

  async cancelJob(jobId: string): Promise<{ success: boolean; message: string }> {
    const queue = this.queueService.getQueue(RunDownloadJob.queue)
    const job = await queue.getJob(jobId)

    if (job) {
      return await this._cancelFileDownloadJob(jobId, job, queue)
    }

    const extractQueue = this.queueService.getQueue(RunExtractPmtilesJob.queue)
    const extractJob = await extractQueue.getJob(jobId)

    if (extractJob) {
      return await this._cancelExtractJob(jobId, extractJob, extractQueue)
    }

    const modelQueue = this.queueService.getQueue(DownloadModelJob.queue)
    const modelJob = await modelQueue.getJob(jobId)

    if (modelJob) {
      return await this._cancelModelDownloadJob(jobId, modelJob, modelQueue)
    }

    // FDA drug dataset: cancel is matched on the deterministic jobId only (the
    // single card the aggregator shows). The continuation parts run under
    // auto-generated ids, so cancelling must stop the whole CHAIN, not just the
    // current part — otherwise the next continuation fires after we remove one.
    if (jobId === DownloadDrugDataJob.jobId) {
      return await this._cancelDrugDownloadJob()
    }

    return { success: true, message: 'Job not found (may have already completed)' }
  }

  /**
   * Cancel the FDA drug-data download.
   *
   * The drug job has no Redis cancel-signal / AbortController (unlike
   * RunDownloadJob), and it self-continues into the next part under a fresh jobId.
   * So a v1 cancel that only removed the current job would leave the next
   * continuation to fire. Instead we obliterate the single-purpose drug-download
   * queue (force = removes the active/locked job too), which drops the current
   * part AND every queued continuation in one shot. Scoped to the drug-download
   * queue only — the ingest queue and everything else are untouched. The on-disk
   * parts are intentionally LEFT in place: they're resumable, and a re-trigger
   * picks up from the .tmp rather than re-downloading. (Tracked as the v1 choice
   * for cancel depth — full cross-process signal cancel is a follow-up.)
   */
  private async _cancelDrugDownloadJob(): Promise<{ success: boolean; message: string }> {
    const queue = this.queueService.getQueue(DownloadDrugDataJob.queue)
    try {
      await queue.obliterate({ force: true })
      return { success: true, message: 'Drug data download cancelled' }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      return { success: false, message: `Could not cancel drug data download: ${msg}` }
    }
  }

  private async _cancelExtractJob(
    jobId: string,
    job: Job<RunExtractPmtilesJobParams>,
    queue: Queue<RunExtractPmtilesJobParams>
  ): Promise<{ success: boolean; message: string }> {
    const outputFilepath = job.data.outputFilepath

    await RunExtractPmtilesJob.signalCancel(jobId)

    // Same-process fallback when worker and API share a process
    RunExtractPmtilesJob.childProcesses.get(jobId)?.kill('SIGTERM')
    RunExtractPmtilesJob.childProcesses.delete(jobId)

    await this._pollForTerminalState(job, jobId)
    await this._removeJobWithLockFallback(job, queue, RunExtractPmtilesJob.queue, jobId)

    if (outputFilepath) {
      try {
        await deleteFileIfExists(outputFilepath)
      } catch {
        // File may not exist yet (subprocess may not have opened it)
      }
    }

    return { success: true, message: 'Extract cancelled and partial file deleted' }
  }

  /** Cancel a content download (zim, map, pmtiles, etc.) */
  private async _cancelFileDownloadJob(
    jobId: string,
    job: any,
    queue: any
  ): Promise<{ success: boolean; message: string }> {
    const filepath = job.data.filepath

    // Signal the worker process to abort the download via Redis
    await RunDownloadJob.signalCancel(jobId)

    // Also try in-memory abort (works if worker is in same process)
    RunDownloadJob.abortControllers.get(jobId)?.abort('user-cancel')
    RunDownloadJob.abortControllers.delete(jobId)

    await this._pollForTerminalState(job, jobId)
    await this._removeJobWithLockFallback(job, queue, RunDownloadJob.queue, jobId)

    // Delete the partial file from disk
    if (filepath) {
      try {
        await deleteFileIfExists(filepath)
        // Also try .tmp in case PR #448 staging is merged
        await deleteFileIfExists(filepath + '.tmp')
      } catch {
        // File may not exist yet (waiting job)
      }
    }

    // If this was a Wikipedia download, update selection status to failed
    // (the worker's failed event may not fire if we removed the job first)
    if (job.data.filetype === 'zim' && job.data.url?.includes('wikipedia_en_')) {
      try {
        const { DockerService } = await import('#services/docker_service')
        const { ZimService } = await import('#services/zim_service')
        const dockerService = new DockerService()
        const zimService = new ZimService(dockerService)
        await zimService.onWikipediaDownloadComplete(job.data.url, false)
      } catch {
        // Best effort
      }
    }

    return { success: true, message: 'Download cancelled and partial file deleted' }
  }

  /** Cancel an Ollama model download — mirrors the file cancel pattern but skips file cleanup */
  private async _cancelModelDownloadJob(
    jobId: string,
    job: any,
    queue: any
  ): Promise<{ success: boolean; message: string }> {
    const modelName: string = job.data?.modelName ?? 'unknown'

    // Signal the worker process to abort the pull via Redis
    await DownloadModelJob.signalCancel(jobId)

    // Also try in-memory abort (works if worker is in same process)
    DownloadModelJob.abortControllers.get(jobId)?.abort('user-cancel')
    DownloadModelJob.abortControllers.delete(jobId)

    await this._pollForTerminalState(job, jobId)
    await this._removeJobWithLockFallback(job, queue, DownloadModelJob.queue, jobId)

    // Broadcast a cancelled event so the frontend hook clears the entry. We use percent: -2
    // (distinct from -1 = error) so the hook can route it to a 2s auto-clear instead of the
    // 15s error display. The frontend ALSO removes the entry optimistically from the API
    // response, so this is belt-and-suspenders for cases where the SSE arrives first.
    transmit.broadcast(BROADCAST_CHANNELS.OLLAMA_MODEL_DOWNLOAD, {
      model: modelName,
      jobId,
      percent: -2,
      status: 'cancelled',
      timestamp: new Date().toISOString(),
    })

    // Note on partial blob cleanup: Ollama manages model blobs internally at
    // /root/.ollama/models/blobs/. We deliberately do NOT call /api/delete here — Ollama's
    // expected behavior is to retain partial blobs so a re-pull resumes from where it left
    // off. If the user wants to reclaim that space, they can re-pull and let it complete,
    // or delete the partially-downloaded model from the AI Settings page.
    return { success: true, message: 'Model download cancelled' }
  }

  /** Wait up to 4s (250ms intervals) for the job to reach a terminal state */
  private async _pollForTerminalState(job: any, jobId: string): Promise<void> {
    const POLL_INTERVAL_MS = 250
    const POLL_TIMEOUT_MS = 4000
    const deadline = Date.now() + POLL_TIMEOUT_MS

    while (Date.now() < deadline) {
      await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS))
      try {
        const state = await job.getState()
        if (state === 'failed' || state === 'completed' || state === 'unknown') {
          return
        }
      } catch {
        return // getState() throws if job is already gone
      }
    }

    console.warn(
      `[DownloadService] cancelJob: job ${jobId} did not reach terminal state within timeout, removing anyway`
    )
  }

  /** Remove a BullMQ job, clearing a stale worker lock if the first attempt fails */
  private async _removeJobWithLockFallback(
    job: any,
    queue: any,
    queueName: string,
    jobId: string
  ): Promise<void> {
    try {
      await job.remove()
    } catch {
      // Lock contention fallback: clear lock and retry once
      try {
        const client = await queue.client
        await client.del(`bull:${queueName}:${jobId}:lock`)
        const updatedJob = await queue.getJob(jobId)
        if (updatedJob) await updatedJob.remove()
      } catch {
        // Best effort - job will be cleaned up on next dismiss attempt
      }
    }
  }
}

import db from '@adonisjs/lucid/services/db'
import logger from '@adonisjs/core/services/logger'
import { rm } from 'node:fs/promises'
import type { Job } from 'bullmq'
import { QueueService } from './queue_service.js'
import { DownloadDrugDataJob, STORAGE_BASE } from '#jobs/download_drug_data_job'
import { IngestDrugDataJob } from '#jobs/ingest_drug_data_job'

/**
 * Manifest resource id for the FDA drug dataset — the `installed_resources`
 * row's `resource_id`, matching the `medicine-standard` tier manifest entry.
 * Single source of truth so the install write-back, the tier-status math, and
 * uninstall all agree on the same id.
 */
export const DRUG_DATASET_RESOURCE_ID = 'openfda-drug-labels'
import {
  normalizeDrugName,
  parseDownloadState,
  deriveIngestPhase,
  resolveExpectedTotal,
  resolveIngestRecordsShown,
  summarizeJobError,
  isExportDateNewer,
} from '../../util/drug_labels.js'
import KVStore from '#models/kv_store'
import { parseCompareIds, MAX_COMPARE } from '../../util/compare_ids.js'
import type {
  DrugSearchResult,
  DrugLabelDetail,
  DrugIngestStatus,
  DrugPhaseState,
  DrugDownloadStatus,
  DrugIngestPhaseStatus,
  DrugInteractionEntry,
} from '../../types/drug_reference.js'

/**
 * Drug Reference v1 — service layer.
 *
 * Exposes search (collapsed by brand+generic), detail fetch, ingest trigger,
 * and ingest status. Mirrors the shape of DownloadService/ZimService.
 */
export class DrugReferenceService {
  /**
   * Search for drug labels, collapsed by (brand_name, generic_name).
   *
   * Each distinct (brand_name, generic_name) pair returns ONE result — a
   * representative row id (MIN(id)) and a labelCount of how many set_ids
   * collapsed into it. This is the locked UX decision.
   *
   * Scope:
   *   'name'       (default) — existing path: MATCH(searchable_name) on brand+generic.
   *   'indication' — new path: MATCH(searchable_name, indications) on the combined
   *                  ft_drug_labels_name_indications index so users can search by
   *                  what a drug treats ("heartburn", "high blood pressure").
   *
   * Strategy (both scopes):
   *   1. FULLTEXT path: MATCH(cols) AGAINST(? IN NATURAL LANGUAGE MODE)
   *      — relevance-ranked, requires >= 3 chars (innodb_ft_min_token_size = 3).
   *   2. LIKE fallback: query < 3 chars OR FULLTEXT throws → LIKE '%term%'.
   *   3. Both paths apply the optional product_type filter and GROUP BY collapse.
   */
  async search(
    query: string,
    options: {
      productType?: string
      route?: string
      sort?: 'relevance' | 'name'
      limit?: number
      offset?: number
      scope?: 'name' | 'indication'
    }
  ): Promise<DrugSearchResult[]> {
    const limit = options.limit ?? 50
    const offset = options.offset ?? 0
    const scope = options.scope ?? 'name'
    const normalized = normalizeDrugName(query, null) ?? query.trim()

    if (!normalized || normalized.length === 0) return []

    const useLike = normalized.length < 3

    if (scope === 'indication') {
      if (!useLike) {
        try {
          return await this.searchIndicationFulltext(normalized, options.productType, limit, offset)
        } catch (err) {
          logger.warn(
            `[DrugReferenceService] FULLTEXT indication search failed, falling back to LIKE: ${
              err instanceof Error ? err.message : String(err)
            }`
          )
        }
      }
      return await this.searchIndicationLike(normalized, options.productType, limit, offset)
    }

    if (!useLike) {
      // FULLTEXT path
      try {
        return await this.searchFulltext(normalized, options, limit, offset)
      } catch (err) {
        logger.warn(
          `[DrugReferenceService] FULLTEXT search failed, falling back to LIKE: ${
            err instanceof Error ? err.message : String(err)
          }`
        )
      }
    }

    // LIKE fallback
    return await this.searchLike(normalized, options, limit, offset)
  }

  private async searchFulltext(
    normalized: string,
    opts: { productType?: string; route?: string; sort?: 'relevance' | 'name' },
    limit: number,
    offset: number
  ): Promise<DrugSearchResult[]> {
    let sql = `
      SELECT
        MIN(id) AS id,
        brand_name,
        generic_name,
        MIN(manufacturer) AS manufacturer,
        MIN(route) AS route,
        MIN(product_type) AS product_type,
        COUNT(*) AS labelCount,
        MAX(MATCH(searchable_name) AGAINST(? IN NATURAL LANGUAGE MODE)) AS relevance
      FROM drug_labels
      WHERE MATCH(searchable_name) AGAINST(? IN NATURAL LANGUAGE MODE)
    `
    const bindings: unknown[] = [normalized, normalized]

    if (opts.productType) {
      sql += ' AND product_type = ?'
      bindings.push(opts.productType)
    }
    if (opts.route) {
      // `route` is a comma-joined uppercase list (e.g. "ORAL, TOPICAL").
      sql += ' AND route LIKE ?'
      bindings.push(`%${opts.route.toUpperCase()}%`)
    }

    sql += `
      GROUP BY brand_name, generic_name
      ORDER BY ${opts.sort === 'name' ? 'COALESCE(brand_name, generic_name) ASC' : 'relevance DESC'}
      LIMIT ? OFFSET ?
    `
    bindings.push(limit, offset)

    const rows = await db.rawQuery(sql, bindings)
    return this.mapSearchRows(rows[0])
  }

  private async searchLike(
    normalized: string,
    opts: { productType?: string; route?: string; sort?: 'relevance' | 'name' },
    limit: number,
    offset: number
  ): Promise<DrugSearchResult[]> {
    const term = `%${normalized}%`
    let sql = `
      SELECT
        MIN(id) AS id,
        brand_name,
        generic_name,
        MIN(manufacturer) AS manufacturer,
        MIN(route) AS route,
        MIN(product_type) AS product_type,
        COUNT(*) AS labelCount
      FROM drug_labels
      WHERE (searchable_name LIKE ? OR brand_name LIKE ?)
    `
    const bindings: unknown[] = [term, term]

    if (opts.productType) {
      sql += ' AND product_type = ?'
      bindings.push(opts.productType)
    }
    if (opts.route) {
      sql += ' AND route LIKE ?'
      bindings.push(`%${opts.route.toUpperCase()}%`)
    }

    sql += `
      GROUP BY brand_name, generic_name
      ORDER BY brand_name ASC
      LIMIT ? OFFSET ?
    `
    bindings.push(limit, offset)

    const rows = await db.rawQuery(sql, bindings)
    return this.mapSearchRows(rows[0])
  }

  /**
   * FULLTEXT indication-scope search.
   *
   * MATCHes over (searchable_name, indications) — must exactly match the
   * ft_drug_labels_name_indications index column list. The MAX(MATCH …) pattern
   * is LOAD-BEARING: MySQL 8.0 ONLY_FULL_GROUP_BY rejects a bare MATCH() in
   * SELECT when GROUP BY is in effect; wrapping in MAX() makes it an aggregate
   * and satisfies the mode constraint.
   */
  private async searchIndicationFulltext(
    normalized: string,
    productType: string | undefined,
    limit: number,
    offset: number
  ): Promise<DrugSearchResult[]> {
    let sql = `
      SELECT
        MIN(id) AS id,
        brand_name,
        generic_name,
        MIN(manufacturer) AS manufacturer,
        MIN(route) AS route,
        MIN(product_type) AS product_type,
        COUNT(*) AS labelCount,
        MAX(MATCH(searchable_name, indications) AGAINST(? IN NATURAL LANGUAGE MODE)) AS relevance
      FROM drug_labels
      WHERE MATCH(searchable_name, indications) AGAINST(? IN NATURAL LANGUAGE MODE)
    `
    const bindings: unknown[] = [normalized, normalized]

    if (productType) {
      sql += ' AND product_type = ?'
      bindings.push(productType)
    }

    sql += `
      GROUP BY brand_name, generic_name
      ORDER BY relevance DESC
      LIMIT ? OFFSET ?
    `
    bindings.push(limit, offset)

    const rows = await db.rawQuery(sql, bindings)
    return this.mapSearchRows(rows[0])
  }

  /**
   * LIKE indication-scope fallback (query < 3 chars or FULLTEXT unavailable).
   *
   * Searches searchable_name OR indications so short queries still return
   * useful results without requiring the FULLTEXT index.
   */
  private async searchIndicationLike(
    normalized: string,
    productType: string | undefined,
    limit: number,
    offset: number
  ): Promise<DrugSearchResult[]> {
    const term = `%${normalized}%`
    let sql = `
      SELECT
        MIN(id) AS id,
        brand_name,
        generic_name,
        MIN(manufacturer) AS manufacturer,
        MIN(route) AS route,
        MIN(product_type) AS product_type,
        COUNT(*) AS labelCount
      FROM drug_labels
      WHERE (searchable_name LIKE ? OR indications LIKE ?)
    `
    const bindings: unknown[] = [term, term]

    if (productType) {
      sql += ' AND product_type = ?'
      bindings.push(productType)
    }

    sql += `
      GROUP BY brand_name, generic_name
      ORDER BY brand_name ASC
      LIMIT ? OFFSET ?
    `
    bindings.push(limit, offset)

    const rows = await db.rawQuery(sql, bindings)
    return this.mapSearchRows(rows[0])
  }

  private mapSearchRows(rows: any[]): DrugSearchResult[] {
    if (!Array.isArray(rows)) return []
    return rows.map((row) => ({
      id: Number(row.id),
      brand_name: row.brand_name ?? null,
      generic_name: row.generic_name ?? null,
      manufacturer: row.manufacturer ?? null,
      route: row.route ?? null,
      product_type: row.product_type ?? null,
      labelCount: Number(row.labelCount ?? row.labelcount ?? 1),
    }))
  }

  /**
   * Load the full detail for a single drug label row by its surrogate id.
   * Returns null if the row doesn't exist.
   */
  async find(id: number): Promise<DrugLabelDetail | null> {
    const { default: DrugLabel } = await import('#models/drug_label')
    const row = await DrugLabel.find(id)
    if (!row) return null

    return {
      id: row.id,
      set_id: row.set_id,
      spl_id: row.spl_id,
      version: row.version,
      brand_name: row.brand_name,
      generic_name: row.generic_name,
      manufacturer: row.manufacturer,
      product_ndc: row.product_ndc,
      route: row.route,
      product_type: row.product_type,
      indications: row.indications,
      dosage: row.dosage,
      warnings: row.warnings,
      boxed_warning: row.boxed_warning,
      drug_interactions: row.drug_interactions,
      contraindications: row.contraindications,
      when_using: row.when_using,
      stop_use: row.stop_use,
      source_updated_at: row.source_updated_at,
      ingested_at: row.ingested_at.toISO() ?? '',
    }
  }

  /**
   * Return the drug interaction text for a set of label ids.
   *
   * - Dedupes and caps the id list via parseCompareIds / MAX_COMPARE.
   * - One query: SELECT id, brand_name, generic_name, product_type,
   *   drug_interactions FROM drug_labels WHERE id IN (?).
   * - Re-orders the rows to match the requested id order so the caller's
   *   column positions are stable even if MySQL returns rows in a different
   *   order. Missing ids (non-existent in the table) are silently omitted.
   * - Returns [] for an empty or entirely-invalid id list.
   */
  async getInteractionsFor(ids: number[]): Promise<DrugInteractionEntry[]> {
    if (ids.length === 0) return []

    // Dedupe + cap (caller may already have done this, but be defensive).
    const safeIds = parseCompareIds(ids.join(',')).slice(0, MAX_COMPARE)
    if (safeIds.length === 0) return []

    const placeholders = safeIds.map(() => '?').join(', ')
    const sql = `
      SELECT id, brand_name, generic_name, product_type, drug_interactions
      FROM drug_labels
      WHERE id IN (${placeholders})
    `
    const rows = await db.rawQuery(sql, safeIds)
    const rawRows: Array<{
      id: number | string
      brand_name: string | null
      generic_name: string | null
      product_type: string | null
      drug_interactions: string | null
    }> = Array.isArray(rows[0]) ? rows[0] : []

    // Build a lookup by id so we can re-order to match the request order.
    const byId = new Map<number, DrugInteractionEntry>()
    for (const row of rawRows) {
      const entry: DrugInteractionEntry = {
        id: Number(row.id),
        brand_name: row.brand_name ?? null,
        generic_name: row.generic_name ?? null,
        product_type: row.product_type ?? null,
        drug_interactions: row.drug_interactions ?? null,
      }
      byId.set(entry.id, entry)
    }

    // Re-order: iterate safeIds, include only ids that exist in the table.
    const ordered: DrugInteractionEntry[] = []
    for (const id of safeIds) {
      const entry = byId.get(id)
      if (entry) ordered.push(entry)
    }
    return ordered
  }

  /**
   * Get current row count — what's searchable right now.
   */
  async rowCount(): Promise<number> {
    try {
      const result = await db.rawQuery('SELECT COUNT(*) AS cnt FROM drug_labels')
      const rows = result[0] as Array<{ cnt: number | string }>
      return Number(rows[0]?.cnt ?? 0)
    } catch {
      return 0
    }
  }

  /**
   * Dispatch the download phase (idempotent — deduped by deterministic jobId).
   * Auto-chains the ingest phase on completion. Returns "already running" if the
   * download job is active/waiting.
   */
  async triggerDownload() {
    return DownloadDrugDataJob.dispatch(true)
  }

  /**
   * Freshness check for the content-auto-update path: compare the live openFDA
   * manifest `export_date` against the last-ingested one (KV
   * `drugReference.lastUpdatedExportDate`). Reuses the job's single manifest
   * fetch (Maxim 4 — one openFDA call site) and the pure `isExportDateNewer`
   * compare (defensive about the unconfirmed date format; see its TODO).
   *
   * Returns `{ updateAvailable, latestExportDate, currentExportDate }`. Never
   * triggers a download itself — `attemptAutoUpdate` decides whether to, after
   * its own gating (only when installed, no active job).
   */
  async checkForUpdate(): Promise<{
    updateAvailable: boolean
    latestExportDate: string | null
    currentExportDate: string | null
  }> {
    const current = await KVStore.getValue('drugReference.lastUpdatedExportDate')
    const manifest = await DownloadDrugDataJob.fetchManifest()
    const latest = manifest.export_date ?? null
    return {
      updateAvailable: isExportDateNewer(latest ?? '', current),
      latestExportDate: latest,
      currentExportDate: current,
    }
  }

  /**
   * Freshness pass for the drug dataset, invoked from
   * `ContentAutoUpdateService.attemptDrugDataset()` inside the hourly content
   * loop — so the dataset refreshes alongside ZIMs and maps under the shared
   * `contentAutoUpdate.*` master switch and window, not on a rogue schedule.
   *
   * Gating (unchanged from the prior standalone job): only acts when the dataset
   * is installed, and never while a drug download or ingest is already in flight,
   * so it can't stack a refresh on a running install. A failed manifest fetch is
   * a transient miss (offline), reported rather than thrown.
   */
  async attemptAutoUpdate(): Promise<{
    started: boolean
    reason: string
    latestExportDate?: string | null
  }> {
    // Only act when the dataset is installed.
    const rowCount = await this.rowCount()
    if (rowCount === 0) {
      return { started: false, reason: 'not-installed' }
    }

    // Don't stack on top of an in-flight download/ingest.
    const [dlJob, ingJob] = await Promise.all([
      DownloadDrugDataJob.getJob(),
      IngestDrugDataJob.getJob(),
    ])
    const activeStates = ['active', 'waiting', 'delayed']
    const dlState = dlJob ? await dlJob.getState() : undefined
    const ingState = ingJob ? await ingJob.getState() : undefined
    if (
      (dlState && activeStates.includes(dlState)) ||
      (ingState && activeStates.includes(ingState))
    ) {
      return { started: false, reason: 'job-in-flight' }
    }

    let check: Awaited<ReturnType<DrugReferenceService['checkForUpdate']>>
    try {
      check = await this.checkForUpdate()
    } catch (err) {
      // Offline or manifest fetch failed — transient, retried next run.
      logger.warn(
        `[DrugReferenceService] Freshness check failed (will retry next run): ${
          err instanceof Error ? err.message : String(err)
        }`
      )
      return { started: false, reason: 'check-failed' }
    }

    if (!check.updateAvailable) {
      return {
        started: false,
        reason: `up-to-date (current=${check.currentExportDate ?? 'none'}, latest=${
          check.latestExportDate ?? 'unknown'
        })`,
        latestExportDate: check.latestExportDate,
      }
    }

    logger.info(
      `[DrugReferenceService] Newer export_date available ` +
        `(current=${check.currentExportDate ?? 'none'} → latest=${check.latestExportDate}); ` +
        'triggering re-download.'
    )
    const result = await this.triggerDownload()
    return {
      started: result.created,
      reason: result.created ? 'update-dispatched' : result.message,
      latestExportDate: check.latestExportDate,
    }
  }

  /**
   * Dispatch the ingest phase from the already-downloaded on-disk parts (the
   * manual "Ingest into search" path). Guards on the KV download-state marker so
   * it fails fast with a typed result when nothing has been downloaded, rather
   * than dispatching a job that would immediately fail in the worker.
   */
  async triggerIngestFromDisk() {
    const marker = parseDownloadState(await KVStore.getValue('drugReference.downloadState'))
    if (!marker) {
      return {
        job: undefined,
        created: false,
        message: 'Nothing downloaded — run Download FDA data first.',
        nothingDownloaded: true,
      }
    }
    const result = await IngestDrugDataJob.dispatch()
    return { ...result, nothingDownloaded: false }
  }

  /**
   * Force-clear a wedged ingest and restart it from the on-disk parts.
   *
   * A worker killed mid-ingest (e.g. during a `nomad upgrade`) leaves its job
   * 'active' holding a lock BullMQ won't reclaim until lockDuration elapses, so
   * the normal dispatch refuses to start a new ingest and the UI button stays
   * disabled ("Indexing…") with no way out. Obliterating the single-purpose
   * drug-ingest queue removes the stuck job (force = even active/locked); we then
   * re-dispatch from disk. The downloaded parts and the download-state marker are
   * left untouched, so this restarts ingest WITHOUT re-downloading.
   */
  async resetAndReingest() {
    const marker = parseDownloadState(await KVStore.getValue('drugReference.downloadState'))
    if (!marker) {
      return {
        job: undefined,
        created: false,
        message: 'Nothing downloaded — run Download FDA data first.',
        nothingDownloaded: true,
      }
    }

    const queue = QueueService.getInstance().getQueue(IngestDrugDataJob.queue)
    try {
      // force: true removes the active/locked stuck job too. Scoped to the
      // single-purpose ingest queue, so nothing else is affected.
      await queue.obliterate({ force: true })
      logger.info('[DrugReferenceService] drug-ingest queue obliterated for restart')
    } catch (err) {
      logger.warn(
        `[DrugReferenceService] ingest queue obliterate failed (continuing to dispatch): ${
          err instanceof Error ? err.message : String(err)
        }`
      )
    }

    const result = await IngestDrugDataJob.dispatch()
    return { ...result, nothingDownloaded: false }
  }

  /**
   * Write (or refresh) the `installed_resources` 'dataset' row that the tier-
   * status math and the curated-install filter read. Shared by the ingest job's
   * final pass, the ZimService tier-select path, and DrugInstallRowProvider's
   * boot backfill so all three write the same shape. Throws; callers log.
   */
  async recordInstalledRow(opts: {
    version: string
    collectionRef: string | null
    fileSizeBytes: number | null
  }): Promise<void> {
    const { default: InstalledResource } = await import('#models/installed_resource')
    const { DateTime } = await import('luxon')
    await InstalledResource.updateOrCreate(
      { resource_id: DRUG_DATASET_RESOURCE_ID, resource_type: 'dataset' },
      {
        version: opts.version,
        collection_ref: opts.collectionRef,
        url: 'https://api.fda.gov/download.json',
        // No single on-disk file — the parts are deleted after ingest; the
        // installed artifact is the DB table. Record the staging dir for
        // provenance; uninstall keys off resource_id, never this path.
        file_path: STORAGE_BASE,
        file_size_bytes: opts.fileSizeBytes,
        installed_at: DateTime.now(),
      }
    )
  }

  /** Whether the `installed_resources` 'dataset' row exists. */
  async hasInstalledRow(): Promise<boolean> {
    const { default: InstalledResource } = await import('#models/installed_resource')
    const row = await InstalledResource.query()
      .where('resource_type', 'dataset')
      .where('resource_id', DRUG_DATASET_RESOURCE_ID)
      .first()
    return row !== null
  }

  /**
   * Whether either drug queue holds an active/waiting/delayed job. Counts the
   * whole queue rather than the deterministic jobIds, since ingest continuations
   * run without one. Throws when Redis is unreachable.
   */
  async isJobInFlight(): Promise<boolean> {
    for (const queueName of [DownloadDrugDataJob.queue, IngestDrugDataJob.queue]) {
      const counts = await QueueService.getInstance()
        .getQueue(queueName)
        .getJobCounts('active', 'waiting', 'delayed')
      if ((counts.active ?? 0) + (counts.waiting ?? 0) + (counts.delayed ?? 0) > 0) return true
    }
    return false
  }

  /**
   * Uninstall the offline FDA drug dataset — the curated-tier "remove" path.
   *
   * Mirrors how ZimService.delete() reverses a ZIM install: stop anything that
   * could re-create the data, delete the on-disk artifacts, drop the data, and
   * remove the install-state row so the tier reads not-installed and the home
   * tiles auto-hide (the same cascade as a ZIM delete).
   *
   * Order matters:
   *   1. Obliterate BOTH drug queues (force = removes active/locked jobs too) so a
   *      running download/ingest can't write rows back in after we clear them.
   *      Scoped to the two single-purpose drug queues — nothing else is touched.
   *   2. Delete the on-disk parts dir (STORAGE_BASE is a FIXED constant, never a
   *      client value — no path-traversal surface). Usually empty after a full
   *      ingest; non-empty only when uninstalling a downloaded-not-yet-ingested
   *      state.
   *   3. TRUNCATE drug_labels (not DROP) — preserves the schema + FULLTEXT
   *      indexes so a later reinstall re-ingests without a migration.
   *   4. Clear the KV markers (download-state + last-updated export_date).
   *   5. Delete the `installed_resources` 'dataset' row.
   *
   * Every step is best-effort and logged: a partial failure still removes as much
   * as it can and reports what it did, rather than leaving a half-uninstalled
   * state with no signal.
   */
  async uninstall(): Promise<{
    success: boolean
    rowsDropped: number
    message: string
  }> {
    const rowsBefore = await this.rowCount()
    const errors: string[] = []

    // 1. Stop in-flight jobs on both drug queues (force removes locked/active).
    for (const queueName of [DownloadDrugDataJob.queue, IngestDrugDataJob.queue]) {
      try {
        await QueueService.getInstance().getQueue(queueName).obliterate({ force: true })
        logger.info(`[DrugReferenceService] obliterated ${queueName} for uninstall`)
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err)
        logger.warn(`[DrugReferenceService] obliterate ${queueName} failed: ${msg}`)
        errors.push(`queue ${queueName}: ${msg}`)
      }
    }

    // 2. Delete the on-disk parts directory. STORAGE_BASE is a fixed module const
    // (never a client filename), so this is not a path-traversal surface.
    try {
      await rm(STORAGE_BASE, { recursive: true, force: true })
      logger.info(`[DrugReferenceService] removed on-disk parts dir ${STORAGE_BASE}`)
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      logger.warn(`[DrugReferenceService] could not remove ${STORAGE_BASE}: ${msg}`)
      errors.push(`storage: ${msg}`)
    }

    // 3. Drop the searchable data. TRUNCATE keeps schema + the FULLTEXT indexes
    // so reinstall re-ingests cleanly with no migration.
    try {
      await db.rawQuery('TRUNCATE TABLE drug_labels')
      logger.info('[DrugReferenceService] truncated drug_labels')
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      logger.error(`[DrugReferenceService] TRUNCATE drug_labels failed: ${msg}`)
      errors.push(`truncate: ${msg}`)
    }

    // 4. Clear KV markers.
    try {
      await KVStore.clearValue('drugReference.downloadState')
      await KVStore.clearValue('drugReference.lastUpdatedExportDate')
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      logger.warn(`[DrugReferenceService] clearing KV markers failed: ${msg}`)
      errors.push(`kv: ${msg}`)
    }

    // 5. Remove the install-state row so the tier reads not-installed.
    try {
      const { default: InstalledResource } = await import('#models/installed_resource')
      await InstalledResource.query()
        .where('resource_type', 'dataset')
        .where('resource_id', DRUG_DATASET_RESOURCE_ID)
        .delete()
      logger.info('[DrugReferenceService] deleted installed_resources dataset row')
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      logger.warn(`[DrugReferenceService] deleting install row failed: ${msg}`)
      errors.push(`install-row: ${msg}`)
    }

    const rowsDropped = rowsBefore - (await this.rowCount())
    const success = errors.length === 0
    return {
      success,
      rowsDropped,
      message: success
        ? `Uninstalled FDA drug reference (${rowsDropped} labels removed).`
        : `Uninstall completed with ${errors.length} issue(s): ${errors.join('; ')}`,
    }
  }

  /**
   * Resolve the canonical deterministic job for a phase's queue, falling back to
   * the most-progressed auto-id continuation when the deterministic job is
   * absent or completed (passes > 0 use auto-generated ids). Each phase has its
   * own queue + jobId, so this is called once per queue with the matching ids.
   */
  private async resolvePhaseJob(
    queueName: string,
    deterministicJobId: string
  ): Promise<Job | undefined> {
    const queueService = QueueService.getInstance()
    const queue = queueService.getQueue(queueName)

    let job = await queue.getJob(deterministicJobId)
    if (!job || (await job.getState()) === 'completed') {
      const activeJobs = await queue.getJobs(['active', 'waiting', 'delayed'])
      const continuation = activeJobs
        .filter((j) => j.id !== deterministicJobId)
        .sort((a, b) => (b.data?.partIndex ?? 0) - (a.data?.partIndex ?? 0))[0]
      if (continuation) {
        job = continuation
      } else {
        // No live continuation. If the chain FAILED partway, surface the failed
        // job so the status reads 'failed' instead of falsely 'ready' with only
        // part 1's count. BUT removeOnFail keeps history: a STALE failure from a
        // prior run must not mask a newer successful one (seen live: a fixed
        // re-run completed, yet the panel stayed 'failed' on last night's
        // duplicate-key job). Compare finish times and only surface the failed
        // job when it is the most recent terminal outcome.
        const [failedJobs, completedJobs] = await Promise.all([
          queue.getJobs(['failed']),
          queue.getJobs(['completed']),
        ])
        const newestFailed = failedJobs.sort((a, b) => (b.finishedOn ?? 0) - (a.finishedOn ?? 0))[0]
        const newestCompletedFinish = completedJobs.reduce(
          (max, j) => Math.max(max, j.finishedOn ?? 0),
          0
        )
        if (newestFailed && (newestFailed.finishedOn ?? 0) > newestCompletedFinish) {
          job = newestFailed
        }
      }
    }
    return job
  }

  /** Map a BullMQ job state to the per-phase run state. */
  private phaseStateFor(state: string | undefined): DrugPhaseState {
    if (state === 'failed') return 'failed'
    if (state === 'completed') return 'completed'
    if (state === 'active' || state === 'waiting' || state === 'delayed') return 'running'
    return 'idle'
  }

  /**
   * Return the two-phase ingest status for the UI panel. Reads the download job
   * (drug-download queue) and the ingest job (drug-ingest queue) independently,
   * merges the KV download-state marker + last-updated marker + live row count,
   * and derives the top-level phase from the two sub-phases.
   */
  async getIngestStatus(): Promise<DrugIngestStatus> {
    const [downloadJob, ingestJob] = await Promise.all([
      this.resolvePhaseJob(DownloadDrugDataJob.queue, DownloadDrugDataJob.jobId),
      this.resolvePhaseJob(IngestDrugDataJob.queue, IngestDrugDataJob.jobId),
    ])

    const [lastUpdated, rawMarker, count] = await Promise.all([
      KVStore.getValue('drugReference.lastUpdatedExportDate'),
      KVStore.getValue('drugReference.downloadState'),
      this.rowCount(),
    ])
    const marker = parseDownloadState(rawMarker)

    // ── Download sub-status ─────────────────────────────────────────────────
    const dlState = downloadJob ? await downloadJob.getState() : undefined
    const dlData = downloadJob?.data ?? {}
    let downloadPhaseState = this.phaseStateFor(dlState)
    // A finished download job is pruned (removeOnComplete) but the marker proves
    // the parts are on disk — treat that as a completed download phase so the
    // manual "Ingest into search" button stays available.
    if (downloadPhaseState === 'idle' && marker) downloadPhaseState = 'completed'

    const download: DrugDownloadStatus = {
      state: downloadPhaseState,
      partsDone: downloadPhaseState === 'completed' ? (marker?.totalParts ?? dlData.totalParts ?? 0) : (dlData.partIndex ?? 0),
      totalParts: dlData.totalParts ?? marker?.totalParts ?? 0,
      bytesDownloaded: dlData.bytesDownloaded,
      currentPartName: dlData.currentPartName ?? null,
      failedReason:
        dlState === 'failed' ? summarizeJobError(downloadJob?.failedReason) : undefined,
    }

    // ── Ingest sub-status ───────────────────────────────────────────────────
    const ingState = ingestJob ? await ingestJob.getState() : undefined
    const ingData = ingestJob?.data ?? {}
    let ingestPhaseState = this.phaseStateFor(ingState)
    // A pruned-but-successful ingest leaves rows + the last-updated marker and
    // clears the download marker; reflect that as a completed ingest phase.
    if (ingestPhaseState === 'idle' && !marker && count > 0) ingestPhaseState = 'completed'

    // total_records 0 means "unknown" (e.g. a manifest rebuilt from an older
    // marker) — resolveExpectedTotal falls back to a parts estimate, then the
    // live row count, so the counter/%/ETA never silently vanish.
    const expectedTotal = resolveExpectedTotal(
      ingData.manifest?.total_records,
      ingData.totalParts,
      count
    )
    const jobRecords = ingData.recordsIngested ?? 0
    // While ingesting, the per-job recordsIngested lags across the per-part
    // continuation handoff (continuations run under auto jobIds). Drive the shown
    // count from max(jobRecords, live rowCount) so a first ingest tracks the table
    // filling 0 → ~259k, while a re-ingest into a populated table still rides the
    // per-job counter. Outside the running phase, trust the job's own total.
    // Always reconcile against the live row count (the per-job recordsIngested can
    // be a partial/stale total — a completed pass-0 job only counted part 1; a
    // failed continuation stops mid-run). WHILE RUNNING, additionally subtract the
    // run's start-row baseline so a re-ingest into a populated table shows THIS
    // run's progress (0 → ~259k) instead of reading ~100% from second zero.
    // Outside running, start=0 so 'ready'/'failed' reflect total searchable rows.
    const records =
      ingestPhaseState === 'running'
        ? resolveIngestRecordsShown(jobRecords, count, expectedTotal, ingData.startRowCount ?? 0)
        : resolveIngestRecordsShown(jobRecords, count, expectedTotal)

    const ingest: DrugIngestPhaseStatus = {
      state: ingestPhaseState,
      records,
      expectedTotal,
      partsDone: ingData.partIndex ?? 0,
      totalParts: ingData.totalParts ?? marker?.totalParts ?? 0,
      currentPartName: ingData.currentPartName ?? null,
      failedReason: ingState === 'failed' ? summarizeJobError(ingestJob?.failedReason) : undefined,
    }

    const phase = deriveIngestPhase(download, ingest, count)

    // The active phase drives elapsed/ETA: ingest start when ingesting, else the
    // download start.
    const startedAtMs =
      phase === 'ingesting'
        ? (ingData.startedAt ?? null)
        : phase === 'downloading'
          ? (dlData.startedAt ?? null)
          : null

    const error =
      phase === 'failed' ? (ingest.failedReason ?? download.failedReason) : undefined

    return {
      phase,
      download,
      ingest,
      startedAtMs,
      lastUpdated: lastUpdated ?? null,
      rowCount: count,
      error,
    }
  }
}

import { RagService } from '#services/rag_service'
import { inject } from '@adonisjs/core'
import logger from '@adonisjs/core/services/logger'
import { createHash } from 'node:crypto'
import { readdir, readFile } from 'node:fs/promises'
import { basename, join, resolve } from 'node:path'
import { KB_EVAL_COLLECTION } from '../../constants/kb_collections.js'
import { EMBEDDING_MODEL_NAME } from '../../constants/ollama.js'
import {
  assertGoldensMatchCorpus,
  computeCorpusFingerprint,
  parseGoldens,
  type Golden,
} from '../utils/eval/golden_set.js'
import { EVAL_CORPUS_DIR } from '../utils/eval/corpus_source.js'

/** Where the golden question set lives, relative to the app root. */
export const EVAL_GOLDENS_DIR = 'tests/eval/goldens'

/**
 * The suite that runs when none is named — i.e. `core.jsonl`. Every other
 * `.jsonl` in the goldens directory is opt-in via `--suite`, so adding one
 * cannot move the numbers an existing baseline was recorded against.
 */
export const DEFAULT_GOLDEN_SUITE = 'core'

// EVAL_CORPUS_DIR and docIdFromSource live in app/utils/eval/corpus_source.ts:
// they are pure path logic, and keeping them out of this service is what lets
// the leak guard be unit-tested without booting AdonisJS.
export { docIdFromSource, EVAL_CORPUS_DIR } from '../utils/eval/corpus_source.js'

export type CorpusDocument = {
  /** Filename without extension. This is the id goldens refer to. */
  docId: string
  /** Absolute path on disk; becomes the Qdrant `source` payload. */
  path: string
  text: string
}

export type IngestSummary = {
  fingerprint: string
  documents: number
  chunks: number
  removedBeforeIngest: number
  failures: Array<{ docId: string; reason: string }>
}

/**
 * Owns the frozen evaluation corpus: reading it off disk, fingerprinting it,
 * and pushing it through NOMAD's real ingest path into the reserved
 * `__nomad_eval__` collection tag.
 *
 * Ingesting through `RagService.embedAndStoreText` rather than writing vectors
 * directly is the whole point — chunk size, the token-estimate ratio, the
 * search_document prefix, and the embedding model are all in scope of the
 * measurement, so a change to any of them shows up as a retrieval score
 * movement instead of hiding.
 */
@inject()
export class EvalCorpusService {
  constructor(private ragService: RagService) {}

  private corpusPath(): string {
    return resolve(join(process.cwd(), EVAL_CORPUS_DIR))
  }

  /** Read every markdown document in the corpus, sorted for determinism. */
  async loadCorpus(): Promise<CorpusDocument[]> {
    const dir = this.corpusPath()
    const entries = (await readdir(dir)).filter((f) => f.endsWith('.md')).sort()
    if (entries.length === 0) {
      throw new Error(`No corpus documents found in ${dir}`)
    }
    return Promise.all(
      entries.map(async (file) => {
        const path = join(dir, file)
        return { docId: basename(file, '.md'), path, text: await readFile(path, 'utf8') }
      })
    )
  }

  /**
   * Load and validate golden files, cross-checked against the corpus.
   *
   * Each `.jsonl` in the goldens directory is a *suite*, named after the file.
   * Only `core` loads by default. That matters for comparability: aggregate
   * metrics are means over whatever ran, so silently adding goldens to the
   * default set would move recall@k and correctness for reasons unrelated to any
   * change under test, and quietly invalidate every committed baseline. Opting
   * in keeps a suite's numbers separate until someone asks for them.
   */
  async loadGoldens(suites: string[] = [DEFAULT_GOLDEN_SUITE]): Promise<Golden[]> {
    const dir = resolve(join(process.cwd(), EVAL_GOLDENS_DIR))
    const available = (await readdir(dir)).filter((f) => f.endsWith('.jsonl')).sort()
    if (available.length === 0) throw new Error(`No golden files found in ${dir}`)

    // '*' loads every suite. Used by `eval:corpus`, which validates the fixtures
    // rather than measuring anything — a malformed golden should fail validation
    // whether or not its suite is part of the default run.
    const wanted = new Set(suites)
    const files = wanted.has('*')
      ? available
      : available.filter((f) => wanted.has(basename(f, '.jsonl')))
    if (files.length === 0) {
      throw new Error(
        `No golden suites matched [${suites.join(', ')}]. Available: ` +
          available.map((f) => basename(f, '.jsonl')).join(', ')
      )
    }

    const goldens: Golden[] = []
    const seen = new Set<string>()
    for (const file of files) {
      const parsed = parseGoldens(await readFile(join(dir, file), 'utf8'), file)
      for (const g of parsed) {
        // parseGoldens dedupes within a file; this catches collisions across files.
        if (seen.has(g.id)) throw new Error(`Duplicate golden id "${g.id}" in ${file}`)
        seen.add(g.id)
        goldens.push(g)
      }
    }

    const corpus = await this.loadCorpus()
    assertGoldensMatchCorpus(
      goldens,
      corpus.map((d) => d.docId)
    )
    return goldens
  }

  /**
   * Hash the corpus together with the ingest parameters that shaped it.
   * Reports carry this; two reports with different fingerprints are not
   * comparable and `eval:compare` refuses to pretend otherwise.
   */
  async fingerprint(): Promise<string> {
    const corpus = await this.loadCorpus()
    return computeCorpusFingerprint(
      {
        documents: new Map(corpus.map((d) => [d.docId, d.text])),
        chunkTokens: RagService.TARGET_TOKENS_PER_CHUNK,
        chunkOverlapTokens: RagService.CHUNK_OVERLAP_TOKENS,
        charToTokenRatio: RagService.CHAR_TO_TOKEN_RATIO,
        embeddingModel: EMBEDDING_MODEL_NAME,
        embeddingDimension: RagService.EMBEDDING_DIMENSION,
      },
      (input) => createHash('sha256').update(input).digest('hex')
    )
  }

  /** Remove every eval point. Never touches user content. */
  async reset(): Promise<number> {
    const removed = await this.ragService.deleteCollectionPoints(KB_EVAL_COLLECTION)
    logger.info(`[Eval] Removed ${removed} eval corpus chunks`)
    return removed
  }

  /** How many eval chunks are currently in the vector store. */
  async count(): Promise<number> {
    return this.ragService.countChunksInCollection(KB_EVAL_COLLECTION)
  }

  /**
   * Wipe and rebuild the eval corpus.
   *
   * Always a full rebuild: a partial re-ingest would leave the vector store in
   * a state no fingerprint describes, and a fingerprint that does not describe
   * the store is worse than no fingerprint at all.
   */
  async ingest(onProgress?: (docId: string, index: number, total: number) => void): Promise<IngestSummary> {
    const corpus = await this.loadCorpus()
    const removedBeforeIngest = await this.reset()

    let chunks = 0
    const failures: IngestSummary['failures'] = []

    for (const [index, doc] of corpus.entries()) {
      onProgress?.(doc.docId, index + 1, corpus.length)
      try {
        const result = await this.ragService.embedAndStoreText(doc.text, {
          source: doc.path,
          collection: KB_EVAL_COLLECTION,
        })
        if (!result) {
          failures.push({ docId: doc.docId, reason: 'embedAndStoreText returned null' })
          continue
        }
        chunks += result.chunks
      } catch (error) {
        failures.push({ docId: doc.docId, reason: error instanceof Error ? error.message : String(error) })
      }
    }

    return {
      fingerprint: await this.fingerprint(),
      documents: corpus.length,
      chunks,
      removedBeforeIngest,
      failures,
    }
  }
}

import { EvalCorpusService } from '#services/eval_corpus_service'
import { OllamaService, type NomadChatUsage } from '#services/ollama_service'
import { RagPipelineService } from '#services/rag_pipeline_service'
import { inject } from '@adonisjs/core'
import logger from '@adonisjs/core/services/logger'
import { KB_EVAL_COLLECTION } from '../../constants/kb_collections.js'
import { RAG_MIN_FINAL_SCORE } from '../../constants/ollama.js'
import { resolveSamplerProfile } from '../utils/sampler.js'
import type { OllamaChatMessage, ResponseStyle, SamplerProfile } from '../../types/ollama.js'
import type { PipelineOptions, RetrievedChunk } from '../../types/rag.js'
import { docIdFromSource } from '../utils/eval/corpus_source.js'
import type { Golden } from '../utils/eval/golden_set.js'
import {
  scoreAnswer,
  summarizeNumeric,
  summarizeRepeats,
  type GenerationScores,
  type NumericSummary,
  type RepeatStats,
} from '../utils/eval/generation_metrics.js'

/**
 * The three ways to run a question, and what each one isolates.
 *
 * This is the part of the harness that answers "code bug or weak model?".
 * Running the same question all three ways turns one ambiguous score into a
 * decomposition:
 *
 * - `oracle` gives the model perfect context by construction. A low score here
 *   is the model (or the prompt) failing to use good context — retrieval is
 *   provably not at fault.
 * - `e2e` is the real product. `oracle - e2e` is the cost of imperfect retrieval.
 * - `noretrieval` is the model's parametric baseline. `e2e - noretrieval` is
 *   what RAG is actually buying, and on the fictional questions it should be
 *   nearly everything, since no model can know them.
 */
export type GenerationMode = 'oracle' | 'e2e' | 'noretrieval'

/**
 * Sentinel model name for the extractive reference run.
 *
 * `--model=mock` needs no Ollama at all: it answers by echoing whatever context
 * the pipeline injected, and refuses when nothing was injected. That makes it
 * two useful things at once — a way to exercise scoring and reporting with zero
 * models installed (so the harness itself is CI-testable), and a genuine
 * *ceiling* line: the best a perfectly extractive model could score given this
 * retrieval. A real model below the mock line is the bottleneck; a mock line
 * that is itself low means retrieval is.
 */
export const MOCK_MODEL = 'mock'

/**
 * Fixed sampling for eval runs. Never used by production chat.
 *
 * Temperature 0 is the default because a repeatable number is worth more than a
 * realistic one for most of what this harness gates. But greedy decoding makes
 * top_p, top_k and min_p inert — the highest-probability token wins whatever
 * they say — so a run left at 0 cannot see a Response Style change at all. That
 * is what `--style` is for: it sets `samplerStyle`, which replaces this
 * temperature with the style's and sends the real truncation settings, so the
 * chat path can actually be measured. The seed stays fixed either way, which
 * makes a sampled run approximately rather than exactly reproducible; `--repeats`
 * and the `unstable` counter are how that gets accounted for.
 */
export const EVAL_TEMPERATURE = 0
export const EVAL_SEED = 42

/**
 * What a run sends to the decoder: a fixed temperature, a sampler profile, or
 * neither. Exactly one of the three, which is why it is a shape rather than two
 * loose optional arguments threaded through runCase.
 */
type EvalSampling = { temperature?: number; sampler?: SamplerProfile }

function resolveEvalSampling(style: ResponseStyle | undefined): EvalSampling {
  if (!style) return { temperature: EVAL_TEMPERATURE }
  const sampler = resolveSamplerProfile(style)
  // `off` resolves to no profile, and sends no temperature either — that is the
  // pre-setting behaviour this harness needs to be able to reproduce.
  return sampler ? { sampler } : {}
}

export type GenerationRunOptions = {
  mode: GenerationMode
  model: string
  repeats?: number
  topK?: number
  scoreThreshold?: number
  /** Post-rerank relevance floor. Defaults to the constant, never to the setting. */
  minFinalScore?: number
  /** Skip the history-aware rewrite even on multi-turn goldens. */
  skipQueryRewrite?: boolean
  /**
   * Sample the way real chat does, under this Response Style, instead of at
   * temperature 0.
   *
   * Three states, not two. Unset is the deterministic default and the right
   * choice for anything being gated on. A style is the chat path as a user
   * experiences it. `off` sends no sampler settings *and* no temperature, which
   * is the pre-setting behaviour and therefore the honest control to compare a
   * style against: `--style=auto` against `--style=off` measures the change,
   * where `--style=auto` against a temperature-0 run measures the change plus
   * the difference between greedy and sampled decoding.
   *
   * Model-declared samplers are deliberately not merged in even under `auto`:
   * the harness scores a style, and a number that moved because one machine's
   * model shipped a different modelfile is not a number worth committing.
   */
  samplerStyle?: ResponseStyle
  onProgress?: (id: string, index: number, total: number) => void
}

export type GenerationCaseResult = {
  id: string
  tags: string[]
  expectRefusal: boolean
  /** One entry per repeat. */
  answers: string[]
  scores: GenerationScores[]
  correctness: RepeatStats
  refusalCorrectness: RepeatStats
  leakageFree: RepeatStats
  groundedness: NumericSummary | null
  retrievedDocIds: string[]
  injectedChunks: number
  /**
   * What the budget planner did with the window on this case.
   *
   * Without this a low score is ambiguous: it could mean the model answered
   * badly, or it could mean the model never saw the material because the
   * relevant turns were evicted. These fields tell the two apart.
   */
  budget?: {
    contextWindow: number
    estimatedPromptTokens: number
    promptBudget: number
    turnsDropped: number
    chunksDropped: number
    historyElided: boolean
    queryTruncated: boolean
  }
  /**
   * Estimated vs. the backend's real prompt token count. The estimator is the
   * foundation every budget decision rests on, so its error is worth gating on.
   */
  promptTokenError?: number
  /** Non-null only when something went wrong talking to the model. */
  error?: string
}

export type GenerationAggregate = {
  cases: number
  /** Cases whose pass/fail flipped across repeats; excluded from gating. */
  unstable: number
  errors: number
  correctness: number | null
  refusalCorrectness: number | null
  leakageRate: number | null
  thinkTagLeakRate: number | null
  markdownRate: number | null
  groundedness: NumericSummary | null
  meanAnswerLength: number | null
  /** Share of cases where history had to be trimmed to fit the window. */
  historyElidedRate: number | null
  /** Share of cases where a retrieved chunk didn't fit the context budget. */
  chunksDroppedRate: number | null
  /** Mean absolute error of the token estimator against real prompt counts. */
  promptTokenError: NumericSummary | null
  meanPromptTokens: number | null
}

export type GenerationRunResult = {
  params: {
    mode: GenerationMode
    model: string
    repeats: number
    /** Null when the run sent no temperature at all, under `--style=off`. */
    temperature: number | null
    seed: number
    /** The Response Style sampled under; null for the deterministic default. */
    samplerStyle: ResponseStyle | null
    topK?: number
    scoreThreshold?: number
    minFinalScore: number
  }
  overall: GenerationAggregate
  byTag: Record<string, GenerationAggregate>
  cases: GenerationCaseResult[]
  elapsedMs: number
}

@inject()
export class EvalGenerationService {
  constructor(
    private ollamaService: OllamaService,
    private pipeline: RagPipelineService,
    private corpusService: EvalCorpusService
  ) {}

  async run(goldens: Golden[], options: GenerationRunOptions): Promise<GenerationRunResult> {
    const repeats = Math.max(1, options.repeats ?? 3)
    const started = Date.now()
    const isMock = options.model === MOCK_MODEL
    const sampling = resolveEvalSampling(options.samplerStyle)

    // Oracle mode needs the corpus text on hand to synthesize perfect context.
    const corpusText = options.mode === 'oracle' ? await this.loadCorpusText() : null

    if (!isMock) await this.prepareModel(options.model)

    const cases: GenerationCaseResult[] = []
    for (const [index, golden] of goldens.entries()) {
      options.onProgress?.(golden.id, index + 1, goldens.length)
      cases.push(await this.runCase(golden, options, repeats, corpusText, isMock, sampling))
    }

    return {
      params: {
        mode: options.mode,
        model: options.model,
        repeats,
        temperature: sampling.sampler?.temperature ?? sampling.temperature ?? null,
        seed: EVAL_SEED,
        samplerStyle: options.samplerStyle ?? null,
        topK: options.topK,
        scoreThreshold: options.scoreThreshold,
        minFinalScore: options.minFinalScore ?? RAG_MIN_FINAL_SCORE,
      },
      overall: aggregateGeneration(cases),
      byTag: aggregateGenerationByTag(cases),
      cases,
      elapsedMs: Date.now() - started,
    }
  }

  /**
   * Evict other resident models and burn one throwaway generation.
   *
   * Both borrowed from BenchmarkService, and for the same reasons it added
   * them: a cold first run is dramatically slower and behaves differently, and
   * leftover models in VRAM change how the one under test is scheduled. Quality
   * runs are less timing-sensitive than throughput runs, but a first-token
   * timeout or an OOM-driven CPU fallback absolutely does change the answer.
   */
  private async prepareModel(model: string): Promise<void> {
    try {
      await this.ollamaService.unloadAllChatModelsExcept(model)
    } catch (error) {
      logger.warn(`[Eval] Could not evict resident models: ${errorText(error)}`)
    }
    try {
      await this.ollamaService.chat({
        model,
        messages: [{ role: 'user', content: 'Reply with the single word: ready' }],
        temperature: EVAL_TEMPERATURE,
        seed: EVAL_SEED,
      })
    } catch (error) {
      // Best-effort: if warm-up fails the scored runs will surface the real
      // problem with a better message than we could produce here.
      logger.warn(`[Eval] Warm-up generation failed: ${errorText(error)}`)
    }
  }

  private async loadCorpusText(): Promise<Map<string, { text: string; path: string }>> {
    const docs = await this.corpusService.loadCorpus()
    return new Map(docs.map((d) => [d.docId, { text: d.text, path: d.path }]))
  }

  private async runCase(
    golden: Golden,
    options: GenerationRunOptions,
    repeats: number,
    corpusText: Map<string, { text: string; path: string }> | null,
    isMock: boolean,
    sampling: EvalSampling
  ): Promise<GenerationCaseResult> {
    const messages: OllamaChatMessage[] = [
      ...golden.turns.map((t) => ({ role: t.role, content: t.content })),
      { role: 'user' as const, content: golden.query },
    ]

    const pipelineOptions: PipelineOptions = {
      collection: KB_EVAL_COLLECTION,
      topK: options.topK,
      scoreThreshold: options.scoreThreshold,
      // Pinned to the constant, not left to fall through to resolveMinFinalScore()
      // — otherwise a `rag.minRelevance` slider set on one developer's machine
      // would silently move every generation score. Same reasoning as the
      // retrieval tier; see EvalRetrievalService.run.
      minFinalScore: options.minFinalScore ?? RAG_MIN_FINAL_SCORE,
      // The mock run must not touch Ollama at all — that is what makes it
      // usable with no models installed. The rewrite is a chat-model call, so
      // it is always skipped there (it would 404 and silently fall back, which
      // works but quietly makes the "no model needed" claim untrue).
      skipQueryRewrite: options.skipQueryRewrite || isMock,
      // A developer's personal NOMAD.md would silently skew every score.
      skipNomadMd: true,
      // Pinned off rather than read from `rag.relevanceCheck`, for the same
      // reason as minFinalScore. eval:retrieval --judge-model measures it.
      relevanceCheckModel: null,
    }

    if (options.mode === 'oracle') {
      pipelineOptions.oracleContext = golden.relevantDocIds.map((docId) => {
        const doc = corpusText?.get(docId)
        return {
          text: doc?.text ?? '',
          score: 1,
          metadata: { source: doc?.path },
        } satisfies RetrievedChunk
      })
    } else if (options.mode === 'noretrieval') {
      // An empty oracle context short-circuits retrieval without injecting
      // anything — the model answers from parametric memory alone.
      pipelineOptions.oracleContext = []
    }

    const answers: string[] = []
    const scores: GenerationScores[] = []
    let retrievedDocIds: string[] = []
    let injectedChunks = 0
    let budget: GenerationCaseResult['budget']
    let promptTokenError: number | undefined
    let error: string | undefined

    for (let attempt = 0; attempt < repeats; attempt++) {
      try {
        const trace = await this.pipeline.buildPrompt(messages, options.model, pipelineOptions)
        retrievedDocIds = uniqueDocIds(trace.retrieved)
        injectedChunks = trace.injected.length
        const context = trace.injected.map((c) => c.text).join('\n\n')
        if (trace.budget) {
          budget = {
            contextWindow: trace.budget.contextWindow,
            estimatedPromptTokens: trace.budget.estimatedPromptTokens,
            promptBudget: trace.budget.promptBudget,
            turnsDropped: trace.budget.turnsDropped,
            chunksDropped: trace.budget.chunksDropped,
            historyElided: trace.budget.historyElided,
            queryTruncated: trace.budget.queryTruncated,
          }
        }

        const generated = isMock
          ? { answer: mockAnswer(context), usage: undefined }
          : await this.generate(options.model, trace.messages, trace.numCtx, trace.numPredict, sampling)
        const answer = generated.answer

        // The backend just reported the prompt's real token count. Comparing it
        // to the estimate is the only way to know whether the budget above was
        // built on a number worth trusting.
        if (generated.usage?.promptTokens && trace.uncalibratedPromptTokens) {
          promptTokenError =
            Math.abs(generated.usage.promptTokens - trace.uncalibratedPromptTokens) /
            generated.usage.promptTokens
        }

        answers.push(answer)
        scores.push(
          scoreAnswer({
            answer,
            context,
            mustInclude: golden.mustInclude,
            mustNotInclude: golden.mustNotInclude,
            expectRefusal: golden.expectRefusal,
          })
        )
      } catch (err) {
        error = errorText(err)
        break
      }
    }

    return {
      id: golden.id,
      tags: golden.tags,
      expectRefusal: golden.expectRefusal,
      answers,
      scores,
      correctness: summarizeRepeats(scores.map((s) => s.correct)),
      refusalCorrectness: summarizeRepeats(scores.map((s) => s.refusalCorrect)),
      leakageFree: summarizeRepeats(scores.map((s) => s.leakage.length === 0)),
      groundedness: summarizeNumeric(scores.map((s) => s.numericGroundedness)),
      retrievedDocIds,
      injectedChunks,
      budget,
      promptTokenError,
      error,
    }
  }

  private async generate(
    model: string,
    messages: OllamaChatMessage[],
    numCtx?: number,
    numPredict?: number,
    sampling: EvalSampling = { temperature: EVAL_TEMPERATURE }
  ): Promise<{ answer: string; usage?: NomadChatUsage }> {
    const response = await this.ollamaService.chat({
      model,
      messages,
      numCtx,
      numPredict,
      // Spread rather than passed as fields: an explicit temperature outranks a
      // profile's inside OllamaService, so under a style it has to be absent
      // entirely or the run would carry the style's truncation settings at
      // temperature 0 and measure a decoder nobody uses.
      ...sampling,
      seed: EVAL_SEED,
    })
    return { answer: response.message.content.trim(), usage: response.usage }
  }
}

/**
 * The extractive reference answer: echo the context, or decline when there is
 * none. Deterministic, model-free, and an honest ceiling for the current
 * retrieval.
 */
export function mockAnswer(context: string): string {
  if (!context.trim()) return "I don't have information about that."
  return context
}

function uniqueDocIds(chunks: RetrievedChunk[]): string[] {
  const ids: string[] = []
  const seen = new Set<string>()
  for (const chunk of chunks) {
    const docId = docIdFromSource(chunk.metadata?.source)
    if (docId && !seen.has(docId)) {
      seen.add(docId)
      ids.push(docId)
    }
  }
  return ids
}

function errorText(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

const rate = (values: boolean[]): number | null =>
  values.length === 0 ? null : values.filter(Boolean).length / values.length

export function aggregateGeneration(cases: GenerationCaseResult[]): GenerationAggregate {
  const scored = cases.filter((c) => c.scores.length > 0)
  const allScores = scored.flatMap((c) => c.scores)

  return {
    cases: cases.length,
    unstable: scored.filter((c) => c.correctness.unstable).length,
    errors: cases.filter((c) => c.error).length,
    // Mean pass-rate rather than all-or-nothing, so a case that passes 2 of 3
    // is reported as 0.67 instead of being silently rounded either way.
    correctness: scored.length === 0 ? null : mean(scored.map((c) => c.correctness.passRate)),
    refusalCorrectness:
      scored.length === 0 ? null : mean(scored.map((c) => c.refusalCorrectness.passRate)),
    leakageRate: rate(allScores.map((s) => s.leakage.length > 0)),
    thinkTagLeakRate: rate(allScores.map((s) => s.thinkTagLeak)),
    markdownRate: rate(allScores.map((s) => s.markdownFormatted)),
    groundedness: summarizeNumeric(allScores.map((s) => s.numericGroundedness)),
    meanAnswerLength: allScores.length === 0 ? null : mean(allScores.map((s) => s.length)),
    historyElidedRate: rate(cases.filter((c) => c.budget).map((c) => c.budget!.historyElided)),
    chunksDroppedRate: rate(cases.filter((c) => c.budget).map((c) => c.budget!.chunksDropped > 0)),
    promptTokenError: summarizeNumeric(
      cases.map((c) => c.promptTokenError).filter((e): e is number => e !== undefined)
    ),
    meanPromptTokens: (() => {
      const values = cases
        .map((c) => c.budget?.estimatedPromptTokens)
        .filter((v): v is number => v !== undefined)
      return values.length === 0 ? null : mean(values)
    })(),
  }
}

export function aggregateGenerationByTag(
  cases: GenerationCaseResult[]
): Record<string, GenerationAggregate> {
  const tags = new Set(cases.flatMap((c) => c.tags))
  const out: Record<string, GenerationAggregate> = {}
  for (const tag of [...tags].sort()) {
    out[tag] = aggregateGeneration(cases.filter((c) => c.tags.includes(tag)))
  }
  return out
}

const mean = (values: number[]) => values.reduce((a, b) => a + b, 0) / values.length

import { inject } from '@adonisjs/core'
import { execFile } from 'node:child_process'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'
import { promisify } from 'node:util'
import type { GenerationRunResult } from './eval_generation_service.js'
import type { RetrievalRunResult } from './eval_retrieval_service.js'
import { flattenByK, type EvalReport, type ReportMeta } from '../utils/eval/report.js'

const run = promisify(execFile)

export const EVAL_REPORTS_DIR = 'tests/eval/reports'
export const EVAL_BASELINES_DIR = 'tests/eval/baselines'

/**
 * Turns run results into durable, comparable report files.
 *
 * Two formats, on purpose: JSON is what `eval:compare` diffs, and Markdown is
 * what a human actually reads when a number moved and they need to know which
 * question broke and what the model said.
 */
@inject()
export class EvalReportService {
  async buildMeta(
    kind: 'retrieval' | 'generation',
    corpusFingerprint: string,
    params: Record<string, unknown>
  ): Promise<ReportMeta> {
    const [git, nomadVersion, platform] = await Promise.all([
      readGitState(),
      readNomadVersion(),
      readPlatform(),
    ])
    return {
      kind,
      createdAt: new Date().toISOString(),
      corpusFingerprint,
      gitSha: git.sha,
      gitBranch: git.branch,
      gitDirty: git.dirty,
      nomadVersion,
      platform,
      params,
    }
  }

  fromRetrieval(meta: ReportMeta, result: RetrievalRunResult): EvalReport {
    const flatten = (agg: RetrievalRunResult['overall']) => ({
      ...flattenByK('recall', agg.recall),
      ...flattenByK('hitRate', agg.hitRate),
      ...flattenByK('precision', agg.precision),
      ...flattenByK('ndcg', agg.ndcg),
      mrr: agg.mrr,
      emptyRateOnAnswerable: agg.emptyRateOnAnswerable,
      nonEmptyRateOnRefusal: agg.nonEmptyRateOnRefusal,
    })
    return {
      meta,
      metrics: flatten(result.overall),
      byTag: Object.fromEntries(Object.entries(result.byTag).map(([tag, agg]) => [tag, flatten(agg)])),
      cases: result.cases,
    }
  }

  fromGeneration(meta: ReportMeta, result: GenerationRunResult): EvalReport {
    const flatten = (agg: GenerationRunResult['overall']) => ({
      correctness: agg.correctness,
      refusalCorrectness: agg.refusalCorrectness,
      leakageRate: agg.leakageRate,
      thinkTagLeakRate: agg.thinkTagLeakRate,
      markdownRate: agg.markdownRate,
      groundedness: agg.groundedness?.mean ?? null,
      historyElidedRate: agg.historyElidedRate,
      chunksDroppedRate: agg.chunksDroppedRate,
      promptTokenError: agg.promptTokenError?.mean ?? null,
      meanPromptTokens: agg.meanPromptTokens,
    })
    return {
      meta,
      metrics: flatten(result.overall),
      byTag: Object.fromEntries(Object.entries(result.byTag).map(([tag, agg]) => [tag, flatten(agg)])),
      // Answers are kept in full. When a score moves, the only question anyone
      // actually asks is "what did it say?", and a truncated answer cannot
      // answer it.
      cases: result.cases,
    }
  }

  /** Write `<slug>.json` and `<slug>.md`; returns the JSON path. */
  async write(report: EvalReport, slug: string, markdown: string): Promise<string> {
    const dir = resolve(join(process.cwd(), EVAL_REPORTS_DIR))
    await mkdir(dir, { recursive: true })
    const jsonPath = join(dir, `${slug}.json`)
    await writeFile(jsonPath, JSON.stringify(report, null, 2))
    await writeFile(join(dir, `${slug}.md`), markdown)
    return jsonPath
  }

  async read(path: string): Promise<EvalReport> {
    const parsed = JSON.parse(await readFile(resolve(path), 'utf8'))
    if (!parsed?.meta?.kind || !parsed?.metrics) {
      throw new Error(`${path} is not an eval report`)
    }
    return parsed as EvalReport
  }

  /**
   * Baselines are filed under their corpus fingerprint. That is not cosmetic:
   * it makes it structurally impossible to overwrite the baseline for one
   * corpus with a run against another.
   */
  baselinePath(report: EvalReport, name: string): string {
    return resolve(
      join(process.cwd(), EVAL_BASELINES_DIR, report.meta.corpusFingerprint, `${name}.json`)
    )
  }

  async promoteToBaseline(report: EvalReport, name: string): Promise<string> {
    const path = this.baselinePath(report, name)
    await mkdir(dirname(path), { recursive: true })
    await writeFile(path, JSON.stringify(report, null, 2))
    return path
  }
}

async function readGitState() {
  const git = async (args: string[]) => (await run('git', args)).stdout.trim()
  try {
    const [sha, branch, status] = await Promise.all([
      git(['rev-parse', 'HEAD']),
      git(['rev-parse', '--abbrev-ref', 'HEAD']),
      git(['status', '--porcelain']),
    ])
    // A dirty tree matters: it means the report does not correspond to any
    // commit, so a later "this regressed at sha X" claim would be unfounded.
    return { sha, branch, dirty: status.length > 0 }
  } catch {
    return { sha: null, branch: null, dirty: false }
  }
}

async function readNomadVersion(): Promise<string | null> {
  try {
    const pkg = JSON.parse(await readFile(resolve(join(process.cwd(), '..', 'package.json')), 'utf8'))
    return pkg.version ?? null
  } catch {
    return null
  }
}

async function readPlatform() {
  const os = await import('node:os')
  return {
    cpuArchitecture: os.arch(),
    osName: `${os.type()} ${os.release()}`,
    nodeVersion: process.version,
  }
}

import { EvalCorpusService } from '#services/eval_corpus_service'
import { RagService } from '#services/rag_service'
import { RelevanceJudgeService } from '#services/relevance_judge_service'
import { inject } from '@adonisjs/core'
import { KB_EVAL_COLLECTION } from '../../constants/kb_collections.js'
import {
  RAG_DEFAULT_SCORE_THRESHOLD,
  RAG_DEFAULT_TOP_K,
  RAG_MIN_FINAL_SCORE,
} from '../../constants/ollama.js'
import type { RetrievalStages } from '../../types/rag.js'
import { docIdFromSource } from '../utils/eval/corpus_source.js'
import type { Golden } from '../utils/eval/golden_set.js'
import {
  aggregate,
  aggregateByTag,
  DEFAULT_K_VALUES,
  scoreCase,
  type RetrievalAggregate,
  type RetrievalCase,
  type RetrievalCaseResult,
  type ScoredChunk,
} from '../utils/eval/retrieval_metrics.js'

export type RetrievalRunOptions = {
  topK?: number
  scoreThreshold?: number
  /** Post-rerank relevance floor. Defaults to the constant, never to the setting. */
  minFinalScore?: number
  kValues?: number[]
  /** Score the raw dense / reranked / diversified orderings separately. */
  ablate?: boolean
  /** Also return every golden's full pre-floor candidate pool (see RetrievalStages.candidates). */
  dump?: boolean
  /**
   * Run the relevance check on this model after the floor, as chat does when it
   * is enabled. Unset keeps this tier model-free and deterministic.
   */
  judgeModel?: string
}

/** What the relevance check cost and did, when `judgeModel` was set. */
export type JudgeStats = {
  model: string
  calls: number
  /** Calls that failed open (timeout, error, unusable verdict). */
  failures: number
  rejected: number
  meanMs: number
  maxMs: number
}

/** One golden's full candidate pool, for simulating a relevance gate offline. */
export type CandidatePool = {
  id: string
  tags: string[]
  expectRefusal: boolean
  relevantDocIds: string[]
  candidates: Array<{ docId: string | null; score: number; semanticScore: number | null }>
}

export type StageAblation = {
  dense: RetrievalAggregate
  reranked: RetrievalAggregate
  diversified: RetrievalAggregate
}

export type RetrievalRunResult = {
  params: { topK: number; scoreThreshold: number; minFinalScore: number; kValues: number[] }
  overall: RetrievalAggregate
  byTag: Record<string, RetrievalAggregate>
  cases: RetrievalCaseResult[]
  ablation: StageAblation | null
  /**
   * Chunks that came back without a resolvable eval doc id. Non-zero means the
   * collection filter leaked and the run is measuring the wrong corpus.
   */
  unresolvedChunks: number
  /** Every golden's candidate pool, when `dump` was requested. */
  pools: CandidatePool[] | null
  judge: JudgeStats | null
}

/**
 * Runs the golden question set through NOMAD's real retrieval path and scores
 * the result.
 *
 * Deliberately does not touch the chat model. The only model call is the
 * embedding of each query, whose output is stable, so two runs over the same
 * corpus produce identical numbers on any hardware. That is what makes this the
 * fast inner loop and the only tier worth gating CI on: a movement here is a
 * code change, full stop.
 *
 * Multi-turn goldens are scored on their raw final message. Resolving the
 * coreference would need the chat model, which would make this tier
 * non-deterministic — so the multi-turn bucket here reports the honest floor,
 * and the rewrite's contribution is measured in the generation tier instead.
 */
@inject()
export class EvalRetrievalService {
  constructor(
    private ragService: RagService,
    private corpusService: EvalCorpusService,
    private judgeService: RelevanceJudgeService
  ) {}

  async run(goldens: Golden[], options: RetrievalRunOptions = {}): Promise<RetrievalRunResult> {
    const topK = options.topK ?? RAG_DEFAULT_TOP_K
    const scoreThreshold = options.scoreThreshold ?? RAG_DEFAULT_SCORE_THRESHOLD
    // RAG_MIN_FINAL_SCORE, deliberately — NOT resolveMinFinalScore(). The chat
    // path reads the user's `rag.minRelevance` setting; this tier must not, or a
    // slider position on one developer's machine would silently move the numbers
    // and the committed baseline would stop being reproducible anywhere else.
    // Same reasoning as the harness omitting `skipRetrieval`.
    const minFinalScore = options.minFinalScore ?? RAG_MIN_FINAL_SCORE
    const kValues = options.kValues ?? DEFAULT_K_VALUES

    const cases: RetrievalCase[] = []
    const denseCases: RetrievalCase[] = []
    const rerankedCases: RetrievalCase[] = []
    const diversifiedCases: RetrievalCase[] = []
    const pools: CandidatePool[] = []
    const recordStages = options.ablate || options.dump
    const judgeMs: number[] = []
    let judgeFailures = 0
    let judgeRejected = 0
    let unresolvedChunks = 0

    for (const golden of goldens) {
      const stages: RetrievalStages = {}
      let docs = await this.ragService.searchSimilarDocuments(
        golden.query,
        topK,
        scoreThreshold,
        KB_EVAL_COLLECTION,
        recordStages ? stages : undefined,
        minFinalScore
      )

      if (options.judgeModel && docs.length > 0) {
        const verdict = await this.judgeService.judge(golden.query, docs, options.judgeModel)
        judgeMs.push(verdict.ms)
        if (!verdict.judged) judgeFailures++
        judgeRejected += verdict.rejected
        docs = verdict.kept
      }

      const retrieved: ScoredChunk[] = docs.map((d) => {
        const docId = docIdFromSource(d.metadata?.source)
        if (!docId) unresolvedChunks++
        return { docId, score: d.score, semanticScore: d.metadata?.semantic_score }
      })

      cases.push(toCase(golden, retrieved))

      if (options.dump) {
        pools.push({
          id: golden.id,
          tags: golden.tags,
          expectRefusal: golden.expectRefusal,
          relevantDocIds: golden.relevantDocIds,
          candidates: (stages.candidates ?? []).map((c) => ({
            docId: docIdFromSource(c.source),
            score: c.score,
            semanticScore: c.semanticScore ?? null,
          })),
        })
      }

      if (options.ablate) {
        denseCases.push(toCase(golden, stageToChunks(stages.dense)))
        rerankedCases.push(toCase(golden, stageToChunks(stages.reranked)))
        diversifiedCases.push(toCase(golden, stageToChunks(stages.diversified)))
      }
    }

    const results = cases.map((c) => scoreCase(c, kValues))

    const aggregateStage = (stageCases: RetrievalCase[]) =>
      aggregate(stageCases, stageCases.map((c) => scoreCase(c, kValues)), kValues)

    return {
      params: { topK, scoreThreshold, minFinalScore, kValues },
      overall: aggregate(cases, results, kValues),
      byTag: aggregateByTag(cases, results, kValues),
      cases: results,
      ablation: options.ablate
        ? {
            dense: aggregateStage(denseCases),
            reranked: aggregateStage(rerankedCases),
            diversified: aggregateStage(diversifiedCases),
          }
        : null,
      unresolvedChunks,
      pools: options.dump ? pools : null,
      judge: options.judgeModel
        ? {
            model: options.judgeModel,
            calls: judgeMs.length,
            failures: judgeFailures,
            rejected: judgeRejected,
            meanMs: judgeMs.length ? judgeMs.reduce((a, b) => a + b, 0) / judgeMs.length : 0,
            maxMs: judgeMs.length ? Math.max(...judgeMs) : 0,
          }
        : null,
    }
  }

  /** Confirm the corpus is actually ingested before reporting a score of zero. */
  async assertCorpusReady(): Promise<number> {
    const chunks = await this.corpusService.count()
    if (chunks === 0) {
      throw new Error(
        'The eval corpus is not ingested — every score would be zero. Run: node ace eval:corpus --ingest'
      )
    }
    return chunks
  }
}

function toCase(golden: Golden, retrieved: ScoredChunk[]): RetrievalCase {
  return {
    id: golden.id,
    tags: golden.tags,
    retrieved,
    relevantDocIds: golden.relevantDocIds,
    expectRefusal: golden.expectRefusal,
  }
}

function stageToChunks(stage: Array<{ source?: string; score: number }> | undefined): ScoredChunk[] {
  return (stage ?? []).map((entry) => ({
    docId: docIdFromSource(entry.source),
    score: entry.score,
  }))
}

import axios from 'axios'
import { XMLParser } from 'fast-xml-parser'
import { DateTime } from 'luxon'
import logger from '@adonisjs/core/services/logger'
import InstalledResource from '#models/installed_resource'
import { isRawListRemoteZimFilesResponse } from '../../util/zim.js'
import { KIWIX_CATALOG_BASE_URL } from '../../constants/kiwix.js'

/**
 * Local, in-process freshness check for installed content (Kiwix ZIM files +
 * PMTiles maps). This replaces the former dependency on the external
 * project-nomad-api `/api/v1/resources/check-updates` endpoint — every NOMAD
 * instance now queries the upstream catalogs directly.
 *
 * Downloads have always gone straight to the Kiwix/GitHub mirrors regardless of
 * who performed the check, so moving the check in-process only shifts the
 * lightweight *catalog* lookup. To stay mirror-respectful the auto-updater gates
 * these calls behind the update window and bounds their concurrency; sizes come
 * from the catalog metadata so we avoid per-file HEAD requests.
 *
 * Robustness over the old API: ZIM lookups use the OPDS exact `name=` filter
 * (no lossy keyword stripping) and every returned link is still validated
 * against the authoritative `^<id>_YYYY-MM\.zim$` filename regex, so a substring
 * match in the catalog can never resolve to the wrong book. Parsing is fully
 * defensive — a malformed entry is skipped, never thrown.
 */

const GITHUB_PMTILES_URL =
  'https://api.github.com/repos/Crosstalk-Solutions/project-nomad-maps/contents/pmtiles'

const CATALOG_TIMEOUT_MS = 15000
/** Concurrent ZIM catalog lookups — keep small to avoid hammering the mirror. */
const ZIM_CHECK_CONCURRENCY = 4

/** The newest available version of a single resource (a YYYY-MM date stamp). */
export interface CatalogResult {
  version: string
  download_url: string
  size_bytes: number
}

interface CatalogZimEntry {
  name: string | null
  download_url: string
  file_name: string
  size_bytes: number
}

interface GithubContentEntry {
  name: string
  download_url: string | null
  size: number
}

function escapeRegex(input: string): string {
  return input.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

export class KiwixCatalogService {
  private parser = new XMLParser({
    ignoreAttributes: false,
    attributeNamePrefix: '',
    textNodeName: '#text',
  })

  /**
   * Resolve the newest available version for a batch of installed resources.
   * Returns a map keyed by `"<resource_type>:<resource_id>"`; resources with no
   * available newer version (or a failed lookup) are simply absent.
   *
   * ZIMs are checked one OPDS request each (bounded concurrency). All maps are
   * resolved from a single GitHub directory listing.
   */
  async getLatestForResources(
    resources: Array<{ resource_id: string; resource_type: 'zim' | 'map' }>
  ): Promise<Map<string, CatalogResult>> {
    const result = new Map<string, CatalogResult>()
    const zims = resources.filter((r) => r.resource_type === 'zim')
    const maps = resources.filter((r) => r.resource_type === 'map')

    await this.forEachWithConcurrency(zims, ZIM_CHECK_CONCURRENCY, async (r) => {
      try {
        const latest = await this.getLatestZim(r.resource_id)
        if (latest) result.set(`zim:${r.resource_id}`, latest)
      } catch (error) {
        logger.warn(
          `[KiwixCatalogService] ZIM check failed for ${r.resource_id}: ${error instanceof Error ? error.message : error}`
        )
      }
    })

    if (maps.length > 0) {
      try {
        const listing = await this.fetchMapListing()
        for (const r of maps) {
          const latest = this.pickNewestMap(listing, r.resource_id)
          if (latest) result.set(`map:${r.resource_id}`, latest)
        }
      } catch (error) {
        logger.warn(
          `[KiwixCatalogService] Map listing fetch failed: ${error instanceof Error ? error.message : error}`
        )
      }
    }

    return result
  }

  /** Newest catalog version of a single ZIM book, or null if none/older. */
  async getLatestZim(resourceId: string): Promise<CatalogResult | null> {
    const pattern = new RegExp(`^${escapeRegex(resourceId)}_(\\d{4}-\\d{2})\\.zim$`)

    // 1. Exact-name lookup (the robust path). Resolves most books, whose OPDS `<name>`
    //    is the full filename base: devdocs_en_python, zimgit-water_en,
    //    freecodecamp_en_all, nhs.uk_en_medicines ...
    const named = await this.fetchZimEntries({ name: resourceId, count: 50, start: 0 })
    const exact = this.pickNewestZim(named, pattern)
    if (exact) return exact

    // 2. Flavoured books index under the base WITHOUT the flavour, which the catalog
    //    carries in a separate `<flavour>` element: `wikibooks_en_all_nopic_2026-04.zim`
    //    is `<name>wikibooks_en_all</name><flavour>nopic</flavour>`. Our resource ids are
    //    filename bases, so `name=wikibooks_en_all_nopic` matched nothing and every
    //    maxi/mini/nopic book -- including every Wikipedia -- was unresolvable.
    //    Retry against the base; `pattern` still decides, so a broader query is safe.
    const base = this.stripFlavourSuffix(resourceId)
    if (base) {
      const byBase = await this.fetchZimEntries({ name: base, count: 50, start: 0 })
      const flavoured = this.pickNewestZim(byBase, pattern)
      if (flavoured) return flavoured
    }

    // Nothing in the catalog matches this id. There used to be a third step here: a
    // bounded `q=` keyword scan, up to 5 paged requests per unresolved book on every
    // check. It was removed because `q=` searches an entry's title and summary, never
    // its filename, so it cannot match a resource id -- across every id tested it
    // resolved nothing while the two `name=` lookups above resolved everything that
    // was resolvable. It was pure repeat traffic aimed at a mirror that has just had
    // to deploy anti-crawler measures.
    return null
  }

  /**
   * Drop the trailing `_<flavour>` segment from a resource id, or null when there is
   * nothing to drop. Deliberately not matched against a flavour allowlist: openZIM adds
   * flavours over time, and a wrong guess costs one extra catalog request because the
   * authoritative filename check still gates every result.
   */
  private stripFlavourSuffix(resourceId: string): string | null {
    const cut = resourceId.lastIndexOf('_')
    if (cut <= 0) return null
    return resourceId.slice(0, cut)
  }

  /** Newest catalog version of a single PMTiles map, or null if none/older. */
  async getLatestMap(resourceId: string): Promise<CatalogResult | null> {
    const listing = await this.fetchMapListing()
    return this.pickNewestMap(listing, resourceId)
  }

  // ── ZIM internals ───────────────────────────────────────────────────────────

  private pickNewestZim(entries: CatalogZimEntry[], pattern: RegExp): CatalogResult | null {
    let latest: CatalogResult | null = null
    for (const entry of entries) {
      const match = entry.file_name.match(pattern)
      if (!match) continue
      const version = match[1]
      if (!latest || version > latest.version) {
        latest = { version, download_url: entry.download_url, size_bytes: entry.size_bytes }
      }
    }
    return latest
  }

  private async fetchZimEntries(params: {
    name?: string
    count: number
    start: number
  }): Promise<CatalogZimEntry[]> {
    const { entries } = await this.fetchZimEntriesPage(params)
    return entries
  }

  private async fetchZimEntriesPage(params: {
    name?: string
    count: number
    start: number
  }): Promise<{ entries: CatalogZimEntry[]; totalResults: number }> {
    const res = await axios.get(KIWIX_CATALOG_BASE_URL, {
      params: {
        start: params.start,
        count: params.count,
        // No `lang` filter. This is a freshness check for an ALREADY-INSTALLED book, so
        // the language is whatever the user installed; `lang: 'eng'` made every
        // non-English ZIM permanently unresolvable here. The authoritative
        // `^<id>_YYYY-MM.zim$` filename check is what resolves the right book.
        ...(params.name ? { name: params.name } : {}),
      },
      responseType: 'text',
      timeout: CATALOG_TIMEOUT_MS,
    })
    return this.parseZimEntries(res.data)
  }

  private parseZimEntries(xml: string): { entries: CatalogZimEntry[]; totalResults: number } {
    let parsed: any
    try {
      parsed = this.parser.parse(xml)
    } catch {
      return { entries: [], totalResults: 0 }
    }
    if (!isRawListRemoteZimFilesResponse(parsed)) {
      return { entries: [], totalResults: 0 }
    }

    const feed = parsed.feed
    const totalResults = Number(feed?.totalResults)
    const rawEntries = feed?.entry
      ? Array.isArray(feed.entry)
        ? feed.entry
        : [feed.entry]
      : []

    const entries: CatalogZimEntry[] = []
    for (const raw of rawEntries) {
      if (!raw || typeof raw !== 'object') continue
      const links = Array.isArray(raw.link) ? raw.link : raw.link ? [raw.link] : []
      const downloadLink = links.find(
        (link: any) =>
          link &&
          typeof link === 'object' &&
          link.type === 'application/x-zim' &&
          typeof link.href === 'string'
      )
      if (!downloadLink) continue

      // The OPDS href ends with `.meta4`; strip it to get the real .zim URL.
      const href: string = downloadLink.href
      const download_url = href.endsWith('.meta4') ? href.slice(0, -'.meta4'.length) : href
      const file_name = download_url.split('/').pop() || ''
      if (!file_name) continue

      const size_bytes = Number.parseInt(downloadLink.length, 10) || 0
      entries.push({
        name: typeof raw.name === 'string' ? raw.name : null,
        download_url,
        file_name,
        size_bytes,
      })
    }

    return { entries, totalResults: Number.isFinite(totalResults) ? totalResults : 0 }
  }

  // ── Map internals ────────────────────────────────────────────────────────────

  private async fetchMapListing(): Promise<GithubContentEntry[]> {
    const res = await axios.get(GITHUB_PMTILES_URL, {
      headers: { Accept: 'application/vnd.github+json' },
      timeout: CATALOG_TIMEOUT_MS,
    })
    return Array.isArray(res.data) ? res.data : []
  }

  private pickNewestMap(listing: GithubContentEntry[], resourceId: string): CatalogResult | null {
    const pattern = new RegExp(`^${escapeRegex(resourceId)}_(\\d{4}-\\d{2})\\.pmtiles$`)
    let latest: CatalogResult | null = null
    for (const file of listing) {
      if (!file || typeof file.name !== 'string' || !file.download_url) continue
      const match = file.name.match(pattern)
      if (!match) continue
      const version = match[1]
      if (!latest || version > latest.version) {
        latest = {
          version,
          download_url: file.download_url,
          size_bytes: typeof file.size === 'number' ? file.size : 0,
        }
      }
    }
    return latest
  }

  // ── Shared ───────────────────────────────────────────────────────────────────

  private async forEachWithConcurrency<T>(
    items: T[],
    concurrency: number,
    worker: (item: T) => Promise<void>
  ): Promise<void> {
    let cursor = 0
    const runners = Array.from({ length: Math.min(concurrency, items.length) }, async () => {
      while (cursor < items.length) {
        const index = cursor++
        await worker(items[index])
      }
    })
    await Promise.all(runners)
  }
}

/**
 * Persist the latest-known available-update state onto an installed resource.
 * Shared by the manual check and the auto-updater so both keep the cool-off
 * anchor consistent.
 *
 * The first-seen anchor is reset **only** when the available version string
 * actually changes, so a manual "Check for updates" never resets the auto
 * cool-off clock. State is cleared entirely once the resource is current (the
 * update got installed, or the upstream release was withdrawn).
 */
export async function reconcileResourceUpdateState(
  resource: InstalledResource,
  latest: CatalogResult | null,
  now: DateTime
): Promise<void> {
  const hasUpdate = latest !== null && latest.version > resource.version

  if (hasUpdate) {
    if (resource.available_update_version !== latest!.version) {
      resource.available_update_version = latest!.version
      resource.available_update_first_seen_at = now
    }
    // Keep the cached size fresh even when the version is unchanged (the catalog
    // may report a size it lacked on a previous check).
    const size = latest!.size_bytes || null
    if (resource.available_update_size_bytes !== size) {
      resource.available_update_size_bytes = size
    }
  } else if (resource.available_update_version !== null) {
    resource.available_update_version = null
    resource.available_update_size_bytes = null
    resource.available_update_first_seen_at = null
  }

  if (resource.$isDirty) {
    await resource.save()
  }
}

import { XMLBuilder, XMLParser } from 'fast-xml-parser'
import { readFile, writeFile, rename, readdir } from 'fs/promises'
import { join } from 'path'
import { Archive } from '@openzim/libzim'
import { KIWIX_LIBRARY_XML_PATH, ZIM_STORAGE_PATH, ensureDirectoryExists, isValidZimFile } from '../utils/fs.js'
import logger from '@adonisjs/core/services/logger'
import { randomUUID } from 'node:crypto'

const CONTAINER_DATA_PATH = '/data'
const XML_DECLARATION = '<?xml version="1.0" encoding="UTF-8"?>\n'

interface KiwixBook {
  id: string
  path: string
  title: string
  description?: string
  language?: string
  creator?: string
  publisher?: string
  name?: string
  flavour?: string
  tags?: string
  faviconMimeType?: string
  favicon?: string
  date?: string
  articleCount?: number
  mediaCount?: number
  size?: number
}

export class KiwixLibraryService {
  getLibraryFilePath(): string {
    return join(process.cwd(), KIWIX_LIBRARY_XML_PATH)
  }

  containerLibraryPath(): string {
    return '/data/kiwix-library.xml'
  }

  private _filenameToTitle(filename: string): string {
    const withoutExt = filename.endsWith('.zim') ? filename.slice(0, -4) : filename
    const parts = withoutExt.split('_')
    // Drop last segment if it looks like a date (YYYY-MM)
    const lastPart = parts[parts.length - 1]
    const isDate = /^\d{4}-\d{2}$/.test(lastPart)
    const titleParts = isDate && parts.length > 1 ? parts.slice(0, -1) : parts
    return titleParts.map((p) => p.charAt(0).toUpperCase() + p.slice(1)).join(' ')
  }

  /**
   * Reads all kiwix-manage-compatible metadata from a ZIM file, including the internal UUID,
   * rich text fields, and the base64-encoded favicon. Kiwix-serve uses the UUID for OPDS
   * catalog entries and illustration URLs (/catalog/v2/illustration/{uuid}).
   *
   * Returns null on any error so callers can fall back gracefully.
   */
  private async _readZimMetadata(zimFilePath: string): Promise<Partial<KiwixBook> | null> {
    try {
      if (!(await isValidZimFile(zimFilePath))) {
        logger.warn(`[KiwixLibraryService] Skipping invalid/corrupted ZIM file: ${zimFilePath}`)
        return null
      }
      const archive = new Archive(zimFilePath)

      const getMeta = (key: string): string | undefined => {
        try {
          return archive.getMetadata(key) || undefined
        } catch {
          return undefined
        }
      }

      let favicon: string | undefined
      let faviconMimeType: string | undefined
      try {
        if (archive.illustrationSizes.size > 0) {
          const size = archive.illustrationSizes.has(48)
            ? 48
            : ([...archive.illustrationSizes][0] as number)
          const item = archive.getIllustrationItem(size)
          favicon = item.data.data.toString('base64')
          faviconMimeType = item.mimetype || undefined
        }
      } catch {
        // ZIM has no illustration — that's fine
      }

      const rawFilesize =
        typeof archive.filesize === 'bigint' ? Number(archive.filesize) : archive.filesize

      return {
        id: archive.uuid || undefined,
        title: getMeta('Title'),
        description: getMeta('Description'),
        language: getMeta('Language'),
        creator: getMeta('Creator'),
        publisher: getMeta('Publisher'),
        name: getMeta('Name'),
        flavour: getMeta('Flavour'),
        tags: getMeta('Tags'),
        date: getMeta('Date'),
        articleCount: archive.articleCount,
        mediaCount: archive.mediaCount,
        size: Math.floor(rawFilesize / 1024),
        favicon,
        faviconMimeType,
      }
    } catch {
      return null
    }
  }

  private _buildXml(books: KiwixBook[]): string {
    const builder = new XMLBuilder({
      ignoreAttributes: false,
      attributeNamePrefix: '@_',
      format: true,
      suppressEmptyNode: false,
    })

    const obj: Record<string, any> = {
      library: {
        '@_version': '20110515',
        ...(books.length > 0 && {
          book: books.map((b) => ({
            '@_id': b.id,
            '@_path': b.path,
            '@_title': b.title,
            ...(b.description !== undefined && { '@_description': b.description }),
            ...(b.language !== undefined && { '@_language': b.language }),
            ...(b.creator !== undefined && { '@_creator': b.creator }),
            ...(b.publisher !== undefined && { '@_publisher': b.publisher }),
            ...(b.name !== undefined && { '@_name': b.name }),
            ...(b.flavour !== undefined && { '@_flavour': b.flavour }),
            ...(b.tags !== undefined && { '@_tags': b.tags }),
            ...(b.faviconMimeType !== undefined && { '@_faviconMimeType': b.faviconMimeType }),
            ...(b.favicon !== undefined && { '@_favicon': b.favicon }),
            ...(b.date !== undefined && { '@_date': b.date }),
            ...(b.articleCount !== undefined && { '@_articleCount': b.articleCount }),
            ...(b.mediaCount !== undefined && { '@_mediaCount': b.mediaCount }),
            ...(b.size !== undefined && { '@_size': b.size }),
          })),
        }),
      },
    }

    return XML_DECLARATION + builder.build(obj)
  }

  private async _atomicWrite(content: string): Promise<void> {
    const filePath = this.getLibraryFilePath()
    const tmpPath = `${filePath}.tmp.${randomUUID()}`
    await writeFile(tmpPath, content, 'utf-8')
    await rename(tmpPath, filePath)
  }

  private _parseExistingBooks(xmlContent: string): KiwixBook[] {
    const parser = new XMLParser({
      ignoreAttributes: false,
      attributeNamePrefix: '@_',
      isArray: (name) => name === 'book',
    })

    const parsed = parser.parse(xmlContent)
    const books: any[] = parsed?.library?.book ?? []

    return books
      .map((b) => ({
        id: b['@_id'] ?? '',
        path: b['@_path'] ?? '',
        title: b['@_title'] ?? '',
        description: b['@_description'],
        language: b['@_language'],
        creator: b['@_creator'],
        publisher: b['@_publisher'],
        name: b['@_name'],
        flavour: b['@_flavour'],
        tags: b['@_tags'],
        faviconMimeType: b['@_faviconMimeType'],
        favicon: b['@_favicon'],
        date: b['@_date'],
        articleCount:
          b['@_articleCount'] !== undefined ? Number(b['@_articleCount']) : undefined,
        mediaCount: b['@_mediaCount'] !== undefined ? Number(b['@_mediaCount']) : undefined,
        size: b['@_size'] !== undefined ? Number(b['@_size']) : undefined,
      }))
      .filter((b) => b.id && b.path)
  }

  /**
   * Returns the number of books currently listed in the library XML, or 0 if the
   * file doesn't exist yet. Used to report a before/after delta on a manual rescan.
   */
  async getBookCount(): Promise<number> {
    try {
      const content = await readFile(this.getLibraryFilePath(), 'utf-8')
      return this._parseExistingBooks(content).length
    } catch (err: any) {
      if (err.code === 'ENOENT') return 0
      throw err
    }
  }

  /**
   * True if the library XML parses and has a <library> root. A truncated or
   * corrupt file (e.g. an interrupted write) fails this even though it exists,
   * so the caller can rebuild rather than leave Kiwix serving a broken library.
   * An empty-but-well-formed library is considered valid (nothing to repair).
   */
  private _isValidLibraryXml(xmlContent: string): boolean {
    try {
      const parser = new XMLParser({
        ignoreAttributes: false,
        attributeNamePrefix: '@_',
        isArray: (name) => name === 'book',
      })
      const parsed = parser.parse(xmlContent)
      return parsed?.library !== undefined && parsed?.library !== null
    } catch {
      return false
    }
  }

  /**
   * Boot-time safety net: if the library XML is missing or unparseable, rebuild
   * it from the ZIM files on disk so Kiwix (running in library mode with
   * --monitorLibrary) doesn't come up serving an empty/broken library with no
   * path to recovery. This covers files lost or corrupted outside the normal
   * download flow (storage relocation, interrupted write, manual deletion).
   *
   * Returns true if a rebuild was performed. Filesystem errors other than
   * "not found" are surfaced rather than masked by a rebuild.
   */
  async ensureLibraryXmlHealthy(): Promise<boolean> {
    let content: string
    try {
      content = await readFile(this.getLibraryFilePath(), 'utf-8')
    } catch (err: any) {
      if (err?.code === 'ENOENT') {
        logger.warn('[KiwixLibraryService] Library XML missing on startup; rebuilding from disk.')
        await this.rebuildFromDisk()
        return true
      }
      throw err
    }

    if (this._isValidLibraryXml(content)) return false

    logger.warn('[KiwixLibraryService] Library XML present but invalid; rebuilding from disk.')
    await this.rebuildFromDisk()
    return true
  }

  async rebuildFromDisk(opts?: { excludeFilenames?: string[] }): Promise<number> {
    const dirPath = join(process.cwd(), ZIM_STORAGE_PATH)
    await ensureDirectoryExists(dirPath)

    let entries: string[] = []
    try {
      entries = await readdir(dirPath)
    } catch {
      entries = []
    }

    const excludeSet = new Set(opts?.excludeFilenames ?? [])
    const zimFiles = entries.filter((name) => name.endsWith('.zim') && !excludeSet.has(name))

    const books: KiwixBook[] = []
    for (const filename of zimFiles) {
      const meta = await this._readZimMetadata(join(dirPath, filename))
      if (meta === null) {
        logger.warn(`[KiwixLibraryService] Skipping unreadable ZIM file: ${filename}`)
        continue
      }
      const containerPath = `${CONTAINER_DATA_PATH}/${filename}`
      books.push({
        ...meta,
        // Override fields that must be derived locally, not from ZIM metadata
        id: meta?.id ?? filename.slice(0, -4),
        path: containerPath,
        title: meta?.title ?? this._filenameToTitle(filename),
      })
    }

    const xml = this._buildXml(books)
    await this._atomicWrite(xml)
    logger.info(`[KiwixLibraryService] Rebuilt library XML with ${books.length} book(s).`)
    return books.length
  }

  async addBook(filename: string): Promise<void> {
    const zimFilename = filename.endsWith('.zim') ? filename : `${filename}.zim`
    const containerPath = `${CONTAINER_DATA_PATH}/${zimFilename}`

    const filePath = this.getLibraryFilePath()
    let existingBooks: KiwixBook[] = []

    try {
      const content = await readFile(filePath, 'utf-8')
      existingBooks = this._parseExistingBooks(content)
    } catch (err: any) {
      if (err.code === 'ENOENT') {
        // XML doesn't exist yet — rebuild from disk; the completed download is already there
        await this.rebuildFromDisk()
        return
      }
      throw err
    }

    if (existingBooks.some((b) => b.path === containerPath)) {
      logger.info(`[KiwixLibraryService] ${zimFilename} already in library, skipping.`)
      return
    }

    const fullPath = join(process.cwd(), ZIM_STORAGE_PATH, zimFilename)
    const meta = await this._readZimMetadata(fullPath)

    if (meta === null) {
      logger.error(`[KiwixLibraryService] Cannot add ${zimFilename}: file is invalid or corrupted.`)
      return
    }

    existingBooks.push({
      ...meta,
      id: meta?.id ?? zimFilename.slice(0, -4),
      path: containerPath,
      title: meta?.title ?? this._filenameToTitle(zimFilename),
    })

    const xml = this._buildXml(existingBooks)
    await this._atomicWrite(xml)
    logger.info(`[KiwixLibraryService] Added ${zimFilename} to library XML.`)
  }

  async removeBook(filename: string): Promise<void> {
    const zimFilename = filename.endsWith('.zim') ? filename : `${filename}.zim`
    const containerPath = `${CONTAINER_DATA_PATH}/${zimFilename}`

    const filePath = this.getLibraryFilePath()
    let existingBooks: KiwixBook[] = []

    try {
      const content = await readFile(filePath, 'utf-8')
      existingBooks = this._parseExistingBooks(content)
    } catch (err: any) {
      if (err.code === 'ENOENT') {
        logger.warn(`[KiwixLibraryService] Library XML not found, nothing to remove.`)
        return
      }
      throw err
    }

    const filtered = existingBooks.filter((b) => b.path !== containerPath)

    if (filtered.length === existingBooks.length) {
      logger.info(`[KiwixLibraryService] ${zimFilename} not found in library, nothing to remove.`)
      return
    }

    const xml = this._buildXml(filtered)
    await this._atomicWrite(xml)
    logger.info(`[KiwixLibraryService] Removed ${zimFilename} from library XML.`)
  }
}

