  // must be part of the eval corpus fingerprint.
  public static CHUNK_OVERLAP_TOKENS = 150
  public static PREFIX_TOKEN_BUDGET = 10 // Reserve ~10 tokens for prefixes
  public static CHAR_TO_TOKEN_RATIO = 2 // Conservative chars-per-token estimate; technical docs
  // (numbers, symbols, abbreviations) tokenize denser
  // than plain prose (~3), so 2 avoids context overflows
  // Nomic Embed Text v1.5 uses task-specific prefixes for optimal performance
  public static SEARCH_DOCUMENT_PREFIX = 'search_document: '
  public static SEARCH_QUERY_PREFIX = 'search_query: '
  public static EMBEDDING_BATCH_SIZE = 8 // Conservative batch size for low-end hardware

  constructor(
    private dockerService: DockerService,
    private ollamaService: OllamaService
  ) {}

  private async _initializeQdrantClient() {
    if (!this.qdrantInitPromise) {
      this.qdrantInitPromise = (async () => {
        const qdrantUrl = await this.dockerService.getServiceURL(SERVICE_NAMES.QDRANT)
        if (!qdrantUrl) {
          throw new Error(
            'Qdrant vector database is offline. Restart the AI Assistant service in Settings to restore the Knowledge Base.'
          )
        }
        this.qdrant = new QdrantClient({ url: qdrantUrl })
      })().catch((err) => {
        this.qdrantInitPromise = null
        this.qdrant = null
        throw err
      })
    }
    return this.qdrantInitPromise
  }

  public async checkQdrantHealth(): Promise<{ online: boolean; message?: string }> {
    try {
      await this._ensureDependencies()
      await this.qdrant!.getCollections()
      return { online: true }
    } catch {
      this.qdrant = null
      this.qdrantInitPromise = null
      // Qdrant may have restarted (or been recreated) — re-verify collections on reconnect
      this.ensuredCollections.clear()
      return {
        online: false,
        message:
          'Qdrant vector database is offline. Restart the AI Assistant service in Settings to restore the Knowledge Base.',
      }
    }
  }

  private async _ensureDependencies() {
    if (!this.qdrant) {
      await this._initializeQdrantClient()
    }
  }

  private async _ensureCollection(
    collectionName: string,
    dimensions: number = RagService.EMBEDDING_DIMENSION
  ) {
    try {
      await this._ensureDependencies()

      if (this.ensuredCollections.has(collectionName)) {
        return
      }

      const collections = await this.qdrant!.getCollections()
      const collectionExists = collections.collections.some((col) => col.name === collectionName)

      if (!collectionExists) {
        await this.qdrant!.createCollection(collectionName, {
          vectors: {
            size: dimensions,
            distance: 'Cosine',
          },
        })
      }

      // Create payload indexes for faster filtering (idempotent — Qdrant ignores duplicates)
      await this.qdrant!.createPayloadIndex(collectionName, {
        field_name: 'source',
        field_schema: 'keyword',
      })
      await this.qdrant!.createPayloadIndex(collectionName, {
        field_name: 'content_type',
        field_schema: 'keyword',
      })
      await this.qdrant!.createPayloadIndex(collectionName, {
        field_name: 'collection',
        field_schema: 'keyword',
      })
      await this.qdrant!.createPayloadIndex(collectionName, {
        field_name: 'active',
        field_schema: 'bool',
      })

      // Backfill: stamp `active: true` on any point that predates this field.
      // `is_empty` (not a match-all filter) means this only ever touches points
      // that have never been explicitly set, so re-running this on every boot
      // can never clobber a user's explicit toggle-off. This is data hygiene
      // only — search correctness never depends on it having run (see the
      // must_not filter in searchSimilarDocuments).
      await this.qdrant!.setPayload(collectionName, {
        payload: { active: true },
        filter: { must: [{ is_empty: { key: 'active' } }] },
      })

      // Only memoize after every step succeeded, so a partial failure is retried
      this.ensuredCollections.add(collectionName)
    } catch (error) {
      logger.error('Error ensuring Qdrant collection:', error)
      throw error
    }
  }

  /**
   * Sanitizes text to ensure it's safe for JSON encoding and Qdrant storage.
   * Removes problematic characters that can cause "unexpected end of hex escape" errors:
   * - Null bytes (\x00)
   * - Invalid Unicode sequences
   * - Control characters (except newlines, tabs, and carriage returns)
   */
  private sanitizeText(text: string): string {
    return (
      text
        // Null bytes
        .replace(/\x00/g, '')
        // Problematic control characters (keep \n, \r, \t)
        .replace(/[\x01-\x08\x0B-\x0C\x0E-\x1F\x7F]/g, '')
        // Invalid Unicode surrogates
        .replace(/[\uD800-\uDFFF]/g, '')
        // Trim extra whitespace
        .trim()
    )
  }

  /**
   * Estimates token count for text. This is a conservative approximation:
   * - English text: ~1 token per 3 characters
   * - Adds buffer for special characters and tokenization variance
   *
   * Note: This is approximate and realistic english
   * tokenization is ~4 chars/token, but we use 3 here to be safe.
   * Actual tokenization may differ, but being
   * conservative prevents context length errors.
   */
  private estimateTokenCount(text: string): number {
    // This accounts for special characters, numbers, and punctuation
    return Math.ceil(text.length / RagService.CHAR_TO_TOKEN_RATIO)
  }

  /**
   * Truncates text to fit within token limit, preserving word boundaries.
   * Ensures the text + prefix won't exceed the model's context window.
   */
  private truncateToTokenLimit(text: string, maxTokens: number): string {
    const estimatedTokens = this.estimateTokenCount(text)

    if (estimatedTokens <= maxTokens) {
      return text
    }

    // Calculate how many characters we can keep using our ratio
    const maxChars = Math.floor(maxTokens * RagService.CHAR_TO_TOKEN_RATIO)

    // Truncate at word boundary
    let truncated = text.substring(0, maxChars)
    const lastSpace = truncated.lastIndexOf(' ')

    if (lastSpace > maxChars * 0.8) {
      // If we found a space in the last 20%, use it
      truncated = truncated.substring(0, lastSpace)
    }

    logger.warn(
      `[RAG] Truncated text from ${text.length} to ${truncated.length} chars (est. ${estimatedTokens} → ${this.estimateTokenCount(truncated)} tokens)`
    )

    return truncated
  }

  /**
   * Preprocesses a query to improve retrieval by expanding it with context.
   * This helps match documents even when using different terminology.
   * TODO: We could probably move this to a separate QueryPreprocessor class if it grows more complex, but for now it's manageable here.
   */
  private static QUERY_EXPANSION_DICTIONARY: Record<string, string> = {
    bob: 'bug out bag',
    bov: 'bug out vehicle',
    bol: 'bug out location',
    edc: 'every day carry',
    mre: 'meal ready to eat',
    shtf: 'shit hits the fan',
    teotwawki: 'the end of the world as we know it',
    opsec: 'operational security',
    ifak: 'individual first aid kit',
    ghb: 'get home bag',
    ghi: 'get home in',
    wrol: 'without rule of law',
    emp: 'electromagnetic pulse',
    ham: 'ham amateur radio',
    nbr: 'nuclear biological radiological',
    cbrn: 'chemical biological radiological nuclear',
    sar: 'search and rescue',
    comms: 'communications radio',
    fifo: 'first in first out',
    mylar: 'mylar bag food storage',
    paracord: 'paracord 550 cord',
    ferro: 'ferro rod fire starter',
    bivvy: 'bivvy bivy emergency shelter',
    bdu: 'battle dress uniform',
    gmrs: 'general mobile radio service',
    frs: 'family radio service',
    nbc: 'nuclear biological chemical',
  }

  private preprocessQuery(query: string): string {
    let expanded = query.trim()

    // Expand known domain abbreviations/acronyms
    const words = expanded.toLowerCase().split(/\s+/)
    const expansions: string[] = []

    for (const word of words) {
      const cleaned = word.replace(/[^\w]/g, '')
      if (RagService.QUERY_EXPANSION_DICTIONARY[cleaned]) {
        expansions.push(RagService.QUERY_EXPANSION_DICTIONARY[cleaned])
      }
    }

    if (expansions.length > 0) {
      expanded = `${expanded} ${expansions.join(' ')}`
      logger.debug(`[RAG] Query expanded with domain terms: "${expanded}"`)
    }

    logger.debug(`[RAG] Original query: "${query}"`)
    logger.debug(`[RAG] Preprocessed query: "${expanded}"`)
    return expanded
  }

  /**
   * Extract keywords from query for hybrid search
   */
  private extractKeywords(query: string): string[] {
    const split = query.split(' ')
    const noStopWords = removeStopwords(split)

    // Future: This is basic normalization, could be improved with stemming/lemmatization later
    const keywords = noStopWords
      .map((word) => word.replace(/[^\w]/g, '').toLowerCase())
      .filter((word) => word.length > 2)

    return [...new Set(keywords)]
  }

  public async embedAndStoreText(
    text: string,
    metadata: Record<string, any> = {},
    onProgress?: (percent: number) => Promise<void>
  ): Promise<{ chunks: number } | null> {
    try {
      await this._ensureCollection(
        RagService.CONTENT_COLLECTION_NAME,
        RagService.EMBEDDING_DIMENSION
      )

      if (!this.embeddingModelVerified) {
        const allModels = await this.ollamaService.getModels(true)
        const embeddingModel =
          allModels.find((model) => model.name === EMBEDDING_MODEL_NAME) ??
          allModels.find((model) => model.name.toLowerCase().includes('nomic-embed-text'))

        if (!embeddingModel) {
          try {
            const downloadResult = await this.ollamaService.downloadModel(EMBEDDING_MODEL_NAME)
            if (!downloadResult.success) {
              throw new Error(downloadResult.message || 'Unknown error during model download')
            }
          } catch (modelError) {
            logger.error(
              `[RAG] Embedding model ${EMBEDDING_MODEL_NAME} not found locally and failed to download:`,
              modelError
            )
            this.embeddingModelVerified = false
            return null
          }
        }
        this.resolvedEmbeddingModel = embeddingModel?.name ?? EMBEDDING_MODEL_NAME
        this.embeddingModelVerified = true
      }

      // TokenChunker uses character-based tokenization (1 char = 1 token)
      // We need to convert our embedding model's token counts to character counts
      // since nomic-embed-text tokenizer uses ~3 chars per token
      const targetCharsPerChunk = Math.floor(RagService.TARGET_TOKENS_PER_CHUNK * RagService.CHAR_TO_TOKEN_RATIO)
      const overlapChars = Math.floor(RagService.CHUNK_OVERLAP_TOKENS * RagService.CHAR_TO_TOKEN_RATIO)

      const chunker = await TokenChunker.create({
        chunkSize: targetCharsPerChunk,
        chunkOverlap: overlapChars,
      })

      const chunkResults = await chunker.chunk(text)

      if (!chunkResults || chunkResults.length === 0) {
        throw new Error('No text chunks generated for embedding.')
      }

      // Extract text from chunk results
      const chunks = chunkResults.map((chunk) => chunk.text)

      // Prepare all chunk texts with prefix and truncation
      const prefixedChunks: string[] = []
      for (let i = 0; i < chunks.length; i++) {
        let chunkText = chunks[i]

        // Final safety check: ensure chunk + prefix fits
        const prefixText = RagService.SEARCH_DOCUMENT_PREFIX
        const withPrefix = prefixText + chunkText
        const estimatedTokens = this.estimateTokenCount(withPrefix)

        if (estimatedTokens > RagService.MAX_SAFE_TOKENS) {
          const prefixTokens = this.estimateTokenCount(prefixText)
          const maxTokensForText = RagService.MAX_SAFE_TOKENS - prefixTokens
          logger.warn(
            `[RAG] Chunk ${i} estimated at ${estimatedTokens} tokens (${chunkText.length} chars), truncating to ${maxTokensForText} tokens`
          )
          chunkText = this.truncateToTokenLimit(chunkText, maxTokensForText)
        }

        prefixedChunks.push(RagService.SEARCH_DOCUMENT_PREFIX + chunkText)
      }

      // Batch embed chunks for performance
      const embeddings: number[][] = []
      const batchSize = RagService.EMBEDDING_BATCH_SIZE
      const totalBatches = Math.ceil(prefixedChunks.length / batchSize)

      for (let batchIdx = 0; batchIdx < totalBatches; batchIdx++) {
        const batchStart = batchIdx * batchSize
        const batch = prefixedChunks.slice(batchStart, batchStart + batchSize)

        logger.debug(
          `[RAG] Embedding batch ${batchIdx + 1}/${totalBatches} (${batch.length} chunks)`
        )

        const response = await this.ollamaService.embed(
          this.resolvedEmbeddingModel ?? EMBEDDING_MODEL_NAME,
          batch
        )

        embeddings.push(...response.embeddings)

        if (onProgress) {
          const progress = ((batchStart + batch.length) / prefixedChunks.length) * 100
          await onProgress(progress)
        }
      }

      const timestamp = Date.now()

      // Sanitize source metadata once up front — every chunk in this call shares
      // the same source.
      const sanitizedSource =
        typeof metadata.source === 'string' ? this.sanitizeText(metadata.source) : 'unknown'

      // Preserve an existing file's active/inactive toggle across re-ingestion
      // (retries, force re-embeds, replaced-content reindexing, etc.) instead of
      // resetting it to active on every write. A genuinely new file (no row yet)
      // still defaults to active.
      const active = await this._readActiveFlag(sanitizedSource)

      const points = chunks.map((chunkText, index) => {
        // Sanitize text to prevent JSON encoding errors
        const sanitizedText = this.sanitizeText(chunkText)

        // Extract keywords from content
        const contentKeywords = this.extractKeywords(sanitizedText)

        // For ZIM content, also extract keywords from structural metadata
        let structuralKeywords: string[] = []
        if (metadata.full_title) {
          structuralKeywords = this.extractKeywords(metadata.full_title as string)
        } else if (metadata.article_title) {
          structuralKeywords = this.extractKeywords(metadata.article_title as string)
        }

        // Combine and dedup keywords
        const allKeywords = [...new Set([...structuralKeywords, ...contentKeywords])]

        logger.debug(`[RAG] Extracted keywords for chunk ${index}: [${allKeywords.join(', ')}]`)
        if (structuralKeywords.length > 0) {
          logger.debug(
            `[RAG]   - Structural: [${structuralKeywords.join(', ')}], Content: [${contentKeywords.join(', ')}]`
          )
        }

        return {
          id: randomUUID(), // qdrant requires either uuid or unsigned int
          vector: embeddings[index],
          payload: {
            ...metadata,
            text: sanitizedText,
            chunk_index: index,
            total_chunks: chunks.length,
            keywords: allKeywords.join(' '), // store as space-separated string for text search
            char_count: sanitizedText.length,
            created_at: timestamp,
            source: sanitizedSource,
            active,
          },
        }
      })

      await this.qdrant!.upsert(RagService.CONTENT_COLLECTION_NAME, { points })

      // A toggle can land between the read above and the upsert, and its
      // setPayload then misses these points. The toggles write the row before
      // Qdrant, so re-reading after the upsert closes the gap: either this read
      // sees the new value, or the toggle's setPayload runs after the upsert and
      // covers these points itself.
      const currentActive = await this._readActiveFlag(sanitizedSource)
      if (currentActive !== active) {
        await this.qdrant!.setPayload(RagService.CONTENT_COLLECTION_NAME, {
          payload: { active: currentActive },
          points: points.map((p) => p.id),
        })
      }

      logger.debug(`[RAG] Successfully embedded and stored ${chunks.length} chunks`)
      logger.debug(`[RAG] First chunk preview: "${chunks[0].substring(0, 100)}..."`)

      return { chunks: chunks.length }
    } catch (error) {
      console.error(error)
      logger.error('[RAG] Error embedding text:', error)
      return null
    }
  }

  private async preprocessImage(filebuffer: Buffer): Promise<Buffer> {
    return await sharp(filebuffer)
      .grayscale()
      .normalize()
      .sharpen()
      .resize({ width: 2000, fit: 'inside' })
      .toBuffer()
  }

  private async convertPDFtoImages(filebuffer: Buffer): Promise<Buffer[]> {
    const converted = await fromBuffer(filebuffer, {
      quality: 50,
      density: 200,
      format: 'png',
    }).bulk(-1, {
      responseType: 'buffer',
    })
    return converted.filter((res) => res.buffer).map((res) => res.buffer!)
  }

  private async extractPDFText(filebuffer: Buffer): Promise<string> {
    const parser = new PDFParse({ data: filebuffer })
    const data = await parser.getText()
    await parser.destroy()
    return data.text
  }

  private async extractTXTText(filebuffer: Buffer): Promise<string> {
    return filebuffer.toString('utf-8')
  }

  private async extractImageText(filebuffer: Buffer): Promise<string> {
    const worker = await createWorker('eng')
    const result = await worker.recognize(filebuffer)
    await worker.terminate()
    return result.data.text
  }

  private async processImageFile(fileBuffer: Buffer): Promise<string> {
    const preprocessedBuffer = await this.preprocessImage(fileBuffer)
    return await this.extractImageText(preprocessedBuffer)
  }

  /**
   * Will process the PDF and attempt to extract text.
   * If the extracted text is minimal, it will fallback to OCR on each page.
   */
  private async processPDFFile(fileBuffer: Buffer): Promise<string> {
    let extractedText = await this.extractPDFText(fileBuffer)

    // Check if there was no extracted text or it was very minimal
    if (!extractedText || extractedText.trim().length < 100) {
      logger.debug('[RAG] PDF text extraction minimal, attempting OCR on pages')
      // Convert PDF pages to images for OCR if text extraction was poor
      const imageBuffers = await this.convertPDFtoImages(fileBuffer)
      extractedText = ''

      for (const imgBuffer of imageBuffers) {
        const preprocessedImg = await this.preprocessImage(imgBuffer)
        const pageText = await this.extractImageText(preprocessedImg)
        extractedText += pageText + '\n'
      }
    }

    return extractedText
  }

  /**
   * Process a ZIM file: extract content with metadata and embed each chunk.
   * Returns early with complete result since ZIM processing is self-contained.
   * Supports batch processing to prevent lock timeouts on large ZIM files.
   */
  private async processZIMFile(
    filepath: string,
    deleteAfterEmbedding: boolean,
    batchOffset?: number,
    onProgress?: (percent: number) => Promise<void>,
    collection?: string
  ): Promise<ProcessZIMFileResponse> {
    const zimExtractionService = new ZIMExtractionService()

    // Process in batches to avoid lock timeout
    const startOffset = batchOffset || 0

    logger.info(
      `[RAG] Extracting ZIM content (batch: offset=${startOffset}, size=${ZIM_BATCH_SIZE})`
    )

    const {
      chunks: zimChunks,
      totalArticles,
      articlesProcessed,
    } = await zimExtractionService.extractZIMContent(filepath, {
      startOffset,
      batchSize: ZIM_BATCH_SIZE,
    })

    logger.info(
      `[RAG] Extracted ${zimChunks.length} chunks from ZIM file with enhanced metadata (file totalArticles=${totalArticles})`
    )

    // Process each chunk individually with its metadata
    let totalChunks = 0
    for (let i = 0; i < zimChunks.length; i++) {
      const zimChunk = zimChunks[i]
      const result = await this.embedAndStoreText(zimChunk.text, {
        source: filepath,
        content_type: 'zim_article',
        // Without this the ZIM path writes points with no `collection` at all, so
        // getKnowledgeCollections() (which facets on it) never sees them.
        ...(collection ? { collection } : {}),

        // Article-level context
        article_title: zimChunk.articleTitle,
        article_path: zimChunk.articlePath,

        // Section-level context
        section_title: zimChunk.sectionTitle,
        full_title: zimChunk.fullTitle,
        hierarchy: zimChunk.hierarchy,
        section_level: zimChunk.sectionLevel,

        // Use the same document ID for all chunks from the same article for grouping in search results
        document_id: zimChunk.documentId,

        // Archive metadata
        archive_title: zimChunk.archiveMetadata.title,
        archive_creator: zimChunk.archiveMetadata.creator,
        archive_publisher: zimChunk.archiveMetadata.publisher,
        archive_date: zimChunk.archiveMetadata.date,
        archive_language: zimChunk.archiveMetadata.language,
        archive_description: zimChunk.archiveMetadata.description,

        // Extraction metadata - not overly relevant for search, but could be useful for debugging and future features...
        extraction_strategy: zimChunk.strategy,
      })

      if (result) {
        totalChunks += result.chunks
      }

      if (onProgress) {
        await onProgress(((i + 1) / zimChunks.length) * 100)
      }
    }

    // Gate the continuation on articles the extractor CONSUMED, not on articles that
    // produced chunks. Articles whose text is empty after cleaning (redirect stubs,
    // category pages, media/PDF wrappers) contribute no documentIds, so a chunk-derived
    // count reads a normal sparse batch as end-of-archive and silently abandons the rest
    // of the file. See `zim_batch_decision.ts` for the full rationale.
    const articlesWithContent = new Set(zimChunks.map((c) => c.documentId)).size
    const hasMoreBatches = hasMoreArticleBatches({
      articlesProcessed,
      batchSize: ZIM_BATCH_SIZE,
    })

    logger.info(
      `[RAG] Successfully embedded ${totalChunks} total chunks from ${articlesWithContent}/${articlesProcessed} articles (hasMore: ${hasMoreBatches})`
    )

    // Only delete the file when:
    // 1. deleteAfterEmbedding is true (caller wants deletion)
    // 2. No more batches remain (this is the final batch)
    // This prevents race conditions where early batches complete after later ones
    const shouldDelete = deleteAfterEmbedding && !hasMoreBatches
    if (shouldDelete) {
      logger.info(`[RAG] Final batch complete, deleting ZIM file: ${filepath}`)
      await deleteFileIfExists(filepath)
    } else if (!hasMoreBatches) {
      logger.info(`[RAG] Final batch complete, but file deletion was not requested`)
    }

    return {
      success: true,
      message: hasMoreBatches
        ? 'ZIM batch processed successfully. More batches remain.'
        : 'ZIM file processed and embedded successfully with enhanced metadata.',
      chunks: totalChunks,
      hasMoreBatches,
      // MUST be the consumed count: EmbedFileJob advances the next batch offset by this
      // value. Reporting the content-bearing count instead re-reads the overlap on every
      // sparse batch, and a batch that yields no text at all would advance the offset by
      // zero and re-run the same window forever.
      articlesProcessed,
      totalArticles,
    }
  }

  private async processTextFile(fileBuffer: Buffer): Promise<string> {
    return await this.extractTXTText(fileBuffer)
  }

  /**
   * Extract text content from a DOCX file using mammoth. DOCX is a ZIP-based
   * XML format, so raw-text extraction (extractTXTText) would return garbage —
   * this parses the document XML properly and returns clean plain text.
   */
  private async processDocxFile(fileBuffer: Buffer): Promise<string> {
    const { value: text } = await mammoth.extractRawText({ buffer: fileBuffer })
    return text
  }

  /**
   * Extract text content from an EPUB file.
   * EPUBs are ZIP archives containing XHTML content files.
   * Reads the OPF manifest to determine reading order, then extracts
   * text from each content document in sequence.
   */
  private async processEPUBFile(fileBuffer: Buffer): Promise<string> {
    const zip = await JSZip.loadAsync(fileBuffer)

    // Read container.xml to find the OPF file path
    const containerXml = await zip.file('META-INF/container.xml')?.async('text')
    if (!containerXml) {
      throw new Error('Invalid EPUB: missing META-INF/container.xml')
    }

    // Parse container.xml to get the OPF rootfile path
    const $container = cheerio.load(containerXml, { xml: true })
    const opfPath = $container('rootfile').attr('full-path')
    if (!opfPath) {
      throw new Error('Invalid EPUB: no rootfile found in container.xml')
    }

    // Determine the base directory of the OPF file for resolving relative paths
    const opfDir = opfPath.includes('/') ? opfPath.substring(0, opfPath.lastIndexOf('/') + 1) : ''

    // Read and parse the OPF file
    const opfContent = await zip.file(opfPath)?.async('text')
    if (!opfContent) {
      throw new Error(`Invalid EPUB: OPF file not found at ${opfPath}`)
    }

    const $opf = cheerio.load(opfContent, { xml: true })

    // Build a map of manifest items (id -> href)
    const manifestItems = new Map<string, string>()
    $opf('manifest item').each((_, el) => {
      const id = $opf(el).attr('id')
      const href = $opf(el).attr('href')
      const mediaType = $opf(el).attr('media-type') || ''
      // Only include XHTML/HTML content documents
      if (id && href && (mediaType.includes('html') || mediaType.includes('xml'))) {
        manifestItems.set(id, href)
      }
    })

    // Get the reading order from the spine
    const spineOrder: string[] = []
    $opf('spine itemref').each((_, el) => {
      const idref = $opf(el).attr('idref')
      if (idref && manifestItems.has(idref)) {
        spineOrder.push(manifestItems.get(idref)!)
      }
    })

    // If no spine found, fall back to all manifest items
    const contentFiles = spineOrder.length > 0 ? spineOrder : Array.from(manifestItems.values())

    // Extract text from each content file in order
    const textParts: string[] = []
    for (const href of contentFiles) {
      const fullPath = opfDir + href
      const content = await zip.file(fullPath)?.async('text')
      if (content) {
        const $ = cheerio.load(content)
        // Remove script and style elements
        $('script, style').remove()
        const text = $('body').text().trim()
        if (text) {
          textParts.push(text)
        }
      }
    }

    const fullText = textParts.join('\n\n')
    logger.debug(
      `[RAG] EPUB extracted ${textParts.length} chapters, ${fullText.length} characters total`
    )
    return fullText
  }

  private async embedTextAndCleanup(
    extractedText: string,
    filepath: string,
    deleteAfterEmbedding: boolean = false,
    onProgress?: (percent: number) => Promise<void>,
    collection?: string
  ): Promise<{ success: boolean; message: string; chunks?: number }> {
    if (!extractedText || extractedText.trim().length === 0) {
      return {
        success: false,
        message: 'Process completed succesfully, but no text was found to embed.',
      }
    }

    const embedResult = await this.embedAndStoreText(
      extractedText,
      {
        source: filepath,
        ...(collection ? { collection } : {}),
      },
      onProgress
    )

    if (!embedResult) {
      return { success: false, message: 'Failed to embed and store the extracted text.' }
    }

    if (deleteAfterEmbedding) {
      logger.info(`[RAG] Embedding complete, deleting uploaded file: ${filepath}`)
      await deleteFileIfExists(filepath)
    }

    return {
      success: true,
      message: 'File processed and embedded successfully.',
      chunks: embedResult.chunks,
    }
  }

  /**
   * Main pipeline to process and embed an uploaded file into the RAG knowledge base.
   * This includes text extraction, chunking, embedding, and storing in Qdrant.
   *
   * Orchestrates file type detection and delegates to specialized processors.
   * For ZIM files, supports batch processing via batchOffset parameter.
   */
  public async processAndEmbedFile(
    filepath: string,
    deleteAfterEmbedding: boolean = false,
    batchOffset?: number,
    onProgress?: (percent: number) => Promise<void>,
    collection?: string
  ): Promise<ProcessAndEmbedFileResponse> {
    try {
      const fileType = determineFileType(filepath)
      logger.debug(`[RAG] Processing file: ${filepath} (detected type: ${fileType})`)

      if (fileType === 'unknown') {
        return { success: false, message: 'Unsupported file type.' }
      }

      // Read file buffer (not needed for ZIM as it reads directly)
      const fileBuffer = fileType !== 'zim' ? await getFile(filepath, 'buffer') : null
      if (fileType !== 'zim' && !fileBuffer) {
        return { success: false, message: 'Failed to read the uploaded file.' }
      }

      // Process based on file type
      // ZIM files are handled specially since they have their own embedding workflow
      if (fileType === 'zim') {
        return await this.processZIMFile(filepath, deleteAfterEmbedding, batchOffset, onProgress, collection)
      }

      // Extract text based on file type
      // Report ~10% when extraction begins; actual embedding progress follows via callback
      if (onProgress) await onProgress(10)
      let extractedText: string
      switch (fileType) {
        case 'image':
          extractedText = await this.processImageFile(fileBuffer!)
          break
        case 'pdf':
          extractedText = await this.processPDFFile(fileBuffer!)
          break
        case 'docx':
          extractedText = await this.processDocxFile(fileBuffer!)
          break
        case 'epub':
          extractedText = await this.processEPUBFile(fileBuffer!)
          break
        case 'text':
        default:
          extractedText = await this.processTextFile(fileBuffer!)
          break
      }

      // Extraction done — scale remaining embedding progress from 15% to 100%
      if (onProgress) await onProgress(15)
      const scaledProgress = onProgress ? (p: number) => onProgress(15 + p * 0.85) : undefined

      // Embed extracted text and cleanup
      return await this.embedTextAndCleanup(
        extractedText,
        filepath,
        deleteAfterEmbedding,
        scaledProgress,
        collection
      )
    } catch (error) {
      logger.error('[RAG] Error processing and embedding file:', error)
      return { success: false, message: 'Error processing and embedding file.' }
    }
  }

  /**
   * Search for documents similar to the query text in the Qdrant knowledge base.
   * Uses a hybrid approach combining semantic similarity and keyword matching.
   * Implements adaptive thresholds and result reranking for optimal retrieval.
   * @param query - The search query text
   * @param limit - Maximum number of results to return (default: 5)
   * @param scoreThreshold - Minimum similarity score threshold (default: 0.3, much lower than before)
   * @param minFinalScore - Post-rerank relevance floor; below it a chunk is dropped
   * @returns Array of relevant text chunks with their scores
   */
  public async searchSimilarDocuments(
    query: string,
    limit: number = 5,
    scoreThreshold: number = 0.3, // Lower default threshold - was 0.7, now 0.3
    collection?: string,
    /**
     * Optional sink for the intermediate ranked lists. When supplied, the raw
     * dense order, the post-rerank order, and the post-diversity order are all
     * written here. Purely observational — nothing about the returned result
     * changes — and it is what lets the eval harness answer "is the reranking
     * heuristic actually helping?" without a second implementation of search.
     */
    stagesOut?: RetrievalStages,
    /**
     * Relevance floor on the post-rerank score. Defaults to 0 so the parameter
     * is purely additive for callers that predate it; the chat pipeline and the
     * eval harness both pass a real value.
     */
    minFinalScore: number = 0,
    /** Optional sink for the floor's counts; see RetrievalFloorStats. */
    floorOut?: RetrievalFloorStats
  ): Promise<Array<{ text: string; score: number; metadata?: Record<string, any> }>> {
    try {
      logger.debug(`[RAG] Starting similarity search for query: "${query}"`)

      await this._ensureCollection(
        RagService.CONTENT_COLLECTION_NAME,
        RagService.EMBEDDING_DIMENSION
      )

      // Check if collection has any points
      const collectionInfo = await this.qdrant!.getCollection(RagService.CONTENT_COLLECTION_NAME)
      const pointCount = collectionInfo.points_count || 0
      logger.debug(`[RAG] Knowledge base contains ${pointCount} document chunks`)

      if (pointCount === 0) {
        logger.debug('[RAG] Knowledge base is empty. Could not perform search.')
        return []
      }

      if (!this.embeddingModelVerified) {
        const allModels = await this.ollamaService.getModels(true)
        const embeddingModel =
          allModels.find((model) => model.name === EMBEDDING_MODEL_NAME) ??
          allModels.find((model) => model.name.toLowerCase().includes('nomic-embed-text'))

        if (!embeddingModel) {
          logger.warn(`[RAG] ${EMBEDDING_MODEL_NAME} not found. Cannot perform similarity search.`)
          this.embeddingModelVerified = false
          return []
        }
        this.resolvedEmbeddingModel = embeddingModel.name
        this.embeddingModelVerified = true
      }

      // Preprocess query for better matching
      const processedQuery = this.preprocessQuery(query)
      const keywords = this.extractKeywords(processedQuery)
      logger.debug(`[RAG] Extracted keywords: [${keywords.join(', ')}]`)

      // Generate embedding for the query with search_query prefix
      // Ensure query doesn't exceed token limit
      const prefixTokens = this.estimateTokenCount(RagService.SEARCH_QUERY_PREFIX)
      const maxQueryTokens = RagService.MAX_SAFE_TOKENS - prefixTokens
      const truncatedQuery = this.truncateToTokenLimit(processedQuery, maxQueryTokens)

      const prefixedQuery = RagService.SEARCH_QUERY_PREFIX + truncatedQuery
      logger.debug(`[RAG] Generating embedding with prefix: "${RagService.SEARCH_QUERY_PREFIX}"`)

      // Validate final token count
      const queryTokenCount = this.estimateTokenCount(prefixedQuery)
      if (queryTokenCount > RagService.MAX_SAFE_TOKENS) {
        logger.error(
          `[RAG] Query too long even after truncation: ${queryTokenCount} tokens (max: ${RagService.MAX_SAFE_TOKENS})`
        )
        return []
      }

      const response = await this.ollamaService.embed(
        this.resolvedEmbeddingModel ?? EMBEDDING_MODEL_NAME,
        [prefixedQuery]
      )

      // Perform semantic search with a higher limit to enable reranking
      const searchLimit = limit * 3 // Get more results for reranking
      logger.debug(
        `[RAG] Searching for top ${searchLimit} semantic matches (threshold: ${scoreThreshold})`
      )

      const searchResults = await this.qdrant!.search(RagService.CONTENT_COLLECTION_NAME, {
        vector: response.embeddings[0],
        limit: searchLimit,
        score_threshold: scoreThreshold,
        with_payload: true,
        filter: {
          // Denylist, not allowlist: a point with no `active` field at all
          // (not yet backfilled) must still be found by default. Search
          // correctness must never depend on the backfill's timing.
          must_not: [{ key: 'active', match: { value: false } }],
          ...(collection ? { must: [{ key: 'collection', match: { value: collection } }] } : {}),
        },
      })

      logger.debug(`[RAG] Found ${searchResults.length} results above threshold ${scoreThreshold}`)

      // Map results with metadata for reranking
      const resultsWithMetadata: RAGResult[] = searchResults.map((result) => ({
        text: (result.payload?.text as string) || '',
        score: result.score,
        keywords: (result.payload?.keywords as string) || '',
        chunk_index: (result.payload?.chunk_index as number) || 0,
        created_at: (result.payload?.created_at as number) || 0,
        // Enhanced ZIM metadata (likely be undefined for non-ZIM content)
        article_title: result.payload?.article_title as string | undefined,
        section_title: result.payload?.section_title as string | undefined,
        full_title: result.payload?.full_title as string | undefined,
        hierarchy: result.payload?.hierarchy as string | undefined,
        document_id: result.payload?.document_id as string | undefined,
        content_type: result.payload?.content_type as string | undefined,
        source: result.payload?.source as string | undefined,
        // Citation metadata (#1179) -- date/title of the archive a chunk was
        // extracted from, when known. Undefined for non-ZIM content, which
        // carries no equivalent embedded metadata.
        archive_title: result.payload?.archive_title as string | undefined,
        archive_date: result.payload?.archive_date as string | undefined,
      }))

      const rerankedResults = this.rerankResults(resultsWithMetadata, keywords, query)

      logger.debug(`[RAG] Top 3 results after reranking:`)
      rerankedResults.slice(0, 3).forEach((result, idx) => {
        logger.debug(
          `[RAG]   ${idx + 1}. Score: ${result.finalScore.toFixed(4)} (semantic: ${result.score.toFixed(4)}) - "${result.text.substring(0, 100)}..."`
        )
      })

      // Relevance floor, applied here — after reranking, before diversity.
      //
      // The ordering is deliberate. The floor is a judgement about relevance,
      // and the reranked score is where that judgement is best informed. The
      // diversity penalty that follows is about redundancy, not relevance: it
      // multiplies by 0.85^n, so flooring afterwards would drop the fourth chunk
      // of the one document that actually answers the question and blame a knob
      // labelled "relevance" for it.
      const { survivors, belowFloor } = applyRelevanceFloor(rerankedResults, minFinalScore)
      if (floorOut) {
        floorOut.candidates = rerankedResults.length
        floorOut.belowFloor = belowFloor
      }
      if (belowFloor > 0) {
        logger.debug(
          `[RAG] Relevance floor ${minFinalScore}: dropped ${belowFloor} of ${rerankedResults.length} chunk(s)`
        )
      }
      if (survivors.length === 0 && rerankedResults.length > 0) {
        // Nothing cleared the bar. Returning empty is the point: the pipeline
        // then injects no context block at all, rather than handing the model
        // passages it has to be talked out of using.
        logger.debug(
          `[RAG] Nothing cleared the relevance floor (best was ${rerankedResults[0].finalScore.toFixed(4)}) — injecting no context`
        )
      }

      // Apply source diversity penalty to avoid all results from the same document
      const diverseResults = this.applySourceDiversity(survivors)

      // Record the three ranked lists for the eval harness's stage ablation.
      // Sliced to `limit` so each stage is compared on the window that would
      // actually have been injected, not on the wider rerank candidate pool.
      //
      // `reranked` is recorded pre-floor on purpose: the ablation asks whether
      // each heuristic *orders* better, and a filter applied to two of the three
      // lists would answer a different question. The floor's own effect is
      // measured by sweeping --min-final-score against the headline metrics.
      if (stagesOut) {
        const summarize = (rows: Array<{ text: string; score: number; source?: string }>) =>
          rows.slice(0, limit).map((r) => ({ source: r.source, score: r.score }))
        stagesOut.dense = summarize(resultsWithMetadata)
        stagesOut.reranked = rerankedResults
          .slice(0, limit)
          .map((r) => ({ source: r.source, score: r.finalScore }))
        stagesOut.diversified = diverseResults
          .slice(0, limit)
          .map((r) => ({ source: r.source, score: r.finalScore }))
        stagesOut.candidates = rerankedResults.map((r) => ({
          source: r.source,
          score: r.finalScore,
          semanticScore: r.score,
        }))
      }

      // Return top N results with enhanced metadata
      return diverseResults.slice(0, limit).map((result) => ({
        text: result.text,
        score: result.finalScore,
        metadata: {
          chunk_index: result.chunk_index,
          created_at: result.created_at,
          semantic_score: result.score,
          // The originating file/ZIM path. Stored on every point but previously
          // dropped here, which made it impossible to map a retrieved chunk back
          // to its document — needed for citations and for recall@k scoring.
          source: result.source,
          // Enhanced ZIM metadata (likely be undefined for non-ZIM content)
          article_title: result.article_title,
          section_title: result.section_title,
          full_title: result.full_title,
          hierarchy: result.hierarchy,
          document_id: result.document_id,
          content_type: result.content_type,
          // Citation metadata (#1179)
          archive_title: result.archive_title,
          archive_date: result.archive_date,
        },
      }))
    } catch (error) {
      logger.error('[RAG] Error searching similar documents:', error)
      return []
    }
  }

  /**
   * Rerank search results using hybrid scoring that combines:
   * 1. Semantic similarity score (primary signal)
   * 2. Keyword overlap bonus (conservative, quality-gated)
   * 3. Direct term matches (conservative)
   *
   * Tries to boost only already-relevant results, not promote
   * low-quality results just because they have keyword matches.
   *
   * Future: this is a decent feature-based approach, but we could
   * switch to a python-based reranker in the future if the benefits
   * outweigh the overhead.
   */
  private rerankResults(
    results: Array<RAGResult>,
    queryKeywords: string[],
    originalQuery: string
  ): Array<RerankedRAGResult> {
    return results
      .map((result) => {
        let finalScore = result.score

        // Quality gate: Only apply boosts if semantic score is reasonable
        // Try to prevent promoting irrelevant results that just happen to have keyword matches
        const MIN_SEMANTIC_THRESHOLD = 0.35

        if (result.score < MIN_SEMANTIC_THRESHOLD) {
          // For low-scoring results, use semantic score as-is
          // This prevents false positives from keyword gaming
          logger.debug(
            `[RAG] Skipping boost for low semantic score: ${result.score.toFixed(3)} (threshold: ${MIN_SEMANTIC_THRESHOLD})`
          )
          return {
            ...result,
            finalScore,
          }
        }

        // Boost score based on keyword overlap (diminishing returns - overlap goes down, so does boost)
        const docKeywords = result.keywords
          .toLowerCase()
          .split(' ')
          .filter((k) => k.length > 0)
        const matchingKeywords = queryKeywords.filter(
          (kw) =>
            docKeywords.includes(kw.toLowerCase()) ||
            result.text.toLowerCase().includes(kw.toLowerCase())
        )
        const keywordOverlap = matchingKeywords.length / Math.max(queryKeywords.length, 1)

        // Use square root for diminishing returns: 100% overlap = sqrt(1.0) = 1.0, 25% = 0.5
        // Then scale conservatively (max 10% boost instead of 20%)
        const keywordBoost = Math.sqrt(keywordOverlap) * 0.1 * result.score

        if (keywordOverlap > 0) {
          logger.debug(
            `[RAG] Keyword overlap: ${matchingKeywords.length}/${queryKeywords.length} - Boost: ${keywordBoost.toFixed(3)}`
          )
        }

        // Boost if original query terms appear in text (case-insensitive)
        // Scale boost proportionally to base score to avoid over-promoting weak matches
        const queryTerms = originalQuery
          .toLowerCase()
          .split(/\s+/)
          .filter((t) => t.length > 3)
        const directMatches = queryTerms.filter((term) =>
          result.text.toLowerCase().includes(term)
        ).length

        if (queryTerms.length > 0) {
          const directMatchRatio = directMatches / queryTerms.length
          // Conservative boost: max 7.5% of the base score
          const directMatchBoost = Math.sqrt(directMatchRatio) * 0.075 * result.score

          if (directMatches > 0) {
            logger.debug(
              `[RAG] Direct term matches: ${directMatches}/${queryTerms.length} - Boost: ${directMatchBoost.toFixed(3)}`
            )
            finalScore += directMatchBoost
          }
        }

        // Boost when query keywords match the chunk's section/article heading. ZIM
        // content carries this structural metadata (already fetched, no extra cost),
        // and a query term appearing in a heading is a strong relevance signal that
        // body-text matching alone misses. Same conservative, score-scaled, diminishing
        // -returns shape as the boosts above, so it can't promote a weak match.
        const headingText = [result.full_title, result.section_title, result.article_title]
          .filter(Boolean)
          .join(' ')
          .toLowerCase()
        if (headingText) {
          const headingHits = queryKeywords.filter((kw) =>
            headingText.includes(kw.toLowerCase())
          ).length
          if (headingHits > 0) {
            const headingRatio = headingHits / Math.max(queryKeywords.length, 1)
            const headingBoost = Math.sqrt(headingRatio) * 0.1 * result.score
            logger.debug(
              `[RAG] Heading match: ${headingHits}/${queryKeywords.length} - Boost: ${headingBoost.toFixed(3)}`
            )
            finalScore += headingBoost
          }
        }

        finalScore = Math.min(1.0, finalScore + keywordBoost)

        return {
          ...result,
          finalScore,
        }
      })
      .sort((a, b) => b.finalScore - a.finalScore)
  }

  /**
   * Applies a diversity penalty so results from the same source are down-weighted.
   * Uses greedy selection: for each result, apply 0.85^n penalty where n is the
   * number of results already selected from the same source.
   */
  private applySourceDiversity(results: Array<RerankedRAGResult>) {
    const sourceCounts = new Map<string, number>()
    const DIVERSITY_PENALTY = 0.85

    return results
      .map((result) => {
        const sourceKey = result.document_id || result.source || 'unknown'
        const count = sourceCounts.get(sourceKey) || 0
        const penalty = Math.pow(DIVERSITY_PENALTY, count)
        const diverseScore = result.finalScore * penalty

        sourceCounts.set(sourceKey, count + 1)

        if (count > 0) {
          logger.debug(
            `[RAG] Source diversity penalty for "${sourceKey}": ${result.finalScore.toFixed(4)} → ${diverseScore.toFixed(4)} (seen ${count}x)`
          )
        }

        return { ...result, finalScore: diverseScore }
      })
      .sort((a, b) => b.finalScore - a.finalScore)
  }

  /**
   * Retrieve all unique source files that have been stored in the knowledge base.
   * @returns Array of unique full source paths
   */
  public async hasDocuments(): Promise<boolean> {
    try {
      await this._ensureCollection(
        RagService.CONTENT_COLLECTION_NAME,
        RagService.EMBEDDING_DIMENSION
      )
      const collectionInfo = await this.qdrant!.getCollection(RagService.CONTENT_COLLECTION_NAME)
      return (collectionInfo.points_count ?? 0) > 0
    } catch {
      return false
    }
  }

  public async getStoredFiles(): Promise<StoredFileInfo[]> {
    try {
      await this._ensureCollection(
        RagService.CONTENT_COLLECTION_NAME,
        RagService.EMBEDDING_DIMENSION
      )

      // Use Qdrant's facet API to enumerate distinct `source` values in one
      // call. The previous scroll-loop walked every point in the collection
      // (3M+ on a fully-ingested NOMAD) just to learn the ~40 unique sources,
      // which made this endpoint take 50+ seconds. Facet returns the unique
      // values directly. `exact: true` so the count we'll reuse for warnings
      // matches what would be reported by an exhaustive walk.
      const sources = new Set<string>()
      const facetResult = await this.qdrant!.facet(RagService.CONTENT_COLLECTION_NAME, {
        key: 'source',
        limit: RagService.FACET_SOURCE_LIMIT,
        exact: true,
        // Keep the developer eval corpus out of the user's Stored Files list.
        // It shares this Qdrant collection but is not the user's content, and
        // its fixture paths would render as broken/missing files in the KB UI.
        filter: EXCLUDE_EVAL_FILTER,
      })
      for (const hit of facetResult.hits) {
        if (typeof hit.value === 'string') sources.add(hit.value)
      }

      // Union the Qdrant-derived list with the disk-backed file paths the
      // state machine has tracked. Without this, files known to the scanner
      // but with zero embedded chunks (video-only ZIMs, failed-before-first-
      // chunk ingestions, browse_only opt-outs) never get a row in Stored
      // Files — which means warnings keyed off those files (#895 zero_chunks
      // in particular) have no row to attach to. The state machine is the
      // authoritative "what's on disk?" view; Qdrant is "what made it into
      // the vector store?". Both are needed to render the KB UI honestly.
      const stateByPath = new Map<
        string,
        {
          state: KbIngestStateValue
          chunks_embedded: number
          collection: string | null
          active: boolean
        }
      >()
      try {
        const stateRows = await KbIngestState.query().select(
          'file_path',
          'state',
          'chunks_embedded',
          'collection',
          'active'
        )
        for (const row of stateRows) {
          sources.add(row.file_path)
          stateByPath.set(row.file_path, {
            state: row.state,
            chunks_embedded: row.chunks_embedded,
            collection: row.collection,
            // MySQL hands back tinyint(1) as 0/1, not a boolean. Coerce here so
            // every consumer sees a real boolean -- the raw 1 reached the DOM as
            // aria-checked="1", which is not a valid ARIA value and leaves screen
            // readers with no idea whether the toggle is on.
            active: Boolean(row.active),
          })
        }
      } catch (error) {
        // Non-fatal: if the state machine query fails for any reason we'd
        // rather return the Qdrant-derived list than 500 the whole panel.
        logger.warn(
          { err: error },
          '[RagService.getStoredFiles] state-machine union skipped; returning Qdrant-only list'
        )
      }

      const uploadsAbsPath = resolve(join(process.cwd(), RagService.UPLOADS_STORAGE_PATH))
      return await Promise.all(
        Array.from(sources).map(async (source) => {
          const row = stateByPath.get(source)
          const fileName = source.split(/[/\\]/).at(-1) ?? source
          const isUserUpload = resolve(source).startsWith(uploadsAbsPath + sep)
          const stats = await getFileStatsIfExists(source)
          return {
            source,
            state: row?.state ?? null,
            chunksEmbedded: row?.chunks_embedded ?? 0,
            fileName,
            size: stats?.size ?? null,
            uploadedAt: stats?.modifiedTime.toISOString() ?? null,
            isUserUpload,
            collection: row?.collection ?? null,
            active: row ? Boolean(row.active) : true,
          }
        })
      )
    } catch (error) {
      logger.error('Error retrieving stored files:', error)
      return []
    }
  }

  /**
   * Enumerate distinct `collection` values currently in the knowledge base,
   * for populating a subject-picker in the upload/chat UI. Mirrors the
   * `source` facet pattern used elsewhere in this file (see getStoredFiles).
   */
  public async getKnowledgeCollections(): Promise<string[]> {
    await this._ensureCollection(RagService.CONTENT_COLLECTION_NAME, RagService.EMBEDDING_DIMENSION)
    const facetResult = await this.qdrant!.facet(RagService.CONTENT_COLLECTION_NAME, {
      key: 'collection',
      limit: RagService.FACET_SOURCE_LIMIT,
      exact: true,
    })
    const collections = new Set<string>()
    for (const hit of facetResult.hits) {
      // The reserved eval tag is internal; never offer it in a subject picker.
      if (typeof hit.value === 'string' && hit.value !== KB_EVAL_COLLECTION) {
        collections.add(hit.value)
      }
    }
    return Array.from(collections).sort()
  }

  /**
   * Reassign a stored file's collection after the fact. Updates the `collection`
   * payload field on every existing Qdrant point for this source in place (no
   * re-chunking or re-embedding needed), then mirrors the change onto the
   * KbIngestState row so getStoredFiles() reflects it immediately.
   */
  public async updateFileCollection(
    source: string,
    collection: string | null
  ): Promise<{ success: boolean; message: string }> {
    try {
      await this._ensureCollection(
        RagService.CONTENT_COLLECTION_NAME,
        RagService.EMBEDDING_DIMENSION
      )

      await this.qdrant!.setPayload(RagService.CONTENT_COLLECTION_NAME, {
        payload: { collection },
        filter: { must: [{ key: 'source', match: { value: source } }] },
      })

      // The setPayload above only reaches points that already exist, so for a file
      // that has not been indexed yet it matches nothing. The row is therefore the
      // only durable record of the choice until EmbedFileJob picks it up -- create
      // it when absent rather than reporting success and storing the value nowhere.
      const row = await KbIngestState.getOrCreate(source)
      row.collection = collection
      await row.save()

      return {
        success: true,
        message: collection ? `Moved to "${collection}".` : 'Moved to Uncategorized.',
      }
    } catch (error) {
      logger.error('[RAG] Error updating file collection:', error)
      return { success: false, message: 'Error updating file collection.' }
    }
  }

  /**
   * Toggle a file's active (searchable) state. Writes the KbIngestState row,
   * then updates the `active` payload field on every existing Qdrant point for
   * this source in place — no deletion or re-embedding, so this is instant in
   * either direction. Vectors stay in Qdrant permanently either way; only
   * `searchSimilarDocuments()`'s query-time filter is affected. See #1119.
   *
   * The row goes first so an in-flight embedAndStoreText() call always ends up
   * with the right value: its post-upsert re-read either sees this write, or
   * the setPayload below runs after its upsert and covers the new points.
   */
  public async setFileActive(
    source: string,
    active: boolean
  ): Promise<{ success: boolean; message: string }> {
    try {
      await this._ensureCollection(
        RagService.CONTENT_COLLECTION_NAME,
        RagService.EMBEDDING_DIMENSION
      )

      // A source can have chunks in Qdrant but no state row: a ZIM mid-ingestion
      // (markIndexed only runs after the final batch), a pre-RFC install, or a
      // lost row. getStoredFiles() reports such a file as active, so skipping the
      // write here left the switch stuck on while every point went inactive, and
      // the user had no way to turn it back on. Create the row the same way the
      // scanner backfills it: `indexed` when chunks exist, so the file doesn't
      // regress to pending_decision and get re-dispatched.
      let row = await KbIngestState.query().where('file_path', source).first()
      const previousActive = row ? Boolean(row.active) : true
      if (!row) {
        const { count } = await this.qdrant!.count(RagService.CONTENT_COLLECTION_NAME, {
          filter: { must: [{ key: 'source', match: { value: source } }] },
          exact: false,
        })
        row = await KbIngestState.firstOrCreate(
          { file_path: source },
          {
            file_path: source,
            state: count > 0 ? 'indexed' : 'pending_decision',
            chunks_embedded: 0,
            collection: null,
            active,
          }
        )
      }
      row.active = active
      await row.save()

      try {
        await this.qdrant!.setPayload(RagService.CONTENT_COLLECTION_NAME, {
          payload: { active },
          filter: { must: [{ key: 'source', match: { value: source } }] },
        })
      } catch (error) {
        // Put the row back so the panel keeps showing what retrieval does.
        row.active = previousActive
        await row.save()
        throw error
      }

      return { success: true, message: active ? 'File is now active.' : 'File is now inactive.' }
    } catch (error) {
      logger.error('[RAG] Error updating file active state:', error)
      return { success: false, message: 'Error updating file active state.' }
    }
  }

  /**
   * A source's active flag as a real boolean. MySQL returns tinyint(1) as 0/1,
   * and a raw 0 stamped into a Qdrant payload slips past the
   * `must_not: active == false` search filter. A source with no row is active.
   */
  private async _readActiveFlag(source: string): Promise<boolean> {
    const row = await KbIngestState.query().where('file_path', source).first()
    return row ? Boolean(row.active) : true
  }

  /**
   * Toggle every file tagged with a KB collection (the personal-upload
   * `collection` field -- not the unrelated curated ZIM-pack "collections"
   * feature) active/inactive in one bulk operation, mirroring the
   * collection-scoped bulk writes in renameKnowledgeCollection/
   * deleteKnowledgeCollection rather than looping setFileActive() per file.
   * `collection: null` targets the "Uncategorized" bucket.
   *
   * Returns the count of files whose active value actually changed (not the
   * collection's total membership), so the caller can report accurate scope
   * for what is otherwise an opaque bulk action -- e.g. "Turned off 9 files",
   * not "Turned off 12" when 3 were already inactive.
   */
  public async setKnowledgeCollectionActive(
    collection: string | null,
    active: boolean
  ): Promise<{ success: boolean; message: string; affectedCount: number }> {
    try {
      await this._ensureCollection(
        RagService.CONTENT_COLLECTION_NAME,
        RagService.EMBEDDING_DIMENSION
      )

      const collectionQuery = () =>
        collection === null
          ? KbIngestState.query().whereNull('collection')
          : KbIngestState.query().where('collection', collection)

      const collectionFilterClause =
        collection === null
          ? { is_empty: { key: 'collection' } }
          : { key: 'collection', match: { value: collection } }

      // Rows before Qdrant, for the same reason as setFileActive(). Only rows
      // that change are touched, so a failed setPayload can restore exactly
      // those without flipping files that already held the target value.
      const changedPaths = (
        await collectionQuery().where('active', !active).select('file_path')
      ).map((r) => r.file_path)
      const affectedCount = changedPaths.length
      await collectionQuery().update({ active })

      try {
        await this.qdrant!.setPayload(RagService.CONTENT_COLLECTION_NAME, {
          payload: { active },
          filter: { must: [collectionFilterClause] },
        })
      } catch (error) {
        if (changedPaths.length > 0) {
          await KbIngestState.query().whereIn('file_path', changedPaths).update({ active: !active })
        }
        throw error
      }

      const label = collection ?? 'Uncategorized'
      const verb = active ? 'Turned on' : 'Turned off'
      return {
        success: true,
        message: `${verb} ${affectedCount} file${affectedCount === 1 ? '' : 's'} in "${label}".`,
        affectedCount,
      }
    } catch (error) {
      logger.error('[RAG] Error updating KB collection active state:', error)
      return {
        success: false,
        message: 'Error updating collection active state.',
        affectedCount: 0,
      }
    }
  }

  /**
   * Rename a knowledge-base collection everywhere it's referenced: updates every
   * Qdrant point tagged with the old name in place, and mirrors the change onto
   * any matching KbIngestState rows so getStoredFiles() reflects it immediately.
   */
  public async renameKnowledgeCollection(
    oldName: string,
    newName: string
  ): Promise<{ success: boolean; message: string }> {
    try {
      if (!oldName || !newName || oldName === newName) {
        return { success: false, message: 'Invalid collection names.' }
      }
      await this._ensureCollection(
        RagService.CONTENT_COLLECTION_NAME,
        RagService.EMBEDDING_DIMENSION
      )

      await this.qdrant!.setPayload(RagService.CONTENT_COLLECTION_NAME, {
        payload: { collection: newName },
        filter: { must: [{ key: 'collection', match: { value: oldName } }] },
      })

      await KbIngestState.query().where('collection', oldName).update({ collection: newName })

      return { success: true, message: `Renamed "${oldName}" to "${newName}".` }
    } catch (error) {
      logger.error('[RAG] Error renaming knowledge collection:', error)
      return { success: false, message: 'Error renaming collection.' }
    }
  }

  /**
   * Remove a collection by reassigning every file tagged with it back to
   * Uncategorized (collection: null). Non-destructive — no files or embeddings
   * are deleted, only the grouping label is cleared so items can be
   * recategorized later.
   */
  public async deleteKnowledgeCollection(
    name: string
  ): Promise<{ success: boolean; message: string }> {
    try {
      if (!name) {
        return { success: false, message: 'Invalid collection name.' }
      }
      await this._ensureCollection(
        RagService.CONTENT_COLLECTION_NAME,
        RagService.EMBEDDING_DIMENSION
      )

      await this.qdrant!.setPayload(RagService.CONTENT_COLLECTION_NAME, {
        payload: { collection: null },
        filter: { must: [{ key: 'collection', match: { value: name } }] },
      })

      await KbIngestState.query().where('collection', name).update({ collection: null })

      return { success: true, message: `"${name}" removed. Files moved to Uncategorized.` }
    } catch (error) {
      logger.error('[RAG] Error deleting knowledge collection:', error)
      return { success: false, message: 'Error deleting collection.' }
    }
  }

  /**
   * Count the points carrying a given `collection` tag.
   *
   * Distinct from the facet-based counts above, which deliberately exclude
   * internal collections. This answers "how many chunks are in exactly this
   * collection", which is what the eval harness needs to confirm an ingest
   * landed and what a future per-collection UI would want.
   */
  public async countChunksInCollection(collection: string): Promise<number> {
    await this._ensureCollection(RagService.CONTENT_COLLECTION_NAME, RagService.EMBEDDING_DIMENSION)
    const result = await this.qdrant!.count(RagService.CONTENT_COLLECTION_NAME, {
      filter: { must: [{ key: 'collection', match: { value: collection } }] },
      exact: true,
    })
    return result.count
  }

  /**
   * Hard-delete every point carrying a given `collection` tag.
   *
   * Note this is NOT what `deleteKnowledgeCollection` does — that one clears the
   * tag and leaves the user's documents in place, because deleting a user's
   * content because they renamed a folder would be indefensible. This one
   * genuinely removes the points, and exists for the eval corpus, which is
   * disposable by construction. Returns the number of points removed.
   */
  public async deleteCollectionPoints(collection: string): Promise<number> {
    await this._ensureCollection(RagService.CONTENT_COLLECTION_NAME, RagService.EMBEDDING_DIMENSION)
    const before = await this.countChunksInCollection(collection)
    if (before === 0) return 0
    await this.qdrant!.delete(RagService.CONTENT_COLLECTION_NAME, {
      wait: true,
      filter: { must: [{ key: 'collection', match: { value: collection } }] },
    })
    return before
  }

  /**
   * Resolve a stored-file `source` to an absolute disk path, but only if the
   * path lives under the uploads directory. Mirrors the docs_service traversal
   * guard: resolve, then require the resolved path to be strictly inside the
   * base + path separator (so siblings of `kb_uploads` can't slip through).
   * Returns null for anything else — ZIMs, admin docs, README, or paths
   * outside the app entirely. The viewer/download endpoints lean on this so
   * they don't need to repeat the check.
   */
  private resolveUploadPath(source: string): string | null {
    const uploadsAbsPath = resolve(join(process.cwd(), RagService.UPLOADS_STORAGE_PATH))
    const resolved = resolve(source)
    if (!resolved.startsWith(uploadsAbsPath + sep)) return null
    return resolved
  }

  private static readonly VIEWABLE_TEXT_EXTENSIONS: ReadonlySet<string> = new Set([
    'md',
    'txt',
    'csv',
    'json',
    'yaml',
    'yml',
    'toml',
    'xml',
    'html',
  ])

  /**
   * Read the text content of a user-uploaded file for in-browser viewing.
   * Returns null when the source is outside uploads, missing, or not a
   * recognized text extension. The extension allowlist is intentionally narrow
   * — PDFs/EPUBs/ZIMs round-trip through Download, not the viewer.
   */
  public async readFileContent(
    source: string
  ): Promise<{ content: string; extension: string; fileName: string } | null> {
    const resolved = this.resolveUploadPath(source)
    if (!resolved) return null

    const extension = resolved.split('.').at(-1)?.toLowerCase() ?? ''
    if (!RagService.VIEWABLE_TEXT_EXTENSIONS.has(extension)) return null

    const stats = await getFileStatsIfExists(resolved)
    if (!stats) return null

    try {
      const { readFile } = await import('node:fs/promises')
      const content = await readFile(resolved, 'utf-8')
      const fileName = resolved.split(/[/\\]/).at(-1) ?? resolved
      return { content, extension, fileName }
    } catch (error) {
      logger.warn({ err: error, source }, '[RagService.readFileContent] read failed')
      return null
    }
  }

  /**
   * Resolve a download-target path for a stored upload. Returns null if the
   * source isn't an upload or the file is missing on disk.
   */
  public async resolveDownloadPath(source: string): Promise<string | null> {
    const resolved = this.resolveUploadPath(source)
    if (!resolved) return null
    const stats = await getFileStatsIfExists(resolved)
    return stats ? resolved : null
  }

  /**
   * Compute whether the first-chat JIT prompt should fire and surface the file
   * count the banner uses in its copy ("Index your N existing files?"). The
   * banner appears when the user hasn't yet picked a global ingest policy
   * (`rag.defaultIngestPolicy` unset) and the scanner has actually seen at
   * least one embeddable file — i.e., the prompt is actionable, not theoretical
   * on a freshly-installed empty NOMAD.
   *
   * Once the user picks a policy (Always or Manual) via the banner buttons or
   * the KB modal toggle, `shouldPrompt` flips to false for good.
   */
  public async getPolicyPromptState(): Promise<{
    shouldPrompt: boolean
    hasContent: boolean
    totalFiles: number
  }> {
    const policy = await KVStore.getValue('rag.defaultIngestPolicy')
    const countRow = await KbIngestState.query().count('* as total').first()
    const totalFiles = Number((countRow as any)?.$extras?.total ?? 0)
    return {
      shouldPrompt: policy === null && totalFiles > 0,
      hasContent: totalFiles > 0,
      totalFiles,
    }
  }

  /**
   * Compute conditional warnings (RFC #883 §6) for every source the scanner
   * sees on disk. Returns `{ ok, warnings }` — `ok: false` distinguishes a
   * computation failure (Qdrant unreachable, DB outage, FS error) from the
   * healthy-but-empty case, which is critical because the whole point of this
   * surface is to expose silent failures; reporting "everything healthy" when
   * we couldn't actually check would reintroduce the bug we set out to fix.
   *
   * Per-source chunk counts come from a single Qdrant scroll over the
   * collection's points; expected-chunk estimates come from the ratio
   * registry. Files in the scanner's directories that have no qdrant points
   * at all show up with `chunksInQdrant: 0` so Warning A can fire.
   */
  public async computeFileWarnings(): Promise<FileWarningsResult> {
    try {
      await this._ensureCollection(
        RagService.CONTENT_COLLECTION_NAME,
        RagService.EMBEDDING_DIMENSION
      )

      // Per-source chunk count via Qdrant's facet API. Was a full scroll of
      // every point in the collection, which on a fully-ingested NOMAD takes
      // ~50s for a 3M-point KB just to count ~40 sources. Facet returns the
      // distinct values + counts in a single call. `exact: true` because the
      // counts feed Warning A's zero_chunks decision — approximate counts
      // could mis-fire warnings near thresholds.
      const chunksBySource = new Map<string, number>()
      const facetResult = await this.qdrant!.facet(RagService.CONTENT_COLLECTION_NAME, {
        key: 'source',
        limit: RagService.FACET_SOURCE_LIMIT,
        exact: true,
        // Same exclusion as getStoredFiles: eval fixtures are not user files,
        // and counting them here would raise bogus zero_chunks warnings.
        filter: EXCLUDE_EVAL_FILTER,
      })
      for (const hit of facetResult.hits) {
        if (typeof hit.value === 'string') chunksBySource.set(hit.value, hit.count)
      }

      // Scan the filesystem the same way scanAndSyncStorage does so Warning A
      // can fire on files with zero qdrant points (the headline "video-only
      // ZIM" case).
      const KB_UPLOADS_PATH = join(process.cwd(), RagService.UPLOADS_STORAGE_PATH)
      const ZIM_PATH = join(process.cwd(), ZIM_STORAGE_PATH)
      const allSources = new Set<string>(chunksBySource.keys())
      const sizeByPath = new Map<string, number>()

      for (const dir of [KB_UPLOADS_PATH, ZIM_PATH]) {
        try {
          const entries = await listDirectoryContentsRecursive(dir)
          for (const entry of entries) {
            if (entry.type !== 'file') continue
            allSources.add(entry.key)
            const stat = await getFileStatsIfExists(entry.key)
            if (stat) sizeByPath.set(entry.key, Number(stat.size))
          }
        } catch (error: any) {
          if (error?.code !== 'ENOENT') throw error
        }
      }

      const out: Record<string, FileWarning[]> = {}
      for (const source of allSources) {
        const fileSizeBytes = sizeByPath.get(source) ?? 0
        const chunksInQdrant = chunksBySource.get(source) ?? 0
        const fileName = source.split(/[/\\]/).pop() ?? source
        // ignoreCatchAll: the partial_stall warning must only fire when the
        // registry has a *specific* expectation for this file. The empty-pattern
        // fallback (100 chunks/MB) over-predicts wildly for atypical ZIMs that
        // are mostly PDFs/images/link-outs (e.g. military-medicine), producing
        // false "ingestion stalled" warnings. Suppress Warning B in that case. (#913)
        const expectedChunks =
          fileSizeBytes > 0
            ? await KbRatioRegistry.estimateChunks(fileName, fileSizeBytes, {
                ignoreCatchAll: true,
              })
            : null

        const warnings = decideWarnings({ fileSizeBytes, chunksInQdrant, expectedChunks })
        if (warnings.length > 0) out[source] = warnings
      }

      return { ok: true, warnings: out }
    } catch (error) {
      logger.error('[RAG] Error computing file warnings:', error)
      return { ok: false, warnings: {} }
    }
  }

  /**
   * Delete all Qdrant points associated with a given source path and remove
   * the corresponding file from disk if it lives under the uploads directory.
   * @param source - Full source path as stored in Qdrant payloads
   */
  public async deleteFileBySource(source: string): Promise<{ success: boolean; message: string }> {
    try {
      await this._ensureCollection(
        RagService.CONTENT_COLLECTION_NAME,
        RagService.EMBEDDING_DIMENSION
      )

      await this.qdrant!.delete(RagService.CONTENT_COLLECTION_NAME, {
        filter: {
          must: [{ key: 'source', match: { value: source } }],
        },
      })

      logger.info(`[RAG] Deleted all points for source: ${source}`)

      /** Delete the physical file only if it lives inside the uploads directory.
       * resolve() normalises path traversal sequences (e.g. "/../..") before the
       * check to prevent path traversal vulns
       * The trailing sep is to ensure a prefix like "kb_uploads_{something_incorrect}" can't slip through.
       */
      const uploadsAbsPath = join(process.cwd(), RagService.UPLOADS_STORAGE_PATH)
      const resolvedSource = resolve(source)
      if (resolvedSource.startsWith(uploadsAbsPath + sep)) {
        await deleteFileIfExists(resolvedSource)
        logger.info(`[RAG] Deleted uploaded file from disk: ${resolvedSource}`)
      } else {
        logger.warn(
          `[RAG] File was removed from knowledge base but doesn't live in Nomad's uploads directory, so it can't be safely removed. Skipping deletion of physical file...`
        )
      }

      // Drop the ingest state row last so the file disappears entirely. Without
      // this, the next scanAndSyncStorage would see `indexed + no chunks` for a
      // path that no longer exists in storage and try to re-embed nothing.
      await KbIngestState.remove(source)

      return { success: true, message: 'File removed from knowledge base.' }
    } catch (error) {
      logger.error('[RAG] Error deleting file from knowledge base:', error)
      return { success: false, message: 'Error deleting file from knowledge base.' }
    }
  }

  /**
   * Reconcile the knowledge base after a curated content file (a ZIM) is
   * replaced on disk by a newer downloaded version. Called from
   * `RunDownloadJob.onComplete` once the new file is written and the old file
   * has been deleted from disk.
   *
   * The decision (see `decideContentReindex` for the exhaustive, tested
   * contract) mirrors the REPLACED file's prior indexed state instead of the
   * global `rag.defaultIngestPolicy`. On a content update the user has already
   * chosen whether this content belongs in the AI knowledge base, so we honor
   * that choice in both directions:
   *
   *   1. (caller already deleted the outdated file from disk)
   *   2. Qdrant not installed          → no-op (no knowledge base exists)
   *   3. Old file WAS indexed + Qdrant
   *      running                       → delete ONLY the old file's points
   *                                       (filter `source == oldFilePath`), drop
   *                                       its ingest-state row, and queue the new
   *                                       file for embedding — BYPASSING the
   *                                       Always/Manual policy on purpose.
   *   4. Old file NOT indexed          → no-op (respect the prior un-indexed /
   *                                       browse-only choice; do NOT auto-embed
   *                                       even under an Always policy)
   *   5. Old indexed but Qdrant NOT
   *      currently running             → no-op. We can't remove the stale points,
   *                                       and a queued embed job could be cleared
   *                                       before Qdrant returns. Acting half-way is
   *                                       wasteful, so we defer entirely. Accepted
   *                                       tradeoff: the old file's points linger in
   *                                       Qdrant until a future re-index; they are
   *                                       NOT auto-reaped here.
   *
   * Point deletion is exact: ZIM chunks are stored with `source` equal to the
   * full file path (see embedAndStoreText callers), so filtering on the old path
   * can only ever remove the replaced file's own points.
   *
   * Returns the decision outcome for logging/tests; never throws on a Qdrant
   * hiccup mid-reindex (logged and surfaced as `qdrant_not_running` semantics by
   * the caller's try/catch).
   */
  public async reconcileReplacedContentFile(params: {
    oldFilePath: string
    newFilePath: string
    fileName: string
  }): Promise<ReindexOutcome> {
    const { oldFilePath, newFilePath, fileName } = params

    const isReplacement = !!oldFilePath && oldFilePath !== newFilePath

    // Step 2: is the knowledge base even installed? Short-circuits before any
    // KB-state lookup, per the spec ordering.
    const qdrantInstalled = isReplacement
      ? !!(await this.dockerService.getServiceURL(SERVICE_NAMES.QDRANT))
      : false

    // Steps 3/4: was the OUTDATED file actually indexed? The state row is the
    // authoritative signal (RFC #883) — chunk presence alone can't distinguish
    // a fully-indexed file from a stalled ingestion.
    let oldFileWasIndexed = false
    if (isReplacement && qdrantInstalled) {
      const oldState = await KbIngestState.query().where('file_path', oldFilePath).first()
      oldFileWasIndexed = oldState?.state === 'indexed'
    }

    // Step 5: only check liveness once we know we'd otherwise act. The health
    // check is a real network round-trip, so we avoid it on the common no-op
    // paths above.
    let qdrantRunning = false
    if (isReplacement && qdrantInstalled && oldFileWasIndexed) {
      qdrantRunning = (await this.checkQdrantHealth()).online
    }

    const outcome = decideContentReindex({
      isReplacement,
      qdrantInstalled,
      oldFileWasIndexed,
      qdrantRunning,
    })

    if (outcome === 'reindex') {
      // Order matters: remove the stale points and state row BEFORE queueing the
      // new embed so a fresh index can't be conflated with the old one. Each step
      // targets only `oldFilePath` / `newFilePath` — never another resource.
      await this.purgeIndexedSource(oldFilePath)
      const { EmbedFileJob } = await import('#jobs/embed_file_job')
      await EmbedFileJob.dispatch({ fileName, filePath: newFilePath })
    }

    return outcome
  }

  /**
   * Root paths for Nomad's own bundled docs (README.md + docs/), embedded by
   * discoverNomadDocs(). They live outside kb_uploads/zim storage, so
   * _discoverKbFiles()'s scan never sees them — the orphan sweep in
   * scanAndSyncStorage() uses this to exclude them rather than hardcoding
   * the same two paths a second time.
   */
  private _nomadDocsRoots(): { readmePath: string; docsDir: string } {
    return {
      readmePath: join(process.cwd(), 'README.md'),
      docsDir: join(process.cwd(), 'docs'),
    }
  }

  public async discoverNomadDocs(force?: boolean): Promise<{ success: boolean; message: string }> {
    try {
      const { readmePath: README_PATH, docsDir: DOCS_DIR } = this._nomadDocsRoots()

      const alreadyEmbeddedRaw = await KVStore.getValue('rag.docsEmbedded')
      if (alreadyEmbeddedRaw && !force) {
        logger.info('[RAG] Nomad docs have already been discovered and queued. Skipping.')
        return {
          success: true,
          message: 'Nomad docs have already been discovered and queued. Skipping.',
        }
      }

      const filesToEmbed: Array<{ path: string; source: string }> = []

      const readmeExists = await getFileStatsIfExists(README_PATH)
      if (readmeExists) {
        filesToEmbed.push({ path: README_PATH, source: 'README.md' })
      }

      const dirContents = await listDirectoryContentsRecursive(DOCS_DIR)
      for (const entry of dirContents) {
        if (entry.type === 'file') {
          filesToEmbed.push({ path: entry.key, source: join('docs', entry.name) })
        }
      }

      logger.info(`[RAG] Discovered ${filesToEmbed.length} Nomad doc files to embed`)

      // Import EmbedFileJob dynamically to avoid circular dependencies
      const { EmbedFileJob } = await import('#jobs/embed_file_job')

      // Dispatch an EmbedFileJob for each discovered file
      for (const fileInfo of filesToEmbed) {
        try {
          logger.info(`[RAG] Dispatching embed job for: ${fileInfo.source}`)
          await EmbedFileJob.dispatch({
            filePath: fileInfo.path,
            fileName: fileInfo.source,
          })
          logger.info(`[RAG] Successfully dispatched job for ${fileInfo.source}`)
        } catch (fileError) {
          logger.error(`[RAG] Error dispatching job for file ${fileInfo.source}:`, fileError)
        }
      }

      // Update KV store to mark docs as discovered so we don't redo this unnecessarily
      await KVStore.setValue('rag.docsEmbedded', true)

      return {
        success: true,
        message: `Nomad docs discovery completed. Dispatched ${filesToEmbed.length} embedding jobs.`,
      }
    } catch (error) {
      logger.error('Error discovering Nomad docs:', error)
      return { success: false, message: 'Error discovering Nomad docs.' }
    }
  }

  /**
   * Absolute roots that _discoverKbFiles() scans. Shared with the orphan
   * sweep in scanAndSyncStorage() so it can allowlist candidates to sources
   * actually reachable by that scan, rather than denylisting every other
   * known source root by hand — a source embedded under a future root
   * outside kb_uploads/zim would otherwise be silently misclassified as
   * orphaned and purged the first time it's added (see _nomadDocsRoots()
   * for exactly that lesson learned with README.md/docs).
   */
  private _kbScanRoots(): { kbUploadsPath: string; zimPath: string } {
    return {
      kbUploadsPath: join(process.cwd(), RagService.UPLOADS_STORAGE_PATH),
      zimPath: join(process.cwd(), ZIM_STORAGE_PATH),
    }
  }

  /**
   * Walk kb_uploads and zim storage directories, returning the full path of
   * every embeddable file. Non-embeddable types (e.g. kiwix-library.xml) are
   * filtered out so they aren't dispatched only to fail with "Unsupported file
   * type" and retry on every sync.
   */
  private async _discoverKbFiles(): Promise<string[]> {
    return (await this._discoverKbFilesWithRoots()).files
  }

  /**
   * As _discoverKbFiles(), but also reports which roots were actually walked.
   *
   * A root that isn't there is skipped rather than fatal, because a fresh
   * install legitimately has no kb_uploads until the first upload. That makes
   * an absent root indistinguishable from a present-but-empty one by looking
   * at the file list alone — and the orphan sweep in scanAndSyncStorage()
   * cannot afford to confuse the two. "This root wasn't there" means we know
   * nothing about it and must not touch it. A root that was there but empty
   * is not much better evidence: boot creates the zim directory, so an
   * unmounted volume shows up as an empty one (#1378). decideOrphans()
   * therefore also refuses to purge under a walked root with no files.
   *
   * That distinction is the whole reason this variant exists. If the zim root
   * is missing, renamed, or not yet mounted (see #1050 — relocating the data
   * path is easy to get subtly wrong), the scan still returns a non-empty
   * list from kb_uploads. A guard that only checks "did the scan come back
   * empty" therefore passes, and every ZIM in the index gets purged in one
   * batch. Reporting the roots lets the sweep confine itself to ground it
   * actually stood on.
   */
  private async _discoverKbFilesWithRoots(): Promise<{
    files: string[]
    scannedRoots: string[]
  }> {
    const { kbUploadsPath: KB_UPLOADS_PATH, zimPath: ZIM_PATH } = this._kbScanRoots()
    const filesInStorage: string[] = []
    const scannedRoots: string[] = []

    for (const [label, dirPath] of [
      [RagService.UPLOADS_STORAGE_PATH, KB_UPLOADS_PATH] as const,
      [ZIM_STORAGE_PATH, ZIM_PATH] as const,
    ]) {
      try {
        const contents = await listDirectoryContentsRecursive(dirPath)
        contents.forEach((entry) => {
          if (entry.type === 'file') filesInStorage.push(entry.key)
        })
        scannedRoots.push(dirPath)
        logger.debug(`[RAG] Found ${contents.length} files in ${label}`)
      } catch (error) {
        if (error.code === 'ENOENT') {
          logger.debug(`[RAG] ${label} directory does not exist, skipping`)
        } else {
          throw error
        }
      }
    }

    return {
      files: filesInStorage.filter((f) => determineFileType(f) !== 'unknown'),
      scannedRoots,
    }
  }

  /**
   * Dispatch one EmbedFileJob per file path. Returns honest counts: `queuedCount`
   * is jobs newly enqueued, `dedupedCount` is jobs that hit BullMQ's per-file
   * jobId dedupe (an existing :completed/:waiting/etc. entry was returned
   * instead of a new enqueue), and `failedPaths` lists files whose dispatch
   * threw. Pass `force: true` for bulk callers that need to bypass dedupe
   * entirely. Per-file errors are logged but don't abort the batch — callers
   * must inspect `failedPaths` to surface partial failure to the operator.
   */
  private async _dispatchEmbedJobsFor(
    filePaths: string[],
    options?: { force?: boolean }
  ): Promise<{ queuedCount: number; dedupedCount: number; failedPaths: string[] }> {
    const { EmbedFileJob } = await import('#jobs/embed_file_job')
    let queuedCount = 0
    let dedupedCount = 0
    const failedPaths: string[] = []
    for (const filePath of filePaths) {
      try {
        const fileName = filePath.split(/[/\\]/).pop() || filePath
        const stats = await getFileStatsIfExists(filePath)
        const result = await EmbedFileJob.dispatch(
          {
            filePath,
            fileName,
            fileSize: stats?.size,
          },
          { force: options?.force }
        )
        if (result.created) {
          queuedCount++
        } else {
          dedupedCount++
        }
      } catch (fileError) {
        failedPaths.push(filePath)
        logger.error(`[RAG] Error dispatching job for file ${filePath}:`, fileError)
      }
    }
    return { queuedCount, dedupedCount, failedPaths }
  }

  /**
   * Dispatch an embed job for a single stored file. Wraps `_dispatchEmbedJobsFor`
   * with the safety checks needed for a user-triggered per-row action:
   *   1. The source must be known to the scanner OR have a state row — prevents
   *      arbitrary path dispatch from the public API.
   *   2. We refuse if any inflight job (waiting/active/delayed/paused) already
   *      targets this filePath. Otherwise a double-click or a rapid retry could
   *      enqueue duplicate jobs, producing duplicate chunks.
   *   3. When `force` is true (Re-embed of an already-indexed file), we
   *      pre-delete the prior Qdrant points so the new run doesn't stack on
   *      top of the old ones. For force=false (Index of a never-embedded file),
   *      there's nothing to clear.
   */
  public async embedSingleFile(
    source: string,
    force: boolean = false
  ): Promise<EmbedSingleFileResult> {
    const stateRow = await KbIngestState.query().where('file_path', source).first()
    if (!stateRow) {
      const knownFiles = await this._discoverKbFiles()
      if (!knownFiles.includes(source)) {
        return {
          success: false,
          code: 'not_found',
          message: 'File is not a tracked knowledge-base source.',
        }
      }
    }

    const { EmbedFileJob } = await import('#jobs/embed_file_job')
    const { QueueService } = await import('#services/queue_service')
    const queue = QueueService.getInstance().getQueue(EmbedFileJob.queue)
    const inflight = await queue.getJobs(['waiting', 'active', 'delayed', 'paused'])
    if (inflight.some((j) => j.data?.filePath === source)) {
      return {
        success: false,
        code: 'inflight',
        message:
          'A job for this file is already in progress. Wait for it to finish before re-queuing.',
      }
    }

    if (force) {
      try {
        await this._deletePointsBySource(source)
      } catch (err) {
        logger.error(`[RAG] Failed to delete prior points for ${source}; aborting re-embed:`, err)
        return {
          success: false,
          code: 'delete_failed',
          message: 'Failed to clear prior embeddings before re-embed.',
        }
      }
    }

    const result = await this._dispatchEmbedJobsFor([source], { force })
    if (result.failedPaths.length > 0) {
      return {
        success: false,
        code: 'dispatch_failed',
        message: 'Failed to dispatch embed job for this file.',
      }
    }
    return {
      success: true,
      message: force ? 'Re-embed queued for this file.' : 'Indexing queued for this file.',
    }
  }

  /**
   * Delete all Qdrant points whose `source` payload matches the given path.
   * Unlike deleteFileBySource(), this does NOT touch the file on disk — used
   * by reembedAll() where the file must remain so it can be re-ingested.
   */
  private async _deletePointsBySource(source: string): Promise<void> {
    await this._deletePointsBySources([source])
  }

  /**
   * Same as _deletePointsBySource(), but for many sources in one round trip
   * via Qdrant's `match.any` filter — used by the orphan sweep below, where
   * purging one-by-one would mean a separate delete call (plus a separate
   * _ensureCollection check) per orphan.
   */
  private async _deletePointsBySources(sources: string[]): Promise<void> {
    if (sources.length === 0) return
    await this._ensureCollection(RagService.CONTENT_COLLECTION_NAME, RagService.EMBEDDING_DIMENSION)
    await this.qdrant!.delete(RagService.CONTENT_COLLECTION_NAME, {
      filter: { must: [{ key: 'source', match: { any: sources } }] },
    })
  }

  /**
   * Purge a source's Qdrant points and its `KbIngestState` row without
   * touching the file on disk. For callers where the file is already gone
   * (or never existed as a knowledge-base upload) — `ZimService.delete()`
   * (#1170) and the orphan sweep in `scanAndSyncStorage()` below. Does NOT
   * attempt to delete a physical file; use `deleteFileBySource()` for the
   * user-triggered "remove this file" action instead.
   *
   * State row removed first, points second: orphan detection in
   * scanAndSyncStorage() only looks at what's still in Qdrant, so if a
   * failure lands between the two steps, leftover points stay visible to
   * the next sync's reverse sweep and get retried there. Deleting the
   * points first would instead risk an orphaned state row that nothing
   * ever looks at again. Both steps are individually idempotent, so a
   * retry from either partial state is safe.
   */
  public async purgeIndexedSource(source: string): Promise<void> {
    await this.purgeIndexedSources([source])
  }

  /**
   * Batched form of purgeIndexedSource() — one KbIngestState delete query
   * and one Qdrant delete call for the whole list, instead of a per-source
   * round trip to each. Used by the orphan sweep in scanAndSyncStorage(),
   * which can otherwise find dozens of orphans after a bulk content change.
   */
  public async purgeIndexedSources(sources: string[]): Promise<void> {
    if (sources.length === 0) return
    await KbIngestState.query().whereIn('file_path', sources).delete()
    await this._deletePointsBySources(sources)
  }

  /**
   * Returns true if the file-embeddings queue has any in-flight work
   * (waiting, active, delayed, or paused). Bulk re-embed actions use this
   * to refuse mid-flight to avoid racing with deletes/dispatches already
   * in progress.
   */
  private async _hasInflightEmbedJobs(): Promise<boolean> {
    const { EmbedFileJob } = await import('#jobs/embed_file_job')
    const { QueueService } = await import('#services/queue_service')
    const queue = QueueService.getInstance().getQueue(EmbedFileJob.queue)
    const counts = await queue.getJobCounts('waiting', 'active', 'delayed', 'paused')
    return (
      (counts.waiting || 0) + (counts.active || 0) + (counts.delayed || 0) + (counts.paused || 0) >
      0
    )
  }

  /**
   * Scans the knowledge base storage directories and syncs with Qdrant.
   * Identifies files that exist in storage but haven't been embedded yet,
   * and dispatches EmbedFileJob for each missing file.
   */
  public async scanAndSyncStorage(): Promise<{
    success: boolean
    message: string
    filesScanned?: number
    filesQueued?: number
  }> {
    try {
      logger.info('[RAG] Starting knowledge base sync scan')

      await this.discoverNomadDocs(true).catch((error) => {
        logger.error('[RAG] Error during Nomad docs discovery in sync process:', error)
      })

      const { files: filesInStorage, scannedRoots } = await this._discoverKbFilesWithRoots()
      logger.info(`[RAG] Found ${filesInStorage.length} embeddable files in storage`)

      await this._ensureCollection(
        RagService.CONTENT_COLLECTION_NAME,
        RagService.EMBEDDING_DIMENSION
      )

      // Collect every unique `source` already in Qdrant so we can skip files
      // that have already been embedded. Facet returns the distinct values in
      // a single call rather than scrolling the whole collection.
      const sourcesInQdrant = new Set<string>()
      const facetResult = await this.qdrant!.facet(RagService.CONTENT_COLLECTION_NAME, {
        key: 'source',
        limit: RagService.FACET_SOURCE_LIMIT,
        exact: true,
      })
      for (const hit of facetResult.hits) {
        if (typeof hit.value === 'string') sourcesInQdrant.add(hit.value)
      }

      logger.info(`[RAG] Found ${sourcesInQdrant.size} unique sources in Qdrant`)

      // Load all known per-file ingest states. The state row is authoritative
      // over the "any chunks in Qdrant" heuristic — it captures user choices
      // (browse_only) and terminal outcomes (failed, stalled) that aren't visible
      // from Qdrant alone. See RFC #883 for the full state machine.
      const stateRows = await KbIngestState.all()
      const stateByPath = new Map(stateRows.map((row) => [row.file_path, row]))

      // Non-embeddable files (e.g. kiwix-library.xml in /storage/zim) would otherwise
      // be dispatched to EmbedFileJob, fail with "Unsupported file type", and retry
      // on every sync — filter them out before state decisions.
      const embeddableFiles = filesInStorage.filter(
        (filePath) => determineFileType(filePath) !== 'unknown'
      )

      // Reverse sweep (#1170): sourcesInQdrant and embeddableFiles are both
      // already known at this point — the forward loop below only ever asks
      // "is this on-disk file already embedded?" This closes the other
      // direction: a source in Qdrant with no corresponding file on disk is a
      // leftover from ZimService.delete() (which never touched Qdrant) or
      // from reconcileReplacedContentFile's qdrant_not_running no-op. Running
      // this in sync (rather than only in the delete path) also self-heals
      // installs already in this state.
      //
      // Confined to `scannedRoots`, the roots the scan above actually walked,
      // not the roots it meant to walk. Nomad's own bundled docs (README.md +
      // docs/) live outside these roots, so they're left alone without being
      // named here, and a root missing at scan time contributes nothing
      // (#1050). Within each walked root, decideOrphans also withholds the
      // purge when the root holds no embeddable files (an unmounted volume
      // leaves an empty mountpoint behind, #1378) or when it would remove most
      // of the root at once. Withheld roots are reported back to the operator
      // rather than silently skipped.
      const { orphans, withheld } = decideOrphans(
        [...sourcesInQdrant],
        embeddableFiles,
        scannedRoots
      )
      for (const w of withheld) {
        logger.warn(
          `[RAG] Withheld purge of ${w.count} indexed source(s) under ${w.root} (${w.reason}); the directory may be unmounted or pointing at the wrong location`
        )
      }
      let orphansPurged = 0
      if (orphans.length > 0) {
        logger.info(
          `[RAG] Found ${orphans.length} orphaned source(s) with no corresponding file on disk`
        )
        try {
          await this.purgeIndexedSources(orphans)
          orphansPurged = orphans.length
        } catch (error) {
          logger.error(`[RAG] Failed to purge orphaned sources:`, error)
        }
        logger.info(`[RAG] Purged ${orphansPurged}/${orphans.length} orphaned source(s)`)
      }

      // Read the global ingest policy. Unset is treated as 'Always' so legacy
      // installs keep their current behavior until the user explicitly opts
      // into Manual mode from the KB panel.
      const policyRaw = await KVStore.getValue('rag.defaultIngestPolicy')
      const policy: IngestPolicy = policyRaw === 'Manual' ? 'Manual' : 'Always'

      const filesToEmbed: string[] = []
      let backfilled = 0
      let createdRows = 0
      let createdPending = 0
      let skipped = 0

      for (const filePath of embeddableFiles) {
        const stateRow = stateByPath.get(filePath) ?? null
        const action = decideScanAction(stateRow, sourcesInQdrant.has(filePath), policy)

        switch (action.kind) {
          case 'skip':
            skipped++
            break
          case 'backfill_indexed':
            // Pre-RFC install (or a fresh admin pointed at an existing Qdrant volume):
            // chunks already exist with no state row, so trust Qdrant and record
            // `indexed` without re-embedding. chunks_embedded is left 0 because
            // we don't count points-per-source during the scroll above.
            await KbIngestState.create({
              file_path: filePath,
              state: 'indexed',
              chunks_embedded: 0,
            })
            backfilled++
            break
          case 'create_pending':
            // Manual mode: record that we've seen the file but don't dispatch.
            // The KB panel surfaces a per-card "Index" affordance for these.
            await KbIngestState.create({
              file_path: filePath,
              state: 'pending_decision',
              chunks_embedded: 0,
            })
            createdPending++
            break
          case 'dispatch':
            if (action.createStateRow) {
              await KbIngestState.create({
                file_path: filePath,
                state: 'pending_decision',
                chunks_embedded: 0,
              })
              createdRows++
            }
            filesToEmbed.push(filePath)
            break
        }
      }

      logger.info(
        `[RAG] Scan results (policy=${policy}): ${filesToEmbed.length} to embed, ${backfilled} backfilled, ${createdRows} new pending, ${createdPending} waiting on user, ${skipped} skipped`
      )

      const withheldNote = withheld
        .map(
          (w) =>
            `; left ${w.count} indexed source${w.count !== 1 ? 's' : ''} under ${relative(process.cwd(), w.root)} untouched because ${
              w.reason === 'empty_root'
                ? 'that folder has no files (is the drive mounted?)'
                : 'removing them would clear most of that folder (is it pointing at the right drive?)'
            }`
        )
        .join('')
      const orphanNote =
        (orphansPurged > 0
          ? `; purged ${orphansPurged} orphaned source${orphansPurged !== 1 ? 's' : ''}`
          : '') + withheldNote

      if (filesToEmbed.length === 0) {
        return {
          success: true,
          message: `Knowledge base is already in sync${orphanNote}`,
          filesScanned: filesInStorage.length,
          filesQueued: 0,
        }
      }

      const { queuedCount, dedupedCount } = await this._dispatchEmbedJobsFor(filesToEmbed)
      const dedupeNote = dedupedCount > 0 ? ` (${dedupedCount} already queued)` : ''
      return {
        success: true,
        message: `Scanned ${filesInStorage.length} files, queued ${queuedCount} for embedding${dedupeNote}${orphanNote}`,
        filesScanned: filesInStorage.length,
        filesQueued: queuedCount,
      }
    } catch (error) {
      logger.error('[RAG] Error scanning and syncing knowledge base:', error)
      return { success: false, message: 'Error scanning and syncing knowledge base' }
    }
  }

  /**
   * Re-embed every file on disk (per-file replace). For each discovered file:
   * delete its existing Qdrant points by `source` match, then dispatch a fresh
   * EmbedFileJob. Files are NOT removed from disk. Any orphan points (points
   * whose source file no longer exists) are intentionally preserved — use
   * resetAndRebuild() if a clean slate is required.
   *
   * Refuses to run if the embeddings queue already has in-flight work.
   */
  public async reembedAll(): Promise<{
    success: boolean
    message: string
    filesScanned?: number
    filesQueued?: number
    failedPaths?: string[]
  }> {
    try {
      if (await this._hasInflightEmbedJobs()) {
        return {
          success: false,
          message:
            'Embed jobs are already in progress. Wait for the queue to drain (or clean up failed jobs) before triggering a bulk re-embed.',
        }
      }

      logger.info('[RAG] Starting full re-embed (per-file replace)')

      await this.discoverNomadDocs(true).catch((error) => {
        logger.error('[RAG] Error re-running Nomad docs discovery during re-embed:', error)
      })

      const filesInStorage = await this._discoverKbFiles()

      await this._ensureCollection(
        RagService.CONTENT_COLLECTION_NAME,
        RagService.EMBEDDING_DIMENSION
      )

      // Per-file: delete-then-dispatch. We tried dispatch-then-delete but that
      // opens a race where a fast worker can write new points before our
      // delete-by-source runs, wiping both. Instead we delete first, then
      // dispatch — and if dispatch fails, we surface the failed paths in the
      // response so the operator knows which files dropped out (rather than
      // silently leaving them unindexed). A subsequent sync rescan picks them
      // back up. Note: a delete-failure aborts the per-file pair (we don't
      // dispatch a job whose old points are still present, since they'd live
      // alongside the new vectors forever).
      const { EmbedFileJob } = await import('#jobs/embed_file_job')
      let queuedCount = 0
      const failedPaths: string[] = []
      for (const filePath of filesInStorage) {
        try {
          await this._deletePointsBySource(filePath)
        } catch (err) {
          logger.error(
            `[RAG] Failed to delete prior points for ${filePath}; skipping dispatch:`,
            err
          )
          failedPaths.push(filePath)
          continue
        }
        try {
          const fileName = filePath.split(/[/\\]/).pop() || filePath
          const stats = await getFileStatsIfExists(filePath)
          const result = await EmbedFileJob.dispatch(
            { filePath, fileName, fileSize: stats?.size },
            { force: true }
          )
          if (result.created) queuedCount++
        } catch (fileError) {
          // Old points already deleted but the new job never made it onto the
          // queue. Logged + surfaced so an operator can rerun a sync.
          logger.error(
            `[RAG] Re-embed dispatch failed for ${filePath} after delete; file is now unindexed until next sync:`,
            fileError
          )
          failedPaths.push(filePath)
        }
      }

      logger.info(
        `[RAG] Re-embed dispatched ${queuedCount}/${filesInStorage.length} files` +
          (failedPaths.length > 0 ? ` (${failedPaths.length} failed)` : '')
      )

      const failureSuffix =
        failedPaths.length > 0
          ? ` ${failedPaths.length} file${failedPaths.length === 1 ? '' : 's'} failed to dispatch and are temporarily unindexed — run a sync rescan to recover.`
          : ''

      return {
        success: failedPaths.length === 0,
        message:
          `Re-embedding ${queuedCount} file${queuedCount === 1 ? '' : 's'}. Existing points were replaced.` +
          failureSuffix,
        filesScanned: filesInStorage.length,
        filesQueued: queuedCount,
        ...(failedPaths.length > 0 ? { failedPaths } : {}),
      }
    } catch (error) {
      logger.error('[RAG] Error during re-embed:', error)
      return { success: false, message: 'Error during re-embed' }
    }
  }

  /**
   * Destructive rebuild. Drops the entire Qdrant collection (wiping every
   * point including orphans), recreates it with the correct dimension, clears
   * the Nomad-docs discovery flag, then dispatches an EmbedFileJob for every
   * file currently on disk.
   *
   * Refuses to run if the embeddings queue already has in-flight work.
   */
  public async resetAndRebuild(): Promise<{
    success: boolean
    message: string
    filesScanned?: number
    filesQueued?: number
    failedPaths?: string[]
  }> {
    try {
      if (await this._hasInflightEmbedJobs()) {
        return {
          success: false,
          message:
            'Embed jobs are already in progress. Wait for the queue to drain (or clean up failed jobs) before triggering a reset.',
        }
      }

      logger.info('[RAG] Starting destructive reset & rebuild')

      await this._initializeQdrantClient()
      try {
        await this.qdrant!.deleteCollection(RagService.CONTENT_COLLECTION_NAME)
        logger.info(`[RAG] Dropped collection ${RagService.CONTENT_COLLECTION_NAME}`)
      } catch (err) {
        // Collection may not exist yet on a fresh install — log and continue.
        logger.warn(`[RAG] deleteCollection failed (may not exist): ${(err as Error).message}`)
      }

      // The collection is gone — drop it from the ensured cache so the
      // _ensureCollection call below actually recreates it
      this.ensuredCollections.delete(RagService.CONTENT_COLLECTION_NAME)

      await this._ensureCollection(
        RagService.CONTENT_COLLECTION_NAME,
        RagService.EMBEDDING_DIMENSION
      )

      // Force Nomad docs to be re-dispatched.
      await KVStore.setValue('rag.docsEmbedded', false)
      await this.discoverNomadDocs(true).catch((error) => {
        logger.error('[RAG] Error re-running Nomad docs discovery after reset:', error)
      })

      const filesInStorage = await this._discoverKbFiles()
      const { queuedCount, failedPaths } = await this._dispatchEmbedJobsFor(filesInStorage, {
        force: true,
      })

      logger.info(
        `[RAG] Reset complete — dispatched ${queuedCount}/${filesInStorage.length} files` +
          (failedPaths.length > 0 ? ` (${failedPaths.length} failed)` : '')
      )

      // Collection was already dropped, so dispatch failures here mean the
      // file is gone from Qdrant with no pending job to repopulate it. Surface
      // the count + paths so the operator can rerun a sync rescan to recover.
      const failureSuffix =
        failedPaths.length > 0
          ? ` ${failedPaths.length} file${failedPaths.length === 1 ? '' : 's'} failed to dispatch and are temporarily unindexed — run a sync rescan to recover.`
          : ''

      return {
        success: failedPaths.length === 0,
        message:
          `Collection wiped. Queued ${queuedCount} file${queuedCount === 1 ? '' : 's'} for a full rebuild.` +
          failureSuffix,
        filesScanned: filesInStorage.length,
        filesQueued: queuedCount,
        ...(failedPaths.length > 0 ? { failedPaths } : {}),
      }
    } catch (error) {
      logger.error('[RAG] Error during reset & rebuild:', error)
      return { success: false, message: 'Error during reset & rebuild' }
    }
  }
}

import { OllamaService } from '#services/ollama_service'
import { inject } from '@adonisjs/core'
import logger from '@adonisjs/core/services/logger'
import KVStore from '#models/kv_store'
import { RELEVANCE_CHECK_MAX_TOKENS, SYSTEM_PROMPTS } from '../../constants/ollama.js'
import type { RetrievedChunk } from '../../types/rag.js'
import {
  buildJudgeInput,
  isRelevanceCheckEnabled,
  ON_TOPIC_SCHEMA,
  pickOnTopic,
} from '../utils/relevance_judge.js'
import { resolveStructured } from '../utils/structured_output.js'
import { resolveTasksModel } from '../utils/tasks_model.js'

export type JudgeResult = {
  /** Every chunk when the model said they fit the question, none when it said not. */
  kept: RetrievedChunk[]
  /** How many were dropped. 0 when the check failed open. */
  rejected: number
  /** False when the call failed and every chunk was kept unjudged. */
  judged: boolean
  ms: number
}

/**
 * Asks a model whether the retrieved chunks are about what the user asked, and
 * drops them all when it says no (#1341). Runs after the relevance floor, so it
 * only ever sees the few chunks that were about to be injected and cited.
 *
 * Fails open by design. The floor has already removed the noise; this removes
 * the coherent-but-off-topic remainder. A timeout or a garbled verdict costing
 * one turn that precision is a much smaller failure than an answerable question
 * losing its context because a model misbehaved.
 */
@inject()
export class RelevanceJudgeService {
  constructor(private ollamaService: OllamaService) {}

  /**
   * The model to run the check on this turn, or null to skip it. Opt-in via
   * `rag.relevanceCheck`; runs on the tasks model when one is configured and on
   * the chat model otherwise.
   */
  async resolveModel(chatModel: string): Promise<string | null> {
    try {
      if (!isRelevanceCheckEnabled(await KVStore.getValue('rag.relevanceCheck'))) return null
    } catch (error) {
      logger.warn(
        `[RAG] Failed to read rag.relevanceCheck, skipping the check: ${error instanceof Error ? error.message : error}`
      )
      return null
    }
    return resolveTasksModel(this.ollamaService, chatModel, undefined, '[RAG]')
  }

  async judge(question: string, chunks: RetrievedChunk[], model: string): Promise<JudgeResult> {
    const started = Date.now()
    const unjudged = (): JudgeResult => ({
      kept: chunks,
      rejected: 0,
      judged: false,
      ms: Date.now() - started,
    })
    if (chunks.length === 0 || !question.trim()) return unjudged()

    try {
      const thinkingCapable = await this.ollamaService.checkModelHasThinking(model)
      const response = await this.ollamaService.chat({
        model,
        messages: [
          { role: 'system', content: SYSTEM_PROMPTS.relevance_check },
          {
            role: 'user',
            content: buildJudgeInput(
              question,
              chunks.map((c) => ({
                text: c.text,
                // Titles only from content metadata. A filename is not a claim
                // about what a passage says, and in the eval corpus it would
                // hand the judge the answer ("distractor-…").
                title:
                  c.metadata?.full_title || c.metadata?.article_title || c.metadata?.archive_title,
              }))
            ),
          },
        ],
        numPredict: RELEVANCE_CHECK_MAX_TOKENS,
        temperature: 0,
        think: false,
        thinkingCapable,
        format: ON_TOPIC_SCHEMA,
      })

      const verdict = resolveStructured(
        response.message.content.trim(),
        pickOnTopic,
        response.structured === true
      )
      if (!verdict.ok) {
        logger.warn(
          `[RAG] Relevance check on "${model}" returned no usable verdict (${verdict.reason}); keeping all chunks`
        )
        return unjudged()
      }

      const ms = Date.now() - started
      logger.debug(
        `[RAG] Relevance check on "${model}": ${verdict.value ? 'on topic' : 'off topic'} (${chunks.length} chunk(s), ${ms}ms)`
      )
      return verdict.value
        ? { kept: chunks, rejected: 0, judged: true, ms }
        : { kept: [], rejected: chunks.length, judged: true, ms }
    } catch (error) {
      logger.warn(
        `[RAG] Relevance check on "${model}" failed, keeping all chunks: ${error instanceof Error ? error.message : error}`
      )
      return unjudged()
    }
  }
}

import Service from '#models/service'
import InstalledResource from '#models/installed_resource'
import { inject } from '@adonisjs/core'
import { DockerService } from '#services/docker_service'
import { ServiceSlim } from '../../types/services.js'
import logger from '@adonisjs/core/services/logger'
import si from 'systeminformation'
import {
  GpuHealthStatus,
  NomadDiskInfo,
  NomadDiskInfoRaw,
  SystemInformationResponse,
} from '../../types/system.js'
import { SERVICE_NAMES } from '../../constants/service_names.js'
import { readFileSync } from 'node:fs'
import { readFile } from 'node:fs/promises'
import path, { join } from 'node:path'
import { getAllFilesystems, getFile } from '../utils/fs.js'
import axios from 'axios'
import env from '#start/env'
import KVStore from '#models/kv_store'
import { KV_STORE_SCHEMA, KVStoreKey } from '../../types/kv_store.js'
import { isNewerVersion } from '../utils/version.js'
import { isUnresolvedGpuModel } from '../utils/gpu_model.js'
import {
  classifyOllamaComputeBackend,
  diagnoseAmdCpuFallback,
  parseOllamaGpuFromLogs,
  readOllamaStartupLogs,
  resolveExpectedGpuVendor,
  type OllamaGpuInfo,
} from '#services/ollama_compute'
import { invalidateAssistantNameCache } from '../../config/inertia.js'
import { invalidateMinRelevanceCache } from '../utils/rag_relevance.js'
import { invalidateResponseStyleCache } from '../utils/response_style.js'
import { KiwixLibraryService } from '#services/kiwix_library_service'

@inject()
export class SystemService {
  private static appVersion: string | null = null
  private static diskInfoFile = '/storage/nomad-disk-info.json'

  constructor(private dockerService: DockerService) {}

  async checkServiceInstalled(serviceName: string): Promise<boolean> {
    const services = await this.getServices({ installedOnly: true })
    return services.some((service) => service.service_name === serviceName)
  }

  async getInternetStatus(): Promise<boolean> {
    // Primary endpoint stays Cloudflare's privacy-respecting utility endpoint.
    // The fallbacks are hosts the application already contacts elsewhere
    // (GitHub API for update checks, the Project NOMAD API for release-note
    // subscriptions), so no new third-party services are introduced. They exist
    // to avoid false "offline" reports on networks that block 1.1.1.1.
    const DEFAULT_TEST_URLS = [
      'https://1.1.1.1/cdn-cgi/trace',
      'https://api.github.com',
      'https://api.projectnomad.us',
    ]
    const MAX_ATTEMPTS = 3

    let testUrls = DEFAULT_TEST_URLS

    // Resolve the test endpoint in priority order: the INTERNET_STATUS_TEST_URL
    // env var always wins (legacy override for operators who intentionally point
    // connectivity checks at a specific endpoint), then the UI-configurable value
    // stored in KVStore, and finally the built-in defaults.
    const envTestUrl = env.get('INTERNET_STATUS_TEST_URL')?.trim()
    const kvTestUrl = (await KVStore.getValue('system.internetStatusTestUrl'))?.trim()
    const customTestUrl = envTestUrl || kvTestUrl

    // If a custom test URL is provided and valid, use it exclusively.
    if (customTestUrl && customTestUrl !== '') {
      try {
        new URL(customTestUrl)
        testUrls = [customTestUrl]
      } catch (error) {
        logger.warn(
          `Invalid internet status test URL: ${customTestUrl}. Falling back to default URLs.`
        )
      }
    }

    for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
      try {
        // Probe all test endpoints in parallel and resolve as soon as the first one
        // responds. Any HTTP response (including non-2xx) means we reached the
        // internet, so accept all status codes rather than requiring a strict 200.
        await Promise.any(
          testUrls.map((testUrl) => {
            logger.debug(`[SystemService] Checking internet connectivity via: ${testUrl}`)
            return axios.get(testUrl, { timeout: 5000, validateStatus: () => true })
          })
        )
        return true
      } catch (error) {
        // Promise.any only rejects (with an AggregateError) when every endpoint failed.
        logger.warn(
          `Internet status check attempt ${attempt}/${MAX_ATTEMPTS} failed: ${error instanceof Error ? error.message : error}`
        )

        if (attempt < MAX_ATTEMPTS) {
          // delay before next attempt
          await new Promise((resolve) => setTimeout(resolve, 1000))
        }
      }
    }

    logger.warn('All internet status check attempts failed.')
    return false
  }

  /**
   * The running nomad_ollama container and its inspect data, or null when it is
   * not running. The inspect data records the GPU config the install actually
   * applied (DeviceRequests, /dev/kfd, the ROCm image), which is what the GPU
   * health check keys on.
   */
  private async _findRunningOllamaContainer() {
    const containers = await this.dockerService.docker.listContainers({ all: false })
    const summary = containers.find((c) => c.Names.includes(`/${SERVICE_NAMES.OLLAMA}`))
    if (!summary) return null
    const container = this.dockerService.docker.getContainer(summary.Id)
    return { container, inspect: await container.inspect() }
  }

  /**
   * Probe Ollama startup logs for the canonical "inference compute" line that records
   * which compute backend was selected. This catches silent CPU fallback (e.g. when
   * /dev/kfd is mounted but ROCm initialization fails, or NVML dies after an update)
   * which the older nvidia-smi exec probe could not detect.
   *
   * Returns the parsed library, GPU model name, and VRAM in MiB, or null when:
   *   - the Ollama container is not running
   *   - the line has not been emitted (Ollama still starting up)
   *   - logs show CPU-only operation (no GPU detected)
   */
  async getOllamaInferenceComputeFromLogs(): Promise<OllamaGpuInfo | null> {
    try {
      const ollama = await this._findRunningOllamaContainer()
      if (!ollama) return null
      return parseOllamaGpuFromLogs(await readOllamaStartupLogs(ollama.container, ollama.inspect))
    } catch (error) {
      logger.warn(
        `[SystemService] Failed to probe Ollama logs for inference compute line: ${error instanceof Error ? error.message : error}`
      )
      return null
    }
  }

  async getNvidiaSmiInfo(): Promise<
    | Array<{ vendor: string; model: string; vram: number }>
    | { error: string }
    | 'OLLAMA_NOT_FOUND'
    | 'BAD_RESPONSE'
    | 'UNKNOWN_ERROR'
  > {
    try {
      const containers = await this.dockerService.docker.listContainers({ all: false })
      const ollamaContainer = containers.find((c) => c.Names.includes(`/${SERVICE_NAMES.OLLAMA}`))
      if (!ollamaContainer) {
        logger.info(
          'Ollama container not found for nvidia-smi info retrieval. This is expected if Ollama is not installed.'
        )
        return 'OLLAMA_NOT_FOUND'
      }

      // Execute nvidia-smi inside the Ollama container to get GPU info
      const container = this.dockerService.docker.getContainer(ollamaContainer.Id)
      const exec = await container.exec({
        Cmd: ['nvidia-smi', '--query-gpu=name,memory.total', '--format=csv,noheader,nounits'],
        AttachStdout: true,
        AttachStderr: true,
        Tty: true,
      })

      // Read the output stream with a timeout to prevent hanging if nvidia-smi fails
      const stream = await exec.start({ Tty: true })
      const output = await new Promise<string>((resolve) => {
        let data = ''
        const timeout = setTimeout(() => resolve(data), 5000)
        stream.on('data', (chunk: Buffer) => {
          data += chunk.toString()
        })
        stream.on('end', () => {
          clearTimeout(timeout)
          resolve(data)
        })
      })

      // Remove any non-printable characters and trim the output
      const cleaned = Array.from(output)
        .filter((character) => character.charCodeAt(0) > 8)
        .join('')
        .trim()
      if (
        cleaned &&
        !cleaned.toLowerCase().includes('error') &&
        !cleaned.toLowerCase().includes('not found')
      ) {
        // Split by newlines to handle multiple GPUs installed
        const lines = cleaned.split('\n').filter((line) => line.trim())

        // Map each line out to a useful structure for us
        const gpus = lines.map((line) => {
          const parts = line.split(',').map((s) => s.trim())
          return {
            vendor: 'NVIDIA',
            model: parts[0] || 'NVIDIA GPU',
            vram: parts[1] ? Number.parseInt(parts[1], 10) : 0,
          }
        })

        return gpus.length > 0 ? gpus : 'BAD_RESPONSE'
      }

      // If we got output but looks like an error, consider it a bad response from nvidia-smi
      return 'BAD_RESPONSE'
    } catch (error) {
      logger.error('Error getting nvidia-smi info:', error)
      if (error instanceof Error && error.message) {
        return { error: error.message }
      }
      return 'UNKNOWN_ERROR'
    }
  }

  async getExternalOllamaGpuInfo(): Promise<Array<{
    vendor: string
    model: string
    vram: number
  }> | null> {
    try {
      // If a remote Ollama URL is configured, use it directly without requiring a local container
      const remoteOllamaUrl = await KVStore.getValue('ai.remoteOllamaUrl')
      if (!remoteOllamaUrl) {
        const containers = await this.dockerService.docker.listContainers({ all: false })
        const ollamaContainer = containers.find((c) => c.Names.includes(`/${SERVICE_NAMES.OLLAMA}`))
        if (!ollamaContainer) {
          return null
        }

        const actualImage = (ollamaContainer.Image || '').toLowerCase()
        if (actualImage.includes('ollama/ollama') || actualImage.startsWith('ollama:')) {
          return null
        }
      }

      const ollamaUrl = remoteOllamaUrl || (await this.dockerService.getServiceURL(SERVICE_NAMES.OLLAMA))
      if (!ollamaUrl) {
        return null
      }

      await axios.get(new URL('/api/tags', ollamaUrl).toString(), { timeout: 3000 })

      let vramMb = 0
      try {
        const psResponse = await axios.get(new URL('/api/ps', ollamaUrl).toString(), {
          timeout: 3000,
        })
        const loadedModels = Array.isArray(psResponse.data?.models) ? psResponse.data.models : []
        const largestAllocation = loadedModels.reduce(
          (max: number, model: { size_vram?: number | string }) =>
            Math.max(max, Number(model.size_vram) || 0),
          0
        )
        vramMb = largestAllocation > 0 ? Math.round(largestAllocation / (1024 * 1024)) : 0
      } catch {}

      return [
        {
          vendor: 'NVIDIA',
          model: 'NVIDIA GPU (external Ollama)',
          vram: vramMb,
        },
      ]
    } catch (error) {
      logger.info(
        `[SystemService] External Ollama GPU probe failed: ${error instanceof Error ? error.message : error}`
      )
      return null
    }
  }

  async getServices({ installedOnly = true }: { installedOnly?: boolean }): Promise<ServiceSlim[]> {
    const statuses = await this._syncContainersWithDatabase() // Sync and reuse the fetched status list

    const query = Service.query()
      .orderBy('display_order', 'asc')
      .orderBy('friendly_name', 'asc')
      .select(
        'id',
        'service_name',
        'installed',
        'installation_status',
        'ui_location',
        'custom_url',
        'friendly_name',
        'description',
        'icon',
        'powered_by',
        'display_order',
        'container_image',
        'available_update_version',
        'auto_update_enabled',
        'is_custom',
        'is_user_modified',
        'is_deprecated',
        'is_link_tile',
        'link_color',
        'category'
      )
      .where('is_dependency_service', false)
      // Deprecated/sunset apps stay visible only while still installed, so the user can manage and
      // uninstall them — they never reappear in the install catalog once removed.
      .where((q) => {
        q.where('is_deprecated', false).orWhere('installed', true)
      })
    if (installedOnly) {
      query.where('installed', true)
    }

    const services = await query
    if (!services || services.length === 0) {
      return []
    }

    const toReturn: ServiceSlim[] = []

    for (const service of services) {
      const status = statuses.find((s) => s.service_name === service.service_name)
      toReturn.push({
        id: service.id,
        service_name: service.service_name,
        friendly_name: service.friendly_name,
        description: service.description,
        icon: service.icon,
        installed: service.installed,
        installation_status: service.installation_status,
        status: status ? status.status : 'unknown',
        ui_location: service.ui_location || '',
        custom_url: service.custom_url,
        powered_by: service.powered_by,
        display_order: service.display_order,
        container_image: service.container_image,
        available_update_version: service.available_update_version,
        auto_update_enabled: service.auto_update_enabled,
        is_custom: service.is_custom,
        is_user_modified: service.is_user_modified,
        is_deprecated: service.is_deprecated,
        is_link_tile: service.is_link_tile,
        link_color: service.link_color,
        category: service.category,
      })
    }

    return toReturn
  }

  static getAppVersion(): string {
    try {
      if (this.appVersion) {
        return this.appVersion
      }

      // Return 'dev' for development environment (version.json won't exist)
      if (process.env.NODE_ENV === 'development') {
        this.appVersion = 'dev'
        return 'dev'
      }

      const packageJson = readFileSync(join(process.cwd(), 'version.json'), 'utf-8')
      const packageData = JSON.parse(packageJson)

      const version = packageData.version || '0.0.0'

      this.appVersion = version
      return version
    } catch (error) {
      logger.error('Error getting app version:', error)
      return '0.0.0'
    }
  }

  async getSystemInfo(): Promise<SystemInformationResponse | undefined> {
    try {
      const [cpu, mem, os, currentLoad, fsSize, uptime, graphics] = await Promise.all([
        si.cpu(),
        si.mem(),
        si.osInfo(),
        si.currentLoad(),
        si.fsSize(),
        si.time(),
        si.graphics(),
      ])

      let diskInfo: NomadDiskInfoRaw | undefined
      let disk: NomadDiskInfo[] = []

      try {
        const diskInfoRawString = await getFile(
          path.join(process.cwd(), SystemService.diskInfoFile),
          'string'
        )

        diskInfo = (
          diskInfoRawString
            ? JSON.parse(diskInfoRawString.toString())
            : { diskLayout: { blockdevices: [] }, fsSize: [] }
        ) as NomadDiskInfoRaw

        disk = this.calculateDiskUsage(diskInfo)
      } catch (error) {
        logger.error('Error reading disk info file:', error)
      }

      // GPU health tracking — detect when host has a GPU runtime but Ollama can't access it.
      // Primary probe: parse Ollama's "inference compute" startup log line for both NVIDIA
      // and AMD. Secondary probe (NVIDIA only): nvidia-smi exec, retained as a fallback for
      // hardware enrichment when log parsing has not yet captured a startup line.
      let gpuHealth: GpuHealthStatus = {
        status: 'no_gpu',
        hasNvidiaRuntime: false,
        hasRocmRuntime: false,
        ollamaGpuAccessible: false,
      }

      // Query Docker API for host-level info (hostname, OS, GPU runtime)
      // si.osInfo() returns the container's info inside Docker, not the host's
      try {
        const dockerInfo = await this.dockerService.docker.info()

        if (dockerInfo.Name) {
          os.hostname = dockerInfo.Name
        }
        if (dockerInfo.OperatingSystem) {
          os.distro = dockerInfo.OperatingSystem
        }
        if (dockerInfo.KernelVersion) {
          os.kernel = dockerInfo.KernelVersion
        }

        // si.graphics() in the admin container uses lspci (pciutils ships in
        // the image for AMD detection). lspci has no real VRAM info for
        // discrete GPUs, so systeminformation parses the first PCI memory
        // Region (BAR0, typically 1-32 MiB) as `vram`. nvidia-smi / ROCm
        // tooling enrichment also can't run since neither is in the admin
        // image. No real dGPU has under 256 MiB, so any discrete-GPU controller
        // below that threshold needs the probes below to give us real data.
        // Applies to both NVIDIA and AMD; Intel iGPUs are exempt because their
        // shared-system-memory VRAM reading via lspci can legitimately be small.
        const DGPU_BOGUS_VRAM_THRESHOLD_MIB = 256
        const isDiscreteGpuVendor = (vendor: string) =>
          /nvidia|advanced micro devices|amd|ati/i.test(vendor)
        const isBogusDgpuVram = (c: { vendor?: string; vram?: number | null }) =>
          isDiscreteGpuVendor(c.vendor || '') &&
          typeof c.vram === 'number' &&
          c.vram < DGPU_BOGUS_VRAM_THRESHOLD_MIB

        // Clear the bogus value up front. If a probe replaces the entry below
        // we get the real VRAM; if no probe succeeds (Ollama not installed,
        // passthrough_failed) the UI falls back to "N/A" instead of showing
        // "1 MB" / "32 MB". The lspci model/vendor strings stay since they're
        // still useful for identifying the card.
        const hasLspciBogusDgpuVram = (graphics.controllers || []).some(isBogusDgpuVram)
        if (hasLspciBogusDgpuVram) {
          for (const c of graphics.controllers) {
            if (isBogusDgpuVram(c)) c.vram = null
          }
        }

        // The same pci.ids staleness that produces bogus VRAM also produces a
        // placeholder model name — a card newer than the container's pci.ids is
        // reported as its raw id, e.g. "Device 2d05" for an RTX 5060 (#1165).
        //
        // These are independent symptoms, not one. lspci can hand back a
        // perfectly plausible BAR0 reading alongside an unresolved name, and in
        // that case nothing above fires, no probe runs, and Settings > System
        // renders the raw PCI id as the GPU model (#1196). NVIDIA usually hides
        // this because the nvidia-smi path tends to be reached for other
        // reasons; AMD has no equivalent, so it shows the raw id.
        //
        // The probes below resolve a real name from Ollama's own startup log,
        // so trigger them on an unresolved name too rather than only on VRAM.
        const hasUnresolvedGpuName = (graphics.controllers || []).some((c) =>
          isUnresolvedGpuModel(c.model || '')
        )

        // Run the probes when controllers are empty (common inside Docker),
        // when lspci gave us bogus discrete-GPU BAR0 values that need replacing,
        // or when it named a card it couldn't resolve. Only in those cases do
        // probe results replace the lspci controllers; a clean lspci reading
        // stays as the display source.
        const lspciNeedsProbe =
          !graphics.controllers ||
          graphics.controllers.length === 0 ||
          hasLspciBogusDgpuVram ||
          hasUnresolvedGpuName
        const useProbeControllers = (controllers: typeof graphics.controllers) => {
          if (lspciNeedsProbe) graphics.controllers = controllers
        }
        const toControllers = (gpus: Array<{ vendor: string; model: string; vram: number }>) =>
          gpus.map((gpu) => ({
            model: gpu.model,
            vendor: gpu.vendor,
            bus: '',
            vram: gpu.vram,
            vramDynamic: false,
          }))

        // Runtime flags are reported whichever path runs below. They used to be set
        // only inside the probe branch, so a box whose lspci reading looked clean
        // reported hasRocmRuntime: false even with an AMD GPU configured (#1344).
        const runtimes = dockerInfo.Runtimes || {}
        gpuHealth.hasNvidiaRuntime = 'nvidia' in runtimes

        // AMD doesn't register a Docker runtime. Detection sources, in priority order:
        //   1. KV 'gpu.type' (set by DockerService._detectGPUType after first Ollama install)
        //   2. Marker file at /app/storage/.nomad-gpu-type (written by install_nomad.sh)
        // The marker file matters because the System page should reflect AMD presence
        // even before AI Assistant has been installed for the first time.
        let savedGpuType: string | null | undefined = await KVStore.getValue('gpu.type') as string | undefined
        if (!savedGpuType) {
          try {
            savedGpuType = (await readFile('/app/storage/.nomad-gpu-type', 'utf8')).trim()
          } catch {}
        }
        const amdEnabledRaw = await KVStore.getValue('ai.amdGpuAcceleration')
        const amdAccelerationEnabled = String(amdEnabledRaw) !== 'false'
        gpuHealth.hasRocmRuntime = savedGpuType === 'amd' && amdAccelerationEnabled

        // When Ollama is expected on a GPU, its startup log decides health whatever
        // lspci returned. A clean lspci reading says a GPU exists, not that Ollama
        // uses it: an AMD iGPU silently on CPU used to land in the else branch below
        // and report 'ok' (#1344).
        const ollama = await this._findRunningOllamaContainer().catch(() => null)
        const expectedVendor = resolveExpectedGpuVendor({
          hasNvidiaRuntime: gpuHealth.hasNvidiaRuntime,
          amdConfigured: gpuHealth.hasRocmRuntime,
          container: ollama?.inspect ?? null,
        })

        if (expectedVendor || lspciNeedsProbe) {
          if (expectedVendor) {
            gpuHealth.gpuVendor = expectedVendor

            // Primary probe: Ollama log parsing — works for both vendors and catches silent fallback
            const ollamaLogs = ollama
              ? await readOllamaStartupLogs(ollama.container, ollama.inspect)
              : ''
            const logInfo = parseOllamaGpuFromLogs(ollamaLogs)
            if (logInfo) {
              useProbeControllers([
                {
                  model: logInfo.name,
                  vendor:
                    logInfo.library === 'CUDA' ? 'NVIDIA' : logInfo.library === 'ROCm' ? 'AMD' : '',
                  bus: '',
                  vram: logInfo.vramMiB,
                  vramDynamic: false,
                },
              ])
              gpuHealth.status = 'ok'
              gpuHealth.ollamaGpuAccessible = true
            } else if (classifyOllamaComputeBackend(ollamaLogs) === 'cpu') {
              // Ollama reported its devices and none was a GPU. Definitive for both
              // vendors, so skip the nvidia-smi exec, which cannot run in a CPU-only
              // container anyway.
              gpuHealth.status = 'passthrough_failed'
              logger.warn(
                `${expectedVendor === 'amd' ? 'AMD' : 'NVIDIA'} GPU expected but Ollama reported a CPU-only backend at startup`
              )
            } else if (expectedVendor === 'nvidia') {
              // NVIDIA secondary path: nvidia-smi exec preserves prior behavior when
              // the log parser hasn't seen a startup line yet (e.g. log rotation,
              // very fresh container). Distinguishes "no Ollama container" from
              // "container exists but GPU broken".
              const nvidiaInfo = await this.getNvidiaSmiInfo()
              if (Array.isArray(nvidiaInfo)) {
                useProbeControllers(toControllers(nvidiaInfo))
                gpuHealth.status = 'ok'
                gpuHealth.ollamaGpuAccessible = true
              } else {
                const externalOllamaGpu = await this.getExternalOllamaGpuInfo()
                if (externalOllamaGpu) {
                  useProbeControllers(toControllers(externalOllamaGpu))
                  gpuHealth.status = 'ok'
                  gpuHealth.ollamaGpuAccessible = true
                } else if (nvidiaInfo === 'OLLAMA_NOT_FOUND') {
                  gpuHealth.status = 'ollama_not_installed'
                } else {
                  gpuHealth.status = 'passthrough_failed'
                  logger.warn(
                    `NVIDIA runtime detected but GPU passthrough failed: ${typeof nvidiaInfo === 'string' ? nvidiaInfo : JSON.stringify(nvidiaInfo)}`
                  )
                }
              }
            } else if (!ollama) {
              // AMD path: no nvidia-smi equivalent worth running — log parser is authoritative.
              // Distinguish "Ollama not running" from "Ollama running but no GPU log line".
              const externalOllamaGpu = await this.getExternalOllamaGpuInfo()
              if (externalOllamaGpu) {
                useProbeControllers(toControllers(externalOllamaGpu))
                gpuHealth.status = 'ok'
                gpuHealth.ollamaGpuAccessible = true
              } else {
                gpuHealth.status = 'ollama_not_installed'
              }
            } else {
              gpuHealth.status = 'passthrough_failed'
              logger.warn(
                'AMD GPU detected but Ollama logs show no ROCm initialization — passthrough or HSA override may have failed'
              )
            }

            // Tell the UI whether a reinstall would help or an HSA override is needed.
            // Reinstalling an AMD container whose config already matches rebuilds the
            // same CPU-bound container, so the banner must not offer that as the fix.
            if (gpuHealth.status === 'passthrough_failed' && expectedVendor === 'amd' && ollama) {
              Object.assign(
                gpuHealth,
                diagnoseAmdCpuFallback(
                  ollama.inspect,
                  ollamaLogs,
                  // Pass the container env so the diff matches what a reinstall would
                  // really build, including an override it keeps from the container (#1377).
                  await this.dockerService.getAmdHsaOverride({
                    quiet: true,
                    containerEnv: ollama.inspect.Config?.Env,
                  })
                )
              )
            }
          }
        } else {
          // si.graphics() returned usable controllers and no GPU runtime is expected
          // (host install, not Docker). Still unprobed, see #1325.
          gpuHealth.status = 'ok'
          gpuHealth.ollamaGpuAccessible = true
        }
      } catch {
        // Docker info query failed, skip host-level enrichment
      }

      return {
        cpu,
        mem,
        os,
        disk,
        currentLoad,
        fsSize,
        uptime,
        graphics,
        gpuHealth,
      }
    } catch (error) {
      logger.error('Error getting system info:', error)
      return undefined
    }
  }

  async checkLatestVersion(force?: boolean): Promise<{
    success: boolean
    updateAvailable: boolean
    currentVersion: string
    latestVersion: string
    message?: string
  }> {
    try {
      const currentVersion = SystemService.getAppVersion()
      const cachedUpdateAvailable = await KVStore.getValue('system.updateAvailable')
      const cachedLatestVersion = await KVStore.getValue('system.latestVersion')

      // Use cached values if not forcing a fresh check.
      // the CheckUpdateJob will update these values every 12 hours
      if (!force) {
        return {
          success: true,
          updateAvailable: cachedUpdateAvailable ?? false,
          currentVersion,
          latestVersion: cachedLatestVersion || '',
        }
      }

      const earlyAccess = (await KVStore.getValue('system.earlyAccess')) ?? false

      let latestVersion: string
      if (earlyAccess) {
        const response = await axios.get(
          'https://api.github.com/repos/Crosstalk-Solutions/project-nomad/releases',
          { headers: { Accept: 'application/vnd.github+json' }, timeout: 5000 }
        )
        if (!response?.data?.length) throw new Error('No releases found')
        latestVersion = response.data[0].tag_name.replace(/^v/, '').trim()
      } else {
        const response = await axios.get(
          'https://api.github.com/repos/Crosstalk-Solutions/project-nomad/releases/latest',
          { headers: { Accept: 'application/vnd.github+json' }, timeout: 5000 }
        )
        if (!response?.data?.tag_name) throw new Error('Invalid response from GitHub API')
        latestVersion = response.data.tag_name.replace(/^v/, '').trim()
      }

      logger.info(`Current version: ${currentVersion}, Latest version: ${latestVersion}`)

      const updateAvailable =
        process.env.NODE_ENV === 'development'
          ? false
          : isNewerVersion(latestVersion, currentVersion.trim(), earlyAccess)

      // Cache the results in KVStore for frontend checks
      await KVStore.setValue('system.updateAvailable', updateAvailable)
      await KVStore.setValue('system.latestVersion', latestVersion)

      return {
        success: true,
        updateAvailable,
        currentVersion,
        latestVersion,
      }
    } catch (error) {
      logger.error('Error checking latest version:', error)
      return {
        success: false,
        updateAvailable: false,
        currentVersion: '',
        latestVersion: '',
        message: `Failed to check latest version: ${error instanceof Error ? error.message : error}`,
      }
    }
  }

  async subscribeToReleaseNotes(email: string): Promise<{ success: boolean; message: string }> {
    try {
      const response = await axios.post(
        'https://api.projectnomad.us/api/v1/lists/release-notes/subscribe',
        { email },
        { timeout: 5000 }
      )

      if (response.status === 200) {
        return {
          success: true,
          message: 'Successfully subscribed to release notes',
        }
      }

      return {
        success: false,
        message: `Failed to subscribe: ${response.statusText}`,
      }
    } catch (error) {
      logger.error('Error subscribing to release notes:', error)
      return {
        success: false,
        message: `Failed to subscribe: ${error instanceof Error ? error.message : error}`,
      }
    }
  }

  async getDebugInfo(): Promise<string> {
    const appVersion = SystemService.getAppVersion()
    const environment = process.env.NODE_ENV || 'unknown'

    const [systemInfo, services, internetStatus, versionCheck] = await Promise.all([
      this.getSystemInfo(),
      this.getServices({ installedOnly: false }),
      this.getInternetStatus().catch(() => null),
      this.checkLatestVersion().catch(() => null),
    ])

    // Diagnostics tied to common support cases: storage relocation (#1050),
    // container/updater issues (#858), GPU passthrough (#755/#878), and the
    // auto-update trilogy. All best-effort so a single failure never blanks the
    // whole bundle.
    const [dockerVersion, hostStorageRoot, kiwixBookCount, gpuType] = await Promise.all([
      this.dockerService.docker
        .version()
        .then((v: any) => v?.Version ?? null)
        .catch(() => null),
      this.dockerService.getHostStorageRoot().catch(() => null),
      new KiwixLibraryService().getBookCount().catch(() => null),
      KVStore.getValue('gpu.type').catch(() => null),
    ])
    const [autoUpdateCore, autoUpdateApps, autoUpdateContent, autoDisabledReason] =
      await Promise.all([
        KVStore.getValue('autoUpdate.enabled').catch(() => null),
        KVStore.getValue('appAutoUpdate.enabled').catch(() => null),
        KVStore.getValue('contentAutoUpdate.enabled').catch(() => null),
        KVStore.getValue('autoUpdate.autoDisabledReason').catch(() => null),
      ])
    const isEnabled = (v: any) => v === true || v === 'true'

    const lines: string[] = [
      'Project NOMAD Debug Info',
      '========================',
      `App Version: ${appVersion}`,
      `Environment: ${environment}`,
    ]

    if (systemInfo) {
      const { cpu, mem, os, disk, fsSize, uptime, graphics, gpuHealth } = systemInfo

      lines.push('')
      lines.push('System:')
      if (os.distro) lines.push(`  OS: ${os.distro}`)
      if (os.hostname) lines.push(`  Hostname: ${os.hostname}`)
      if (os.kernel) lines.push(`  Kernel: ${os.kernel}`)
      if (os.arch) lines.push(`  Architecture: ${os.arch}`)
      if (dockerVersion) lines.push(`  Docker Engine: ${dockerVersion}`)
      if (uptime?.uptime) lines.push(`  Uptime: ${this._formatUptime(uptime.uptime)}`)

      lines.push('')
      lines.push('Hardware:')
      if (cpu.brand) {
        lines.push(`  CPU: ${cpu.brand} (${cpu.cores} cores)`)
      }
      if (mem.total) {
        const total = this._formatBytes(mem.total)
        const used = this._formatBytes(mem.total - (mem.available || 0))
        const available = this._formatBytes(mem.available || 0)
        lines.push(`  RAM: ${total} total, ${used} used, ${available} available`)
      }
      if (graphics.controllers && graphics.controllers.length > 0) {
        for (const gpu of graphics.controllers) {
          const vram = gpu.vram ? ` (${gpu.vram} MB VRAM)` : ''
          lines.push(`  GPU: ${gpu.model}${vram}`)
        }
      } else {
        lines.push('  GPU: None detected')
      }
      if (gpuHealth?.status) {
        const vendor = gpuType || gpuHealth.gpuVendor
        lines.push(`  GPU Passthrough: ${gpuHealth.status}${vendor ? ` (${vendor})` : ''}`)
      }

      // Disk info — try disk array first, fall back to fsSize
      const diskEntries = disk.filter((d) => d.totalSize > 0)
      if (diskEntries.length > 0) {
        for (const d of diskEntries) {
          const size = this._formatBytes(d.totalSize)
          const type = d.tran?.toUpperCase() || (d.rota ? 'HDD' : 'SSD')
          lines.push(`  Disk: ${size}, ${Math.round(d.percentUsed)}% used, ${type}`)
        }
      } else if (fsSize.length > 0) {
        const realFs = fsSize.filter((f) => f.fs.startsWith('/dev/'))
        const seen = new Set<number>()
        for (const f of realFs) {
          if (seen.has(f.size)) continue
          seen.add(f.size)
          lines.push(`  Disk: ${this._formatBytes(f.size)}, ${Math.round(f.use)}% used`)
        }
      }
    }

    lines.push('')
    lines.push('Storage:')
    lines.push(`  Host storage root: ${hostStorageRoot ?? 'unknown'}`)
    lines.push(`  Container path: ${DockerService.ADMIN_STORAGE_DEST}`)
    const storageEnv = process.env.NOMAD_STORAGE_PATH
    lines.push(
      `  NOMAD_STORAGE_PATH: ${storageEnv ? storageEnv : 'not set (auto-detected from admin mount)'}`
    )
    if (kiwixBookCount !== null) {
      lines.push(
        `  Kiwix library: ${kiwixBookCount === 0 ? 'empty (0 books)' : `${kiwixBookCount} book(s)`}`
      )
    }

    const installed = services.filter((s) => s.installed)
    lines.push('')
    if (installed.length > 0) {
      lines.push('Installed Services:')
      for (const svc of installed) {
        lines.push(`  ${svc.friendly_name} (${svc.service_name}): ${svc.status}`)
      }
    } else {
      lines.push('Installed Services: None')
    }

    if (internetStatus !== null) {
      lines.push('')
      lines.push(`Internet Status: ${internetStatus ? 'Online' : 'Offline'}`)
    }

    if (versionCheck?.success) {
      const updateMsg = versionCheck.updateAvailable
        ? `Yes (${versionCheck.latestVersion} available)`
        : `No (${versionCheck.currentVersion} is latest)`
      lines.push(`Update Available: ${updateMsg}`)
    }

    lines.push('')
    lines.push('Auto-Update:')
    lines.push(`  Core: ${isEnabled(autoUpdateCore) ? 'Enabled' : 'Disabled'}`)
    lines.push(`  Apps: ${isEnabled(autoUpdateApps) ? 'Enabled' : 'Disabled'}`)
    lines.push(`  Content: ${isEnabled(autoUpdateContent) ? 'Enabled' : 'Disabled'}`)
    if (autoDisabledReason) {
      lines.push(`  Auto-disabled reason: ${autoDisabledReason}`)
    }

    return lines.join('\n')
  }

  private _formatUptime(seconds: number): string {
    const days = Math.floor(seconds / 86400)
    const hours = Math.floor((seconds % 86400) / 3600)
    const minutes = Math.floor((seconds % 3600) / 60)
    if (days > 0) return `${days}d ${hours}h ${minutes}m`
    if (hours > 0) return `${hours}h ${minutes}m`
    return `${minutes}m`
  }

  private _formatBytes(bytes: number, decimals = 1): string {
    if (bytes === 0) return '0 Bytes'
    const k = 1024
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB']
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return Number.parseFloat((bytes / Math.pow(k, i)).toFixed(decimals)) + ' ' + sizes[i]
  }

  async updateSetting(key: KVStoreKey, value: any): Promise<void> {
    if (
      (value === '' || value === undefined || value === null) &&
      KV_STORE_SCHEMA[key] === 'string'
    ) {
      await KVStore.clearValue(key)
    } else {
      await KVStore.setValue(key, value)
    }
    if (key === 'ai.assistantCustomName') {
      invalidateAssistantNameCache()
    }
    if (key === 'rag.minRelevance') {
      invalidateMinRelevanceCache()
    }
    if (key === 'ai.responseStyle') {
      invalidateResponseStyleCache()
    }
    // Re-enabling auto-update after a backoff-driven auto-disable clears the
    // failure state so it gets a fresh start instead of immediately re-tripping.
    if (key === 'autoUpdate.enabled' && (value === true || value === 'true')) {
      await KVStore.setValue('autoUpdate.consecutiveFailures', '0')
      await KVStore.clearValue('autoUpdate.autoDisabledReason')
    }
    // Re-enabling the global app auto-update master switch clears every app's
    // per-app failure backoff so previously self-disabled apps get a fresh start.
    if (key === 'appAutoUpdate.enabled' && (value === true || value === 'true')) {
      await Service.query().update({
        auto_update_consecutive_failures: 0,
        auto_update_disabled_reason: null,
      })
    }
    // Re-enabling content auto-update clears the feature-level backoff and every
    // resource's per-resource backoff so previously self-disabled content gets a
    // fresh start.
    if (key === 'contentAutoUpdate.enabled' && (value === true || value === 'true')) {
      await KVStore.setValue('contentAutoUpdate.consecutiveFailures', '0')
      await KVStore.clearValue('contentAutoUpdate.autoDisabledReason')
      await InstalledResource.query().update({
        auto_update_consecutive_failures: 0,
        auto_update_disabled_reason: null,
      })
    }
  }

  /**
   * Checks the current state of Docker containers against the database records and updates the database accordingly.
   * It will mark services as not installed if their corresponding containers do not exist, regardless of their running state.
   * Handles cases where a container might have been manually removed, ensuring the database reflects the actual existence of containers.
   * Containers that exist but are stopped, paused, or restarting will still be considered installed.
   * Returns the fetched service status list so callers can reuse it without a second Docker API call.
   */
  private async _syncContainersWithDatabase(): Promise<{ service_name: string; status: string }[]> {
    try {
      const allServices = await Service.all()
      const serviceStatusList = await this.dockerService.getServicesStatus()

      for (const service of allServices) {
        // Link tiles are shortcuts with no container behind them, so container
        // reconciliation does not apply: they are always "installed" in the only
        // sense that matters, which is that the dashboard should show them.
        // Without this they are marked not-installed on the next sync and vanish.
        if (service.is_link_tile) continue

        const containerExists = serviceStatusList.find(
          (s) => s.service_name === service.service_name
        )

        if (service.installed) {
          // If marked as installed but container doesn't exist, mark as not installed
          if (!containerExists) {
            // Exception: remote Ollama is configured without a local container — don't reset it
            if (service.service_name === SERVICE_NAMES.OLLAMA) {
              const remoteUrl = await KVStore.getValue('ai.remoteOllamaUrl')
              if (remoteUrl) continue
            }
            logger.warn(
              `Service ${service.service_name} is marked as installed but container does not exist. Marking as not installed.`
            )
            service.installed = false
            service.installation_status = 'idle'
            await service.save()
          }
        } else {
          // If marked as not installed but container exists (any state), mark as installed
          if (containerExists) {
            logger.warn(
              `Service ${service.service_name} is marked as not installed but container exists. Marking as installed.`
            )
            service.installed = true
            service.installation_status = 'idle'
            await service.save()
          }
        }
      }

      return serviceStatusList
    } catch (error) {
      logger.error('Error syncing containers with database:', error)
      return []
    }
  }

  private calculateDiskUsage(diskInfo: NomadDiskInfoRaw): NomadDiskInfo[] {
    const { diskLayout, fsSize } = diskInfo

    if (!diskLayout?.blockdevices || !fsSize) {
      return []
    }

    // Deduplicate: same device path mounted in multiple places (Docker bind-mounts)
    // Keep the entry with the largest size — that's the real partition
    const deduped = new Map<string, NomadDiskInfoRaw['fsSize'][0]>()
    for (const entry of fsSize) {
      const existing = deduped.get(entry.fs)
      if (!existing || entry.size > existing.size) {
        deduped.set(entry.fs, entry)
      }
    }
    const dedupedFsSize = Array.from(deduped.values())

    return diskLayout.blockdevices
      .filter((disk) => disk.type === 'disk') // Only physical disks
      .map((disk) => {
        const filesystems = getAllFilesystems(disk, dedupedFsSize)

        // Across all partitions
        const totalUsed = filesystems.reduce((sum, p) => sum + (p.used || 0), 0)
        const totalSize = filesystems.reduce((sum, p) => sum + (p.size || 0), 0)
        const percentUsed = totalSize > 0 ? (totalUsed / totalSize) * 100 : 0

        return {
          name: disk.name,
          model: disk.model || 'Unknown',
          vendor: disk.vendor || '',
          rota: disk.rota || false,
          tran: disk.tran || '',
          size: disk.size,
          totalUsed,
          totalSize,
          percentUsed: Math.round(percentUsed * 100) / 100,
          filesystems: filesystems.map((p) => ({
            fs: p.fs,
            mount: p.mount,
            used: p.used,
            size: p.size,
            percentUsed: p.use,
          })),
        }
      })
  }

  /**
   * Check whether the host has enough free memory and disk to comfortably run an app.
   * Returns an array of human-readable warning strings; an empty array means no concerns.
   * These are advisory only — the caller decides whether to block or warn.
   */
  async checkResourceWarnings(minMemoryMB: number, minDiskMB: number): Promise<string[]> {
    const warnings: string[] = []

    try {
      const mem = await si.mem()
      const availableMB = Math.floor(mem.available / 1024 / 1024)
      if (availableMB < minMemoryMB) {
        warnings.push(
          `Low memory: ${availableMB} MB available, this app recommends at least ${minMemoryMB} MB free.`
        )
      }
    } catch (err: any) {
      logger.warn(`[SystemService] checkResourceWarnings mem check failed: ${err.message}`)
    }

    try {
      const storagePath = env.get('NOMAD_STORAGE_PATH', '/opt/project-nomad/storage')
      const fsSizes = await si.fsSize()
      // Find the filesystem whose mount point is the longest prefix of storagePath
      const fs = fsSizes
        .filter((f) => storagePath.startsWith(f.mount))
        .sort((a, b) => b.mount.length - a.mount.length)[0]

      if (fs) {
        const availableDiskMB = Math.floor((fs.size - fs.used) / 1024 / 1024)
        if (availableDiskMB < minDiskMB) {
          warnings.push(
            `Low disk space: ${availableDiskMB} MB available on ${fs.mount}, this app recommends at least ${minDiskMB} MB free.`
          )
        }
      }
    } catch (err: any) {
      logger.warn(`[SystemService] checkResourceWarnings disk check failed: ${err.message}`)
    }

    return warnings
  }

  /**
   * Return the next suggested host port for a custom app in the 8600+ range.
   * Looks at existing custom service records and all Docker container port bindings.
   */
  async getNextSuggestedCustomPort(): Promise<number> {
    const CUSTOM_PORT_START = 8600
    const occupied = new Set<number>()

    try {
      // Ports used by existing custom services in the DB
      const customServices = await Service.query().where('is_custom', true)
      for (const svc of customServices) {
        const config = svc.container_config ? JSON.parse(svc.container_config) : null
        const bindings = config?.HostConfig?.PortBindings ?? {}
        for (const binding of Object.values(bindings) as any[]) {
          const port = parseInt(binding?.[0]?.HostPort, 10)
          if (!isNaN(port)) occupied.add(port)
        }
      }

      // Ports used by any running Docker container in the 8600+ range
      const containers = await this.dockerService.docker.listContainers({ all: true })
      for (const c of containers) {
        for (const p of c.Ports) {
          if (p.PublicPort && p.PublicPort >= CUSTOM_PORT_START) occupied.add(p.PublicPort)
        }
      }
    } catch (err: any) {
      logger.warn(`[SystemService] getNextSuggestedCustomPort probe failed: ${err.message}`)
    }

    let candidate = CUSTOM_PORT_START
    while (occupied.has(candidate)) candidate += 10
    return candidate
  }
}

import logger from '@adonisjs/core/services/logger'
import { readFileSync, existsSync } from 'fs'
import { writeFile } from 'fs/promises'
import { join } from 'path'
import KVStore from '#models/kv_store'

interface UpdateStatus {
  stage: 'idle' | 'starting' | 'pulling' | 'pulled' | 'recreating' | 'complete' | 'error'
  progress: number
  message: string
  timestamp: string
}

export class SystemUpdateService {
  private static SHARED_DIR = '/app/update-shared'
  private static REQUEST_FILE = join(SystemUpdateService.SHARED_DIR, 'update-request')
  private static STATUS_FILE = join(SystemUpdateService.SHARED_DIR, 'update-status')
  private static LOG_FILE = join(SystemUpdateService.SHARED_DIR, 'update-log')

  /**
   * Requests a system update by creating a request file that the sidecar will detect.
   *
   * @param options.targetTag - Explicit Docker image tag to install (e.g. "v1.33.2").
   *   When omitted, falls back to the cached `system.latestVersion` (manual-update
   *   behavior). Auto-update passes an eligibility-vetted tag here, which may differ
   *   from `system.latestVersion` when the newest release is a major bump.
   * @param options.requester - Identifier recorded in the request file for auditing.
   */
  async requestUpdate(options?: {
    targetTag?: string
    requester?: string
  }): Promise<{ success: boolean; message: string }> {
    try {
      const currentStatus = this.getUpdateStatus()
      if (currentStatus && !['idle', 'complete', 'error'].includes(currentStatus.stage)) {
        return {
          success: false,
          message: `Update already in progress (stage: ${currentStatus.stage})`,
        }
      }

      // Determine the Docker image tag to install. Prefer an explicit caller-supplied
      // tag; otherwise use the cached latest version.
      let targetTag = options?.targetTag
      if (!targetTag) {
        const latestVersion = await KVStore.getValue('system.latestVersion')
        targetTag = latestVersion ? `v${latestVersion}` : 'latest'
      }

      const requestData = {
        requested_at: new Date().toISOString(),
        requester: options?.requester ?? 'admin-api',
        target_tag: targetTag,
      }

      await writeFile(SystemUpdateService.REQUEST_FILE, JSON.stringify(requestData, null, 2))
      logger.info(`[SystemUpdateService]: System update requested (target tag: ${requestData.target_tag}) - sidecar will process shortly`)

      return {
        success: true,
        message: 'System update initiated. The admin container will restart during the process.',
      }
    } catch (error) {
      logger.error({ err: error }, '[SystemUpdateService] Failed to request system update')
      return {
        success: false,
        message: 'Failed to request system update. Check server logs for details.',
      }
    }
  }

  getUpdateStatus(): UpdateStatus | null {
    try {
      if (!existsSync(SystemUpdateService.STATUS_FILE)) {
        return {
          stage: 'idle',
          progress: 0,
          message: 'No update in progress',
          timestamp: new Date().toISOString(),
        }
      }

      const statusContent = readFileSync(SystemUpdateService.STATUS_FILE, 'utf-8')
      return JSON.parse(statusContent) as UpdateStatus
    } catch (error) {
      logger.error('[SystemUpdateService]: Failed to read update status:', error)
      return null
    }
  }

  getUpdateLogs(): string {
    try {
      if (!existsSync(SystemUpdateService.LOG_FILE)) {
        return 'No update logs available'
      }

      return readFileSync(SystemUpdateService.LOG_FILE, 'utf-8')
    } catch (error) {
      logger.error('[SystemUpdateService]: Failed to read update logs:', error)
      return `Error reading logs: ${error.message}`
    }
  }

  /**
   * Check if the update sidecar is reachable (i.e. shared volume is mounted)
   */
  isSidecarAvailable(): boolean {
    try {
      return existsSync(SystemUpdateService.SHARED_DIR)
    } catch (error) {
      return false
    }
  }
}

import { inject } from '@adonisjs/core'
import logger from '@adonisjs/core/services/logger'
import KVStore from '#models/kv_store'
import { clampRatio, updateEwma } from '../utils/token_estimate.js'

/**
 * Learns, per model, how far the token estimator is off — and corrects it.
 *
 * The estimator in `token_estimate.ts` cannot tokenize exactly (no vocabulary,
 * no tokenize endpoint, offline appliance). But every chat response already
 * carries the exact answer: Ollama reports `prompt_eval_count`, the true token
 * count of the prompt we just sent. That is free ground truth on every single
 * turn, and before this it was thrown away.
 *
 * So: record what we estimated, compare it to what the backend actually counted,
 * and fold `actual / estimated` into a per-model EWMA. The budget planner
 * multiplies by that factor from then on. Measured convergence is a couple of
 * turns, and it matters — Qwen tokenizes ~26% finer than Llama on the same text,
 * which no single global constant can absorb.
 *
 * Persisted as one JSON blob (`ai.tokenRatios`) rather than a key per model,
 * because KVStoreKey is a closed union. The data is pure cache: deleting the row
 * costs nothing but a short re-learn.
 */
@inject()
export class TokenCalibrationService {
  /** Model name -> learned correction factor. Authoritative once loaded. */
  private ratios: Map<string, number> = new Map()
  private loaded: Promise<void> | null = null
  /** Last persisted value per model, so we only write when the ratio really moved. */
  private persisted: Map<string, number> = new Map()

  /**
   * A ratio has to move by more than this before it earns a database write.
   * Once converged the factor barely twitches, and a row update per chat turn
   * would be pure noise on a machine that may be running from an SD card.
   */
  private static PERSIST_THRESHOLD = 0.02

  private async _load(): Promise<void> {
    if (!this.loaded) {
      this.loaded = (async () => {
        try {
          const raw = await KVStore.getValue('ai.tokenRatios')
          if (!raw) return
          const parsed = JSON.parse(raw)
          if (parsed && typeof parsed === 'object') {
            for (const [model, value] of Object.entries(parsed)) {
              if (typeof value === 'number' && Number.isFinite(value)) {
                const clamped = clampRatio(value)
                this.ratios.set(model, clamped)
                this.persisted.set(model, clamped)
              }
            }
          }
        } catch (error) {
          // Corrupt or hand-edited JSON. This is a cache; start over rather than
          // failing a chat request over it.
          logger.warn(
            `[TokenCalibration] Could not read stored ratios, starting fresh: ${error instanceof Error ? error.message : error}`
          )
        }
      })()
    }
    return this.loaded
  }

  /**
   * The correction factor to apply when estimating for `model`.
   * Returns 1 for a model we've never seen — an uncalibrated estimate, which is
   * still materially better than a fixed chars-per-token divisor.
   */
  async ratioFor(model: string): Promise<number> {
    await this._load()
    return this.ratios.get(model) ?? 1
  }

  /**
   * Record one observation.
   *
   * `estimatedTokens` must be the *uncalibrated* estimate for exactly the
   * messages that were sent — otherwise the factor gets applied twice and the
   * EWMA chases its own tail.
   */
  async record(model: string, estimatedTokens: number, actualTokens: number | undefined): Promise<void> {
    if (!actualTokens || !estimatedTokens || estimatedTokens <= 0 || actualTokens <= 0) return
    // Tiny prompts are dominated by chat-template overhead and teach us little
    // about how this model tokenizes real content.
    if (actualTokens < 32) return

    await this._load()

    const observed = clampRatio(actualTokens / estimatedTokens)
    const previous = this.ratios.get(model) ?? null
    const next = clampRatio(updateEwma(previous, observed))
    this.ratios.set(model, next)

    logger.debug(
      `[TokenCalibration] ${model}: estimated ${estimatedTokens}, actual ${actualTokens} ` +
        `(observed ${observed.toFixed(3)}, ratio ${next.toFixed(3)})`
    )

    const lastWritten = this.persisted.get(model)
    if (lastWritten === undefined || Math.abs(next - lastWritten) > TokenCalibrationService.PERSIST_THRESHOLD) {
      await this._persist(model, next)
    }
  }

  private async _persist(model: string, ratio: number): Promise<void> {
    try {
      const blob: Record<string, number> = {}
      for (const [name, value] of this.ratios) blob[name] = Number(value.toFixed(4))
      await KVStore.setValue('ai.tokenRatios', JSON.stringify(blob))
      this.persisted.set(model, ratio)
    } catch (error) {
      // Calibration is an optimization. Losing a write means a slightly worse
      // estimate next boot, never a failed chat.
      logger.warn(
        `[TokenCalibration] Failed to persist ratios: ${error instanceof Error ? error.message : error}`
      )
    }
  }
}

import { Archive, Entry } from '@openzim/libzim'
import * as cheerio from 'cheerio'
import { HTML_SELECTORS_TO_REMOVE, NON_CONTENT_HEADING_PATTERNS } from '../../constants/zim_extraction.js'
import { extractStructuredContent } from '../utils/zim_html.js'
import logger from '@adonisjs/core/services/logger'
import { ExtractZIMChunkingStrategy, ExtractZIMContentOptions, ZIMContentChunk, ZIMArchiveMetadata } from '../../types/zim.js'
import { randomUUID } from 'node:crypto'
import { access } from 'node:fs/promises'
import { isValidZimFile } from '../utils/fs.js'

export class ZIMExtractionService {

    private extractArchiveMetadata(archive: Archive): ZIMArchiveMetadata {
        try {
            return {
                title: archive.getMetadata('Title') || archive.getMetadata('Name') || 'Unknown',
                creator: archive.getMetadata('Creator') || 'Unknown',
                publisher: archive.getMetadata('Publisher') || 'Unknown',
                date: archive.getMetadata('Date') || 'Unknown',
                language: archive.getMetadata('Language') || 'Unknown',
                description: archive.getMetadata('Description') || '',
            }
        } catch (error) {
            logger.warn('[ZIMExtractionService]: Could not extract all metadata, using defaults', error)
            return {
                title: 'Unknown',
                creator: 'Unknown',
                publisher: 'Unknown',
                date: 'Unknown',
                language: 'Unknown',
                description: '',
            }
        }
    }

    /**
     * Breaks out a ZIM file's entries into their structured content form
     * to facilitate better indexing and retrieval.
     * Returns enhanced chunks with full article context and metadata.
     * 
     * @param filePath - Path to the ZIM file
     * @param opts - Options including maxArticles, strategy, onProgress, startOffset, and batchSize
     */
    async extractZIMContent(
        filePath: string,
        opts: ExtractZIMContentOptions = {}
    ): Promise<{ chunks: ZIMContentChunk[]; totalArticles: number; articlesProcessed: number }> {
        try {
            logger.info(`[ZIMExtractionService]: Processing ZIM file at path: ${filePath}`)

            // defensive - check if file still exists before opening
            // could have been deleted by another process or batch
            try {
                await access(filePath)
            } catch (error) {
                logger.error(`[ZIMExtractionService]: ZIM file not accessible: ${filePath}`)
                throw new Error(`ZIM file not found or not accessible: ${filePath}`)
            }

            // Validate ZIM magic number before opening with native library.
            // A corrupted file causes a native C++ abort that cannot be caught by JS.
            if (!(await isValidZimFile(filePath))) {
                throw new Error(`ZIM file is invalid or corrupted: ${filePath}`)
            }

            const archive = new Archive(filePath)

            // Extract archive-level metadata once
            const archiveMetadata = this.extractArchiveMetadata(archive)
            logger.info(`[ZIMExtractionService]: Archive metadata - Title: ${archiveMetadata.title}, Language: ${archiveMetadata.language}`)

            let articlesProcessed = 0
            let articlesSkipped = 0
            const processedPaths = new Set<string>()
            const toReturn: ZIMContentChunk[] = []

            // Support batch processing to avoid lock timeouts on large ZIM files
            const startOffset = opts.startOffset || 0
            const batchSize = opts.batchSize || (opts.maxArticles || Infinity)

            for (const entry of archive.iterByPath()) {
                // Skip articles until we reach the start offset
                if (articlesSkipped < startOffset) {
                    if (this.isArticleEntry(entry) && !processedPaths.has(entry.path)) {
                        articlesSkipped++
                    }
                    continue
                }

                if (articlesProcessed >= batchSize) {
                    break
                }

                if (!this.isArticleEntry(entry)) {
                    logger.debug(`[ZIMExtractionService]: Skipping non-article entry at path: ${entry.path}`)
                    continue
                }

                if (processedPaths.has(entry.path)) {
                    logger.debug(`[ZIMExtractionService]: Skipping duplicate entry at path: ${entry.path}`)
                    continue
                }
                processedPaths.add(entry.path)

                const item = entry.item
                const blob = item.data
                const html = this.getCleanedHTMLString(blob.data)

                const strategy = opts.strategy || this.chooseChunkingStrategy(html);
                logger.debug(`[ZIMExtractionService]: Chosen chunking strategy for path ${entry.path}: ${strategy}`)

                // Generate a unique document ID. All chunks from same article will share it
                const documentId = randomUUID()
                const articleTitle = entry.title || entry.path

                let chunks: ZIMContentChunk[]

                if (strategy === 'structured') {
                    const structured = extractStructuredContent(html)
                    chunks = structured.sections.map(s => ({
                        text: s.text,
                        articleTitle,
                        articlePath: entry.path,
                        sectionTitle: s.heading,
                        fullTitle: `${articleTitle} - ${s.heading}`,
                        hierarchy: `${articleTitle} > ${s.heading}`,
                        sectionLevel: s.level,
                        documentId,
                        archiveMetadata,
                        strategy,
                    }))
                } else {
                    // Simple strategy - entire article as one chunk
                    const text = this.extractTextFromHTML(html) || ''
                    chunks = [{
                        text,
                        articleTitle,
                        articlePath: entry.path,
                        sectionTitle: articleTitle, // Same as article for simple strategy
                        fullTitle: articleTitle,
                        hierarchy: articleTitle,
                        documentId,
                        archiveMetadata,
                        strategy,
                    }]
                }

                logger.debug(`Extracted ${chunks.length} chunks from article at path: ${entry.path} using strategy: ${strategy}`)

                const nonEmptyChunks = chunks.filter(c => c.text.trim().length > 0)
                logger.debug(`After filtering empty chunks, ${nonEmptyChunks.length} chunks remain for article at path: ${entry.path}`)
                toReturn.push(...nonEmptyChunks)
                articlesProcessed++

                if (opts.onProgress) {
                    opts.onProgress(articlesProcessed, archive.articleCount)
                }
            }

            logger.info(`[ZIMExtractionService]: Completed processing ZIM file. Total articles processed: ${articlesProcessed}`)
            logger.debug("Final structured content sample:", toReturn.slice(0, 3).map(c => ({
                articleTitle: c.articleTitle,
                sectionTitle: c.sectionTitle,
                hierarchy: c.hierarchy,
                textPreview: c.text.substring(0, 100)
            })))
            logger.debug("Total structured sections extracted:", toReturn.length)
            return { chunks: toReturn, totalArticles: archive.articleCount, articlesProcessed }
        } catch (error) {
            logger.error('Error processing ZIM file:', error)
            throw error
        }
    }

    private chooseChunkingStrategy(html: string, options = {
        forceStrategy: null as ExtractZIMChunkingStrategy | null,
    }): ExtractZIMChunkingStrategy {
        const {
            forceStrategy = null,
        } = options;

        if (forceStrategy) return forceStrategy;

        // Use a simple analysis to determin if the HTML has any meaningful structure
        // that we can leverage for better chunking. If not, we'll just chunk it as one big piece of text.
        return this.hasStructuredHeadings(html) ? 'structured' : 'simple';
    }

    private getCleanedHTMLString(buff: Buffer<ArrayBufferLike>): string {
        const rawString = buff.toString('utf-8');
        const $ = cheerio.load(rawString);

        HTML_SELECTORS_TO_REMOVE.forEach((selector) => {
            $(selector).remove()
        });

        return $.html();
    }

    private extractTextFromHTML(html: string): string | null {
        try {
            const $ = cheerio.load(html)

            // Search body first, then root if body is absent
            const text = $('body').length ? $('body').text() : $.root().text()

            return text.replace(/\s+/g, ' ').replace(/\n\s*\n/g, '\n').trim()
        } catch (error) {
            logger.error('Error extracting text from HTML:', error)
            return null
        }
    }

    private hasStructuredHeadings(html: string): boolean {
        const $ = cheerio.load(html);

        const headings = $('h2, h3').toArray();

        // Consider it structured if it has at least 2 headings to break content into meaningful sections
        if (headings.length < 2) return false;

        // Check that headings have substantial content between them
        let sectionsWithContent = 0;

        for (const heading of headings) {
            const $heading = $(heading);
            const headingText = $heading.text().trim();

            // Skip empty or very short headings, likely not meaningful
            if (headingText.length < 3) continue;

            // Skip common non-content headings
            if (NON_CONTENT_HEADING_PATTERNS.some(pattern => pattern.test(headingText))) {
                continue;
            }

            // Content until next heading
            let contentLength = 0;
            let $next = $heading.next();

            while ($next.length && !$next.is('h1, h2, h3, h4')) {
                contentLength += $next.text().trim().length;
                $next = $next.next();
            }

            // Consider it a real section if it has at least 100 chars of content
            if (contentLength >= 100) {
                sectionsWithContent++;
            }
        }

        // Require at least 2 sections with substantial content
        return sectionsWithContent >= 2;
    }

    private isArticleEntry(entry: Entry): boolean {
        try {
            if (entry.isRedirect) return false;

            const item = entry.item;
            const mimeType = item.mimetype;

            return mimeType === 'text/html' || mimeType === 'application/xhtml+xml';
        } catch {
            return false;
        }
    }
}

import {
  CatalogLanguage,
  ListRemoteZimFilesResponse,
  RawRemoteZimFileEntry,
  RemoteZimFileEntry,
} from '../../types/zim.js'
import axios from 'axios'
import * as cheerio from 'cheerio'
import { XMLParser } from 'fast-xml-parser'
import { isRawListRemoteZimFilesResponse, isRawRemoteZimFileEntry } from '../../util/zim.js'
import { findReplacedWikipediaFiles } from '../utils/zim_filename.js'
import { decideSupersededDeletion } from '../utils/superseded_resource.js'
import logger from '@adonisjs/core/services/logger'
import { DockerService } from './docker_service.js'
import { inject } from '@adonisjs/core'
import {
  deleteFileIfExists,
  ensureDirectoryExists,
  getFileStatsIfExists,
  listDirectoryContents,
  ZIM_STORAGE_PATH,
} from '../utils/fs.js'
import { join, resolve, sep } from 'path'
import { WikipediaOption, WikipediaState } from '../../types/downloads.js'
import vine from '@vinejs/vine'
import { wikipediaOptionsFileSchema } from '#validators/curated_collections'
import WikipediaSelection from '#models/wikipedia_selection'
import InstalledResource from '#models/installed_resource'
import CollectionManifest from '#models/collection_manifest'
import { RunDownloadJob } from '#jobs/run_download_job'
import { DownloadDrugDataJob } from '#jobs/download_drug_data_job'
import { DrugReferenceService } from './drug_reference_service.js'
import { SERVICE_NAMES } from '../../constants/service_names.js'
import { CollectionManifestService } from './collection_manifest_service.js'
import { KiwixCatalogService } from './kiwix_catalog_service.js'
import { KiwixLibraryService } from './kiwix_library_service.js'
import { RagService } from './rag_service.js'
import { OllamaService } from './ollama_service.js'
import type { CategoryWithStatus } from '../../types/collections.js'
import CustomLibrarySource from '#models/custom_library_source'
import { assertNotPrivateUrl } from '#validators/common'
import { resolveZimDownload } from '../utils/zim_download_resolution.js'
import { getHostedContentHeaders } from '../utils/hosted_content_auth.js'
import { KIWIX_CATALOG_BASE_URL } from '../../constants/kiwix.js'

const ZIM_MIME_TYPES = ['application/x-zim', 'application/x-openzim', 'application/octet-stream']
const WIKIPEDIA_OPTIONS_URL = 'https://raw.githubusercontent.com/Crosstalk-Solutions/project-nomad/refs/heads/main/collections/wikipedia.json'

@inject()
export class ZimService {
  constructor(private dockerService: DockerService) { }

  async list() {
    const dirPath = join(process.cwd(), ZIM_STORAGE_PATH)
    await ensureDirectoryExists(dirPath)

    const all = await listDirectoryContents(dirPath)
    const zimEntries = all.filter((item) => item.name.endsWith('.zim'))

    const files = await Promise.all(
      zimEntries.map(async (entry) => {
        const filePath = entry.type === 'file' ? entry.key : join(dirPath, entry.name)
        const stats = await getFileStatsIfExists(filePath)
        return {
          ...entry,
          title: null,
          summary: null,
          author: null,
          size_bytes: stats ? Number(stats.size) : null,
        }
      })
    )

    return {
      files,
    }
  }

  async listRemote({
    start,
    count,
    query,
    language = 'eng',
  }: {
    start: number
    count: number
    query?: string
    /**
     * ISO-639-3 code to filter the catalog by, or `all` for no filter. Defaults to
     * English, which is what this browser has always shown -- but it is now a default
     * the user can change, not a hardcode. English is ~1,300 of the catalog's ~10,900
     * books, so the filter was hiding the large majority of the library.
     */
    language?: string
  }): Promise<ListRemoteZimFilesResponse> {
    // Kiwix returns pages of content unaware of what the user has installed locally. When
    // the installed set is large, a single 12-item Kiwix page can come back with everything
    // already installed → 0 post-filter items → frontend deadlock (#731). Accumulate across
    // upstream pages so we return a useful batch. Bounded by MAX_KIWIX_FETCHES so a heavily
    // saturated install doesn't hang a single request; the frontend scroll loop + auto-fetch
    // effect handle continuation.
    const KIWIX_PAGE_SIZE = 60
    const MAX_KIWIX_FETCHES = 5

    const parser = new XMLParser({
      ignoreAttributes: false,
      attributeNamePrefix: '',
      textNodeName: '#text',
    })

    // Snapshot locally-installed files once — the filesystem won't change mid-request.
    const existing = await this.list()
    const existingKeys = new Set(existing.files.map((file) => file.name))

    const accumulated: RemoteZimFileEntry[] = []
    const seenIds = new Set<string>()
    let currentStart = start
    let totalResults = 0

    for (let i = 0; i < MAX_KIWIX_FETCHES; i++) {
      const res = await axios.get(KIWIX_CATALOG_BASE_URL, {
        params: {
          start: currentStart,
          count: KIWIX_PAGE_SIZE,
          // `all` means "no filter", which the catalog expresses by omitting `lang`.
          ...(language && language !== 'all' ? { lang: language } : {}),
          ...(query ? { q: query } : {}),
        },
        responseType: 'text',
      })

      const parsed = parser.parse(res.data)
      if (!isRawListRemoteZimFilesResponse(parsed)) {
        throw new Error('Invalid response format from remote library')
      }
      totalResults = parsed.feed.totalResults

      const rawEntries = parsed.feed.entry
        ? Array.isArray(parsed.feed.entry)
          ? parsed.feed.entry
          : [parsed.feed.entry]
        : []

      // Empty upstream response — bail even if totalResults suggests more (transient Kiwix
      // hiccup or totalResults drift between pages). Prevents a pointless spin.
      if (rawEntries.length === 0) break

      // Advance by actual returned count, not requested count. Short pages at the tail
      // would otherwise cause us to skip entries on the next fetch.
      currentStart += rawEntries.length

      for (const raw of rawEntries) {
        if (!isRawRemoteZimFileEntry(raw)) continue
        const entry = raw as RawRemoteZimFileEntry

        const downloadLink = entry.link.find(
          (link: any) =>
            typeof link === 'object' &&
            'rel' in link &&
            'length' in link &&
            'href' in link &&
            'type' in link &&
            link.type === 'application/x-zim'
        )
        if (!downloadLink) continue

        // downloadLink['href'] ends with .meta4; strip that to get the actual .zim URL.
        const download_url = downloadLink['href'].substring(0, downloadLink['href'].length - 6)
        const file_name = download_url.split('/').pop() || `${entry.title}.zim`
        if (existingKeys.has(file_name)) continue
        if (seenIds.has(entry.id)) continue
        seenIds.add(entry.id)

        const sizeBytes = parseInt(downloadLink['length'], 10)
        accumulated.push({
          id: entry.id,
          title: entry.title,
          updated: entry.updated,
          summary: entry.summary,
          size_bytes: sizeBytes || 0,
          download_url,
          author: entry.author.name,
          file_name,
          language: entry.language,
          category: entry.category,
          tags: entry.tags,
          article_count: entry.articleCount,
          media_count: entry.mediaCount,
          publisher: entry.publisher?.name,
          issued: entry['dc:issued'],
        })
      }

      if (accumulated.length >= count) break
      if (currentStart >= totalResults) break
    }

    return {
      items: accumulated,
      has_more: currentStart < totalResults,
      total_count: totalResults,
      next_start: currentStart,
    }
  }

  /**
   * The languages the Kiwix catalog actually holds books in, newest count first.
   *
   * Sourced live from the catalog rather than a bundled ISO list, so the options are
   * always exactly what can be browsed, and each carries a real book count. Titles are
   * the catalog's own endonyms ("français", "中文"), which is what a reader scanning for
   * their own language recognises.
   *
   * Requires internet, like the rest of this browser. Failures return an empty list
   * rather than throwing: a missing language filter should degrade to "English only",
   * never take down the page that lists the books.
   */
  async listCatalogLanguages(): Promise<CatalogLanguage[]> {
    const LANGUAGES_URL = 'https://opds.library.kiwix.org/catalog/v2/languages'
    try {
      const res = await axios.get(LANGUAGES_URL, { responseType: 'text', timeout: 15000 })
      const parser = new XMLParser({
        ignoreAttributes: false,
        attributeNamePrefix: '',
        textNodeName: '#text',
      })
      const parsed = parser.parse(res.data)
      const rawEntries = parsed?.feed?.entry
        ? Array.isArray(parsed.feed.entry)
          ? parsed.feed.entry
          : [parsed.feed.entry]
        : []

      const languages: CatalogLanguage[] = []
      for (const raw of rawEntries) {
        if (!raw || typeof raw !== 'object') continue
        // `dc:language` is the ISO-639-3 code; `thr:count` is how many books carry it.
        const code = raw['dc:language']
        const label = raw.title
        const bookCount = Number(raw['thr:count'])
        if (typeof code !== 'string' || !code.trim()) continue
        if (!Number.isFinite(bookCount) || bookCount <= 0) continue
        languages.push({
          code: code.trim(),
          label: typeof label === 'string' && label.trim() ? label.trim() : code.trim(),
          book_count: bookCount,
        })
      }

      languages.sort((a, b) => b.book_count - a.book_count)
      return languages
    } catch (error) {
      logger.warn(
        `[ZimService] Catalog language list unavailable: ${
          error instanceof Error ? error.message : error
        }`
      )
      return []
    }
  }

  async downloadRemote(url: string, metadata?: { title?: string; summary?: string; author?: string; size_bytes?: number }): Promise<{ filename: string; jobId?: string }> {
    const parsed = new URL(url)
    if (!parsed.pathname.endsWith('.zim')) {
      throw new Error(`Invalid ZIM file URL: ${url}. URL must end with .zim`)
    }

    const existing = await RunDownloadJob.getActiveByUrl(url)
    if (existing) {
      throw new Error('A download for this URL is already in progress')
    }

    // Extract the filename from the URL
    const filename = url.split('/').pop()
    if (!filename) {
      throw new Error('Could not determine filename from URL')
    }

    const filepath = join(process.cwd(), ZIM_STORAGE_PATH, filename)

    // Parse resource metadata for the download job
    const parsedFilename = CollectionManifestService.parseZimFilename(filename)
    const resourceMetadata = parsedFilename
      ? { resource_id: parsedFilename.resource_id, version: parsedFilename.version, collection_ref: null }
      : undefined

    // Dispatch a background download job
    const result = await RunDownloadJob.dispatch({
      url,
      filepath,
      timeout: 30000,
      allowedMimeTypes: ZIM_MIME_TYPES,
      filetype: 'zim',
      title: metadata?.title,
      totalBytes: metadata?.size_bytes,
      resourceMetadata,
    })

    if (!result || !result.job) {
      throw new Error('Failed to dispatch download job')
    }

    logger.info(`[ZimService] Dispatched background download job for ZIM file: ${filename}`)

    return {
      filename,
      jobId: result.job.id,
    }
  }

  async listCuratedCategories(): Promise<CategoryWithStatus[]> {
    const manifestService = new CollectionManifestService()
    return manifestService.getCategoriesWithStatus()
  }

  async downloadCategoryTier(categorySlug: string, tierSlug: string): Promise<string[] | null> {
    const manifestService = new CollectionManifestService()
    const spec = await manifestService.getSpecWithFallback<import('../../types/collections.js').ZimCategoriesSpec>('zim_categories')
    if (!spec) {
      throw new Error('Could not load ZIM categories spec')
    }

    const category = spec.categories.find((c) => c.slug === categorySlug)
    if (!category) {
      throw new Error(`Category not found: ${categorySlug}`)
    }

    const tier = category.tiers.find((t) => t.slug === tierSlug)
    if (!tier) {
      throw new Error(`Tier not found: ${tierSlug}`)
    }

    const allResources = CollectionManifestService.resolveTierResources(tier, category.tiers)

    // Filter out already installed. Includes 'dataset' rows (the FDA drug labels)
    // alongside 'zim' so an installed dataset is filtered out here — without it,
    // a re-select of an installed Medicine tier would re-dispatch the ~1.7 GB drug
    // download every time (the dataset branch's own getIngestStatus guard is a
    // second line of defence, but this keeps the filter symmetric with the row-
    // driven tier-status math).
    const installed = await InstalledResource.query().whereIn('resource_type', ['zim', 'dataset'])
    const installedIds = new Set(installed.map((r) => r.resource_id))
    const toDownload = allResources.filter((r) => !installedIds.has(r.id))

    if (toDownload.length === 0) return null

    const latestByResource = await new KiwixCatalogService().getLatestForResources(
      toDownload.map((resource) => ({ resource_id: resource.id, resource_type: 'zim' }))
    )
    const downloadFilenames: string[] = []

    for (const resource of toDownload) {
      // A `dataset` resource (e.g. the FDA drug labels) is DB-ingested, not a
      // ZIM file — route it to the drug download+ingest pipeline instead of
      // RunDownloadJob. The install-state row written on ingest 'ready' (below,
      // via resourceMeta) is what the installed-filter above and the tier-status
      // math key off; until that row exists the getIngestStatus guard prevents
      // re-dispatching the ~1.7 GB download on every tier select.
      if (resource.type === 'dataset') {
        const drugReferenceService = new DrugReferenceService()
        const status = await drugReferenceService.getIngestStatus()
        if (status.phase === 'ready' || status.rowCount > 0) {
          logger.info('[ZimService] Drug dataset already ingested, skipping dispatch.')
          // Reaching here means no 'dataset' row exists (the installed filter
          // above would have dropped the resource). A finished ingest that lost
          // its row write (1.34.0's narrow enum, or a manual ingest) gets one now,
          // so re-selecting the tier resolves it without waiting for a reboot.
          if (status.phase === 'ready' && status.lastUpdated) {
            try {
              await drugReferenceService.recordInstalledRow({
                version: status.lastUpdated,
                collectionRef: categorySlug,
                fileSizeBytes: null,
              })
              logger.info('[ZimService] Backfilled installed_resources row for the drug dataset.')
            } catch (err) {
              logger.error(
                `[ZimService] Failed to backfill drug dataset row: ${
                  err instanceof Error ? err.message : String(err)
                }`
              )
            }
          }
          continue
        }
        // DownloadDrugDataJob.dispatch() is idempotent on its deterministic
        // jobId — a concurrent in-flight download returns "already running"
        // without re-adding, so this is safe to call repeatedly. The resourceMeta
        // is threaded through download → ingest so the final ingest pass writes
        // the `installed_resources` 'dataset' row, making the tier read installed.
        await DownloadDrugDataJob.dispatch(true, {
          resourceId: resource.id,
          version: resource.version,
          collectionRef: categorySlug,
        })
        logger.info('[ZimService] Dispatched drug data download for dataset resource.')
        continue
      }

      const resolved = resolveZimDownload(
        resource,
        latestByResource.get(`zim:${resource.id}`) ?? null
      )
      const existingJob = await RunDownloadJob.getActiveByUrl(resolved.url)
      if (existingJob) {
        logger.warn(`[ZimService] Download already in progress for ${resolved.url}, skipping.`)
        continue
      }

      const filename = resolved.url.split('/').pop()
      if (!filename) continue

      downloadFilenames.push(filename)
      const filepath = join(process.cwd(), ZIM_STORAGE_PATH, filename)

      await RunDownloadJob.dispatch({
        url: resolved.url,
        filepath,
        timeout: 30000,
        allowedMimeTypes: ZIM_MIME_TYPES,
        filetype: 'zim',
        title: (resource as any).title || undefined,
        totalBytes: resolved.sizeBytes,
        // Undefined for every ungated resource, so the existing flow is untouched.
        requestHeaders: getHostedContentHeaders(resource),
        resourceMetadata: {
          resource_id: resource.id,
          version: resolved.version,
          collection_ref: categorySlug,
        },
      })
    }

    return downloadFilenames.length > 0 ? downloadFilenames : null
  }

  async downloadRemoteSuccessCallback(urls: string[], restart = true) {
    // Check if any URL is a Wikipedia download and handle it
    for (const url of urls) {
      if (url.includes('wikipedia_en_')) {
        await this.onWikipediaDownloadComplete(url, true)
      }
    }

    // Update the kiwix library XML after all downloaded ZIM files are in place.
    // This covers all ZIM types including Wikipedia. Rebuilding once from disk
    // avoids repeated XML parse/write cycles and reduces the chance of write races
    // when multiple download jobs complete concurrently.
    const kiwixLibraryService = new KiwixLibraryService()
    try {
      await kiwixLibraryService.rebuildFromDisk()
    } catch (err) {
      logger.error('[ZimService] Failed to rebuild kiwix library from disk:', err)
    }

    if (restart) {
      // Check if there are any remaining ZIM download jobs before restarting
      const { QueueService } = await import('./queue_service.js')
      const queueService = QueueService.getInstance()
      const queue = queueService.getQueue('downloads')

      // Get all active and waiting jobs
      const [activeJobs, waitingJobs] = await Promise.all([
        queue.getActive(),
        queue.getWaiting(),
      ])

      // Filter out completed jobs (progress === 100) to avoid race condition
      // where this job itself is still in the active queue
      const activeIncompleteJobs = activeJobs.filter((job) => {
        const progress = typeof job.progress === 'object' && job.progress !== null
          ? (job.progress as any).percent
          : typeof job.progress === 'number' ? job.progress : 0
        return progress < 100
      })

      // Check if any remaining incomplete jobs are ZIM downloads
      const allJobs = [...activeIncompleteJobs, ...waitingJobs]
      const hasRemainingZimJobs = allJobs.some((job) => job.data.filetype === 'zim')

      if (hasRemainingZimJobs) {
        logger.info('[ZimService] Skipping container restart - more ZIM downloads pending')
      } else {
        // If kiwix is already running in library mode, --monitorLibrary will pick up
        // the XML change automatically — no restart needed.
        const isLegacy = await this.dockerService.isKiwixOnLegacyConfig()
        if (!isLegacy) {
          logger.info('[ZimService] Kiwix is in library mode — XML updated, no container restart needed.')
        } else {
          // Legacy config: restart (affectContainer will trigger migration instead)
          logger.info('[ZimService] No more ZIM downloads pending - restarting KIWIX container')
          await this.dockerService
            .affectContainer(SERVICE_NAMES.KIWIX, 'restart')
            .catch((error) => {
              logger.error(`[ZimService] Failed to restart KIWIX container:`, error)
            })
        }
      }
    }

    // Create InstalledResource entries for downloaded files
    const zimStorageDir = join(process.cwd(), ZIM_STORAGE_PATH)
    let removedSupersededZim = false
    for (const url of urls) {
      // Skip Wikipedia files (managed separately)
      if (url.includes('wikipedia_en_')) continue

      const filename = url.split('/').pop()
      if (!filename) continue

      const parsed = CollectionManifestService.parseZimFilename(filename)
      if (!parsed) continue

      const filepath = join(zimStorageDir, filename)
      const stats = await getFileStatsIfExists(filepath)

      try {
        // Capture the prior install for this resource_id BEFORE updateOrCreate
        // overwrites it, so we know the old file path to clean up (#634).
        const prior = await InstalledResource.query()
          .where('resource_id', parsed.resource_id)
          .where('resource_type', 'zim')
          .first()

        const { DateTime } = await import('luxon')
        await InstalledResource.updateOrCreate(
          { resource_id: parsed.resource_id, resource_type: 'zim' },
          {
            version: parsed.version,
            url: url,
            file_path: filepath,
            file_size_bytes: stats ? Number(stats.size) : null,
            installed_at: DateTime.now(),
          }
        )
        logger.info(`[ZimService] Created InstalledResource entry for: ${parsed.resource_id}`)

        // Remove the superseded prior version's file if (and only if) every
        // safety rail passes — see decideSupersededDeletion. The InstalledResource
        // row already points at the new file, so we delete the old file directly
        // (NOT via this.delete(), which would drop the row by resource_id).
        const decision = decideSupersededDeletion({
          existing: prior ? { file_path: prior.file_path, version: prior.version } : null,
          newFilePath: filepath,
          newVersion: parsed.version,
          newFileExists: !!stats,
          storageBaseDir: zimStorageDir,
        })
        if (decision.delete && decision.path) {
          try {
            await deleteFileIfExists(decision.path)
            removedSupersededZim = true
            logger.info(
              `[ZimService] Removed superseded ${parsed.resource_id} file: ${decision.path}`
            )
          } catch (err) {
            logger.warn(`[ZimService] Failed to remove superseded file ${decision.path}:`, err)
          }
        } else if (decision.reason !== 'first_install' && decision.reason !== 'same_file') {
          logger.info(
            `[ZimService] Kept prior ${parsed.resource_id} file (reason: ${decision.reason})`
          )
        }
      } catch (error) {
        logger.error(`[ZimService] Failed to create InstalledResource for ${filename}:`, error)
      }
    }

    // If we removed any superseded ZIM, rebuild the Kiwix library so its XML no
    // longer references the deleted file. The earlier rebuild in this flow ran
    // while both versions were still on disk.
    if (removedSupersededZim) {
      try {
        await new KiwixLibraryService().rebuildFromDisk()
        logger.info('[ZimService] Rebuilt Kiwix library after removing superseded ZIM(s).')
      } catch (err) {
        logger.error('[ZimService] Failed to rebuild Kiwix library after cleanup:', err)
      }
    }
  }

  /**
   * Rebuilds the kiwix library XML from whatever ZIM files are currently on disk.
   *
   * This is the manual counterpart to the automatic rebuilds that run after a
   * download or delete. It exists for the sideload case: a user copies a .zim file
   * onto the box (USB, SSH, network share) outside the download flow, and kiwix has
   * no way to discover it without regenerating the library index.
   *
   * In library mode (--monitorLibrary) kiwix-serve hot-reloads the XML on its own, so
   * no restart is needed. Only legacy glob-mode containers are restarted to pick up
   * the change. Returns the book count before and after plus the number added.
   */
  async rescanLibrary(): Promise<{ before: number; after: number; added: number }> {
    const kiwixLibraryService = new KiwixLibraryService()
    const before = await kiwixLibraryService.getBookCount()
    const after = await kiwixLibraryService.rebuildFromDisk()

    const isLegacy = await this.dockerService.isKiwixOnLegacyConfig()
    if (isLegacy) {
      logger.info('[ZimService] Kiwix in legacy mode — restarting container after rescan.')
      await this.dockerService
        .affectContainer(SERVICE_NAMES.KIWIX, 'restart')
        .catch((error) => {
          logger.error('[ZimService] Failed to restart KIWIX container after rescan:', error)
        })
    }

    return { before, after, added: Math.max(0, after - before) }
  }

  async registerLocalUpload(filename: string): Promise<{ added: number }> {
    let added = 0
    try {
      const result = await this.rescanLibrary()
      added = result.added
    } catch (err) {
      logger.error('[ZimService] Failed to rebuild kiwix library after local upload:', err)
    }

    const parsed = CollectionManifestService.parseZimFilename(filename)
    if (parsed) {
      const filepath = join(process.cwd(), ZIM_STORAGE_PATH, filename)
      const stats = await getFileStatsIfExists(filepath)
      try {
        const { DateTime } = await import('luxon')
        await InstalledResource.updateOrCreate(
          { resource_id: parsed.resource_id, resource_type: 'zim' },
          {
            version: parsed.version,
            url: `local-upload://${filename}`,
            file_path: filepath,
            file_size_bytes: stats ? Number(stats.size) : null,
            installed_at: DateTime.now(),
          }
        )
      } catch (error) {
        logger.error(`[ZimService] Failed to create InstalledResource for ${filename}:`, error)
      }
    }

    // If the uploaded file matches a known Wikipedia option, mark it as installed
    try {
      const manifest = await CollectionManifest.find('wikipedia')
      if (manifest) {
        const spec = manifest.spec_data as { options: Array<{ id: string; url: string | null }> }
        const matchedOption = spec.options.find(
          (opt) => opt.url && opt.url.split('/').pop() === filename
        )
        if (matchedOption && matchedOption.url) {
          const existing = await WikipediaSelection.query().first()
          if (existing) {
            existing.option_id = matchedOption.id
            existing.url = matchedOption.url
            existing.filename = filename
            existing.status = 'installed'
            await existing.save()
          } else {
            await WikipediaSelection.create({
              option_id: matchedOption.id,
              url: matchedOption.url,
              filename,
              status: 'installed',
            })
          }
          logger.info(`[ZimService] Marked Wikipedia option '${matchedOption.id}' as installed from local upload`)

          // Remove any other wikipedia_en_*.zim files, same as the download flow
          const allFiles = await this.list()
          const staleWikipediaFiles = allFiles.files.filter(
            (f) => f.name.startsWith('wikipedia_en_') && f.name !== filename
          )
          for (const stale of staleWikipediaFiles) {
            try {
              await this.delete(stale.name)
              logger.info(`[ZimService] Deleted stale Wikipedia file after upload: ${stale.name}`)
            } catch (err) {
              logger.warn(`[ZimService] Could not delete stale Wikipedia file: ${stale.name}`, err)
            }
          }
        }
      }
    } catch (error) {
      logger.error(`[ZimService] Failed to update WikipediaSelection for ${filename}:`, error)
    }

    const ollamaUrl = await this.dockerService.getServiceURL('nomad_ollama')
    if (ollamaUrl) {
      // Respect the global ingest policy, same as the post-download path (PR #919).
      // This used to dispatch unconditionally, so a user who deliberately chose
      // Manual still got sideloaded ZIMs embedded behind their back.
      //
      // Reuses decideScanAction rather than re-inlining the Always/Manual check,
      // so an existing browse_only or pending_decision row is honored too instead
      // of being overridden by the act of re-uploading the file.
      const filePath = join(process.cwd(), ZIM_STORAGE_PATH, filename)
      try {
        const { default: KVStore } = await import('#models/kv_store')
        const { default: KbIngestState } = await import('#models/kb_ingest_state')
        const { decideScanAction } = await import('../utils/kb_ingest_decision.js')

        // Unset is treated as Always, preserving legacy behavior — mirrors
        // rag_service.ts and run_download_job.ts.
        const policyRaw = await KVStore.getValue('rag.defaultIngestPolicy')
        const policy = policyRaw === 'Manual' ? 'Manual' : 'Always'

        const existing = await KbIngestState.findBy('file_path', filePath)
        const action = decideScanAction(existing, false, policy)

        if (action.kind === 'dispatch') {
          const { EmbedFileJob } = await import('#jobs/embed_file_job')
          await EmbedFileJob.dispatch({ fileName: filename, filePath })
        } else if (action.kind === 'create_pending') {
          // firstOrCreate so the KB panel surfaces the per-file Index affordance
          // without demoting a row that already exists.
          await KbIngestState.getOrCreate(filePath)
        }
        // 'skip' and 'backfill_indexed' need no action here: the file was just
        // written to disk, so there is nothing to backfill and a settled state
        // row means the user has already decided about this file.
      } catch (error) {
        logger.error(`[ZimService] KB ingest decision failed after local upload:`, error)
      }
    }

    return { added }
  }

  async delete(file: string): Promise<void> {
    let fileName = file
    if (!fileName.endsWith('.zim')) {
      fileName += '.zim'
    }

    const basePath = resolve(join(process.cwd(), ZIM_STORAGE_PATH))
    const fullPath = resolve(join(basePath, fileName))

    // Prevent path traversal — resolved path must stay within the storage directory
    if (!fullPath.startsWith(basePath + sep)) {
      throw new Error('Invalid filename')
    }

    const exists = await getFileStatsIfExists(fullPath)
    if (!exists) {
      throw new Error('not_found')
    }

    await deleteFileIfExists(fullPath)

    // Purge this file's Qdrant points and KbIngestState row directly so a
    // deleted ZIM stops surfacing as a stale search citation immediately,
    // rather than waiting for the next scanAndSyncStorage reverse sweep to
    // catch it (#1170). Never touched Qdrant here before — the file's points
    // and state row would otherwise linger indefinitely.
    //
    // Guarded on the AI Assistant being installed at all — otherwise every
    // delete on an install without it hits _initializeQdrantClient()'s
    // "offline" throw and logs a misleading error for the common no-AI case.
    const qdrantInstalled = !!(await this.dockerService.getServiceURL(SERVICE_NAMES.QDRANT))
    if (qdrantInstalled) {
      try {
        const ragService = new RagService(this.dockerService, new OllamaService())
        await ragService.purgeIndexedSource(fullPath)
      } catch (err) {
        logger.error(`[ZimService] Failed to purge knowledge-base entries for ${fullPath}:`, err)
      }
    }

    // Remove from kiwix library XML so --monitorLibrary stops serving the deleted file
    const kiwixLibraryService = new KiwixLibraryService()
    await kiwixLibraryService.removeBook(fileName).catch((err) => {
      logger.error(`[ZimService] Failed to remove ${fileName} from kiwix library:`, err)
    })

    // Clean up InstalledResource entry
    const parsed = CollectionManifestService.parseZimFilename(fileName)
    if (parsed) {
      await InstalledResource.query()
        .where('resource_id', parsed.resource_id)
        .where('resource_type', 'zim')
        .delete()
      logger.info(`[ZimService] Deleted InstalledResource entry for: ${parsed.resource_id}`)
    }

    // If this file was the active Wikipedia selection, clear the selection
    try {
      const selection = await WikipediaSelection.query().first()
      if (selection && selection.filename === fileName) {
        selection.option_id = 'none'
        selection.status = 'none'
        selection.filename = null
        selection.url = null
        await selection.save()
        logger.info(`[ZimService] Cleared WikipediaSelection after deleting ${fileName}`)
      }
    } catch (error) {
      logger.error(`[ZimService] Failed to clear WikipediaSelection after deleting ${fileName}:`, error)
    }
  }

  // Wikipedia selector methods

  async getWikipediaOptions(): Promise<WikipediaOption[]> {
    try {
      const response = await axios.get(WIKIPEDIA_OPTIONS_URL)
      const data = response.data

      const validated = await vine.validate({
        schema: wikipediaOptionsFileSchema,
        data,
      })

      return validated.options
    } catch (error) {
      logger.error(`[ZimService] Failed to fetch Wikipedia options:`, error)
      throw new Error('Failed to fetch Wikipedia options')
    }
  }

  async getWikipediaSelection(): Promise<WikipediaSelection | null> {
    // Get the single row from wikipedia_selections (there should only ever be one)
    return WikipediaSelection.query().first()
  }

  async getWikipediaState(): Promise<WikipediaState> {
    const options = await this.getWikipediaOptions()
    const selection = await this.getWikipediaSelection()

    return {
      options,
      currentSelection: selection
        ? {
          optionId: selection.option_id,
          status: selection.status,
          filename: selection.filename,
          url: selection.url,
        }
        : null,
    }
  }

  async selectWikipedia(optionId: string): Promise<{ success: boolean; jobId?: string; message?: string }> {
    const options = await this.getWikipediaOptions()
    const selectedOption = options.find((opt) => opt.id === optionId)

    if (!selectedOption) {
      throw new Error(`Invalid Wikipedia option: ${optionId}`)
    }

    const currentSelection = await this.getWikipediaSelection()

    // If same as currently installed, no action needed
    if (currentSelection?.option_id === optionId && currentSelection.status === 'installed') {
      return { success: true, message: 'Already installed' }
    }

    // Handle "none" option - delete current Wikipedia file and update DB
    if (optionId === 'none') {
      if (currentSelection?.filename) {
        try {
          await this.delete(currentSelection.filename)
          logger.info(`[ZimService] Deleted Wikipedia file: ${currentSelection.filename}`)
        } catch (error) {
          // File might already be deleted, that's OK
          logger.warn(`[ZimService] Could not delete Wikipedia file (may already be gone): ${currentSelection.filename}`)
        }
      }

      // Update or create the selection record (always use first record)
      if (currentSelection) {
        currentSelection.option_id = 'none'
        currentSelection.url = null
        currentSelection.filename = null
        currentSelection.status = 'none'
        await currentSelection.save()
      } else {
        await WikipediaSelection.create({
          option_id: 'none',
          url: null,
          filename: null,
          status: 'none',
        })
      }

      // Restart Kiwix to reflect the change
      await this.dockerService
        .affectContainer(SERVICE_NAMES.KIWIX, 'restart')
        .catch((error) => {
          logger.error(`[ZimService] Failed to restart Kiwix after Wikipedia removal:`, error)
        })

      return { success: true, message: 'Wikipedia removed' }
    }

    // Start download for the new Wikipedia option
    if (!selectedOption.url) {
      throw new Error('Selected Wikipedia option has no download URL')
    }

    // Check if already downloading
    const existingJob = await RunDownloadJob.getActiveByUrl(selectedOption.url)
    if (existingJob) {
      return { success: false, message: 'Download already in progress' }
    }

    // Extract filename from URL
    const filename = selectedOption.url.split('/').pop()
    if (!filename) {
      throw new Error('Could not determine filename from URL')
    }

    const filepath = join(process.cwd(), ZIM_STORAGE_PATH, filename)

    // Update or create selection record to show downloading status
    let selection: WikipediaSelection
    if (currentSelection) {
      currentSelection.option_id = optionId
      currentSelection.url = selectedOption.url
      currentSelection.filename = filename
      currentSelection.status = 'downloading'
      await currentSelection.save()
      selection = currentSelection
    } else {
      selection = await WikipediaSelection.create({
        option_id: optionId,
        url: selectedOption.url,
        filename: filename,
        status: 'downloading',
      })
    }

    // Dispatch download job
    const result = await RunDownloadJob.dispatch({
      url: selectedOption.url,
      filepath,
      timeout: 30000,
      allowedMimeTypes: ZIM_MIME_TYPES,
      filetype: 'zim',
      title: selectedOption.name,
      totalBytes: selectedOption.size_mb ? selectedOption.size_mb * 1024 * 1024 : undefined,
    })

    if (!result || !result.job) {
      // Revert status on failure to dispatch
      selection.option_id = currentSelection?.option_id || 'none'
      selection.url = currentSelection?.url || null
      selection.filename = currentSelection?.filename || null
      selection.status = currentSelection?.status || 'none'
      await selection.save()
      throw new Error('Failed to dispatch download job')
    }

    logger.info(`[ZimService] Started Wikipedia download for ${optionId}: ${filename}`)

    return {
      success: true,
      jobId: result.job.id,
      message: 'Download started',
    }
  }

  async onWikipediaDownloadComplete(url: string, success: boolean): Promise<void> {
    const filename = url.split('/').pop() || ''
    const selection = await this.getWikipediaSelection()

    // Determine which Wikipedia option this file belongs to by matching filename
    let matchedOptionId: string | null = null
    try {
      const options = await this.getWikipediaOptions()
      for (const opt of options) {
        if (opt.url && opt.url.split('/').pop() === filename) {
          matchedOptionId = opt.id
          break
        }
      }
    } catch {
      // If we can't fetch options, try to continue with existing selection
    }

    if (success) {
      // Update or create the selection record
      // Match by filename (not URL) so mirror downloads are recognized
      if (selection) {
        selection.option_id = matchedOptionId || selection.option_id
        selection.url = url
        selection.filename = filename
        selection.status = 'installed'
        await selection.save()
      } else {
        await WikipediaSelection.create({
          option_id: matchedOptionId || 'unknown',
          url: url,
          filename: filename,
          status: 'installed',
        })
      }

      logger.info(`[ZimService] Wikipedia download completed successfully: ${filename}`)

      // Delete prior versions of THIS specific Wikipedia variant only.
      // Earlier logic deleted anything starting with `wikipedia_en_`, which silently
      // wiped distinct corpora the user had installed independently (issue #884).
      const existingFiles = await this.list()
      const wikipediaFiles = findReplacedWikipediaFiles(
        filename,
        existingFiles.files.map((f) => f.name)
      )

      for (const oldFile of wikipediaFiles) {
        try {
          await this.delete(oldFile)
          logger.info(`[ZimService] Deleted old Wikipedia file: ${oldFile}`)
        } catch (error) {
          logger.warn(`[ZimService] Could not delete old Wikipedia file: ${oldFile}`, error)
        }
      }
    } else {
      // Download failed - update selection if it matches this file
      if (selection && (!selection.filename || selection.filename === filename)) {
        selection.status = 'failed'
        await selection.save()
        logger.error(`[ZimService] Wikipedia download failed for: ${filename}`)
      } else {
        logger.error(`[ZimService] Wikipedia download failed for: ${filename} (no matching selection)`)
      }
    }
  }

  // Custom library source management

  async listCustomLibraries(): Promise<CustomLibrarySource[]> {
    return CustomLibrarySource.all()
  }

  async addCustomLibrary(name: string, baseUrl: string): Promise<CustomLibrarySource> {
    const count = await CustomLibrarySource.query().count('* as total')
    const total = Number(count[0].$extras.total)
    if (total >= 10) {
      throw new Error('Maximum of 10 custom libraries allowed')
    }

    // Ensure URL ends with /
    const normalizedUrl = baseUrl.endsWith('/') ? baseUrl : baseUrl + '/'

    return CustomLibrarySource.create({
      name,
      base_url: normalizedUrl,
    })
  }

  async removeCustomLibrary(id: number): Promise<void> {
    const source = await CustomLibrarySource.find(id)
    if (!source) {
      throw new Error('Custom library not found')
    }
    if (source.is_default) {
      throw new Error('Cannot remove a built-in mirror')
    }
    await source.delete()
  }

  async browseLibraryUrl(url: string): Promise<{
    directories: { name: string; url: string }[]
    files: { name: string; url: string; size_bytes: number | null }[]
  }> {
    assertNotPrivateUrl(url)

    const normalizedUrl = url.endsWith('/') ? url : url + '/'

    const res = await axios.get(normalizedUrl, {
      responseType: 'text',
      timeout: 15000,
      headers: {
        'Accept': 'text/html',
      },
    })

    const html: string = res.data
    const directories: { name: string; url: string }[] = []
    const files: { name: string; url: string; size_bytes: number | null }[] = []

    const $ = cheerio.load(html)

    $('a').each((_, el) => {
      const href = el.attribs?.href
      if (!href || href === '../' || href === './' || href === '/' || href.startsWith('?') || href.startsWith('#')) {
        return
      }
      if (href.startsWith('/') || href.startsWith('http://') || href.startsWith('https://')) {
        return
      }

      if (href.endsWith('/')) {
        const dirName = decodeURIComponent(href.replace(/\/$/, ''))
        directories.push({
          name: dirName,
          url: new URL(href, normalizedUrl).toString(),
        })
        return
      }

      if (href.endsWith('.zim')) {
        const fileName = decodeURIComponent(href)

        // Apache/Nginx autoindex put the date + size in the text node directly
        // following </a> within a <pre>. Walk forward across text siblings until
        // we find a parseable size token.
        let trailingText = ''
        let sibling = el.next
        while (sibling && sibling.type === 'text') {
          trailingText += sibling.data
          if (/\n/.test(sibling.data)) break
          sibling = sibling.next
        }

        files.push({
          name: fileName,
          url: new URL(href, normalizedUrl).toString(),
          size_bytes: this._parseListingSize(trailingText),
        })
      }
    })

    directories.sort((a, b) => a.name.localeCompare(b.name))
    files.sort((a, b) => a.name.localeCompare(b.name))

    return { directories, files }
  }

  /**
   * Parse a directory-listing size token out of the text that follows an anchor.
   * Apache renders e.g. `   2024-01-15 10:30  5.1G`; Nginx renders raw bytes.
   * Returns bytes or null if no size token is found.
   */
  private _parseListingSize(text: string): number | null {
    // Skip the date/time columns; grab the last numeric token (with optional suffix)
    // before a newline. Matches `5.1G`, `5368709120`, `1.2T`, etc.
    const sizeMatch = /([\d.]+\s*[KMGT]?B?|\d+)\s*$/i.exec(text.split('\n')[0].trim())
    if (!sizeMatch) return null

    const sizeStr = sizeMatch[1].replace(/\s|B$/gi, '')
    const num = parseFloat(sizeStr)
    if (isNaN(num)) return null

    if (/^\d+$/.test(sizeStr)) return num

    const suffix = sizeStr.slice(-1).toUpperCase()
    const multipliers: Record<string, number> = { K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 }
    return multipliers[suffix] ? Math.round(num * multipliers[suffix]) : null
  }
}

/**
 * Map an AMD GPU's gfx target to the `HSA_OVERRIDE_GFX_VERSION` value the ollama:rocm
 * container needs, or `null` when the card is discovered natively and no override should
 * be applied.
 *
 * This is intentionally a pure function so the mapping is unit-testable without
 * constructing the Docker service or touching the container runtime. `DockerService`
 * delegates its private `_mapGfxToHsaOverride` to this.
 *
 * The bundled `ollama/ollama:rocm` rocblas ships kernels for a fixed allowlist — as seen
 * in ollama's own startup log:
 *   supported=[gfx1030, gfx1100/1101/1102, gfx1150/1151, gfx1200/1201, gfx908/90a/942/950]
 * A target NOT in that list is dropped to CPU unless we coerce it onto a supported one via
 * HSA_OVERRIDE_GFX_VERSION.
 *
 * Mapping:
 *  - gfx1030 / gfx1100 / gfx1101 / gfx1102 → none. Discrete RDNA 2/3 on the allowlist;
 *    forcing an override here breaks GPU discovery.
 *  - gfx1150 / gfx1151 (Strix 890M, Strix Halo) → none. RDNA 3.5 iGPUs that ARE on the
 *    allowlist under the bundled ROCm, so native discovery works. (#1076 got this right.)
 *  - gfx1103 (Phoenix/Hawk Point 780M/760M) → '11.0.0'. RDNA 3 iGPU that is NOT on the
 *    allowlist, so it must be coerced onto gfx1100's kernels. #1076 wrongly grouped it with
 *    gfx1150/1151 and dropped the override, silently sending the 780M to CPU (the very
 *    common iGPU this regression hit). 11.0.0 is the value that worked on v1.33.0 and that
 *    restores full GPU offload in the field; #1076's "gfx1100 WMMA fault" theory did not
 *    hold up.
 *  - gfx1031..gfx1036 (RDNA 2 iGPUs, e.g. Rembrandt 680M) → '10.3.0'. Not on the allowlist;
 *    coerce onto gfx1030.
 *  - anything else (unknown/newer target) → none. Prefer native discovery over a coercion
 *    that's likely wrong; a hardcoded default gets more wrong as ROCm adds native targets.
 */
export function mapGfxToHsaOverride(gfx: string): string | null {
  // Officially supported by the bundled ROCm — no override needed.
  if (gfx === 'gfx1030' || gfx === 'gfx1100' || gfx === 'gfx1101' || gfx === 'gfx1102') {
    return null
  }
  // RDNA 3.5 iGPUs (Strix 890M = gfx1150, Strix Halo = gfx1151) — natively supported.
  if (gfx === 'gfx1150' || gfx === 'gfx1151') {
    return null
  }
  // RDNA 3 Phoenix/Hawk Point (780M/760M = gfx1103) — NOT on the rocblas allowlist; coerce
  // to gfx1100 kernels or ollama drops it to CPU.
  if (gfx === 'gfx1103') {
    return '11.0.0'
  }
  // RDNA 2 variants + iGPUs (gfx1031..gfx1036, e.g. Rembrandt 680M) — coerce to gfx1030.
  if (/^gfx103[1-6]$/.test(gfx)) {
    return '10.3.0'
  }
  // Unknown/newer target: prefer native discovery over a coercion that's likely wrong.
  return null
}

const HSA_OVERRIDE_ENV_PREFIX = 'HSA_OVERRIDE_GFX_VERSION='
const HSA_OVERRIDE_VALUE_RE = /^\d+\.\d+\.\d+$/

/** The raw HSA_OVERRIDE_GFX_VERSION in a container env, or null when it is not set. */
export function readHsaOverrideFromEnv(env: string[] | null | undefined): string | null {
  const entry = (env ?? []).find((e) => e.startsWith(HSA_OVERRIDE_ENV_PREFIX))
  return entry ? entry.slice(HSA_OVERRIDE_ENV_PREFIX.length) : null
}

export type AmdHsaOverrideResolution = {
  value: string | null
  source: 'kv' | 'kv-disabled' | 'marker' | 'container' | 'default'
  /** Set when the KV held something unusable and was skipped. */
  invalidManual?: string
}

/**
 * Pick the HSA_OVERRIDE_GFX_VERSION an AMD install should apply. Resolution order:
 *   1. KV `ai.amdHsaOverride`: a version forces it, 'none'/'off'/'false' disables it.
 *   2. The gfx marker install_nomad.sh writes, mapped through mapGfxToHsaOverride. A
 *      marker is authoritative even when it maps to none.
 *   3. The override the existing container already runs with (#1377). Upgraded installs
 *      that got it by hand or from an older install path have neither 1 nor 2, and
 *      dropping a working override would push the GPU back to CPU.
 *   4. None, letting ROCm discover the GPU natively.
 */
export function pickAmdHsaOverride(input: {
  manual: unknown
  markerGfx: string | null
  containerEnv?: string[] | null
}): AmdHsaOverrideResolution {
  let invalidManual: string | undefined
  if (input.manual !== null && input.manual !== undefined && String(input.manual).trim() !== '') {
    const manual = String(input.manual).trim().toLowerCase()
    if (manual === 'none' || manual === 'off' || manual === 'false') {
      return { value: null, source: 'kv-disabled' }
    }
    if (HSA_OVERRIDE_VALUE_RE.test(manual)) return { value: manual, source: 'kv' }
    invalidManual = String(input.manual)
  }
  const extra = invalidManual !== undefined ? { invalidManual } : {}

  if (input.markerGfx !== null) {
    return { value: mapGfxToHsaOverride(input.markerGfx), source: 'marker', ...extra }
  }

  const existing = readHsaOverrideFromEnv(input.containerEnv)?.trim()
  if (existing && HSA_OVERRIDE_VALUE_RE.test(existing)) {
    return { value: existing, source: 'container', ...extra }
  }

  return { value: null, source: 'default', ...extra }
}

import type { MultipartFile } from '@adonisjs/bodyparser/types'
import type { ChatCompletionMessageParam } from 'openai/resources/chat/completions.js'
import sharp from 'sharp'

export const MAX_CHAT_IMAGES = 4
export const MAX_CHAT_IMAGE_BYTES = 8 * 1024 * 1024
export const MAX_CHAT_IMAGE_PIXELS = 40_000_000
export const MAX_NORMALIZED_IMAGE_BYTES = 4 * 1024 * 1024
export const MAX_NORMALIZED_IMAGE_DIMENSION = 2048

const SUPPORTED_IMAGE_FORMATS = new Set(['jpeg', 'png', 'webp'])

export class ChatImageError extends Error {
  constructor(
    message: string,
    public readonly status: 413 | 415 | 422
  ) {
    super(message)
    this.name = 'ChatImageError'
  }
}

export type NormalizedChatImage = {
  name: string
  dataUrl: string
}

export async function normalizeChatImages(files: MultipartFile[]): Promise<NormalizedChatImage[]> {
  if (files.length > MAX_CHAT_IMAGES) {
    throw new ChatImageError(`Attach no more than ${MAX_CHAT_IMAGES} images.`, 422)
  }

  const normalized: NormalizedChatImage[] = []
  for (const file of files) {
    normalized.push(await normalizeChatImage(file))
  }
  return normalized
}

async function normalizeChatImage(file: MultipartFile): Promise<NormalizedChatImage> {
  if (!file.tmpPath) {
    throw new ChatImageError(`Could not process "${file.clientName}".`, 422)
  }
  if (file.size > MAX_CHAT_IMAGE_BYTES) {
    throw new ChatImageError(`"${file.clientName}" exceeds the 8 MB per-image limit.`, 413)
  }
  if (!file.isValid) {
    throw new ChatImageError(`"${file.clientName}" is not a valid image upload.`, 422)
  }

  try {
    const pipeline = sharp(file.tmpPath, {
      animated: false,
      failOn: 'warning',
      limitInputPixels: MAX_CHAT_IMAGE_PIXELS,
    })
    const metadata = await pipeline.metadata()

    if (!metadata.format || !SUPPORTED_IMAGE_FORMATS.has(metadata.format)) {
      throw new ChatImageError(
        `"${file.clientName}" is not supported. Use JPEG, PNG, or WebP.`,
        415
      )
    }
    if ((metadata.pages ?? 1) > 1) {
      throw new ChatImageError(`Animated images are not supported.`, 415)
    }

    const normalized = await pipeline
      .rotate()
      .resize({
        width: MAX_NORMALIZED_IMAGE_DIMENSION,
        height: MAX_NORMALIZED_IMAGE_DIMENSION,
        fit: 'inside',
        withoutEnlargement: true,
      })
      .flatten({ background: '#ffffff' })
      .jpeg({ quality: 85 })
      .toBuffer()

    if (normalized.byteLength > MAX_NORMALIZED_IMAGE_BYTES) {
      throw new ChatImageError(
        `"${file.clientName}" remains too large after image processing.`,
        413
      )
    }

    return {
      name: file.clientName,
      dataUrl: `data:image/jpeg;base64,${normalized.toString('base64')}`,
    }
  } catch (error) {
    if (error instanceof ChatImageError) throw error
    throw new ChatImageError(`"${file.clientName}" could not be decoded as an image.`, 422)
  }
}

export function attachImagesToLatestUserMessage(
  messages: Array<{ role: 'system' | 'user' | 'assistant'; content: string }>,
  images: NormalizedChatImage[]
): ChatCompletionMessageParam[] {
  if (images.length === 0) return messages

  let latestUserIndex = -1
  messages.forEach((message, index) => {
    if (message.role === 'user') latestUserIndex = index
  })
  if (latestUserIndex < 0) {
    throw new ChatImageError('Images require a user message.', 422)
  }

  return messages.map((message, index) => {
    if (index !== latestUserIndex) return message
    return {
      role: 'user',
      content: [
        { type: 'text', text: message.content },
        ...images.map((image) => ({
          type: 'image_url' as const,
          image_url: { url: image.dataUrl },
        })),
      ],
    }
  })
}

import logger from '@adonisjs/core/services/logger'
import type InstalledResource from '#models/installed_resource'

/**
 * Per-resource failure backoff for content (ZIM/map) auto-updates, shared by the
 * three places that observe an auto-update's real lifecycle:
 *
 *   - {@link ContentAutoUpdateService.attempt} — a dispatch that fails to even
 *     enqueue (counts as a failure; no job runs so no terminal event follows).
 *   - `RunDownloadJob.onComplete` — a download that actually finished (success).
 *   - the worker `failed` handler in `commands/queue/work.ts` — a download that
 *     exhausted its retries (terminal failure).
 *
 * Kept in a dependency-light util (not on ContentAutoUpdateService) on purpose:
 * RunDownloadJob is imported by CollectionUpdateService, which is imported by
 * ContentAutoUpdateService, so importing the service back into the job would
 * close an import cycle. Only the InstalledResource model and the logger are
 * touched here.
 */

/** Genuine consecutive auto-update failures before a resource self-disables. */
export const MAX_CONSECUTIVE_FAILURES = 3

/** Clear a resource's failure backoff after a successful auto-update. */
export async function recordResourceUpdateSuccess(resource: InstalledResource): Promise<void> {
  if (resource.auto_update_consecutive_failures === 0 && !resource.auto_update_disabled_reason) {
    return
  }
  resource.auto_update_consecutive_failures = 0
  resource.auto_update_disabled_reason = null
  await resource.save()
}

/** Record an auto-update failure and self-disable the resource at the threshold. */
export async function recordResourceUpdateFailure(
  resource: InstalledResource,
  reason: string
): Promise<void> {
  const failures = (resource.auto_update_consecutive_failures || 0) + 1
  resource.auto_update_consecutive_failures = failures
  if (failures >= MAX_CONSECUTIVE_FAILURES) {
    resource.auto_update_disabled_reason = `Auto-update disabled after ${failures} consecutive failures. Last error: ${reason}`
    logger.error(
      `[ContentAutoUpdate] ${resource.resource_id} auto-disabled after ${failures} failures`
    )
  }
  await resource.save()
  logger.error(
    `[ContentAutoUpdate] ${resource.resource_id} failure ${failures}/${MAX_CONSECUTIVE_FAILURES}: ${reason}`
  )
}

/**
 * Decides what actually goes into the prompt, and what gets left out.
 *
 * Before this existed, nothing trimmed anything: the browser posted the whole
 * session, the pipeline copied it verbatim, and overflow was left to the
 * backend. That is the worst possible arrangement, because backend truncation is
 * *silent* and *positional* — llama.cpp drops from the middle of the window, so
 * what gets discarded is conversation history and retrieved knowledge-base
 * context, while the model gives no indication anything is missing. Measured on
 * a live Ollama, a 7,000-token prompt came back having processed 2,060 tokens,
 * and the model confabulated an answer from the fragment that survived.
 *
 * So the rule here is: never hand the backend more than it can hold. Decide
 * explicitly what to drop, drop it in a way the model can reason about, and
 * record what happened so the eval harness can see it.
 *
 * Allocation order, most protected first:
 *   1. Response reserve  — a floor held back for the answer itself. The actual
 *                          generation cap is whatever the window has left once
 *                          the prompt is assembled, which is usually far more.
 *   2. Fixed blocks      — system prompts and the current question. Never dropped.
 *   3. Retrieved context — whole chunks, best-first, until its share is spent.
 *   4. History           — whole turns, newest-first, into whatever remains.
 *
 * Pure and dependency-free so it runs under bare `node --test`, the same
 * convention as `rag_prompt.ts`.
 */

import { estimateMessagesTokens, estimateTokens } from './token_estimate.js'

export type BudgetRole = 'system' | 'user' | 'assistant'
export type BudgetMessage = { role: BudgetRole; content: string }

/** A retrieved chunk, already ranked — index 0 is the best match. */
export type BudgetChunk = { text: string; metadata?: Record<string, any> }

/**
 * Where the per-turn retrieved-context block goes.
 *
 * `tail` places it immediately before the current question, leaving
 * [system][history] as a byte-identical prefix across turns so the backend can
 * reuse its KV cache. `front` is the historical behaviour: a system message
 * ahead of all history, which changes content every turn and therefore
 * invalidates the cached prefix for the entire conversation behind it.
 *
 * The common advice to "inject RAG into the system prompt" assumes the context
 * is fixed for the session (an attached document), where a fixed position does
 * preserve the prefix. When context is re-retrieved every turn, the opposite is
 * true. Both are kept so `eval:generation` can measure the difference rather
 * than the choice resting on argument alone.
 */
export type RagPlacement = 'tail' | 'front'

export type BudgetInputs = {
  /** Stable system blocks (NOMAD.md, formatting rules), in final order. */
  systemBlocks: BudgetMessage[]
  /** Prior conversation, oldest first, excluding the current question. */
  history: BudgetMessage[]
  /** The current user message. Never dropped. */
  query: BudgetMessage
  /** Retrieved chunks, best first. May be empty. */
  ragChunks: BudgetChunk[]
  /** Renders surviving chunks into the final context message. */
  renderRagBlock: (chunks: BudgetChunk[]) => string
  /** The resolved context window, in tokens. */
  contextWindow: number
  /** Learned per-model token-estimator correction. */
  ratio?: number
  ragPlacement?: RagPlacement
  /** Overrides for the response reserve and RAG share; mostly for tests. */
  responseReserve?: number
  ragShare?: number
}

export type BudgetTrace = {
  contextWindow: number
  responseReserve: number
  promptBudget: number
  estimatedPromptTokens: number
  systemTokens: number
  queryTokens: number
  ragTokens: number
  historyTokens: number
  chunksKept: number
  chunksDropped: number
  turnsKept: number
  turnsDropped: number
  historyElided: boolean
  queryTruncated: boolean
  ragPlacement: RagPlacement
  numPredict: number
}

export type BudgetResult = {
  messages: BudgetMessage[]
  trace: BudgetTrace
  /**
   * What to send as num_predict: the space the window actually has left after
   * the prompt, less a margin for estimator error. Never below the reserve.
   */
  numPredict: number
}

/**
 * Ceiling on tokens reserved for the answer.
 *
 * This only bounds how much prompt space is held back; it is not the
 * generation cap. It used to double as one, which pinned every answer at 1024
 * tokens regardless of window size and cut long answers off mid-sentence
 * (#1342).
 */
export const MAX_RESPONSE_RESERVE = 8192
/** Share of the window reserved for the answer when that is smaller. */
export const RESPONSE_RESERVE_FRACTION = 0.25
/**
 * Headroom left between the estimated prompt and the end of the window when
 * sizing num_predict. The estimator is calibrated per model but still only an
 * estimate; undershooting here means llama.cpp context-shifts mid-answer.
 */
export const NUM_PREDICT_SAFETY_FRACTION = 0.05
export const NUM_PREDICT_SAFETY_MIN = 64
/** Share of the remaining budget the retrieved context may claim. */
export const DEFAULT_RAG_SHARE = 0.35

/**
 * Marker inserted where turns were dropped.
 *
 * Worth the handful of tokens: without it the model sees a conversation that
 * appears to begin mid-thought and has no way to tell that it is missing
 * context, which is exactly when small models start confidently inventing what
 * "we discussed earlier".
 */
export const ELISION_MARKER =
  '[Earlier messages in this conversation have been omitted to fit the context window.]'

/**
 * Turns are dropped in blocks rather than one at a time.
 *
 * Dropping a single turn per request would shift the prompt prefix on *every*
 * subsequent turn, invalidating the backend's KV cache each time — trading a
 * small saving in tokens for a full re-prefill. Dropping several at once means
 * the prefix then stays stable for several turns.
 */
export const HISTORY_EVICTION_BLOCK = 4

/**
 * Group a flat message list into whole turns.
 *
 * A turn is a user message plus everything that answers it. Truncating on a
 * message boundary instead can leave the transcript starting with an assistant
 * reply to a question the model can no longer see — which reads, to the model,
 * as though it said something unprompted.
 */
export function groupIntoTurns(history: BudgetMessage[]): BudgetMessage[][] {
  const turns: BudgetMessage[][] = []
  for (const message of history) {
    if (message.role === 'user' || turns.length === 0) {
      turns.push([message])
    } else {
      turns[turns.length - 1].push(message)
    }
  }
  return turns
}

/**
 * Plan the prompt.
 *
 * Never returns a message array estimated to exceed `contextWindow -
 * responseReserve`, except in the degenerate case where the fixed blocks alone
 * are too large — and in that case the query is truncated visibly rather than
 * being handed to the backend to cut silently.
 */
export function planPrompt(inputs: BudgetInputs): BudgetResult {
  const ratio = inputs.ratio ?? 1
  const placement = inputs.ragPlacement ?? 'tail'
  const contextWindow = inputs.contextWindow

  const responseReserve =
    inputs.responseReserve ??
    Math.max(256, Math.min(MAX_RESPONSE_RESERVE, Math.floor(contextWindow * RESPONSE_RESERVE_FRACTION)))
  const promptBudget = Math.max(0, contextWindow - responseReserve)

  const cost = (messages: BudgetMessage[]) => estimateMessagesTokens(messages, ratio)

  // --- Fixed blocks: system prompts and the question --------------------
  const systemTokens = cost(inputs.systemBlocks)
  let query = inputs.query
  let queryTokens = cost([query])
  let queryTruncated = false

  // Degenerate case: the system prompts plus the question alone overflow the
  // window. Truncating here is a bad outcome, but it is a *visible* one — the
  // alternative is the backend silently cutting the question in half.
  if (systemTokens + queryTokens > promptBudget) {
    const available = Math.max(0, promptBudget - systemTokens)
    if (available > 0) {
      const perToken = query.content.length / Math.max(1, estimateTokens(query.content, ratio))
      const keepChars = Math.max(0, Math.floor(available * perToken) - ELISION_MARKER.length)
      query = {
        ...query,
        content:
          query.content.slice(0, keepChars) +
          '\n\n[This message was truncated because it exceeds the context window.]',
      }
      queryTokens = cost([query])
      queryTruncated = true
    }
  }

  let remaining = promptBudget - systemTokens - queryTokens

  // --- Retrieved context: whole chunks, best first ----------------------
  //
  // Whole chunks, deliberately. The previous behaviour capped on a running
  // character count, which could hand the model a chunk cut off mid-sentence —
  // the worst of both worlds, since it costs tokens without carrying a complete
  // fact. A chunk that doesn't fit is dropped, not shortened.
  const ragBudget = Math.max(0, Math.floor(Math.max(0, remaining) * (inputs.ragShare ?? DEFAULT_RAG_SHARE)))
  const keptChunks: BudgetChunk[] = []
  let ragTokens = 0

  if (inputs.ragChunks.length > 0 && ragBudget > 0) {
    for (const chunk of inputs.ragChunks) {
      const candidate = [...keptChunks, chunk]
      const rendered = inputs.renderRagBlock(candidate)
      const candidateTokens = cost([{ role: 'system', content: rendered }])
      if (candidateTokens <= ragBudget) {
        keptChunks.push(chunk)
        ragTokens = candidateTokens
      }
      // Keep scanning: a later, smaller chunk may still fit where this one didn't.
    }
  }

  const ragMessage: BudgetMessage | null =
    keptChunks.length > 0
      ? { role: 'system', content: inputs.renderRagBlock(keptChunks) }
      : null

  remaining -= ragTokens

  // --- History: whole turns, newest first -------------------------------
  const turns = groupIntoTurns(inputs.history)
  const keptTurns: BudgetMessage[][] = []
  let historyTokens = 0

  for (let i = turns.length - 1; i >= 0; i--) {
    const turnTokens = cost(turns[i])
    if (historyTokens + turnTokens > remaining) break
    keptTurns.unshift(turns[i])
    historyTokens += turnTokens
  }

  const turnsDropped = turns.length - keptTurns.length

  // Chunky eviction: once we're dropping anything, drop a whole block, so the
  // surviving prefix stays put for the next several turns instead of shifting
  // on every request and forcing a re-prefill each time.
  if (turnsDropped > 0 && keptTurns.length > 0) {
    const overshoot = turnsDropped % HISTORY_EVICTION_BLOCK
    const extra = overshoot === 0 ? 0 : HISTORY_EVICTION_BLOCK - overshoot
    for (let i = 0; i < extra && keptTurns.length > 1; i++) {
      const removed = keptTurns.shift()!
      historyTokens -= cost(removed)
    }
  }

  const historyElided = keptTurns.length < turns.length
  const historyMessages = keptTurns.flat()

  // --- Assemble, stability-descending -----------------------------------
  const messages: BudgetMessage[] = []
  messages.push(...inputs.systemBlocks)
  if (historyElided) {
    messages.push({ role: 'system', content: ELISION_MARKER })
  }

  if (placement === 'front' && ragMessage) {
    // Historical ordering, kept only so the two can be compared under eval.
    messages.splice(inputs.systemBlocks.length, 0, ragMessage)
    messages.push(...historyMessages)
  } else {
    messages.push(...historyMessages)
    if (ragMessage) messages.push(ragMessage)
  }
  messages.push(query)

  const estimatedPromptTokens = cost(messages)

  // The planner already kept the prompt within `contextWindow - responseReserve`,
  // so the reserve floor can never push generation past the window.
  const safetyMargin = Math.max(
    NUM_PREDICT_SAFETY_MIN,
    Math.ceil(estimatedPromptTokens * NUM_PREDICT_SAFETY_FRACTION)
  )
  const numPredict = Math.max(responseReserve, contextWindow - estimatedPromptTokens - safetyMargin)

  return {
    messages,
    numPredict,
    trace: {
      contextWindow,
      responseReserve,
      promptBudget,
      estimatedPromptTokens,
      systemTokens,
      queryTokens,
      ragTokens,
      historyTokens,
      chunksKept: keptChunks.length,
      chunksDropped: inputs.ragChunks.length - keptChunks.length,
      turnsKept: keptTurns.length,
      turnsDropped: turns.length - keptTurns.length,
      historyElided,
      queryTruncated,
      ragPlacement: placement,
      numPredict,
    },
  }
}

/**
 * Pure helpers for deciding how large a model's context window should be.
 *
 * Kept out of OllamaService so they can run under bare `node --test` with no
 * Ollama, Docker, or MySQL — the same convention as `rag_prompt.ts`. The service
 * supplies the facts (what /api/show said, how much memory is free); everything
 * here is a function of its arguments.
 */

/**
 * Ladder of context sizes we're willing to request.
 *
 * Snapping to a ladder is not cosmetic. Ollama unloads and reloads a model
 * whenever a request asks for a different `num_ctx` than the loaded instance, so
 * a continuously-varying window would stall a turn and throw away the KV cache
 * every time the conversation grew. Snapping (plus per-model memoization in the
 * resolver) keeps the value constant for a session.
 */
export const CONTEXT_LADDER = [4096, 8192, 16384, 32768, 65536, 131072] as const

/** Never go below this: it is roughly a system prompt plus a few real turns. */
export const MIN_CONTEXT = 4096

/**
 * Fallback window when the backend can't tell us anything — a non-Ollama
 * OpenAI-compatible server, or /api/show unavailable. Deliberately modest:
 * budgeting too small wastes capacity, budgeting too large silently truncates.
 */
export const UNKNOWN_BACKEND_CONTEXT = 8192

/**
 * Read the trained context length out of an /api/show `model_info` blob.
 *
 * Keys are architecture-prefixed (`llama.context_length`, `qwen3.context_length`,
 * `gemma3.context_length`, ...), so prefer the prefix named by
 * `general.architecture` and fall back to any `*.context_length` key. Ollama's
 * client types this as a Map but the wire format is a plain object; handle both.
 */
export function readContextLength(modelInfo: unknown): number | undefined {
  if (!modelInfo) return undefined
  const entries: [string, any][] =
    modelInfo instanceof Map
      ? [...modelInfo.entries()]
      : typeof modelInfo === 'object'
        ? Object.entries(modelInfo as Record<string, any>)
        : []
  if (entries.length === 0) return undefined

  const lookup = new Map(entries)
  const arch = lookup.get('general.architecture')
  if (typeof arch === 'string') {
    const exact = lookup.get(`${arch}.context_length`)
    if (typeof exact === 'number' && exact > 0) return exact
  }

  for (const [key, value] of entries) {
    if (key.endsWith('.context_length') && typeof value === 'number' && value > 0) {
      return value
    }
  }
  return undefined
}

/**
 * Pull `num_ctx` out of the `parameters` string /api/show returns (the modelfile
 * PARAMETER lines, e.g. `num_ctx                        8192`). When a model
 * author baked in a window, that is a deliberate signal worth respecting as a
 * ceiling hint.
 */
export function readModelfileNumCtx(parameters: unknown): number | undefined {
  if (typeof parameters !== 'string') return undefined
  const match = parameters.match(/^\s*num_ctx\s+(\d+)\s*$/m)
  if (!match) return undefined
  const value = Number.parseInt(match[1], 10)
  return Number.isFinite(value) && value > 0 ? value : undefined
}

/**
 * Parse Ollama's `details.parameter_size` ("8.0B", "1.5B", "70B") into billions.
 * Falls back to the tag-name regex — which is what the codebase used to rely on
 * exclusively, and which guesses wrong on names like "phi3" that carry no size.
 */
export function parseParameterBillions(
  parameterSize: string | undefined,
  modelName?: string
): number | undefined {
  const fromDetails = parameterSize?.match(/([\d.]+)\s*B/i)
  if (fromDetails) {
    const value = Number.parseFloat(fromDetails[1])
    if (Number.isFinite(value)) return value
  }
  const fromName = modelName?.match(/(\d+\.?\d*)\s*[bB](?![a-zA-Z])/)
  if (fromName) {
    const value = Number.parseFloat(fromName[1])
    if (Number.isFinite(value)) return value
  }
  return undefined
}

/** Round a token count down to the largest ladder rung that fits. */
export function snapToLadder(tokens: number): number {
  let chosen = MIN_CONTEXT
  for (const rung of CONTEXT_LADDER) {
    if (rung <= tokens) chosen = rung
  }
  return chosen
}

// ---------------------------------------------------------------------------
// How much memory a context window actually costs
// ---------------------------------------------------------------------------

/**
 * Bytes per element in the KV cache.
 *
 * Budgeted at f16 (2 bytes) even though the Ollama container is started with
 * `OLLAMA_KV_CACHE_TYPE=q8_0`. Ollama silently falls back to f16 on
 * architectures that don't support cache quantization, so treating q8_0 as
 * guaranteed would double the real cost of every window we hand out. Quantized
 * cache is headroom, not a budgeting assumption.
 */
const KV_BYTES_PER_ELEMENT = 2

/**
 * Exact KV-cache cost per token, from the model's own GGUF metadata.
 *
 *     2 (K and V) x layers x kv_heads x head_dim x bytes_per_element
 *
 * For llama3:8b that is 2 x 32 x 8 x 128 x 2 = 128 KiB per token, so an 8k
 * window costs 1 GiB — which is why "just set num_ctx high" is not free advice
 * on the hardware NOMAD targets.
 *
 * Returns undefined when the metadata is missing (non-Ollama backend, or an
 * architecture that names its keys differently), leaving the caller to fall back
 * to `estimateKvBytesPerToken`.
 */
export function computeKvBytesPerToken(modelInfo: unknown): number | undefined {
  if (!modelInfo) return undefined
  const entries: [string, any][] =
    modelInfo instanceof Map
      ? [...modelInfo.entries()]
      : typeof modelInfo === 'object'
        ? Object.entries(modelInfo as Record<string, any>)
        : []
  if (entries.length === 0) return undefined
  const info = new Map(entries)

  const arch = info.get('general.architecture')
  if (typeof arch !== 'string') return undefined
  const num = (suffix: string): number | undefined => {
    const value = info.get(`${arch}.${suffix}`)
    return typeof value === 'number' && value > 0 ? value : undefined
  }

  const layers = num('block_count')
  // Grouped-query attention means KV heads are usually far fewer than attention
  // heads; using head_count here would overestimate cost several-fold.
  const kvHeads = num('attention.head_count_kv') ?? num('attention.head_count')
  if (!layers || !kvHeads) return undefined

  // Prefer explicit key/value lengths; otherwise derive head_dim from the
  // embedding width and the attention head count.
  let headDim = num('attention.key_length')
  if (!headDim) {
    const embedding = num('embedding_length')
    const heads = num('attention.head_count')
    if (embedding && heads) headDim = embedding / heads
  }
  if (!headDim) return undefined

  return 2 * layers * kvHeads * headDim * KV_BYTES_PER_ELEMENT
}

/**
 * Fallback KV cost per token when GGUF metadata is unavailable, interpolated
 * from the common architectures at each size. Deliberately pessimistic — an
 * overestimate costs a smaller window, an underestimate costs an OOM at load.
 */
export function estimateKvBytesPerToken(paramBillions: number | undefined): number {
  const b = paramBillions ?? 8
  if (b <= 1.5) return 32 * 1024
  if (b <= 4) return 64 * 1024
  if (b <= 9) return 128 * 1024
  if (b <= 15) return 192 * 1024
  if (b <= 35) return 256 * 1024
  return 512 * 1024
}

/**
 * Fraction of memory left free for weights-adjacent overhead: compute buffers,
 * activations, the graph, and whatever else shares the device. Without this the
 * arithmetic says a window fits right up to the byte and the model fails to load.
 */
const MEMORY_SAFETY_FRACTION = 0.8

export type ContextWindowInputs = {
  /** Trained context length from /api/show. The hard ceiling. */
  modelMaxCtx?: number
  /** num_ctx baked into the modelfile, treated as an author's ceiling hint. */
  modelfileNumCtx?: number
  /** Cost of one token of KV cache, exact or estimated. */
  kvBytesPerToken: number
  /** Memory available for the model, in bytes (VRAM, or a share of system RAM). */
  availableBytes?: number
  /** On-disk size of the weights, in bytes — they occupy the same pool. */
  modelBytes?: number
  /** User cap from `ai.contextWindow`. Only ever lowers the result. */
  userCap?: number
}

export type ContextWindowDecision = {
  contextWindow: number
  /** Which constraint actually bound the result — surfaced in logs and the UI. */
  limitedBy: 'user' | 'model' | 'memory' | 'floor' | 'default'
  affordableTokens?: number
}

/**
 * Decide the context window for a model.
 *
 * The result must be *stable for the life of the process*: Ollama unloads and
 * reloads a model whenever a request asks for a different num_ctx than the
 * loaded instance, which stalls the turn and discards the KV cache. Callers
 * memoize per model; this function is pure so that memoization is safe.
 */
export function resolveContextWindow(inputs: ContextWindowInputs): ContextWindowDecision {
  const ceilings: Array<{ value: number; source: ContextWindowDecision['limitedBy'] }> = []

  if (inputs.modelMaxCtx && inputs.modelMaxCtx > 0) {
    ceilings.push({ value: inputs.modelMaxCtx, source: 'model' })
  }
  if (inputs.modelfileNumCtx && inputs.modelfileNumCtx > 0) {
    ceilings.push({ value: inputs.modelfileNumCtx, source: 'model' })
  }
  if (inputs.userCap && inputs.userCap > 0) {
    ceilings.push({ value: inputs.userCap, source: 'user' })
  }

  let affordableTokens: number | undefined
  if (inputs.availableBytes && inputs.availableBytes > 0 && inputs.kvBytesPerToken > 0) {
    const forKv = inputs.availableBytes * MEMORY_SAFETY_FRACTION - (inputs.modelBytes ?? 0)
    affordableTokens = Math.max(0, Math.floor(forKv / inputs.kvBytesPerToken))
    ceilings.push({ value: affordableTokens, source: 'memory' })
  }

  if (ceilings.length === 0) {
    return { contextWindow: UNKNOWN_BACKEND_CONTEXT, limitedBy: 'default' }
  }

  const binding = ceilings.reduce((lowest, c) => (c.value < lowest.value ? c : lowest))
  const snapped = snapToLadder(binding.value)

  // The floor wins over a *memory* shortfall: a window under 4k is not worth
  // having, and Ollama will offload to host RAM rather than refuse. It must
  // never win over the model itself, though — asking for more than the trained
  // context pushes RoPE past what the weights ever saw and degrades output.
  // tinyllama (trained 2048) is the case that catches this.
  const hardCeiling = Math.min(
    ...[inputs.modelMaxCtx, inputs.modelfileNumCtx, inputs.userCap].filter(
      (v): v is number => typeof v === 'number' && v > 0
    ),
    Number.POSITIVE_INFINITY
  )

  if (snapped <= MIN_CONTEXT) {
    const floored = Math.min(MIN_CONTEXT, hardCeiling)
    return {
      contextWindow: floored,
      limitedBy: floored < MIN_CONTEXT ? 'model' : 'floor',
      affordableTokens,
    }
  }

  return { contextWindow: snapped, limitedBy: binding.source, affordableTokens }
}

/** Parse the `ai.contextWindow` setting. "auto"/unset/garbage all mean "no cap". */
export function parseUserContextCap(raw: string | null | undefined): number | undefined {
  if (!raw || raw === 'auto') return undefined
  const value = Number.parseInt(raw, 10)
  return Number.isFinite(value) && value >= MIN_CONTEXT ? value : undefined
}

import {
  DoResumableDownloadParams,
  DoResumableDownloadWithRetryParams,
} from '../../types/downloads.js'
import axios from 'axios'
import { Transform } from 'stream'
import { deleteFileIfExists, ensureDirectoryExists, getFileStatsIfExists } from './fs.js'
import { createWriteStream } from 'fs'
import { rename } from 'fs/promises'
import path from 'path'
import logger from '@adonisjs/core/services/logger'

/**
 * A gated source rejected this install's credentials (401/403).
 *
 * Permanent by nature: whether the entitlement key is baked in is a property of
 * the build, so no amount of retrying changes the answer. Declared here rather
 * than thrown as an UnrecoverableError directly so this module stays free of a
 * BullMQ dependency — RunDownloadJob translates it at the queue boundary.
 */
export class GatedContentAuthError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'GatedContentAuthError'
  }
}

// Some upstream mirrors reject requests with a missing or generic User-Agent.
// Notably, download.kiwix.org routes the large Wikimedia-family ZIMs (Wikipedia,
// Wikiversity, Wikibooks — including the flagship full Wikipedia) to
// dumps.wikimedia.org, which returns HTTP 403 for a default `axios/x` (or empty)
// User-Agent per Wikimedia's UA policy. Identify ourselves descriptively so
// those downloads succeed.
const DOWNLOAD_HEADERS: Record<string, string> = {
  'User-Agent': 'ProjectNOMAD/1.0 (+https://projectnomad.us)',
}

/**
 * Perform a resumable download with progress tracking
 * @param param0 - Download parameters. Leave allowedMimeTypes empty to skip mime type checking.
 * Otherwise, mime types should be in the format "application/pdf", "image/png", etc.
 * @returns Path to the downloaded file
 */
export async function doResumableDownload({
  url,
  filepath,
  timeout = 30000,
  signal,
  onProgress,
  onComplete,
  forceNew = false,
  allowedMimeTypes,
  requestHeaders,
}: DoResumableDownloadParams): Promise<string> {
  const dirname = path.dirname(filepath)
  await ensureDirectoryExists(dirname)

  // Stage download to a .tmp file so consumers (e.g. Kiwix) never see a partial file
  const tempPath = filepath + '.tmp'

  // Check if partial .tmp file exists for resume
  let startByte = 0
  let appendMode = false

  const existingStats = await getFileStatsIfExists(tempPath)
  if (existingStats && !forceNew) {
    startByte = Number(existingStats.size)
    appendMode = true
  }

  // Merge default headers with any caller-supplied headers (e.g. Creator Packs' Authorization)
  const headers: Record<string, string> = { ...DOWNLOAD_HEADERS, ...requestHeaders }

  // Get file info with HEAD request first. Gated sources (Creator Packs) require
  // the auth header on the HEAD too, or the probe 401s before the GET is reached.
  let headResponse
  try {
    headResponse = await axios.head(url, {
      signal,
      timeout,
      headers,
    })
  } catch (error: any) {
    // A 401/403 from a gated source is not a network problem and the raw axios
    // message ("Request failed with status code 401") reads like our server is
    // broken. Translate it, because the actual cause is almost always a build
    // without the entitlement key baked in — i.e. not an official release.
    // failedReason is surfaced verbatim on the downloads UI.
    const status = error?.response?.status
    if (status === 401 || status === 403) {
      throw new GatedContentAuthError(
        'This content is hosted by Project NOMAD and requires an official release build. ' +
          `The download server rejected this install's credentials (HTTP ${status}).`
      )
    }
    throw error
  }

  // Some upstream hosts (notably download.kiwix.org for .zim files) don't set a
  // Content-Type header at all. Per RFC 7231 §3.1.1.5, "if no Content-Type is
  // provided" the recipient may treat it as application/octet-stream — which is
  // already in every binary-content allowlist we use (ZIM, PMTILES, base assets).
  // Without this default, the validator below throws `MIME type  is not allowed`
  // and breaks all downloads from kiwix's primary host (#848).
  const contentType =
    headResponse.headers['content-type']?.toString() || 'application/octet-stream'
  const totalBytes = parseInt(headResponse.headers['content-length']?.toString() || '0', 10)
  const supportsRangeRequests = headResponse.headers['accept-ranges'] === 'bytes'

  // If allowedMimeTypes is provided, check content type
  if (allowedMimeTypes && allowedMimeTypes.length > 0) {
    const isMimeTypeAllowed = allowedMimeTypes.some((mimeType) => contentType.includes(mimeType))
    if (!isMimeTypeAllowed) {
      throw new Error(`MIME type ${contentType} is not allowed`)
    }
  }

  // If final file already exists at correct size, return early (idempotent)
  const finalFileStats = await getFileStatsIfExists(filepath)
  if (finalFileStats && Number(finalFileStats.size) === totalBytes && totalBytes > 0 && !forceNew) {
    return filepath
  }

  // If .tmp file is already at correct size (complete but never renamed), just rename it
  if (startByte === totalBytes && totalBytes > 0 && !forceNew) {
    await rename(tempPath, filepath)
    if (onComplete) {
      await onComplete(url, filepath)
    }
    return filepath
  }

  // If server doesn't support range requests and we have a partial .tmp file, delete it
  if (!supportsRangeRequests && startByte > 0) {
    await deleteFileIfExists(tempPath)
    startByte = 0
    appendMode = false
  }

  // A .tmp bigger than the file now on the server cannot be a prefix of it — the
  // publisher replaced the file under the same name (openZIM rolls builds forward,
  // see #1189/#1187). Resuming would ask for a range past the end and get a 416 on
  // every attempt, with nothing deleting the .tmp, so the download could never
  // recover on its own. Discard and start clean.
  if (startByte > totalBytes && totalBytes > 0) {
    logger.warn(
      `[Download] Discarding stale partial for ${filepath}: .tmp is ${startByte}B but the server reports ${totalBytes}B`
    )
    await deleteFileIfExists(tempPath)
    startByte = 0
    appendMode = false
  }

  // Add Range header if resuming
  if (supportsRangeRequests && startByte > 0) {
    headers.Range = `bytes=${startByte}-`
  }

  const fetchStream = (headers: Record<string, string>) =>
    axios.get(url, {
      responseType: 'stream',
      headers,
      signal,
      timeout,
    })

  let response = await fetchStream(headers)

  if (response.status !== 200 && response.status !== 206) {
    throw new Error(`Failed to download: HTTP ${response.status}`)
  }

  // If we requested a range but the server returned 200 (ignored the Range header),
  // appending would corrupt the .tmp file — delete it and restart from byte 0.
  if (headers.Range && response.status === 200) {
    response.data.destroy()
    await deleteFileIfExists(tempPath)
    startByte = 0
    appendMode = false
    delete headers.Range
    response = await fetchStream(headers)
    if (response.status !== 200 && response.status !== 206) {
      throw new Error(`Failed to download: HTTP ${response.status}`)
    }
  }

  return new Promise((resolve, reject) => {
    let downloadedBytes = startByte
    let lastProgressTime = Date.now()
    let lastDownloadedBytes = startByte

    // Stall detection: if no data arrives for 5 minutes, abort the download
    const STALL_TIMEOUT_MS = 5 * 60 * 1000
    let stallTimer: ReturnType<typeof setTimeout> | null = null

    const clearStallTimer = () => {
      if (stallTimer) {
        clearTimeout(stallTimer)
        stallTimer = null
      }
    }

    const resetStallTimer = () => {
      clearStallTimer()
      stallTimer = setTimeout(() => {
        cleanup(new Error('Download stalled - no data received for 5 minutes'))
      }, STALL_TIMEOUT_MS)
    }

    // Progress tracking stream to monitor data flow
    const progressStream = new Transform({
      transform(chunk: Buffer, _: any, callback: Function) {
        downloadedBytes += chunk.length
        resetStallTimer()

        // Update progress tracking
        const now = Date.now()
        if (onProgress && now - lastProgressTime >= 500) {
          lastProgressTime = now
          lastDownloadedBytes = downloadedBytes
          onProgress({
            downloadedBytes,
            totalBytes,
            lastProgressTime,
            lastDownloadedBytes,
            url,
          })
        }

        this.push(chunk)
        callback()
      },
    })

    const writeStream = createWriteStream(tempPath, {
      flags: appendMode ? 'a' : 'w',
    })

    const cleanup = (error?: Error) => {
      clearStallTimer()
      progressStream.destroy()
      response.data.destroy()
      writeStream.destroy()
      if (error) {
        reject(error)
      }
    }

    response.data.on('error', cleanup)
    progressStream.on('error', cleanup)
    writeStream.on('error', cleanup)

    signal?.addEventListener('abort', () => {
      cleanup(new Error('Download aborted'))
    })

    writeStream.on('finish', async () => {
      clearStallTimer()
      try {
        // Atomically move the completed .tmp file to the final path
        await rename(tempPath, filepath)
      } catch (renameError) {
        // A parallel job may have completed the same file first — treat as success
        // if the destination already exists at the expected size.
        const existing = await getFileStatsIfExists(filepath)
        if (existing && Number(existing.size) === totalBytes && totalBytes > 0) {
          // fall through to resolve
        } else {
          reject(renameError)
          return
        }
      }
      if (onProgress) {
        onProgress({
          downloadedBytes,
          totalBytes,
          lastProgressTime: Date.now(),
          lastDownloadedBytes: downloadedBytes,
          url,
        })
      }
      if (onComplete) {
        await onComplete(url, filepath)
      }
      resolve(filepath)
    })

    // Start stall timer and pipe: response -> progressStream -> writeStream
    resetStallTimer()
    response.data.pipe(progressStream).pipe(writeStream)
  })
}

export async function doResumableDownloadWithRetry({
  url,
  filepath,
  signal,
  timeout = 30000,
  onProgress,
  max_retries = 3,
  retry_delay = 2000,
  onAttemptError,
  allowedMimeTypes,
}: DoResumableDownloadWithRetryParams): Promise<string> {
  const dirname = path.dirname(filepath)
  await ensureDirectoryExists(dirname)

  let attempt = 0
  let lastError: Error | null = null

  while (attempt < max_retries) {
    try {
      const result = await doResumableDownload({
        url,
        filepath,
        signal,
        timeout,
        allowedMimeTypes,
        onProgress,
      })

      return result // return on success
    } catch (error: any) {
      attempt++
      lastError = error as Error

      const isAborted = error.name === 'AbortError' || error.code === 'ABORT_ERR'
      const isNetworkError =
        error.code === 'ECONNRESET' || error.code === 'ENOTFOUND' || error.code === 'ETIMEDOUT'

      onAttemptError?.(error, attempt)
      if (isAborted) {
        throw new Error(`Download aborted for URL: ${url}`)
      }

      if (attempt < max_retries && isNetworkError) {
        await delay(retry_delay)
        continue
      }

      // If max retries reached or non-retriable error, throw
      if (attempt >= max_retries || !isNetworkError) {
        throw error
      }
    }
  }

  // should not reach here, but TypeScript needs a return
  throw lastError || new Error('Unknown error during download')
}

async function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

import type { ZimCategoriesSpec } from '../../types/collections.js'

/**
 * Observed state of the FDA drug dataset, gathered at admin boot by
 * DrugInstallRowProvider.
 */
export interface DrugRowReconcileInput {
  /** Rows in `drug_labels`. */
  rowCount: number
  /** Whether the `installed_resources` 'dataset' row already exists. */
  hasInstallRow: boolean
  /** KV `drugReference.lastUpdatedExportDate`; only the final ingest pass sets it. */
  lastUpdatedExportDate: string | null
  /** Whether KV `drugReference.downloadState` still holds a marker. */
  hasDownloadMarker: boolean
  /** Whether either drug queue has an active/waiting/delayed job. */
  jobInFlight: boolean
}

export type DrugRowReconcileDecision =
  | { action: 'backfill'; version: string }
  | { action: 'skip'; reason: string }

/**
 * Decide whether a completed drug ingest is missing its `installed_resources`
 * row and should get one.
 *
 * On 1.34.0 the column was still enum('zim','map'), so every ingest finished
 * `ready` with 261k labels and a failed row write. The tier-status math reads
 * that row, so Medicine never resolved its Standard tier. The same state also
 * follows a manual ingest (no resourceMeta), including a reset-and-reingest.
 *
 * Backfill only when the ingest provably finished: the export-date marker is
 * written by the final pass, and the download marker is cleared right after it
 * (the same "completed" inference getIngestStatus() makes). A running job is
 * left alone, since it writes its own row on `ready`.
 */
export function decideDrugRowReconcile(input: DrugRowReconcileInput): DrugRowReconcileDecision {
  if (input.hasInstallRow) return { action: 'skip', reason: 'install row present' }
  if (input.rowCount <= 0) return { action: 'skip', reason: 'no drug labels ingested' }
  if (input.jobInFlight) return { action: 'skip', reason: 'drug download/ingest in flight' }
  if (input.hasDownloadMarker) {
    return { action: 'skip', reason: 'download marker present (ingest not finished)' }
  }
  const version = input.lastUpdatedExportDate?.trim()
  if (!version) return { action: 'skip', reason: 'no export date (ingest never completed)' }
  return { action: 'backfill', version }
}

/**
 * Slug of the curated category whose tiers carry the given dataset resource,
 * for the row's `collection_ref`. Null when the spec is absent or no tier lists it.
 */
export function findDatasetCategorySlug(
  spec: ZimCategoriesSpec | null,
  resourceId: string
): string | null {
  for (const category of spec?.categories ?? []) {
    for (const tier of category.tiers ?? []) {
      if ((tier.resources ?? []).some((r) => r.type === 'dataset' && r.id === resourceId)) {
        return category.slug
      }
    }
  }
  return null
}

