export async function listDirectoryContents(path: string): Promise<FileEntry[]> {
  const entries = await readdir(path, { withFileTypes: true })
  const results: FileEntry[] = []
  for (const entry of entries) {
    if (entry.isFile()) {
      results.push({
        type: 'file',
        key: join(path, entry.name),
        name: entry.name,
      })
    } else if (entry.isDirectory()) {
      results.push({
        type: 'directory',
        prefix: join(path, entry.name),
        name: entry.name,
      })
    }
  }
  return results
}

export async function listDirectoryContentsRecursive(path: string): Promise<FileEntry[]> {
  let results: FileEntry[] = []
  const entries = await readdir(path, { withFileTypes: true })
  for (const entry of entries) {
    const fullPath = join(path, entry.name)
    if (entry.isDirectory()) {
      const subdirectoryContents = await listDirectoryContentsRecursive(fullPath)
      results = results.concat(subdirectoryContents)
    } else {
      results.push({
        type: 'file',
        key: fullPath,
        name: entry.name,
      })
    }
  }
  return results
}

export async function ensureDirectoryExists(path: string): Promise<void> {
  try {
    await stat(path)
  } catch (error: any) {
    if (error.code === 'ENOENT') {
      await mkdir(path, { recursive: true })
    }
  }
}

export async function getFile(path: string, returnType: 'buffer'): Promise<Buffer | null>
export async function getFile(
  path: string,
  returnType: 'stream'
): Promise<NodeJS.ReadableStream | null>
export async function getFile(path: string, returnType: 'string'): Promise<string | null>
export async function getFile(
  path: string,
  returnType: 'buffer' | 'string' | 'stream' = 'buffer'
): Promise<Buffer | string | NodeJS.ReadableStream | null> {
  try {
    if (returnType === 'string') {
      return await readFile(path, 'utf-8')
    } else if (returnType === 'stream') {
      return createReadStream(path)
    }
    return await readFile(path)
  } catch (error: any) {
    if (error.code === 'ENOENT') {
      return null
    }
    throw error
  }
}

export async function getFileStatsIfExists(
  path: string
): Promise<{ size: number; modifiedTime: Date } | null> {
  try {
    const stats = await stat(path)
    return {
      size: stats.size,
      modifiedTime: stats.mtime,
    }
  } catch (error: any) {
    if (error.code === 'ENOENT') {
      return null
    }
    throw error
  }
}

/**
 * Validates that a file has the ZIM magic number (0x44D495A).
 * Must be called before passing a file to @openzim/libzim Archive,
 * because a corrupted ZIM causes a native C++ abort that cannot be
 * caught by JS try/catch.
 */
export async function isValidZimFile(filePath: string): Promise<boolean> {
  let fh
  try {
    fh = await open(filePath, 'r')
    const buf = Buffer.alloc(4)
    const { bytesRead } = await fh.read(buf, 0, 4, 0)
    if (bytesRead < 4) return false
    // ZIM magic number: 72 17 32 04 (little-endian 0x044D4953)
    return buf[0] === 0x5a && buf[1] === 0x49 && buf[2] === 0x4d && buf[3] === 0x04
  } catch {
    return false
  } finally {
    await fh?.close()
  }
}

export async function deleteFileIfExists(path: string): Promise<void> {
  try {
    await unlink(path)
  } catch (error: any) {
    if (error.code !== 'ENOENT') {
      throw error
    }
  }
}

export function getAllFilesystems(
  device: LSBlockDevice,
  fsSize: NomadDiskInfoRaw['fsSize']
): NomadDiskInfoRaw['fsSize'] {
  const filesystems: NomadDiskInfoRaw['fsSize'] = []
  const seen = new Set()

  function traverse(dev: LSBlockDevice) {
    // Try to find matching filesystem
    const fs = fsSize.find((f) => matchesDevice(f.fs, dev.name))

    if (fs && !seen.has(fs.fs)) {
      filesystems.push(fs)
      seen.add(fs.fs)
    }

    // Traverse children recursively
    if (dev.children) {
      dev.children.forEach((child) => traverse(child))
    }
  }

  traverse(device)
  return filesystems
}

export function matchesDevice(fsPath: string, deviceName: string): boolean {
  // Remove /dev/ and /dev/mapper/ prefixes
  const normalized = fsPath.replace('/dev/mapper/', '').replace('/dev/', '')

  // Direct match (covers /dev/sda1 ↔ sda1, /dev/nvme0n1p1 ↔ nvme0n1p1)
  if (normalized === deviceName) {
    return true
  }

  // LVM/device-mapper: e.g., /dev/mapper/ubuntu--vg-ubuntu--lv contains "ubuntu--lv"
  if (fsPath.startsWith('/dev/mapper/') && fsPath.includes(deviceName)) {
    return true
  }

  return false
}

export function determineFileType(filename: string): 'image' | 'pdf' | 'text' | 'docx' | 'epub' | 'zim' | 'unknown' {
  const ext = path.extname(filename).toLowerCase()
  if (['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.tiff', '.webp'].includes(ext)) {
    return 'image'
  } else if (ext === '.pdf') {
    return 'pdf'
  } else if (ext === '.docx') {
    return 'docx'
  } else if (['.txt', '.md', '.rtf'].includes(ext)) {
    return 'text'
  } else if (ext === '.epub') {
    return 'epub'
  } else if (ext === '.zim') {
    return 'zim'
  } else {
    return 'unknown'
  }
}

/**
 * Sanitize a filename by removing potentially dangerous characters.
 * @param filename The original filename
 * @returns The sanitized filename
 */
export function sanitizeFilename(filename: string): string {
  return filename.replace(/[^a-zA-Z0-9._-]/g, '_')
}

/**
 * Is this GPU "model" a placeholder rather than a real name?
 *
 * systeminformation resolves PCI ids against the container's pci.ids database.
 * When a card is newer than that file it reports the raw id verbatim — an RTX
 * 5060 comes back as "Device 2d05". Vendor detection still succeeds, so these
 * strings otherwise pass as legitimate model names.
 *
 * Deliberately narrow: it must never reject a real product name. No shipping
 * GPU is called "Device" followed by four hex digits, and the Microsoft entries
 * below are placeholder adapter names that appear nowhere outside a Windows or
 * WSL graphics stack.
 *
 * Lives in its own module rather than beside its first caller because both the
 * leaderboard submission path and the Settings > System display path need the
 * same answer, and they diverged once already: #1165 fixed the submission and
 * left the System page reporting the raw id (#1196). One definition, two
 * callers, so the next placeholder shape only has to be added once.
 */
export function isUnresolvedGpuModel(model: string): boolean {
  const s = model.trim()
  if (s === '') return true
  if (/^device\s+[0-9a-f]{4}$/i.test(s)) return true
  if (/^unknown$/i.test(s)) return true
  // WSL2 exposes the GPU through /dev/dxg rather than the real adapter, so
  // si.graphics() reports Microsoft's generic placeholder even while CUDA work
  // is running on a physical card. Left unhandled, an RTX 3090 reaches the
  // public leaderboard labelled "Microsoft Basic Render Driver", which is worse
  // than no label: it is wrong, and it fragments per-hardware grouping (#1218).
  //
  // These are Microsoft's own placeholder adapter names and appear nowhere
  // outside a Windows/WSL graphics stack, so this cannot reject a real product
  // name on a native Linux host.
  if (/^microsoft basic (render driver|display adapter)$/i.test(s)) return true
  return false
}

import logger from '@adonisjs/core/services/logger'
import type { ContainerRegistryService } from '#services/container_registry_service'
import type { SystemService } from '#services/system_service'

/**
 * Shared pre-flight primitives for update flows (core app + installed apps).
 * Kept framework-light (plain functions + injected service instances) so both
 * {@link AutoUpdateService} and {@link AppAutoUpdateService} reuse one implementation.
 */

export type BlockerSeverity = 'skip' | 'failure'

export interface Blocker {
  reason: string
  severity: BlockerSeverity
}

export interface PreflightResult {
  ok: boolean
  blockers: Blocker[]
}

/** Require free space >= imageSize * factor to cover decompressed layers + headroom. */
export const DISK_SAFETY_FACTOR = 2
/** Conservative fallback when the registry image size can't be determined. */
export const MIN_FREE_BYTES = 5 * 1024 * 1024 * 1024 // 5 GiB

/** Free bytes on the root filesystem (best-effort, falls back to max available). */
export async function getFreeBytes(systemService: SystemService): Promise<number | null> {
  const info = await systemService.getSystemInfo()
  if (!info?.fsSize?.length) return null
  const root = info.fsSize.find((f) => f.mount === '/')
  if (root) return root.available
  return Math.max(...info.fsSize.map((f) => f.available))
}

function gib(bytes: number): string {
  return `${(bytes / 1024 / 1024 / 1024).toFixed(1)} GiB`
}

/**
 * Returns a `failure` disk blocker if free space is insufficient for the given
 * image reference, otherwise null. Mirrors the core update's behavior: estimate
 * the image's compressed download size from the registry manifest, require
 * `size * DISK_SAFETY_FACTOR` (or {@link MIN_FREE_BYTES} when size is unknown),
 * and never block on transient lookup errors (returns null on failure).
 *
 * @param image Full image reference INCLUDING tag (e.g. "ollama/ollama:0.23.2").
 */
export async function checkImageDiskSpace(params: {
  image: string
  hostArch: string
  containerRegistryService: ContainerRegistryService
  systemService: SystemService
}): Promise<Blocker | null> {
  const { image, hostArch, containerRegistryService, systemService } = params
  try {
    const parsed = containerRegistryService.parseImageReference(image)
    const imageSize = await containerRegistryService.getImageDownloadSize(
      parsed,
      parsed.tag,
      hostArch
    )
    const required = imageSize !== null ? imageSize * DISK_SAFETY_FACTOR : MIN_FREE_BYTES

    const free = await getFreeBytes(systemService)
    if (free === null) {
      logger.warn('[ImageDiskPreflight] Could not determine free disk space; skipping disk check')
      return null
    }

    if (free < required) {
      return {
        reason: `Insufficient disk space: ${gib(free)} free, ${gib(required)} required`,
        severity: 'failure',
      }
    }
    return null
  } catch (error) {
    logger.warn(`[ImageDiskPreflight] Disk space check failed: ${error.message}`)
    return null
  }
}

import type { KbIngestStateValue } from '../../types/kb_ingest_state.js'

/**
 * Decision returned by `decideScanAction` describing what scanAndSyncStorage
 * should do for one file given its current state row (if any), whether Qdrant
 * already has chunks for it, and the global ingest policy.
 *
 * - `skip` — file is in a settled state (already indexed, deliberately not
 *   indexed, or in a manual-recovery state); no auto-dispatch.
 * - `dispatch` — file needs to be (re-)embedded; an EmbedFileJob should be
 *   dispatched. `createStateRow` indicates whether a new state row needs to
 *   be created before dispatch (i.e. first time the scanner has seen it).
 * - `backfill_indexed` — Qdrant has chunks but no state row exists yet
 *   (pre-RFC install, or new admin instance pointed at an existing Qdrant
 *   volume). Create a row in `indexed` state without re-embedding.
 * - `create_pending` — Manual mode: record that we've seen the file but
 *   don't dispatch. Frontend surfaces a per-card "Index" affordance.
 */
export type ScanAction =
  | { kind: 'skip' }
  | { kind: 'dispatch'; createStateRow: boolean }
  | { kind: 'backfill_indexed' }
  | { kind: 'create_pending' }

export interface KbIngestStateRow {
  state: KbIngestStateValue
}

/**
 * Global auto-index policy stored at KV `rag.defaultIngestPolicy`. Unset is
 * treated as `Always` so existing installs keep their current behavior until
 * the user opts into Manual mode through the KB panel.
 */
export type IngestPolicy = 'Always' | 'Manual'

/**
 * Decide what scanAndSyncStorage should do for a single embeddable file.
 *
 * Replaces the earlier `!sourcesInQdrant.has(filePath)` binary check, which
 * couldn't tell a fully-indexed file from a stalled mid-batch ingestion, and
 * couldn't honor a user's "browse only" choice. The state row is now the
 * authoritative answer; Qdrant chunk presence is corroborating evidence.
 */
export function decideScanAction(
  stateRow: KbIngestStateRow | null,
  hasChunksInQdrant: boolean,
  policy: IngestPolicy = 'Always'
): ScanAction {
  if (!stateRow) {
    if (hasChunksInQdrant) return { kind: 'backfill_indexed' }
    return policy === 'Always'
      ? { kind: 'dispatch', createStateRow: true }
      : { kind: 'create_pending' }
  }

  switch (stateRow.state) {
    case 'indexed':
      return hasChunksInQdrant ? { kind: 'skip' } : { kind: 'dispatch', createStateRow: false }
    case 'pending_decision':
      // Manual mode: file is waiting for the user to opt in via per-card Index.
      // Always mode: treat as "user-equivalent of auto-index" and dispatch.
      return policy === 'Always'
        ? { kind: 'dispatch', createStateRow: false }
        : { kind: 'skip' }
    case 'browse_only':
    case 'failed':
    case 'stalled':
      return { kind: 'skip' }
  }
}

/**
 * Visual status assigned to an in-flight (or stuck) embedding job, used to
 * pick the colored status pill in the KB Processing Queue. See RFC #883 §5.
 *
 * - `waiting`  — queued, no batch has started yet
 * - `healthy`  — last batch < 2 minutes ago
 * - `slow`     — last batch 2-5 minutes ago (CPU-paced multi-batch ingestion
 *                falls into this band; not necessarily a problem)
 * - `stalled`  — last batch > 5 minutes ago (likely a real problem)
 * - `failed`   — job recorded a failed status
 */
export type JobHealthStatus = 'waiting' | 'healthy' | 'slow' | 'stalled' | 'failed'

export interface JobHealthInput {
  /** BullMQ job.data.status — set by EmbedFileJob.handle on transitions. */
  status: string
  /** 0-100. 0 means no work observed yet on this job-row. */
  progress: number
  /** ms epoch of the last completed batch. Multi-batch ZIMs update this on
   * every continuation; single-batch jobs leave it unset until completion. */
  lastBatchAt?: number
  /** ms epoch of the first batch start. Used as a fallback "last activity"
   * signal for jobs that haven't yet completed their first batch. */
  startedAt?: number
  /** Current ms epoch. Injected for testability. */
  now: number
}

const SLOW_THRESHOLD_MS = 2 * 60 * 1000
const STALLED_THRESHOLD_MS = 5 * 60 * 1000

export function computeJobHealth(input: JobHealthInput): JobHealthStatus {
  if (input.status === 'failed') return 'failed'

  // No progress recorded and no activity timestamps — job is still queued.
  if (
    input.progress === 0 &&
    input.lastBatchAt === undefined &&
    input.startedAt === undefined
  ) {
    return 'waiting'
  }

  const lastActivity = input.lastBatchAt ?? input.startedAt ?? input.now
  const stalenessMs = input.now - lastActivity

  if (stalenessMs > STALLED_THRESHOLD_MS) return 'stalled'
  if (stalenessMs > SLOW_THRESHOLD_MS) return 'slow'
  return 'healthy'
}

export interface RatioRow {
  pattern: string
  chunks_per_mb: number
}

/**
 * Bytes of on-disk storage one embedded chunk consumes inside Qdrant.
 *
 * Rough composition for our pipeline:
 *   - vector: 768 dims × float32 = 3,072 B
 *   - chunk text payload: ~3,000 B (target 1,500 tokens × 2 chars/token)
 *   - source/metadata payload + Qdrant indexes: ~2,000 B
 *
 * Used for surfacing pre-ingest disk-cost estimates; the actual figure
 * varies with collection params and will be replaced by self-calibration
 * (RFC #883 Phase 4) once we have real measurements.
 */
export const BYTES_PER_CHUNK_ON_DISK = 8_000

export interface BatchEstimateInput {
  filename: string
  sizeBytes: number
}

export interface BatchEstimate {
  totalChunks: number
  totalBytes: number
  hasUnknown: boolean
}

/**
 * Aggregate an embedding-disk-cost estimate across a batch of files (curated
 * tier add, multi-upload, sync preview, etc). `hasUnknown` is true when at
 * least one file did not match any registry row — the totals only include
 * matched files, so callers should annotate "estimate excludes unknown files"
 * when surfacing the figure.
 */
export function estimateBatch(
  files: BatchEstimateInput[],
  rows: RatioRow[]
): BatchEstimate {
  let totalChunks = 0
  let hasUnknown = false
  for (const f of files) {
    const chunks = estimateChunkCount(f.filename, f.sizeBytes, rows)
    if (chunks === null) {
      hasUnknown = true
    } else {
      totalChunks += chunks
    }
  }
  return {
    totalChunks,
    totalBytes: totalChunks * BYTES_PER_CHUNK_ON_DISK,
    hasUnknown,
  }
}

/**
 * Pick the chunks_per_mb estimate for a filename by longest-prefix match.
 *
 * Patterns are filename prefixes (`devdocs_`, `wikipedia_en_simple_`, ...).
 * The longest matching prefix wins, so a specific entry (`wikipedia_en_simple_`)
 * overrides the broader fallback (`wikipedia_en_`). An empty-string pattern in
 * the registry serves as a catch-all that matches every input.
 *
 * Returns `null` if no row matches and no empty-string fallback is present —
 * caller decides whether to surface "unknown" or use its own default.
 *
 * `ignoreCatchAll` excludes the empty-string catch-all row from matching, so a
 * filename that only the fallback would have matched returns `null` instead.
 * Callers that need a *specific* expectation (e.g. the partial_stall warning,
 * which must not fire on atypical ZIMs the registry can't actually characterize)
 * pass this; rough aggregate estimates (disk cost) leave it off. See #913.
 */
export function findChunksPerMb(
  filename: string,
  rows: RatioRow[],
  opts: { ignoreCatchAll?: boolean } = {}
): number | null {
  let best: RatioRow | null = null
  for (const row of rows) {
    if (opts.ignoreCatchAll && row.pattern === '') continue
    if (!filename.startsWith(row.pattern)) continue
    if (best === null || row.pattern.length > best.pattern.length) {
      best = row
    }
  }
  return best === null ? null : best.chunks_per_mb
}

/**
 * Estimate the number of embedding chunks a ZIM-style file will produce given
 * its size on disk in bytes. Returns `null` when the registry has nothing to
 * match against. Caller is responsible for converting the estimate into either
 * a disk-footprint estimate (chunks × bytes-per-chunk in Qdrant) or a time
 * estimate (chunks ÷ chunks-per-minute-on-this-hardware).
 */
export function estimateChunkCount(
  filename: string,
  fileSizeBytes: number,
  rows: RatioRow[],
  opts: { ignoreCatchAll?: boolean } = {}
): number | null {
  const ratio = findChunksPerMb(filename, rows, opts)
  if (ratio === null) return null
  const megabytes = fileSizeBytes / (1024 * 1024)
  return Math.round(ratio * megabytes)
}

/**
 * Conditional warnings surfaced on Stored Files rows in the KB panel.
 * See RFC #883 §6 — these warnings appear ONLY when their triggering condition
 * is met, never on healthy files, to keep the panel silent in the common case.
 *
 * - `zero_chunks`   — a non-trivial file produced 0 embedding chunks. Common
 *                     cause: video-only or image-only ZIMs that the pipeline
 *                     completes "successfully" with no extractable text.
 *                     AI Assistant cannot reference this content.
 * - `partial_stall` — the file has embedded chunks but well below the count
 *                     expected from the ratio registry. Likely a mid-batch
 *                     stall (which the binary "any chunks ⇒ embedded" check
 *                     used to mask). Surfaces a Retry affordance.
 */
import type { FileWarning } from '../../types/rag.js'

export type { FileWarning }

/** Files smaller than this are too small to flag as suspicious zero-chunk
 *  cases — a 5 KB upload that produces 0 chunks is much more likely to be a
 *  legitimate edge case (placeholder file) than the gigabyte-scale video ZIM
 *  problem this warning targets. */
export const ZERO_CHUNKS_MIN_SIZE_BYTES = 100 * 1024 * 1024 // 100 MB

/** Fraction of expected chunks below which we consider a file partially
 *  stalled. 0.5 (50%) matches the threshold described in RFC #883 §6 Warning B. */
export const PARTIAL_STALL_RATIO_THRESHOLD = 0.5

export interface WarningInputs {
  /** Source file size on disk in bytes. */
  fileSizeBytes: number
  /** Distinct chunks present in Qdrant for this source. */
  chunksInQdrant: number
  /** Best estimate of chunks the file should produce, from the ratio
   *  registry. `null` when no registry pattern matches and no fallback is
   *  configured — Warning B is suppressed in that case (we'd rather be silent
   *  than wrong). */
  expectedChunks: number | null
}

export function decideWarnings(inputs: WarningInputs): FileWarning[] {
  const warnings: FileWarning[] = []

  // Warning A: file is large but produced nothing. Almost always a video-only
  // or image-only ZIM; AI Assistant literally cannot reference this content.
  if (
    inputs.chunksInQdrant === 0 &&
    inputs.fileSizeBytes > ZERO_CHUNKS_MIN_SIZE_BYTES
  ) {
    warnings.push({ kind: 'zero_chunks', fileSizeBytes: inputs.fileSizeBytes })
  }

  // Warning B: chunks present but far below expectation. Suppresses when we
  // have no expectation (registry miss) since the comparison would be
  // meaningless and we'd rather under-warn than mislead.
  if (
    inputs.expectedChunks !== null &&
    inputs.expectedChunks > 0 &&
    inputs.chunksInQdrant > 0 &&
    inputs.chunksInQdrant < inputs.expectedChunks * PARTIAL_STALL_RATIO_THRESHOLD
  ) {
    warnings.push({
      kind: 'partial_stall',
      chunksEmbedded: inputs.chunksInQdrant,
      chunksExpected: inputs.expectedChunks,
    })
  }

  return warnings
}

export function formatSpeed(bytesPerSecond: number): string {
  if (bytesPerSecond < 1024) return `${bytesPerSecond.toFixed(0)} B/s`
  if (bytesPerSecond < 1024 * 1024) return `${(bytesPerSecond / 1024).toFixed(1)} KB/s`
  return `${(bytesPerSecond / (1024 * 1024)).toFixed(1)} MB/s`
}

export function toTitleCase(str: string): string {
  return str
    .toLowerCase()
    .split(' ')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ')
}

/**
 * Decide which model runs an ancillary AI task (chat titles, chat suggestions).
 *
 * `configured` is the user's `ai.tasksModel` setting. It only wins when the
 * model is still installed — a model can be deleted from /settings/models long
 * after it was picked here, and a request for a missing model 404s. In every
 * other case the caller's existing `fallback` applies, so an unset setting
 * leaves prior behaviour untouched.
 */
export function pickTasksModel(
  configured: string | null | undefined,
  installedNames: string[],
  fallback: string | null
): { model: string | null; staleConfigured: string | null } {
  const trimmed = configured?.trim()
  if (!trimmed) {
    return { model: fallback, staleConfigured: null }
  }
  if (installedNames.includes(trimmed)) {
    return { model: trimmed, staleConfigured: null }
  }
  return { model: fallback, staleConfigured: trimmed }
}

export function parseBoolean(value: any): boolean {
  if (typeof value === 'boolean') return value
  if (typeof value === 'string') {
    const lower = value.toLowerCase()
    return lower === 'true' || lower === '1'
  }
  if (typeof value === 'number') {
    return value === 1
  }
  return false
}

/**
 * Interpret a stored `rag.minRelevance` value as a retrieval relevance floor.
 *
 * Pure, and separate from the cached KV read in rag_relevance.ts, for the same
 * reason pickTasksModel is separate from resolveTasksModel: every interesting
 * case here is a bad or absent value, and none of them need a database.
 *
 * Unset, empty, 'auto' and unparseable all mean "use the recommended default" —
 * a corrupt row must not silently disable filtering. An explicit 0 is different:
 * it is a real choice, and it turns the floor off.
 */
export function parseMinRelevance(raw: string | null | undefined, fallback: number): number {
  if (raw === null || raw === undefined) return fallback
  const trimmed = String(raw).trim()
  if (trimmed === '' || trimmed === 'auto') return fallback
  const parsed = Number(trimmed)
  if (!Number.isFinite(parsed)) return fallback
  return Math.min(1, Math.max(0, parsed))
}

/**
 * Apply the retrieval relevance floor to a reranked candidate list.
 *
 * Pure, and called from RagService.searchSimilarDocuments between reranking and
 * the source-diversity penalty. The ordering is the interesting part: the floor
 * is a judgement about *relevance*, and the reranked score is where that
 * judgement is best informed. Diversity is about *redundancy* — it multiplies by
 * 0.85^n per repeated source — so flooring afterwards would drop the fourth
 * chunk of the one document that actually answers the question and blame a knob
 * labelled "relevance" for it.
 *
 * An empty result is a real answer, not a failure: it means nothing retrieved
 * was relevant enough, and the caller should inject no context block at all
 * rather than hand the model passages it has to be talked out of using.
 */
export function applyRelevanceFloor<T extends { finalScore: number }>(
  results: T[],
  minFinalScore: number
): { survivors: T[]; belowFloor: number } {
  if (!(minFinalScore > 0)) return { survivors: results, belowFloor: 0 }
  const survivors = results.filter((r) => r.finalScore >= minFinalScore)
  return { survivors, belowFloor: results.length - survivors.length }
}

import type { ModelVisionCapability } from '../../types/ollama.js'

export type ModelCapabilities = {
  thinking: boolean
  vision: ModelVisionCapability
}

export type ModelCapabilityProbes = {
  ollamaShow: () => Promise<unknown>
  llamaProps: () => Promise<unknown>
}

export type InstalledModelMetadata = {
  name: string
  size: number
  capabilities?: string[]
}

export function capabilitiesFromOllamaShow(value: unknown): ModelCapabilities | null {
  if (!value || typeof value !== 'object') return null
  const capabilities = (value as { capabilities?: unknown }).capabilities
  if (!Array.isArray(capabilities) || !capabilities.every((item) => typeof item === 'string')) {
    return null
  }

  return {
    thinking: capabilities.includes('thinking'),
    vision: capabilities.includes('vision') ? 'supported' : 'unsupported',
  }
}

export function visionCapabilityFromLlamaProps(value: unknown): ModelVisionCapability | null {
  if (!value || typeof value !== 'object') return null
  const modalities = (value as { modalities?: unknown }).modalities
  if (modalities && typeof modalities === 'object' && !Array.isArray(modalities)) {
    const vision = (modalities as { vision?: unknown }).vision
    return typeof vision === 'boolean' ? (vision ? 'supported' : 'unsupported') : null
  }
  if (Array.isArray(modalities) && modalities.every((item) => typeof item === 'string')) {
    return modalities.includes('image') || modalities.includes('vision')
      ? 'supported'
      : 'unsupported'
  }
  return null
}

export async function resolveModelCapabilities(
  advertisedMetadata: unknown,
  probes: ModelCapabilityProbes
): Promise<ModelCapabilities | null> {
  const advertised = capabilitiesFromOllamaShow(advertisedMetadata)
  // A model list that reports vision is trusted outright. One that does not is
  // not conclusive: Ollama's /api/tags lists gemma3 as ['completion'] while its
  // /api/show for the same model reports ['completion', 'vision'], which left
  // image upload disabled for one of the most common small vision models.
  if (advertised?.vision === 'supported') return advertised

  try {
    const ollama = capabilitiesFromOllamaShow(await probes.ollamaShow())
    if (ollama) return ollama
  } catch {}

  try {
    const vision = visionCapabilityFromLlamaProps(await probes.llamaProps())
    if (vision) return { thinking: advertised?.thinking ?? false, vision }
  } catch {}

  return advertised
}

export function installedModelsFromOpenAIResponse(value: unknown): InstalledModelMetadata[] {
  if (!value || typeof value !== 'object') return []
  const data = (value as { data?: unknown }).data
  if (!Array.isArray(data)) return []

  return data.flatMap((entry) => {
    if (!entry || typeof entry !== 'object') return []
    const { id, capabilities } = entry as { id?: unknown; capabilities?: unknown }
    if (typeof id !== 'string') return []

    const model: InstalledModelMetadata = { name: id, size: 0 }
    if (
      Array.isArray(capabilities) &&
      capabilities.every((capability) => typeof capability === 'string')
    ) {
      model.capabilities = capabilities
    }
    return [model]
  })
}

/**
 * Per-queue BullMQ stall-recovery options.
 *
 * The pure, dependency-free core of `getStallOptionsForQueue` in
 * `commands/queue/work.ts` (mirrors `decideScanAction` in
 * `kb_ingest_decision.ts`).
 *
 * Two questions decide a queue's entry, and they pull in opposite directions:
 *
 * 1. **How long does one job legitimately hold the lock?** If that can exceed
 *    `lockDuration`, BullMQ calls a perfectly healthy job stalled.
 * 2. **Is re-running a job safe?** On a stall BullMQ increments the job's `stc`
 *    counter and re-queues it, failing it only once the counter passes
 *    `maxStalledCount` (`moveStalledJobsToWait`). It does **not** check whether
 *    the original is still running. For an idempotent job that recovery is what
 *    we want; for a job that writes non-idempotent data it is worse than the
 *    failure it is preventing.
 *
 * Note that `maxStalledCount: 0` is meaningful and is not the same as leaving
 * it unset: the comparison is `stalledCount > maxStalledCount` after an
 * increment, so 0 fails the job on the FIRST stall rather than re-queueing it,
 * while the BullMQ default of 1 re-queues once.
 */

export const DEFAULT_LOCK_DURATION = 300_000
export const LONG_LOCK_DURATION = 1_800_000

export interface StallOptions {
  lockDuration: number
  /** Left undefined to keep BullMQ's default of 1. */
  maxStalledCount?: number
}

export interface StallQueueNames {
  /** ZIM/document embedding — a self-continuing batch chain. */
  embedFile: string
  /** Content downloads — resumable. */
  download: string
  drugDownload: string
  drugIngest: string
}

export function stallOptionsForQueue(queueName: string, queues: StallQueueNames): StallOptions {
  // Long single streams (a ~150 MB resumable HTTP pull, then an unzip +
  // JSON-stream ingest at concurrency 1). Re-running a part is safe: the
  // download resumes and the ingest upserts by key.
  if (queueName === queues.drugDownload || queueName === queues.drugIngest) {
    return { lockDuration: LONG_LOCK_DURATION, maxStalledCount: 3 }
  }

  // NEVER auto-recover a stalled job on this queue (#1269). Embedding is a
  // self-continuing chain, so re-queueing while the original is alive produces
  // two chains walking the same file, both writing to Qdrant with freshly
  // minted point ids. A failed chain is visible and re-indexable; a forked one
  // is silent and corrupts the index.
  if (queueName === queues.embedFile) {
    return { lockDuration: LONG_LOCK_DURATION, maxStalledCount: 0 }
  }

  // The opposite call to embeddings (#1203). A download is resumable and
  // re-running one is harmless, but the default maxStalledCount of 1 fails the
  // job on a second stall and bypasses its own `attempts: 10` retry policy.
  if (queueName === queues.download) {
    return { lockDuration: LONG_LOCK_DURATION, maxStalledCount: 3 }
  }

  return { lockDuration: DEFAULT_LOCK_DURATION }
}

/**
 * Pure helpers for shaping the retrieved-context block.
 *
 * These live here rather than in RagPipelineService so they can be exercised
 * under bare `node --experimental-strip-types` with no MySQL, Redis, Qdrant, or
 * Ollama — the same reason `kb_ratio_lookup.ts` is shaped this way. The service
 * supplies the config; everything below is a function of its arguments.
 *
 * Token budgeting used to live here too, as a chars-per-token estimate feeding a
 * `num_ctx` ladder. Both are gone: the estimate now comes from
 * `token_estimate.ts` (calibrated against real token counts) and the allocation
 * from `context_budget.ts`. The ladder in particular was dead code — it fed a
 * `num_ctx` that the OpenAI-compatible endpoint silently discarded, so no chat
 * ever ran at the window it computed.
 */

import { parseParameterBillions } from './context_window.js'
import type { ChatSource } from '../../types/chat.js'

export type ContextLimits = { maxResults: number; maxTokens: number }
export type ContextLimitTier = { maxParams: number; maxResults: number; maxTokens: number }

/** The minimum shape these helpers need; the real chunks carry more. */
export type BudgetableChunk = { text: string; metadata?: Record<string, any> }
export type BudgetableMessage = { role: 'system' | 'user' | 'assistant'; content: string }

/**
 * Determine RAG context limits from the model's parameter count.
 *
 * `parameterSize` is Ollama's own `details.parameter_size` ("8.0B") and is the
 * honest source. The model name is only a fallback: it used to be the *only*
 * source, which meant a tag carrying no size — "phi3", "mistral-nemo", anything
 * custom — was silently assumed to be 8B and handed far more context than a
 * small model can actually use. When neither source knows, 8B remains the
 * assumption, but now it is one made explicitly rather than by a failed regex.
 */
export function getContextLimitsForModel(
  modelName: string,
  tiers: readonly ContextLimitTier[],
  parameterSize?: string
): ContextLimits {
  const paramBillions = parseParameterBillions(parameterSize, modelName) ?? 8

  for (const tier of tiers) {
    if (paramBillions <= tier.maxParams) {
      return { maxResults: tier.maxResults, maxTokens: tier.maxTokens }
    }
  }

  return { maxResults: 5, maxTokens: 0 }
}

/**
 * Render retrieved chunks into the block the rag_context prompt wraps.
 *
 * Each block is labelled with its source title when one is available — a
 * neutral, honest provenance signal — but never with the raw relevance score.
 * nomic cosine scores for genuinely relevant passages sit around 0.4-0.6, and
 * surfacing e.g. "42%" primes the model to distrust correct context. Scores
 * stay in the logs and in the eval report.
 */
export function buildContextBlock(docs: BudgetableChunk[]): string {
  return docs
    .map((doc, idx) => {
      const title =
        doc.metadata?.archive_title || doc.metadata?.full_title || doc.metadata?.article_title
      const date = doc.metadata?.archive_date
      const label = title
        ? `[Context ${idx + 1} — ${title}${date ? ` (${date})` : ''}]`
        : `[Context ${idx + 1}]`
      return `${label}\n${doc.text}`
    })
    .join('\n\n')
}

/**
 * Build the deduplicated "Sources" list shown under an assistant answer.
 *
 * Deliberately fed from what was *injected* into the prompt rather than from
 * everything retrieval returned: a chunk dropped by the budget planner never
 * reached the model, so citing it would credit the answer to a document it was
 * not based on -- the exact failure the citation list exists to prevent.
 *
 * Dedupes on the originating path so a dozen chunks out of one archive collapse
 * to one entry, falling back to the title when a point carries no path. Points
 * with neither are skipped rather than shown as "Unknown source": an entry the
 * user cannot act on is worse than one fewer entry.
 */
export function buildCitations(docs: BudgetableChunk[]): ChatSource[] {
  const seen = new Set<string>()
  const sources: ChatSource[] = []

  for (const doc of docs) {
    const title =
      doc.metadata?.archive_title || doc.metadata?.full_title || doc.metadata?.article_title
    const path = doc.metadata?.source as string | undefined
    const key = path || title
    if (!key || seen.has(key)) continue
    seen.add(key)

    sources.push({
      // A user-uploaded PDF carries no embedded title, so fall back to its
      // filename -- which is what the user named it and will recognise.
      title: title || path!.split('/').pop() || path!,
      date: doc.metadata?.archive_date,
      source: path,
    })
  }

  return sources
}

import logger from '@adonisjs/core/services/logger'
import KVStore from '#models/kv_store'
import { RAG_MIN_FINAL_SCORE } from '../../constants/ollama.js'
import { parseMinRelevance } from './misc.js'

/**
 * Resolves the user's retrieval relevance floor (`rag.minRelevance`), cached.
 *
 * Read on every chat turn, changed roughly never, so a KV round-trip per turn
 * would be pure overhead on the critical path. Cached at module scope rather
 * than on a service instance: NOMAD's services are `@inject()` but are not
 * registered as singletons, so instance state lives and dies with a single
 * request — which is why ContextWindowService's "memoized for the process
 * lifetime" memo isn't, and why its invalidate() never had a caller to matter to.
 *
 * Belt and braces, mirroring the assistant-name cache in config/inertia.ts: the
 * TTL bounds how stale this can get if an invalidation is ever missed, and
 * SystemService.updateSetting calls invalidateMinRelevanceCache() so the common
 * case takes effect immediately.
 */
const CACHE_TTL_MS = 60_000

let cache: { value: number; expiresAt: number } | null = null

export function invalidateMinRelevanceCache(): void {
  cache = null
}

/** The relevance floor to apply to this turn's retrieval. */
export async function resolveMinFinalScore(): Promise<number> {
  const now = Date.now()
  if (cache && now < cache.expiresAt) return cache.value

  let raw: string | null = null
  try {
    raw = await KVStore.getValue('rag.minRelevance')
  } catch (error) {
    // A KV read failure must not take retrieval out, and must not be cached —
    // fall back to the default and let the next turn try again.
    logger.warn(
      `[RAG] Failed to read rag.minRelevance, using ${RAG_MIN_FINAL_SCORE}: ${error instanceof Error ? error.message : error}`
    )
    return RAG_MIN_FINAL_SCORE
  }

  const value = parseMinRelevance(raw, RAG_MIN_FINAL_SCORE)
  cache = { value, expiresAt: now + CACHE_TTL_MS }
  return value
}

/**
 * The pure half of the retrieval relevance check (#1341): the grammar, the
 * setting, and what the judge gets to read.
 *
 * Why a model and not another threshold: on a library holding general prose
 * (Gutenberg, Wikipedia), the nearest chunk to *any* question scores as high as
 * a genuinely relevant one. Measured on the eval corpus with its distractors,
 * the weakest correct top hit scored 0.666 post-rerank while "write me a haiku
 * about autumn leaves" pulled Walden at 0.705. No cutoff on that axis separates
 * the two, so the decision has to be a judgement about the question.
 *
 * Why one verdict for the whole set rather than one per passage: asked
 * passage-by-passage, every model tried (0.5B to 8B) rejected passages that
 * were on-topic but did not spell the answer out, and cost 9-17 points of
 * recall@5. "Are these about what was asked?" is the easier question, and on an
 * 8B model it took off-topic leaks from 67% to 6% for ~5 points of recall. On a
 * 3B model it rejects most real questions, which is why the check is opt-in.
 *
 * Pure so it unit-tests under bare node; RelevanceJudgeService owns the call.
 */

/**
 * Longest excerpt of each passage the judge reads. At 700 characters the window
 * routinely stopped a sentence short of the answer (wound packing, counterpoise
 * length) and the judge rightly said the passage didn't cover it.
 */
export const JUDGE_EXCERPT_CHARS = 1500

/** Anything shorter carries no topical signal; don't let it steer the excerpt. */
const MIN_TERM_LENGTH = 4

export type JudgeablePassage = { text: string; title?: string }

export const ON_TOPIC_SCHEMA = {
  type: 'object',
  properties: { on_topic: { type: 'boolean' } },
  required: ['on_topic'],
  additionalProperties: false,
} as const

export function pickOnTopic(value: any): boolean | null {
  return typeof value?.on_topic === 'boolean' ? value.on_topic : null
}

/**
 * Interpret the stored `rag.relevanceCheck` setting. Off unless explicitly on:
 * the check costs a model call per turn and hurts recall on small models, so
 * nothing short of a deliberate choice should turn it on.
 */
export function isRelevanceCheckEnabled(raw: unknown): boolean {
  return raw === true || raw === 'true'
}

/**
 * The stretch of `text` most about the question, at most `maxChars` long.
 *
 * Chunks run ~3000 characters and the judge sees half of each, so which half
 * matters. Picks the window holding the most occurrences of the question's
 * longer terms, falling back to the start when none appear.
 */
export function excerptFor(text: string, question: string, maxChars = JUDGE_EXCERPT_CHARS): string {
  const clean = text.replace(/\s+/g, ' ').trim()
  if (clean.length <= maxChars) return clean

  const terms = [
    ...new Set(
      question
        .toLowerCase()
        .split(/[^\p{L}\p{N}]+/u)
        .filter((t) => t.length >= MIN_TERM_LENGTH)
    ),
  ]
  const lower = clean.toLowerCase()
  const hits: number[] = []
  for (const term of terms) {
    for (let at = lower.indexOf(term); at !== -1; at = lower.indexOf(term, at + term.length)) {
      hits.push(at)
    }
  }
  if (hits.length === 0) return clean.slice(0, maxChars) + '…'
  hits.sort((a, b) => a - b)

  // Densest window: two pointers over the sorted hit positions.
  let bestStart = hits[0]
  let bestCount = 0
  for (let lo = 0, hi = 0; hi < hits.length; hi++) {
    while (hits[hi] - hits[lo] > maxChars) lo++
    if (hi - lo + 1 > bestCount) {
      bestCount = hi - lo + 1
      bestStart = hits[lo]
    }
  }

  // Open a little before the first hit so the sentence it sits in reads whole.
  const start = Math.max(0, Math.min(bestStart - Math.floor(maxChars / 5), clean.length - maxChars))
  const end = start + maxChars
  return (start > 0 ? '…' : '') + clean.slice(start, end) + (end < clean.length ? '…' : '')
}

/** The user turn of the judge call: the question, then each passage. */
export function buildJudgeInput(question: string, passages: JudgeablePassage[]): string {
  const blocks = passages.map((p, i) => {
    const heading = p.title ? `p${i + 1} (from "${p.title}")` : `p${i + 1}`
    return `${heading}:\n${excerptFor(p.text, question)}`
  })
  return `Question: ${question.trim()}\n\n${blocks.join('\n\n')}`
}

import logger from '@adonisjs/core/services/logger'
import KVStore from '#models/kv_store'
import { DEFAULT_RESPONSE_STYLE } from '../../constants/ollama.js'
import type { ResponseStyle } from '../../types/ollama.js'
import { parseResponseStyle } from './sampler.js'

/**
 * Resolves the user's Response Style (`ai.responseStyle`), cached.
 *
 * Same shape and same reasoning as the relevance-floor cache next door: read on
 * every chat turn, changed roughly never, and NOMAD's services are `@inject()`
 * but not registered as singletons, so caching on a service instance would give
 * a cache that lives and dies inside one request.
 *
 * The TTL bounds how stale this gets if an invalidation is ever missed;
 * SystemService.updateSetting calls invalidateResponseStyleCache() so the common
 * case takes effect on the next turn rather than a minute later.
 */
const CACHE_TTL_MS = 60_000

let cache: { value: ResponseStyle; expiresAt: number } | null = null

export function invalidateResponseStyleCache(): void {
  cache = null
}

/** The response style to sample this turn under. */
export async function resolveResponseStyle(): Promise<ResponseStyle> {
  const now = Date.now()
  if (cache && now < cache.expiresAt) return cache.value

  let raw: string | null = null
  try {
    raw = await KVStore.getValue('ai.responseStyle')
  } catch (error) {
    // A KV read failure must not take chat out, and must not be cached — fall
    // back to the default and let the next turn try again.
    logger.warn(
      `[Ollama] Failed to read ai.responseStyle, using ${DEFAULT_RESPONSE_STYLE}: ${error instanceof Error ? error.message : error}`
    )
    return DEFAULT_RESPONSE_STYLE
  }

  const value = parseResponseStyle(raw)
  cache = { value, expiresAt: now + CACHE_TTL_MS }
  return value
}

/**
 * Merging catalog config onto an already-installed curated service.
 *
 * `ServiceSeeder.run()` keeps curated services in sync with the catalog by
 * overwriting `container_config` and `ui_location` on every boot. That is correct
 * for anything not yet installed, and wrong for anything that is: an install whose
 * published host port differs from the catalog default gets its port reset, which
 * desyncs the row from the container that is actually running. The Open link then
 * points at a port with nothing behind it, and the next recreate collides with
 * whatever process took the catalog port in the meantime.
 *
 * A host port diverges for an ordinary reason: the default was already taken on
 * that machine, so the user moved it. That is a property of the machine, not a
 * preference the catalog should get a vote on.
 *
 * These helpers keep the running install's host ports while still applying every
 * other catalog change, so an app on an alternate port continues to receive image,
 * env, metadata and scheme updates. The alternative considered was flagging such
 * rows `is_user_modified` so the sync skips them entirely, which also protects the
 * port but permanently opts that install out of all future catalog updates. This
 * is the narrower fix: preserve the one field the machine owns, sync the rest.
 */

/** `{ "8080/tcp": [{ "HostPort": "8090" }] }` keyed by container port. */
type PortBindings = Record<string, Array<{ HostPort?: string }> | undefined>

/**
 * `services.container_config` is a MySQL **json** column, so the driver hands back
 * an already-parsed object at runtime even though the model declares it
 * `string | null`. The catalog side of the comparison is a `JSON.stringify` string.
 * Both shapes reach these helpers, so accept either.
 *
 * This is not a hypothetical: a string-only version of this function silently
 * no-opped against a real database while passing every string-fixture unit test.
 */
type SerializedConfig = string | Record<string, any> | null | undefined

function parseConfig(value: SerializedConfig): Record<string, any> | null {
  if (!value) return null
  if (typeof value === 'object') return value
  try {
    const parsed = JSON.parse(value)
    return parsed && typeof parsed === 'object' ? parsed : null
  } catch {
    // A row we cannot parse gets the catalog value verbatim, which is the
    // pre-existing behaviour and no worse than what it has now.
    return null
  }
}

function readPortBindings(containerConfig: SerializedConfig): PortBindings | null {
  const bindings = parseConfig(containerConfig)?.HostConfig?.PortBindings
  if (!bindings || typeof bindings !== 'object') return null
  return bindings as PortBindings
}

function firstHostPort(bindings: PortBindings | null): string | null {
  if (!bindings) return null
  for (const list of Object.values(bindings)) {
    const port = Array.isArray(list) ? list[0]?.HostPort : undefined
    if (port) return String(port)
  }
  return null
}

/**
 * Catalog `container_config` with the live install's published host ports kept.
 *
 * Matching is per container-side port, so if the catalog changes which port the
 * app listens on *inside* the container, that is a genuine catalog change and the
 * catalog value wins. Only the host side of a binding the install already has is
 * preserved.
 */
export function mergeContainerConfigPreservingHostPorts<T extends string | null>(
  catalogConfig: T,
  liveConfig: SerializedConfig
): T {
  if (!catalogConfig) return catalogConfig
  const live = readPortBindings(liveConfig)
  if (!live) return catalogConfig

  const parsed = parseConfig(catalogConfig)
  if (!parsed) return catalogConfig

  const catalogBindings: PortBindings | undefined = parsed?.HostConfig?.PortBindings
  if (!catalogBindings || typeof catalogBindings !== 'object') return catalogConfig

  let changed = false
  for (const [containerPort, catalogList] of Object.entries(catalogBindings)) {
    const livePort = Array.isArray(live[containerPort]) ? live[containerPort]![0]?.HostPort : undefined
    if (!livePort) continue

    const catalogPort = Array.isArray(catalogList) ? catalogList[0]?.HostPort : undefined
    if (catalogPort === undefined || String(catalogPort) === String(livePort)) continue

    catalogBindings[containerPort] = [{ ...(Array.isArray(catalogList) ? catalogList[0] : {}), HostPort: String(livePort) }]
    changed = true
  }

  return (changed ? JSON.stringify(parsed) : catalogConfig) as T
}

/**
 * Catalog `ui_location` with the live install's port kept, when it is a port at all.
 *
 * `ui_location` is one of `"8090"`, `"https:8480"`, or a path like `"/chat"`. Only
 * the first two forms carry a port, and only those are rewritten. The catalog's
 * scheme is always taken, so a catalog change like Vaultwarden moving to `https:`
 * still reaches an install running on an alternate port.
 *
 * `mergedConfig` must be the container_config this sync is about to WRITE, meaning
 * the output of `mergeContainerConfigPreservingHostPorts`, not the live row. The
 * live port is only honoured when that config actually publishes it, which does
 * two things: it keeps a stale or hand-edited `ui_location` from pinning the link
 * to a port nothing is listening on, and it keeps the link in step with the config
 * in the one case the catalog wins outright. When the catalog moves the
 * container-side port, no live host port is preserved, so the link takes the
 * catalog port rather than pointing at a port the recreate will not bind.
 */
export function mergeUiLocationPreservingHostPort(
  catalogUiLocation: string | null,
  liveUiLocation: string | null | undefined,
  mergedConfig: SerializedConfig
): string | null {
  if (!catalogUiLocation || !liveUiLocation) return catalogUiLocation

  const catalogMatch = catalogUiLocation.match(/^(?:(https?):)?(\d+)$/)
  const liveMatch = liveUiLocation.match(/^(?:(https?):)?(\d+)$/)
  if (!catalogMatch || !liveMatch) return catalogUiLocation

  const livePort = liveMatch[2]
  if (livePort === catalogMatch[2]) return catalogUiLocation

  const bindings = readPortBindings(mergedConfig)
  const publishedPorts = new Set(
    bindings
      ? Object.values(bindings)
          .flatMap((list) => (Array.isArray(list) ? list : []))
          .map((b) => (b?.HostPort ? String(b.HostPort) : null))
          .filter((p): p is string => p !== null)
      : []
  )
  if (!publishedPorts.has(livePort)) return catalogUiLocation

  const scheme = catalogMatch[1]
  return scheme ? `${scheme}:${livePort}` : livePort
}

/** Exported for tests: the first published host port in a serialized config. */
export function firstPublishedHostPort(containerConfig: SerializedConfig): string | null {
  return firstHostPort(readPortBindings(containerConfig))
}

/**
 * JSON Schemas and a tolerant parser for the structured ancillary calls —
 * chat titles, suggestion chips, and the RAG query rewrite.
 *
 * The prompts used to *ask* for a format and the callers recovered the answer by
 * string surgery: split on comma, else on newline, strip `1.`, strip bullets,
 * strip quotes. That is a request, not a constraint, and the failure mode was
 * silent — an empty chip list, or a paragraph as the sidebar title.
 *
 * Ollama's `format` parameter compiles a JSON Schema to a GBNF grammar, so the
 * decoder cannot emit anything else. It only exists on the native /api/chat
 * transport, so every caller keeps its old parser as the fallback for other
 * backends; `parseStructured` returning null is what selects that path.
 *
 * Pure functions, no framework imports — see `think_stream.ts` / `rag_prompt.ts`.
 */

/** Sidebar chat title. */
export const TITLE_SCHEMA = {
  type: 'object',
  properties: {
    title: { type: 'string' },
  },
  required: ['title'],
  additionalProperties: false,
} as const

/** The three conversation-starter chips on an empty chat. */
export const SUGGESTIONS_SCHEMA = {
  type: 'object',
  properties: {
    suggestions: {
      type: 'array',
      items: { type: 'string' },
      minItems: 3,
      maxItems: 3,
    },
  },
  required: ['suggestions'],
  additionalProperties: false,
} as const

/**
 * History-aware query rewrite. An array rather than a single string even though
 * only the first entry is used today: multi-query / RAG-Fusion (gap analysis 3.2)
 * then needs a prompt change and nothing else.
 */
export const QUERIES_SCHEMA = {
  type: 'object',
  properties: {
    queries: {
      type: 'array',
      items: { type: 'string' },
      minItems: 1,
    },
  },
  required: ['queries'],
  additionalProperties: false,
} as const

/**
 * Pull a JSON object out of a model response and narrow it with `pick`.
 *
 * Total by construction — every failure returns null so the caller falls through
 * to its string parser. This runs on the chat critical path via the rewrite, so
 * it must never throw.
 *
 * Tolerates the things an unconstrained model does anyway: a ```json fence, a
 * sentence of preamble, trailing commentary. Grammar-constrained output needs
 * none of that, but the same helper is used on backends where the grammar was
 * never applied.
 */
export function parseStructured<T>(raw: string, pick: (value: any) => T | null): T | null {
  if (!raw) return null

  // Outermost braces: the first `{` to the last `}`. Preamble and trailing prose
  // both fall outside it, and a nested object stays inside.
  const start = raw.indexOf('{')
  const end = raw.lastIndexOf('}')
  if (start === -1 || end <= start) return null

  let parsed: any
  try {
    parsed = JSON.parse(raw.slice(start, end + 1))
  } catch {
    return null
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null

  try {
    return pick(parsed)
  } catch {
    return null
  }
}

/**
 * The two ways a structured call can fail to yield a value.
 *
 * `unconstrained` — no grammar reached the model (a non-native backend, or a call
 * that never asked for one). The response is prose by design and the caller's
 * legacy string parser is the correct recovery.
 *
 * `constrained-parse-failed` — the grammar *was* applied and the output still did
 * not yield a value. In practice that means a truncated object: the model hit its
 * token cap mid-JSON. Feeding that to a parser written for prose is what produces
 * `{"title": ...` in the sidebar or a JSON blob in the embedded query, so the
 * caller must take its safe path instead.
 */
export type StructuredResult<T> =
  | { ok: true; value: T }
  | { ok: false; reason: 'constrained-parse-failed' | 'unconstrained' }

/**
 * `parseStructured` plus the reason it failed, so callers branch on what actually
 * happened rather than sniffing the raw text for braces.
 *
 * `constrained` is `NomadChatResponse.structured` — whether the decoder was really
 * grammar-constrained for the request, which only the transport knows.
 *
 * Total, like `parseStructured`: a picker that throws is a failed parse, not an
 * exception on the chat critical path.
 */
export function resolveStructured<T>(
  raw: string,
  pick: (value: any) => T | null,
  constrained: boolean
): StructuredResult<T> {
  const value = parseStructured(raw, pick)
  if (value !== null) return { ok: true, value }
  return { ok: false, reason: constrained ? 'constrained-parse-failed' : 'unconstrained' }
}

/** Non-empty trimmed string, or null. */
function cleanString(value: unknown): string | null {
  if (typeof value !== 'string') return null
  const trimmed = value.trim()
  return trimmed.length > 0 ? trimmed : null
}

/** Trimmed, non-empty entries of a string array. Null when nothing survives. */
function cleanStringArray(value: unknown): string[] | null {
  if (!Array.isArray(value)) return null
  const cleaned = value.map(cleanString).filter((s): s is string => s !== null)
  return cleaned.length > 0 ? cleaned : null
}

/** `{title: string}` -> the title. */
export const pickTitle = (value: any): string | null => cleanString(value?.title)

/** `{suggestions: string[]}` -> up to three non-empty suggestions. */
export const pickSuggestions = (value: any): string[] | null => {
  const suggestions = cleanStringArray(value?.suggestions)
  return suggestions ? suggestions.slice(0, 3) : null
}

/** `{queries: string[]}` -> every non-empty query, best first. */
export const pickQueries = (value: any): string[] | null => cleanStringArray(value?.queries)

import { resolve, sep } from 'node:path'

/**
 * Decides whether a curated resource's PREVIOUSLY-installed file should be
 * deleted now that a newer version has been downloaded (issue #634 — old map
 * and ZIM versions accumulated on disk indefinitely because only Wikipedia had
 * version cleanup).
 *
 * This is intentionally a pure function so every safety rail is unit-testable
 * without touching the DB or filesystem. The caller looks up the prior
 * `InstalledResource` row, records the new version, then asks this whether the
 * old file is safe to remove.
 *
 * Safety rails (a "delete" decision requires ALL of these):
 *  - There was a prior install for this exact resource_id (`existing` non-null).
 *    Untracked / sideloaded files have no row and are therefore never touched.
 *  - The old file path actually differs from the new one (a genuine version
 *    swap, not a re-download of the same file).
 *  - The new file is confirmed present on disk — we never remove the old copy
 *    before the replacement is verified.
 *  - The new version is strictly newer than the recorded one, so a re-install
 *    or downgrade can't wipe a newer file.
 *  - The old path resolves to within the resource's storage directory, so a
 *    malformed DB value can't direct a delete outside the content store.
 */

export interface SupersededInputs {
  /** Prior InstalledResource row for this resource_id, or null on first install. */
  existing: { file_path: string; version: string } | null
  /** Absolute path of the newly downloaded file. */
  newFilePath: string
  /** Version of the newly downloaded file (e.g. "2026-05"). */
  newVersion: string
  /** Whether the new file is confirmed present on disk. */
  newFileExists: boolean
  /** Absolute storage directory the old file must live under to be eligible. */
  storageBaseDir: string
}

export type SupersededReason =
  | 'first_install'
  | 'same_file'
  | 'new_file_missing'
  | 'not_newer'
  | 'outside_storage'
  | 'superseded'

export interface SupersededDecision {
  delete: boolean
  /** Resolved old path to delete — set only when `delete` is true. */
  path?: string
  reason: SupersededReason
}

export function decideSupersededDeletion(inputs: SupersededInputs): SupersededDecision {
  const { existing, newFilePath, newVersion, newFileExists, storageBaseDir } = inputs

  if (!existing) return { delete: false, reason: 'first_install' }
  if (existing.file_path === newFilePath) return { delete: false, reason: 'same_file' }
  if (!newFileExists) return { delete: false, reason: 'new_file_missing' }
  // Versions are zero-padded date strings (YYYY-MM / YYYY-MM-DD), so a lexical
  // compare orders them correctly. Require strictly newer.
  if (!(newVersion > existing.version)) return { delete: false, reason: 'not_newer' }

  const resolvedOld = resolve(existing.file_path)
  const base = resolve(storageBaseDir)
  if (resolvedOld !== base && !resolvedOld.startsWith(base + sep)) {
    return { delete: false, reason: 'outside_storage' }
  }

  return { delete: true, path: resolvedOld, reason: 'superseded' }
}

import logger from '@adonisjs/core/services/logger'
import KVStore from '#models/kv_store'
import type { OllamaService } from '#services/ollama_service'
import { pickTasksModel } from './misc.js'

/**
 * Resolve the model to use for ancillary work — chat titles, suggestions, and
 * the per-turn retrieval query rewrite.
 *
 * Lifted out of ChatService so the RAG pipeline can use it too. The rewrite is
 * the ancillary call that matters most and was the one still running on the main
 * chat model: it happens on *every* turn, on the critical path, and it sends a
 * completely different prompt. With Ollama's default OLLAMA_NUM_PARALLEL=1 there
 * is a single slot, so that call evicted the chat model's cached prefix every
 * turn and guaranteed a full re-prefill of the conversation. Routing it to a
 * small dedicated model keeps the chat model's KV cache intact.
 *
 * Falls back to `fallback` when the setting is unset (preserving the previous
 * behaviour) or when the configured model is no longer installed. `installed` is
 * passed by callers that already listed models, to avoid a second round-trip.
 */
export async function resolveTasksModel(
  ollamaService: OllamaService,
  fallback: string | null,
  installed?: { name: string }[],
  logPrefix = '[TasksModel]'
): Promise<string | null> {
  let configured: string | null = null
  try {
    configured = await KVStore.getValue('ai.tasksModel')
  } catch (error) {
    logger.error(
      `${logPrefix} Failed to read ai.tasksModel: ${error instanceof Error ? error.message : error}`
    )
    return fallback
  }
  if (!configured?.trim()) {
    return fallback
  }

  let models = installed
  if (!models) {
    try {
      models = await ollamaService.getModels()
    } catch (error) {
      logger.error(
        `${logPrefix} Failed to list models while resolving the tasks model: ${error instanceof Error ? error.message : error}`
      )
      return fallback
    }
  }

  const { model, staleConfigured } = pickTasksModel(
    configured,
    (models ?? []).map((m) => m.name),
    fallback
  )
  if (staleConfigured) {
    logger.warn(
      `${logPrefix} Configured tasks model "${staleConfigured}" is not installed; falling back to "${fallback ?? 'none'}"`
    )
  }
  return model
}

/**
 * Stateful splitter for inline `<think>...</think>` reasoning tags.
 *
 * Ollama's native `/api/chat` and its `/v1` shim both surface reasoning as a
 * dedicated field (`message.thinking` / `delta.reasoning`), but other
 * OpenAI-compatible backends (LM Studio, llama.cpp, plain GGUF servers) emit
 * the tags inline in the content stream. This splits them back out so the UI
 * gets a clean `content` channel and a separate `thinking` channel regardless
 * of which backend answered.
 *
 * Lives here rather than inside OllamaService because both transports need it
 * and because it is the only real logic in the streaming path — as a pure
 * class it can be exercised under bare `node --test` with no Ollama, the same
 * reason `rag_prompt.ts` is shaped this way.
 *
 * The hard part is that a tag can be split across chunk boundaries: a chunk may
 * end with `"<thi"`. Any trailing text that could still turn out to be the start
 * of a tag is held back in the buffer and re-examined when the next chunk lands.
 */

const OPEN_TAG = '<think>'
const CLOSE_TAG = '</think>'

/**
 * How many trailing characters of `text` could be the beginning of `tag`.
 * Returns 0 when no suffix of `text` is a prefix of `tag`.
 */
export function partialTagSuffix(tag: string, text: string): number {
  for (let len = Math.min(tag.length - 1, text.length); len >= 1; len--) {
    if (text.endsWith(tag.slice(0, len))) return len
  }
  return 0
}

export type ThinkSplit = { content: string; thinking: string }

export class ThinkTagSplitter {
  private buffer = ''
  private inThink = false

  /**
   * Feed the next slice of raw model output. Returns only what could be
   * resolved from this call; text that might be a partial tag stays buffered.
   */
  push(raw: string): ThinkSplit {
    this.buffer += raw
    let content = ''
    let thinking = ''

    while (this.buffer.length > 0) {
      if (this.inThink) {
        const closeIdx = this.buffer.indexOf(CLOSE_TAG)
        if (closeIdx !== -1) {
          thinking += this.buffer.slice(0, closeIdx)
          this.buffer = this.buffer.slice(closeIdx + CLOSE_TAG.length)
          this.inThink = false
        } else {
          const hold = partialTagSuffix(CLOSE_TAG, this.buffer)
          thinking += this.buffer.slice(0, this.buffer.length - hold)
          this.buffer = this.buffer.slice(this.buffer.length - hold)
          break
        }
      } else {
        const openIdx = this.buffer.indexOf(OPEN_TAG)
        if (openIdx !== -1) {
          content += this.buffer.slice(0, openIdx)
          this.buffer = this.buffer.slice(openIdx + OPEN_TAG.length)
          this.inThink = true
        } else {
          const hold = partialTagSuffix(OPEN_TAG, this.buffer)
          content += this.buffer.slice(0, this.buffer.length - hold)
          this.buffer = this.buffer.slice(this.buffer.length - hold)
          break
        }
      }
    }

    return { content, thinking }
  }

  /**
   * Flush whatever is still buffered at end of stream. A held-back partial tag
   * that never completed was never a tag, so it belongs to whichever channel
   * we were in when the stream ended — losing it would silently truncate the
   * answer.
   */
  flush(): ThinkSplit {
    const pending = this.buffer
    this.buffer = ''
    return this.inThink ? { content: '', thinking: pending } : { content: pending, thinking: '' }
  }
}

/**
 * One-shot convenience for non-streaming responses.
 */
export function splitThinkTags(raw: string): ThinkSplit {
  const splitter = new ThinkTagSplitter()
  const streamed = splitter.push(raw)
  const tail = splitter.flush()
  return {
    content: streamed.content + tail.content,
    thinking: streamed.thinking + tail.thinking,
  }
}

/**
 * Non-streaming counterpart to the merge the streaming normalizers do inline.
 *
 * A backend may report reasoning structurally (native `message.thinking`, or
 * `reasoning` on the /v1 shim), inline as `<think>` tags, or both at once —
 * and the ancillary calls (title, suggestions, query rewrite) all go through
 * the non-streaming path. Without this the tags reached the sidebar title and,
 * worse, the string that gets embedded and sent to Qdrant.
 */
export function normalizeNonStreamed(rawContent: string, nativeThinking?: string): ThinkSplit {
  const split = splitThinkTags(rawContent ?? '')
  return {
    content: split.content,
    thinking: (nativeThinking ?? '') + split.thinking,
  }
}

import { DateTime } from 'luxon'

/**
 * Shared update-window helpers used by both the core auto-update
 * ({@link AutoUpdateService}) and the per-app auto-update ({@link AppAutoUpdateService}).
 *
 * The window is interpreted in the container's local time (set via the TZ env var).
 * Windows that wrap past midnight (start > end, e.g. 22:00-02:00) are supported.
 */

/** Parse an "HH:MM" 24-hour string into minutes-since-midnight, or null if malformed. */
export function parseWindowMinutes(hhmm: string): number | null {
  const match = /^([01]\d|2[0-3]):([0-5]\d)$/.exec(hhmm)
  if (!match) return null
  return Number(match[1]) * 60 + Number(match[2])
}

/** Whether `now` falls inside the [windowStart, windowEnd) window (handles midnight wrap). */
export function isWithinWindow(
  windowStart: string,
  windowEnd: string,
  now: DateTime = DateTime.now()
): boolean {
  const start = parseWindowMinutes(windowStart)
  const end = parseWindowMinutes(windowEnd)
  if (start === null || end === null) return false

  const current = now.hour * 60 + now.minute
  if (start === end) return false // zero-length window
  if (start < end) {
    return current >= start && current < end
  }
  // Wraps midnight
  return current >= start || current < end
}

/**
 * Compare two semantic version strings to determine if the first is newer than the second.
 * @param version1 - The version to check (e.g., "1.25.0")
 * @param version2 - The current version (e.g., "1.24.0")
 * @returns true if version1 is newer than version2
 */
export function isNewerVersion(version1: string, version2: string, includePreReleases = false): boolean {
  const normalize = (v: string) => v.replace(/^v/, '')
  const [base1, pre1] = normalize(version1).split('-')
  const [base2, pre2] = normalize(version2).split('-')

  // If pre-releases are not included and version1 is a pre-release, don't consider it newer
  if (!includePreReleases && pre1) {
    return false
  }

  const v1Parts = base1.split('.').map((p) => parseInt(p, 10) || 0)
  const v2Parts = base2.split('.').map((p) => parseInt(p, 10) || 0)

  const maxLen = Math.max(v1Parts.length, v2Parts.length)
  for (let i = 0; i < maxLen; i++) {
    const a = v1Parts[i] || 0
    const b = v2Parts[i] || 0
    if (a > b) return true
    if (a < b) return false
  }

  // Base versions equal — GA > RC, RC.n+1 > RC.n
  if (!pre1 && pre2) return true // v1 is GA, v2 is RC → v1 is newer
  if (pre1 && !pre2) return false // v1 is RC, v2 is GA → v2 is newer
  if (!pre1 && !pre2) return false // both GA, equal

  // Both prerelease: compare numeric suffix (e.g. "rc.2" vs "rc.1")
  const pre1Num = parseInt(pre1.split('.')[1], 10) || 0
  const pre2Num = parseInt(pre2.split('.')[1], 10) || 0
  return pre1Num > pre2Num
}

/**
 * Parse the major version number from a tag string.
 * Strips the 'v' prefix if present.
 * @param tag - Version tag (e.g., "v3.8.1", "10.19.4")
 * @returns The major version number
 */
export function parseMajorVersion(tag: string): number {
  const normalized = tag.replace(/^v/, '')
  const major = parseInt(normalized.split('.')[0], 10)
  return isNaN(major) ? 0 : major
}

import type { CatalogResult } from '../services/kiwix_catalog_service.js'
import type { SpecResource } from '../../types/collections.js'
import { isGatedResource } from './hosted_content.js'

export type ResolvedZimDownload = {
  url: string
  version: string
  sizeBytes: number | undefined
}

function compareZimVersions(left: string, right: string): number {
  const parse = (value: string): [number, number] | null => {
    const match = /^(\d{4})-(\d{1,2})$/.exec(value)
    if (!match) return null

    const month = Number.parseInt(match[2], 10)
    if (month < 1 || month > 12) return null

    return [Number.parseInt(match[1], 10), month]
  }

  const leftParts = parse(left)
  const rightParts = parse(right)
  if (!leftParts || !rightParts) return left.localeCompare(right)

  return leftParts[0] - rightParts[0] || leftParts[1] - rightParts[1]
}

export function resolveZimDownload(
  resource: SpecResource,
  latest: CatalogResult | null
): ResolvedZimDownload {
  const manifestSizeBytes = resource.size_mb > 0 ? resource.size_mb * 1024 * 1024 : undefined

  // Content we host ourselves is pinned to the manifest URL, never the Kiwix
  // catalog. It isn't in the openzim catalog at all, so this is normally a no-op
  // — but a resource-id collision would otherwise silently redirect a gated
  // download to a third-party mirror, losing both the auth header and any
  // guarantee about what the bytes are.
  //
  // Consequence, stated rather than implied: gated content does NOT participate
  // in catalog-driven auto-update. New versions ship by bumping the manifest.
  if (isGatedResource(resource)) {
    return {
      url: resource.url,
      version: resource.version,
      sizeBytes: manifestSizeBytes,
    }
  }

  if (!latest || compareZimVersions(latest.version, resource.version) < 0) {
    return {
      url: resource.url,
      version: resource.version,
      sizeBytes: manifestSizeBytes,
    }
  }

  return {
    url: latest.download_url,
    version: latest.version,
    sizeBytes: latest.size_bytes > 0 ? latest.size_bytes : manifestSizeBytes,
  }
}

/**
 * Strip the trailing `_YYYY-MM(-DD).zim` date suffix from a Kiwix-style ZIM
 * filename so different release dates of the same variant share a stem
 * (e.g., `wikipedia_en_all_nopic`) while distinct corpora keep distinct stems
 * (`wikipedia_en_simple_all_nopic`, `wikipedia_en_medicine_nopic`, etc.).
 */
export function zimFilenameStem(name: string): string {
  return name.replace(/_\d{4}-\d{2}(?:-\d{2})?\.zim$/i, '')
}

/**
 * Of the existing files, return only those that are prior-version replacements
 * of `currentFilename` — same Wikipedia variant stem, different release. Used
 * by the post-download cleanup to avoid deleting unrelated Wikipedia corpora
 * the user has installed independently (issue #884).
 */
export function findReplacedWikipediaFiles(
  currentFilename: string,
  existingNames: string[]
): string[] {
  const currentStem = zimFilenameStem(currentFilename)
  return existingNames.filter(
    (n) =>
      n.startsWith('wikipedia_en_') && n !== currentFilename && zimFilenameStem(n) === currentStem
  )
}

import * as cheerio from 'cheerio'
import { NON_CONTENT_HEADING_PATTERNS } from '../../constants/zim_extraction.js'

export interface ZIMSection {
  heading: string
  text: string
  level: number
}

export interface StructuredContent {
  title: string
  sections: ZIMSection[]
  fullText: string
}

/**
 * True when a section heading is one of the low-signal boilerplate headings
 * (See also / References / External links / etc.). Sections under these
 * headings are reference apparatus, not article content, and shouldn't reach
 * the embedder. (#902)
 */
export function isNonContentHeading(heading: string): boolean {
  return NON_CONTENT_HEADING_PATTERNS.some((pattern) => pattern.test(heading))
}

/**
 * Render an HTML <table> into delimited text. cheerio's `.text()` concatenates
 * every cell with no separators ("AgeDoseAdult500mg" word salad), which is
 * unsearchable and pollutes embeddings. Instead, join cells with " | " and rows
 * with newlines so row/column structure survives into the chunk. (#902)
 */
export function tableToText($: cheerio.CheerioAPI, table: any): string {
  const rows: string[] = []
  $(table)
    .find('tr')
    .each((_, tr) => {
      const cells = $(tr)
        .find('th, td')
        .map((__, cell) => $(cell).text().replace(/\s+/g, ' ').trim())
        .get()
        .filter((cell) => cell.length > 0)
      if (cells.length > 0) {
        rows.push(cells.join(' | '))
      }
    })
  return rows.join('\n')
}

/**
 * Break a cleaned article's HTML into heading-delimited sections for chunking.
 * Skips non-content sections (References, See also, ...) at emit time and
 * renders tables as delimited text rather than concatenated cell soup. (#902)
 */
export function extractStructuredContent(html: string): StructuredContent {
  const $ = cheerio.load(html)

  const title = $('h1').first().text().trim() || $('title').text().trim()

  const sections: ZIMSection[] = []
  let currentSection = { heading: 'Introduction', content: [] as string[], level: 2, skip: false }

  const flushSection = () => {
    if (!currentSection.skip && currentSection.content.length > 0) {
      sections.push({
        heading: currentSection.heading,
        text: currentSection.content.join(' ').replace(/\s+/g, ' ').trim(),
        level: currentSection.level,
      })
    }
  }

  // Walk the full DOM rather than only direct children of <body>. Modern ZIMs (Devdocs,
  // Wikipedia, FreeCodeCamp, etc.) wrap article content in a container div, which under
  // .children() would be a single non-heading/non-paragraph element and yield zero sections.
  $('body')
    .find('h2, h3, h4, p, ul, ol, dl, table')
    .each((_, element) => {
      const $el = $(element)
      const tagName = element.tagName?.toLowerCase()

      if (['h2', 'h3', 'h4'].includes(tagName)) {
        // Save the section we just finished, then open the next one.
        flushSection()
        const heading = $el
          .text()
          .replace(/\[edit\]/gi, '')
          .trim()
        const level = Number.parseInt(tagName.substring(1)) // Extract number from h2, h3, h4
        currentSection = {
          heading,
          content: [],
          level,
          skip: isNonContentHeading(heading),
        }
      } else if (['p', 'ul', 'ol', 'dl', 'table'].includes(tagName)) {
        // Don't bother collecting content for a section we're going to drop.
        if (currentSection.skip) return
        const text = tagName === 'table' ? tableToText($, element) : $el.text().trim()
        if (text.length > 0) {
          currentSection.content.push(text)
        }
      }
    })

  // Push the last section if it has content
  flushSection()

  // Fallback: if the selector walk produced no sections but the body has meaningful
  // text (unusual structure, minimal markup), emit one section with the full body text
  // so the article still contributes to the knowledge base.
  if (sections.length === 0) {
    const bodyText = $('body').text().replace(/\s+/g, ' ').trim()
    if (bodyText.length > 0) {
      sections.push({
        heading: title || 'Content',
        text: bodyText,
        level: 2,
      })
    }
  }

  return {
    title,
    sections,
    fullText: sections.map((s) => `${s.heading}\n${s.text}`).join('\n\n'),
  }
}

/**
 * Deterministic scorers for generated answers.
 *
 * Every metric here is computable offline with no judge model, which is what
 * makes the generation tier gateable. An LLM judge can be layered on later for
 * the things regex genuinely cannot see (nuanced faithfulness, completeness),
 * but nothing in this file needs one — and a number you can compute without a
 * model is a number that cannot drift because the judge changed.
 *
 * These are intentionally *conservative*. Each one is a proxy, and each proxy's
 * blind spot is documented where it lives. A proxy you understand the limits of
 * beats a score you cannot explain.
 */

/** Answer-level scoring of one generated response against one golden. */
export type GenerationScores = {
  /** Every mustInclude pattern matched and no mustNotInclude pattern did. */
  correct: boolean
  matchedRequired: string[]
  missedRequired: string[]
  /** Forbidden patterns that appeared. Non-empty means a specific wrong claim. */
  hitForbidden: string[]
  /** The model declined to answer. */
  refused: boolean
  /**
   * Refusal behaviour was right: declined an out-of-corpus question, or
   * answered an answerable one.
   */
  refusalCorrect: boolean
  /** The answer narrated its own retrieval ("according to Context 1"). */
  leakage: string[]
  /** Reasoning tags survived into the user-visible answer. */
  thinkTagLeak: boolean
  /**
   * Fraction of the answer's numeric claims that also appear in the injected
   * context. null when the answer makes no numeric claims.
   */
  numericGroundedness: number | null
  /** Numbers asserted by the answer that the context does not support. */
  ungroundedNumbers: string[]
  /** The answer used at least some markdown structure. */
  markdownFormatted: boolean
  /** Characters. Useful for spotting a model that answers by writing an essay. */
  length: number
}

/**
 * Phrases that mean "I am not answering this".
 *
 * Tuned against NOMAD's actual rag_context prompt, which instructs the model to
 * answer from general knowledge rather than hedge — so a hedge here is either a
 * correct refusal on an out-of-corpus question or a prompt regression on an
 * answerable one. Which of those it is, is exactly what `refusalCorrect` says.
 */
const REFUSAL_PATTERNS: RegExp[] = [
  /\bi (?:don'?t|do not) (?:know|have)\b/i,
  /\bi(?:'m| am) (?:not able|unable) to\b/i,
  /\bi (?:couldn'?t|could not|can'?t|cannot) find\b/i,
  /\b(?:no|not enough) (?:information|details|data)\b/i,
  /\b(?:does|do) not (?:contain|include|mention|specify|provide|cover)\b/i,
  /\b(?:isn'?t|is not|aren'?t|are not) (?:mentioned|specified|covered|available|provided)\b/i,
  /\bnot (?:mentioned|specified|covered|stated|documented)\b/i,
  /\bunable to (?:answer|determine|find)\b/i,
  /\bthere (?:is|'s) no (?:information|mention|record)\b/i,
  // "I'd" has no space before the contraction, so this cannot reuse the
  // `i (?:would|'d)` shape used above.
  /\bi(?:'d| would) need more\b/i,
]

/**
 * Phrases that narrate the retrieval machinery.
 *
 * The rag_context prompt explicitly forbids these ("Never narrate your
 * retrieval or reasoning process"), so any hit is a measurable prompt
 * regression. This is the cheapest, sharpest signal in the whole harness: pure
 * regex, zero ambiguity, and it catches a bad prompt edit on the first run.
 */
const LEAKAGE_PATTERNS: RegExp[] = [
  /\b(?:according to|based on|per|from) the (?:provided |retrieved |given |supplied )?context\b/i,
  /\bcontext \d+\b/i,
  /\bthe knowledge ?base\b/i,
  /\bthe (?:provided|retrieved|supplied|given) (?:documents?|passages?|excerpts?|text)\b/i,
  /\bthe context (?:does not|doesn'?t|is|was|seems|appears)\b/i,
  /\b(?:in|from) the (?:documents?|passages?) (?:provided|above|below)\b/i,
  // "I wasn't able to find specific context regarding X, but here's a general
  // answer" is the verbatim symptom that started NOMAD's RAG work. It is both a
  // refusal and a leak, and it is the single most important string this
  // detector has to catch — a prompt change that brings it back must fail
  // loudly on the very next run.
  /\b(?:no|any|specific|relevant) context\b/i,
  /\bsearch results?\b/i,
]

/** Reasoning-model tags that must never reach the user. */
const THINK_TAG = /<\/?(?:think|thought|thinking|reasoning)\b[^>]*>/i

export function detectRefusal(answer: string): boolean {
  return REFUSAL_PATTERNS.some((re) => re.test(answer))
}

export function detectLeakage(answer: string): string[] {
  return LEAKAGE_PATTERNS.filter((re) => re.test(answer)).map((re) => re.source)
}

export function hasThinkTagLeak(answer: string): boolean {
  return THINK_TAG.test(answer)
}

/**
 * Loose markdown check: a header, a list, emphasis, a table, or a code fence.
 *
 * Deliberately loose. SYSTEM_PROMPTS.default asks for markdown "for
 * readability", not for a specific structure, so requiring headers would fail
 * perfectly good one-sentence answers. This only catches a model that has
 * stopped formatting entirely.
 */
export function isMarkdownFormatted(answer: string): boolean {
  return /(^|\n)\s{0,3}#{1,6}\s|(^|\n)\s*[-*+]\s|(^|\n)\s*\d+\.\s|\*\*[^*]+\*\*|`[^`]+`|(^|\n)\s*\|/.test(
    answer
  )
}

/**
 * Numeric tokens the answer asserts, normalized for comparison.
 *
 * Numbers are the highest-value fabrication signal in this domain: a wrong
 * boiling time, bleach dose, or canner pressure is a wrong answer with real
 * consequences, and it is exactly the kind of specific the rag_context prompt
 * forbids inventing.
 *
 * Thousands separators are stripped so "2,000" and "2000" compare equal.
 */
export function extractNumbers(text: string): string[] {
  const matches = text.match(/\d[\d,]*(?:\.\d+)?/g) ?? []
  const normalized = matches.map((m) => m.replace(/,/g, '').replace(/\.0+$/, ''))
  return [...new Set(normalized)]
}

/**
 * Fraction of the answer's numeric claims that the injected context supports.
 *
 * Returns null when the answer contains no numbers — a qualitative answer is
 * not ungrounded, it is just not measurable this way, and folding it in as 1.0
 * would quietly inflate the score.
 *
 * **Known limitation, stated plainly:** this only sees numbers. An answer that
 * fabricates a procedure or a proper noun scores a perfect 1.0 here. It is a
 * fabrication *detector*, not a faithfulness *guarantee* — the LLM-judge tier
 * exists for the rest. Small integers (0-10) are excluded because they appear
 * incidentally in almost any prose ("3 layers", "step 2") and would swamp the
 * signal with false grounding.
 */
export function numericGroundedness(
  answer: string,
  context: string
): { score: number | null; ungrounded: string[] } {
  const contextNumbers = new Set(extractNumbers(context))
  const claimed = extractNumbers(answer).filter((n) => {
    const value = Number.parseFloat(n)
    return !Number.isNaN(value) && value > 10
  })
  if (claimed.length === 0) return { score: null, ungrounded: [] }
  const ungrounded = claimed.filter((n) => !contextNumbers.has(n))
  return { score: (claimed.length - ungrounded.length) / claimed.length, ungrounded }
}

/** Which of a golden's patterns matched, using case-insensitive regex semantics. */
export function matchPatterns(answer: string, patterns: string[]): { matched: string[]; missed: string[] } {
  const matched: string[] = []
  const missed: string[] = []
  for (const pattern of patterns) {
    if (new RegExp(pattern, 'i').test(answer)) matched.push(pattern)
    else missed.push(pattern)
  }
  return { matched, missed }
}

export type ScoreAnswerInput = {
  answer: string
  /** The context text actually injected into the prompt; '' when none was. */
  context: string
  mustInclude: string[]
  mustNotInclude: string[]
  expectRefusal: boolean
}

export function scoreAnswer(input: ScoreAnswerInput): GenerationScores {
  const { answer, context, mustInclude, mustNotInclude, expectRefusal } = input

  const required = matchPatterns(answer, mustInclude)
  const forbidden = matchPatterns(answer, mustNotInclude)
  const refused = detectRefusal(answer)
  const grounding = numericGroundedness(answer, context)

  return {
    // An out-of-corpus question has no mustInclude patterns, so `correct` there
    // is carried entirely by refusalCorrect below rather than by assertions.
    correct: required.missed.length === 0 && forbidden.matched.length === 0,
    matchedRequired: required.matched,
    missedRequired: required.missed,
    hitForbidden: forbidden.matched,
    refused,
    refusalCorrect: expectRefusal ? refused : !refused,
    leakage: detectLeakage(answer),
    thinkTagLeak: hasThinkTagLeak(answer),
    numericGroundedness: grounding.score,
    ungroundedNumbers: grounding.ungrounded,
    markdownFormatted: isMarkdownFormatted(answer),
    length: answer.length,
  }
}

// --- aggregation over repeats -------------------------------------------------

export type RepeatStats = {
  /** How many of N repeats passed. */
  passes: number
  repeats: number
  passRate: number
  /**
   * True when the outcome was neither always-pass nor always-fail. Unstable
   * cases are excluded from gating — treating a coin flip as a regression is
   * how a harness loses the team's trust in one afternoon.
   */
  unstable: boolean
}

export function summarizeRepeats(outcomes: boolean[]): RepeatStats {
  const repeats = outcomes.length
  const passes = outcomes.filter(Boolean).length
  return {
    passes,
    repeats,
    passRate: repeats === 0 ? 0 : passes / repeats,
    unstable: repeats > 1 && passes > 0 && passes < repeats,
  }
}

export type NumericSummary = { mean: number; stddev: number; n: number }

/**
 * Mean and population standard deviation, ignoring nulls.
 *
 * The stddev is not decoration: with temperature 0 it should be near zero, and
 * a non-trivial value is the harness telling you the run is noisier than the
 * difference you are about to interpret.
 */
export function summarizeNumeric(values: Array<number | null>): NumericSummary | null {
  const defined = values.filter((v): v is number => v !== null && Number.isFinite(v))
  if (defined.length === 0) return null
  const mean = defined.reduce((a, b) => a + b, 0) / defined.length
  const variance = defined.reduce((acc, v) => acc + (v - mean) ** 2, 0) / defined.length
  return { mean, stddev: Math.sqrt(variance), n: defined.length }
}

/**
 * Loading and validating the golden question set, plus the corpus fingerprint.
 *
 * Pure and dependency-free so it runs under bare node in unit tests. Callers
 * supply file contents; nothing here touches the filesystem except through the
 * explicit `readFile`-shaped arguments the service passes in.
 */

/** A prior conversation turn, for multi-turn / coreference cases. */
export type GoldenTurn = { role: 'user' | 'assistant'; content: string }

export type Golden = {
  /** Stable identifier. Used as the join key across reports and baselines. */
  id: string
  /** The user's question, as they would actually type it. */
  query: string
  /** Conversation history preceding `query`. Empty for single-turn cases. */
  turns: GoldenTurn[]
  /**
   * Documents that genuinely answer the question, by corpus doc id (the
   * markdown filename without its extension). Empty for out-of-corpus cases.
   */
  relevantDocIds: string[]
  /**
   * Patterns the answer must contain. Each entry is a case-insensitive
   * **regular expression** — plain text is a valid regex, and alternation lets
   * one entry accept "3 minutes" or "three minutes" without inflating the list.
   */
  mustInclude: string[]
  /** Patterns the answer must NOT contain. Same regex semantics. */
  mustNotInclude: string[]
  /**
   * True when the corpus genuinely cannot answer the question and the correct
   * behaviour is to decline rather than invent. Scored as refusal-correctness.
   */
  expectRefusal: boolean
  /** Free-form buckets for per-slice reporting (single-hop, acronym, ...). */
  tags: string[]
}

export class GoldenSetError extends Error {}

/**
 * Parse a JSONL golden file, validating hard enough that a typo fails loudly at
 * load rather than silently scoring zero for the rest of the project's life.
 */
export function parseGoldens(jsonl: string, sourceName = 'goldens'): Golden[] {
  const goldens: Golden[] = []
  const seen = new Set<string>()

  jsonl.split('\n').forEach((rawLine, idx) => {
    const line = rawLine.trim()
    if (!line || line.startsWith('//')) return

    const where = `${sourceName}:${idx + 1}`
    let parsed: any
    try {
      parsed = JSON.parse(line)
    } catch (err) {
      throw new GoldenSetError(`${where}: not valid JSON — ${(err as Error).message}`)
    }

    const req = (field: string) => {
      if (parsed[field] === undefined) throw new GoldenSetError(`${where}: missing "${field}"`)
      return parsed[field]
    }

    const id = req('id')
    if (typeof id !== 'string' || !id) throw new GoldenSetError(`${where}: "id" must be a non-empty string`)
    if (seen.has(id)) throw new GoldenSetError(`${where}: duplicate id "${id}"`)
    seen.add(id)

    const query = req('query')
    if (typeof query !== 'string' || !query.trim()) {
      throw new GoldenSetError(`${where}: "query" must be a non-empty string`)
    }

    const strArray = (field: string): string[] => {
      const v = parsed[field] ?? []
      if (!Array.isArray(v) || v.some((x) => typeof x !== 'string')) {
        throw new GoldenSetError(`${where}: "${field}" must be an array of strings`)
      }
      return v
    }

    const mustInclude = strArray('mustInclude')
    const mustNotInclude = strArray('mustNotInclude')
    // Compile every pattern now. A bad regex that only blows up on the one run
    // where it finally matches is far worse than one that fails at load.
    for (const pattern of [...mustInclude, ...mustNotInclude]) {
      try {
        new RegExp(pattern, 'i')
      } catch (err) {
        throw new GoldenSetError(`${where}: invalid regex ${JSON.stringify(pattern)} — ${(err as Error).message}`)
      }
    }

    const turns = (parsed.turns ?? []) as GoldenTurn[]
    if (!Array.isArray(turns) || turns.some((t) => t?.role !== 'user' && t?.role !== 'assistant')) {
      throw new GoldenSetError(`${where}: "turns" must be an array of {role: user|assistant, content}`)
    }

    const expectRefusal = Boolean(parsed.expectRefusal)
    const relevantDocIds = strArray('relevantDocIds')
    if (expectRefusal && relevantDocIds.length > 0) {
      throw new GoldenSetError(
        `${where}: "${id}" expects a refusal but also lists relevant documents — one of those is wrong`
      )
    }
    if (!expectRefusal && relevantDocIds.length === 0) {
      throw new GoldenSetError(
        `${where}: "${id}" lists no relevant documents and does not expect a refusal — it can never be scored`
      )
    }

    goldens.push({
      id,
      query,
      turns,
      relevantDocIds,
      mustInclude,
      mustNotInclude,
      expectRefusal,
      tags: strArray('tags'),
    })
  })

  if (goldens.length === 0) throw new GoldenSetError(`${sourceName}: no goldens found`)
  return goldens
}

/**
 * Every doc id a golden refers to must exist in the corpus, or recall is being
 * computed against a target that can never be hit.
 */
export function assertGoldensMatchCorpus(goldens: Golden[], corpusDocIds: Iterable<string>): void {
  const corpus = new Set(corpusDocIds)
  const missing = new Set<string>()
  for (const g of goldens) {
    for (const docId of g.relevantDocIds) if (!corpus.has(docId)) missing.add(docId)
  }
  if (missing.size > 0) {
    throw new GoldenSetError(
      `goldens reference documents that are not in the corpus: ${[...missing].sort().join(', ')}`
    )
  }
}

/**
 * Inputs to the corpus fingerprint. Anything that changes what ends up in the
 * vector store belongs here — if it changes, prior reports are not comparable.
 */
export type FingerprintInputs = {
  /** docId -> raw file contents. */
  documents: Map<string, string>
  chunkTokens: number
  chunkOverlapTokens: number
  charToTokenRatio: number
  embeddingModel: string
  embeddingDimension: number
}

/**
 * A stable hash over the corpus and the ingest parameters that shaped it.
 *
 * Reports carry this. Comparing two reports with different fingerprints is
 * meaningless, and the compare command refuses to do it — which is the whole
 * point: it makes "I changed the chunk size and the score moved" impossible to
 * confuse with "I changed the prompt and the score moved".
 *
 * `hash` is injected so this stays pure and testable; the service passes a
 * node:crypto sha256.
 */
export function computeCorpusFingerprint(
  inputs: FingerprintInputs,
  hash: (input: string) => string
): string {
  const docIds = [...inputs.documents.keys()].sort()
  const parts: string[] = [
    `chunkTokens=${inputs.chunkTokens}`,
    `chunkOverlapTokens=${inputs.chunkOverlapTokens}`,
    `charToTokenRatio=${inputs.charToTokenRatio}`,
    `embeddingModel=${inputs.embeddingModel}`,
    `embeddingDimension=${inputs.embeddingDimension}`,
  ]
  for (const id of docIds) {
    parts.push(`doc=${id}\n${inputs.documents.get(id)}`)
  }
  return hash(parts.join('\n---\n')).slice(0, 16)
}

/**
 * Report shape, baseline diffing, and the gate decision.
 *
 * Pure functions over plain objects — the service layer does the file I/O. The
 * comparison logic in particular has to be testable without a filesystem,
 * because it is the piece that decides whether a pull request is blocked.
 */

export type ReportKind = 'retrieval' | 'generation'

/**
 * Provenance. Every field here exists to answer "is this report comparable to
 * that one?", and `corpusFingerprint` is the one that can veto the comparison
 * outright.
 */
export type ReportMeta = {
  kind: ReportKind
  createdAt: string
  corpusFingerprint: string
  gitSha: string | null
  gitBranch: string | null
  gitDirty: boolean
  nomadVersion: string | null
  /** Host platform. Recorded for context; never used to justify a score. */
  platform: {
    cpuArchitecture: string | null
    osName: string | null
    nodeVersion: string
  }
  params: Record<string, unknown>
}

/**
 * A report is metadata plus a flat bag of named metrics plus the per-case
 * detail. Flattening the metrics is deliberate: it means the diff logic does
 * not need to know anything about retrieval versus generation, so adding a
 * metric later requires no change to the comparison or the gate.
 */
export type EvalReport = {
  meta: ReportMeta
  /** metric name -> value. null means "not measurable in this run". */
  metrics: Record<string, number | null>
  /** tag -> metric name -> value. */
  byTag: Record<string, Record<string, number | null>>
  /** Per-question detail, for the "what did it actually say" question. */
  cases: unknown[]
}

/**
 * Whether a metric going up is good.
 *
 * Without this the diff cannot tell an improvement from a regression, and a
 * leakage rate falling to zero would be reported as a failure.
 */
export type MetricDirection = 'higher-is-better' | 'lower-is-better'

export const METRIC_DIRECTIONS: Record<string, MetricDirection> = {
  // retrieval
  'recall@1': 'higher-is-better',
  'recall@3': 'higher-is-better',
  'recall@5': 'higher-is-better',
  'recall@10': 'higher-is-better',
  'hitRate@1': 'higher-is-better',
  'hitRate@3': 'higher-is-better',
  'hitRate@5': 'higher-is-better',
  'hitRate@10': 'higher-is-better',
  'precision@1': 'higher-is-better',
  'precision@3': 'higher-is-better',
  'precision@5': 'higher-is-better',
  'precision@10': 'higher-is-better',
  'ndcg@1': 'higher-is-better',
  'ndcg@3': 'higher-is-better',
  'ndcg@5': 'higher-is-better',
  'ndcg@10': 'higher-is-better',
  mrr: 'higher-is-better',
  emptyRateOnAnswerable: 'lower-is-better',
  nonEmptyRateOnRefusal: 'lower-is-better',
  // generation
  correctness: 'higher-is-better',
  refusalCorrectness: 'higher-is-better',
  leakageRate: 'lower-is-better',
  thinkTagLeakRate: 'lower-is-better',
  markdownRate: 'higher-is-better',
  groundedness: 'higher-is-better',
  // context budgeting
  //
  // These are diagnostics as much as gates. A rise in historyElidedRate means
  // conversations are being trimmed more often, which explains a correctness
  // drop that would otherwise look like the model getting worse. promptTokenError
  // gates the token estimator itself: every budget decision rests on it, so a
  // regression there quietly degrades everything downstream.
  historyElidedRate: 'lower-is-better',
  chunksDroppedRate: 'lower-is-better',
  promptTokenError: 'lower-is-better',
}

export type MetricDelta = {
  metric: string
  baseline: number | null
  current: number | null
  delta: number | null
  direction: MetricDirection
  /** Signed so that positive always means "better", whatever the direction. */
  improvement: number | null
  regressed: boolean
  /** Present in one report but not the other. */
  onlyIn?: 'baseline' | 'current'
}

export type ComparisonResult = {
  comparable: boolean
  /** Why the comparison was refused, when it was. */
  incomparableReason?: string
  tolerance: number
  deltas: MetricDelta[]
  regressions: MetricDelta[]
  improvements: MetricDelta[]
}

/**
 * Default tolerance band.
 *
 * Not zero, on purpose. Even at temperature 0 the generation tier moves a
 * little between runs, and a gate that fires on 0.001 gets switched off within
 * a week. 0.02 is roughly "one question in fifty" on a 99-question set — small
 * enough to catch a real regression, large enough to ignore a coin flip.
 */
export const DEFAULT_TOLERANCE = 0.02

/**
 * Slack for floating-point representation error at the tolerance boundary.
 *
 * Without it, `0.9 - 0.02` evaluates to a delta of -0.020000000000000018, which
 * is "greater than the tolerance" by 1.8e-17 and would block a pull request. A
 * gate that fires on the last bit of a double is a gate people learn to ignore.
 */
const BOUNDARY_EPSILON = 1e-9

export function compareReports(
  baseline: EvalReport,
  current: EvalReport,
  tolerance: number = DEFAULT_TOLERANCE
): ComparisonResult {
  if (baseline.meta.kind !== current.meta.kind) {
    return incomparable(
      `cannot compare a ${baseline.meta.kind} report against a ${current.meta.kind} report`,
      tolerance
    )
  }

  // The hard veto. Different corpora, chunk sizes, or embedding models mean the
  // two numbers were produced by different experiments, and diffing them would
  // manufacture a regression (or hide one) out of nothing.
  if (baseline.meta.corpusFingerprint !== current.meta.corpusFingerprint) {
    return incomparable(
      `corpus fingerprint changed (${baseline.meta.corpusFingerprint} -> ${current.meta.corpusFingerprint}). ` +
        'The corpus, chunk size, or embedding model differs, so these runs are not measuring the same thing. Re-baseline instead.',
      tolerance
    )
  }

  const names = [...new Set([...Object.keys(baseline.metrics), ...Object.keys(current.metrics)])].sort()
  const deltas: MetricDelta[] = names.map((metric) => {
    const b = baseline.metrics[metric] ?? null
    const c = current.metrics[metric] ?? null
    const direction = METRIC_DIRECTIONS[metric] ?? 'higher-is-better'
    const onlyIn =
      !(metric in baseline.metrics) ? ('current' as const)
      : !(metric in current.metrics) ? ('baseline' as const)
      : undefined

    if (b === null || c === null) {
      return { metric, baseline: b, current: c, delta: null, direction, improvement: null, regressed: false, onlyIn }
    }

    const delta = c - b
    const improvement = direction === 'higher-is-better' ? delta : -delta
    return {
      metric,
      baseline: b,
      current: c,
      delta,
      direction,
      improvement,
      regressed: improvement < -(tolerance + BOUNDARY_EPSILON),
      onlyIn,
    }
  })

  return {
    comparable: true,
    tolerance,
    deltas,
    regressions: deltas.filter((d) => d.regressed),
    improvements: deltas.filter(
      (d) => d.improvement !== null && d.improvement > tolerance + BOUNDARY_EPSILON
    ),
  }
}

function incomparable(reason: string, tolerance: number): ComparisonResult {
  return {
    comparable: false,
    incomparableReason: reason,
    tolerance,
    deltas: [],
    regressions: [],
    improvements: [],
  }
}

/** Flatten a `Record<number, number|null>` into `name@k` keys. */
export function flattenByK(
  prefix: string,
  values: Record<number, number | null>
): Record<string, number | null> {
  return Object.fromEntries(Object.entries(values).map(([k, v]) => [`${prefix}@${k}`, v]))
}

const pct = (v: number | null) => (v === null ? 'n/a' : v.toFixed(4))

/** Human-readable summary, worst regressions first. */
export function renderComparisonMarkdown(
  baselinePath: string,
  currentPath: string,
  result: ComparisonResult
): string {
  const lines: string[] = ['# Eval comparison', '']
  lines.push(`- baseline: \`${baselinePath}\``)
  lines.push(`- current:  \`${currentPath}\``)
  lines.push(`- tolerance: ${result.tolerance}`)
  lines.push('')

  if (!result.comparable) {
    lines.push('## Not comparable', '', result.incomparableReason ?? 'unknown reason', '')
    return lines.join('\n')
  }

  lines.push(
    result.regressions.length > 0
      ? `## ${result.regressions.length} regression(s)`
      : '## No regressions'
  )
  lines.push('')
  lines.push('| metric | baseline | current | delta | verdict |')
  lines.push('|---|---:|---:|---:|---|')

  // Worst first — the thing a developer needs is at the top, not sorted
  // alphabetically halfway down a wall of unchanged rows.
  const ordered = [...result.deltas].sort((a, b) => (a.improvement ?? 0) - (b.improvement ?? 0))
  for (const d of ordered) {
    const verdict =
      d.onlyIn === 'current' ? 'new'
      : d.onlyIn === 'baseline' ? 'removed'
      : d.delta === null ? '—'
      : d.regressed ? '**REGRESSED**'
      : (d.improvement ?? 0) > result.tolerance ? 'improved'
      : 'within tolerance'
    const arrow = d.delta === null ? 'n/a' : `${d.delta >= 0 ? '+' : ''}${d.delta.toFixed(4)}`
    lines.push(`| ${d.metric} | ${pct(d.baseline)} | ${pct(d.current)} | ${arrow} | ${verdict} |`)
  }
  lines.push('')
  return lines.join('\n')
}

/**
 * Information-retrieval metrics for the RAG eval harness.
 *
 * Pure functions over ranked results — no I/O, no models, no clock. Everything
 * here is deterministic, which is the point: a change in these numbers is
 * unambiguously a change in the code, never in the weather.
 *
 * ## Two levels of measurement, and why both
 *
 * Retrieval returns *chunks*, but a golden answer lives in a *document*. The
 * two questions we care about are different, so they are measured differently:
 *
 * - **Document level** (recall, MRR, nDCG): "did the answer's document make it
 *   into the context at all, and how near the top?" Chunks are collapsed to
 *   their document, keeping each document's best rank.
 * - **Chunk level** (precision): "how much of what we injected is noise?" This
 *   is deliberately *not* deduped — five chunks from one irrelevant document
 *   cost five slots of a small model's context and should be counted five
 *   times.
 *
 * Reporting only one of these hides a real failure mode in the other.
 */

/** One retrieved chunk, reduced to what scoring needs. */
export type ScoredChunk = {
  /** Corpus document this chunk came from; null if it could not be resolved. */
  docId: string | null
  /** The pipeline's final (post-rerank) score. */
  score: number
  /** The raw pre-rerank cosine score, when available. */
  semanticScore?: number
}

export type RetrievalCase = {
  id: string
  tags: string[]
  /** Ranked chunks, best first, exactly as the pipeline returned them. */
  retrieved: ScoredChunk[]
  /** Documents that genuinely answer the question. */
  relevantDocIds: string[]
  /** True when the right behaviour is to retrieve nothing useful. */
  expectRefusal: boolean
}

/**
 * Collapse a ranked chunk list to a ranked document list, keeping each
 * document's best (earliest) position. Chunks with no resolvable document are
 * dropped — they still occupy a rank in the chunk-level metrics, but they
 * cannot be credited to any document.
 */
export function toDocumentRanking(retrieved: ScoredChunk[]): string[] {
  const seen = new Set<string>()
  const ranking: string[] = []
  for (const chunk of retrieved) {
    if (!chunk.docId || seen.has(chunk.docId)) continue
    seen.add(chunk.docId)
    ranking.push(chunk.docId)
  }
  return ranking
}

/**
 * Fraction of the relevant documents that appear within the top `k` chunks.
 *
 * Returns null when there are no relevant documents (an out-of-corpus case) —
 * recall is undefined there, and returning 0 would drag the mean down for
 * questions that are *supposed* to retrieve nothing.
 */
export function recallAtK(retrieved: ScoredChunk[], relevantDocIds: string[], k: number): number | null {
  if (relevantDocIds.length === 0) return null
  const relevant = new Set(relevantDocIds)
  const found = new Set<string>()
  for (const chunk of retrieved.slice(0, k)) {
    if (chunk.docId && relevant.has(chunk.docId)) found.add(chunk.docId)
  }
  return found.size / relevant.size
}

/**
 * 1 if *any* relevant document appears in the top `k`, else 0.
 *
 * Distinct from recall on multi-hop questions: finding one of two required
 * documents is a hit but only 0.5 recall. Reporting both is what separates
 * "found something" from "found enough to answer".
 */
export function hitRateAtK(retrieved: ScoredChunk[], relevantDocIds: string[], k: number): number | null {
  if (relevantDocIds.length === 0) return null
  const relevant = new Set(relevantDocIds)
  return retrieved.slice(0, k).some((c) => c.docId && relevant.has(c.docId)) ? 1 : 0
}

/**
 * Fraction of the top `k` *chunks* that come from a relevant document.
 *
 * Not deduped, on purpose — this measures context pollution, and a small model
 * drowning in four irrelevant chunks does not care that they share a source.
 * Denominator is min(k, retrieved.length) so a pipeline returning 2 good chunks
 * is not punished for the 3 it correctly declined to return.
 */
export function precisionAtK(retrieved: ScoredChunk[], relevantDocIds: string[], k: number): number | null {
  if (relevantDocIds.length === 0) return null
  const window = retrieved.slice(0, k)
  if (window.length === 0) return 0
  const relevant = new Set(relevantDocIds)
  const hits = window.filter((c) => c.docId && relevant.has(c.docId)).length
  return hits / window.length
}

/**
 * Reciprocal of the rank of the first relevant chunk (1-indexed); 0 if none.
 * Averaged over cases this is MRR.
 */
export function reciprocalRank(retrieved: ScoredChunk[], relevantDocIds: string[]): number | null {
  if (relevantDocIds.length === 0) return null
  const relevant = new Set(relevantDocIds)
  const idx = retrieved.findIndex((c) => c.docId && relevant.has(c.docId))
  return idx === -1 ? 0 : 1 / (idx + 1)
}

/**
 * Normalized discounted cumulative gain at `k`, over the **document** ranking,
 * with binary gain.
 *
 *   DCG@k  = Σ_{i=1..k}  rel_i / log2(i + 1)
 *   IDCG@k = Σ_{i=1..min(R, k)}  1 / log2(i + 1)        where R = |relevant|
 *   nDCG@k = DCG@k / IDCG@k
 *
 * The ideal ranking is defined against the *known* number of relevant documents
 * rather than against however many happened to be retrieved. That distinction
 * matters: normalizing against the retrieved set would score a run that found
 * one of three required documents, and ranked it first, as a perfect 1.0.
 *
 * This is the metric that catches "right documents, wrong order" — a reranking
 * regression that leaves recall untouched while pushing the answer to position
 * five, where a 1B model with a 2-result budget will never see it.
 */
export function ndcgAtK(retrieved: ScoredChunk[], relevantDocIds: string[], k: number): number | null {
  if (relevantDocIds.length === 0) return null
  const relevant = new Set(relevantDocIds)
  const docRanking = toDocumentRanking(retrieved).slice(0, k)

  let dcg = 0
  docRanking.forEach((docId, i) => {
    if (relevant.has(docId)) dcg += 1 / Math.log2(i + 2) // i is 0-indexed, so rank = i + 1
  })

  let idcg = 0
  for (let i = 0; i < Math.min(relevant.size, k); i++) {
    idcg += 1 / Math.log2(i + 2)
  }

  return idcg === 0 ? 0 : dcg / idcg
}

/**
 * Score separation: the gap between what relevant and irrelevant chunks score.
 *
 * This is how the similarity threshold gets calibrated with evidence instead of
 * intuition. If the relevant p10 sits below the irrelevant p90, no threshold
 * can cleanly separate them and the honest conclusion is that the *retriever*
 * needs work, not the cutoff.
 *
 * ## Two axes, because there are two cutoffs
 *
 * A chunk carries two scores and they are not interchangeable:
 *
 * - the **semantic** score is raw cosine, and it is what Qdrant's
 *   `score_threshold` filters on — before reranking ever runs;
 * - the **final** score is what reranking and source diversity produced, and it
 *   is what `RAG_MIN_FINAL_SCORE` filters on.
 *
 * Reranking's boosts are score-scaled and additive (up to ~1.275x), so the two
 * distributions sit at different heights. Calibrating one cutoff against the
 * other axis' percentiles is off by exactly that factor, which is why both are
 * reported separately rather than collapsed into one number.
 */
export type ScoreDistribution = {
  count: number
  min: number
  p10: number
  median: number
  p90: number
  max: number
  mean: number
}

export function describeScores(scores: number[]): ScoreDistribution | null {
  if (scores.length === 0) return null
  const sorted = [...scores].sort((a, b) => a - b)
  const pct = (p: number) => {
    // Nearest-rank percentile: no interpolation, so a reported value is always
    // a value that actually occurred.
    const idx = Math.min(sorted.length - 1, Math.max(0, Math.ceil((p / 100) * sorted.length) - 1))
    return sorted[idx]
  }
  return {
    count: sorted.length,
    min: sorted[0],
    p10: pct(10),
    median: pct(50),
    p90: pct(90),
    max: sorted[sorted.length - 1],
    mean: sorted.reduce((a, b) => a + b, 0) / sorted.length,
  }
}

/** Mean over the entries that are actually defined; null if none are. */
export function meanOf(values: Array<number | null>): number | null {
  const defined = values.filter((v): v is number => v !== null)
  if (defined.length === 0) return null
  return defined.reduce((a, b) => a + b, 0) / defined.length
}

export type RetrievalCaseResult = {
  id: string
  tags: string[]
  retrievedCount: number
  relevantDocIds: string[]
  retrievedDocIds: string[]
  expectRefusal: boolean
  recall: Record<number, number | null>
  hitRate: Record<number, number | null>
  precision: Record<number, number | null>
  ndcg: Record<number, number | null>
  reciprocalRank: number | null
  /** True when this case retrieved nothing at all. */
  empty: boolean
  /**
   * The highest-ranked chunk's scores, or null when nothing was retrieved. Shown
   * for out-of-corpus leaks: the gap between the two says how much of a false
   * positive the reranker's lexical boosts supplied.
   */
  top: { score: number; semanticScore: number | null } | null
}

export type RetrievalAggregate = {
  cases: number
  /** Cases with at least one relevant document (i.e. excluding refusal cases). */
  answerable: number
  recall: Record<number, number | null>
  hitRate: Record<number, number | null>
  precision: Record<number, number | null>
  ndcg: Record<number, number | null>
  mrr: number | null
  /**
   * Fraction of *answerable* questions that retrieved nothing. A non-zero value
   * means the score threshold is filtering out real answers.
   */
  emptyRateOnAnswerable: number | null
  /**
   * Fraction of *out-of-corpus* questions that retrieved something anyway. This
   * is the other half of the threshold trade-off: context handed to the model
   * for a question the corpus cannot answer is exactly what produces a
   * confident, wrong reply.
   */
  nonEmptyRateOnRefusal: number | null
  /** Semantic (raw cosine) scores — the axis Qdrant's score_threshold filters on. */
  relevantScores: ScoreDistribution | null
  irrelevantScores: ScoreDistribution | null
  /** Post-rerank scores — the axis RAG_MIN_FINAL_SCORE filters on. */
  relevantFinalScores: ScoreDistribution | null
  irrelevantFinalScores: ScoreDistribution | null
}

export const DEFAULT_K_VALUES = [1, 3, 5, 10]

export function scoreCase(c: RetrievalCase, kValues: number[] = DEFAULT_K_VALUES): RetrievalCaseResult {
  const byK = <T>(fn: (k: number) => T): Record<number, T> =>
    Object.fromEntries(kValues.map((k) => [k, fn(k)]))

  return {
    id: c.id,
    tags: c.tags,
    retrievedCount: c.retrieved.length,
    relevantDocIds: c.relevantDocIds,
    retrievedDocIds: toDocumentRanking(c.retrieved),
    expectRefusal: c.expectRefusal,
    recall: byK((k) => recallAtK(c.retrieved, c.relevantDocIds, k)),
    hitRate: byK((k) => hitRateAtK(c.retrieved, c.relevantDocIds, k)),
    precision: byK((k) => precisionAtK(c.retrieved, c.relevantDocIds, k)),
    ndcg: byK((k) => ndcgAtK(c.retrieved, c.relevantDocIds, k)),
    reciprocalRank: reciprocalRank(c.retrieved, c.relevantDocIds),
    empty: c.retrieved.length === 0,
    top:
      c.retrieved.length === 0
        ? null
        : { score: c.retrieved[0].score, semanticScore: c.retrieved[0].semanticScore ?? null },
  }
}

export function aggregate(
  cases: RetrievalCase[],
  results: RetrievalCaseResult[],
  kValues: number[] = DEFAULT_K_VALUES
): RetrievalAggregate {
  const answerable = results.filter((r) => !r.expectRefusal)
  const refusals = results.filter((r) => r.expectRefusal)

  const byK = (pick: (r: RetrievalCaseResult, k: number) => number | null): Record<number, number | null> =>
    Object.fromEntries(kValues.map((k) => [k, meanOf(results.map((r) => pick(r, k)))]))

  // Split every retrieved chunk's score by whether its document was relevant.
  // Refusal cases contribute only to the irrelevant side — by definition
  // nothing they retrieve is relevant, and that is precisely the population a
  // threshold needs to exclude.
  const relevantScores: number[] = []
  const irrelevantScores: number[] = []
  const relevantFinalScores: number[] = []
  const irrelevantFinalScores: number[] = []
  for (const c of cases) {
    const relevant = new Set(c.relevantDocIds)
    for (const chunk of c.retrieved) {
      const isRelevant = Boolean(chunk.docId && relevant.has(chunk.docId))
      ;(isRelevant ? relevantScores : irrelevantScores).push(chunk.semanticScore ?? chunk.score)
      ;(isRelevant ? relevantFinalScores : irrelevantFinalScores).push(chunk.score)
    }
  }

  return {
    cases: results.length,
    answerable: answerable.length,
    recall: byK((r, k) => r.recall[k]),
    hitRate: byK((r, k) => r.hitRate[k]),
    precision: byK((r, k) => r.precision[k]),
    ndcg: byK((r, k) => r.ndcg[k]),
    mrr: meanOf(results.map((r) => r.reciprocalRank)),
    emptyRateOnAnswerable:
      answerable.length === 0 ? null : answerable.filter((r) => r.empty).length / answerable.length,
    nonEmptyRateOnRefusal:
      refusals.length === 0 ? null : refusals.filter((r) => !r.empty).length / refusals.length,
    relevantScores: describeScores(relevantScores),
    irrelevantScores: describeScores(irrelevantScores),
    relevantFinalScores: describeScores(relevantFinalScores),
    irrelevantFinalScores: describeScores(irrelevantFinalScores),
  }
}

/** Aggregate restricted to cases carrying a given tag, for per-slice reporting. */
export function aggregateByTag(
  cases: RetrievalCase[],
  results: RetrievalCaseResult[],
  kValues: number[] = DEFAULT_K_VALUES
): Record<string, RetrievalAggregate> {
  const tags = new Set(results.flatMap((r) => r.tags))
  const byId = new Map(cases.map((c) => [c.id, c]))
  const out: Record<string, RetrievalAggregate> = {}
  for (const tag of [...tags].sort()) {
    const tagged = results.filter((r) => r.tags.includes(tag))
    out[tag] = aggregate(
      tagged.map((r) => byId.get(r.id)!).filter(Boolean),
      tagged,
      kValues
    )
  }
  return out
}

