    app.listen('SIGTERM', () => app.terminate())
    app.listenIf(app.managedByPm2, 'SIGINT', () => app.terminate())
  })
  .testRunner()
  .configure(async (app) => {
    const { runnerHooks, ...config } = await import('../tests/bootstrap.js')

    processCLIArgs(process.argv.splice(2))
    configure({
      ...app.rcFile.tests,
      ...config,
      ...{
        setup: runnerHooks.setup,
        teardown: runnerHooks.teardown.concat([() => app.terminate()]),
      },
    })
  })
  .run(() => run())
  .catch((error) => {
    process.exitCode = 1
    prettyPrintError(error)
  })

import { BaseCommand, flags } from '@adonisjs/core/ace'
import type { CommandOptions } from '@adonisjs/core/types/ace'

/**
 * Exercise the app auto-update decision logic WITHOUT ever triggering a real update.
 *
 *   # Prove the per-app eligibility + window logic deterministically (no DB/Docker):
 *   node ace app-auto-update:dry-run --scenarios
 *
 *   # Show, against the live DB, which opted-in apps WOULD update right now:
 *   node ace app-auto-update:dry-run
 */
export default class AppAutoUpdateDryRun extends BaseCommand {
  static commandName = 'app-auto-update:dry-run'
  static description = 'Dry-run the app auto-update decision logic (never triggers an update)'

  @flags.boolean({ description: 'Run the built-in deterministic scenario suite and exit' })
  declare scenarios: boolean

  static options: CommandOptions = {
    startApp: true,
  }

  async run() {
    const { DateTime } = await import('luxon')
    const { DockerService } = await import('#services/docker_service')
    const { DownloadService } = await import('#services/download_service')
    const { SystemService } = await import('#services/system_service')
    const { ContainerRegistryService } = await import('#services/container_registry_service')
    const { QueueService } = await import('#services/queue_service')
    const { AppAutoUpdateService } = await import('#services/app_auto_update_service')
    const { isWithinWindow } = await import('../../app/utils/update_window.js')

    const dockerService = new DockerService()
    const svc = new AppAutoUpdateService(
      dockerService,
      new DownloadService(QueueService.getInstance()),
      new SystemService(dockerService),
      new ContainerRegistryService()
    )

    if (this.scenarios) {
      const ok = this.runScenarios(svc, DateTime, isWithinWindow)
      if (!ok) this.exitCode = 1
      return
    }

    // --- Live read-only snapshot (no update triggered) ----------------------
    const status = await svc.getStatus()
    this.logger.log('')
    this.logger.log(`  Master switch   : ${status.enabled ? 'enabled' : 'disabled'}`)
    this.logger.log(
      `  Window          : ${status.windowStart}-${status.windowEnd} ` +
        `(currently ${status.withinWindow ? 'inside' : 'outside'})`
    )
    this.logger.log(`  Cool-off hours  : ${status.cooloffHours}`)
    this.logger.log('')
    if (status.apps.length === 0) {
      this.logger.info('No apps are opted into auto-update.')
      return
    }
    this.logger.log('Opted-in apps:')
    for (const app of status.apps) {
      const tag = app.eligible ? this.colors.green('WOULD UPDATE') : this.colors.dim('skip')
      this.logger.log(
        `  ${tag}  ${app.friendly_name || app.service_name}: ${app.current_version}` +
          `${app.available_update_version ? ' → ' + app.available_update_version : ''} — ${app.reason}`
      )
    }
  }

  /**
   * Deterministic acceptance suite over the pure decision helpers — no DB or Docker.
   * Uses ContainerRegistryService.parseImageReference (pure) via appEligibility.
   */
  private runScenarios(svc: any, DateTime: any, isWithinWindow: any): boolean {
    const now = DateTime.fromISO('2026-06-04T12:00:00Z')
    const daysAgo = (d: number) => now.minus({ days: d })
    const hoursAgo = (h: number) => now.minus({ hours: h })

    const mk = (o: Record<string, any>) => ({
      service_name: 'nomad_test',
      container_image: 'ollama/ollama:0.18.1',
      available_update_version: null,
      available_update_first_seen_at: null,
      auto_update_disabled_reason: null,
      ...o,
    })

    type Case = { name: string; service: any; cooloff: number; expect: boolean }
    const cases: Case[] = [
      { name: 'no update → not eligible', service: mk({}), cooloff: 72, expect: false },
      {
        name: 'major bump → not eligible',
        service: mk({
          available_update_version: '1.0.0',
          available_update_first_seen_at: daysAgo(10),
        }),
        cooloff: 72,
        expect: false,
      },
      {
        name: 'minor newer inside cool-off → not eligible',
        service: mk({
          available_update_version: '0.19.0',
          available_update_first_seen_at: hoursAgo(10),
        }),
        cooloff: 72,
        expect: false,
      },
      {
        name: 'minor newer past cool-off → eligible',
        service: mk({
          available_update_version: '0.19.0',
          available_update_first_seen_at: daysAgo(5),
        }),
        cooloff: 72,
        expect: true,
      },
      {
        name: 'null first-seen → not eligible',
        service: mk({ available_update_version: '0.19.0', available_update_first_seen_at: null }),
        cooloff: 72,
        expect: false,
      },
      {
        name: 'self-disabled → not eligible',
        service: mk({
          available_update_version: '0.19.0',
          available_update_first_seen_at: daysAgo(30),
          auto_update_disabled_reason: 'disabled',
        }),
        cooloff: 72,
        expect: false,
      },
      {
        name: ':latest pinned → not eligible',
        service: mk({
          container_image: 'foo/bar:latest',
          available_update_version: '1.2.3',
          available_update_first_seen_at: daysAgo(30),
        }),
        cooloff: 72,
        expect: false,
      },
      {
        name: 'cool-off 0 applies immediately',
        service: mk({
          available_update_version: '0.18.2',
          available_update_first_seen_at: hoursAgo(1),
        }),
        cooloff: 0,
        expect: true,
      },
    ]

    type WinCase = { name: string; start: string; end: string; at: string; expect: boolean }
    const at = (hhmm: string) => `2026-06-04T${hhmm}:00`
    const windows: WinCase[] = [
      {
        name: 'normal 20:00-23:00 @ 21:00 → in',
        start: '20:00',
        end: '23:00',
        at: at('21:00'),
        expect: true,
      },
      {
        name: 'normal 20:00-23:00 @ 19:00 → out',
        start: '20:00',
        end: '23:00',
        at: at('19:00'),
        expect: false,
      },
      {
        name: 'wrap 22:00-02:00 @ 01:00 → in',
        start: '22:00',
        end: '02:00',
        at: at('01:00'),
        expect: true,
      },
      {
        name: 'wrap 22:00-02:00 @ 12:00 → out',
        start: '22:00',
        end: '02:00',
        at: at('12:00'),
        expect: false,
      },
    ]

    let passed = 0
    let failed = 0

    this.logger.log('')
    this.logger.log('Eligibility scenarios:')
    for (const c of cases) {
      const got = svc.appEligibility(c.service, c.cooloff, now).eligible
      const ok = got === c.expect
      this.report(ok, `${c.name} (expected ${c.expect}, got ${got})`)
      ok ? passed++ : failed++
    }

    this.logger.log('')
    this.logger.log('Window scenarios:')
    for (const c of windows) {
      const got = isWithinWindow(c.start, c.end, DateTime.fromISO(c.at))
      const ok = got === c.expect
      this.report(ok, `${c.name} (expected ${c.expect}, got ${got})`)
      ok ? passed++ : failed++
    }

    this.logger.log('')
    if (failed === 0) {
      this.logger.success(`All ${passed} scenarios passed`)
    } else {
      this.logger.error(`${failed} scenario(s) failed, ${passed} passed`)
    }
    return failed === 0
  }

  private report(ok: boolean, message: string) {
    if (ok) {
      this.logger.log(`  ${this.colors.green('✓')} ${message}`)
    } else {
      this.logger.log(`  ${this.colors.red('✗')} ${message}`)
    }
  }
}

import { BaseCommand, flags } from '@adonisjs/core/ace'
import type { CommandOptions } from '@adonisjs/core/types/ace'
import { readFile } from 'node:fs/promises'

/**
 * Exercise the auto-update decision pipeline WITHOUT ever triggering a real update.
 *
 *   # Prove the core logic deterministically (no network/DB/Docker):
 *   node ace auto-update:dry-run --scenarios
 *
 *   # Simulate "what would happen if I were running 1.32.0 right now"
 *   # against the live GitHub releases feed and real pre-flight checks:
 *   node ace auto-update:dry-run --current=1.32.0 --force-enabled
 *
 *   # Fully offline simulation with a canned release list + fixed clock:
 *   node ace auto-update:dry-run --current=1.32.0 --force-enabled \
 *     --releases-file=./fixtures/releases.json --now=2026-06-04T21:00:00Z \
 *     --window-start=20:00 --window-end=23:00 --skip-preflight
 */
export default class AutoUpdateDryRun extends BaseCommand {
  static commandName = 'auto-update:dry-run'
  static description = 'Dry-run the auto-update decision pipeline (never triggers an update)'

  @flags.boolean({ description: 'Run the built-in deterministic scenario suite and exit' })
  declare scenarios: boolean

  @flags.string({ description: 'Simulate this currently-running version (e.g. 1.32.0)' })
  declare current: string

  @flags.boolean({ description: 'Ignore the persisted enabled setting and treat as enabled' })
  declare forceEnabled: boolean

  @flags.string({ description: 'Override cool-off hours' })
  declare cooloff: string

  @flags.string({ description: 'Override window start (HH:MM)' })
  declare windowStart: string

  @flags.string({ description: 'Override window end (HH:MM)' })
  declare windowEnd: string

  @flags.string({ description: 'Simulate the clock at this ISO timestamp' })
  declare now: string

  @flags.string({ description: 'Path to a JSON file with a GitHub releases array (offline)' })
  declare releasesFile: string

  @flags.boolean({ description: 'Bypass Docker/disk/queue pre-flight checks' })
  declare skipPreflight: boolean

  static options: CommandOptions = {
    startApp: true,
  }

  async run() {
    const { DateTime } = await import('luxon')
    const { DockerService } = await import('#services/docker_service')
    const { DownloadService } = await import('#services/download_service')
    const { SystemService } = await import('#services/system_service')
    const { SystemUpdateService } = await import('#services/system_update_service')
    const { ContainerRegistryService } = await import('#services/container_registry_service')
    const { QueueService } = await import('#services/queue_service')
    const { AutoUpdateService } = await import('#services/auto_update_service')

    const dockerService = new DockerService()
    const svc = new AutoUpdateService(
      dockerService,
      new DownloadService(QueueService.getInstance()),
      new SystemService(dockerService),
      new SystemUpdateService(),
      new ContainerRegistryService()
    )

    if (this.scenarios) {
      const ok = this.runScenarios(svc, DateTime)
      if (!ok) {
        this.exitCode = 1
      }
      return
    }

    // --- Live / simulated single dry run ------------------------------------
    const overrides: Record<string, any> = {}
    if (this.current) overrides.currentVersion = this.current
    if (this.forceEnabled) overrides.forceEnabled = true
    if (this.cooloff) overrides.cooloffHours = Number(this.cooloff)
    if (this.windowStart) overrides.windowStart = this.windowStart
    if (this.windowEnd) overrides.windowEnd = this.windowEnd
    if (this.skipPreflight) overrides.skipPreflight = true
    if (this.now) overrides.now = DateTime.fromISO(this.now)
    if (this.releasesFile) {
      const raw = await readFile(this.releasesFile, 'utf-8')
      overrides.releases = JSON.parse(raw)
    }

    this.logger.info('Running auto-update dry run (no update will be triggered)...')
    const decision = await svc.dryRun(overrides)

    this.logger.log('')
    this.logger.log(`  Current version : ${decision.currentVersion}`)
    this.logger.log(`  Enabled         : ${decision.enabled}`)
    this.logger.log(
      `  Window          : ${decision.config.windowStart}-${decision.config.windowEnd} ` +
        `(currently ${decision.withinWindow ? 'inside' : 'outside'})`
    )
    this.logger.log(`  Cool-off hours  : ${decision.config.cooloffHours}`)
    this.logger.log(
      `  Eligible target : ${decision.eligibleTarget ? decision.eligibleTarget.tag + ' (published ' + decision.eligibleTarget.publishedAt + ')' : '—'}`
    )
    if (decision.preflight) {
      if (decision.preflight.ok) {
        this.logger.log(`  Pre-flight      : ok`)
      } else {
        this.logger.log(`  Pre-flight      : BLOCKED`)
        for (const b of decision.preflight.blockers) {
          this.logger.log(`      - [${b.severity}] ${b.reason}`)
        }
      }
    } else {
      this.logger.log(`  Pre-flight      : (not reached)`)
    }
    this.logger.log('')

    const verdict =
      decision.outcome === 'ready'
        ? `WOULD UPDATE → ${decision.eligibleTarget!.tag}`
        : `WOULD NOT UPDATE (${decision.outcome}): ${decision.reason}`
    if (decision.outcome === 'ready') {
      this.logger.success(verdict)
    } else {
      this.logger.info(verdict)
    }
  }

  /**
   * Deterministic acceptance suite over the pure decision helpers — no network,
   * DB, or Docker. Proves every branch reviewers care about.
   */
  private runScenarios(svc: any, DateTime: any): boolean {
    const NOW = '2026-06-04T12:00:00Z'
    const now = DateTime.fromISO(NOW)
    const daysAgo = (d: number) => now.minus({ days: d }).toISO()
    const hoursAgo = (h: number) => now.minus({ hours: h }).toISO()
    const rel = (tag: string, published: string, extra: object = {}) => ({
      tag_name: tag,
      published_at: published,
      ...extra,
    })

    type EligCase = {
      name: string
      releases: any[]
      current: string
      cooloff: number
      expect: string | null
    }

    const eligibility: EligCase[] = [
      {
        name: 'only a major bump is newer → none (major requires manual)',
        releases: [rel('v2.0.0', daysAgo(10))],
        current: '1.32.0',
        cooloff: 72,
        expect: null,
      },
      {
        name: 'same-major minor newer but inside cool-off → none',
        releases: [rel('v1.33.0', hoursAgo(10))],
        current: '1.32.0',
        cooloff: 72,
        expect: null,
      },
      {
        name: 'same-major patch past cool-off → selected',
        releases: [rel('v1.32.1', daysAgo(5))],
        current: '1.32.0',
        cooloff: 72,
        expect: '1.32.1',
      },
      {
        name: 'mixed: newest same-major past cool-off wins; major/in-cooloff/prerelease ignored',
        releases: [
          rel('v2.0.0', daysAgo(30)),
          rel('v1.34.0', hoursAgo(5)),
          rel('v1.33.2', daysAgo(4)),
          rel('v1.33.5', daysAgo(1), { prerelease: true }),
          rel('v1.33.0', daysAgo(8)),
        ],
        current: '1.32.9',
        cooloff: 72,
        expect: '1.33.2',
      },
      {
        name: 'draft releases ignored',
        releases: [rel('v1.33.0', daysAgo(5), { draft: true })],
        current: '1.32.0',
        cooloff: 72,
        expect: null,
      },
      {
        name: 'malformed tag with injection chars → ignored (M2)',
        releases: [rel('v1.33.0|; e reboot', daysAgo(10))],
        current: '1.32.0',
        cooloff: 72,
        expect: null,
      },
      {
        name: 'dev build never updates',
        releases: [rel('v1.33.0', daysAgo(10))],
        current: 'dev',
        cooloff: 72,
        expect: null,
      },
      {
        name: 'cool-off of 0 applies immediately',
        releases: [rel('v1.32.1', hoursAgo(1))],
        current: '1.32.0',
        cooloff: 0,
        expect: '1.32.1',
      },
    ]

    type WinCase = { name: string; start: string; end: string; at: string; expect: boolean }
    const at = (hhmm: string) => `2026-06-04T${hhmm}:00`
    const windows: WinCase[] = [
      {
        name: 'normal 20:00-23:00 @ 21:00 → in',
        start: '20:00',
        end: '23:00',
        at: at('21:00'),
        expect: true,
      },
      {
        name: 'normal 20:00-23:00 @ 19:00 → out',
        start: '20:00',
        end: '23:00',
        at: at('19:00'),
        expect: false,
      },
      {
        name: 'wrap 22:00-02:00 @ 23:00 → in',
        start: '22:00',
        end: '02:00',
        at: at('23:00'),
        expect: true,
      },
      {
        name: 'wrap 22:00-02:00 @ 01:00 → in',
        start: '22:00',
        end: '02:00',
        at: at('01:00'),
        expect: true,
      },
      {
        name: 'wrap 22:00-02:00 @ 12:00 → out',
        start: '22:00',
        end: '02:00',
        at: at('12:00'),
        expect: false,
      },
    ]

    let passed = 0
    let failed = 0

    this.logger.log('')
    this.logger.log('Eligibility scenarios:')
    for (const c of eligibility) {
      const got = svc.selectEligibleTarget(c.releases, c.current, c.cooloff, now)
      const gotVersion = got ? got.version : null
      const ok = gotVersion === c.expect
      this.report(ok, `${c.name} (expected ${c.expect ?? 'none'}, got ${gotVersion ?? 'none'})`)
      ok ? passed++ : failed++
    }

    this.logger.log('')
    this.logger.log('Window scenarios:')
    for (const c of windows) {
      const cfg = { enabled: true, windowStart: c.start, windowEnd: c.end, cooloffHours: 72 }
      const got = svc.isWithinWindow(cfg, DateTime.fromISO(c.at))
      const ok = got === c.expect
      this.report(ok, `${c.name} (expected ${c.expect}, got ${got})`)
      ok ? passed++ : failed++
    }

    this.logger.log('')
    if (failed === 0) {
      this.logger.success(`All ${passed} scenarios passed`)
    } else {
      this.logger.error(`${failed} scenario(s) failed, ${passed} passed`)
    }
    return failed === 0
  }

  private report(ok: boolean, message: string) {
    if (ok) {
      this.logger.log(`  ${this.colors.green('✓')} ${message}`)
    } else {
      this.logger.log(`  ${this.colors.red('✗')} ${message}`)
    }
  }
}

import { BaseCommand, flags } from '@adonisjs/core/ace'
import type { CommandOptions } from '@adonisjs/core/types/ace'

export default class BenchmarkResults extends BaseCommand {
  static commandName = 'benchmark:results'
  static description = 'Display benchmark results'

  @flags.boolean({ description: 'Show only the latest result', alias: 'l' })
  declare latest: boolean

  @flags.string({ description: 'Output format (table, json)', default: 'table' })
  declare format: string

  @flags.string({ description: 'Show specific benchmark by ID', alias: 'i' })
  declare id: string

  static options: CommandOptions = {
    startApp: true,
  }

  async run() {
    const { DockerService } = await import('#services/docker_service')
    const { BenchmarkService } = await import('#services/benchmark_service')
    const dockerService = new DockerService()
    const benchmarkService = new BenchmarkService(dockerService)

    try {
      let results

      if (this.id) {
        const result = await benchmarkService.getResultById(this.id)
        results = result ? [result] : []
      } else if (this.latest) {
        const result = await benchmarkService.getLatestResult()
        results = result ? [result] : []
      } else {
        results = await benchmarkService.getAllResults()
      }

      if (results.length === 0) {
        this.logger.info('No benchmark results found.')
        this.logger.info('Run "node ace benchmark:run" to create a benchmark.')
        return
      }

      if (this.format === 'json') {
        console.log(JSON.stringify(results, null, 2))
        return
      }

      // Table format
      for (const result of results) {
        this.logger.info('')
        this.logger.info(`=== Benchmark ${result.benchmark_id} ===`)
        this.logger.info(`Type: ${result.benchmark_type}`)
        this.logger.info(`Date: ${result.created_at}`)
        this.logger.info('')

        this.logger.info('Hardware:')
        this.logger.info(`  CPU: ${result.cpu_model}`)
        this.logger.info(`  Cores: ${result.cpu_cores} physical, ${result.cpu_threads} threads`)
        this.logger.info(`  RAM: ${Math.round(result.ram_bytes / (1024 * 1024 * 1024))} GB`)
        this.logger.info(`  Disk: ${result.disk_type}`)
        if (result.gpu_model) {
          this.logger.info(`  GPU: ${result.gpu_model}`)
        }
        this.logger.info('')

        this.logger.info('Scores:')
        this.logger.info(`  CPU: ${result.cpu_score.toFixed(2)}`)
        this.logger.info(`  Memory: ${result.memory_score.toFixed(2)}`)
        this.logger.info(`  Disk Read: ${result.disk_read_score.toFixed(2)}`)
        this.logger.info(`  Disk Write: ${result.disk_write_score.toFixed(2)}`)

        if (result.ai_tokens_per_second) {
          this.logger.info(`  AI Tokens/sec: ${result.ai_tokens_per_second.toFixed(2)}`)
          this.logger.info(`  AI TTFT: ${result.ai_time_to_first_token?.toFixed(2)} ms`)
        }
        this.logger.info('')

        this.logger.info(`NOMAD Score: ${result.nomad_score.toFixed(2)} / 100`)

        if (result.submitted_to_repository) {
          this.logger.info(`Submitted: Yes (${result.repository_id})`)
        } else {
          this.logger.info('Submitted: No')
        }
        this.logger.info('')
      }

      this.logger.info(`Total results: ${results.length}`)

    } catch (error) {
      this.logger.error(`Failed to retrieve results: ${error.message}`)
      this.exitCode = 1
    }
  }
}

import { BaseCommand, flags } from '@adonisjs/core/ace'
import type { CommandOptions } from '@adonisjs/core/types/ace'

export default class BenchmarkRun extends BaseCommand {
  static commandName = 'benchmark:run'
  static description = 'Run system and/or AI benchmarks to measure server performance'

  @flags.boolean({ description: 'Run system benchmarks only (CPU, memory, disk)', alias: 's' })
  declare systemOnly: boolean

  @flags.boolean({ description: 'Run AI benchmark only', alias: 'a' })
  declare aiOnly: boolean

  @flags.boolean({ description: 'Submit results to repository after completion', alias: 'S' })
  declare submit: boolean

  static options: CommandOptions = {
    startApp: true,
  }

  async run() {
    const { DockerService } = await import('#services/docker_service')
    const { BenchmarkService } = await import('#services/benchmark_service')
    const dockerService = new DockerService()
    const benchmarkService = new BenchmarkService(dockerService)

    // Determine benchmark type
    let benchmarkType: 'full' | 'system' | 'ai' = 'full'
    if (this.systemOnly) {
      benchmarkType = 'system'
    } else if (this.aiOnly) {
      benchmarkType = 'ai'
    }

    this.logger.info(`Starting ${benchmarkType} benchmark...`)
    this.logger.info('')

    try {
      // Run the benchmark
      let result
      switch (benchmarkType) {
        case 'system':
          this.logger.info('Running system benchmarks (CPU, memory, disk)...')
          result = await benchmarkService.runSystemBenchmarks()
          break
        case 'ai':
          this.logger.info('Running AI benchmark...')
          result = await benchmarkService.runAIBenchmark()
          break
        default:
          this.logger.info('Running full benchmark suite...')
          result = await benchmarkService.runFullBenchmark()
      }

      // Display results
      this.logger.info('')
      this.logger.success('Benchmark completed!')
      this.logger.info('')

      this.logger.info('=== Hardware Info ===')
      this.logger.info(`CPU: ${result.cpu_model}`)
      this.logger.info(`Cores: ${result.cpu_cores} physical, ${result.cpu_threads} threads`)
      this.logger.info(`RAM: ${Math.round(result.ram_bytes / (1024 * 1024 * 1024))} GB`)
      this.logger.info(`Disk Type: ${result.disk_type}`)
      if (result.gpu_model) {
        this.logger.info(`GPU: ${result.gpu_model}`)
      }

      this.logger.info('')
      this.logger.info('=== Benchmark Scores ===')
      this.logger.info(`CPU Score: ${result.cpu_score.toFixed(2)}`)
      this.logger.info(`Memory Score: ${result.memory_score.toFixed(2)}`)
      this.logger.info(`Disk Read Score: ${result.disk_read_score.toFixed(2)}`)
      this.logger.info(`Disk Write Score: ${result.disk_write_score.toFixed(2)}`)

      if (result.ai_tokens_per_second) {
        this.logger.info(`AI Tokens/sec: ${result.ai_tokens_per_second.toFixed(2)}`)
        this.logger.info(`AI Time to First Token: ${result.ai_time_to_first_token?.toFixed(2)} ms`)
        this.logger.info(`AI Model: ${result.ai_model_used}`)
      }

      this.logger.info('')
      this.logger.info(`NOMAD Score: ${result.nomad_score.toFixed(2)} / 100`)
      this.logger.info('')
      this.logger.info(`Benchmark ID: ${result.benchmark_id}`)

      // Submit if requested
      if (this.submit) {
        this.logger.info('')
        this.logger.info('Submitting results to repository...')
        try {
          const submitResult = await benchmarkService.submitToRepository(result.benchmark_id)
          this.logger.success(`Results submitted! Repository ID: ${submitResult.repository_id}`)
          this.logger.info(`Your percentile: ${submitResult.percentile}%`)
        } catch (error) {
          this.logger.error(`Failed to submit: ${error.message}`)
        }
      }

    } catch (error) {
      this.logger.error(`Benchmark failed: ${error.message}`)
      this.exitCode = 1
    }
  }
}

import { BaseCommand, flags } from '@adonisjs/core/ace'
import type { CommandOptions } from '@adonisjs/core/types/ace'

export default class BenchmarkSubmit extends BaseCommand {
  static commandName = 'benchmark:submit'
  static description = 'Submit benchmark results to the community repository'

  @flags.string({ description: 'Benchmark ID to submit (defaults to latest)', alias: 'i' })
  declare benchmarkId: string

  @flags.boolean({ description: 'Skip confirmation prompt', alias: 'y' })
  declare yes: boolean

  static options: CommandOptions = {
    startApp: true,
  }

  async run() {
    const { DockerService } = await import('#services/docker_service')
    const { BenchmarkService } = await import('#services/benchmark_service')
    const dockerService = new DockerService()
    const benchmarkService = new BenchmarkService(dockerService)

    try {
      // Get the result to submit
      const result = this.benchmarkId
        ? await benchmarkService.getResultById(this.benchmarkId)
        : await benchmarkService.getLatestResult()

      if (!result) {
        this.logger.error('No benchmark result found.')
        this.logger.info('Run "node ace benchmark:run" first to create a benchmark.')
        this.exitCode = 1
        return
      }

      if (result.submitted_to_repository) {
        this.logger.warning(`Benchmark ${result.benchmark_id} has already been submitted.`)
        this.logger.info(`Repository ID: ${result.repository_id}`)
        return
      }

      // Show what will be submitted
      this.logger.info('')
      this.logger.info('=== Data to be submitted ===')
      this.logger.info('')
      this.logger.info('Hardware Information:')
      this.logger.info(`  CPU Model: ${result.cpu_model}`)
      this.logger.info(`  CPU Cores: ${result.cpu_cores}`)
      this.logger.info(`  CPU Threads: ${result.cpu_threads}`)
      this.logger.info(`  RAM: ${Math.round(result.ram_bytes / (1024 * 1024 * 1024))} GB`)
      this.logger.info(`  Disk Type: ${result.disk_type}`)
      if (result.gpu_model) {
        this.logger.info(`  GPU: ${result.gpu_model}`)
      }
      this.logger.info('')
      this.logger.info('Benchmark Scores:')
      this.logger.info(`  CPU Score: ${result.cpu_score.toFixed(2)}`)
      this.logger.info(`  Memory Score: ${result.memory_score.toFixed(2)}`)
      this.logger.info(`  Disk Read: ${result.disk_read_score.toFixed(2)}`)
      this.logger.info(`  Disk Write: ${result.disk_write_score.toFixed(2)}`)
      if (result.ai_tokens_per_second) {
        this.logger.info(`  AI Tokens/sec: ${result.ai_tokens_per_second.toFixed(2)}`)
        this.logger.info(`  AI TTFT: ${result.ai_time_to_first_token?.toFixed(2)} ms`)
      }
      this.logger.info(`  NOMAD Score: ${result.nomad_score.toFixed(2)}`)
      this.logger.info('')
      this.logger.info('Privacy Notice:')
      this.logger.info('  - Only the information shown above will be submitted')
      this.logger.info('  - No IP addresses, hostnames, or personal data is collected')
      this.logger.info('  - Submissions are completely anonymous')
      this.logger.info('')

      // Confirm submission
      if (!this.yes) {
        const confirm = await this.prompt.confirm(
          'Do you want to submit this benchmark to the community repository?'
        )
        if (!confirm) {
          this.logger.info('Submission cancelled.')
          return
        }
      }

      // Submit
      this.logger.info('Submitting benchmark...')
      const submitResult = await benchmarkService.submitToRepository(result.benchmark_id)

      this.logger.success('Benchmark submitted successfully!')
      this.logger.info('')
      this.logger.info(`Repository ID: ${submitResult.repository_id}`)
      this.logger.info(`Your percentile: ${submitResult.percentile}%`)
      this.logger.info('')
      this.logger.info('Thank you for contributing to the NOMAD community!')

    } catch (error) {
      this.logger.error(`Submission failed: ${error.message}`)
      this.exitCode = 1
    }
  }
}

import { BaseCommand, flags } from '@adonisjs/core/ace'
import type { CommandOptions } from '@adonisjs/core/types/ace'
import { isWithinWindow } from '../../app/utils/update_window.js'

/**
 * Exercise the content auto-update decision pipeline WITHOUT ever dispatching a
 * real download.
 *
 *   # Prove the core selection/eligibility/window logic deterministically
 *   # (no network/DB):
 *   node ace content-auto-update:dry-run --scenarios
 *
 *   # Evaluate what the next run would do against the currently-persisted
 *   # available-update state (run a "Check for Content Updates" first to refresh
 *   # it), forcing the feature on and overriding the cap:
 *   node ace content-auto-update:dry-run --force-enabled --cap=20 --window-start=00:00 --window-end=23:59
 */
export default class ContentAutoUpdateDryRun extends BaseCommand {
  static commandName = 'content-auto-update:dry-run'
  static description = 'Dry-run the content auto-update decision pipeline (never dispatches a download)'

  @flags.boolean({ description: 'Run the built-in deterministic scenario suite and exit' })
  declare scenarios: boolean

  @flags.boolean({ description: 'Ignore the persisted enabled setting and treat as enabled' })
  declare forceEnabled: boolean

  @flags.string({ description: 'Override cool-off hours' })
  declare cooloff: string

  @flags.string({ description: 'Override window start (HH:MM)' })
  declare windowStart: string

  @flags.string({ description: 'Override window end (HH:MM)' })
  declare windowEnd: string

  @flags.string({ description: 'Override per-window data cap in GB (0 = unlimited)' })
  declare cap: string

  @flags.string({ description: 'Override bytes already used this window' })
  declare usedBytes: string

  @flags.string({ description: 'Simulate the clock at this ISO timestamp' })
  declare now: string

  static options: CommandOptions = {
    startApp: true,
  }

  async run() {
    const { DateTime } = await import('luxon')
    const { DownloadService } = await import('#services/download_service')
    const { QueueService } = await import('#services/queue_service')
    const { ContentAutoUpdateService } = await import('#services/content_auto_update_service')

    const svc = new ContentAutoUpdateService(new DownloadService(QueueService.getInstance()))

    if (this.scenarios) {
      const ok = this.runScenarios(svc, DateTime)
      if (!ok) this.exitCode = 1
      return
    }

    const BYTES_PER_GB = 1024 * 1024 * 1024
    const overrides: Record<string, any> = {}
    if (this.forceEnabled) overrides.forceEnabled = true
    if (this.cooloff) overrides.cooloffHours = Number(this.cooloff)
    if (this.windowStart) overrides.windowStart = this.windowStart
    if (this.windowEnd) overrides.windowEnd = this.windowEnd
    if (this.cap) overrides.maxBytesPerWindow = Math.round(Number(this.cap) * BYTES_PER_GB)
    if (this.usedBytes) overrides.windowBytesUsed = Number(this.usedBytes)
    if (this.now) overrides.now = DateTime.fromISO(this.now)

    this.logger.info('Running content auto-update dry run (no download will be dispatched)...')
    const d = await svc.dryRun(overrides)

    this.logger.log('')
    this.logger.log(`  Enabled         : ${d.enabled}`)
    this.logger.log(
      `  Window          : ${d.config.windowStart}-${d.config.windowEnd} ` +
        `(currently ${d.withinWindow ? 'inside' : 'outside'})`
    )
    this.logger.log(`  Cool-off hours  : ${d.config.cooloffHours}`)
    this.logger.log(
      `  Data cap        : ${d.config.maxBytesPerWindow > 0 ? d.config.maxBytesPerWindow + ' bytes' : 'unlimited'}`
    )
    this.logger.log(`  Eligible        : ${d.eligibleCount}`)
    this.logger.log(`  Would start     : ${d.selection.selected.map((c) => c.resource.resource_id).join(', ') || '—'}`)
    this.logger.log(
      `  Skipped (cap)   : ${d.selection.skippedOversize.map((c) => c.resource.resource_id).join(', ') || '—'}`
    )
    this.logger.log(
      `  Deferred (budget): ${d.selection.deferred.map((c) => c.resource.resource_id).join(', ') || '—'}`
    )
    this.logger.log('')
  }

  /**
   * Deterministic acceptance suite over the pure decision helpers — no network
   * or dispatch. Mirrors the per-resource eligibility, cap selection, and window
   * branches reviewers care about.
   */
  private runScenarios(svc: any, DateTime: any): boolean {
    const now = DateTime.fromISO('2026-06-04T03:00:00Z')
    const daysAgo = (d: number) => now.minus({ days: d })
    const hoursAgo = (h: number) => now.minus({ hours: h })

    const res = (o: Record<string, any> = {}) => ({
      resource_id: 'res',
      version: '2024-01',
      available_update_version: null,
      available_update_size_bytes: null,
      available_update_first_seen_at: null,
      auto_update_disabled_reason: null,
      auto_update_consecutive_failures: 0,
      installed_at: daysAgo(100),
      ...o,
    })
    const cand = (id: string, size: number, installedAt: any = daysAgo(100)) => ({
      resource: res({ resource_id: id }),
      version: '2024-06',
      download_url: `(test)`,
      size_bytes: size,
      installed_at: installedAt,
    })

    let passed = 0
    let failed = 0
    const report = (ok: boolean, message: string) => {
      this.logger.log(`  ${ok ? this.colors.green('✓') : this.colors.red('✗')} ${message}`)
      ok ? passed++ : failed++
    }

    this.logger.log('')
    this.logger.log('Eligibility scenarios:')
    report(
      svc.resourceEligibility(res(), 72, now).eligible === false,
      'no available update → not eligible'
    )
    report(
      svc.resourceEligibility(
        res({ available_update_version: '2024-06', available_update_first_seen_at: hoursAgo(10) }),
        72,
        now
      ).eligible === false,
      'inside cool-off → not eligible'
    )
    report(
      svc.resourceEligibility(
        res({ available_update_version: '2024-06', available_update_first_seen_at: daysAgo(5) }),
        72,
        now
      ).eligible === true,
      'past cool-off → eligible'
    )
    report(
      svc.resourceEligibility(
        res({
          available_update_version: '2024-06',
          available_update_first_seen_at: daysAgo(30),
          auto_update_disabled_reason: 'disabled',
        }),
        72,
        now
      ).eligible === false,
      'self-disabled → not eligible'
    )

    this.logger.log('')
    this.logger.log('Cap selection scenarios:')
    {
      const s = svc.selectUnderCap([cand('a', 1000), cand('b', 2000)], 10000, 0)
      report(s.selected.length === 2, 'under cap selects all')
    }
    {
      const s = svc.selectUnderCap([cand('huge', 50000)], 20000, 0)
      report(
        s.selected.length === 0 && s.skippedOversize.length === 1,
        'oversize file → skipped, never selected'
      )
    }
    {
      const s = svc.selectUnderCap([cand('mid', 8000)], 10000, 5000)
      report(s.selected.length === 0 && s.deferred.length === 1, 'over remaining budget → deferred')
    }
    {
      const s = svc.selectUnderCap([cand('a', 0)], 10000, 0)
      report(s.selected.length === 0 && s.deferred.length === 1, 'unknown size → deferred')
    }
    {
      const s = svc.selectUnderCap([cand('big', 9_999_999_999)], 0, 0)
      report(s.selected.length === 1, 'cap 0 → unlimited')
    }

    this.logger.log('')
    this.logger.log('Window scenarios:')
    report(
      isWithinWindow('02:00', '05:00', DateTime.fromISO('2026-06-04T03:00:00')) === true,
      'normal 02:00-05:00 @ 03:00 → in'
    )
    report(
      isWithinWindow('22:00', '02:00', DateTime.fromISO('2026-06-04T01:00:00')) === true,
      'wrap 22:00-02:00 @ 01:00 → in'
    )
    report(
      isWithinWindow('22:00', '02:00', DateTime.fromISO('2026-06-04T12:00:00')) === false,
      'wrap 22:00-02:00 @ 12:00 → out'
    )

    this.logger.log('')
    if (failed === 0) {
      this.logger.success(`All ${passed} scenarios passed`)
    } else {
      this.logger.error(`${failed} scenario(s) failed, ${passed} passed`)
    }
    return failed === 0
  }
}

import { BaseCommand, args, flags } from '@adonisjs/core/ace'
import type { CommandOptions } from '@adonisjs/core/types/ace'

/**
 * Diff an eval report against a baseline and fail on regression.
 *
 * This is the "did my change help?" command, and the one CI would call.
 *
 *   node ace eval:compare tests/eval/baselines/<fp>/retrieval.json tests/eval/reports/latest.json
 *   node ace eval:compare base.json current.json --tolerance=0.05
 *   node ace eval:compare --promote=retrieval tests/eval/reports/latest.json
 */
export default class EvalCompare extends BaseCommand {
  static commandName = 'eval:compare'
  static description = 'Diff an eval report against a baseline; exits non-zero on regression'

  @args.string({ description: 'Baseline report JSON (or the report to promote, with --promote)' })
  declare baseline: string

  @args.string({ description: 'Current report JSON', required: false })
  declare current: string

  @flags.string({ description: 'Regression tolerance per metric (default: 0.02)' })
  declare tolerance: string

  @flags.string({
    description: 'Promote the given report to a committed baseline under this name, then exit',
  })
  declare promote: string

  @flags.boolean({ description: 'Print the full metric table, not just the regressions' })
  declare verbose: boolean

  /**
   * Deliberately does not boot the application.
   *
   * Comparing two report files is pure I/O — it needs no MySQL, no Redis, no
   * Qdrant, and no Ollama. Keeping it that way is what lets CI run the gate on
   * a committed baseline without standing up the whole stack, and it avoids the
   * app's noisy Redis teardown on exit.
   */
  static options: CommandOptions = {
    startApp: false,
  }

  async run() {
    const { EvalReportService } = await import('#services/eval_report_service')
    const { compareReports, DEFAULT_TOLERANCE } = await import('../../app/utils/eval/report.js')
    const service = new EvalReportService()

    try {
      if (this.promote) {
        const report = await service.read(this.baseline)
        const path = await service.promoteToBaseline(report, this.promote)
        this.logger.success(`Promoted to baseline: ${path}`)
        this.logger.info(`Corpus fingerprint: ${report.meta.corpusFingerprint}`)
        this.logger.info('Commit this file so the whole team gates against the same numbers.')
        return
      }

      if (!this.current) {
        this.logger.error('Two report paths are required (or use --promote=<name> with one).')
        this.exitCode = 1
        return
      }

      const [baseline, current] = await Promise.all([
        service.read(this.baseline),
        service.read(this.current),
      ])
      const tolerance = this.tolerance ? Number.parseFloat(this.tolerance) : DEFAULT_TOLERANCE
      const result = compareReports(baseline, current, tolerance)

      if (!result.comparable) {
        // Refusing is the correct outcome, not a failure of the tool — diffing
        // runs from different corpora would manufacture a regression.
        this.logger.error('Reports are not comparable:')
        this.logger.error(`  ${result.incomparableReason}`)
        this.exitCode = 1
        return
      }

      this.logger.info(
        `baseline ${short(baseline.meta.gitSha)} (${baseline.meta.createdAt}) -> current ${short(current.meta.gitSha)} (${current.meta.createdAt})`
      )
      this.logger.info(`corpus ${current.meta.corpusFingerprint} · tolerance ${tolerance}`)
      if (current.meta.gitDirty) {
        this.logger.warning('Current report was produced from a dirty working tree.')
      }
      this.logger.info('')

      const rows = this.verbose
        ? [...result.deltas].sort((a, b) => (a.improvement ?? 0) - (b.improvement ?? 0))
        : [...result.regressions, ...result.improvements]

      if (rows.length === 0) {
        this.logger.success('No metric moved outside the tolerance band.')
      } else {
        for (const d of rows) {
          const line = `  ${d.metric.padEnd(24)} ${fmt(d.baseline)} -> ${fmt(d.current)}  ${signed(d.delta)}`
          if (d.regressed) this.logger.error(`${line}   REGRESSED`)
          else if ((d.improvement ?? 0) > tolerance) this.logger.success(`${line}   improved`)
          else this.logger.info(line)
        }
      }

      this.logger.info('')
      if (result.regressions.length > 0) {
        this.logger.error(
          `${result.regressions.length} metric(s) regressed beyond the ${tolerance} tolerance.`
        )
        this.exitCode = 1
      } else {
        this.logger.success(
          `No regressions. ${result.improvements.length} metric(s) improved beyond tolerance.`
        )
      }
    } catch (error) {
      this.logger.error(error instanceof Error ? error.message : String(error))
      this.exitCode = 1
    }
  }
}

const fmt = (v: number | null) => (v === null ? '   n/a' : v.toFixed(4).padStart(6))
const signed = (v: number | null) => (v === null ? '     ' : `${v >= 0 ? '+' : ''}${v.toFixed(4)}`)
const short = (sha: string | null) => (sha ? sha.slice(0, 7) : 'unknown')

import { BaseCommand, flags } from '@adonisjs/core/ace'
import type { CommandOptions } from '@adonisjs/core/types/ace'

/**
 * Manage the frozen evaluation corpus.
 *
 *   # Validate the corpus and goldens without touching the vector store
 *   node ace eval:corpus --check
 *
 *   # Show what is currently ingested
 *   node ace eval:corpus --status
 *
 *   # Wipe and rebuild (the normal path; safe — never touches user content)
 *   node ace eval:corpus --ingest
 *
 *   # Remove the eval corpus entirely
 *   node ace eval:corpus --reset
 */
export default class EvalCorpus extends BaseCommand {
  static commandName = 'eval:corpus'
  static description = 'Manage the frozen RAG evaluation corpus (ingest, reset, status, check)'

  @flags.boolean({ description: 'Wipe and re-ingest the corpus into the reserved eval collection' })
  declare ingest: boolean

  @flags.boolean({ description: 'Remove every eval corpus chunk from the vector store' })
  declare reset: boolean

  @flags.boolean({ description: 'Show the fingerprint and current chunk count' })
  declare status: boolean

  @flags.boolean({
    description: 'Validate the corpus and goldens only — no Qdrant, no Ollama, no writes',
  })
  declare check: boolean

  @flags.boolean({ description: 'Leave application debug logging on (very noisy)' })
  declare debug: boolean

  static options: CommandOptions = {
    startApp: true,
  }

  async run() {
    const { EvalCorpusService } = await import('#services/eval_corpus_service')
    const { quietLogging } = await import('../../app/utils/eval/quiet.js')
    const service = await this.app.container.make(EvalCorpusService)
    const restoreLogging = quietLogging(this.debug)
    try {
      await this.dispatch(service)
    } finally {
      restoreLogging()
    }
  }

  private async dispatch(service: any) {

    // Default to --status so a bare invocation is always safe.
    if (!this.ingest && !this.reset && !this.check) this.status = true

    if (this.check) {
      return this.runCheck(service)
    }

    if (this.reset) {
      const removed = await service.reset()
      this.logger.success(`Removed ${removed} eval corpus chunks`)
      return
    }

    if (this.ingest) {
      return this.runIngest(service)
    }

    const [fingerprint, chunks, goldens] = await Promise.all([
      service.fingerprint(),
      service.count(),
      service.loadGoldens(['*']),
    ])
    this.logger.info(`Fingerprint:   ${fingerprint}`)
    this.logger.info(`Chunks in KB:  ${chunks}`)
    this.logger.info(`Goldens:       ${goldens.length}`)
    if (chunks === 0) {
      this.logger.warning('Corpus is not ingested. Run: node ace eval:corpus --ingest')
    }
  }

  /**
   * Validation-only path. Deliberately avoids the container-resolved services'
   * network dependencies so a contributor can check their golden edits without
   * a running stack.
   */
  private async runCheck(service: any) {
    try {
      const corpus = await service.loadCorpus()
      const goldens = await service.loadGoldens(['*'])
      const fingerprint = await service.fingerprint()

      const tagCounts = new Map<string, number>()
      for (const g of goldens) {
        for (const tag of g.tags) tagCounts.set(tag, (tagCounts.get(tag) ?? 0) + 1)
      }

      // A document no golden asks about is dead weight in the corpus: it costs
      // ingest time and adds distractor noise nobody chose deliberately.
      const referenced = new Set<string>(goldens.flatMap((g: any) => g.relevantDocIds))
      const unreferenced = corpus
        .map((d: any) => d.docId)
        .filter((id: string) => !referenced.has(id))

      this.logger.success(`Corpus OK: ${corpus.length} documents, ${goldens.length} goldens`)
      this.logger.info(`Fingerprint: ${fingerprint}`)
      this.logger.info(
        `Tags: ${[...tagCounts.entries()]
          .sort((a, b) => b[1] - a[1])
          .map(([t, n]) => `${t}=${n}`)
          .join(' ')}`
      )
      const refusals = goldens.filter((g: any) => g.expectRefusal).length
      this.logger.info(`Refusal cases: ${refusals} / ${goldens.length}`)
      if (unreferenced.length > 0) {
        this.logger.warning(`Documents no golden references: ${unreferenced.join(', ')}`)
      }
    } catch (error) {
      this.logger.error(error instanceof Error ? error.message : String(error))
      this.exitCode = 1
    }
  }

  private async runIngest(service: any) {
    this.logger.info('Rebuilding the eval corpus (user content is never touched)...')
    // Validate before destroying anything — a typo in a golden should not cost
    // you the ingest you were about to run.
    await service.loadGoldens(['*'])

    const summary = await service.ingest((docId: string, index: number, total: number) => {
      this.logger.info(`  [${index}/${total}] ${docId}`)
    })

    this.logger.info('')
    if (summary.removedBeforeIngest > 0) {
      this.logger.info(`Removed ${summary.removedBeforeIngest} chunks from the previous ingest`)
    }
    this.logger.success(`Ingested ${summary.documents} documents into ${summary.chunks} chunks`)
    this.logger.info(`Fingerprint: ${summary.fingerprint}`)

    if (summary.failures.length > 0) {
      this.logger.error(`${summary.failures.length} document(s) failed to ingest:`)
      for (const f of summary.failures) this.logger.error(`  ${f.docId}: ${f.reason}`)
      // A partial corpus produces scores that look real and are not.
      this.logger.error('The corpus is incomplete — results from this state are not comparable.')
      this.exitCode = 1
    }
  }
}

import { BaseCommand, flags } from '@adonisjs/core/ace'
import type { CommandOptions } from '@adonisjs/core/types/ace'
import type {
  GenerationAggregate,
  GenerationMode,
} from '../../app/services/eval_generation_service.js'
import type { ResponseStyle } from '../../types/ollama.js'

const MODES: GenerationMode[] = ['oracle', 'e2e', 'noretrieval']
const STYLES: ResponseStyle[] = ['auto', 'focused', 'creative', 'off']

/**
 * Score generated answers against the golden set.
 *
 * The `--mode` flag is the whole point of this command:
 *
 *   oracle       perfect context injected by construction -> isolates the MODEL
 *   e2e          real retrieval                           -> the real product
 *   noretrieval  no context at all                        -> parametric baseline
 *
 * Run all three on the same model and the ambiguous complaint "the AI gave a
 * bad answer" decomposes into a number that can be acted on.
 *
 *   node ace eval:generation --model=llama3.2:latest --mode=oracle
 *   node ace eval:generation --model=llama3:8b --all-modes
 *   node ace eval:generation --model=mock          # no Ollama needed
 */
export default class EvalGeneration extends BaseCommand {
  static commandName = 'eval:generation'
  static description = 'Score generated answers, with oracle/e2e/noretrieval ablation'

  @flags.string({ description: 'Ollama model to evaluate, or "mock" for the extractive ceiling' })
  declare model: string

  @flags.string({ description: `One of: ${MODES.join(', ')} (default: e2e)` })
  declare mode: string

  @flags.boolean({ description: 'Run all three modes and print the decomposition' })
  declare allModes: boolean

  @flags.string({ description: 'Repeats per question, for stability (default: 3)' })
  declare repeats: string

  @flags.string({
    description:
      'Comma-separated golden suites to run, by filename without .jsonl (default: core). ' +
      'Extra suites are opt-in so they cannot move the numbers a baseline was recorded against.',
  })
  declare suite: string

  @flags.string({
    description:
      `Sample the way real chat does, under one of: ${STYLES.join(', ')}. ` +
      'Omit for the deterministic temperature-0 default. Greedy decoding makes ' +
      'min_p, top_p and top_k inert, so a Response Style is only visible with ' +
      'this flag set, and "off" (no samplers, no temperature) is the control to ' +
      'compare a style against.',
  })
  declare style: string

  @flags.string({ description: 'Only run goldens carrying this tag' })
  declare tag: string

  @flags.string({ description: 'Limit to the first N goldens (for a quick smoke run)' })
  declare limit: string

  @flags.boolean({ description: 'Print every failing question with the answer the model gave' })
  declare verbose: boolean

  @flags.boolean({ description: 'Leave application debug logging on (very noisy)' })
  declare debug: boolean

  static options: CommandOptions = {
    startApp: true,
  }

  async run() {
    const { EvalCorpusService } = await import('#services/eval_corpus_service')
    const { EvalGenerationService, MOCK_MODEL } = await import('#services/eval_generation_service')
    const { quietLogging } = await import('../../app/utils/eval/quiet.js')

    const corpusService = await this.app.container.make(EvalCorpusService)
    const generationService = await this.app.container.make(EvalGenerationService)
    const restoreLogging = quietLogging(this.debug)

    try {
      if (!this.model) {
        this.logger.error('--model is required (use --model=mock to run without Ollama)')
        this.exitCode = 1
        return
      }

      const modes: GenerationMode[] = this.allModes
        ? MODES
        : [(this.mode as GenerationMode) || 'e2e']
      for (const mode of modes) {
        if (!MODES.includes(mode)) {
          this.logger.error(`Unknown mode "${mode}". Expected one of: ${MODES.join(', ')}`)
          this.exitCode = 1
          return
        }
      }

      if (this.style && !STYLES.includes(this.style as ResponseStyle)) {
        this.logger.error(`Unknown style "${this.style}". Expected one of: ${STYLES.join(', ')}`)
        this.exitCode = 1
        return
      }
      const samplerStyle = this.style ? (this.style as ResponseStyle) : undefined

      let goldens = await corpusService.loadGoldens(this.suite ? this.suite.split(',').map((s) => s.trim()) : undefined)
      if (this.tag) goldens = goldens.filter((g) => g.tags.includes(this.tag))
      if (this.limit) goldens = goldens.slice(0, Number.parseInt(this.limit, 10))
      if (goldens.length === 0) {
        this.logger.error('No goldens matched the given filters')
        this.exitCode = 1
        return
      }

      // e2e and oracle both need the corpus present; noretrieval does not, but
      // requiring it uniformly keeps the three modes comparable.
      const chunks = await corpusService.count()
      if (chunks === 0 && modes.some((m) => m !== 'noretrieval')) {
        this.logger.error('The eval corpus is not ingested. Run: node ace eval:corpus --ingest')
        this.exitCode = 1
        return
      }

      const fingerprint = await corpusService.fingerprint()
      const repeats = this.repeats ? Number.parseInt(this.repeats, 10) : 3
      this.logger.info(
        `Corpus ${fingerprint} · ${goldens.length} goldens · model=${this.model} · repeats=${repeats}` +
          (samplerStyle ? ` · style=${samplerStyle}` : ' · style=deterministic (temp 0)')
      )
      if (samplerStyle) {
        this.logger.info(
          'Sampling is on: the seed is fixed but the run is only approximately reproducible. Watch the unstable count.'
        )
      }
      if (this.model === MOCK_MODEL) {
        this.logger.info(
          'Mock model: answers are the injected context verbatim — this is the extractive ceiling for the current retrieval, not a real model.'
        )
      }
      this.logger.info('')

      const summaries: Array<{ mode: GenerationMode; agg: GenerationAggregate }> = []

      for (const mode of modes) {
        const result = await generationService.run(goldens, {
          mode,
          model: this.model,
          repeats,
          samplerStyle,
          onProgress: (id, index, total) => {
            if (this.verbose) this.logger.info(`  [${index}/${total}] ${mode}: ${id}`)
          },
        })
        summaries.push({ mode, agg: result.overall })

        this.printAggregate(mode, result.overall, result.elapsedMs)

        if (result.overall.errors > 0) {
          this.logger.error(
            `${result.overall.errors} question(s) errored talking to the model — the scores above are incomplete.`
          )
          const firstError = result.cases.find((c) => c.error)
          if (firstError) this.logger.error(`  first error (${firstError.id}): ${firstError.error}`)
          this.exitCode = 1
        }

        if (this.verbose) this.printFailures(result.cases)
      }

      if (summaries.length > 1) this.printDecomposition(summaries)
    } catch (error) {
      this.logger.error(error instanceof Error ? error.message : String(error))
      this.exitCode = 1
    } finally {
      restoreLogging()
    }
  }

  private printAggregate(mode: GenerationMode, agg: GenerationAggregate, elapsedMs: number) {
    this.logger.info(`=== ${mode.toUpperCase()} (${(elapsedMs / 1000).toFixed(1)}s) ===`)
    this.logger.info(`  correctness        ${fmt(agg.correctness)}`)
    this.logger.info(`  refusal correct    ${fmt(agg.refusalCorrectness)}`)
    this.logger.info(`  leakage rate       ${fmt(agg.leakageRate)}  (lower is better)`)
    this.logger.info(`  think-tag leak     ${fmt(agg.thinkTagLeakRate)}  (should be 0)`)
    this.logger.info(`  markdown formatted ${fmt(agg.markdownRate)}`)
    this.logger.info(
      `  numeric grounding  ${agg.groundedness ? `${agg.groundedness.mean.toFixed(3)} (n=${agg.groundedness.n})` : '  n/a'}`
    )
    this.logger.info(
      `  mean answer length ${agg.meanAnswerLength === null ? 'n/a' : Math.round(agg.meanAnswerLength)} chars`
    )
    // Context budgeting. These explain *why* a correctness number moved: an
    // answer the model never had the material for is a different failure from
    // an answer it got wrong, and only these two lines tell them apart.
    if (agg.meanPromptTokens !== null) {
      this.logger.info(`  mean prompt tokens ${Math.round(agg.meanPromptTokens)}`)
    }
    if (agg.historyElidedRate !== null) {
      this.logger.info(
        `  history elided     ${fmt(agg.historyElidedRate)}  (share of cases needing a trim)`
      )
    }
    if (agg.chunksDroppedRate !== null) {
      this.logger.info(
        `  context dropped    ${fmt(agg.chunksDroppedRate)}  (share of cases where a chunk didn't fit)`
      )
    }
    if (agg.promptTokenError) {
      // Every budget decision rests on the estimate; if this drifts, the trims
      // above are being made against a number that is no longer true.
      this.logger.info(
        `  token estimate err ${(agg.promptTokenError.mean * 100).toFixed(1)}%  (vs the backend's real count)`
      )
    }
    if (agg.unstable > 0) {
      this.logger.warning(
        `  ${agg.unstable} question(s) flipped between repeats — excluded from gating, do not read them as a regression.`
      )
    }
    this.logger.info('')
  }

  /**
   * The reason this command exists: turn three scores into an attribution.
   */
  private printDecomposition(summaries: Array<{ mode: GenerationMode; agg: GenerationAggregate }>) {
    const get = (mode: GenerationMode) => summaries.find((s) => s.mode === mode)?.agg.correctness ?? null
    const oracle = get('oracle')
    const e2e = get('e2e')
    const none = get('noretrieval')

    this.logger.info('=== Decomposition ===')
    if (oracle !== null && e2e !== null) {
      const cost = oracle - e2e
      this.logger.info(`  retrieval cost   ${cost.toFixed(3)}   (oracle ${oracle.toFixed(3)} - e2e ${e2e.toFixed(3)})`)
      this.logger.info(`  model ceiling    ${oracle.toFixed(3)}   (what this model manages with perfect context)`)
    }
    if (e2e !== null && none !== null) {
      this.logger.info(`  RAG contribution ${(e2e - none).toFixed(3)}   (e2e ${e2e.toFixed(3)} - noretrieval ${none.toFixed(3)})`)
    }

    if (oracle !== null && e2e !== null) {
      // The actual triage rule, stated so nobody has to re-derive it.
      const cost = oracle - e2e
      if (oracle < 0.6) {
        this.logger.warning(
          '  Oracle is low: this model struggles even with perfect context. Retrieval work will not fix it — try a larger model.'
        )
      } else if (cost > 0.15) {
        this.logger.warning(
          '  Large retrieval cost: the model can use good context but is not being given it. Work on retrieval.'
        )
      } else {
        this.logger.success('  Model and retrieval are both holding up on this corpus.')
      }
    }
    if (none !== null && e2e !== null && e2e <= none) {
      this.logger.warning(
        '  RAG is not adding anything over the bare model on this set — check that retrieval is actually reaching the prompt.'
      )
    }
  }

  private printFailures(cases: Array<any>) {
    const failures = cases.filter((c) => c.correctness.passRate < 1 || c.refusalCorrectness.passRate < 1)
    if (failures.length === 0) return
    this.logger.info('--- failures ---')
    for (const f of failures) {
      this.logger.info(`  ${f.id}  correct=${f.correctness.passes}/${f.correctness.repeats} refusal=${f.refusalCorrectness.passes}/${f.refusalCorrectness.repeats}`)
      const score = f.scores[0]
      if (score?.missedRequired?.length) {
        this.logger.info(`    missed: ${score.missedRequired.join(' | ')}`)
      }
      if (score?.hitForbidden?.length) {
        this.logger.info(`    said forbidden: ${score.hitForbidden.join(' | ')}`)
      }
      if (score?.leakage?.length) {
        this.logger.info(`    narrated retrieval`)
      }
      if (f.answers[0]) {
        const preview = f.answers[0].replace(/\s+/g, ' ').slice(0, 220)
        this.logger.info(`    said: ${preview}${f.answers[0].length > 220 ? '…' : ''}`)
      }
    }
    this.logger.info('')
  }
}

const fmt = (v: number | null) => (v === null ? '  n/a' : v.toFixed(3))

import { BaseCommand, flags } from '@adonisjs/core/ace'
import type { CommandOptions } from '@adonisjs/core/types/ace'
import type { GenerationAggregate } from '../../app/services/eval_generation_service.js'

type Row = {
  model: string
  oracle: GenerationAggregate | null
  e2e: GenerationAggregate | null
  error?: string
}

/**
 * Build the model capability table.
 *
 * This is the artifact that answers a GitHub issue. When a user reports "the
 * AI gave me a bad answer", look up their model in this table:
 *
 *   - scoring at or near its row  -> the model is at its ceiling. The honest
 *                                    answer is "run a larger model", not a bug.
 *   - scoring well below its row  -> something is wrong with their config or
 *                                    our code, and it is worth investigating.
 *
 * Without it, every quality concern is unfalsifiable.
 *
 *   node ace eval:matrix --models=llama3.2:latest,llama3:8b --limit=30
 *   node ace eval:matrix --models=... --promote   # commit as the reference table
 */
export default class EvalMatrix extends BaseCommand {
  static commandName = 'eval:matrix'
  static description = 'Score several models side by side to build the capability reference table'

  @flags.string({ description: 'Comma-separated Ollama model names' })
  declare models: string

  @flags.string({ description: 'Repeats per question (default: 1 — the matrix is already long)' })
  declare repeats: string

  @flags.string({ description: 'Limit to the first N goldens' })
  declare limit: string

  @flags.string({ description: 'Only run goldens carrying this tag' })
  declare tag: string

  @flags.boolean({ description: 'Write the table to tests/eval/baselines/<fingerprint>/matrix.json' })
  declare promote: boolean

  @flags.boolean({ description: 'Leave application debug logging on (very noisy)' })
  declare debug: boolean

  static options: CommandOptions = {
    startApp: true,
  }

  async run() {
    const { EvalCorpusService } = await import('#services/eval_corpus_service')
    const { EvalGenerationService } = await import('#services/eval_generation_service')
    const { quietLogging } = await import('../../app/utils/eval/quiet.js')
    const { mkdir, writeFile } = await import('node:fs/promises')
    const { dirname, join, resolve } = await import('node:path')

    const corpusService = await this.app.container.make(EvalCorpusService)
    const generationService = await this.app.container.make(EvalGenerationService)
    const restoreLogging = quietLogging(this.debug)

    try {
      if (!this.models) {
        this.logger.error('--models is required, e.g. --models=llama3.2:latest,llama3:8b')
        this.exitCode = 1
        return
      }
      const models = this.models.split(',').map((m) => m.trim()).filter(Boolean)

      let goldens = await corpusService.loadGoldens()
      if (this.tag) goldens = goldens.filter((g) => g.tags.includes(this.tag))
      if (this.limit) goldens = goldens.slice(0, Number.parseInt(this.limit, 10))

      const fingerprint = await corpusService.fingerprint()
      const repeats = this.repeats ? Number.parseInt(this.repeats, 10) : 1
      this.logger.info(
        `Corpus ${fingerprint} · ${goldens.length} goldens · ${models.length} models · repeats=${repeats}`
      )
      this.logger.info('Running oracle and e2e for each model. This takes a while.')
      this.logger.info('')

      const rows: Row[] = []
      for (const model of models) {
        this.logger.info(`--- ${model} ---`)
        const row: Row = { model, oracle: null, e2e: null }
        try {
          // Only oracle and e2e: those two are what the triage rule needs, and
          // adding noretrieval would half again the runtime of an already long
          // command for a number that does not change the verdict.
          for (const mode of ['oracle', 'e2e'] as const) {
            const started = Date.now()
            const result = await generationService.run(goldens, { mode, model, repeats })
            row[mode] = result.overall
            this.logger.info(
              `  ${mode.padEnd(6)} correctness=${fmt(result.overall.correctness)} refusal=${fmt(result.overall.refusalCorrectness)} (${((Date.now() - started) / 1000).toFixed(0)}s)`
            )
            if (result.overall.errors > 0) {
              this.logger.warning(`  ${result.overall.errors} question(s) errored in ${mode}`)
            }
          }
        } catch (error) {
          row.error = error instanceof Error ? error.message : String(error)
          this.logger.error(`  failed: ${row.error}`)
        }
        rows.push(row)
      }

      this.logger.info('')
      this.printTable(rows)

      if (this.promote) {
        const path = resolve(join(process.cwd(), 'tests/eval/baselines', fingerprint, 'matrix.json'))
        await mkdir(dirname(path), { recursive: true })
        await writeFile(
          path,
          JSON.stringify(
            {
              corpusFingerprint: fingerprint,
              createdAt: new Date().toISOString(),
              goldens: goldens.length,
              repeats,
              tag: this.tag ?? null,
              rows,
            },
            null,
            2
          )
        )
        this.logger.success(`Capability table written: ${path}`)
        this.logger.info('Commit it — this is the reference a support triage compares against.')
      }
    } catch (error) {
      this.logger.error(error instanceof Error ? error.message : String(error))
      this.exitCode = 1
    } finally {
      restoreLogging()
    }
  }

  private printTable(rows: Row[]) {
    this.logger.info('=== Capability matrix ===')
    this.logger.info('')
    const width = Math.max(20, ...rows.map((r) => r.model.length + 2))
    this.logger.info(
      `${'model'.padEnd(width)}${'oracle'.padStart(8)}${'e2e'.padStart(8)}${'ret.cost'.padStart(10)}${'refusal'.padStart(9)}${'leakage'.padStart(9)}${'ground'.padStart(8)}`
    )
    for (const row of rows) {
      if (row.error) {
        this.logger.info(`${row.model.padEnd(width)}  ERROR: ${row.error}`)
        continue
      }
      const cost =
        row.oracle?.correctness !== null && row.oracle?.correctness !== undefined &&
        row.e2e?.correctness !== null && row.e2e?.correctness !== undefined
          ? row.oracle.correctness - row.e2e.correctness
          : null
      this.logger.info(
        row.model.padEnd(width) +
          fmt(row.oracle?.correctness ?? null).padStart(8) +
          fmt(row.e2e?.correctness ?? null).padStart(8) +
          (cost === null ? '   n/a' : `${cost >= 0 ? '+' : ''}${cost.toFixed(3)}`).padStart(10) +
          fmt(row.e2e?.refusalCorrectness ?? null).padStart(9) +
          fmt(row.e2e?.leakageRate ?? null).padStart(9) +
          fmt(row.e2e?.groundedness?.mean ?? null).padStart(8)
      )
    }
    this.logger.info('')
    this.logger.info('oracle   = correctness with perfect context (the model\'s ceiling)')
    this.logger.info('e2e      = correctness with real retrieval (what a user gets)')
    this.logger.info('ret.cost = oracle - e2e (what imperfect retrieval costs this model)')
    this.logger.info('leakage  = rate of narrating retrieval; lower is better')
  }
}

const fmt = (v: number | null) => (v === null ? ' n/a' : v.toFixed(3))

import { BaseCommand, flags } from '@adonisjs/core/ace'
import type { CommandOptions } from '@adonisjs/core/types/ace'
import type { RetrievalAggregate } from '../../app/utils/eval/retrieval_metrics.js'

/**
 * Score NOMAD's retrieval against the frozen golden set.
 *
 * No chat model is involved, so this is deterministic and hardware-independent:
 * a movement in these numbers is a code change, not a slow machine or an unlucky
 * sample. It is the fast inner loop for anything touching chunking, embedding,
 * thresholds, or reranking.
 *
 *   node ace eval:retrieval
 *   node ace eval:retrieval --ablate                 # is the reranker helping?
 *   node ace eval:retrieval --threshold=0.5          # sweep the Qdrant cutoff
 *   node ace eval:retrieval --min-final-score=0.6    # sweep the post-rerank floor
 *   node ace eval:retrieval --tag=multi-hop          # one slice only
 */
export default class EvalRetrieval extends BaseCommand {
  static commandName = 'eval:retrieval'
  static description = 'Score RAG retrieval against the golden set (deterministic, no chat model)'

  @flags.string({ description: 'Chunks to retrieve per query (default: the production value)' })
  declare topK: string

  @flags.string({ description: 'Minimum similarity score (default: the production value)' })
  declare threshold: string

  @flags.string({
    description:
      'Post-rerank relevance floor; chunks below it are dropped (default: the production value). ' +
      'Reads RAG_MIN_FINAL_SCORE, never the rag.minRelevance setting — see EvalRetrievalService.',
  })
  declare minFinalScore: string

  @flags.string({
    description:
      'Run the retrieval relevance check on this model after the floor (default: off, keeping this tier model-free)',
  })
  declare judgeModel: string

  @flags.boolean({ description: 'Also score the raw dense, reranked, and diversified orderings' })
  declare ablate: boolean

  @flags.string({
    description:
      'Comma-separated golden suites to run, by filename without .jsonl (default: core). ' +
      'Extra suites are opt-in so they cannot move the numbers a baseline was recorded against.',
  })
  declare suite: string

  @flags.string({ description: 'Only run goldens carrying this tag' })
  declare tag: string

  @flags.boolean({ description: 'Print each failing question and what it retrieved' })
  declare verbose: boolean

  @flags.boolean({ description: 'Leave application debug logging on (very noisy)' })
  declare debug: boolean

  @flags.boolean({ description: 'Write a JSON + Markdown report to tests/eval/reports/' })
  declare report: boolean

  @flags.string({
    description:
      "Write every golden's full pre-floor candidate pool (boosted + cosine scores) to this JSON path, " +
      'for simulating a relevance gate offline',
  })
  declare dump: string

  static options: CommandOptions = {
    startApp: true,
  }

  async run() {
    const { EvalCorpusService } = await import('#services/eval_corpus_service')
    const { EvalRetrievalService } = await import('#services/eval_retrieval_service')
    const { EvalReportService } = await import('#services/eval_report_service')
    const { quietLogging } = await import('../../app/utils/eval/quiet.js')

    const corpusService = await this.app.container.make(EvalCorpusService)
    const retrievalService = await this.app.container.make(EvalRetrievalService)
    const reportService = await this.app.container.make(EvalReportService)
    const restoreLogging = quietLogging(this.debug)

    try {
      const chunks = await retrievalService.assertCorpusReady()
      const fingerprint = await corpusService.fingerprint()
      let goldens = await corpusService.loadGoldens(this.suite ? this.suite.split(',').map((s) => s.trim()) : undefined)

      if (this.tag) {
        goldens = goldens.filter((g) => g.tags.includes(this.tag))
        if (goldens.length === 0) {
          this.logger.error(`No goldens carry the tag "${this.tag}"`)
          this.exitCode = 1
          return
        }
      }

      this.logger.info(`Corpus ${fingerprint} · ${chunks} chunks · ${goldens.length} goldens`)
      this.logger.info('')

      const started = Date.now()
      const result = await retrievalService.run(goldens, {
        topK: this.topK ? Number.parseInt(this.topK, 10) : undefined,
        scoreThreshold: this.threshold ? Number.parseFloat(this.threshold) : undefined,
        minFinalScore: this.minFinalScore ? Number.parseFloat(this.minFinalScore) : undefined,
        ablate: this.ablate,
        dump: Boolean(this.dump),
        judgeModel: this.judgeModel || undefined,
      })
      const elapsed = ((Date.now() - started) / 1000).toFixed(1)

      this.logger.info(
        `Params: topK=${result.params.topK} threshold=${result.params.scoreThreshold} ` +
          `minFinalScore=${result.params.minFinalScore}  (${elapsed}s)`
      )
      if (result.judge) {
        const j = result.judge
        this.logger.info(
          `Relevance check: ${j.model} · ${j.calls} calls · rejected ${j.rejected} chunk(s) · ` +
            `${j.failures} failed open · mean ${Math.round(j.meanMs)}ms max ${Math.round(j.maxMs)}ms`
        )
      }
      this.logger.info('')
      this.printAggregate('OVERALL', result.overall, result.params.kValues)

      if (result.unresolvedChunks > 0) {
        // Every retrieved chunk should belong to the eval corpus. Anything else
        // means the collection filter leaked and the numbers above describe a
        // corpus nobody chose.
        this.logger.error(
          `${result.unresolvedChunks} retrieved chunk(s) did not belong to the eval corpus — the collection filter leaked.`
        )
        this.exitCode = 1
      }

      this.printThresholdGuidance(result.overall)

      if (result.ablation) {
        this.logger.info('')
        this.logger.info('=== Stage ablation (does each heuristic earn its place?) ===')
        const k = result.params.kValues.includes(5) ? 5 : result.params.kValues[0]
        const row = (name: string, agg: RetrievalAggregate) =>
          this.logger.info(
            `  ${name.padEnd(14)} recall@${k}=${fmt(agg.recall[k])}  ndcg@${k}=${fmt(agg.ndcg[k])}  mrr=${fmt(agg.mrr)}  prec@${k}=${fmt(agg.precision[k])}`
          )
        row('dense only', result.ablation.dense)
        row('+ rerank', result.ablation.reranked)
        row('+ diversity', result.ablation.diversified)
        this.explainAblation(result.ablation, k)
      }

      this.logger.info('')
      this.logger.info('=== By tag ===')
      for (const [tag, agg] of Object.entries(result.byTag).sort()) {
        const k = result.params.kValues.includes(5) ? 5 : result.params.kValues[0]
        // A refusal-only tag has no recall to report; what it has is the leak rate,
        // which is the number #1341 is about.
        const leak =
          agg.nonEmptyRateOnRefusal === null ? '' : `  leaked=${pct(agg.nonEmptyRateOnRefusal)}`
        this.logger.info(
          `  ${tag.padEnd(20)} n=${String(agg.cases).padStart(3)}  recall@${k}=${fmt(agg.recall[k])}  ndcg@${k}=${fmt(agg.ndcg[k])}${leak}`
        )
      }

      const k = result.params.kValues.includes(5) ? 5 : result.params.kValues[0]
      const misses = result.cases.filter((c) => !c.expectRefusal && (c.recall[k] ?? 1) < 1)
      this.logger.info('')
      this.logger.info(`${misses.length} of ${result.overall.answerable} answerable questions missed at k=${k}`)

      if (this.verbose && misses.length > 0) {
        this.logger.info('')
        this.logger.info('=== Misses ===')
        for (const miss of misses) {
          this.logger.info(`  ${miss.id}`)
          this.logger.info(`    wanted:   ${miss.relevantDocIds.join(', ') || '(none)'}`)
          this.logger.info(`    retrieved: ${miss.retrievedDocIds.join(', ') || '(nothing)'}`)
        }
      } else if (misses.length > 0) {
        this.logger.info('Re-run with --verbose to see which questions and what they retrieved.')
      }

      // The other failure: a question the corpus cannot answer that retrieved
      // something anyway. Each of these becomes a citation the user sees.
      const leaks = result.cases.filter((c) => c.expectRefusal && !c.empty)
      if (leaks.length > 0) {
        this.logger.info('')
        this.logger.info(`${leaks.length} out-of-corpus question(s) retrieved something anyway`)
        if (this.verbose) {
          this.logger.info('')
          this.logger.info('=== Leaks ===')
          for (const leak of leaks) {
            this.logger.info(`  ${leak.id}`)
            const top = leak.top
              ? `  (top final=${leak.top.score.toFixed(3)} semantic=${leak.top.semanticScore?.toFixed(3) ?? 'n/a'})`
              : ''
            this.logger.info(`    retrieved: ${leak.retrievedDocIds.join(', ')}${top}`)
          }
        }
      }

      if (this.dump && result.pools) {
        const { writeFile } = await import('node:fs/promises')
        await writeFile(this.dump, JSON.stringify({ fingerprint, params: result.params, pools: result.pools }, null, 2))
        this.logger.info('')
        this.logger.success(`Candidate pools written: ${this.dump}`)
      }

      if (this.report) {
        const meta = await reportService.buildMeta('retrieval', fingerprint, {
          ...result.params,
          tag: this.tag ?? null,
        })
        const doc = reportService.fromRetrieval(meta, result)
        const slug = `retrieval-${meta.createdAt.replace(/[:.]/g, '-')}`
        const path = await reportService.write(doc, slug, renderRetrievalMarkdown(doc, result, misses))
        this.logger.info('')
        this.logger.success(`Report written: ${path}`)
      }
    } catch (error) {
      this.logger.error(error instanceof Error ? error.message : String(error))
      this.exitCode = 1
    } finally {
      restoreLogging()
    }
  }

  private printAggregate(label: string, agg: RetrievalAggregate, kValues: number[]) {
    this.logger.info(`=== ${label} (${agg.answerable} answerable of ${agg.cases}) ===`)
    const row = (name: string, values: Record<number, number | null>) =>
      this.logger.info(
        `  ${name.padEnd(10)} ${kValues.map((k) => `@${k}=${fmt(values[k])}`).join('  ')}`
      )
    row('recall', agg.recall)
    row('hit rate', agg.hitRate)
    row('precision', agg.precision)
    row('ndcg', agg.ndcg)
    this.logger.info(`  mrr        ${fmt(agg.mrr)}`)
  }

  /**
   * Turn the score distributions into an actual recommendation. The raw
   * percentiles are the evidence; this is the reading of them, which is what
   * the threshold constants have never had.
   *
   * Printed per axis, because the two cutoffs filter different numbers:
   * `--threshold` is applied by Qdrant to the raw cosine score, and
   * `--min-final-score` is applied after reranking. Reading one off the other's
   * percentiles is wrong by the reranker's boost factor.
   */
  private printThresholdGuidance(agg: RetrievalAggregate) {
    this.logger.info('')
    this.logger.info('=== Score separation (how to calibrate the cutoffs) ===')
    this.printAxis(
      'semantic, pre-rerank  — calibrates --threshold',
      agg.relevantScores,
      agg.irrelevantScores
    )
    this.printAxis(
      'final, post-rerank    — calibrates --min-final-score',
      agg.relevantFinalScores,
      agg.irrelevantFinalScores
    )
    if (agg.emptyRateOnAnswerable !== null && agg.emptyRateOnAnswerable > 0) {
      this.logger.warning(
        `  ${pct(agg.emptyRateOnAnswerable)} of answerable questions retrieved nothing — threshold may be too high.`
      )
    }
    if (agg.nonEmptyRateOnRefusal !== null && agg.nonEmptyRateOnRefusal > 0) {
      this.logger.warning(
        `  ${pct(agg.nonEmptyRateOnRefusal)} of out-of-corpus questions retrieved something anyway — that context is what produces confident wrong answers.`
      )
    }
  }

  /** One axis of the separation table, plus the reading of it. */
  private printAxis(
    label: string,
    rel: RetrievalAggregate['relevantScores'],
    irr: RetrievalAggregate['irrelevantScores']
  ) {
    if (!rel && !irr) return
    this.logger.info(`  ${label}`)
    const row = (name: string, d: NonNullable<typeof rel>) =>
      this.logger.info(
        `    ${name.padEnd(18)} n=${d.count} min=${d.min.toFixed(3)} p10=${d.p10.toFixed(3)} median=${d.median.toFixed(3)} p90=${d.p90.toFixed(3)}`
      )
    if (rel) row('relevant chunks', rel)
    if (irr) row('irrelevant chunks', irr)
    if (rel && irr) {
      if (rel.p10 > irr.p90) {
        this.logger.success(
          `    Clean separation: a cutoff between ${irr.p90.toFixed(3)} and ${rel.p10.toFixed(3)} splits them.`
        )
      } else {
        this.logger.warning(
          `    Overlapping: relevant p10 (${rel.p10.toFixed(3)}) sits below irrelevant p90 (${irr.p90.toFixed(3)}); ` +
            `a cutoff near ${rel.min.toFixed(3)} keeps every relevant chunk seen here.`
        )
      }
    }
  }

  private explainAblation(ablation: { dense: RetrievalAggregate; reranked: RetrievalAggregate; diversified: RetrievalAggregate }, k: number) {
    const verdict = (name: string, before: number | null, after: number | null) => {
      if (before === null || after === null) return
      const delta = after - before
      if (Math.abs(delta) < 1e-6) {
        this.logger.warning(`  ${name} changed nothing at k=${k} — it is complexity with no measured benefit.`)
      } else if (delta < 0) {
        this.logger.warning(`  ${name} made ndcg@${k} worse by ${Math.abs(delta).toFixed(4)}.`)
      } else {
        this.logger.success(`  ${name} improved ndcg@${k} by ${delta.toFixed(4)}.`)
      }
    }
    verdict('Reranking', ablation.dense.ndcg[k], ablation.reranked.ndcg[k])
    verdict('Source diversity', ablation.reranked.ndcg[k], ablation.diversified.ndcg[k])
  }
}

const fmt = (v: number | null) => (v === null ? '  n/a' : v.toFixed(3))
const pct = (v: number) => `${(v * 100).toFixed(0)}%`

/**
 * The human-readable half of a report. Leads with the misses, because when a
 * number moves the next question is always "which questions?" and a table of
 * aggregates cannot answer it.
 */
function renderRetrievalMarkdown(doc: any, result: any, misses: any[]): string {
  const lines: string[] = ['# Retrieval eval', '']
  lines.push(`- corpus: \`${doc.meta.corpusFingerprint}\``)
  lines.push(`- commit: \`${doc.meta.gitSha ?? 'unknown'}\`${doc.meta.gitDirty ? ' (dirty tree)' : ''}`)
  lines.push(`- when: ${doc.meta.createdAt}`)
  lines.push(
    `- params: topK=${result.params.topK} threshold=${result.params.scoreThreshold} minFinalScore=${result.params.minFinalScore}`
  )
  lines.push('')
  lines.push('## Metrics', '')
  lines.push('| metric | value |', '|---|---:|')
  for (const [name, value] of Object.entries(doc.metrics)) {
    lines.push(`| ${name} | ${value === null ? 'n/a' : (value as number).toFixed(4)} |`)
  }
  lines.push('')
  lines.push(`## Misses (${misses.length})`, '')
  if (misses.length === 0) {
    lines.push('None.')
  } else {
    for (const m of misses) {
      lines.push(`### \`${m.id}\``)
      lines.push(`- wanted: ${m.relevantDocIds.join(', ') || '_none_'}`)
      lines.push(`- retrieved: ${m.retrievedDocIds.join(', ') || '_nothing_'}`)
      lines.push('')
    }
  }
  lines.push('## By tag', '')
  lines.push('| tag | recall@5 | ndcg@5 |', '|---|---:|---:|')
  for (const [tag, metrics] of Object.entries(doc.byTag).sort()) {
    const m = metrics as Record<string, number | null>
    const cell = (v: number | null | undefined) => (v === null || v === undefined ? 'n/a' : v.toFixed(4))
    lines.push(`| ${tag} | ${cell(m['recall@5'])} | ${cell(m['ndcg@5'])} |`)
  }
  return lines.join('\n') + '\n'
}

import { BaseCommand, flags } from '@adonisjs/core/ace'
import type { CommandOptions } from '@adonisjs/core/types/ace'
import { Worker } from 'bullmq'
import queueConfig from '#config/queue'
import { RunDownloadJob } from '#jobs/run_download_job'
import { RunExtractPmtilesJob } from '#jobs/run_extract_pmtiles_job'
import { DownloadModelJob } from '#jobs/download_model_job'
import { RunBenchmarkJob } from '#jobs/run_benchmark_job'
import { EmbedFileJob } from '#jobs/embed_file_job'
import { CheckUpdateJob } from '#jobs/check_update_job'
import { CheckServiceUpdatesJob } from '#jobs/check_service_updates_job'
import { AutoUpdateJob } from '#jobs/auto_update_job'
import { AppAutoUpdateJob } from '#jobs/app_auto_update_job'
import { ContentAutoUpdateJob } from '#jobs/content_auto_update_job'
import { DownloadDrugDataJob } from '#jobs/download_drug_data_job'
import { IngestDrugDataJob } from '#jobs/ingest_drug_data_job'
import { stallOptionsForQueue, type StallOptions } from '../../app/utils/queue_stall_options.js'

export default class QueueWork extends BaseCommand {
  static commandName = 'queue:work'
  static description = 'Start processing jobs from the queue'

  @flags.string({ description: 'Queue name to process' })
  declare queue: string

  @flags.boolean({ description: 'Process all queues automatically' })
  declare all: boolean

  static options: CommandOptions = {
    startApp: true,
    staysAlive: true,
  }

  async run() {
    // Validate that either --queue or --all is provided
    if (!this.queue && !this.all) {
      this.logger.error('You must specify either --queue=<name> or --all')
      process.exit(1)
    }

    if (this.queue && this.all) {
      this.logger.error('Cannot specify both --queue and --all flags')
      process.exit(1)
    }

    const [jobHandlers, allQueues] = await this.loadJobHandlers()

    // Determine which queues to process
    const queuesToProcess = this.all ? Array.from(allQueues.values()) : [this.queue]

    this.logger.info(`Starting workers for queues: ${queuesToProcess.join(', ')}`)

    const workers: Worker[] = []

    // Create a worker for each queue
    for (const queueName of queuesToProcess) {
      const stall = this.getStallOptionsForQueue(queueName)
      const worker = new Worker(
        queueName,
        async (job) => {
          this.logger.info(`[${queueName}] Processing job: ${job.id} of type: ${job.name}`)
          const jobHandler = jobHandlers.get(job.name)
          if (!jobHandler) {
            throw new Error(`No handler found for job: ${job.name}`)
          }

          return await jobHandler.handle(job)
        },
        {
          connection: queueConfig.connection,
          concurrency: this.getConcurrencyForQueue(queueName),
          // lockDuration/maxStalledCount are per-queue — see
          // getStallOptionsForQueue for which queues override the default
          // (300000, BullMQ's default maxStalledCount) and why. Queues without
          // an entry there are unaffected.
          lockDuration: stall.lockDuration,
          ...(stall.maxStalledCount !== undefined
            ? { maxStalledCount: stall.maxStalledCount }
            : {}),
          autorun: true,
        }
      )

      // Required to prevent Node from treating BullMQ internal errors as unhandled
      // EventEmitter errors that crash the process.
      worker.on('error', (err) => {
        this.logger.error(`[${queueName}] Worker error: ${err.message}`)
      })

      worker.on('failed', async (job, err) => {
        this.logger.error(`[${queueName}] Job failed: ${job?.id}, Error: ${err.message}`)

        // If this was a Wikipedia download, mark it as failed in the DB
        if (job?.data?.filetype === 'zim' && job?.data?.url?.includes('wikipedia_en_')) {
          try {
            const { DockerService } = await import('#services/docker_service')
            const { ZimService } = await import('#services/zim_service')
            const dockerService = new DockerService()
            const zimService = new ZimService(dockerService)
            await zimService.onWikipediaDownloadComplete(job.data.url, false)
          } catch (e: any) {
            this.logger.error(
              `[${queueName}] Failed to update Wikipedia status: ${e.message}`
            )
          }
        }

        // Terminal failure of an AUTO content update → advance that resource's
        // backoff (self-disables after MAX_CONSECUTIVE_FAILURES). BullMQ emits
        // `failed` on every attempt, so gate on the final attempt to count each
        // doomed download once, not once per retry. Manual downloads (auto !== true)
        // are deliberately excluded.
        const meta = job?.data?.resourceMetadata
        const isTerminal = (job?.attemptsMade ?? 0) >= (job?.opts?.attempts ?? 1)
        if (job?.name === RunDownloadJob.key && meta?.auto === true && isTerminal) {
          try {
            const { default: InstalledResource } = await import('#models/installed_resource')
            const { recordResourceUpdateFailure } = await import(
              '../../app/utils/content_auto_update_backoff.js'
            )
            const resource = await InstalledResource.query()
              .where('resource_id', meta.resource_id)
              .where('resource_type', job.data.filetype)
              .first()
            if (resource) {
              await recordResourceUpdateFailure(
                resource,
                err instanceof Error ? err.message : String(err)
              )
            }
          } catch (e: any) {
            this.logger.error(
              `[${queueName}] Failed to record content auto-update backoff: ${e.message}`
            )
          }
        }
      })

      worker.on('completed', (job) => {
        this.logger.info(`[${queueName}] Job completed: ${job.id}`)
      })

      workers.push(worker)
      this.logger.info(`Worker started for queue: ${queueName}`)
    }

    // Schedule nightly update checks (idempotent, will persist over restarts)
    await CheckUpdateJob.scheduleNightly()
    await CheckServiceUpdatesJob.scheduleNightly()
    await AutoUpdateJob.schedule()
    await AppAutoUpdateJob.schedule()
    await ContentAutoUpdateJob.schedule()

    // Safety net: log unhandled rejections instead of crashing the worker process.
    // Individual job errors are already caught by BullMQ; this catches anything that
    // escapes (e.g. a fire-and-forget promise in a callback that rejects unexpectedly).
    process.on('unhandledRejection', (reason) => {
      this.logger.error(
        `Unhandled promise rejection in worker process: ${reason instanceof Error ? reason.message : String(reason)}`
      )
    })

    // Graceful shutdown for all workers
    process.on('SIGTERM', async () => {
      this.logger.info('SIGTERM received. Shutting down workers...')
      await Promise.all(workers.map((worker) => worker.close()))
      this.logger.info('All workers shut down gracefully.')
      process.exit(0)
    })
  }

  private async loadJobHandlers(): Promise<[Map<string, any>, Map<string, string>]> {
    const handlers = new Map<string, any>()
    const queues = new Map<string, string>()

    handlers.set(RunDownloadJob.key, new RunDownloadJob())
    handlers.set(RunExtractPmtilesJob.key, new RunExtractPmtilesJob())
    handlers.set(DownloadModelJob.key, new DownloadModelJob())
    handlers.set(RunBenchmarkJob.key, new RunBenchmarkJob())
    handlers.set(EmbedFileJob.key, new EmbedFileJob())
    handlers.set(CheckUpdateJob.key, new CheckUpdateJob())
    handlers.set(CheckServiceUpdatesJob.key, new CheckServiceUpdatesJob())
    handlers.set(AutoUpdateJob.key, new AutoUpdateJob())
    handlers.set(AppAutoUpdateJob.key, new AppAutoUpdateJob())
    handlers.set(ContentAutoUpdateJob.key, new ContentAutoUpdateJob())
    handlers.set(DownloadDrugDataJob.key, new DownloadDrugDataJob())
    handlers.set(IngestDrugDataJob.key, new IngestDrugDataJob())

    queues.set(RunDownloadJob.key, RunDownloadJob.queue)
    queues.set(RunExtractPmtilesJob.key, RunExtractPmtilesJob.queue)
    queues.set(DownloadModelJob.key, DownloadModelJob.queue)
    queues.set(RunBenchmarkJob.key, RunBenchmarkJob.queue)
    queues.set(EmbedFileJob.key, EmbedFileJob.queue)
    queues.set(CheckUpdateJob.key, CheckUpdateJob.queue)
    queues.set(CheckServiceUpdatesJob.key, CheckServiceUpdatesJob.queue)
    queues.set(AutoUpdateJob.key, AutoUpdateJob.queue)
    queues.set(AppAutoUpdateJob.key, AppAutoUpdateJob.queue)
    queues.set(ContentAutoUpdateJob.key, ContentAutoUpdateJob.queue)
    queues.set(DownloadDrugDataJob.key, DownloadDrugDataJob.queue)
    queues.set(IngestDrugDataJob.key, IngestDrugDataJob.queue)

    return [handlers, queues]
  }

  /**
   * Per-queue BullMQ stall-recovery options. See `queue_stall_options.ts` for
   * the reasoning behind each queue's entry; the decision itself is kept pure
   * and unit-tested there.
   */
  private getStallOptionsForQueue(queueName: string): StallOptions {
    return stallOptionsForQueue(queueName, {
      embedFile: EmbedFileJob.queue,
      download: RunDownloadJob.queue,
      drugDownload: DownloadDrugDataJob.queue,
      drugIngest: IngestDrugDataJob.queue,
    })
  }

  /**
   * Get concurrency setting for a specific queue
   * Can be customized per queue based on workload characteristics
   */
  private getConcurrencyForQueue(queueName: string): number {
    const concurrencyMap: Record<string, number> = {
      [RunDownloadJob.queue]: 3,
      // pmtiles extract hits the Protomaps CDN with many parallel range reads per job;
      // cap concurrency at 2 so a second extract doesn't starve the first.
      [RunExtractPmtilesJob.queue]: 2,
      [DownloadModelJob.queue]: 2, // Lower concurrency for resource-intensive model downloads
      [RunBenchmarkJob.queue]: 1, // Run benchmarks one at a time for accurate results
      [EmbedFileJob.queue]: 2, // Lower concurrency for embedding jobs, can be resource intensive
      [CheckUpdateJob.queue]: 1, // No need to run more than one update check at a time
      // Drug download: one part at a time — a ~150 MB resumable HTTP pull per
      // part, no benefit to parallelism and easier on the storage volume.
      [DownloadDrugDataJob.queue]: 1,
      // Drug ingest: one heavy stream at a time — unzipping + parsing ~150 MB
      // of JSON into batched DB inserts; serial keeps memory bounded.
      [IngestDrugDataJob.queue]: 1,
      default: 3,
    }

    return concurrencyMap[queueName] || concurrencyMap.default
  }
}

