      service_name: SERVICE_NAMES.TRANSLATE,
      friendly_name: 'Translated Library',
      powered_by: 'Bergamot',
      display_order: 28,
      description:
        'Read the Information Library in another language. Machine translation that works offline, on CPU',
      icon: 'IconWorld',
