import { useEffect, useState } from 'react'
import StyledModal from './StyledModal'
import { formatBytes } from '~/lib/util'
import api from '~/lib/api'

interface Stats {
  cpuPercent: number
  memUsageBytes: number
  memLimitBytes: number
  memPercent: number
}

interface ServiceStatsModalProps {
  serviceName: string
  friendlyName: string
  open: boolean
  onClose: () => void
}

function Bar({ percent, label, value }: { percent: number; label: string; value: string }) {
  const clamped = Math.min(100, Math.max(0, percent))
  return (
    <div>
      <div className="flex items-center justify-between text-xs mb-1">
        <span className="font-medium text-text-primary">{label}</span>
        <span className="text-text-muted font-mono">{value}</span>
      </div>
      <div className="h-2 w-full rounded-full bg-surface-secondary overflow-hidden">
        <div
          className={`h-full rounded-full transition-all ${
            clamped > 90 ? 'bg-desert-red' : clamped > 70 ? 'bg-desert-orange' : 'bg-desert-green'
          }`}
          style={{ width: `${clamped}%` }}
        />
      </div>
    </div>
  )
}

/** Polls and displays live CPU/memory usage for a running service container. */
export default function ServiceStatsModal({
  serviceName,
  friendlyName,
  open,
  onClose,
}: ServiceStatsModalProps) {
  const [stats, setStats] = useState<Stats | null>(null)
  const [running, setRunning] = useState(true)
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    if (!open) return
    let cancelled = false

    async function poll() {
      const res = await api.getServiceStats(serviceName)
      if (cancelled || !res) return
      setRunning(res.running)
      setStats(res.stats)
      setLoading(false)
    }

    setLoading(true)
    poll()
    const id = setInterval(poll, 2000)
    return () => {
      cancelled = true
      clearInterval(id)
    }
  }, [open, serviceName])

  return (
    <StyledModal
      title={`Stats — ${friendlyName}`}
      open={open}
      onCancel={onClose}
      cancelText="Close"
    >
      <div className="space-y-4 text-sm">
        {!running ? (
          <p className="text-text-muted text-center py-6">
            This app is not running. Start it to see live resource usage.
          </p>
        ) : !stats ? (
          <p className="text-text-muted text-center py-6">
            {loading ? 'Loading…' : 'No stats available.'}
          </p>
        ) : (
          <>
            <Bar label="CPU" percent={stats.cpuPercent} value={`${stats.cpuPercent.toFixed(1)}%`} />
            <Bar
              label="Memory"
              percent={stats.memPercent}
              value={`${formatBytes(stats.memUsageBytes)} / ${formatBytes(stats.memLimitBytes)} (${stats.memPercent.toFixed(1)}%)`}
            />
            <p className="text-xs text-text-muted">Updates every 2 seconds.</p>
          </>
        )}
      </div>
    </StyledModal>
  )
}

import classNames from '~/lib/classNames'
import { formatBytes } from '~/lib/util'
import { IconAlertTriangle, IconServer } from '@tabler/icons-react'

interface StorageProjectionBarProps {
  totalSize: number // Total disk size in bytes
  currentUsed: number // Currently used space in bytes
  projectedAddition: number // Additional space that will be used in bytes
}

export default function StorageProjectionBar({
  totalSize,
  currentUsed,
  projectedAddition,
}: StorageProjectionBarProps) {
  const projectedTotal = currentUsed + projectedAddition
  const currentPercent = (currentUsed / totalSize) * 100
  const projectedPercent = (projectedAddition / totalSize) * 100
  const projectedTotalPercent = (projectedTotal / totalSize) * 100
  const remainingAfter = totalSize - projectedTotal
  const willExceed = projectedTotal > totalSize

  // Determine warning level based on projected total
  const getProjectedColor = () => {
    if (willExceed) return 'bg-desert-red'
    if (projectedTotalPercent >= 90) return 'bg-desert-orange'
    if (projectedTotalPercent >= 75) return 'bg-desert-tan'
    return 'bg-desert-olive'
  }

  const getProjectedGlow = () => {
    if (willExceed) return 'shadow-desert-red/50'
    if (projectedTotalPercent >= 90) return 'shadow-desert-orange/50'
    if (projectedTotalPercent >= 75) return 'shadow-desert-tan/50'
    return 'shadow-desert-olive/50'
  }

  return (
    <div className="bg-desert-stone-lighter/30 rounded-lg p-4 border border-desert-stone-light">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <IconServer size={20} className="text-desert-green" />
          <span className="font-semibold text-desert-green">Storage</span>
        </div>
        <div className="text-sm text-desert-stone-dark font-mono">
          {formatBytes(projectedTotal, 1)} / {formatBytes(totalSize, 1)}
          {projectedAddition > 0 && (
            <span className="text-desert-stone ml-2">
              (+{formatBytes(projectedAddition, 1)} selected)
            </span>
          )}
        </div>
      </div>

      {/* Progress bar */}
      <div className="relative">
        <div className="h-8 bg-desert-green-lighter/20 rounded-lg border border-desert-stone-light overflow-hidden">
          {/* Current usage - darker/subdued */}
          <div
            className="absolute h-full bg-desert-stone transition-all duration-300"
            style={{ width: `${Math.min(currentPercent, 100)}%` }}
          />
          {/* Projected addition - highlighted */}
          {projectedAddition > 0 && (
            <div
              className={classNames(
                'absolute h-full transition-all duration-300 shadow-lg',
                getProjectedColor(),
                getProjectedGlow()
              )}
              style={{
                left: `${Math.min(currentPercent, 100)}%`,
                width: `${Math.min(projectedPercent, 100 - currentPercent)}%`,
              }}
            />
          )}
        </div>

        {/* Percentage label */}
        <div
          className={classNames(
            'absolute top-1/2 -translate-y-1/2 font-bold text-sm',
            projectedTotalPercent > 15
              ? 'left-3 text-white drop-shadow-md'
              : 'right-3 text-desert-green'
          )}
        >
          {Math.round(projectedTotalPercent)}%
        </div>
      </div>

      {/* Legend and warnings */}
      <div className="flex items-center justify-between mt-3">
        <div className="flex items-center gap-4 text-xs">
          <div className="flex items-center gap-1.5">
            <div className="w-3 h-3 rounded bg-desert-stone" />
            <span className="text-desert-stone-dark">Current ({formatBytes(currentUsed, 1)})</span>
          </div>
          {projectedAddition > 0 && (
            <div className="flex items-center gap-1.5">
              <div className={classNames('w-3 h-3 rounded', getProjectedColor())} />
              <span className="text-desert-stone-dark">
                Selected (+{formatBytes(projectedAddition, 1)})
              </span>
            </div>
          )}
        </div>

        {willExceed ? (
          <div className="flex items-center gap-1.5 text-desert-red text-xs font-medium">
            <IconAlertTriangle size={14} />
            <span>Exceeds available space by {formatBytes(projectedTotal - totalSize, 1)}</span>
          </div>
        ) : (
          <div className="text-xs text-desert-stone">
            {formatBytes(remainingAfter, 1)} will remain free
          </div>
        )}
      </div>
    </div>
  )
}

import { useMemo } from 'react'
import clsx from 'clsx'
import DynamicIcon, { DynamicIconName} from './DynamicIcon'
import { IconRefresh } from '@tabler/icons-react'

export interface StyledButtonProps extends React.HTMLAttributes<HTMLButtonElement> {
  children: React.ReactNode
  icon?: DynamicIconName
  disabled?: boolean
  variant?: 'primary' | 'secondary' | 'danger' | 'action' | 'success' | 'ghost' | 'outline'
  size?: 'sm' | 'md' | 'lg'
  loading?: boolean
  fullWidth?: boolean
}

const StyledButton: React.FC<StyledButtonProps> = ({
  children,
  icon,
  variant = 'primary',
  size = 'md',
  loading = false,
  fullWidth = false,
  className,
  ...props
}) => {
  const isDisabled = useMemo(() => {
    return props.disabled || loading
  }, [props.disabled, loading])

  const getIconSize = () => {
    switch (size) {
      case 'sm':
        return 'h-3.5 w-3.5 mr-1.5'
      case 'lg':
        return 'h-5 w-5 mr-2.5'
      default:
        return 'h-4 w-4 mr-2'
    }
  }

  const getSizeClasses = () => {
    switch (size) {
      case 'sm':
        return 'px-2.5 py-1.5 text-xs'
      case 'lg':
        return 'px-4 py-3 text-base'
      default:
        return 'px-3 py-2 text-sm'
    }
  }

  const getVariantClasses = () => {
    const baseTransition = 'transition-all duration-200 ease-in-out'
    const baseHover = 'hover:shadow-md active:scale-[0.98]'

    switch (variant) {
      case 'primary':
        return clsx(
          'bg-desert-green text-white',
          'hover:bg-btn-green-hover hover:shadow-lg',
          'active:bg-btn-green-active',
          'disabled:bg-desert-green-light disabled:text-desert-stone-light',
          baseTransition,
          baseHover
        )

      case 'secondary':
        return clsx(
          'bg-desert-tan text-white',
          'hover:bg-desert-tan-dark hover:shadow-lg',
          'active:bg-desert-tan-dark',
          'disabled:bg-desert-tan-lighter disabled:text-desert-stone-light',
          baseTransition,
          baseHover
        )

      case 'danger':
        return clsx(
          'bg-desert-red text-white',
          'hover:bg-desert-red-dark hover:shadow-lg',
          'active:bg-desert-red-dark',
          'disabled:bg-desert-red-lighter disabled:text-desert-stone-light',
          baseTransition,
          baseHover
        )

      case 'action':
        return clsx(
          'bg-desert-orange text-white',
          'hover:bg-desert-orange-light hover:shadow-lg',
          'active:bg-desert-orange-dark',
          'disabled:bg-desert-orange-lighter disabled:text-desert-stone-light',
          baseTransition,
          baseHover
        )

      case 'success':
        return clsx(
          'bg-desert-olive text-white',
          'hover:bg-desert-olive-dark hover:shadow-lg',
          'active:bg-desert-olive-dark',
          'disabled:bg-desert-olive-lighter disabled:text-desert-stone-light',
          baseTransition,
          baseHover
        )

      case 'ghost':
        return clsx(
          'bg-transparent text-desert-green',
          'hover:bg-desert-sand hover:text-desert-green-dark',
          'active:bg-desert-green-lighter',
          'disabled:text-desert-stone-light',
          baseTransition
        )

      case 'outline':
        return clsx(
          'bg-transparent border-2 border-desert-green text-desert-green',
          'hover:bg-desert-green hover:text-white hover:border-btn-green-hover',
          'active:bg-btn-green-hover active:border-btn-green-active',
          'disabled:border-desert-green-lighter disabled:text-desert-stone-light',
          baseTransition,
          baseHover
        )

      default:
        return ''
    }
  }

  const getLoadingSpinner = () => {
    const spinnerSize = size === 'sm' ? 'h-3.5 w-3.5' : size === 'lg' ? 'h-5 w-5' : 'h-4 w-4'
    return (
      <IconRefresh
        className={clsx(spinnerSize, 'animate-spin')}
      />
    )
  }

  const onClickHandler = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (isDisabled) {
      e.preventDefault()
      return
    }
    props.onClick?.(e)
  }

  return (
    <button
      type="button"
      className={clsx(
        fullWidth ? 'flex w-full' : 'inline-flex',
        getSizeClasses(),
        getVariantClasses(),
        isDisabled ? 'pointer-events-none opacity-60' : 'cursor-pointer',
        'items-center justify-center rounded-md font-semibold focus:outline-none focus:ring-2 focus:ring-desert-green-light focus:ring-offset-2 focus:ring-offset-desert-sand disabled:cursor-not-allowed disabled:shadow-none',
        className
      )}
      {...props}
      disabled={isDisabled}
      onClick={onClickHandler}
    >
      {loading ? (
        getLoadingSpinner()
      ) : (
        <>
          {icon && <DynamicIcon icon={icon} className={getIconSize()} />}
          {children}
        </>
      )}
    </button>
  )
}

export default StyledButton

