import { IconPhoto, IconSend, IconWand, IconX } from '@tabler/icons-react'
import { useState, useRef, useEffect } from 'react'
import classNames from '~/lib/classNames'
import { ChatImageAttachment, ChatMessage } from '../../../types/chat'
import type { ModelVisionCapability } from '../../../types/ollama'
import ChatMessageBubble from './ChatMessageBubble'
import ChatAssistantAvatar from './ChatAssistantAvatar'
import BouncingDots from '../BouncingDots'
import { usePage } from '@inertiajs/react'
import InfoTooltip from '../InfoTooltip'
import { visionAttachmentGuidance } from '../../lib/vision_guidance'

interface ChatInterfaceProps {
  messages: ChatMessage[]
  onSendMessage: (message: string, images: ChatImageAttachment[]) => void
  visionCapability: ModelVisionCapability
  isLoading?: boolean
  chatSuggestions?: string[]
  chatSuggestionsEnabled?: boolean
  chatSuggestionsLoading?: boolean
}

// Sent as an ordinary turn, so it goes through retrieval, budgeting and
// persistence like any other message. The cut-off answer is the newest turn in
// history, which the budget keeps first.
const CONTINUE_PROMPT = 'Continue exactly where you left off. Do not repeat what you already wrote.'

const MAX_VISION_IMAGES = 4
const MAX_VISION_IMAGE_BYTES = 8 * 1024 * 1024
const SUPPORTED_VISION_TYPES = new Set(['image/jpeg', 'image/png', 'image/webp'])

export default function ChatInterface({
  messages,
  onSendMessage,
  visionCapability,
  isLoading = false,
  chatSuggestions = [],
  chatSuggestionsEnabled = false,
  chatSuggestionsLoading = false,
}: ChatInterfaceProps) {
  const { aiAssistantName } = usePage<{ aiAssistantName: string }>().props
  const [input, setInput] = useState('')
  const [images, setImages] = useState<ChatImageAttachment[]>([])
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const textareaRef = useRef<HTMLTextAreaElement>(null)
  const imageInputRef = useRef<HTMLInputElement>(null)
  const previewUrlsRef = useRef<Set<string>>(new Set())

  useEffect(
    () => () => {
      previewUrlsRef.current.forEach((url) => URL.revokeObjectURL(url))
      previewUrlsRef.current.clear()
    },
    []
  )

  useEffect(() => {
    if (visionCapability !== 'unsupported') return
    setImages((current) => {
      current.forEach((image) => {
        URL.revokeObjectURL(image.previewUrl)
        previewUrlsRef.current.delete(image.previewUrl)
      })
      return []
    })
  }, [visionCapability])

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if ((input.trim() || images.length > 0) && !isLoading) {
      onSendMessage(input.trim() || 'Describe the attached image.', images)
      setInput('')
      setImages([])
      if (imageInputRef.current) imageInputRef.current.value = ''
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto'
      }
    }
  }

  const handleImageSelection = (event: React.ChangeEvent<HTMLInputElement>) => {
    const selected = Array.from(event.target.files ?? [])
    event.target.value = ''
    if (selected.length === 0) return

    const availableSlots = MAX_VISION_IMAGES - images.length
    if (availableSlots <= 0) {
      addNotification({ type: 'error', message: `You can attach up to ${MAX_VISION_IMAGES} images.` })
      return
    }

    const attachments: ChatImageAttachment[] = []
    for (const file of selected.slice(0, availableSlots)) {
      if (!SUPPORTED_VISION_TYPES.has(file.type)) {
        addNotification({
          type: 'error',
          message: `${file.name} is not supported. Use JPEG, PNG, or WebP.`,
        })
        continue
      }
      if (file.size > MAX_VISION_IMAGE_BYTES) {
        addNotification({
          type: 'error',
          message: `${file.name} exceeds the 8 MB per-image limit.`,
        })
        continue
      }

      const previewUrl = URL.createObjectURL(file)
      previewUrlsRef.current.add(previewUrl)
      attachments.push({
        id: crypto.randomUUID(),
        name: file.name,
        file,
        previewUrl,
      })
    }

    if (selected.length > availableSlots) {
      addNotification({
        type: 'error',
        message: `Only the first ${availableSlots} selected image(s) were attached.`,
      })
    }
    setImages((current) => [...current, ...attachments])
  }

  const removeImage = (image: ChatImageAttachment) => {
    URL.revokeObjectURL(image.previewUrl)
    previewUrlsRef.current.delete(image.previewUrl)
    setImages((current) => current.filter((item) => item.id !== image.id))
  }

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSubmit(e)
    }
  }

  const handleInput = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setInput(e.target.value)
    // Auto-resize textarea
    e.target.style.height = 'auto'
    e.target.style.height = `${Math.min(e.target.scrollHeight, 200)}px`
  }

  return (
    <div className="flex-1 flex flex-col min-h-0 bg-surface-primary shadow-sm">
      <div className="flex-1 overflow-y-auto px-6 py-4 space-y-6">
        {messages.length === 0 ? (
          <div className="h-full flex items-center justify-center">
            <div className="text-center max-w-md">
              <IconWand className="h-16 w-16 text-desert-green mx-auto mb-4 opacity-50" />
              <h3 className="text-lg font-medium text-text-primary mb-2">Start a conversation</h3>
              <p className="text-text-muted text-sm">
                Interact with your installed language models directly in the Command Center.
              </p>
              {chatSuggestionsEnabled &&
                chatSuggestions &&
                chatSuggestions.length > 0 &&
                !chatSuggestionsLoading && (
                  <div className="mt-8">
                    <h4 className="text-sm font-medium text-text-secondary mb-2">Suggestions:</h4>
                    <div className="flex flex-col gap-2">
                      {chatSuggestions.map((suggestion, index) => (
                        <button
                          key={index}
                          onClick={() => {
                            setInput(suggestion)
                            // Focus the textarea after setting input
                            setTimeout(() => {
                              textareaRef.current?.focus()
                            }, 0)
                          }}
                          className="px-4 py-2 bg-surface-secondary hover:bg-surface-secondary rounded-lg text-sm text-text-primary transition-colors"
                        >
                          {suggestion}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              {/* Display bouncing dots while loading suggestions */}
              {chatSuggestionsEnabled && chatSuggestionsLoading && (
                <BouncingDots text="Thinking" containerClassName="mt-8" />
              )}
              {!chatSuggestionsEnabled && (
                <div className="mt-8 text-sm text-text-muted">
                  Need some inspiration? Enable chat suggestions in settings to get started with
                  example prompts.
                </div>
              )}
            </div>
          </div>
        ) : (
          <>
            {messages.map((message, idx) => (
              <div
                key={message.id}
                className={classNames(
                  'flex gap-4',
                  message.role === 'user' ? 'justify-end' : 'justify-start'
                )}
              >
                {message.role === 'assistant' && <ChatAssistantAvatar />}
                <ChatMessageBubble
                  message={message}
                  onContinue={
                    idx === messages.length - 1 && !isLoading
                      ? () => onSendMessage(CONTINUE_PROMPT, [])
                      : undefined
                  }
                />
              </div>
            ))}
            {/* Loading/thinking indicator */}
            {isLoading && (
              <div className="flex gap-4 justify-start">
                <ChatAssistantAvatar />
                <div className="max-w-[85%] sm:max-w-[70%] rounded-lg px-4 py-3 bg-surface-secondary text-text-primary">
                  <BouncingDots text="Thinking" />
                </div>
              </div>
            )}

            <div ref={messagesEndRef} />
          </>
        )}
      </div>
      <div className="border-t border-border-subtle bg-surface-primary px-6 py-4 flex-shrink-0 min-h-[90px]">
        {images.length > 0 && (
          <div className="mb-3 flex flex-wrap gap-3" aria-label="Attached images">
            {images.map((image) => (
              <div
                key={image.id}
                className="relative h-20 w-20 overflow-hidden rounded-lg border border-border-default bg-surface-secondary"
              >
                <img src={image.previewUrl} alt={image.name} className="h-full w-full object-cover" />
                <button
                  type="button"
                  onClick={() => removeImage(image)}
                  className="absolute right-1 top-1 rounded-full bg-surface-primary/90 p-1 text-text-primary hover:bg-surface-primary"
                  aria-label={`Remove ${image.name}`}
                  disabled={isLoading}
                >
                  <IconX className="h-3.5 w-3.5" aria-hidden="true" />
                </button>
              </div>
            ))}
          </div>
        )}
        <form onSubmit={handleSubmit} className="flex gap-3 items-end">
          <input
            ref={imageInputRef}
            type="file"
            accept="image/jpeg,image/png,image/webp"
            multiple
            className="hidden"
            onChange={handleImageSelection}
          />
          <div className="mb-2 flex items-center">
            <button
              type="button"
              onClick={() => imageInputRef.current?.click()}
              disabled={
                isLoading ||
                images.length >= MAX_VISION_IMAGES ||
                visionCapability === 'unsupported'
              }
              className={classNames(
                'p-3 rounded-lg transition-colors flex-shrink-0',
                isLoading ||
                  images.length >= MAX_VISION_IMAGES ||
                  visionCapability === 'unsupported'
                  ? 'bg-border-default text-text-muted cursor-not-allowed'
                  : 'border border-border-default text-text-secondary hover:bg-surface-secondary'
              )}
              aria-label="Attach images"
            >
              <IconPhoto className="h-6 w-6" aria-hidden="true" />
            </button>
            {visionCapability !== 'supported' && (
              <InfoTooltip
                position="top"
                align="left"
                text={
                  visionAttachmentGuidance(visionCapability)
                }
              />
            )}
          </div>
          <div className="flex-1 relative">
            <textarea
              ref={textareaRef}
              value={input}
              onChange={handleInput}
              onKeyDown={handleKeyDown}
              placeholder={`Type your message to ${aiAssistantName}... (Shift+Enter for new line)`}
              className="w-full resize-none rounded-lg border border-border-default px-4 py-3 pr-12 focus:outline-none focus:ring-2 focus:ring-desert-green focus:border-transparent disabled:bg-surface-secondary disabled:text-text-muted"
              rows={1}
              disabled={isLoading}
              style={{ maxHeight: '200px' }}
            />
          </div>
          <button
            type="submit"
            disabled={(!input.trim() && images.length === 0) || isLoading}
            className={classNames(
              'p-3 rounded-lg transition-all duration-200 flex-shrink-0 mb-2',
              (!input.trim() && images.length === 0) || isLoading
                ? 'bg-border-default text-text-muted cursor-not-allowed'
                : 'bg-desert-green text-white hover:bg-desert-green/90 hover:scale-105'
            )}
          >
            {isLoading ? (
              <div className="h-6 w-6 border-2 border-white border-t-transparent rounded-full animate-spin" />
            ) : (
              <IconSend className="h-6 w-6" />
            )}
          </button>
        </form>
        <p className="mt-2 text-xs text-text-muted" aria-live="polite">
          {visionAttachmentGuidance(visionCapability)}
        </p>
      </div>
    </div>
  )
}

import classNames from '~/lib/classNames'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import { ChatMessage } from '../../../types/chat'

export interface ChatMessageBubbleProps {
  message: ChatMessage
  // Offered on the latest answer when it was cut off at the length limit.
  onContinue?: () => void
}

export default function ChatMessageBubble({ message, onContinue }: ChatMessageBubbleProps) {
  return (
    <div
      className={classNames(
        'max-w-[70%] rounded-lg px-4 py-3',
        message.role === 'user' ? 'bg-desert-green text-white' : 'bg-surface-secondary text-text-primary'
      )}
    >
      {message.images && message.images.length > 0 && (
        <div className="mb-3 grid grid-cols-2 gap-2">
          {message.images.map((image) => (
            <img
              key={image.id}
              src={image.previewUrl}
              alt={image.name}
              className="max-h-64 w-full rounded-md bg-surface-primary/20 object-contain"
            />
          ))}
        </div>
      )}
      {message.isThinking && message.thinking && (
        <div className="mb-3 rounded border border-amber-200 bg-amber-50 px-3 py-2 text-xs">
          <div className="mb-1 flex items-center gap-1.5 font-medium text-amber-700">
            <span>Reasoning</span>
            <span className="h-1.5 w-1.5 rounded-full bg-amber-500 animate-pulse inline-block" />
          </div>
          <div className="prose prose-xs max-w-none text-amber-900/80 max-h-32 overflow-y-auto">
            <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.thinking}</ReactMarkdown>
          </div>
        </div>
      )}
      {!message.isThinking && message.thinking && (
        <details className="mb-3 rounded border border-border-subtle bg-surface-secondary text-xs">
          <summary className="cursor-pointer px-3 py-2 font-medium text-text-muted hover:text-text-primary select-none">
            {message.thinkingDuration !== undefined
              ? `Thought for ${message.thinkingDuration}s`
              : 'Reasoning'}
          </summary>
          <div className="px-3 pb-3 prose prose-xs max-w-none text-text-secondary max-h-48 overflow-y-auto border-t border-border-subtle pt-2">
            <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.thinking}</ReactMarkdown>
          </div>
        </details>
      )}
      <div
        className={classNames(
          'break-words',
          message.role === 'assistant' ? 'prose prose-sm max-w-none' : 'whitespace-pre-wrap'
        )}
      >
        {message.role === 'assistant' ? (
          <ReactMarkdown
            remarkPlugins={[remarkGfm]}
            components={{
              code: ({ node, className, children, ...props }: any) => {
                const isInline = !className?.includes('language-')
                if (isInline) {
                  return (
                    <code
                      className="bg-gray-800 text-gray-100 px-2 py-0.5 rounded font-mono text-sm"
                      {...props}
                    >
                      {children}
                    </code>
                  )
                }
                return (
                  <code
                    className="block bg-gray-800 text-gray-100 p-3 rounded-lg overflow-x-auto font-mono text-sm my-2"
                    {...props}
                  >
                    {children}
                  </code>
                )
              },
              p: ({ children }) => <p className="mb-2 last:mb-0">{children}</p>,
              ul: ({ children }) => <ul className="list-disc pl-5 mb-2">{children}</ul>,
              ol: ({ children }) => <ol className="list-decimal pl-5 mb-2">{children}</ol>,
              li: ({ children }) => <li className="mb-1">{children}</li>,
              h1: ({ children }) => <h1 className="text-xl font-bold mb-2">{children}</h1>,
              h2: ({ children }) => <h2 className="text-lg font-bold mb-2">{children}</h2>,
              h3: ({ children }) => <h3 className="text-base font-bold mb-2">{children}</h3>,
              blockquote: ({ children }) => (
                <blockquote className="border-l-4 border-border-default pl-4 italic my-2">
                  {children}
                </blockquote>
              ),
              a: ({ children, href }) => (
                <a
                  href={href}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-desert-green underline hover:text-desert-green/80"
                >
                  {children}
                </a>
              ),
            }}
          >
            {message.content}
          </ReactMarkdown>
        ) : (
          message.content
        )}
        {message.isStreaming && (
          <span className="inline-block w-2 h-4 ml-1 bg-current animate-pulse" />
        )}
      </div>
      {message.role === 'assistant' && message.truncated && !message.isStreaming && (
        <div className="mt-3 flex flex-wrap items-center gap-2 border-t border-border-subtle pt-2 text-xs text-text-secondary">
          <span>This answer hit the length limit and was cut off.</span>
          {onContinue && (
            <button
              type="button"
              onClick={onContinue}
              className="rounded border border-border-default px-2 py-0.5 font-medium text-desert-green hover:bg-surface-primary focus:outline-none focus:ring-2 focus:ring-desert-green"
            >
              Continue
            </button>
          )}
        </div>
      )}
      {message.role === 'assistant' && message.sources && message.sources.length > 0 && (
        <div className="mt-3 border-t border-border-subtle pt-2 text-xs text-text-primary">
          <div className="mb-1 font-medium">Sources</div>
          <ul className="space-y-0.5">
            {message.sources.map((src, idx) => (
              <li key={idx}>
                {src.title}
                {src.date && <span className="text-text-secondary"> ({src.date})</span>}
              </li>
            ))}
          </ul>
        </div>
      )}
      <div
        className={classNames(
          'text-xs mt-2',
          message.role === 'user' ? 'text-white/70' : 'text-text-muted'
        )}
      >
        {message.timestamp.toLocaleTimeString([], {
          hour: '2-digit',
          minute: '2-digit',
        })}
      </div>
    </div>
  )
}

import classNames from '~/lib/classNames'
import StyledButton from '../StyledButton'
import { router, usePage } from '@inertiajs/react'
import { ChatSession } from '../../../types/chat'
import { IconMessage } from '@tabler/icons-react'
import { useState } from 'react'
import KnowledgeBaseModal from './KnowledgeBaseModal'
import NomadMdModal from './NomadMdModal'

interface ChatSidebarProps {
  sessions: ChatSession[]
  activeSessionId: string | null
  onSessionSelect: (id: string) => void
  onNewChat: () => void
  onClearHistory: () => void
  isInModal?: boolean
  isMobileOpen?: boolean
  onMobileClose?: () => void
}

export default function ChatSidebar({
  sessions,
  activeSessionId,
  onSessionSelect,
  onNewChat,
  onClearHistory,
  isInModal = false,
  isMobileOpen = false,
  onMobileClose,
}: ChatSidebarProps) {
  const { aiAssistantName } = usePage<{ aiAssistantName: string }>().props
  const [isKnowledgeBaseModalOpen, setIsKnowledgeBaseModalOpen] = useState(
    () => new URLSearchParams(window.location.search).get('knowledge_base') === 'true'
  )
  const [isNomadMdModalOpen, setIsNomadMdModalOpen] = useState(false)

  function handleCloseKnowledgeBase() {
    setIsKnowledgeBaseModalOpen(false)
    const params = new URLSearchParams(window.location.search)
    if (params.has('knowledge_base')) {
      params.delete('knowledge_base')
      const newUrl = [window.location.pathname, params.toString()].filter(Boolean).join('?')
      window.history.replaceState(window.history.state, '', newUrl)
    }
  }

  return (
    <aside
      id="chat-sidebar"
      className={classNames(
        'w-64 bg-surface-secondary border-r border-border-subtle flex-col h-full shrink-0',
        'fixed inset-y-0 left-0 z-50 md:static md:z-auto md:flex',
        isMobileOpen ? 'flex' : 'hidden'
      )}
      aria-label="Chat conversations"
    >
      <div className="p-4 border-b border-border-subtle h-[75px] flex items-center justify-center">
        <StyledButton
          onClick={() => {
            onNewChat()
            onMobileClose?.()
          }}
          icon="IconPlus"
          variant="primary"
          fullWidth
        >
          New Chat
        </StyledButton>
      </div>

      <div className="flex-1 overflow-y-auto">
        {sessions.length === 0 ? (
          <div className="p-4 text-center text-text-muted text-sm">No previous chats</div>
        ) : (
          <div className="p-2 space-y-1">
            {sessions.map((session) => (
              <button
                key={session.id}
                onClick={() => {
                  onSessionSelect(session.id)
                  onMobileClose?.()
                }}
                className={classNames(
                  'w-full text-left px-3 py-2 rounded-lg transition-colors group',
                  activeSessionId === session.id
                    ? 'bg-desert-green text-white'
                    : 'hover:bg-surface-secondary text-text-primary'
                )}
              >
                <div className="flex items-start gap-2">
                  <IconMessage
                    className={classNames(
                      'h-5 w-5 mt-0.5 shrink-0',
                      activeSessionId === session.id ? 'text-white' : 'text-text-muted'
                    )}
                  />
                  <div className="flex-1 min-w-0">
                    <div className="font-medium text-sm truncate">{session.title}</div>
                    {session.lastMessage && (
                      <div
                        className={classNames(
                          'text-xs truncate mt-0.5',
                          activeSessionId === session.id ? 'text-white/80' : 'text-text-muted'
                        )}
                      >
                        {session.lastMessage}
                      </div>
                    )}
                  </div>
                </div>
              </button>
            ))}
          </div>
        )}
      </div>
      <div className="p-4 flex flex-col items-center justify-center gap-y-2">
        <img src="/nomad-primary.svg" alt="Project NOMAD Logo" className="h-28 w-28 mb-6 object-contain" />
        <StyledButton
          onClick={() => {
            // /chat is served by the admin app itself, so navigate in place rather than
            // spawning a window. Popping out broke anyone running NOMAD as an installed
            // web app or in kiosk mode, who then had a stray window to get back out of.
            router.visit(isInModal ? '/chat' : '/home')
          }}
          icon={isInModal ? 'IconArrowRight' : 'IconHome'}
          variant="outline"
          size="sm"
          fullWidth
        >
          {isInModal ? 'Open Full Chat' : 'Back to Home'}
        </StyledButton>
        <StyledButton
          onClick={() => {
            router.visit('/settings/models')
          }}
          icon="IconDatabase"
          variant="primary"
          size="sm"
          fullWidth
        >
          Models & Settings
        </StyledButton>
        <StyledButton
          onClick={() => {
            setIsKnowledgeBaseModalOpen(true)
          }}
          icon="IconBrain"
          variant="primary"
          size="sm"
          fullWidth
        >
          Knowledge Base
        </StyledButton>
        <StyledButton
          onClick={() => {
            setIsNomadMdModalOpen(true)
          }}
          icon="IconFileDescription"
          variant="primary"
          size="sm"
          fullWidth
        >
          NOMAD.md
        </StyledButton>
        {sessions.length > 0 && (
          <StyledButton
            onClick={onClearHistory}
            icon="IconTrash"
            variant="danger"
            size="sm"
            fullWidth
          >
            Clear History
          </StyledButton>
        )}
      </div>
      {isKnowledgeBaseModalOpen && (
        <KnowledgeBaseModal aiAssistantName={aiAssistantName} onClose={handleCloseKnowledgeBase} />
      )}
      {isNomadMdModalOpen && (
        <NomadMdModal
          aiAssistantName={aiAssistantName}
          onClose={() => setIsNomadMdModalOpen(false)}
        />
      )}
    </aside>
  )
}

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react'
import { createPortal } from 'react-dom'

interface CollectionComboboxProps {
  /** Current value. Empty string means "Uncategorized". */
  value: string
  onChange: (value: string) => void
  /** Presets + known-in-use tags, already merged and deduped by the caller. */
  options: string[]
  placeholder?: string
  allowUncategorized?: boolean
  className?: string
  disabled?: boolean
}

/**
 * Dependency-free creatable combobox for collection tags. Lets you pick an
 * existing option (preset or already-in-use) or type a brand new one — the
 * "+ Create" row only appears when the (normalized) input doesn't already
 * match something. Actual normalization (trim/lowercase/length cap) happens
 * server-side via sanitizeCollectionName; this just lowercases for the
 * match-check and display so duplicates-by-case don't look like real options.
 *
 * The option list is portaled to `document.body` and positioned via
 * `getBoundingClientRect()` rather than living in normal flow. This is used
 * inside table cells (e.g. the Stored Files panel), where any ancestor with
 * non-`visible` overflow -- a `<td>`, or `StyledTable`'s own scroll wrapper --
 * would otherwise clip the popover to that ancestor's box.
 */
export default function CollectionCombobox({
  value,
  onChange,
  options,
  placeholder = 'Uncategorized',
  allowUncategorized = true,
  className = '',
  disabled = false,
}: CollectionComboboxProps) {
  const [query, setQuery] = useState(value)
  const [isOpen, setIsOpen] = useState(false)
  // Whether the user has typed since the popover opened. The input is
  // pre-filled with `value` on open, but that shouldn't filter the option
  // list down to just the current value -- only actual typing should.
  const [userTyped, setUserTyped] = useState(false)
  const containerRef = useRef<HTMLDivElement>(null)
  const dropdownRef = useRef<HTMLDivElement>(null)
  const [position, setPosition] = useState<{ left: number; top: number; width: number } | null>(null)

  useEffect(() => {
    setQuery(value)
  }, [value])

  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      const target = e.target as Node
      // The list is portaled to <body>, so it is NOT inside containerRef — check both,
      // otherwise mousedown on an option closes the list before its click can land.
      const insideInput = containerRef.current?.contains(target)
      const insideList = dropdownRef.current?.contains(target)
      if (!insideInput && !insideList) {
        setIsOpen(false)
        setQuery(value)
        setUserTyped(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [value])

  /**
   * The list renders in a portal with fixed positioning rather than absolutely inside
   * the input's own box. Every ancestor that sets `overflow` other than visible would
   * otherwise clip it: in the Knowledge Base table each cell carries `truncate`
   * (overflow:hidden), which cropped the list to a single row's height, and the modal
   * body is an `overflow-y-auto` scroller the list could not escape either. Fixed
   * positioning against the viewport sidesteps both.
   */
  const reposition = useCallback(() => {
    const input = containerRef.current
    if (!input) return
    const rect = input.getBoundingClientRect()
    const MAX_HEIGHT = 224 // matches max-h-56
    const GAP = 4
    const spaceBelow = window.innerHeight - rect.bottom
    // Flip above the input when the list would run off the bottom of the viewport
    // and there is more headroom up top.
    const flipUp = spaceBelow < MAX_HEIGHT + GAP && rect.top > spaceBelow
    setPosition({
      left: rect.left,
      top: flipUp ? Math.max(GAP, rect.top - GAP - MAX_HEIGHT) : rect.bottom + GAP,
      width: rect.width,
    })
  }, [])

  useLayoutEffect(() => {
    if (!isOpen) return
    reposition()
    // `true` for capture so scrolling in any ancestor scroller keeps the list attached
    // to its input rather than leaving it stranded mid-air.
    window.addEventListener('scroll', reposition, true)
    window.addEventListener('resize', reposition)
    return () => {
      window.removeEventListener('scroll', reposition, true)
      window.removeEventListener('resize', reposition)
    }
  }, [isOpen, reposition])

  const normalizedQuery = query.trim().toLowerCase()
  // Filtering (and the "+ Create" row) only kick in once the user has typed
  // -- otherwise the pre-filled current value would filter the list down to
  // just itself the instant the popover opens.
  const filterQuery = userTyped ? normalizedQuery : ''
  const filtered = filterQuery
    ? options.filter((o) => o.toLowerCase().includes(filterQuery))
    : options
  const exactMatch = options.find((o) => o.toLowerCase() === normalizedQuery)
  const showCreateOption = userTyped && normalizedQuery.length > 0 && !exactMatch

  const commit = (val: string) => {
    onChange(val)
    setQuery(val)
    setIsOpen(false)
    setUserTyped(false)
  }

  return (
    <div ref={containerRef} className={`relative ${className}`}>
      <input
        type="text"
        value={query}
        disabled={disabled}
        onChange={(e) => {
          setQuery(e.target.value)
          setIsOpen(true)
          setUserTyped(true)
        }}
        onFocus={() => setIsOpen(true)}
        onKeyDown={(e) => {
          if (e.key === 'Enter') {
            e.preventDefault()
            const trimmed = query.trim()
            if (!trimmed) {
              if (allowUncategorized) commit('')
              return
            }
            commit(exactMatch ?? trimmed.toLowerCase())
          } else if (e.key === 'Escape') {
            setIsOpen(false)
            setQuery(value)
            setUserTyped(false)
          }
        }}
        placeholder={placeholder}
        className="w-full rounded border border-border-subtle bg-surface-primary px-2 py-1 text-sm text-text-primary disabled:opacity-50"
      />
      {isOpen && !disabled && position && createPortal(
        <div
          ref={dropdownRef}
          style={{ left: position.left, top: position.top, width: position.width }}
          className="fixed z-[60] max-h-56 overflow-auto rounded border border-border-subtle bg-surface-primary shadow-lg"
        >
          {allowUncategorized && (
            <button
              type="button"
              className="block w-full text-left px-2 py-1.5 text-sm text-text-secondary hover:bg-surface-secondary"
              onClick={() => commit('')}
            >
              Uncategorized
            </button>
          )}
          {filtered.map((opt) => (
            <button
              key={opt}
              type="button"
              className="block w-full text-left px-2 py-1.5 text-sm text-text-primary hover:bg-surface-secondary"
              onClick={() => commit(opt)}
            >
              {opt}
            </button>
          ))}
          {showCreateOption && (
            <button
              type="button"
              className="block w-full text-left px-2 py-1.5 text-sm text-desert-green font-medium hover:bg-surface-secondary border-t border-border-subtle"
              onClick={() => commit(query.trim().toLowerCase())}
            >
              + Create "{query.trim().toLowerCase()}"
            </button>
          )}
          {filtered.length === 0 && !showCreateOption && (
            <div className="px-2 py-1.5 text-sm text-text-muted">No matches</div>
          )}
        </div>,
        document.body
      )}
    </div>
  )
}

import { useState } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import StyledModal from '../StyledModal'
import StyledButton from '~/components/StyledButton'
import { useNotifications } from '~/context/NotificationContext'
import api from '~/lib/api'

interface CollectionsManagerProps {
  onClose: () => void
}

export default function CollectionsManager({ onClose }: CollectionsManagerProps) {
  const { addNotification } = useNotifications()
  const queryClient = useQueryClient()
  const [editingName, setEditingName] = useState<string | null>(null)
  const [editValue, setEditValue] = useState('')
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null)

  const { data: collections = [], isLoading } = useQuery({
    queryKey: ['kbCollections'],
    queryFn: () => api.getKnowledgeCollections(),
    select: (data) => data?.collections ?? [],
  })

  const invalidateAll = () => {
    queryClient.invalidateQueries({ queryKey: ['kbCollections'] })
    queryClient.invalidateQueries({ queryKey: ['storedFiles'] })
  }

  const renameMutation = useMutation({
    mutationFn: ({ oldName, newName }: { oldName: string; newName: string }) =>
      api.renameCollection(oldName, newName),
    onSuccess: (data) => {
      addNotification({ type: 'success', message: data?.message || 'Collection renamed.' })
      setEditingName(null)
      invalidateAll()
    },
    onError: (error: any) => {
      addNotification({ type: 'error', message: error?.message || 'Failed to rename collection.' })
    },
  })

  const deleteMutation = useMutation({
    mutationFn: (name: string) => api.deleteCollection(name),
    onSuccess: (data) => {
      addNotification({ type: 'success', message: data?.message || 'Collection removed.' })
      setConfirmDelete(null)
      invalidateAll()
    },
    onError: (error: any) => {
      addNotification({ type: 'error', message: error?.message || 'Failed to remove collection.' })
    },
  })

  return (
    <StyledModal
      open={true}
      title="Manage Collections"
      onClose={onClose}
      cancelText="Close"
      onCancel={onClose}
      large
    >
      <div className="text-left">
        <p className="text-sm text-text-secondary mb-4">
          Rename or remove collections. Removing a collection doesn't delete any files —
          they're simply moved back to Uncategorized so you can re-sort them.
        </p>

        {isLoading && <p className="text-sm text-text-muted">Loading…</p>}
        {!isLoading && collections.length === 0 && (
          <p className="text-sm text-text-muted">
            No collections yet. Assign a file to a collection from the Knowledge Base table to create one.
          </p>
        )}

        <ul className="divide-y divide-border-subtle">
          {collections.map((name) => (
            <li key={name} className="flex items-center justify-between gap-3 py-3">
              {editingName === name ? (
                <>
                  <input
                    autoFocus
                    value={editValue}
                    onChange={(e) => setEditValue(e.target.value)}
                    className="flex-1 rounded border border-border-subtle bg-surface-primary px-2 py-1 text-sm text-text-primary"
                  />
                  <StyledButton
                    variant="primary"
                    icon="IconCheck"
                    loading={renameMutation.isPending}
                    disabled={!editValue.trim() || editValue.trim() === name}
                    onClick={() =>
                      renameMutation.mutate({ oldName: name, newName: editValue.trim() })
                    }
                  >
                    Save
                  </StyledButton>
                  <StyledButton variant="outline" onClick={() => setEditingName(null)}>
                    Cancel
                  </StyledButton>
                </>
              ) : confirmDelete === name ? (
                <>
                  <span className="flex-1 text-sm text-text-primary">
                    Remove "{name}"? Files move to Uncategorized.
                  </span>
                  <StyledButton
                    variant="danger"
                    icon="IconTrash"
                    loading={deleteMutation.isPending}
                    onClick={() => deleteMutation.mutate(name)}
                  >
                    Confirm
                  </StyledButton>
                  <StyledButton variant="outline" onClick={() => setConfirmDelete(null)}>
                    Cancel
                  </StyledButton>
                </>
              ) : (
                <>
                  <span className="flex-1 text-sm text-text-primary">{name}</span>
                  <StyledButton
                    variant="secondary"
                    icon="IconPencil"
                    onClick={() => {
                      setEditingName(name)
                      setEditValue(name)
                    }}
                  >
                    Rename
                  </StyledButton>
                  <StyledButton
                    variant="danger"
                    icon="IconTrash"
                    onClick={() => setConfirmDelete(name)}
                  >
                    Remove
                  </StyledButton>
                </>
              )}
            </li>
          ))}
        </ul>
      </div>
    </StyledModal>
  )
}

import { useState, useCallback, useEffect, useRef } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import ChatSidebar from './ChatSidebar'
import ChatInterface from './ChatInterface'
import KbPolicyPromptBanner from './KbPolicyPromptBanner'
import StyledModal from '../StyledModal'
import api from '~/lib/api'
import { formatBytes } from '~/lib/util'
import { useModals } from '~/context/ModalContext'
import { ChatImageAttachment, ChatMessage } from '../../../types/chat'
import classNames from '~/lib/classNames'
import { IconMenu2, IconX } from '@tabler/icons-react'
import { useSystemSetting } from '~/hooks/useSystemSetting'
import Switch from '~/components/inputs/Switch'
import InfoTooltip from '~/components/InfoTooltip'
import { abortActiveStream, clearStreamIfCurrent } from './stream_abort'

interface ChatProps {
  enabled: boolean
  isInModal?: boolean
  onClose?: () => void
  suggestionsEnabled?: boolean
  streamingEnabled?: boolean
}

export default function Chat({
  enabled,
  isInModal,
  onClose,
  suggestionsEnabled = false,
  streamingEnabled = true,
}: ChatProps) {
  const queryClient = useQueryClient()
  const { openModal, closeAllModals } = useModals()
  const [activeSessionId, setActiveSessionId] = useState<string | null>(null)
  const [messages, setMessages] = useState<ChatMessage[]>([])
  const [selectedModel, setSelectedModel] = useState<string>('')
  const [collectionFilter, setCollectionFilter] = useState<string>('')
  const [pendingModelSwitch, setPendingModelSwitch] = useState<string | null>(null)
  const pageLoadNormalizedRef = useRef(false)
  const [isStreamingResponse, setIsStreamingResponse] = useState(false)
  const [isMobileSidebarOpen, setIsMobileSidebarOpen] = useState(false)
  const streamAbortRef = useRef<AbortController | null>(null)

  const abortCurrentStream = useCallback(() => {
    abortActiveStream(streamAbortRef)
  }, [])

  useEffect(() => () => abortCurrentStream(), [abortCurrentStream])

  useEffect(() => {
    if (!enabled) {
      abortCurrentStream()
      setIsStreamingResponse(false)
    }
  }, [enabled, abortCurrentStream])

  useEffect(() => {
    if (!isMobileSidebarOpen) return
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setIsMobileSidebarOpen(false)
    }
    window.addEventListener('keydown', closeOnEscape)
    return () => window.removeEventListener('keydown', closeOnEscape)
  }, [isMobileSidebarOpen])

  // Fetch all sessions
  const { data: sessions = [] } = useQuery({
    queryKey: ['chatSessions'],
    queryFn: () => api.getChatSessions(),
    enabled,
    select: (data) =>
      data?.map((s) => ({
        id: s.id,
        title: s.title,
        model: s.model || undefined,
        timestamp: new Date(s.timestamp),
        lastMessage: s.lastMessage || undefined,
      })) || [],
  })

  const activeSession = sessions.find((s) => s.id === activeSessionId)

  const { data: lastModelSetting } = useSystemSetting({ key: 'chat.lastModel', enabled })
  const { data: remoteOllamaUrlSetting } = useSystemSetting({ key: 'ai.remoteOllamaUrl', enabled })
  const { data: autoThinkingSetting } = useSystemSetting({ key: 'ai.autoThinking', enabled })
  // Global default for models the user hasn't explicitly toggled. Coerce defensively — KV
  // booleans have historically round-tripped as strings.
  const autoThinkingDefault =
    autoThinkingSetting?.value === true || autoThinkingSetting?.value === 'true'

  // Knowledge base retrieval, shared with AI Assistant settings (same KV key).
  // Unset means on, so coerce off the negative — an absent value must not read
  // as false.
  const { data: ragEnabledSetting } = useSystemSetting({ key: 'rag.enabled', enabled })
  const ragEnabled = !(ragEnabledSetting?.value === false || ragEnabledSetting?.value === 'false')

  const ragEnabledMutation = useMutation({
    mutationFn: async (value: boolean) => await api.updateSetting('rag.enabled', value),
    // Flip the switch immediately rather than after the round-trip, and roll
    // back if the write fails.
    onMutate: async (value: boolean) => {
      await queryClient.cancelQueries({ queryKey: ['system-setting', 'rag.enabled'] })
      const previous = queryClient.getQueryData(['system-setting', 'rag.enabled'])
      queryClient.setQueryData(['system-setting', 'rag.enabled'], {
        key: 'rag.enabled',
        value,
      })
      return { previous }
    },
    onError: (_err, _value, context) => {
      queryClient.setQueryData(['system-setting', 'rag.enabled'], context?.previous)
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ['system-setting', 'rag.enabled'] })
    },
  })

  const { data: remoteStatus } = useQuery({
    queryKey: ['remoteOllamaStatus'],
    queryFn: () => api.getRemoteOllamaStatus(),
    enabled: enabled && !!remoteOllamaUrlSetting?.value,
    refetchInterval: 15000,
  })

  const { data: installedModels = [], isLoading: isLoadingModels } = useQuery({
    queryKey: ['installedModels'],
    queryFn: () => api.getInstalledModels(),
    enabled,
    select: (data) => data || [],
  })

  const { data: knownCollections = [] } = useQuery({
    queryKey: ['kbCollections'],
    queryFn: () => api.getKnowledgeCollections(),
    select: (data) => data?.collections ?? [],
  })

  // Per-model thinking overrides, remembered client-side (localStorage, keyed by model name).
  // An entry here means the user explicitly toggled thinking for that model; absent means fall
  // back to the global default (ai.autoThinking). Seeded from localStorage when models load.
  const [thinkingOverrides, setThinkingOverrides] = useState<Record<string, boolean>>({})
  useEffect(() => {
    const next: Record<string, boolean> = {}
    for (const m of installedModels) {
      try {
        const stored = localStorage.getItem(`nomad:thinking:${m.name}`)
        if (stored !== null) next[m.name] = stored === 'true'
      } catch { }
    }
    setThinkingOverrides(next)
  }, [installedModels])

  const selectedModelSupportsThinking =
    installedModels.find((m) => m.name === selectedModel)?.thinking === true
  const selectedModelVisionCapability =
    installedModels.find((m) => m.name === selectedModel)?.vision ?? 'unknown'

  // Effective thinking preference for a model: explicit override wins, else the global default.
  const effectiveThinking = useCallback(
    (model: string): boolean =>
      model in thinkingOverrides ? thinkingOverrides[model] : autoThinkingDefault,
    [thinkingOverrides, autoThinkingDefault]
  )

  const setModelThinking = useCallback((model: string, value: boolean) => {
    setThinkingOverrides((prev) => ({ ...prev, [model]: value }))
    try {
      localStorage.setItem(`nomad:thinking:${model}`, String(value))
    } catch { }
  }, [])

  const { data: chatSuggestions, isLoading: chatSuggestionsLoading } = useQuery<string[]>({
    queryKey: ['chatSuggestions'],
    queryFn: async ({ signal }) => {
      const res = await api.getChatSuggestions(signal)
      return res ?? []
    },
    enabled: suggestionsEnabled && !activeSessionId,
    refetchOnWindowFocus: false,
    refetchOnMount: false,
  })

  const deleteAllSessionsMutation = useMutation({
    mutationFn: () => api.deleteAllChatSessions(),
    onSuccess: () => {
      abortCurrentStream()
      setIsStreamingResponse(false)
      queryClient.invalidateQueries({ queryKey: ['chatSessions'] })
      setActiveSessionId(null)
      setMessages([])
      closeAllModals()
    },
  })

  const chatMutation = useMutation({
    mutationFn: (request: {
      model: string
      messages: Array<{ role: 'system' | 'user' | 'assistant'; content: string }>
      images?: File[]
      sessionId?: number
      think?: boolean
      collection?: string
    }) => api.sendChatMessage({ ...request, stream: false }),
    onSuccess: async (data) => {
      if (!data || !activeSessionId) {
        throw new Error('No response from Ollama')
      }

      // Add assistant message
      const assistantMessage: ChatMessage = {
        id: `msg-${Date.now()}-assistant`,
        role: 'assistant',
        content: data.message?.content || 'Sorry, I could not generate a response.',
        timestamp: new Date(),
        truncated: data.done_reason === 'length',
      }

      setMessages((prev) => [...prev, assistantMessage])

      // Refresh sessions to pick up backend-persisted messages and title
      queryClient.invalidateQueries({ queryKey: ['chatSessions'] })
      setTimeout(() => queryClient.invalidateQueries({ queryKey: ['chatSessions'] }), 3000)
    },
    onError: (error) => {
      console.error('Error sending message:', error)
      const errorMessage: ChatMessage = {
        id: `msg-${Date.now()}-error`,
        role: 'assistant',
        content: 'Sorry, there was an error processing your request. Please try again.',
        timestamp: new Date(),
      }
      setMessages((prev) => [...prev, errorMessage])
    },
  })

  // Set default model: prefer last used model, fall back to first installed if last model not available
  useEffect(() => {
    if (installedModels.length > 0 && !selectedModel) {
      const lastModel = lastModelSetting?.value as string | undefined
      if (lastModel && installedModels.some((m) => m.name === lastModel)) {
        setSelectedModel(lastModel)
      } else {
        setSelectedModel(installedModels[0].name)
      }
    }
  }, [installedModels, selectedModel, lastModelSetting])

  // Persist model selection
  useEffect(() => {
    if (selectedModel) {
      api.updateSetting('chat.lastModel', selectedModel)
    }
  }, [selectedModel])

  // Page-load normalization: enforce the "one chat model at a time" invariant
  // when the chat page first mounts. Anything stacked from a prior session
  // gets `keep_alive: 0` so it can be evicted; the embedding model is exempt
  // server-side. We wait for `selectedModel` to be populated by the
  // first-installed / lastModel effect so the request has a target to preserve.
  useEffect(() => {
    if (!enabled) return
    if (!selectedModel) return
    if (pageLoadNormalizedRef.current) return
    pageLoadNormalizedRef.current = true
    api.unloadChatModels(selectedModel).catch((err) => {
      console.warn('Failed to normalize loaded models on chat-page mount:', err)
    })
  }, [enabled, selectedModel])

  const handleUserSelectedModel = useCallback(
    (newModel: string) => {
      if (newModel === selectedModel) return
      // No active chat session yet → no conversation to lose, no popup needed.
      // Just update the dropdown silently; the next "New Chat" will use it.
      if (!activeSessionId) {
        setSelectedModel(newModel)
        return
      }
      // Active session: defer the actual model swap until the user confirms.
      // Setting `pendingModelSwitch` drives the dropdown's effective value
      // *and* opens the confirm modal — clearing it on cancel reverts the
      // visible selection without us having to touch `selectedModel`.
      setPendingModelSwitch(newModel)
    },
    [selectedModel, activeSessionId]
  )

  const handleConfirmModelSwitch = useCallback(async () => {
    const newModel = pendingModelSwitch
    if (!newModel) return
    // Best-effort unload of the previously-active chat model. Fire-and-forget:
    // Ollama queues the eviction until the runner is idle, so an in-flight
    // request on the old model finishes cleanly. We don't await this before
    // clearing the session — UI responsiveness wins over housekeeping.
    api.unloadChatModels(newModel).catch((err) => {
      console.warn('Failed to unload previous chat model:', err)
    })
    abortCurrentStream()
    setIsStreamingResponse(false)
    setSelectedModel(newModel)
    setPendingModelSwitch(null)
    // Clear the active session and messages — the next user message will
    // lazily create a new session via the existing handleSendMessage path,
    // which already calls api.createChatSession with `selectedModel`.
    setActiveSessionId(null)
    setMessages([])
  }, [pendingModelSwitch, abortCurrentStream])

  const handleCancelModelSwitch = useCallback(() => {
    setPendingModelSwitch(null)
  }, [])

  const handleNewChat = useCallback(() => {
    // Just clear the active session and messages - don't create a session yet
    abortCurrentStream()
    setIsStreamingResponse(false)
    setActiveSessionId(null)
    setMessages([])
  }, [abortCurrentStream])

  const handleClearHistory = useCallback(() => {
    openModal(
      <StyledModal
        title="Clear All Chat History?"
        onConfirm={() => deleteAllSessionsMutation.mutate()}
        onCancel={closeAllModals}
        open={true}
        confirmText="Clear All"
        cancelText="Cancel"
        confirmVariant="danger"
      >
        <p className="text-text-primary">
          Are you sure you want to delete all chat sessions? This action cannot be undone and all
          conversations will be permanently deleted.
        </p>
      </StyledModal>,
      'confirm-clear-history-modal'
    )
  }, [openModal, closeAllModals, deleteAllSessionsMutation])

  const handleSessionSelect = useCallback(
    async (sessionId: string) => {
      // Cancel any ongoing suggestions fetch
      queryClient.cancelQueries({ queryKey: ['chatSuggestions'] })
      abortCurrentStream()
      setIsStreamingResponse(false)

      setActiveSessionId(sessionId)
      // Load messages for this session
      const sessionData = await api.getChatSession(sessionId)
      if (sessionData?.messages) {
        setMessages(
          sessionData.messages.map((m) => ({
            id: m.id,
            role: m.role,
            content: m.content,
            timestamp: new Date(m.timestamp),
            sources: m.sources,
          }))
        )
      } else {
        setMessages([])
      }

      // Set the model to match the session's model if it exists and is available
      if (sessionData?.model) {
        setSelectedModel(sessionData.model)
      }

      // Enforce the one-chat-model-at-a-time invariant: ask the backend to
      // unload anything that isn't the target session's model. Fire-and-forget;
      // this is housekeeping. Note we pass the *session's* model here rather
      // than reading `selectedModel`, because setSelectedModel above is async
      // and the effect-driven page-load normalize wouldn't catch a sidebar
      // click after the first render.
      const targetModel = sessionData?.model ?? selectedModel ?? null
      api.unloadChatModels(targetModel).catch((err) => {
        console.warn('Failed to unload non-target chat models on session switch:', err)
      })
    },
    [installedModels, queryClient, selectedModel, abortCurrentStream]
  )

  const handleSendMessage = useCallback(
    async (content: string, images: ChatImageAttachment[] = []) => {
      let sessionId = activeSessionId

      // Render the user's message before anything can await (#1211). Creating the
      // session used to come first, so on a slow or stalled request the message the
      // user just sent simply did not appear, with no spinner and nothing to retry.
      const userMessage: ChatMessage = {
        id: `msg-${Date.now()}`,
        role: 'user',
        content,
        images,
        timestamp: new Date(),
      }

      setMessages((prev) => [...prev, userMessage])

      // Create a new session if none exists
      if (!sessionId) {
        let newSession: Awaited<ReturnType<typeof api.createChatSession>> | undefined
        try {
          newSession = await api.createChatSession('New Chat', selectedModel)
        } catch {
          newSession = undefined
        }

        if (!newSession) {
          // Previously a bare `return`: the message was never rendered and no error
          // was shown either, so a failed session creation looked like the app
          // ignoring the user. Surface it the same way a failed response is surfaced.
          setMessages((prev) => [
            ...prev,
            {
              id: `msg-${Date.now()}-error`,
              role: 'assistant',
              content: 'Sorry, there was an error starting this chat. Please try again.',
              timestamp: new Date(),
            },
          ])
          return
        }

        sessionId = newSession.id
        setActiveSessionId(sessionId)
        queryClient.invalidateQueries({ queryKey: ['chatSessions'] })
      }

      const chatMessages = [
        ...messages.map((m) => ({ role: m.role, content: m.content })),
        { role: 'user' as const, content },
      ]

      abortCurrentStream()

      if (streamingEnabled !== false) {
        // Streaming path
        const abortController = new AbortController()
        streamAbortRef.current = abortController

        setIsStreamingResponse(true)

        const assistantMsgId = `msg-${Date.now()}-assistant`
        let isFirstChunk = true
        let fullContent = ''
        let thinkingContent = ''
        let isThinkingPhase = true
        let thinkingStartTime: number | null = null
        let thinkingDuration: number | null = null

        try {
          await api.streamChatMessage(
            {
              model: selectedModel || 'llama3.2',
              messages: chatMessages,
              stream: true,
              sessionId: sessionId ? Number(sessionId) : undefined, think: effectiveThinking(selectedModel),
              collection: collectionFilter || undefined,
              images: images.map((image) => image.file),
            },
            (chunkContent, chunkThinking, done) => {
              if (chunkThinking.length > 0 && thinkingStartTime === null) {
                thinkingStartTime = Date.now()
              }
              if (isFirstChunk) {
                isFirstChunk = false
                setIsStreamingResponse(false)
                setMessages((prev) => [
                  ...prev,
                  {
                    id: assistantMsgId,
                    role: 'assistant',
                    content: chunkContent,
                    thinking: chunkThinking,
                    timestamp: new Date(),
                    isStreaming: true,
                    isThinking: chunkThinking.length > 0 && chunkContent.length === 0,
                    thinkingDuration: undefined,
                  },
                ])
              } else {
                if (isThinkingPhase && chunkContent.length > 0) {
                  isThinkingPhase = false
                  if (thinkingStartTime !== null) {
                    thinkingDuration = Math.max(
                      1,
                      Math.round((Date.now() - thinkingStartTime) / 1000)
                    )
                  }
                }
                setMessages((prev) =>
                  prev.map((m) =>
                    m.id === assistantMsgId
                      ? {
                        ...m,
                        content: m.content + chunkContent,
                        thinking: (m.thinking ?? '') + chunkThinking,
                        isStreaming: !done,
                        isThinking: isThinkingPhase,
                        thinkingDuration: thinkingDuration ?? undefined,
                      }
                      : m
                  )
                )
              }
              fullContent += chunkContent
              thinkingContent += chunkThinking
            },
            abortController.signal,
            (sources) => {
              setMessages((prev) =>
                prev.map((m) => (m.id === assistantMsgId ? { ...m, sources } : m))
              )
            },
            (reason) => {
              if (reason !== 'length') return
              setMessages((prev) =>
                prev.map((m) => (m.id === assistantMsgId ? { ...m, truncated: true } : m))
              )
            }
          )
        } catch (error: any) {
          if (error?.name !== 'AbortError') {
            setMessages((prev) => {
              const hasAssistantMsg = prev.some((m) => m.id === assistantMsgId)
              if (hasAssistantMsg) {
                return prev.map((m) => (m.id === assistantMsgId ? { ...m, isStreaming: false } : m))
              }
              return [
                ...prev,
                {
                  id: assistantMsgId,
                  role: 'assistant',
                  content:
                    error instanceof Error
                      ? error.message
                      : 'Sorry, there was an error processing your request. Please try again.',
                  timestamp: new Date(),
                },
              ]
            })
          }
        } finally {
          if (clearStreamIfCurrent(streamAbortRef, abortController)) {
            setIsStreamingResponse(false)
          }
        }

        if (fullContent && sessionId) {
          // Ensure the streaming cursor is removed
          setMessages((prev) =>
            prev.map((m) => (m.id === assistantMsgId ? { ...m, isStreaming: false } : m))
          )

          // Refresh sessions to pick up backend-persisted messages and title
          queryClient.invalidateQueries({ queryKey: ['chatSessions'] })
          setTimeout(() => queryClient.invalidateQueries({ queryKey: ['chatSessions'] }), 3000)
        }
      } else {
        // Non-streaming (legacy) path
        chatMutation.mutate({
          model: selectedModel || 'llama3.2',
          messages: chatMessages,
          sessionId: sessionId ? Number(sessionId) : undefined,
          think: effectiveThinking(selectedModel),
          collection: collectionFilter || undefined,
          images: images.map((image) => image.file),
        })
      }
    },
    [activeSessionId, messages, selectedModel, collectionFilter, chatMutation, queryClient, streamingEnabled, effectiveThinking, abortCurrentStream]
  )

  return (
    <>
      {pendingModelSwitch && (
        <StyledModal
          title={`Switch to ${pendingModelSwitch}?`}
          onConfirm={handleConfirmModelSwitch}
          onCancel={handleCancelModelSwitch}
          open={true}
          confirmText="Switch & New Chat"
          cancelText="Cancel"
          confirmVariant="primary"
        >
          <p className="text-text-primary">
            Switching to <strong>{pendingModelSwitch}</strong> will start a new chat. Your current
            conversation stays available in the sidebar.
          </p>
        </StyledModal>
      )}
      <div
        className={classNames(
          'flex border border-border-subtle overflow-hidden shadow-sm w-full',
          isInModal ? 'h-full rounded-lg' : 'h-screen'
        )}
      >
        <ChatSidebar
          sessions={sessions}
          activeSessionId={activeSessionId}
          onSessionSelect={handleSessionSelect}
          onNewChat={handleNewChat}
          onClearHistory={handleClearHistory}
          isInModal={isInModal}
          isMobileOpen={isMobileSidebarOpen}
          onMobileClose={() => setIsMobileSidebarOpen(false)}
        />
        {isMobileSidebarOpen && (
          <button
            type="button"
            aria-label="Close conversation sidebar"
            className="fixed inset-0 z-40 bg-black/40 md:hidden"
            onClick={() => setIsMobileSidebarOpen(false)}
          />
        )}
        <div className="flex-1 flex flex-col min-h-0 min-w-0">
          <KbPolicyPromptBanner />
          <div className="px-3 sm:px-6 py-3 border-b border-border-subtle bg-surface-secondary flex flex-wrap items-center justify-between gap-2 min-h-[75px] flex-shrink-0">
            <div className="flex items-center gap-2 min-w-0">
              <button
                type="button"
                className="rounded-lg p-1.5 hover:bg-surface-primary focus:outline-none focus:ring-2 focus:ring-desert-green md:hidden"
                aria-label="Open conversation sidebar"
                aria-controls="chat-sidebar"
                aria-expanded={isMobileSidebarOpen}
                onClick={() => setIsMobileSidebarOpen(true)}
              >
                <IconMenu2 className="h-6 w-6 text-text-muted" aria-hidden="true" />
              </button>
              <h2 className="text-lg font-semibold text-text-primary truncate">
                {activeSession?.title || 'New Chat'}
              </h2>
            </div>
            <div className="flex items-center gap-2 sm:gap-4 min-w-0">
              {remoteOllamaUrlSetting?.value && (
                <span
                  className={classNames(
                    'text-xs rounded px-2 py-1 font-medium',
                    remoteStatus?.connected === false
                      ? 'text-red-700 bg-red-50 border border-red-200'
                      : 'text-green-700 bg-green-50 border border-green-200'
                  )}
                >
                  {remoteStatus?.connected === false ? 'Remote Disconnected' : 'Remote Connected'}
                </span>
              )}
              {ragEnabled && (
                <div className="flex items-center gap-2">
                  <label htmlFor="collection-select" className="text-sm text-text-secondary">
                    Search in:
                  </label>
                  <select
                    id="collection-select"
                    value={collectionFilter}
                    onChange={(e) => setCollectionFilter(e.target.value)}
                    className="px-3 py-1.5 border border-border-default rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-desert-green focus:border-transparent bg-surface-primary"
                  >
                    <option value="">All</option>
                    {knownCollections.map((c) => (
                      <option key={c} value={c}>{c}</option>
                    ))}
                  </select>
                </div>
              )}
              <div className="flex items-center gap-2 min-w-0">
                <label htmlFor="model-select" className="text-sm text-text-secondary">
                  Model:
                </label>
                {isLoadingModels ? (
                  <div className="text-sm text-text-muted">Loading models...</div>
                ) : installedModels.length === 0 ? (
                  <div className="text-sm text-red-600">No models installed</div>
                ) : (
                  <select
                    id="model-select"
                    value={pendingModelSwitch ?? selectedModel}
                    onChange={(e) => handleUserSelectedModel(e.target.value)}
                    className="min-w-0 max-w-44 sm:max-w-none px-2 sm:px-3 py-1.5 border border-border-default rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-desert-green focus:border-transparent bg-surface-primary"
                  >
                    {installedModels.map((model) => (
                      <option key={model.name} value={model.name}>
                        {model.name}
                        {model.size > 0 ? ` (${formatBytes(model.size)})` : ''}
                      </option>
                    ))}
                  </select>
                )}
              </div>
              <div className="flex items-center">
                <span className="text-sm text-text-secondary select-none">Knowledge Base:</span>
                <InfoTooltip
                  position="bottom"
                  align="right"
                  text="When on, the assistant searches your knowledge base for relevant documents before answering. Turning this off is faster and lighter on hardware, which helps when your knowledge base is small or empty. This is the same setting as in AI Assistant settings."
                />
                <Switch
                  id="chat-rag-toggle"
                  checked={ragEnabled}
                  onChange={(v) => ragEnabledMutation.mutate(v)}
                />
              </div>
              {selectedModelSupportsThinking && (
                <div className="flex items-center">
                  <span className="text-sm text-text-secondary select-none">Thinking:</span>
                  <InfoTooltip
                    position="bottom"
                    align="right"
                    text="When on, this model works through its reasoning before answering. Slower, but often better on tricky questions. Your choice is remembered for this model; the default for other models is set in AI Assistant settings."
                  />
                  <Switch
                    id="chat-thinking-toggle"
                    checked={effectiveThinking(selectedModel)}
                    onChange={(v) => setModelThinking(selectedModel, v)}
                  />
                </div>
              )}
              {isInModal && (
                <button
                  type="button"
                  aria-label="Close chat"
                  onClick={() => {
                    if (onClose) {
                      onClose()
                    }
                  }}
                  className="rounded-lg hover:bg-surface-secondary transition-colors"
                >
                  <IconX className="h-6 w-6 text-text-muted" aria-hidden="true" />
                </button>
              )}
            </div>
          </div>
          <ChatInterface
            messages={messages}
            onSendMessage={handleSendMessage}
            visionCapability={selectedModelVisionCapability}
            isLoading={isStreamingResponse || chatMutation.isPending}
            chatSuggestions={chatSuggestions}
            chatSuggestionsEnabled={suggestionsEnabled}
            chatSuggestionsLoading={chatSuggestionsLoading}
          />
        </div>
      </div>
    </>
  )
}

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { usePage } from '@inertiajs/react'
import { IconBrain } from '@tabler/icons-react'
import api from '~/lib/api'
import StyledButton from '~/components/StyledButton'
import { useNotifications } from '~/context/NotificationContext'

/**
 * First-chat onboarding banner (RFC #883 Phase 3 task 12).
 *
 * Renders above the chat header when the scanner has seen at least one
 * embeddable file AND the user has not yet picked a global ingest policy
 * (`rag.defaultIngestPolicy` unset). Two buttons let the user decide once,
 * after which the prompt never returns:
 *
 *   - "Index existing content" → sets policy=Always and dispatches a sync so
 *     anything already on disk + in `pending_decision` gets queued for embed.
 *   - "Maybe later"            → sets policy=Manual. New content waits in
 *     `pending_decision` until the user opts in from the KB modal.
 *
 * The "dismiss without deciding" X is intentionally NOT here. Dismissing
 * without setting policy would make the banner reappear on every visit until
 * a choice is recorded — annoying. The two action buttons each set policy,
 * and the user can change their mind any time via the Always/Manual radio in
 * the KB modal.
 */
export default function KbPolicyPromptBanner() {
  const queryClient = useQueryClient()
  const { addNotification } = useNotifications()
  // Inertia injects `aiAssistantName` as a shared page prop on chat-mounted
  // pages so the banner pulls the user-set name when surfaced. Default to
  // "AI Assistant" when accessed outside that context (no-op for chat pages,
  // but keeps the component safe for future reuse elsewhere).
  const aiAssistantName =
    usePage<{ aiAssistantName?: string }>().props?.aiAssistantName || 'AI Assistant'

  const { data: promptState } = useQuery({
    queryKey: ['kbPolicyPromptState'],
    queryFn: () => api.getKbPolicyPromptState(),
    staleTime: Infinity,
  })

  const indexNowMutation = useMutation({
    mutationFn: async () => {
      await api.updateSetting('rag.defaultIngestPolicy', 'Always')
      await api.syncRAGStorage()
    },
    onSuccess: () => {
      addNotification({
        type: 'success',
        message: `${aiAssistantName} will index your existing content. You can track progress in the Knowledge Base panel.`,
      })
      queryClient.invalidateQueries({ queryKey: ['kbPolicyPromptState'] })
      queryClient.invalidateQueries({ queryKey: ['ingestPolicy'] })
      queryClient.invalidateQueries({ queryKey: ['embed-jobs'] })
      queryClient.invalidateQueries({ queryKey: ['storedFiles'] })
    },
    onError: (error: any) => {
      addNotification({
        type: 'error',
        message: error?.message || 'Could not start indexing. Try again from the Knowledge Base panel.',
      })
    },
  })

  const maybeLaterMutation = useMutation({
    mutationFn: () => api.updateSetting('rag.defaultIngestPolicy', 'Manual'),
    onSuccess: () => {
      addNotification({
        type: 'success',
        message: 'Your content stays unindexed for now. You can opt in any time from the Knowledge Base panel.',
      })
      queryClient.invalidateQueries({ queryKey: ['kbPolicyPromptState'] })
      queryClient.invalidateQueries({ queryKey: ['ingestPolicy'] })
    },
    onError: (error: any) => {
      addNotification({
        type: 'error',
        message: error?.message || 'Could not save your choice. Try again.',
      })
    },
  })

  if (!promptState?.shouldPrompt) return null

  const fileCount = promptState.totalFiles
  const isBusy = indexNowMutation.isPending || maybeLaterMutation.isPending

  return (
    <div className="px-6 py-3 bg-blue-50 dark:bg-blue-950/30 border-b border-blue-200 dark:border-blue-800 flex-shrink-0">
      <div className="flex items-center gap-3">
        <IconBrain className="h-6 w-6 text-blue-600 dark:text-blue-300 flex-shrink-0" />
        <div className="flex-1 min-w-0">
          <p className="text-sm text-text-primary">
            <strong>
              {fileCount === 1
                ? `Index your existing file for ${aiAssistantName}?`
                : `Index your ${fileCount.toLocaleString()} existing files for ${aiAssistantName}?`}
            </strong>
            {' '}When indexed, {aiAssistantName} can reference them while answering your questions.
          </p>
        </div>
        <div className="flex gap-2 flex-shrink-0">
          <StyledButton
            onClick={() => indexNowMutation.mutate()}
            variant="primary"
            size="sm"
            disabled={isBusy}
            loading={indexNowMutation.isPending}
          >
            Index existing content
          </StyledButton>
          <StyledButton
            onClick={() => maybeLaterMutation.mutate()}
            variant="ghost"
            size="sm"
            disabled={isBusy}
            loading={maybeLaterMutation.isPending}
          >
            Maybe later
          </StyledButton>
        </div>
      </div>
    </div>
  )
}

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { useEffect, useMemo, useRef, useState } from 'react'
import FileUploader from '~/components/file-uploader'
import StyledButton from '~/components/StyledButton'
import type { DynamicIconName } from '~/lib/icons'
import StyledSectionHeader from '~/components/StyledSectionHeader'
import StyledTable from '~/components/StyledTable'
import { useNotifications } from '~/context/NotificationContext'
import api from '~/lib/api'
import {
  groupAndSortKbFiles,
  UNCATEGORIZED_COLLECTION_KEY,
  type KbFileGroup,
  type KbFileSort,
  type KbFileSortKey,
} from '~/lib/kb_file_grouping'
import type { KbIngestStateValue } from '../../../types/kb_ingest_state'
import { formatBytes } from '~/lib/util'
import {
  IconArrowsSort,
  IconChevronDown,
  IconChevronRight,
  IconDownload,
  IconEye,
  IconSortAscending,
  IconSortDescending,
