export const CREATOR_PACKS_KEY = 'creator-packs'

/**
 * Shared, cached source of Creator Packs state for every surface (Content
 * Explorer block, settings page, settings nav gate, Easy Setup wizard step).
 *
 * `configured` reflects whether this build carries the release-injected app key.
 * When false (forks / key unset) the surfaces HIDE themselves — the catalog is
 * public so packs would otherwise list with install buttons that only 503.
 *
 * Polls while a pack download is in flight so the card status flips promptly;
 * otherwise refetches lazily.
 */
const useCreatorPacks = (enabled = true) => {
  const queryClient = useQueryClient()

  const queryData = useQuery({
    queryKey: [CREATOR_PACKS_KEY],
    queryFn: () => api.getCreatorPacks(),
    refetchInterval: (query) => {
      const anyDownloading = query.state.data?.packs?.some((p) => p.status === 'downloading')
      return anyDownloading ? 2000 : false
    },
    refetchOnWindowFocus: false,
    staleTime: 60_000,
    enabled,
  })

  const invalidate = () => {
    queryClient.invalidateQueries({ queryKey: [CREATOR_PACKS_KEY] })
  }

  return {
    ...queryData,
    configured: queryData.data?.configured ?? false,
    packs: queryData.data?.packs ?? [],
    downloads: queryData.data?.downloads ?? [],
    invalidate,
  }
}

export default useCreatorPacks

import { useRef, useEffect } from "react";

const useDebounce = () => {
  const timeout = useRef<number | undefined>(400);

  const debounce =
    (func: Function, wait: number = 0) =>
    (...args: any[]) => {
      clearTimeout(timeout.current);
      timeout.current = window.setTimeout(() => func(...args), wait);
    };

  useEffect(() => {
    return () => {
      if (!timeout.current) return;
      clearTimeout(timeout.current);
    };
  }, []);

  return { debounce };
};

export default useDebounce;

import { NomadDiskInfo } from '../../types/system'
import { Systeminformation } from 'systeminformation'
import { formatBytes } from '~/lib/util'

type DiskDisplayItem = {
  label: string
  value: number
  total: string
  used: string
  subtext: string
  totalBytes: number
  usedBytes: number
}

/** Get all valid disks formatted for display (settings/system page) */
export function getAllDiskDisplayItems(
  disks: NomadDiskInfo[] | undefined,
  fsSize: Systeminformation.FsSizeData[] | undefined
): DiskDisplayItem[] {
  const validDisks = disks?.filter((d) => d.totalSize > 0) || []

  // If /app/storage is backed by a network filesystem (NFS/CIFS), it won't
  // appear in the block-device list. Prepend it so NAS and OS disk are both
  // shown. Local-disk-backed /app/storage is already reported in disk[] and
  // fsSize[], so skip it here to avoid a phantom "NAS Storage" entry.
  const NETWORK_FS_TYPES = new Set(['nfs', 'nfs4', 'cifs', 'smbfs', 'smb2', 'smb3'])
  const storageMount = fsSize?.find(
    (fs) =>
      fs.mount === '/app/storage' && fs.size > 0 && NETWORK_FS_TYPES.has(fs.type?.toLowerCase())
  )
  const storageMountItem: DiskDisplayItem[] = storageMount
    ? [
        {
          label: 'NAS Storage',
          value: storageMount.use || 0,
          total: formatBytes(storageMount.size),
          used: formatBytes(storageMount.used),
          subtext: `${formatBytes(storageMount.used)} / ${formatBytes(storageMount.size)}`,
          totalBytes: storageMount.size,
          usedBytes: storageMount.used,
        },
      ]
    : []

  if (validDisks.length > 0) {
    return [
      ...storageMountItem,
      ...validDisks.map((disk) => ({
        label: disk.name || 'Unknown',
        value: disk.percentUsed || 0,
        total: formatBytes(disk.totalSize),
        used: formatBytes(disk.totalUsed),
        subtext: `${formatBytes(disk.totalUsed || 0)} / ${formatBytes(disk.totalSize || 0)}`,
        totalBytes: disk.totalSize,
        usedBytes: disk.totalUsed,
      })),
    ]
  }

  if (fsSize && fsSize.length > 0) {
    const seen = new Set<number>()
    const uniqueFs = fsSize.filter((fs) => {
      if (fs.size <= 0 || seen.has(fs.size)) return false
      if (storageMount && fs.mount === '/app/storage') return false
      seen.add(fs.size)
      return true
    })
    const realDevices = uniqueFs.filter((fs) => fs.fs.startsWith('/dev/'))
    const displayFs = realDevices.length > 0 ? realDevices : uniqueFs
    return [
      ...storageMountItem,
      ...displayFs.map((fs) => ({
        label: fs.fs || 'Unknown',
        value: fs.use || 0,
        total: formatBytes(fs.size),
        used: formatBytes(fs.used),
        subtext: `${formatBytes(fs.used)} / ${formatBytes(fs.size)}`,
        totalBytes: fs.size,
        usedBytes: fs.used,
      })),
    ]
  }

  return []
}

/** Get primary disk info for storage projection (easy-setup page) */
export function getPrimaryDiskInfo(
  disks: NomadDiskInfo[] | undefined,
  fsSize: Systeminformation.FsSizeData[] | undefined
): { totalSize: number; totalUsed: number } | null {
  // First, check if /app/storage is on a dedicated filesystem (e.g. NFS mount).
  // This is the most accurate source since it reflects the actual backing
  // store for NOMAD content, regardless of whether it's a local disk or
  // network-attached storage.
  const storageMount = fsSize?.find((fs) => fs.mount === '/app/storage' && fs.size > 0)
  if (storageMount) {
    return { totalSize: storageMount.size, totalUsed: storageMount.used }
  }

  const validDisks = disks?.filter((d) => d.totalSize > 0) || []
  if (validDisks.length > 0) {
    const diskWithRoot = validDisks.find((d) =>
      d.filesystems?.some((fs) => fs.mount === '/' || fs.mount === '/storage')
    )
    const primary =
      diskWithRoot || validDisks.reduce((a, b) => (b.totalSize > a.totalSize ? b : a))
    return { totalSize: primary.totalSize, totalUsed: primary.totalUsed }
  }

  if (fsSize && fsSize.length > 0) {
    const realDevices = fsSize.filter((fs) => fs.fs.startsWith('/dev/'))
    const primary =
      realDevices.length > 0
        ? realDevices.reduce((a, b) => (b.size > a.size ? b : a))
        : fsSize[0]
    return { totalSize: primary.size, totalUsed: primary.used }
  }

  return null
}

import { useQuery, useQueryClient } from '@tanstack/react-query'
import { useMemo } from 'react'
import api from '~/lib/api'

export type useDownloadsProps = {
  filetype?: string
  enabled?: boolean
}

const useDownloads = (props: useDownloadsProps) => {
  const queryClient = useQueryClient()

  const queryKey = useMemo(() => {
    return props.filetype ? ['download-jobs', props.filetype] : ['download-jobs']
  }, [props.filetype])

  const queryData = useQuery({
    queryKey: queryKey,
    queryFn: () => api.listDownloadJobs(props.filetype),
    refetchInterval: (query) => {
      const data = query.state.data
      // Idle poll is kept tight so newly-dispatched jobs surface quickly — small ZIM
      // updates can complete in ~2s, so a 30s idle interval almost always missed them.
      return data && data.length > 0 ? 2000 : 3000
    },
    enabled: props.enabled ?? true,
  })

  const invalidate = () => {
    queryClient.invalidateQueries({ queryKey: queryKey })
  }

  return { ...queryData, invalidate }
}

export default useDownloads

import { useEffect, useRef } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import api from '~/lib/api'

const useEmbedJobs = (props: { enabled?: boolean } = {}) => {
  const queryClient = useQueryClient()
  const prevCountRef = useRef<number>(0)

  const queryData = useQuery({
    queryKey: ['embed-jobs'],
    queryFn: () => api.getActiveEmbedJobs().then((data) => data ?? []),
    refetchInterval: (query) => {
      const data = query.state.data
      // Only poll when there are active jobs; otherwise use a slower interval
      return data && data.length > 0 ? 2000 : 30000
    },
    enabled: props.enabled ?? true,
  })

  // When jobs drain to zero, refresh stored files so they appear without reopening the modal
  useEffect(() => {
    const currentCount = queryData.data?.length ?? 0
    if (prevCountRef.current > 0 && currentCount === 0) {
      queryClient.invalidateQueries({ queryKey: ['storedFiles'] })
    }
    prevCountRef.current = currentCount
  }, [queryData.data, queryClient])

  const invalidate = () => {
    queryClient.invalidateQueries({ queryKey: ['embed-jobs'] })
  }

  return { ...queryData, invalidate }
}

export default useEmbedJobs

