              </span>
            )}
          </div>

          {label.brand_name && label.generic_name && (
            <p className="text-base text-text-secondary italic">{label.generic_name}</p>
          )}

          <dl className="mt-3 grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-1 text-sm">
