import logger from '@adonisjs/core/services/logger'
import type { ApplicationService } from '@adonisjs/core/types'
import type { ZimCategoriesSpec } from '../types/collections.js'

/**
 * Backfills the FDA drug dataset's `installed_resources` row when a completed
 * ingest has none.
 *
 * On 1.34.0 `installed_resources.resource_type` was still enum('zim','map'), so
 * every drug ingest landed its 261k labels, reported `ready`, and lost the
 * 'dataset' row write. The migration that widens the enum can't recreate the
 * row, and re-selecting the tier won't either (ZimService skips a dataset that
 * already has rows), so Medicine stayed stuck below its Standard tier. Manual
 * ingests and reset-and-reingest runs dispatch without resourceMeta and end in
 * the same state.
 *
 * Runs once per admin boot. The decision lives in decideDrugRowReconcile(); once
 * the row exists every later boot is a single skip.
 */
export default class DrugInstallRowProvider {
  constructor(protected app: ApplicationService) {}

  async boot() {
    if (this.app.getEnvironment() !== 'web') return

    setImmediate(async () => {
      try {
        const KVStore = (await import('#models/kv_store')).default
        const { DrugReferenceService, DRUG_DATASET_RESOURCE_ID } = await import(
          '#services/drug_reference_service'
        )
        const { CollectionManifestService } = await import(
          '#services/collection_manifest_service'
        )
        const { parseDownloadState } = await import('../util/drug_labels.js')
        const { decideDrugRowReconcile, findDatasetCategorySlug } = await import(
          '../app/utils/drug_install_row_reconcile.js'
        )

        const drugService = new DrugReferenceService()

        // Redis down reads as "in flight": leaving the tier stuck one more boot
        // beats racing a live ingest.
        let jobInFlight = true
        try {
          jobInFlight = await drugService.isJobInFlight()
        } catch (err: any) {
          logger.warn(
            `[DrugInstallRowProvider] Could not read drug queues (${err?.message ?? err}) — treating as in flight.`
          )
        }

        const [rowCount, hasInstallRow, lastUpdated, rawMarker] = await Promise.all([
          drugService.rowCount(),
          drugService.hasInstalledRow(),
          KVStore.getValue('drugReference.lastUpdatedExportDate'),
          KVStore.getValue('drugReference.downloadState'),
        ])

        const decision = decideDrugRowReconcile({
          rowCount,
          hasInstallRow,
          lastUpdatedExportDate: lastUpdated ? String(lastUpdated) : null,
          hasDownloadMarker: parseDownloadState(rawMarker) !== null,
          jobInFlight,
        })

        if (decision.action === 'skip') {
          logger.info(`[DrugInstallRowProvider] No backfill needed: ${decision.reason}.`)
          return
        }

        // Cached spec only: no network at boot, and the box may be offline.
        const spec = await new CollectionManifestService().getCachedSpec<ZimCategoriesSpec>('zim_categories')
        const collectionRef = findDatasetCategorySlug(spec, DRUG_DATASET_RESOURCE_ID)

        await drugService.recordInstalledRow({
          version: decision.version,
          collectionRef,
          fileSizeBytes: null,
        })
        logger.warn(
          `[DrugInstallRowProvider] ${rowCount} drug labels were ingested without an installed_resources row. ` +
            `Backfilled ${DRUG_DATASET_RESOURCE_ID} (version=${decision.version}, collection_ref=${collectionRef ?? 'null'}).`
        )
      } catch (err: any) {
        logger.error(`[DrugInstallRowProvider] Backfill check failed: ${err?.message ?? err}`)
      }
    })
  }
}

import logger from '@adonisjs/core/services/logger'
import type { ApplicationService } from '@adonisjs/core/types'

/**
 * Detects Ollama's silent CPU fallback after admin / host restart, and auto-remediates
 * it on NVIDIA.
 *
 * Detects the condition from Ollama's own "inference compute" startup log line:
 * if Ollama is expected on a GPU (see resolveExpectedGpuVendor) but loaded a CPU-only
 * backend, passthrough is broken. On NVIDIA, nomad_ollama is recreated.
 * This single signal covers two NVIDIA failure modes:
 *   1. nomad_ollama was created CPU-only because the nvidia runtime was registered
 *      only AFTER the AI Assistant was first installed (DockerService attaches a
 *      GPU DeviceRequest only when 'nvidia' is in docker.info().Runtimes at install
 *      time). Common on a host where the runtime was added later.
 *   2. After an update or container recreate, DeviceRequests still lists the nvidia
 *      driver but the toolkit binding inside the container is torn, and Ollama
 *      silently falls back to CPU.
 *
 * PR #208 added detection + a one-click "Fix: Reinstall AI Assistant" banner; this
 * provider performs that click automatically on admin boot.
 *
 * AMD is detect-only. The usual cause there is a missing HSA override for an iGPU
 * outside ROCm's allowlist (e.g. gfx1103), which a reinstall rebuilds unchanged. The
 * provider logs whether a reinstall would change the container and leaves the
 * reinstall to the user; SystemService surfaces the same state as passthrough_failed.
 *
 * Guards:
 *   - One-shot per admin boot. The provider runs once on startup; if the recreate
 *     itself fails the banner remains as a fallback.
 *   - Cooldown: will not auto-reinstall more than once within
 *     AUTO_REMEDIATE_COOLDOWN_MS, to avoid a reinstall loop when the GPU cannot be
 *     accelerated (e.g. an architecture Ollama has no kernels for).
 *   - Opt-out via KV `ai.autoFixGpuPassthrough = false`.
 *   - Skipped entirely when nomad_ollama is not expected on a GPU.
 */
export default class GpuPassthroughRemediationProvider {
  constructor(protected app: ApplicationService) {}

  async boot() {
    if (this.app.getEnvironment() !== 'web') return

    setImmediate(async () => {
      try {
        const KVStore = (await import('#models/kv_store')).default
        const { DockerService } = await import('#services/docker_service')
        const { SERVICE_NAMES } = await import('../constants/service_names.js')
        const Docker = (await import('dockerode')).default

        const enabledRaw = await KVStore.getValue('ai.autoFixGpuPassthrough')
        if (String(enabledRaw) === 'false') {
          logger.info(
            '[GpuPassthroughRemediationProvider] Auto-fix disabled via KV — skipping.'
          )
          return
        }

        const docker = new Docker({ socketPath: '/var/run/docker.sock' })
        const dockerInfo = await docker.info()
        const runtimes = dockerInfo.Runtimes || {}

        const containers = await docker.listContainers({ all: false })
        const ollama = containers.find((c) => c.Names.includes(`/${SERVICE_NAMES.OLLAMA}`))

        if (!ollama) {
          logger.info(
            '[GpuPassthroughRemediationProvider] nomad_ollama not running — skipping.'
          )
          return
        }

        const container = docker.getContainer(ollama.Id)
        const inspect = await container.inspect()
        const {
          classifyOllamaComputeBackend,
          diffAmdOllamaConfig,
          readOllamaStartupLogs,
          resolveExpectedGpuVendor,
        } = await import('#services/ollama_compute')

        // The container's own GPU config decides the vendor. The KV AMD type only
        // matters when no container exists, which the return above rules out.
        const vendor = resolveExpectedGpuVendor({
          hasNvidiaRuntime: 'nvidia' in runtimes,
          amdConfigured: false,
          container: inspect,
        })

        if (!vendor) {
          logger.info(
            '[GpuPassthroughRemediationProvider] nomad_ollama is not configured for a GPU — skipping.'
          )
          return
        }

        // Probe: read Ollama's own "inference compute" startup line from its logs.
        // This is the ground truth for whether Ollama loaded a GPU backend, and it
        // catches every failure mode:
        //   - nomad_ollama created CPU-only because the nvidia runtime was registered
        //     only AFTER first install (Ollama logs library=cpu), and
        //   - DeviceRequests present but the toolkit binding tore after a recreate,
        //     where Ollama silently falls back to CPU (also library=cpu), and
        //   - a ROCm container on an AMD GPU that ROCm could not initialize.
        // The previous implementation probed by exec'ing `nvidia-smi` inside the
        // container, but a CPU-only container does not ship nvidia-smi, so the exec
        // returned an error string that the alphabetic-output check mistook for
        // "healthy" — a false negative that suppressed all auto-remediation.
        const backend = classifyOllamaComputeBackend(await readOllamaStartupLogs(container, inspect))

        if (backend === 'gpu') {
          logger.info(
            '[GpuPassthroughRemediationProvider] Ollama is using a GPU backend — no action needed.'
          )
          return
        }

        if (backend === 'unknown') {
          logger.info(
            '[GpuPassthroughRemediationProvider] No "inference compute" line found in nomad_ollama logs yet — skipping.'
          )
          return
        }

        if (vendor === 'amd') {
          const amdEnabledRaw = await KVStore.getValue('ai.amdGpuAcceleration')
          if (String(amdEnabledRaw) === 'false') {
            logger.info(
              '[GpuPassthroughRemediationProvider] Ollama is on CPU and AMD acceleration is disabled via ai.amdGpuAcceleration — skipping.'
            )
            return
          }

          const hsaOverride = await new DockerService().getAmdHsaOverride()
          const drift = diffAmdOllamaConfig(inspect, hsaOverride)
          if (drift.length > 0) {
            logger.warn(
              '[GpuPassthroughRemediationProvider] AMD GPU configured but Ollama fell back to CPU. ' +
                `A reinstall would change the container (${drift.join('; ')}). ` +
                'Use "Fix: Reinstall AI Assistant" to apply it.'
            )
          } else {
            logger.warn(
              '[GpuPassthroughRemediationProvider] AMD GPU configured but Ollama fell back to CPU, and a ' +
                'reinstall would rebuild the same container. If this is an iGPU outside the ROCm ' +
                'allowlist, use "Fix: Set GFX Override" in Settings (e.g. 11.0.0 for a 780M/gfx1103).'
            )
          }
          return
        }

        // NVIDIA DeviceRequests without a registered runtime: a reinstall would come up
        // CPU-only, since DockerService attaches the GPU only when the runtime is present.
        if (!('nvidia' in runtimes)) {
          logger.warn(
            '[GpuPassthroughRemediationProvider] nomad_ollama requests an NVIDIA GPU but no NVIDIA runtime ' +
              'is registered with Docker. Reinstall the NVIDIA Container Toolkit; skipping auto-reinstall.'
          )
          return
        }

        // backend === 'cpu': an NVIDIA runtime is registered but Ollama still runs on
        // CPU. Cooldown: don't auto-reinstall more than once within the window. A
        // reinstall that fails to move Ollama onto the GPU (e.g. an architecture
        // Ollama has no kernels for) would otherwise trigger a reinstall every boot.
        const remediatedAtRaw = await KVStore.getValue('gpu.autoRemediatedAt')
        const remediatedAtMs = remediatedAtRaw ? new Date(String(remediatedAtRaw)).getTime() : NaN
        const withinCooldown =
          Number.isFinite(remediatedAtMs) && Date.now() - remediatedAtMs < AUTO_REMEDIATE_COOLDOWN_MS
        if (withinCooldown) {
          logger.warn(
            `[GpuPassthroughRemediationProvider] Ollama is on CPU but auto-remediation already ran within the last ${AUTO_REMEDIATE_COOLDOWN_MS / 60000}m (at ${remediatedAtRaw}). Skipping to avoid a reinstall loop; the manual "Fix: Reinstall AI Assistant" banner remains available.`
          )
          return
        }

        logger.warn(
          '[GpuPassthroughRemediationProvider] NVIDIA runtime registered but Ollama fell back to CPU. ' +
            'Auto-reinstalling nomad_ollama; volumes and installed models are preserved.'
        )

        const dockerService = new DockerService()
        const result = await dockerService.forceReinstall(SERVICE_NAMES.OLLAMA)

        if (result.success) {
          await KVStore.setValue('gpu.autoRemediatedAt', new Date().toISOString())
          logger.info(
            '[GpuPassthroughRemediationProvider] nomad_ollama force-reinstall completed successfully.'
          )
        } else {
          logger.error(
            `[GpuPassthroughRemediationProvider] Force-reinstall failed: ${result.message}. ` +
              'User can still click the "Fix: Reinstall AI Assistant" banner manually.'
          )
        }
      } catch (err: any) {
        logger.error(
          `[GpuPassthroughRemediationProvider] Auto-remediation check failed: ${err?.message ?? err}`
        )
      }
    })
  }
}

/**
 * Minimum gap between automatic nomad_ollama reinstalls triggered by this
 * provider. Bounds a reinstall loop when the GPU cannot be accelerated.
 */
const AUTO_REMEDIATE_COOLDOWN_MS = 60 * 60 * 1000 // 1 hour

import logger from '@adonisjs/core/services/logger'
import type { ApplicationService } from '@adonisjs/core/types'

/**
 * Checks whether the installed kiwix container is still using the legacy glob-pattern
 * command (`*.zim --address=all`) and, if so, migrates it to library mode
 * (`--library /data/kiwix-library.xml --monitorLibrary --address=all`) automatically.
 *
 * This provider runs once on every admin startup. After migration the check is a no-op
 * (inspects the container and finds the new command).
 */
export default class KiwixMigrationProvider {
  constructor(protected app: ApplicationService) {}

  async boot() {
    // Only run in the web (HTTP server) environment — skip for ace commands and tests
    if (this.app.getEnvironment() !== 'web') return

    // Defer past synchronous boot so DB connections and all providers are fully ready
    setImmediate(async () => {
      try {
        const Service = (await import('#models/service')).default
        const { SERVICE_NAMES } = await import('../constants/service_names.js')
        const { DockerService } = await import('#services/docker_service')
        const { KiwixLibraryService } = await import('#services/kiwix_library_service')

        const kiwixService = await Service.query()
          .where('service_name', SERVICE_NAMES.KIWIX)
          .first()

        if (!kiwixService?.installed) {
          logger.info('[KiwixMigrationProvider] Kiwix not installed — skipping migration check.')
          return
        }

        const dockerService = new DockerService()
        const isLegacy = await dockerService.isKiwixOnLegacyConfig()

        if (!isLegacy) {
          // Already in library mode. Make sure the library XML actually exists and
          // is parseable — if it was lost or corrupted outside the download flow,
          // rebuild it from disk so Kiwix isn't left serving an empty library.
          const rebuilt = await new KiwixLibraryService().ensureLibraryXmlHealthy()
          logger.info(
            rebuilt
              ? '[KiwixMigrationProvider] Rebuilt missing/invalid Kiwix library XML on startup.'
              : '[KiwixMigrationProvider] Kiwix is already in library mode — no migration needed.'
          )
          return
        }

        logger.info('[KiwixMigrationProvider] Kiwix on legacy config — running automatic migration to library mode.')
        await dockerService.migrateKiwixToLibraryMode()
        logger.info('[KiwixMigrationProvider] Startup migration complete.')
      } catch (err: any) {
        logger.error(`[KiwixMigrationProvider] Startup migration failed: ${err.message}`)
        // Non-fatal: the next affectContainer('restart') call will retry via the
        // intercept in DockerService.affectContainer().
      }
    })
  }
}

import MapsStaticMiddleware from '#middleware/maps_static_middleware'
import logger from '@adonisjs/core/services/logger'
import type { ApplicationService } from '@adonisjs/core/types'
import { defineConfig } from '@adonisjs/static'
import { join } from 'path'

/**
 * This is a bit of a hack to serve static files from the
 * /storage/maps directory using AdonisJS static middleware because
 * the middleware does not allow us to define a custom path we want
 * to serve (it always serves from public/ by default).
 *
 * We use the same other config options, just change the path
 * (though we could also separate config if needed).
 */
export default class MapStaticProvider {
  constructor(protected app: ApplicationService) {}
  register() {
    this.app.container.singleton(MapsStaticMiddleware, () => {
      const path = join(process.cwd(), '/storage/maps')
      logger.info(`Maps static files will be served from ${path}`)
      const config = this.app.config.get<any>('static', defineConfig({}))
      return new MapsStaticMiddleware(path, config)
    })
  }
}

import logger from '@adonisjs/core/services/logger'
import type { ApplicationService } from '@adonisjs/core/types'

/**
 * Ensures the nomad_qdrant container has the `unless-stopped` restart policy.
 *
 * Existing installations may have been created before this policy was enforced
 * in the service seeder. Docker allows updating a container's restart policy
 * without recreating it via the container.update() API.
 *
 * This provider runs once on every admin startup. If the policy is already
 * correct, the check is a no-op.
 */
export default class QdrantRestartPolicyProvider {
  constructor(protected app: ApplicationService) {}

  async boot() {
    if (this.app.getEnvironment() !== 'web') return

    setImmediate(async () => {
      try {
        const Service = (await import('#models/service')).default
        const { SERVICE_NAMES } = await import('../constants/service_names.js')
        const Docker = (await import('dockerode')).default

        const qdrantService = await Service.query()
          .where('service_name', SERVICE_NAMES.QDRANT)
          .first()

        if (!qdrantService?.installed) {
          logger.info('[QdrantRestartPolicyProvider] Qdrant not installed — skipping restart policy check.')
          return
        }

        const docker = new Docker({ socketPath: '/var/run/docker.sock' })
        const containers = await docker.listContainers({ all: true })
        const containerInfo = containers.find((c) => c.Names.includes(`/${SERVICE_NAMES.QDRANT}`))

        if (!containerInfo) {
          logger.warn('[QdrantRestartPolicyProvider] Qdrant container not found — skipping restart policy check.')
          return
        }

        const container = docker.getContainer(containerInfo.Id)
        const inspected = await container.inspect()
        const currentPolicy = inspected.HostConfig?.RestartPolicy?.Name

        if (currentPolicy === 'unless-stopped') {
          logger.info('[QdrantRestartPolicyProvider] Qdrant already has unless-stopped restart policy — no update needed.')
          return
        }

        logger.info(`[QdrantRestartPolicyProvider] Qdrant restart policy is "${currentPolicy ?? 'none'}" — updating to unless-stopped.`)
        await container.update({ RestartPolicy: { Name: 'unless-stopped', MaximumRetryCount: 0 } })
        logger.info('[QdrantRestartPolicyProvider] Qdrant restart policy updated successfully.')
      } catch (err: any) {
        logger.error(`[QdrantRestartPolicyProvider] Failed to update Qdrant restart policy: ${err.message}`)
        // Non-fatal: the container will still run, just without auto-restart on crash.
      }
    })
  }
}

import logger from '@adonisjs/core/services/logger'
import type { ApplicationService } from '@adonisjs/core/types'

/**
 * Self-heals stale `system.updateAvailable` after a sidecar-driven update.
 *
 * When the admin container is recreated on a new image, the KVStore still
 * carries pre-update values for `system.updateAvailable` and
 * `system.latestVersion`. Without intervention the UI keeps showing the
 * "update available" banner until the next scheduled CheckUpdateJob (could be up to ~12h).
 *
 * Synchronous self-heal (no network): if the cached "latest" is not newer
 * than the version we are now running, clear `updateAvailable`. The next
 * scheduled CheckUpdateJob refreshes the cache from GitHub — we deliberately
 * do not hit the network from boot to avoid coupling container startup to
 * a network request to Github (e.g. container restart loop = flooding GitHub with requests).
 *
 * Note: this provider does not set `updateAvailable` to true if the cached
 * "latest" is newer than the current version. We rely on the next scheduled
 * CheckUpdateJob to do that, to avoid false positives in case of a stale cache.
 */
export default class VersionCheckProvider {
  constructor(protected app: ApplicationService) { }

  async boot() {
    if (this.app.getEnvironment() !== 'web') return

    setImmediate(async () => {
      try {
        const KVStore = (await import('#models/kv_store')).default
        const { SystemService } = await import('#services/system_service')
        const { isNewerVersion } = await import('../app/utils/version.js')

        const current = SystemService.getAppVersion()
        if (current === 'dev' || current === '0.0.0'){
          logger.info(`[VersionCheckProvider] Skipping self-heal for version ${current}. Appears to be a dev build without proper version set.`)
          return
        }

        logger.info(`[VersionCheckProvider] Checking for stale updateAvailable (current=${current})`)

        const cachedLatest = (await KVStore.getValue('system.latestVersion')) as string | null
        const earlyAccess = ((await KVStore.getValue('system.earlyAccess')) ?? false) as boolean

        if (cachedLatest && !isNewerVersion(cachedLatest, current, earlyAccess)) {
          await KVStore.setValue('system.updateAvailable', false)
          logger.info(
            `[VersionCheckProvider] Cleared stale updateAvailable (cached=${cachedLatest}, current=${current})`
          )
        }
      } catch (err: any) {
        logger.warn(`[VersionCheckProvider] Self-heal skipped: ${err?.message ?? err}`)
      }
    })
  }
}

#!/usr/bin/env python3
"""
Supply Depot catalog port audit.

For every curated (non-dependency) service in the `services` table, launch its image in a
throwaway container using the catalog's image / command / env / volume container-paths, then
detect what TCP port(s) the app actually listens on inside the container (via /proc/net/tcp,
which needs no tools in the image) and compare against the container port the catalog maps.

A mismatch is the "Meshtastic Web" class of bug: the catalog publishes host->containerPort but
the app listens on a different internal port, so the published port reaches nothing.

Non-invasive: separate `audit_*` containers, random host ports on 127.0.0.1, temp volumes,
auto-removed. It never touches NOMAD's service records or real containers.

Run on a NOMAD host (needs the nomad_mysql container + docker):  python3 audit_catalog_ports.py
"""
import json
import os
import shlex
import shutil
import subprocess
import tempfile
import time

HOST_PORT_BASE = 9300  # throwaway host ports, well clear of catalog (8400s) and customs (8600s)
STARTUP_TIMEOUT = 60   # seconds to wait for an app to come up (heavy JVM apps like Stirling are slow)
MEMORY_CAP = "2g"      # generous cap; some apps (Stirling) OOM under 1g and falsely look crashed

# Apps that legitimately can't run in a throwaway probe (need real data or device config), so a
# "CRASHED"/"UNREACHABLE" verdict for them is expected and NOT a catalog port bug. Listed for the
# reader's benefit only — the script still probes them.
KNOWN_NEEDS_SETUP = {
    "nomad_kiwix_server": "needs a ZIM library (managed separately by NOMAD)",
    "nomad_meshtasticd": "needs a config.yaml with a MAC address",
    "nomad_meshcore_web": "serves HTTPS on 443 only with the bind-mounted SSL config (absent in a bare probe)",
}


def sh(cmd):
    return subprocess.run(cmd, shell=True, capture_output=True, text=True)


def mysql(query):
    """Run a query in the nomad_mysql container, reading the password from its own env.

    The inner command is single-quoted for the host shell so $MYSQL_PASSWORD is NOT expanded
    on the host (where it's unset) — it reaches the container's shell literally and expands there.
    Query must contain no double quotes (these catalog queries don't).
    """
    inner = 'mysql -N -unomad_user -p"$MYSQL_PASSWORD" nomad -e "%s"' % query
    out = sh("docker exec nomad_mysql sh -c " + shlex.quote(inner))
    if out.returncode != 0:
        raise SystemExit("mysql query failed: " + out.stderr)
    return out.stdout


def parse_config(raw):
    try:
        return json.loads(raw) if raw else {}
    except Exception:
        return {}


def container_port(cfg):
    """First container port from PortBindings (preferred) or ExposedPorts, e.g. '8080/tcp' -> 8080."""
    pb = (cfg.get("HostConfig") or {}).get("PortBindings") or {}
    keys = list(pb.keys()) or list((cfg.get("ExposedPorts") or {}).keys())
    for k in keys:
        try:
            return int(k.split("/")[0])
        except ValueError:
            continue
    return None


def listening_ports(name):
    """Listening TCP ports inside a container, parsed from /proc/net/tcp{,6} (st 0A = LISTEN)."""
    ports = set()
    for proc in ("/proc/net/tcp", "/proc/net/tcp6"):
        out = sh(f"docker exec {name} cat {proc} 2>/dev/null")
        for line in out.stdout.splitlines()[1:]:
            f = line.split()
            if len(f) > 3 and f[3] == "0A":
                try:
                    ports.add(int(f[1].split(":")[1], 16))
                except (IndexError, ValueError):
                    pass
    return sorted(ports)


def image_exposed(image):
    out = sh(f"docker image inspect {image} --format '{{{{json .Config.ExposedPorts}}}}'")
    try:
        d = json.loads(out.stdout.strip() or "null") or {}
        return sorted(int(k.split("/")[0]) for k in d)
    except Exception:
        return []


def main():
    rows = mysql(
        "SELECT service_name, container_image, COALESCE(container_command,''), container_config "
        "FROM services WHERE category IS NOT NULL AND is_dependency_service=0 "
        "AND is_custom=0 ORDER BY service_name"
    )
    services = [r.split("\t", 3) for r in rows.splitlines() if r.strip()]
    results = []

    for idx, (name, image, command, raw_cfg) in enumerate(services):
        cfg = parse_config(raw_cfg)
        cport = container_port(cfg)
        env = cfg.get("Env") or []
        binds = (cfg.get("HostConfig") or {}).get("Binds") or []
        host_port = HOST_PORT_BASE + idx
        cname = "audit_" + name
        tmpdirs = []

        sh(f"docker rm -f {cname} >/dev/null 2>&1")

        args = ["docker", "run", "-d", "--name", cname, "--memory=" + MEMORY_CAP]
        for e in env:
            args += ["-e", e]
        for b in binds:
            cpath = b.split(":")[1] if ":" in b else b
            td = tempfile.mkdtemp(prefix="audit_")
            os.chmod(td, 0o777)
            tmpdirs.append(td)
            args += ["-v", f"{td}:{cpath}"]
        if cport:
            args += ["-p", f"127.0.0.1:{host_port}:{cport}/tcp"]
        args.append(image)
        if command.strip():
            args += command.split()

        run = subprocess.run(args, capture_output=True, text=True)
        if run.returncode != 0:
            results.append((name, image, cport, [], None, "START ERROR: " + run.stderr.strip()[:160]))
            for td in tmpdirs:
                shutil.rmtree(td, ignore_errors=True)
            continue

        # Wait for the app to come up: a reachable published port or any internal listener.
        reachable_code, listeners = "000", []
        deadline = time.time() + STARTUP_TIMEOUT
        while time.time() < deadline:
            state = sh(f"docker inspect -f '{{{{.State.Running}}}}' {cname}").stdout.strip()
            listeners = listening_ports(cname)
            if cport:
                reachable_code = sh(
                    f"curl -s -o /dev/null -m 3 -w '%{{http_code}}' http://127.0.0.1:{host_port}"
                ).stdout.strip()
            if (cport and cport in listeners) or (reachable_code not in ("000", "")):
                break
            if state == "false" and listeners == []:
                time.sleep(2)
            time.sleep(2)

        running = sh(f"docker inspect -f '{{{{.State.Running}}}}' {cname}").stdout.strip() == "true"
        if not running:
            verdict = "CRASHED (exited)"
        elif cport is None:
            verdict = "NO PORT in catalog config"
        elif cport in listeners:
            verdict = f"OK (listens on {cport}, http={reachable_code})"
        elif listeners:
            verdict = f"PORT MISMATCH: catalog={cport}, app listens on {listeners}"
        elif reachable_code not in ("000", ""):
            verdict = f"OK (reachable http={reachable_code})"
        else:
            verdict = f"UNREACHABLE: nothing on catalog port {cport} (no listeners detected)"

        results.append((name, image, cport, listeners, image_exposed(image), verdict))

        sh(f"docker rm -f {cname} >/dev/null 2>&1")
        for td in tmpdirs:
            shutil.rmtree(td, ignore_errors=True)

    print("\n===== SUPPLY DEPOT CATALOG PORT AUDIT =====\n")
    for name, image, cport, listeners, exposed, verdict in results:
        flag = "  " if verdict.startswith("OK") else ">>"
        print(f"{flag} {name}")
        print(f"     image:        {image}")
        print(f"     catalog port: {cport}   image EXPOSE: {exposed or '-'}   listening: {listeners or '-'}")
        print(f"     verdict:      {verdict}")
        if name in KNOWN_NEEDS_SETUP and not verdict.startswith("OK"):
            print(f"     note:         expected — {KNOWN_NEEDS_SETUP[name]}; not a port bug")
        print()
    bad = [r for r in results if not r[5].startswith("OK") and r[0] not in KNOWN_NEEDS_SETUP]
    print(f"===== {len([r for r in results if r[5].startswith('OK')])}/{len(results)} OK; "
          f"{len(bad)} unexpected issue(s), {len(KNOWN_NEEDS_SETUP)} known-needs-setup =====")


if __name__ == "__main__":
    main()

