// ── deriveIngestPhase ────────────────────────────────────────────────────────
const dl = (state: DrugDownloadStatus['state']): DrugDownloadStatus => ({
  state,
  partsDone: 0,
  totalParts: 13,
  currentPartName: null,
})
const ing = (state: DrugIngestPhaseStatus['state']): DrugIngestPhaseStatus => ({
  state,
