import { fileURLToPath } from 'node:url'
import {
  parseNaturalRemediesFile,
  parseRemedyEntry,
  remediesForCondition,
  remediesForFreeText,
} from '../../util/conditions.ts'
import { NATURAL_REMEDIES_FILE } from '../../app/data/natural_remedies.ts'
import { CONDITIONS_FILE } from '../../app/data/conditions.ts'
import { parseConditionsFile } from '../../util/conditions.ts'
import type { NaturalRemediesFile } from '../../types/conditions.ts'

let passed = 0
function check(name: string, fn: () => void) {
  fn()
  passed++
  console.log(`  ok - ${name}`)
}

// ── parseRemedyEntry ──────────────────────────────────────────────────────────

check('parseRemedyEntry accepts a well-formed entry', () => {
  const entry = parseRemedyEntry({
    slug: 'ginger',
    name: 'Ginger',
    commonNames: ['Zingiber officinale'],
    conditions: ['nausea-vomiting'],
    uses: 'Used for nausea.',
    evidence: 'Some evidence.',
    cautions: 'May interact with blood thinners.',
    sourceUrl: 'https://www.nccih.nih.gov/health/ginger',
  })
  assert.ok(entry)
  assert.equal(entry!.slug, 'ginger')
  assert.equal(entry!.name, 'Ginger')
  assert.deepEqual(entry!.commonNames, ['Zingiber officinale'])
  assert.deepEqual(entry!.conditions, ['nausea-vomiting'])
})

check('parseRemedyEntry rejects missing required string fields', () => {
  // missing slug
  assert.equal(
    parseRemedyEntry({
      name: 'Ginger',
      commonNames: [],
      conditions: ['nausea'],
      uses: 'u',
      evidence: 'e',
      cautions: 'c',
      sourceUrl: 'https://example.com',
    }),
    null
  )
  // missing uses
  assert.equal(
    parseRemedyEntry({
      slug: 'ginger',
      name: 'Ginger',
      commonNames: [],
      conditions: ['nausea'],
      evidence: 'e',
      cautions: 'c',
      sourceUrl: 'https://example.com',
    }),
    null
  )
})

check('parseRemedyEntry rejects an entry with no usable conditions', () => {
  assert.equal(
    parseRemedyEntry({
      slug: 'g',
      name: 'G',
      commonNames: [],
      conditions: [],
      uses: 'u',
      evidence: 'e',
      cautions: 'c',
      sourceUrl: 'https://example.com',
    }),
    null
  )
})

check('parseRemedyEntry rejects non-objects', () => {
  assert.equal(parseRemedyEntry(null), null)
  assert.equal(parseRemedyEntry('ginger'), null)
  assert.equal(parseRemedyEntry(42), null)
})

check('parseRemedyEntry keeps non-empty commonNames, drops empties', () => {
  const entry = parseRemedyEntry({
    slug: 'g',
    name: 'G',
    commonNames: ['name', '', '  ', 'other'],
    conditions: ['c'],
    uses: 'u',
    evidence: 'e',
    cautions: 'c',
    sourceUrl: 'https://example.com',
  })
  assert.ok(entry)
  assert.deepEqual(entry!.commonNames, ['name', 'other'])
})

// ── parseNaturalRemediesFile ──────────────────────────────────────────────────

check('parseNaturalRemediesFile parses a valid file', () => {
  const file = parseNaturalRemediesFile({
    version: '2026-06-09',
    source: { name: 'NCCIH', url: 'https://nccih.nih.gov', license: 'Public domain' },
    remedies: [
      {
        slug: 'ginger',
        name: 'Ginger',
        commonNames: ['Zingiber officinale'],
        conditions: ['nausea-vomiting'],
        uses: 'Used for nausea.',
        evidence: 'Some evidence.',
        cautions: 'See a clinician.',
        sourceUrl: 'https://www.nccih.nih.gov/health/ginger',
      },
    ],
  })
  assert.equal(file.version, '2026-06-09')
  assert.equal(file.source.name, 'NCCIH')
  assert.equal(file.remedies.length, 1)
  assert.equal(file.remedies[0].slug, 'ginger')
})

check('parseNaturalRemediesFile drops malformed entries but keeps good ones', () => {
  const file = parseNaturalRemediesFile({
    version: 'v',
    source: { name: 'S', url: 'u', license: 'l' },
    remedies: [
      {
        slug: 'good',
        name: 'Good',
        commonNames: [],
        conditions: ['pain'],
        uses: 'u',
        evidence: 'e',
        cautions: 'c',
        sourceUrl: 'https://example.com',
      },
      { slug: 'bad-no-conditions', name: 'Bad', commonNames: [], conditions: [], uses: 'u', evidence: 'e', cautions: 'c', sourceUrl: 'https://example.com' },
      'not-an-object',
    ],
  })
  assert.equal(file.remedies.length, 1)
  assert.equal(file.remedies[0].slug, 'good')
})

check('parseNaturalRemediesFile de-dupes by slug, keeping the first', () => {
  const file = parseNaturalRemediesFile({
    version: 'v',
    source: { name: '', url: '', license: '' },
    remedies: [
      { slug: 'dup', name: 'First', commonNames: [], conditions: ['pain'], uses: 'u', evidence: 'e', cautions: 'c', sourceUrl: 'https://example.com' },
      { slug: 'dup', name: 'Second', commonNames: [], conditions: ['pain'], uses: 'u2', evidence: 'e2', cautions: 'c2', sourceUrl: 'https://example.com' },
    ],
  })
  assert.equal(file.remedies.length, 1)
  assert.equal(file.remedies[0].name, 'First')
})

check('parseNaturalRemediesFile fail-soft on garbage input', () => {
  const empty = parseNaturalRemediesFile(null)
  assert.equal(empty.version, 'unknown')
  assert.deepEqual(empty.remedies, [])

  const noRemedies = parseNaturalRemediesFile({ version: 'v', source: { name: '', url: '', license: '' } })
  assert.deepEqual(noRemedies.remedies, [])
})

// ── remediesForCondition ──────────────────────────────────────────────────────

const sampleFile = parseNaturalRemediesFile({
  version: 'v',
  source: { name: 'S', url: 'u', license: 'l' },
  remedies: [
    { slug: 'ginger', name: 'Ginger', commonNames: [], conditions: ['nausea-vomiting', 'indigestion'], uses: 'u', evidence: 'e', cautions: 'c', sourceUrl: 'https://example.com/ginger' },
    { slug: 'chamomile', name: 'Chamomile', commonNames: [], conditions: ['sleeplessness', 'indigestion'], uses: 'u', evidence: 'e', cautions: 'c', sourceUrl: 'https://example.com/chamomile' },
    { slug: 'aloe-vera', name: 'Aloe Vera', commonNames: [], conditions: ['burns'], uses: 'u', evidence: 'e', cautions: 'c', sourceUrl: 'https://example.com/aloe-vera' },
  ],
})

check('remediesForCondition returns remedies whose conditions[] includes the slug', () => {
  const result = remediesForCondition(sampleFile, 'indigestion')
  assert.equal(result.length, 2)
  assert.deepEqual(
    result.map((r) => r.slug),
    ['ginger', 'chamomile']
  )
})

check('remediesForCondition returns [] when slug matches nothing', () => {
  assert.deepEqual(remediesForCondition(sampleFile, 'fever'), [])
})

check('remediesForCondition returns [] for empty slug', () => {
  assert.deepEqual(remediesForCondition(sampleFile, ''), [])
  assert.deepEqual(remediesForCondition(sampleFile, '  '), [])
})

check('remediesForCondition preserves stable curated order', () => {
  const result = remediesForCondition(sampleFile, 'indigestion')
  assert.equal(result[0].slug, 'ginger')
  assert.equal(result[1].slug, 'chamomile')
})

check('remediesForCondition returns [] for empty remedies file', () => {
  const emptyFile = parseNaturalRemediesFile({ version: 'v', source: { name: '', url: '', license: '' }, remedies: [] })
  assert.deepEqual(remediesForCondition(emptyFile, 'burns'), [])
})

// ── remediesForFreeText ───────────────────────────────────────────────────────

check('remediesForFreeText matches on name (case-insensitive)', () => {
  const result = remediesForFreeText(sampleFile, 'GINGER')
  assert.equal(result.length, 1)
  assert.equal(result[0].slug, 'ginger')
})

check('remediesForFreeText matches on uses substring', () => {
  // All three have uses === 'u', so a substring match on 'u' returns all
  const result = remediesForFreeText(sampleFile, 'aloe')
  assert.equal(result.length, 1)
  assert.equal(result[0].slug, 'aloe-vera')
})

check('remediesForFreeText returns [] for empty query', () => {
  assert.deepEqual(remediesForFreeText(sampleFile, ''), [])
  assert.deepEqual(remediesForFreeText(sampleFile, '  '), [])
})

check('remediesForFreeText dedupes by slug', () => {
  // "indigestion" should not appear twice even if name AND uses both match
  const result = remediesForFreeText(sampleFile, 'Ginger')
  assert.equal(result.filter((r) => r.slug === 'ginger').length, 1)
})

// ── sync check: NATURAL_REMEDIES_FILE ↔ collections/natural_remedies.json ────

check('NATURAL_REMEDIES_FILE parses cleanly with no dropped entries', () => {
  const parsed = parseNaturalRemediesFile(NATURAL_REMEDIES_FILE)
  assert.equal(parsed.remedies.length, NATURAL_REMEDIES_FILE.remedies.length)
})

check('NATURAL_REMEDIES_FILE matches collections/natural_remedies.json in version + count + slugs', () => {
  // This test file is at admin/tests/standalone/; ../../../ reaches the repo root.
  const __dir = dirname(fileURLToPath(import.meta.url))
  const jsonPath = resolve(__dir, '../../../collections/natural_remedies.json')
  const raw = JSON.parse(readFileSync(jsonPath, 'utf8')) as NaturalRemediesFile

  // version
  assert.equal(
    NATURAL_REMEDIES_FILE.version,
    raw.version,
    `version mismatch: TS=${NATURAL_REMEDIES_FILE.version} JSON=${raw.version}`
  )

  // remedy count
  assert.equal(
    NATURAL_REMEDIES_FILE.remedies.length,
    raw.remedies.length,
    `remedy count mismatch: TS=${NATURAL_REMEDIES_FILE.remedies.length} JSON=${raw.remedies.length}`
  )

  // slug set equality
  const tsSlugs = new Set(NATURAL_REMEDIES_FILE.remedies.map((r) => r.slug))
  const jsonSlugs = new Set(raw.remedies.map((r: { slug: string }) => r.slug))
  for (const slug of tsSlugs) {
    assert.ok(jsonSlugs.has(slug), `slug in TS but not in JSON: ${slug}`)
  }
  for (const slug of jsonSlugs) {
    assert.ok(tsSlugs.has(slug), `slug in JSON but not in TS: ${slug}`)
  }
})

check('every remedy condition slug exists in the conditions spine', () => {
  const spine = parseConditionsFile(CONDITIONS_FILE)
  const knownSlugs = new Set(spine.conditions.map((c) => c.slug))
  const unknown: string[] = []
  for (const remedy of NATURAL_REMEDIES_FILE.remedies) {
    for (const condSlug of remedy.conditions) {
      if (!knownSlugs.has(condSlug)) {
        unknown.push(`${remedy.slug} → "${condSlug}"`)
      }
    }
  }
  assert.equal(
    unknown.length,
    0,
    `Unknown condition slugs in remedies:\n  ${unknown.join('\n  ')}`
  )
})

check('shipped NATURAL_REMEDIES_FILE has the 18 curated remedies', () => {
  const n = NATURAL_REMEDIES_FILE.remedies.length
  assert.equal(n, 18, `expected 18 remedies, got ${n}`)
})

check('shipped remedies have unique slugs and non-empty required fields', () => {
  const slugs = new Set<string>()
  for (const r of NATURAL_REMEDIES_FILE.remedies) {
    assert.ok(!slugs.has(r.slug), `duplicate slug: ${r.slug}`)
    slugs.add(r.slug)
    assert.ok(r.name.trim().length > 0, `empty name: ${r.slug}`)
    assert.ok(r.uses.trim().length > 0, `empty uses: ${r.slug}`)
    assert.ok(r.cautions.trim().length > 0, `empty cautions: ${r.slug}`)
    assert.ok(r.sourceUrl.startsWith('https://'), `bad sourceUrl: ${r.slug}`)
    assert.ok(r.conditions.length > 0, `no conditions: ${r.slug}`)
  }
})

console.log(`\n${passed} checks passed`)

import * as assert from 'node:assert/strict'
import { test } from 'node:test'

import {
  mapGfxToHsaOverride,
  pickAmdHsaOverride,
  readHsaOverrideFromEnv,
} from '../../app/utils/amd_hsa_override.js'

test('gfx1103 (Phoenix 780M) coerces to 11.0.0 — the #1076 regression', () => {
  // Not on the bundled rocblas allowlist; without this ollama drops it to CPU.
  assert.equal(mapGfxToHsaOverride('gfx1103'), '11.0.0')
})

test('gfx1150 / gfx1151 (Strix 890M, Strix Halo) stay native — no override', () => {
  // These ARE on the allowlist; forcing an override would needlessly coerce them.
  assert.equal(mapGfxToHsaOverride('gfx1150'), null)
  assert.equal(mapGfxToHsaOverride('gfx1151'), null)
})

test('RDNA 2 iGPUs (gfx1031..gfx1036, e.g. 680M) coerce to 10.3.0', () => {
  assert.equal(mapGfxToHsaOverride('gfx1035'), '10.3.0')
  assert.equal(mapGfxToHsaOverride('gfx1031'), '10.3.0')
  assert.equal(mapGfxToHsaOverride('gfx1036'), '10.3.0')
})

test('discrete cards on the ROCm allowlist get no override', () => {
  for (const gfx of ['gfx1030', 'gfx1100', 'gfx1101', 'gfx1102']) {
    assert.equal(mapGfxToHsaOverride(gfx), null)
  }
})

test('unknown / newer targets default to native discovery (no override)', () => {
  assert.equal(mapGfxToHsaOverride('gfx9999'), null)
  assert.equal(mapGfxToHsaOverride(''), null)
})

const OVERRIDE_ENV = ['OLLAMA_NO_CLOUD=1', 'HSA_OVERRIDE_GFX_VERSION=11.0.0']

test('readHsaOverrideFromEnv reads the override or null', () => {
  assert.equal(readHsaOverrideFromEnv(OVERRIDE_ENV), '11.0.0')
  assert.equal(readHsaOverrideFromEnv(['OLLAMA_NO_CLOUD=1']), null)
  assert.equal(readHsaOverrideFromEnv(null), null)
})

test('pickAmdHsaOverride: a KV version wins over the marker and container', () => {
  assert.deepEqual(pickAmdHsaOverride({ manual: '10.3.0', markerGfx: 'gfx1103', containerEnv: OVERRIDE_ENV }), {
    value: '10.3.0',
    source: 'kv',
  })
})

test('pickAmdHsaOverride: KV none disables even a container override', () => {
  assert.deepEqual(pickAmdHsaOverride({ manual: 'none', markerGfx: null, containerEnv: OVERRIDE_ENV }), {
    value: null,
    source: 'kv-disabled',
  })
})

test('pickAmdHsaOverride: a marker is authoritative even when it maps to none', () => {
  assert.deepEqual(pickAmdHsaOverride({ manual: null, markerGfx: 'gfx1151', containerEnv: OVERRIDE_ENV }), {
    value: null,
    source: 'marker',
  })
})

test('pickAmdHsaOverride keeps the container override with no KV or marker (#1377)', () => {
  assert.deepEqual(pickAmdHsaOverride({ manual: null, markerGfx: null, containerEnv: OVERRIDE_ENV }), {
    value: '11.0.0',
    source: 'container',
  })
  assert.deepEqual(pickAmdHsaOverride({ manual: '', markerGfx: null, containerEnv: OVERRIDE_ENV }), {
    value: '11.0.0',
    source: 'container',
  })
})

test('pickAmdHsaOverride ignores a malformed container override', () => {
  assert.deepEqual(
    pickAmdHsaOverride({ manual: null, markerGfx: null, containerEnv: ['HSA_OVERRIDE_GFX_VERSION=gfx1103'] }),
    { value: null, source: 'default' }
  )
})

test('pickAmdHsaOverride skips an invalid KV value and reports it', () => {
  assert.deepEqual(pickAmdHsaOverride({ manual: 'bogus', markerGfx: null, containerEnv: OVERRIDE_ENV }), {
    value: '11.0.0',
    source: 'container',
    invalidManual: 'bogus',
  })
})

import * as assert from 'node:assert/strict'
import { test } from 'node:test'
import { DateTime } from 'luxon'

import { AppAutoUpdateService } from '../../app/services/app_auto_update_service.js'
import { ContainerRegistryService } from '../../app/services/container_registry_service.js'
import { isWithinWindow } from '../../app/utils/update_window.js'

// appEligibility only touches ContainerRegistryService.parseImageReference (pure,
// offline), so the other constructor deps are irrelevant for these tests.
const svc = new AppAutoUpdateService(
  null as any,
  null as any,
  null as any,
  new ContainerRegistryService()
)

const NOW = DateTime.fromISO('2026-06-04T12:00:00Z')
const daysAgo = (d: number) => NOW.minus({ days: d })
const hoursAgo = (h: number) => NOW.minus({ hours: h })

function makeService(overrides: Record<string, any> = {}) {
  return {
    service_name: 'nomad_test',
    container_image: 'ollama/ollama:0.18.1',
    available_update_version: null,
    available_update_first_seen_at: null,
    auto_update_disabled_reason: null,
    auto_update_enabled: true,
    installed: true,
    ...overrides,
  } as any
}

// ── Per-app eligibility ───────────────────────────────────────────────────────

test('no available update → not eligible (up to date)', () => {
  const v = svc.appEligibility(makeService(), 72, NOW)
  assert.equal(v.eligible, false)
})

test('major bump is never auto-eligible (manual update required)', () => {
  const v = svc.appEligibility(
    makeService({ available_update_version: '1.0.0', available_update_first_seen_at: daysAgo(10) }),
    72,
    NOW
  )
  assert.equal(v.eligible, false)
  assert.match(v.reason, /Major version/)
})

test('same-major newer but still inside cool-off → not eligible', () => {
  const v = svc.appEligibility(
    makeService({
      available_update_version: '0.19.0',
      available_update_first_seen_at: hoursAgo(10),
    }),
    72,
    NOW
  )
  assert.equal(v.eligible, false)
  assert.match(v.reason, /cool-off/i)
})

test('same-major newer and past cool-off → eligible', () => {
  const v = svc.appEligibility(
    makeService({ available_update_version: '0.19.0', available_update_first_seen_at: daysAgo(5) }),
    72,
    NOW
  )
  assert.equal(v.eligible, true)
})

test('null first-seen → not eligible (cool-off pending)', () => {
  const v = svc.appEligibility(
    makeService({ available_update_version: '0.19.0', available_update_first_seen_at: null }),
    72,
    NOW
  )
  assert.equal(v.eligible, false)
})

test('self-disabled app → not eligible regardless of cool-off', () => {
  const v = svc.appEligibility(
    makeService({
      available_update_version: '0.19.0',
      available_update_first_seen_at: daysAgo(30),
      auto_update_disabled_reason: 'Auto-update disabled after 3 consecutive failures.',
    }),
    72,
    NOW
  )
  assert.equal(v.eligible, false)
})

test(':latest-pinned app cannot be version-checked → not eligible', () => {
  const v = svc.appEligibility(
    makeService({
      container_image: 'foo/bar:latest',
      available_update_version: '1.2.3',
      available_update_first_seen_at: daysAgo(30),
    }),
    72,
    NOW
  )
  assert.equal(v.eligible, false)
})

test('available equal to current (not newer) → not eligible', () => {
  const v = svc.appEligibility(
    makeService({
      available_update_version: '0.18.1',
      available_update_first_seen_at: daysAgo(30),
    }),
    72,
    NOW
  )
  assert.equal(v.eligible, false)
})

test('cool-off of 0 applies immediately', () => {
  const v = svc.appEligibility(
    makeService({
      available_update_version: '0.18.2',
      available_update_first_seen_at: hoursAgo(1),
    }),
    0,
    NOW
  )
  assert.equal(v.eligible, true)
})

// ── Shared update window (reused from the core auto-update) ────────────────────

test('window: normal 20:00-23:00 includes 21:00, excludes 19:00', () => {
  assert.equal(isWithinWindow('20:00', '23:00', DateTime.fromISO('2026-06-04T21:00:00')), true)
  assert.equal(isWithinWindow('20:00', '23:00', DateTime.fromISO('2026-06-04T19:00:00')), false)
})

test('window: midnight-wrapping 22:00-02:00 includes 01:00, excludes 12:00', () => {
  assert.equal(isWithinWindow('22:00', '02:00', DateTime.fromISO('2026-06-04T01:00:00')), true)
  assert.equal(isWithinWindow('22:00', '02:00', DateTime.fromISO('2026-06-04T12:00:00')), false)
})

import assert from 'node:assert/strict'
import test from 'node:test'
import type { MultipartFile } from '@adonisjs/bodyparser/types'
import sharp from 'sharp'
import { mkdtemp, rm, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import {
  attachImagesToLatestUserMessage,
  ChatImageError,
  normalizeChatImages,
} from '../../app/utils/chat_images.js'
import {
  capabilitiesFromOllamaShow,
  installedModelsFromOpenAIResponse,
  resolveModelCapabilities,
  visionCapabilityFromLlamaProps,
} from '../../app/utils/model_capabilities.js'

function uploadedFile(path: string, size: number, name = 'sample.png'): MultipartFile {
  return {
    tmpPath: path,
    size,
    clientName: name,
    isValid: true,
  } as MultipartFile
}

test('normalizes a supported image to a bounded JPEG data URL', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'nomad-chat-image-'))
  const path = join(directory, 'sample.png')
  const input = await sharp({
    create: {
      width: 32,
      height: 24,
      channels: 3,
      background: '#556b2f',
    },
  })
    .png()
    .toBuffer()
  await writeFile(path, input)

  try {
    const [image] = await normalizeChatImages([uploadedFile(path, input.byteLength)])
    assert.equal(image.name, 'sample.png')
    assert.match(image.dataUrl, /^data:image\/jpeg;base64,/)
    const decoded = Buffer.from(image.dataUrl.split(',')[1], 'base64')
    const metadata = await sharp(decoded).metadata()
    assert.equal(metadata.format, 'jpeg')
    assert.equal(metadata.width, 32)
    assert.equal(metadata.height, 24)
  } finally {
    await rm(directory, { recursive: true, force: true })
  }
})

test('normalizes image bytes when the filename extension does not match the encoding', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'nomad-chat-image-'))
  const path = join(directory, 'mislabeled.png')
  const input = await sharp({
    create: {
      width: 32,
      height: 24,
      channels: 3,
      background: '#556b2f',
    },
  })
    .webp()
    .toBuffer()
  await writeFile(path, input)

  try {
    const [image] = await normalizeChatImages([
      uploadedFile(path, input.byteLength, 'mislabeled.png'),
    ])
    assert.equal(image.name, 'mislabeled.png')
    assert.match(image.dataUrl, /^data:image\/jpeg;base64,/)
    const decoded = Buffer.from(image.dataUrl.split(',')[1], 'base64')
    const metadata = await sharp(decoded).metadata()
    assert.equal(metadata.format, 'jpeg')
    assert.equal(metadata.width, 32)
    assert.equal(metadata.height, 24)
  } finally {
    await rm(directory, { recursive: true, force: true })
  }
})

test('rejects payloads with more than four images', async () => {
  const files = Array.from({ length: 5 }, (_, index) =>
    uploadedFile(`/tmp/image-${index}.png`, 10, `image-${index}.png`)
  )
  await assert.rejects(
    () => normalizeChatImages(files),
    (error: unknown) => {
      assert.ok(error instanceof ChatImageError)
      assert.equal(error.status, 422)
      return true
    }
  )
})

test('attaches images only to the latest user message', () => {
  const messages = [
    { role: 'user' as const, content: 'Earlier question' },
    { role: 'assistant' as const, content: 'Earlier answer' },
    { role: 'user' as const, content: 'What is shown?' },
  ]
  const result = attachImagesToLatestUserMessage(messages, [
    { name: 'sample.webp', dataUrl: 'data:image/webp;base64,AAAA' },
  ])

  assert.equal(result[0].content, 'Earlier question')
  assert.equal(result[1].content, 'Earlier answer')
  assert.deepEqual(result[2], {
    role: 'user',
    content: [
      { type: 'text', text: 'What is shown?' },
