import * as assert from 'node:assert/strict'
import { test } from 'node:test'
import { join } from 'node:path'

import { decideOrphans, filterOrphanCandidates } from '../../app/utils/kb_orphan_decision.js'

// Paths are built with join() rather than written as POSIX literals so these
// cases exercise the same separator filterOrphanCandidates does. Written as
// '/data/...' string literals they silently pass on Linux CI and fail on a
// Windows dev box, which makes the suite useless exactly where someone is
// most likely to be running it while changing this file.
const STORAGE = join('/data', 'storage')
const KB_UPLOADS_ROOT = join(STORAGE, 'kb_uploads')
const ZIM_ROOT = join(STORAGE, 'zim')

/** Both roots present and walked — the healthy case. */
const SCAN_ROOTS = [KB_UPLOADS_ROOT, ZIM_ROOT]

const upload = (name: string) => join(KB_UPLOADS_ROOT, name)
const zim = (name: string) => join(ZIM_ROOT, name)

test('no sources in Qdrant → no orphans', () => {
  assert.deepEqual(decideOrphans([], [zim('a.zim')], SCAN_ROOTS), { orphans: [], withheld: [] })
})

test('every Qdrant source still has a file on disk → no orphans', () => {
  assert.deepEqual(
    decideOrphans([zim('a.zim'), zim('b.zim')], [zim('a.zim'), zim('b.zim')], SCAN_ROOTS),
    { orphans: [], withheld: [] }
  )
})

test('a source with no matching file on disk is an orphan', () => {
  assert.deepEqual(decideOrphans([zim('a.zim'), zim('gone.zim')], [zim('a.zim')], SCAN_ROOTS), {
    orphans: [zim('gone.zim')],
    withheld: [],
  })
})

test('sources outside every scanned root are never orphans (e.g. bundled docs)', () => {
  const readme = join('/data', 'README.md')
  assert.deepEqual(decideOrphans([readme, zim('a.zim')], [zim('a.zim')], SCAN_ROOTS), {
    orphans: [],
    withheld: [],
  })
})

test('empty disk scan withholds every root instead of purging everything', () => {
  assert.deepEqual(decideOrphans([upload('a.pdf'), zim('a.zim')], [], SCAN_ROOTS), {
    orphans: [],
    withheld: [
      { root: KB_UPLOADS_ROOT, count: 1, reason: 'empty_root' },
      { root: ZIM_ROOT, count: 1, reason: 'empty_root' },
    ],
  })
})

test('filterOrphanCandidates keeps sources under the kb_uploads or zim scan roots', () => {
  assert.deepEqual(filterOrphanCandidates([upload('a.pdf'), zim('b.zim')], SCAN_ROOTS), [
    upload('a.pdf'),
    zim('b.zim'),
  ])
})

test('filterOrphanCandidates excludes sources outside the scanned roots (e.g. bundled docs)', () => {
  assert.deepEqual(
    filterOrphanCandidates(
      [join('/data', 'README.md'), join('/data', 'docs', 'guide.md'), zim('b.zim')],
      SCAN_ROOTS
    ),
    [zim('b.zim')]
  )
})

test('filterOrphanCandidates does not match a sibling directory that merely shares a root as a string prefix', () => {
  // '<storage>/zim-backup/...' must not pass just because it starts with the
  // same characters as zimPath — the trailing separator is what makes this a
  // real subpath check rather than a naive string prefix match.
  assert.deepEqual(filterOrphanCandidates([join(STORAGE, 'zim-backup', 'x.zim')], SCAN_ROOTS), [])
})

test('a root that was not scanned contributes no candidates, even though the scan found files', () => {
  // The #1050 shape: the zim root is relocated or not yet mounted, so
  // _discoverKbFiles() skips it (ENOENT is not fatal) and reports only
  // kb_uploads as scanned. The file list is still non-empty from kb_uploads,
  // so decideOrphans' empty-scan guard does NOT fire. Without confining
  // candidates to roots actually walked, every indexed ZIM would be
  // classified as an orphan and purged in one batch.
  const sourcesInQdrant = [upload('a.pdf'), zim('wikipedia_en_all_maxi.zim'), zim('gutenberg.zim')]
  const candidates = filterOrphanCandidates(sourcesInQdrant, [KB_UPLOADS_ROOT])
  assert.deepEqual(candidates, [upload('a.pdf')])

  // End to end: the ZIMs survive despite having no backing file in the scan.
  assert.deepEqual(decideOrphans(sourcesInQdrant, [upload('a.pdf')], [KB_UPLOADS_ROOT]), {
    orphans: [],
    withheld: [],
  })
})

test('no roots scanned at all yields no candidates', () => {
  // "We could not read any of the storage" must never read as "nothing is on
  // disk, so purge everything."
  assert.deepEqual(filterOrphanCandidates([zim('a.zim')], []), [])
})

test('a walked root with no embeddable files keeps its sources (#1378)', () => {
  // The unmounted-volume shape: boot's ensureDirectoryExists() recreates the
  // zim mountpoint as an empty directory, so the scan walks it without error
  // and reports it as scanned. kb_uploads keeps the overall scan non-empty.
  // Treating "walked and empty" as "everything under it was deleted" would
  // purge every ZIM in the index.
  const sourcesInQdrant = [upload('a.pdf'), zim('wikipedia_en_all_maxi.zim'), zim('gutenberg.zim')]
  assert.deepEqual(decideOrphans(sourcesInQdrant, [upload('a.pdf')], SCAN_ROOTS), {
    orphans: [],
    withheld: [{ root: ZIM_ROOT, count: 2, reason: 'empty_root' }],
  })
})

test('a root holding only non-embeddable files still counts as empty', () => {
  // Kiwix regenerates kiwix-library.xml in the empty mountpoint, so the
  // directory has entries. Only embeddable files are evidence the content is
  // there, and _discoverKbFilesWithRoots() drops the XML before this point, so
  // the zim root arrives with nothing under it.
  const embeddable = [upload('a.pdf')]
  assert.deepEqual(decideOrphans([zim('a.zim')], embeddable, SCAN_ROOTS).withheld, [
    { root: ZIM_ROOT, count: 1, reason: 'empty_root' },
  ])
})

test('an empty kb_uploads root keeps its sources while zim is swept normally', () => {
  const zims = ['a', 'b', 'c'].map((n) => zim(`${n}.zim`))
  assert.deepEqual(
    decideOrphans([upload('a.pdf'), ...zims, zim('gone.zim')], zims, SCAN_ROOTS),
    {
      orphans: [zim('gone.zim')],
      withheld: [{ root: KB_UPLOADS_ROOT, count: 1, reason: 'empty_root' }],
    }
  )
})

test('removing most of a root in one sync is withheld as a likely wrong mount', () => {
  // The root is present and non-empty, but it holds 2 of 10 indexed ZIMs:
  // far likelier a different disk or stale copy than 8 hand-deletions.
  const indexed = Array.from({ length: 10 }, (_, i) => zim(`z${i}.zim`))
  const onDisk = indexed.slice(0, 2)
  assert.deepEqual(decideOrphans(indexed, onDisk, SCAN_ROOTS), {
    orphans: [],
    withheld: [{ root: ZIM_ROOT, count: 8, reason: 'mass_removal' }],
  })
})

test('removing up to half a root is still purged', () => {
  const indexed = Array.from({ length: 10 }, (_, i) => zim(`z${i}.zim`))
  const onDisk = indexed.slice(0, 5)
  assert.deepEqual(decideOrphans(indexed, onDisk, SCAN_ROOTS), {
    orphans: indexed.slice(5),
    withheld: [],
  })
})

test('the mass-removal guard does not engage below the minimum count', () => {
  // 4 of 5 missing is 80%, but only 4 sources: too few for the ratio to mean
  // anything, and cheap to re-embed if wrong.
  const indexed = Array.from({ length: 5 }, (_, i) => zim(`z${i}.zim`))
  assert.deepEqual(decideOrphans(indexed, indexed.slice(0, 1), SCAN_ROOTS), {
    orphans: indexed.slice(1),
    withheld: [],
  })
})

import * as assert from 'node:assert/strict'
import { test } from 'node:test'

import {
  BYTES_PER_CHUNK_ON_DISK,
  estimateBatch,
  estimateChunkCount,
  findChunksPerMb,
} from '../../app/utils/kb_ratio_lookup.js'

const SEEDED_ROWS = [
  { pattern: 'devdocs_', chunks_per_mb: 1100 },
  { pattern: 'wikipedia_en_simple_', chunks_per_mb: 270 },
  { pattern: 'wikipedia_en_', chunks_per_mb: 250 },
  { pattern: 'ifixit_', chunks_per_mb: 50 },
  { pattern: 'lrnselfreliance_', chunks_per_mb: 0 },
  { pattern: '', chunks_per_mb: 100 },
]

test('exact prefix match', () => {
  assert.equal(findChunksPerMb('devdocs_en_python_2026-02.zim', SEEDED_ROWS), 1100)
})

test('longest-prefix wins over broader sibling', () => {
  // wikipedia_en_simple_* should pick 270, not the 250 from wikipedia_en_
  assert.equal(
    findChunksPerMb('wikipedia_en_simple_all_nopic_2026-02.zim', SEEDED_ROWS),
    270
  )
})

test('broader prefix used when no specific match', () => {
  // wikipedia_en_medicine_* is not seeded; falls through to wikipedia_en_ at 250
  assert.equal(findChunksPerMb('wikipedia_en_medicine_nopic_2026-04.zim', SEEDED_ROWS), 250)
})

test('empty-string fallback catches unmatched filenames', () => {
  assert.equal(findChunksPerMb('something_unknown_2026-02.zim', SEEDED_ROWS), 100)
})

test('returns null when no row matches and no fallback is registered', () => {
  const rowsWithoutFallback = SEEDED_ROWS.filter((r) => r.pattern !== '')
  assert.equal(findChunksPerMb('something_unknown_2026-02.zim', rowsWithoutFallback), null)
})

test('zero-ratio entry returns 0, not null (video-only ZIMs)', () => {
  assert.equal(findChunksPerMb('lrnselfreliance_en_all_2025-12.zim', SEEDED_ROWS), 0)
})

test('estimateChunkCount scales by file size in MB', () => {
  // 100 MB * 1100 chunks/MB ≈ 110,000 chunks for devdocs
  const bytes = 100 * 1024 * 1024
  assert.equal(estimateChunkCount('devdocs_en_python_2026-02.zim', bytes, SEEDED_ROWS), 110000)
})

test('estimateChunkCount returns 0 for video-only ZIM regardless of size', () => {
  const bytes = 5 * 1024 * 1024 * 1024 // 5 GB
  assert.equal(estimateChunkCount('lrnselfreliance_en_all_2025-12.zim', bytes, SEEDED_ROWS), 0)
})

test('estimateChunkCount returns null when no match and no fallback', () => {
  const rowsWithoutFallback = SEEDED_ROWS.filter((r) => r.pattern !== '')
  assert.equal(
    estimateChunkCount('something_unknown_2026-02.zim', 50 * 1024 * 1024, rowsWithoutFallback),
    null
  )
})

test('ignoreCatchAll: returns null for filenames only the empty-pattern fallback would match (#913)', () => {
  // military-medicine matches no specific prefix; without ignoreCatchAll it would
  // hit the 100 chunks/MB fallback and wildly over-predict, falsely tripping
  // the partial_stall warning on a PDF/link-out-heavy ZIM.
  assert.equal(
    findChunksPerMb('irp.fas.org_en_military-medicine_2026-05.zim', SEEDED_ROWS, {
      ignoreCatchAll: true,
    }),
    null
  )
  assert.equal(
    estimateChunkCount('irp.fas.org_en_military-medicine_2026-05.zim', 75 * 1024 * 1024, SEEDED_ROWS, {
      ignoreCatchAll: true,
    }),
    null
  )
})

test('ignoreCatchAll: still honors a specific (non-empty) pattern match', () => {
  // A file that matches a real prefix should be unaffected by ignoreCatchAll.
  assert.equal(
    findChunksPerMb('wikipedia_en_simple_all_nopic_2026-02.zim', SEEDED_ROWS, {
      ignoreCatchAll: true,
    }),
    270
  )
})

test('estimateBatch sums chunks and bytes for matched files', () => {
  const files = [
    // 100 MB devdocs -> 110,000 chunks
    { filename: 'devdocs_en_python_2026-02.zim', sizeBytes: 100 * 1024 * 1024 },
    // 500 MB wikipedia_en_simple -> 135,000 chunks
    { filename: 'wikipedia_en_simple_all_nopic_2026-02.zim', sizeBytes: 500 * 1024 * 1024 },
  ]
  const out = estimateBatch(files, SEEDED_ROWS)
  assert.equal(out.totalChunks, 110_000 + 135_000)
  assert.equal(out.totalBytes, (110_000 + 135_000) * BYTES_PER_CHUNK_ON_DISK)
  assert.equal(out.hasUnknown, false)
})

test('estimateBatch sets hasUnknown when a file has no registry match', () => {
  // Drop the empty-string fallback so the unknown file truly has no match
  const rows = SEEDED_ROWS.filter((r) => r.pattern !== '')
  const files = [
    { filename: 'devdocs_en_python_2026-02.zim', sizeBytes: 100 * 1024 * 1024 },
    { filename: 'something_unknown_2026-02.zim', sizeBytes: 50 * 1024 * 1024 },
  ]
  const out = estimateBatch(files, rows)
  assert.equal(out.totalChunks, 110_000) // only the matched file
  assert.equal(out.hasUnknown, true)
})

test('estimateBatch handles video-only ZIMs (0 chunks/MB) without flagging hasUnknown', () => {
  // A 5 GB video ZIM matches the registry with 0 chunks/MB; that is a
  // *known* value, not an unknown — totals should be 0 and hasUnknown false.
  const files = [
    { filename: 'lrnselfreliance_en_all_2025-12.zim', sizeBytes: 5 * 1024 * 1024 * 1024 },
  ]
  const out = estimateBatch(files, SEEDED_ROWS)
  assert.equal(out.totalChunks, 0)
  assert.equal(out.totalBytes, 0)
  assert.equal(out.hasUnknown, false)
})

test('estimateBatch on empty input returns zeros', () => {
  const out = estimateBatch([], SEEDED_ROWS)
  assert.equal(out.totalChunks, 0)
  assert.equal(out.totalBytes, 0)
  assert.equal(out.hasUnknown, false)
})

import * as assert from 'node:assert/strict'
import { test } from 'node:test'

import { decideWarnings } from '../../app/utils/kb_warning_decision.js'

const MB = 1024 * 1024

test('healthy file: chunks present and on-target → no warnings', () => {
  assert.deepEqual(
    decideWarnings({
      fileSizeBytes: 100 * MB,
      chunksInQdrant: 11_000,
      expectedChunks: 11_000,
    }),
    []
  )
})

test('healthy file: chunks slightly above expectation → no warnings', () => {
  assert.deepEqual(
    decideWarnings({
      fileSizeBytes: 100 * MB,
      chunksInQdrant: 12_000,
      expectedChunks: 11_000,
    }),
    []
  )
})

test('Warning A: large file with 0 chunks (video-only ZIM)', () => {
  assert.deepEqual(
    decideWarnings({
      fileSizeBytes: 5 * 1024 * MB,
      chunksInQdrant: 0,
      expectedChunks: 0,
    }),
    [{ kind: 'zero_chunks', fileSizeBytes: 5 * 1024 * MB }]
  )
})

test('Warning A: small empty file is silently ignored (under 100 MB threshold)', () => {
  // A user uploads a 5 KB placeholder.txt that produces nothing → not worth a banner
  assert.deepEqual(
    decideWarnings({
      fileSizeBytes: 5 * 1024, // 5 KB
      chunksInQdrant: 0,
      expectedChunks: null,
    }),
    []
  )
})

test('Warning B: partial stall — chunks well below expectation', () => {
  assert.deepEqual(
    decideWarnings({
      fileSizeBytes: 1000 * MB,
      chunksInQdrant: 266,
      expectedChunks: 600_000,
    }),
    [{ kind: 'partial_stall', chunksEmbedded: 266, chunksExpected: 600_000 }]
  )
})

test('Warning B: chunks just under 50% of expected → triggers', () => {
  assert.deepEqual(
    decideWarnings({
      fileSizeBytes: 100 * MB,
      chunksInQdrant: 4_999,
      expectedChunks: 10_000,
    }),
    [{ kind: 'partial_stall', chunksEmbedded: 4_999, chunksExpected: 10_000 }]
  )
})

test('Warning B: chunks at exactly 50% of expected → does NOT trigger', () => {
  // Strict less-than threshold leaves room for the boundary
  assert.deepEqual(
    decideWarnings({
      fileSizeBytes: 100 * MB,
      chunksInQdrant: 5_000,
      expectedChunks: 10_000,
    }),
    []
  )
})

test('Warning B suppressed when expectedChunks is null (registry miss)', () => {
  // Better to be silent than show a meaningless "266 of unknown" comparison
  assert.deepEqual(
    decideWarnings({
      fileSizeBytes: 100 * MB,
      chunksInQdrant: 266,
      expectedChunks: null,
    }),
    []
  )
})

test('Warning B suppressed when expectedChunks is 0 (video-only registry entry)', () => {
  // A `lrnselfreliance_` row in the registry says "expect 0 chunks". A real
  // file matching it correctly producing 0 chunks must not trigger Warning B.
  assert.deepEqual(
    decideWarnings({
      fileSizeBytes: 500 * MB,
      chunksInQdrant: 0,
      expectedChunks: 0,
    }),
    // Note: Warning A triggers here because file > 100 MB and chunks = 0
    [{ kind: 'zero_chunks', fileSizeBytes: 500 * MB }]
  )
})

test('Both warnings can fire on the same file in principle', () => {
  // Edge case: huge file, 0 chunks, but ratio registry expected 100k.
  // Warning A fires (large + zero), Warning B suppressed (chunksInQdrant must be > 0).
  // This documents the chunksInQdrant > 0 guard on Warning B.
  assert.deepEqual(
    decideWarnings({
      fileSizeBytes: 1000 * MB,
      chunksInQdrant: 0,
      expectedChunks: 100_000,
    }),
    [{ kind: 'zero_chunks', fileSizeBytes: 1000 * MB }]
  )
})

/**
 * Dashboard link tiles: URL normalisation and the icon allowlist.
 *
 * The URL rules matter beyond tidiness. `normalizeCustomUrl` restricting the
 * result to http(s) is the only thing stopping a `javascript:` or `data:` URL
 * being stored and later rendered into an href, so the rejection cases below are
 * a security boundary rather than input hygiene.
 *
 * Pure functions only, no MySQL, Redis, Qdrant or Ollama needed:
 *   npm run test:unit
 */
import * as assert from 'node:assert/strict'
import { test } from 'node:test'

import { normalizeCustomUrl } from '../../app/validators/system.js'
import {
  DEFAULT_LINK_TILE_ICON,
  LINK_TILE_ICONS,
  isLinkTileIcon,
} from '../../constants/link_tile_icons.js'
import {
  DEFAULT_LINK_TILE_COLOR,
  LINK_TILE_COLORS,
  LINK_TILE_COLOR_IDS,
  linkTileColor,
} from '../../constants/link_tile_colors.js'

test('a bare host:port gains http, which is what most LAN devices need', () => {
  assert.equal(normalizeCustomUrl('192.168.1.50:8080'), 'http://192.168.1.50:8080/')
  assert.equal(normalizeCustomUrl('nas.local'), 'http://nas.local/')
})

test('an explicit https scheme is preserved rather than downgraded', () => {
  assert.equal(normalizeCustomUrl('https://nas.local'), 'https://nas.local/')
  assert.equal(normalizeCustomUrl('https://nas.local:9443'), 'https://nas.local:9443/')
})

test('a path survives normalisation', () => {
  assert.equal(normalizeCustomUrl('192.168.1.50:8080/admin'), 'http://192.168.1.50:8080/admin')
  assert.equal(normalizeCustomUrl('https://nas.local/ui/dashboard'), 'https://nas.local/ui/dashboard')
})

test('a query string and port are both kept', () => {
  assert.equal(
    normalizeCustomUrl('http://10.0.0.5:3000/app?tab=media'),
    'http://10.0.0.5:3000/app?tab=media'
  )
})

test('surrounding whitespace is trimmed', () => {
  assert.equal(normalizeCustomUrl('   192.168.1.50:8080   '), 'http://192.168.1.50:8080/')
})

test('empty input is null, not an error', () => {
  // The caller treats null as "no URL given" and refuses to save, rather than
  // storing a tile that goes nowhere.
  assert.equal(normalizeCustomUrl(''), null)
  assert.equal(normalizeCustomUrl('   '), null)
  assert.equal(normalizeCustomUrl(null), null)
  assert.equal(normalizeCustomUrl(undefined), null)
})

test('script-bearing schemes are rejected, which is the XSS boundary', () => {
  // These are the ones that matter: a stored javascript:/data: value would later
  // be rendered into an href. They are refused because prefixing http:// leaves a
  // non-numeric "port", which makes new URL() throw.
  assert.equal(normalizeCustomUrl('javascript:alert(1)'), null)
  assert.equal(normalizeCustomUrl('JAVASCRIPT:alert(1)'), null)
  assert.equal(normalizeCustomUrl('  javascript:alert(1)'), null)
  assert.equal(normalizeCustomUrl('data:text/html,<script>alert(1)</script>'), null)
  assert.equal(normalizeCustomUrl('vbscript:msgbox'), null)
})

test('file: and ftp: are mangled into harmless http URLs rather than rejected', () => {
  // Documenting existing shared behaviour rather than endorsing it. Neither
  // scheme survives: both end up as an http URL pointing at a host named "file"
  // or "ftp", which goes nowhere and cannot execute anything. It is a usability
  // wart, not a security hole, and normalizeCustomUrl is shared with the custom
  // app URL feature, so it is not changed here.
  assert.equal(normalizeCustomUrl('file:///etc/passwd'), 'http://file///etc/passwd')
  assert.equal(normalizeCustomUrl('ftp://example.com'), 'http://ftp//example.com')
})

test('a scheme in mixed case is still recognised as http(s)', () => {
  // The scheme test is case-insensitive, so this must not be double-prefixed
  // into "http://HTTPS://nas.local".
  assert.equal(normalizeCustomUrl('HTTPS://nas.local'), 'https://nas.local/')
})

test('the icon set is exactly 36, so the picker fills a 6x6 grid', () => {
  assert.equal(LINK_TILE_ICONS.length, 36)
  assert.equal(new Set(LINK_TILE_ICONS).size, 36, 'no duplicates')
})

test('isLinkTileIcon accepts only names in the set', () => {
  assert.equal(isLinkTileIcon('IconServer'), true)
  assert.equal(isLinkTileIcon(DEFAULT_LINK_TILE_ICON), true)
  // Real Tabler icons that are deliberately not offered must still be refused,
  // otherwise the server would store a name the picker cannot round-trip.
  assert.equal(isLinkTileIcon('IconTrash'), false)
  assert.equal(isLinkTileIcon('IconNotARealIcon'), false)
  assert.equal(isLinkTileIcon(''), false)
  assert.equal(isLinkTileIcon(null), false)
  assert.equal(isLinkTileIcon(42), false)
})

test('the default icon is part of the offered set', () => {
  assert.ok((LINK_TILE_ICONS as readonly string[]).includes(DEFAULT_LINK_TILE_ICON))
})

test('link tile colors resolve from the brand palette', () => {
  // Unknown, null and empty all fall back rather than rendering an untinted card.
  assert.equal(linkTileColor('orange').id, 'orange')
  assert.equal(linkTileColor(null).id, DEFAULT_LINK_TILE_COLOR)
  assert.equal(linkTileColor('chartreuse').id, DEFAULT_LINK_TILE_COLOR)
})

test('every link tile color ships complete, literal Tailwind classes', () => {
  // Tailwind scans for literal class strings, so an interpolated name would be
  // dropped from the build and the tile would render untinted.
  for (const option of LINK_TILE_COLORS) {
    assert.ok(option.border.startsWith('border-desert-'), option.id)
    assert.ok(option.bg.startsWith('bg-desert-'), option.id)
    assert.ok(option.marker.startsWith('text-desert-'), option.id)
    // The swatch is the same color solid; a tint that works on a card is
    // indistinguishable at 28px.
    assert.ok(option.swatch.startsWith('bg-desert-'), option.id)
    assert.ok(!option.swatch.includes('/'), `${option.id} swatch must be solid`)
    assert.ok(
      !`${option.border}${option.bg}${option.marker}${option.swatch}`.includes('${'),
      option.id
    )
  }
})

