import * as assert from 'node:assert/strict'
import { test } from 'node:test'

import { assertNotPrivateUrl } from '../../app/validators/common.js'

const expectBlocked = (url: string) => {
  assert.throws(() => assertNotPrivateUrl(url), /loopback or link-local/)
}

const expectAllowed = (url: string) => {
  assert.doesNotThrow(() => assertNotPrivateUrl(url))
}

test('blocks loopback and unspecified IPv4 literals', () => {
  expectBlocked('http://127.0.0.1/file.zim')
  expectBlocked('http://127.1.2.3/file.zim')
  expectBlocked('http://0.0.0.0/file.zim')
  // Alternate encodings normalized to 127.0.0.1 / 0.0.0.0 by the WHATWG URL parser
  expectBlocked('http://0177.0.0.1/file.zim')
  expectBlocked('http://2130706433/file.zim')
  expectBlocked('http://0/file.zim')
})

test('blocks link-local IPv4 literals including cloud metadata', () => {
  expectBlocked('http://169.254.169.254/latest/meta-data/')
  expectBlocked('http://169.254.1.1/file.zim')
})

test('blocks IPv6 loopback, link-local, unspecified, and IPv4-mapped loopback', () => {
  expectBlocked('http://[::1]/file.zim')
  expectBlocked('http://[fe80::1]/file.zim')
  expectBlocked('http://[::]/file.zim')
  expectBlocked('http://[::ffff:127.0.0.1]/file.zim')
  expectBlocked('http://[::ffff:7f00:1]/file.zim')
})

test('blocks localhost, including mixed-case and trailing-root-dot forms (#911)', () => {
  expectBlocked('http://localhost/file.zim')
  expectBlocked('http://LOCALHOST/file.zim')
  expectBlocked('http://localhost./file.zim')
  expectBlocked('http://LocalHost./file.zim')
})

test('allows RFC1918 LAN literals, bare LAN hostnames, and public FQDNs', () => {
  expectAllowed('http://10.0.0.2/file.zim')
  expectAllowed('http://172.16.0.2/file.zim')
  expectAllowed('http://192.168.1.10/file.zim')
  expectAllowed('http://nomad3/file.zim')
  expectAllowed('http://my-nas.local/file.zim')
  expectAllowed('https://downloads.example.com/file.zim')
  // A mapped *public* IP must not be blocked
  expectAllowed('http://[::ffff:8.8.8.8]/file.zim')
})

import * as assert from 'node:assert/strict'
import { test } from 'node:test'

import {
  DEFAULT_LOCK_DURATION,
  LONG_LOCK_DURATION,
  stallOptionsForQueue,
} from '../../app/utils/queue_stall_options.js'

const QUEUES = {
  embedFile: 'file-embeddings',
  download: 'downloads',
  drugDownload: 'drug-download',
  drugIngest: 'drug-ingest',
}

const optionsFor = (queue: string) => stallOptionsForQueue(queue, QUEUES)

test('queues without an entry keep the default lock and BullMQ default maxStalledCount', () => {
  for (const queue of ['benchmarks', 'model-downloads', 'update-checks', 'pmtiles-extracts']) {
    assert.deepEqual(optionsFor(queue), { lockDuration: DEFAULT_LOCK_DURATION })
  }
})

test('an unlisted queue leaves maxStalledCount unset rather than setting it to a value', () => {
  // The caller spreads this key only when it is not undefined, so an explicit
  // value here would silently change every other queue's behaviour.
  assert.equal('maxStalledCount' in optionsFor('benchmarks'), false)
})

/**
 * Regression: #1269. Embedding is a self-continuing chain, so a stalled-recovery
 * re-queue runs a second chain alongside a live one, and both write fresh Qdrant
 * points. Failing on the first stall is the only safe option.
 */
test('file-embeddings never auto-recovers a stalled job', () => {
  const opts = optionsFor(QUEUES.embedFile)
  assert.equal(opts.maxStalledCount, 0, 'must fail on the first stall, not re-queue')
  assert.equal(opts.lockDuration, LONG_LOCK_DURATION)
})

test('maxStalledCount 0 is distinguishable from unset', () => {
  // `stalledCount > maxStalledCount` after an increment: 0 fails on the first
  // stall, BullMQ's default of 1 re-queues once first. Guarding against a
  // refactor that treats a falsy 0 as "not configured".
  const embed = optionsFor(QUEUES.embedFile)
  assert.equal(embed.maxStalledCount, 0)
  assert.notEqual(embed.maxStalledCount, undefined)
})

/**
 * Regression: #1203. A download is resumable, so recovery is safe, and the
 * default maxStalledCount of 1 was failing jobs outright and bypassing their
 * own `attempts: 10` policy.
 */
test('downloads tolerate stalls instead of failing outright', () => {
  assert.deepEqual(optionsFor(QUEUES.download), {
    lockDuration: LONG_LOCK_DURATION,
    maxStalledCount: 3,
  })
})

test('the two long-running queues take opposite stall policies', () => {
  const embed = optionsFor(QUEUES.embedFile)
  const download = optionsFor(QUEUES.download)
  assert.equal(embed.lockDuration, download.lockDuration)
  assert.notEqual(
    embed.maxStalledCount,
    download.maxStalledCount,
    'non-idempotent chain and resumable download must not share a recovery policy'
  )
})

test('the drug queues are unchanged', () => {
  for (const queue of [QUEUES.drugDownload, QUEUES.drugIngest]) {
    assert.deepEqual(optionsFor(queue), {
      lockDuration: LONG_LOCK_DURATION,
      maxStalledCount: 3,
    })
  }
})

/**
 * The "Sources" list shown under an assistant answer (#1179).
 *
 * The rule these lock in is that a citation may only ever name a document the
 * model actually read. Offline there is no second opinion to check an answer
 * against, so a citation is the only provenance the user gets — and a wrong one
 * is worse than none, because it lends false weight to a fabricated answer.
 *
 * Pure functions only — no MySQL, Redis, Qdrant, or Ollama needed:
 *   npm run test:unit
 */
import * as assert from 'node:assert/strict'
import { test } from 'node:test'

import { buildCitations } from '../../app/utils/rag_prompt.js'

const chunk = (metadata: Record<string, any>) => ({ text: 'body', score: 0.5, metadata })

test('buildCitations collapses many chunks from one archive into a single entry', () => {
  const sources = buildCitations([
    chunk({ source: '/zim/survival.zim', archive_title: 'Survival Library' }),
    chunk({ source: '/zim/survival.zim', archive_title: 'Survival Library' }),
    chunk({ source: '/zim/survival.zim', archive_title: 'Survival Library' }),
  ])

  assert.equal(sources.length, 1)
  assert.equal(sources[0].title, 'Survival Library')
})

test('buildCitations dedupes on path, not title, so same-named archives stay distinct', () => {
  const sources = buildCitations([
    chunk({ source: '/zim/wikipedia_2024.zim', archive_title: 'Wikipedia' }),
    chunk({ source: '/zim/wikipedia_2026.zim', archive_title: 'Wikipedia' }),
  ])

  assert.equal(sources.length, 2)
  assert.deepEqual(
    sources.map((s) => s.source),
    ['/zim/wikipedia_2024.zim', '/zim/wikipedia_2026.zim']
  )
})

test('buildCitations prefers the archive title over per-article titles', () => {
  const [source] = buildCitations([
    chunk({
      source: '/zim/ifixit.zim',
      archive_title: 'iFixit Repair Guides',
      full_title: 'Replacing a MacBook battery',
      article_title: 'MacBook battery',
    }),
  ])

  assert.equal(source.title, 'iFixit Repair Guides')
})

test('buildCitations falls back through full_title then article_title', () => {
  assert.equal(
    buildCitations([chunk({ source: '/a.zim', full_title: 'Full', article_title: 'Article' })])[0]
      .title,
    'Full'
  )
  assert.equal(
    buildCitations([chunk({ source: '/b.zim', article_title: 'Article' })])[0].title,
    'Article'
  )
})

test('buildCitations names an untitled upload by its filename', () => {
  // A user-uploaded PDF carries no embedded metadata; the filename is what the
  // user chose and is the only label they will recognise.
  const [source] = buildCitations([chunk({ source: '/kb_uploads/well drilling notes.pdf' })])

  assert.equal(source.title, 'well drilling notes.pdf')
  assert.equal(source.source, '/kb_uploads/well drilling notes.pdf')
})

test('buildCitations carries the archive date when one is known', () => {
  const [withDate] = buildCitations([
    chunk({ source: '/zim/wiki.zim', archive_title: 'Wikipedia', archive_date: '2026-06' }),
  ])
  assert.equal(withDate.date, '2026-06')

  const [withoutDate] = buildCitations([chunk({ source: '/zim/wiki.zim', archive_title: 'Wikipedia' })])
  assert.equal(withoutDate.date, undefined)
})

test('buildCitations skips a chunk with neither a path nor a title', () => {
  // "Unknown source" is not a citation — it is a row the user cannot act on,
  // and it makes the answer look sourced when it is not.
  assert.deepEqual(buildCitations([chunk({ chunk_index: 3 })]), [])
})

test('buildCitations returns nothing when no context was injected', () => {
  // Retrieval skipped, or it declined because nothing cleared the relevance
  // floor. No context means no citations, not an empty-looking Sources header.
  assert.deepEqual(buildCitations([]), [])
})

test('buildCitations preserves injection order', () => {
  const sources = buildCitations([
    chunk({ source: '/zim/b.zim', archive_title: 'Second' }),
    chunk({ source: '/zim/a.zim', archive_title: 'First' }),
  ])

  assert.deepEqual(
    sources.map((s) => s.title),
    ['Second', 'First']
  )
})

/**
 * Characterization tests for the prompt-assembly helpers extracted out of
 * OllamaController into RagPipelineService.
 *
 * These lock in the *current* behaviour so any later deliberate change shows up
 * as a failing test rather than a silent shift in answer quality.
 *
 * Token budgeting moved out of this module: the estimate now lives in
 * `token_estimate.spec.ts` and the allocation in `context_budget.spec.ts`. What
 * remains here is model-size tiering and context-block rendering.
 *
 * Pure functions only — no MySQL, Redis, Qdrant, or Ollama needed:
 *   npm run test:unit
 */
import * as assert from 'node:assert/strict'
import { test } from 'node:test'

import {
  buildContextBlock,
  getContextLimitsForModel,
  type ContextLimitTier,
} from '../../app/utils/rag_prompt.js'

/** Mirrors RAG_CONTEXT_LIMITS in constants/ollama.ts. Passed in explicitly so
 *  these tests need no AdonisJS-flavoured imports, per the kb_ratio_lookup
 *  precedent — and so a change to the shipped tiers shows up here as a
 *  deliberate edit rather than a silently-passing test. */
const TIERS: ContextLimitTier[] = [
  { maxParams: 3, maxResults: 2, maxTokens: 1000 },
  { maxParams: 8, maxResults: 4, maxTokens: 2500 },
  { maxParams: Infinity, maxResults: 5, maxTokens: 0 },
]

const limits = (model: string) => getContextLimitsForModel(model, TIERS)

const chunk = (text: string, metadata: Record<string, any> = {}) => ({
  text,
  score: 0.5,
  metadata,
})

// --- getContextLimitsForModel ------------------------------------------------

test('context limits: 1-3B models get the tightest budget', () => {
  assert.deepEqual(limits('llama3.2:1b'), { maxResults: 2, maxTokens: 1000 })
  assert.deepEqual(limits('qwen2.5:3b'), { maxResults: 2, maxTokens: 1000 })
})

test('context limits: fractional sizes parse correctly', () => {
  // "1.5b" must read as 1.5, not 1 or 15 — it decides which tier the model lands in.
  assert.deepEqual(limits('qwen2.5:1.5b'), { maxResults: 2, maxTokens: 1000 })
})

test('context limits: 4-8B tier', () => {
  assert.deepEqual(limits('llama3.1:8b'), { maxResults: 4, maxTokens: 2500 })
})

test('context limits: 13B+ is uncapped', () => {
  assert.deepEqual(limits('llama2:70b'), { maxResults: 5, maxTokens: 0 })
})

test('context limits: unparseable model name is assumed to be 8B', () => {
  // Documented quirk, not an endorsement: "phi3" has no size token, so it is
  // handed the 4-8B budget regardless of what it actually is.
  assert.deepEqual(limits('phi3'), { maxResults: 4, maxTokens: 2500 })
})

test('context limits: quantization suffixes do not confuse the size parse', () => {
  assert.deepEqual(limits('llama3.1:8b-text-q4_1'), {
    maxResults: 4,
    maxTokens: 2500,
  })
})

// --- buildContextBlock -------------------------------------------------------

test('context block: numbers each chunk from 1', () => {
  const out = buildContextBlock([chunk('first'), chunk('second')])
  assert.equal(out, '[Context 1]\nfirst\n\n[Context 2]\nsecond')
})

test('context block: labels with full_title when present', () => {
  const out = buildContextBlock([chunk('body', { full_title: 'Water - Boiling' })])
  assert.equal(out, '[Context 1 — Water - Boiling]\nbody')
})

test('context block: falls back to article_title', () => {
  const out = buildContextBlock([chunk('body', { article_title: 'Water' })])
  assert.equal(out, '[Context 1 — Water]\nbody')
})

test('context block: full_title wins over article_title', () => {
  const out = buildContextBlock([chunk('body', { full_title: 'A - B', article_title: 'A' })])
  assert.equal(out, '[Context 1 — A - B]\nbody')
})

test('context block: never leaks the relevance score to the model', () => {
  // Deliberate: nomic cosine scores for genuinely relevant passages sit around
  // 0.4-0.6, and showing the model "42%" primes it to distrust correct context.
  const out = buildContextBlock([chunk('body', { source: 'f.md', semantic_score: 0.42 })])
  assert.ok(!out.includes('0.42'))
  assert.ok(!out.includes('42'))
})

/**
 * Interpretation of the `rag.minRelevance` setting.
 *
 * Every case that matters here is a value that should never have been stored —
 * a cleared row, a hand-edited string, a half-written migration. The rule these
 * lock in is that none of them may silently switch the relevance floor *off*:
 * losing the setting has to mean "use the recommended default", because the
 * failure is invisible (irrelevant passages quietly return to every answer)
 * rather than loud. The one value that does turn it off is an explicit 0, and
 * that has to keep working — it is a real choice offered in the UI.
 *
 * Pure functions only — no MySQL, Redis, Qdrant, or Ollama needed:
 *   npm run test:unit
 */
import * as assert from 'node:assert/strict'
import { test } from 'node:test'

import { applyRelevanceFloor, parseMinRelevance } from '../../app/utils/misc.js'

const DEFAULT = 0.6

test('min relevance: an unset setting uses the recommended default', () => {
  assert.equal(parseMinRelevance(null, DEFAULT), DEFAULT)
  assert.equal(parseMinRelevance(undefined, DEFAULT), DEFAULT)
})

test('min relevance: empty, whitespace and "auto" all count as unset', () => {
  // SystemService.updateSetting clears the row on an empty string, but a value
  // written before that behaviour (or by hand) must not read as 0.
  assert.equal(parseMinRelevance('', DEFAULT), DEFAULT)
  assert.equal(parseMinRelevance('   ', DEFAULT), DEFAULT)
  assert.equal(parseMinRelevance('auto', DEFAULT), DEFAULT)
})

test('min relevance: an unparseable value uses the default rather than disabling the floor', () => {
  assert.equal(parseMinRelevance('balanced', DEFAULT), DEFAULT)
  assert.equal(parseMinRelevance('NaN', DEFAULT), DEFAULT)
  assert.equal(parseMinRelevance('0.6.1', DEFAULT), DEFAULT)
})

test('min relevance: an explicit 0 turns the floor off and is not treated as unset', () => {
  assert.equal(parseMinRelevance('0', DEFAULT), 0)
  assert.equal(parseMinRelevance('0.0', DEFAULT), 0)
})

test('min relevance: a valid value is used as written', () => {
  assert.equal(parseMinRelevance('0.5', DEFAULT), 0.5)
  assert.equal(parseMinRelevance('0.68', DEFAULT), 0.68)
  assert.equal(parseMinRelevance(' 0.55 ', DEFAULT), 0.55)
  assert.equal(parseMinRelevance('1', DEFAULT), 1)
})

test('min relevance: out-of-range values clamp instead of being rejected', () => {
  // The validator rejects these at the API, so reaching here means the row was
  // written some other way. Clamping keeps retrieval working on a value that is
  // at least meaningful, where a raw -5 would floor nothing and a raw 40 would
  // floor everything.
  assert.equal(parseMinRelevance('-5', DEFAULT), 0)
  assert.equal(parseMinRelevance('40', DEFAULT), 1)
})

const ranked = (...scores: number[]) => scores.map((finalScore, i) => ({ finalScore, id: `c${i}` }))

test('relevance floor: keeps chunks at or above the floor', () => {
  // Boundary inclusive: a chunk scoring exactly the floor is on the right side
  // of it. The presets are round numbers, so this edge is reachable.
  const { survivors, belowFloor } = applyRelevanceFloor(ranked(0.8, 0.6, 0.59), 0.6)
  assert.deepEqual(survivors.map((s) => s.id), ['c0', 'c1'])
  assert.equal(belowFloor, 1)
})

test('relevance floor: nothing clearing it returns an empty list, not the best of a bad set', () => {
  // The whole point of the item. Retrieval declining is what lets the prompt
  // stop asking a 3B model to silently judge relevance for us.
  const { survivors, belowFloor } = applyRelevanceFloor(ranked(0.55, 0.5, 0.42), 0.6)
  assert.deepEqual(survivors, [])
  assert.equal(belowFloor, 3)
})

test('relevance floor: a floor of 0 is a pass-through', () => {
  // The "Off" preset, and the default for callers that predate the parameter.
  const results = ranked(0.9, 0.1)
  const { survivors, belowFloor } = applyRelevanceFloor(results, 0)
  assert.equal(survivors, results)
  assert.equal(belowFloor, 0)
})

test('relevance floor: an empty candidate list stays empty and reports nothing dropped', () => {
  // "The knowledge base had no match above the Qdrant threshold" and "the floor
  // rejected everything" are different states, and the retrieval-status UX needs
  // to tell them apart — so an empty input must not report phantom drops.
  const { survivors, belowFloor } = applyRelevanceFloor(ranked(), 0.6)
  assert.deepEqual(survivors, [])
  assert.equal(belowFloor, 0)
})

/**
 * The `rag.enabled` off-switch, at the level that actually matters: what
 * buildPrompt does and does not call.
 *
 * Turning retrieval off is a resource decision, so "no context injected" is
 * only half the contract — the point is that none of the three expensive steps
 * (hasDocuments, the query-rewrite LLM call, the Qdrant search) run at all.
 * These tests count calls, not just output.
 *
 * Japa suite (not the plain-node `test:unit` runner): RagPipelineService pulls
 * in the AdonisJS container, so it needs the ignited app that `node ace test`
 * provides. Run with:
 *   node ace test --suites=unit --files=rag_retrieval_toggle
 *
 * Deliberately NOT named rag_pipeline_*: that glob is what `npm run test:eval`
 * feeds to the plain-node runner, which cannot boot Adonis.
 */
import { test } from '@japa/runner'
import { RagPipelineService } from '#services/rag_pipeline_service'
import { SYSTEM_PROMPTS } from '../../constants/ollama.js'
import type { OllamaChatMessage } from '../../types/ollama.js'
import type { RetrievedChunk } from '../../types/rag.js'

/** Records every call so the tests can assert on what was *not* run. */
function makeFakes(
  opts: {
    nomadMd?: string | null
    searchResults?: RetrievedChunk[]
    /** What the `rag.relevanceCheck` setting resolves to. Null (off) by default. */
    checkModel?: string | null
    /** The check's verdict when it runs. */
    onTopic?: boolean
  } = {}
) {
  const calls = { hasDocuments: 0, search: 0, chat: 0, judge: 0 }
  const judged = { question: '', model: '' }
  const args = { minFinalScore: undefined as number | undefined }

  const ragService = {
    async hasDocuments() {
      calls.hasDocuments++
      return true
    },
    async searchSimilarDocuments(
      _query: string,
      _limit: number,
      _scoreThreshold: number,
      _collection: string | undefined,
      _stagesOut: unknown,
      minFinalScore: number,
      floorOut?: { candidates: number; belowFloor: number }
    ) {
      calls.search++
      args.minFinalScore = minFinalScore
      const results =
        opts.searchResults ?? [{ text: 'retrieved body', score: 0.9, metadata: { full_title: 'A Doc' } }]
      // Stand in for the real floor: whatever the fake was told to return is
      // what survived, and anything it was told to withhold is what did not.
      if (floorOut) {
        floorOut.candidates = 3
        floorOut.belowFloor = 3 - results.length
      }
      return results
    },
  }

  const ollamaService = {
    async chat() {
      calls.chat++
      return { message: { content: 'rewritten query' } }
    },
    async getModelInfo() {
      return { hasThinking: false, parameterSize: '8.0B' }
    },
    async getModels() {
      return []
    },
    async checkModelHasThinking() {
      return false
    },
  }

  const nomadMdService = {
    async getSystemPrompt() {
      return opts.nomadMd ?? null
    },
  }

  // A fixed window keeps these tests about the toggle rather than about
  // hardware detection; the budget planner is covered by context_budget.spec.ts.
  const contextWindowService = {
    async windowFor() {
      return 8192
    },
  }

  const tokenCalibration = {
    async ratioFor() {
      return 1
    },
  }

  // Off unless a test turns it on, matching the setting's default.
  const relevanceJudge = {
    async resolveModel() {
      return opts.checkModel ?? null
    },
    async judge(question: string, chunks: RetrievedChunk[], model: string) {
      calls.judge++
      judged.question = question
      judged.model = model
      const onTopic = opts.onTopic ?? true
      return {
        kept: onTopic ? chunks : [],
        rejected: onTopic ? 0 : chunks.length,
        judged: true,
        ms: 7,
      }
    },
  }

  const service = new RagPipelineService(
    ollamaService as any,
    ragService as any,
    nomadMdService as any,
    contextWindowService as any,
    tokenCalibration as any,
    relevanceJudge as any
  )

  return { service, calls, args, judged }
}

const userTurn: OllamaChatMessage[] = [{ role: 'user', content: 'how do I purify water?' }]

const systemContents = (messages: OllamaChatMessage[]) =>
  messages.filter((m) => m.role === 'system').map((m) => m.content)

test.group('buildPrompt | skipRetrieval', () => {
  test('skips every expensive step when retrieval is disabled', async ({ assert }) => {
    const { service, calls } = makeFakes()

    const trace = await service.buildPrompt(userTurn, 'llama3.1:8b', { skipRetrieval: true })

    // The whole point of the toggle: nothing reaches Qdrant or the LLM.
    assert.equal(calls.hasDocuments, 0)
    assert.equal(calls.search, 0)
    assert.equal(calls.chat, 0)

    // ...and no knowledge base context lands in the prompt.
    assert.deepEqual(trace.retrieved, [])
    assert.deepEqual(trace.injected, [])
    assert.isNull(trace.rewrittenQuery)
    assert.isFalse(trace.didRewrite)
    assert.isFalse(systemContents(trace.messages).some((c) => c.includes('[Context 1')))
  })

  test('still injects the default system prompt and NOMAD.md when disabled', async ({ assert }) => {
    // Neither of these is RAG; turning retrieval off must not silently strip
    // the user's persistent instructions or the formatting prompt.
    const { service } = makeFakes({ nomadMd: 'Always answer in metric units.' })

    const trace = await service.buildPrompt(userTurn, 'llama3.1:8b', { skipRetrieval: true })

    const systems = systemContents(trace.messages)
    assert.include(systems, SYSTEM_PROMPTS.default)
    assert.include(systems, 'Always answer in metric units.')
  })

  test('retrieves as normal when the option is omitted', async ({ assert }) => {
    // The eval harness never sets skipRetrieval. If this ever fails, every eval
    // run is silently scoring a no-retrieval pipeline.
    const { service, calls } = makeFakes()

    const trace = await service.buildPrompt(userTurn, 'llama3.1:8b', {})

    assert.equal(calls.hasDocuments, 1)
    assert.equal(calls.search, 1)
    assert.lengthOf(trace.retrieved, 1)
    assert.lengthOf(trace.injected, 1)
    assert.isTrue(systemContents(trace.messages).some((c) => c.includes('[Context 1')))
  })

  test('oracleContext still wins over skipRetrieval', async ({ assert }) => {
    // Both are bypasses; oracle mode supplies its own context and is checked
    // first, so an eval running in oracle mode is unaffected by the setting.
    const { service, calls } = makeFakes()
    const oracle = [{ text: 'oracle body', score: 1, metadata: {} }]

    const trace = await service.buildPrompt(userTurn, 'llama3.1:8b', {
      skipRetrieval: true,
      oracleContext: oracle,
    })

    assert.equal(calls.search, 0)
    assert.deepEqual(trace.retrieved, oracle)
    assert.lengthOf(trace.injected, 1)
  })
})

test.group('buildPrompt | relevance floor', () => {
  test('injects no context block when nothing clears the floor', async ({ assert }) => {
    // The point of the floor. Retrieval ran, found candidates, and declined them
    // all — so the model must be handed nothing rather than the best of a bad
    // set, which is what the rag_context prompt used to have to talk it out of.
    const { service, calls } = makeFakes({ searchResults: [] })

    const trace = await service.buildPrompt(userTurn, 'llama3.1:8b', { minFinalScore: 0.62 })

    assert.equal(calls.search, 1)
    assert.deepEqual(trace.retrieved, [])
    assert.deepEqual(trace.injected, [])
    assert.isFalse(systemContents(trace.messages).some((c) => c.includes('[Context 1')))
    // ...and the default system prompt is untouched: declining to retrieve is
    // not the same as turning the assistant off.
    assert.include(systemContents(trace.messages), SYSTEM_PROMPTS.default)
  })

  test('records the floor and the drop count on the trace', async ({ assert }) => {
    // "The knowledge base had no match at all" and "everything found was judged
    // irrelevant" are different things to tell a user, so the trace has to keep
    // them apart rather than both collapsing to an empty retrieved list.
    const { service } = makeFakes({ searchResults: [] })

    const trace = await service.buildPrompt(userTurn, 'llama3.1:8b', { minFinalScore: 0.62 })

    assert.equal(trace.minFinalScore, 0.62)
    assert.equal(trace.chunksBelowFloor, 3)
  })

  test('an explicit option overrides the rag.minRelevance setting', async ({ assert }) => {
    // What keeps the eval harness reproducible: it always passes a value, so a
    // slider set on one machine cannot move the numbers a baseline was recorded
    // against.
    const { service, args } = makeFakes()

    await service.buildPrompt(userTurn, 'llama3.1:8b', { minFinalScore: 0.9 })

    assert.equal(args.minFinalScore, 0.9)
  })
})

test.group('buildPrompt | relevance check', () => {
  test('does not run when the setting is off', async ({ assert }) => {
    // Off is the default: the check is a model call per turn and only pays off
    // on ~8B models, so it must cost nothing until someone opts in.
    const { service, calls } = makeFakes()

    const trace = await service.buildPrompt(userTurn, 'llama3.1:8b', {})

    assert.equal(calls.judge, 0)
    assert.isNull(trace.relevanceCheckModel)
    assert.lengthOf(trace.injected, 1)
  })

  test('an off-topic verdict leaves nothing to inject or cite', async ({ assert }) => {
    // #1341: the floor kept a chunk, the check says it is not about the
    // question, so the prompt gets no context block and the answer no sources.
    const { service, calls } = makeFakes({ checkModel: 'llama3:8b', onTopic: false })

    const trace = await service.buildPrompt(userTurn, 'llama3.1:8b', {})

    assert.equal(calls.judge, 1)
    assert.deepEqual(trace.retrieved, [])
    assert.deepEqual(trace.injected, [])
    assert.equal(trace.chunksRejectedByCheck, 1)
    assert.equal(trace.relevanceCheckModel, 'llama3:8b')
    assert.isFalse(systemContents(trace.messages).some((c) => c.includes('[Context 1')))
  })

  test('an on-topic verdict keeps what the floor kept', async ({ assert }) => {
    const { service } = makeFakes({ checkModel: 'llama3:8b', onTopic: true })

    const trace = await service.buildPrompt(userTurn, 'llama3.1:8b', {})

    assert.lengthOf(trace.injected, 1)
    assert.equal(trace.chunksRejectedByCheck, 0)
    assert.equal(trace.timings.relevanceCheckMs, 7)
  })

  test('judges the retrieval query, not the raw message', async ({ assert }) => {
    // On a follow-up the rewrite is the standalone question; judging "what about
    // the second one?" against the passages would reject everything.
    const { service, judged } = makeFakes({ checkModel: 'llama3:8b' })
    const conversation: OllamaChatMessage[] = [
      { role: 'user', content: 'how do I purify water?' },
      { role: 'assistant', content: 'Boil it or use chlorine.' },
      { role: 'user', content: 'how long for the first one?' },
    ]

    await service.buildPrompt(conversation, 'llama3.1:8b', {})

    assert.equal(judged.question, 'rewritten query')
  })

  test('an explicit null skips it whatever the setting says', async ({ assert }) => {
    // The eval harness pins it off so one machine's setting cannot move scores.
    const { service, calls } = makeFakes({ checkModel: 'llama3:8b', onTopic: false })

    const trace = await service.buildPrompt(userTurn, 'llama3.1:8b', { relevanceCheckModel: null })

    assert.equal(calls.judge, 0)
    assert.lengthOf(trace.injected, 1)
  })

  test('skips the call when the floor already left nothing', async ({ assert }) => {
    const { service, calls } = makeFakes({ checkModel: 'llama3:8b', searchResults: [] })

    await service.buildPrompt(userTurn, 'llama3.1:8b', { minFinalScore: 0.62 })

    assert.equal(calls.judge, 0)
  })
})

/**
 * The pure half of the retrieval relevance check (#1341).
 *
 * What these lock in: the setting stays off unless someone deliberately turned
 * it on, a verdict is only ever read from a well-formed object, and the judge
 * reads the part of a long chunk that is about the question rather than
 * whatever happens to come first.
 *
 * Pure functions only — no MySQL, Redis, Qdrant, or Ollama needed:
 *   npm run test:unit
 */
import * as assert from 'node:assert/strict'
import { test } from 'node:test'

import {
  buildJudgeInput,
  excerptFor,
  isRelevanceCheckEnabled,
  pickOnTopic,
} from '../../app/utils/relevance_judge.js'

test('relevance check: off unless explicitly on', () => {
  assert.equal(isRelevanceCheckEnabled(true), true)
  assert.equal(isRelevanceCheckEnabled('true'), true)
  // Unset, cleared, or anything odd must not start costing a model call per turn.
  for (const raw of [null, undefined, false, 'false', '', 'on', 'auto', 1]) {
    assert.equal(isRelevanceCheckEnabled(raw), false, `expected ${JSON.stringify(raw)} to read as off`)
  }
})

test('relevance check: a verdict is read only from a boolean on_topic', () => {
  assert.equal(pickOnTopic({ on_topic: true }), true)
  assert.equal(pickOnTopic({ on_topic: false }), false)
  // A string "false" is truthy; treating it as a verdict would keep chunks the
  // model rejected. Anything that isn't a real boolean is no verdict at all.
  assert.equal(pickOnTopic({ on_topic: 'false' }), null)
  assert.equal(pickOnTopic({}), null)
  assert.equal(pickOnTopic(null), null)
})

test('excerpt: a short passage is passed through whole', () => {
  assert.equal(excerptFor('Boil   water\nfor one minute.', 'boil water', 100), 'Boil water for one minute.')
})

test('excerpt: a long passage is cut to the window about the question', () => {
  // The answer sits at the end of a long chunk. Taking the start would show the
  // judge only filler, and it would rightly say the passage is off-topic.
  const filler = 'Lorem ipsum dolor sit amet. '.repeat(40)
  const text = `${filler}A counterpoise for a two meter handheld is a wire about 19 inches long.`
  const excerpt = excerptFor(text, 'How long should a counterpoise be?', 200)

  assert.match(excerpt, /counterpoise for a two meter handheld/)
  assert.ok(excerpt.length <= 202, 'excerpt must stay within the window plus ellipses')
  assert.ok(excerpt.startsWith('…'), 'a window that skips the start says so')
})

test('excerpt: with no term in the passage, falls back to the start', () => {
  const text = 'x'.repeat(500)
  assert.equal(excerptFor(text, 'unrelated question', 100), 'x'.repeat(100) + '…')
})

test('judge input: question first, then each passage under its key and title', () => {
  const input = buildJudgeInput('  What is declination? ', [
    { text: 'The angle between true and magnetic north.', title: 'Map and Compass' },
    { text: 'Unrelated text.' },
  ])

  assert.equal(
    input,
    'Question: What is declination?\n\n' +
      'p1 (from "Map and Compass"):\nThe angle between true and magnetic north.\n\n' +
      'p2:\nUnrelated text.'
  )
})

/**
 * Sampler resolution for the Response Style setting.
 *
 * Chat sent no sampler settings at all before this, so every one of these paths
 * is new and the interesting cases are the ones where a value has two sources:
 * a model that declares its own parameters, a caller that pins temperature, and
 * a transport that cannot carry min_p.
 *
 * Pure functions only — no MySQL, Redis, Qdrant, or Ollama needed:
 *   npm run test:unit
 */
import * as assert from 'node:assert/strict'
import { test } from 'node:test'

import { SAMPLER_PRESETS } from '../../constants/ollama.js'
import {
  compatSamplerParams,
  nativeSamplerOptions,
  parseResponseStyle,
  readModelfileSamplers,
  resolveSamplerProfile,
} from '../../app/utils/sampler.js'

// --- parseResponseStyle -------------------------------------------------------

test('an unset style is auto, not off', () => {
  // The whole point of the setting is that the default samples. Falling back to
  // "send nothing" would restore the bug and look identical in the UI.
  assert.equal(parseResponseStyle(null), 'auto')
  assert.equal(parseResponseStyle(undefined), 'auto')
  assert.equal(parseResponseStyle(''), 'auto')
  assert.equal(parseResponseStyle('   '), 'auto')
})

test('a stored style round-trips', () => {
  assert.equal(parseResponseStyle('auto'), 'auto')
  assert.equal(parseResponseStyle('focused'), 'focused')
  assert.equal(parseResponseStyle('creative'), 'creative')
  assert.equal(parseResponseStyle('off'), 'off')
})

test('case and surrounding whitespace are tolerated', () => {
  assert.equal(parseResponseStyle('  Focused '), 'focused')
})

test('an unrecognised value falls back to auto rather than disabling sampling', () => {
  assert.equal(parseResponseStyle('turbo'), 'auto')
  assert.equal(parseResponseStyle('0.7'), 'auto')
})

// --- readModelfileSamplers ----------------------------------------------------

const QWEN_PARAMETERS = [
  'repeat_penalty                 1',
  'stop                           "<|im_start|>"',
  'stop                           "<|im_end|>"',
  'temperature                    0.6',
  'top_k                          20',
  'top_p                          0.95',
].join('\n')

test('reads the sampler parameters a model author baked in', () => {
  assert.deepEqual(readModelfileSamplers(QWEN_PARAMETERS), {
    repeatPenalty: 1,
    temperature: 0.6,
    topK: 20,
    topP: 0.95,
  })
})

test('a model that declares nothing yields an empty profile', () => {
  assert.deepEqual(readModelfileSamplers('num_ctx                        8192'), {})
  assert.deepEqual(readModelfileSamplers(undefined), {})
  assert.deepEqual(readModelfileSamplers(null), {})
  assert.deepEqual(readModelfileSamplers(42), {})
})

test('a repeated PARAMETER line takes its last value, as Ollama does', () => {
  assert.deepEqual(readModelfileSamplers('temperature 0.2\ntemperature 0.9'), { temperature: 0.9 })
})

test('a non-numeric or negative value is ignored rather than propagated', () => {
  assert.deepEqual(readModelfileSamplers('temperature abc\ntop_k -5'), {})
})

test('a key embedded in another key name is not matched', () => {
  // `min_p` must not be read out of a hypothetical `xmin_p` line, and the
  // trailing-anchor is what stops `top_p 0.9 # comment` scoring as 0.9.
  assert.deepEqual(readModelfileSamplers('xtop_p 0.5'), {})
  assert.deepEqual(readModelfileSamplers('top_p 0.9 trailing'), {})
})

// --- resolveSamplerProfile ----------------------------------------------------

test('off resolves to no profile at all', () => {
  assert.equal(resolveSamplerProfile('off'), undefined)
  assert.equal(resolveSamplerProfile('off', { temperature: 0.6 }), undefined)
})

test('auto on a model that declares nothing is the baseline preset', () => {
  assert.deepEqual(resolveSamplerProfile('auto'), SAMPLER_PRESETS.auto)
  assert.deepEqual(resolveSamplerProfile('auto', {}), SAMPLER_PRESETS.auto)
})

test('auto lets the model author win key by key, and still supplies min_p', () => {
  const resolved = resolveSamplerProfile('auto', readModelfileSamplers(QWEN_PARAMETERS))
  assert.equal(resolved?.temperature, 0.6)
  assert.equal(resolved?.topK, 20)
  assert.equal(resolved?.topP, 0.95)
  assert.equal(resolved?.repeatPenalty, 1)
  // The one value no modelfile in the wild sets, and the reason this exists.
  assert.equal(resolved?.minP, SAMPLER_PRESETS.auto.minP)
})

test("auto sends the author's nucleus on the compat transport too", () => {
  // A declared top_p is a better stand-in for the missing min_p than the
  // preset's generic fallback.
  const resolved = resolveSamplerProfile('auto', { topP: 0.95 })
  assert.equal(resolved?.compatTopP, 0.95)
})

test('a style the user picked by name overrides the model, or it would do nothing', () => {
  const declared = readModelfileSamplers(QWEN_PARAMETERS)
  assert.deepEqual(resolveSamplerProfile('focused', declared), SAMPLER_PRESETS.focused)
  assert.deepEqual(resolveSamplerProfile('creative', declared), SAMPLER_PRESETS.creative)
})

test('resolving does not mutate the shared preset', () => {
  resolveSamplerProfile('auto', { temperature: 0.1, topP: 0.5 })
  assert.equal(SAMPLER_PRESETS.auto.temperature, 0.6)
  assert.equal(SAMPLER_PRESETS.auto.compatTopP, 0.9)
})

// --- transport mapping --------------------------------------------------------

test('the native path carries the truncation settings', () => {
  const options = nativeSamplerOptions(SAMPLER_PRESETS.auto)
  assert.deepEqual(options, {
    top_p: 1,
    top_k: 40,
    min_p: 0.05,
    repeat_penalty: 1.1,
  })
})

test('temperature is not a sampler option, so an explicit caller value still wins', () => {
  // OllamaService applies chatRequest.temperature after this, and the eval
  // harness and the grammar-constrained task calls both depend on that ordering.
  assert.equal('temperature' in nativeSamplerOptions(SAMPLER_PRESETS.focused), false)
})

test('no profile means no options, which is what off has to produce', () => {
  assert.deepEqual(nativeSamplerOptions(undefined), {})
  assert.deepEqual(compatSamplerParams(undefined), {})
})

test('the compat path substitutes a real nucleus for the min_p it cannot send', () => {
  // Passing topP straight through would be top_p 1.0 with no min_p behind it:
  // the raw distribution, which is worse than the 0.9 default it replaced.
  assert.deepEqual(compatSamplerParams(SAMPLER_PRESETS.auto), { top_p: 0.9 })
  assert.deepEqual(compatSamplerParams(SAMPLER_PRESETS.focused), { top_p: 0.85 })
  assert.deepEqual(compatSamplerParams(SAMPLER_PRESETS.creative), { top_p: 0.95 })
})

test('the compat path sends nothing it has no equivalent for', () => {
  const params = compatSamplerParams(SAMPLER_PRESETS.auto)
  assert.deepEqual(Object.keys(params), ['top_p'])
})

test('a profile with no compat fallback falls back to its own top_p', () => {
  assert.deepEqual(compatSamplerParams({ topP: 0.8 }), { top_p: 0.8 })
})

test('every preset supplies min_p and a compat nucleus below 1', () => {
  // Two invariants worth failing a retune over: the preset that forgets min_p
  // is the bug this setting exists to fix, and a compat nucleus of 1 is the
  // untruncated distribution.
  for (const [name, preset] of Object.entries(SAMPLER_PRESETS)) {
    assert.ok(preset.minP !== undefined && preset.minP > 0, `${name} is missing min_p`)
    assert.ok(
      preset.compatTopP !== undefined && preset.compatTopP < 1,
      `${name} would sample the raw distribution on a compat backend`
    )
  }
})

import * as assert from 'node:assert/strict'
import { test } from 'node:test'

import {
  firstPublishedHostPort,
  mergeContainerConfigPreservingHostPorts,
  mergeUiLocationPreservingHostPort,
} from '../../app/utils/service_catalog_merge.js'

const config = (bindings: Record<string, string>, extra: Record<string, unknown> = {}) =>
  JSON.stringify({
    Image: 'ghcr.io/example/app:1.0.0',
    ...extra,
    HostConfig: {
      PortBindings: Object.fromEntries(
        Object.entries(bindings).map(([containerPort, hostPort]) => [
          containerPort,
          [{ HostPort: hostPort }],
        ])
      ),
    },
  })

// ── container_config ────────────────────────────────────────────────────────

test('keeps the live host port when it diverges from the catalog default', () => {
  const merged = mergeContainerConfigPreservingHostPorts(
    config({ '8080/tcp': '8090' }),
    config({ '8080/tcp': '9999' })
  )
  assert.equal(firstPublishedHostPort(merged), '9999')
})

test('applies other catalog changes while keeping the port', () => {
  const merged = mergeContainerConfigPreservingHostPorts(
    config({ '8080/tcp': '8090' }, { Image: 'ghcr.io/example/app:2.0.0' }),
    config({ '8080/tcp': '9999' }, { Image: 'ghcr.io/example/app:1.0.0' })
  )
  assert.equal(JSON.parse(merged).Image, 'ghcr.io/example/app:2.0.0')
  assert.equal(firstPublishedHostPort(merged), '9999')
})

test('returns the catalog value untouched when the port already matches', () => {
  const catalog = config({ '8080/tcp': '8090' })
  assert.equal(mergeContainerConfigPreservingHostPorts(catalog, config({ '8080/tcp': '8090' })), catalog)
})

test('a catalog change to the CONTAINER-side port wins', () => {
  // The app now listens on 3000 inside the container. The live 8080 binding is a
  // different key, so there is nothing to preserve and the catalog is authoritative.
  const merged = mergeContainerConfigPreservingHostPorts(
    config({ '3000/tcp': '8090' }),
    config({ '8080/tcp': '9999' })
  )
  assert.equal(firstPublishedHostPort(merged), '8090')
})

test('preserves each port independently on a multi-port app', () => {
  const merged = mergeContainerConfigPreservingHostPorts(
    config({ '8080/tcp': '8310', '8081/tcp': '8311' }),
    config({ '8080/tcp': '9310', '8081/tcp': '8311' })
  )
  const bindings = JSON.parse(merged).HostConfig.PortBindings
  assert.equal(bindings['8080/tcp'][0].HostPort, '9310')
  assert.equal(bindings['8081/tcp'][0].HostPort, '8311')
})

// `services.container_config` is a MySQL json column, so the live value arrives as
// an already-parsed OBJECT, not a string, despite the model typing it `string | null`.
// A string-only implementation passes every other test in this file and silently
// no-ops against a real database. Verified live before adding these.
test('accepts an already-parsed live config object (MySQL json column)', () => {
  const merged = mergeContainerConfigPreservingHostPorts(
    config({ '80/tcp': '8410' }),
    JSON.parse(config({ '80/tcp': '9410' }))
  )
  assert.equal(firstPublishedHostPort(merged), '9410')
})

test('ui_location honours a parsed live config object too', () => {
  assert.equal(
    mergeUiLocationPreservingHostPort('8410', '9410', JSON.parse(config({ '80/tcp': '9410' }))),
    '9410'
  )
})

test('unparseable or portless live config falls back to the catalog', () => {
  const catalog = config({ '8080/tcp': '8090' })
  assert.equal(mergeContainerConfigPreservingHostPorts(catalog, 'not json'), catalog)
  assert.equal(mergeContainerConfigPreservingHostPorts(catalog, null), catalog)
  assert.equal(mergeContainerConfigPreservingHostPorts(catalog, JSON.stringify({})), catalog)
})

// ── ui_location ─────────────────────────────────────────────────────────────

test('rewrites a bare port to the live one', () => {
  assert.equal(
    mergeUiLocationPreservingHostPort('8090', '9999', config({ '8080/tcp': '9999' })),
    '9999'
  )
})

test('takes the catalog scheme and the live port', () => {
  // Vaultwarden moved to https in the catalog; this install runs on 9480.
  assert.equal(
    mergeUiLocationPreservingHostPort('https:8480', '9480', config({ '80/tcp': '9480' })),
    'https:9480'
  )
})

test('a path ui_location is never rewritten', () => {
  assert.equal(mergeUiLocationPreservingHostPort('/chat', '/chat', null), '/chat')
  assert.equal(mergeUiLocationPreservingHostPort('/chat', '9999', config({ '80/tcp': '9999' })), '/chat')
})

// The third argument is the config the sync is about to WRITE, not the live row.
// When the catalog moves the container-side port, the port merge keeps nothing, so
// the link has to take the catalog port too. Feeding the live config here instead
// writes a row whose container binds 8090 while its Open button points at 9999.
test('follows the catalog when a container-side port change wins', () => {
  const catalogConfig = config({ '3000/tcp': '8090' })
  const liveConfig = config({ '8080/tcp': '9999' })
  const mergedConfig = mergeContainerConfigPreservingHostPorts(catalogConfig, liveConfig)

  assert.equal(firstPublishedHostPort(mergedConfig), '8090')
  assert.equal(mergeUiLocationPreservingHostPort('8090', '9999', mergedConfig), '8090')
})

test('a preserved host port still reaches ui_location through the merged config', () => {
  const mergedConfig = mergeContainerConfigPreservingHostPorts(
    config({ '8080/tcp': '8090' }),
    config({ '8080/tcp': '9999' })
  )
  assert.equal(mergeUiLocationPreservingHostPort('8090', '9999', mergedConfig), '9999')
})

test('ignores a live port the install does not actually publish', () => {
  // Stale or hand-edited ui_location: pinning the link to it would point the
  // Open button at a port with nothing behind it.
  assert.equal(
    mergeUiLocationPreservingHostPort('8090', '7777', config({ '8080/tcp': '8090' })),
    '8090'
  )
})

test('null or missing values fall back to the catalog', () => {
  assert.equal(mergeUiLocationPreservingHostPort('8090', null, null), '8090')
  assert.equal(mergeUiLocationPreservingHostPort(null, '9999', null), null)
})

