}

// Proxy da nuvem (RULES-LOCAL-JEV.1): na nuvem do Claude Code, o `fetch` do Node SEM proxy já
// recebeu por horas uma cópia velha da `main`; com `NODE_USE_ENV_PROXY=1` vem a atual. Quando há
// `HTTPS_PROXY` e a variável ainda não está ligada, o script se roda de novo como processo filho
// com ela ligada. No PC (sem `HTTPS_PROXY`) nada muda. Nunca lança.
import { spawn } from 'node:child_process';

const VARIAVEL_USAR_PROXY = 'NODE_USE_ENV_PROXY';
const VALOR_LIGADO = '1';
const CODIGO_FALHA_FILHO = 1;

/**
 * Diz se o ambiente tem proxy configurado e o uso dele ainda não foi ligado.
 * @param {Record<string, string|undefined>} ambiente Variáveis de ambiente.
 * @returns {boolean} true se vale rodar de novo com o proxy.
 */
function precisaDoProxy(ambiente) {
  const temProxy = Boolean(ambiente.HTTPS_PROXY || ambiente.https_proxy);
  return temProxy && ambiente[VARIAVEL_USAR_PROXY] !== VALOR_LIGADO;
}

/**
 * Roda o mesmo script como filho, com o proxy ligado, e espera o fim.
 * @returns {Promise<boolean>} true se o filho rodou até o fim; false se não conseguiu iniciar.
 */
function rodarFilho() {
  return new Promise((resolver) => {
    let filho;
    try {
      const ambiente = {
        ...process.env, [VARIAVEL_USAR_PROXY]: VALOR_LIGADO, NODE_NO_WARNINGS: '1',
      };
      filho = spawn(process.execPath, process.argv.slice(1), {
        env: ambiente, stdio: 'inherit',
      });
    } catch {
      resolver(false);
      return;
    }
    filho.once('error', () => resolver(false));
    filho.once('close', (codigo) => {
      process.exitCode = codigo ?? CODIGO_FALHA_FILHO;
      resolver(true);
    });
  });
}

/**
 * Se estiver na nuvem com proxy e sem `NODE_USE_ENV_PROXY=1`, roda este mesmo script de novo com
 * ele ligado (entrada e saída herdadas) e devolve true: quem chamou deve sair sem fazer mais nada.
 * @returns {Promise<boolean>} true se o filho já fez o trabalho; false para seguir normalmente.
 */
export async function rodarComProxySePreciso() {
  try {
    if (!precisaDoProxy(process.env)) return false;
    return await rodarFilho();
  } catch {
    return false;
  }
}

// Formato simplificado do quadro (`tasks/STATUS.md`, C55): detecção pelo conteúdo, leitura dos
// itens e reescrita de UM item (status, reserva ou nível), sem mexer no resto da linha.
// Só funções puras: nada aqui lê disco, usa Git ou escreve arquivo. Compartilhado pelo
// gerenciador, pelo MCP e pelo Jev; fica em `scripts/jev/` para ir junto no pacote do
// `rules-local` (o pacote só leva arquivos de `scripts/jev/`).
//
// Item da mãe:       `- #<ID> — [<título>](etapas/ETAPA-….md) · <status> · <Em uso por>`
// Item da subtarefa: `  - #<ID>.<n> — <título> · <status> · `<NIVEL>` · só <modelo> (<obs>)`
// A reserva da subtarefa vai numa observação entre parênteses; sem ela, a subtarefa está livre.

export const FORMATOS = Object.freeze({
  TABELA: 'tabela',
  SIMPLIFICADO: 'simplificado',
  VAZIO: 'vazio',
});
export const CODIGO_FORMATO_DESCONHECIDO = 'formato_desconhecido';
export const MENSAGEM_FORMATO_DESCONHECIDO =
  'Formato do quadro não reconhecido: nem tabela (cabeçalho "| Tarefa | … | Status | Em uso por |")'
  + ' nem índice simplificado ("- #<ID> — <título> · <status> · …"). Nada foi gravado.';
export const SEPARADOR = ' · ';
export const LIVRE = '—';

const MARCA_BOM = '﻿';
const SELETOR_VARIACAO = /️/g;
const EMOJIS_STATUS = ['⬜', '🔄', '✅', '⛔', '👀', '❌'];
const EMOJIS_PRIORIDADE = ['🔴', '🟠', '🟡', '🟢'];
const PADRAO_ITEM = /^(\s*)- (#[^\s:—]+(?:\s+(?:a|e|até)\s+#[^\s:—]+)*)\s+—\s+(.*)$/u;
const PADRAO_SECAO_TAREFAS = /^##\s+.*\bTarefas\b/iu;
const PADRAO_NOVA_SECAO = /^##\s/;
const PADRAO_CABECALHO_TAREFA = /^\|\s*\**\s*Tarefa\s*\**\s*\|/iu;
const PADRAO_LINK = /^\[(.*)\]\(([^)\s]+)\)$/u;
const PADRAO_NIVEL = /\b(LEVE|MEDIO|MÉDIO|PESADO)\b/u;
const PADRAO_NIVEL_CRASE = /^`[^`]*\b(?:LEVE|MEDIO|MÉDIO|PESADO)\b[^`]*`$/u;
const PADRAO_SEM_NIVEL = /^n[ií]vel a classificar/iu;
const PADRAO_SO_MODELO = /^s[oó]\s/iu;
const PADRAO_RESERVA = /\(desde\s+\d|\bdesde\s+\d{4}-\d{2}-\d{2}|🔒|trava especial/iu;
const PADRAO_LIVRE = /^livre$/iu;
const PADRAO_DEPENDENCIA =
  /depende\s+d[aeo]s?\s+((?:#?[\w.-]+)(?:\s*(?:,|\be\b)\s*#?[\w.-]+)*)/iu;
const PADRAO_SUFIXO_UUID = /-[0-9a-f]{8}(?:-[0-9a-f]{4,})*(?:-[0-9a-f]+)?$/iu;
const PADRAO_ETAPA_ARQUIVO = /ETAPA-(\d+-[0-9a-f]{8})/iu;
const PADRAO_FAIXA = /^(.*\.)(\d+)$/u;
const LIMITE_FAIXA = 500;
const ABRE = new Set(['(', '[']);
const FECHA = new Set([')', ']']);

/** Erro de quadro que não casa com nenhum formato (R2.3). */
export class ErroFormatoQuadro extends Error {
  /**
   * @param {string} [mensagem] Mensagem curta, sem conteúdo de tarefa.
   */
  constructor(mensagem = MENSAGEM_FORMATO_DESCONHECIDO) {
    super(mensagem);
    this.name = 'ErroFormatoQuadro';
    this.codigo = CODIGO_FORMATO_DESCONHECIDO;
  }
}

/**
 * Divide o texto em linhas (aceita LF e CRLF) e tira a marca BOM.
 * @param {string} texto Conteúdo do arquivo.
 * @returns {string[]} Linhas sem o fim de linha.
 */
function dividirLinhas(texto) {
  const semBom = String(texto ?? '').replace(new RegExp(`^${MARCA_BOM}`), '');
  return semBom.split(/\r?\n/);
}

/**
 * Faixa [inicio, fim) da seção "Tarefas" (até o próximo `## `); sem a seção, o arquivo todo.
 * @param {string[]} linhas Linhas do arquivo.
 * @returns {{inicio: number, fim: number, temSecao: boolean}} Faixa da seção.
 */
export function localizarSecaoTarefas(linhas) {
  const titulo = linhas.findIndex((linha) => PADRAO_SECAO_TAREFAS.test(linha));
  if (titulo < 0) return { inicio: 0, fim: linhas.length, temSecao: false };
  const proxima = linhas.findIndex((linha, i) => i > titulo && PADRAO_NOVA_SECAO.test(linha));
  return { inicio: titulo + 1, fim: proxima < 0 ? linhas.length : proxima, temSecao: true };
}

/**
 * Diz se o texto tem a linha de cabeçalho da tabela de tarefas (formato legado).
 * @param {string[]} linhas Linhas do arquivo.
 * @returns {boolean} true se houver `| Tarefa | …` com Status e Em uso por.
 */
function temCabecalhoDeTabela(linhas) {
  return linhas.some((linha) => {
    if (!PADRAO_CABECALHO_TAREFA.test(linha.trim())) return false;
    const normalizada = linha.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
    return normalizada.includes('status') && normalizada.includes('em uso por');
  });
}

/**
 * Descobre o formato do quadro pelo conteúdo.
 * @param {string} texto Conteúdo do `STATUS.md`.
 * @returns {string|null} Um valor de FORMATOS, ou null se não casar com nenhum.
 */
export function detectarFormato(texto) {
  const linhas = dividirLinhas(texto);
  if (temCabecalhoDeTabela(linhas)) return FORMATOS.TABELA;
  const secao = localizarSecaoTarefas(linhas);
  const trecho = linhas.slice(secao.inicio, secao.fim);
  if (trecho.some((linha) => PADRAO_ITEM.test(linha))) return FORMATOS.SIMPLIFICADO;
  if (linhas.every((linha) => linha.trim() === '')) return FORMATOS.VAZIO;
  const secaoSemTabela = secao.temSecao && !trecho.some((l) => l.trimStart().startsWith('|'));
  if (secaoSemTabela) return FORMATOS.SIMPLIFICADO;
  // Tabela sem cabeçalho (ex.: `task_complete.md` antigo): continua legada, como antes.
  const temLinhaDeTabela = linhas.some((linha) => linha.trimStart().startsWith('|'));
  return temLinhaDeTabela ? FORMATOS.TABELA : null;
}

/**
 * Diz se o texto está no formato simplificado.
 * @param {string} texto Conteúdo do `STATUS.md`.
 * @returns {boolean} true para o índice simplificado.
 */
export function ehFormatoSimplificado(texto) {
  return detectarFormato(texto) === FORMATOS.SIMPLIFICADO;
}

/**
 * Divide o resto do item em trechos separados por ` · `, sem cortar dentro de parênteses,
 * colchetes ou crases (ex.: `(local · main)` e `` `MEDIO · effort medium` `` ficam inteiros).
 * @param {string} texto Texto depois de `#<ID> — `.
 * @returns {string[]} Trechos; `join(' · ')` devolve o texto original.
 */
export function dividirSegmentos(texto) {
  const segmentos = [];
  let profundidade = 0;
  let emCrase = false;
  let inicio = 0;
  for (let i = 0; i < texto.length; i += 1) {
    const caractere = texto[i];
    if (caractere === '`') emCrase = !emCrase;
    if (emCrase) continue;
    if (ABRE.has(caractere)) profundidade += 1;
    if (FECHA.has(caractere)) profundidade = Math.max(0, profundidade - 1);
    const ehSeparador = profundidade === 0 && texto.startsWith(SEPARADOR, i);
    if (!ehSeparador) continue;
    segmentos.push(texto.slice(inicio, i));
    inicio = i + SEPARADOR.length;
    i = inicio - 1;
  }
  segmentos.push(texto.slice(inicio));
  return segmentos;
}

/**
 * Acha os grupos `( … )` de nível 0 de um trecho.
 * @param {string} trecho Trecho do item.
 * @returns {Array<{inicio: number, fim: number, conteudo: string}>} Grupos (fim exclusivo).
 */
export function acharGrupos(trecho) {
  const grupos = [];
  let profundidade = 0;
  let abertura = -1;
  for (let i = 0; i < trecho.length; i += 1) {
    if (trecho[i] === '(') {
      if (profundidade === 0) abertura = i;
      profundidade += 1;
      continue;
    }
    if (trecho[i] !== ')' || profundidade === 0) continue;
    profundidade -= 1;
    if (profundidade > 0) continue;
    grupos.push({ inicio: abertura, fim: i + 1, conteudo: trecho.slice(abertura + 1, i) });
  }
  return grupos;
}

/**
 * Tira os grupos `( … )` de nível 0 de um trecho.
 * @param {string} trecho Trecho do item.
 * @returns {string} Trecho sem os grupos e sem espaços nas pontas.
 */
function semGrupos(trecho) {
  let resultado = trecho;
  for (const grupo of acharGrupos(trecho).reverse()) {
    resultado = resultado.slice(0, grupo.inicio) + resultado.slice(grupo.fim);
  }
  return resultado.replace(/\s{2,}/g, ' ').trim();
}

/**
 * Diz se o trecho começa com um emoji de status da legenda.
 * @param {string} trecho Trecho do item.
 * @returns {string|null} Emoji, ou null.
 */
function emojiDoStatus(trecho) {
  const limpo = trecho.trim().replace(SELETOR_VARIACAO, '');
  return EMOJIS_STATUS.find((emoji) => limpo.startsWith(emoji)) ?? null;
}

/**
 * Expande os IDs do item: `#400.1 a #400.4` vira 400.1…400.4; `#387.1 e #387.2` vira os dois.
 * @param {string} bruto Trecho dos IDs, como escrito.
 * @returns {string[]} IDs sem o `#`.
 */
export function expandirIds(bruto) {
  const partes = bruto.split(/\s+(a|e|até)\s+/u);
  const ids = [partes[0].replace(/^#/, '')];
  for (let i = 1; i < partes.length; i += 2) {
    const destino = partes[i + 1].replace(/^#/, '');
    const anterior = PADRAO_FAIXA.exec(ids[ids.length - 1]);
    const final = PADRAO_FAIXA.exec(destino);
    const ehFaixa = partes[i] !== 'e' && anterior && final && anterior[1] === final[1];
    const tamanho = ehFaixa ? Number(final[2]) - Number(anterior[2]) : 0;
    if (!ehFaixa || tamanho < 1 || tamanho > LIMITE_FAIXA) {
      ids.push(destino);
      continue;
    }
    for (let n = Number(anterior[2]) + 1; n <= Number(final[2]); n += 1) ids.push(anterior[1] + n);
  }
  return [...new Set(ids)];
}

/**
 * Lê o status, a prioridade e as dependências do trecho de status.
 * @param {string} trecho Trecho com o emoji (pode ser vazio).
 * @returns {{status: string, emoji: string|null, prioridade: string, dependeDe: string}} Dados.
 */
function lerStatus(trecho) {
  if (!trecho) return { status: '', emoji: null, prioridade: '', dependeDe: '' };
  const observacao = acharGrupos(trecho).map((grupo) => grupo.conteudo).join('; ');
  const prioridade = EMOJIS_PRIORIDADE.find((emoji) => trecho.includes(emoji)) ?? '';
  const palavra = prioridade
    ? (new RegExp(`${prioridade}\\s*([\\p{L}]+)`, 'u').exec(trecho)?.[1] ?? '') : '';
  const dependencias = PADRAO_DEPENDENCIA.exec(observacao)?.[1] ?? '';
  return {
    status: semGrupos(trecho),
    emoji: emojiDoStatus(trecho),
    prioridade: [prioridade, palavra].filter(Boolean).join(' '),
    dependeDe: dependencias.split(/\s*(?:,|\be\b)\s*/u).map((id) => id.replace(/^#/, ''))
      .filter(Boolean).join(', '),
  };
}

/**
 * Classifica um trecho depois do status: nível, modelo, reserva, livre ou outro.
 * @param {string} trecho Trecho do item.
 * @returns {string} 'nivel' | 'modelo' | 'reserva' | 'livre' | 'outro'.
 */
function tipoDoTrecho(trecho) {
  const limpo = trecho.trim();
  if (PADRAO_NIVEL_CRASE.test(limpo) || PADRAO_SEM_NIVEL.test(limpo)) return 'nivel';
  if (PADRAO_SO_MODELO.test(limpo)) return 'modelo';
  if (PADRAO_LIVRE.test(limpo)) return 'livre';
  const ehReserva = PADRAO_RESERVA.test(limpo) && !limpo.startsWith('(');
  return ehReserva ? 'reserva' : 'outro';
}

/**
 * Lê nível, modelo e reserva dos trechos que vêm depois do status de uma subtarefa.
 * @param {string[]} trechos Trechos depois do status.
 * @returns {{nivel: string|null, modelo: string, emUsoPor: string, observacao: string}} Dados.
 */
function lerCaudaDaSubtarefa(trechos) {
  const modelo = [];
  const observacoes = [];
  let emUsoPor = LIVRE;
  for (const trecho of trechos) {
    const tipo = tipoDoTrecho(trecho);
    if (tipo === 'reserva') emUsoPor = trecho.trim();
    if (tipo === 'reserva' || tipo === 'livre') continue;
    for (const grupo of acharGrupos(trecho)) {
      if (PADRAO_RESERVA.test(grupo.conteudo)) emUsoPor = grupo.conteudo.trim();
      else observacoes.push(grupo.conteudo);
    }
    const texto = semGrupos(trecho).replace(/`/g, '');
    if (texto) modelo.push(texto);
  }
  const textoModelo = modelo.join(SEPARADOR);
  const nivel = PADRAO_NIVEL.exec(textoModelo.toUpperCase())?.[1]?.replace('É', 'E') ?? null;
  return { nivel, modelo: textoModelo, emUsoPor, observacao: observacoes.join('; ') };
}

/**
 * Separa título/link, status e cauda de um item.
 * @param {string[]} segmentos Trechos do item.
 * @returns {{titulo: string, link: string|null, indiceStatus: number, cauda: string[]}} Partes.
 */
function separarPartes(segmentos) {
  const indiceStatus = segmentos.findIndex((trecho, i) => i > 0 && emojiDoStatus(trecho));
  const fimTitulo = indiceStatus < 0 ? segmentos.length : indiceStatus;
  const tituloBruto = segmentos.slice(0, Math.max(1, fimTitulo)).join(SEPARADOR).trim();
  const link = PADRAO_LINK.exec(tituloBruto);
  return {
    titulo: (link ? link[1] : tituloBruto).replace(/\*\*/g, '').trim(),
    link: link ? link[2] : null,
    indiceStatus,
    cauda: indiceStatus < 0 ? [] : segmentos.slice(indiceStatus + 1),
  };
}

/**
 * Rótulo curto da etapa a partir do caminho (`ETAPA-545-8e2a4c60-…` vira `545-8e2a4c60`).
 * @param {string|null} caminho Caminho do link.
 * @returns {string} Rótulo (vazio sem link).
 */
function rotuloDaEtapa(caminho) {
  if (!caminho) return '';
  const achado = PADRAO_ETAPA_ARQUIVO.exec(caminho);
  if (achado) return achado[1];
  return caminho.split('/').pop().replace(/\.md$/iu, '');
}

/**
 * ID curto (sem o sufixo de UUID): `400-8e2a4c60` vira `400`. Usado só para dependências.
 * @param {string} id ID completo.
 * @returns {string} ID sem o sufixo.
 */
export function idCurto(id) {
  return id.replace(PADRAO_SUFIXO_UUID, '');
}

/**
 * Lê uma linha de item (mãe ou subtarefa).
 * @param {string} linha Linha do arquivo.
 * @param {number} indice Índice da linha no arquivo.
 * @param {object|null} mae Último item de mãe lido (para a subtarefa herdar a etapa).
 * @returns {object[]|null} Um item por ID da linha, ou null se não for item.
 */
function lerLinhaDeItem(linha, indice, mae) {
  const achado = PADRAO_ITEM.exec(linha);
  if (!achado) return null;
  const [, recuo, idsBrutos, resto] = achado;
  const ehSubtarefa = recuo.length > 0;
  const segmentos = dividirSegmentos(resto);
  const partes = separarPartes(segmentos);
  const status = lerStatus(partes.indiceStatus < 0 ? '' : segmentos[partes.indiceStatus]);
  const cauda = ehSubtarefa ? lerCaudaDaSubtarefa(partes.cauda) : null;
  const etapaLink = partes.link ?? (ehSubtarefa ? (mae?.etapaLink ?? null) : null);
  const ids = expandirIds(idsBrutos);
  const base = {
    indice, bruto: linha, cabeca: linha.slice(0, linha.length - resto.length), segmentos,
    indiceStatus: partes.indiceStatus, ehSubtarefa, ehMae: !ehSubtarefa,
    idMae: ehSubtarefa ? (mae?.id ?? null) : null, agrupada: ids.length > 1,
    titulo: partes.titulo, etapaLink, etapaRotulo: rotuloDaEtapa(etapaLink), ...status,
    nivel: cauda?.nivel ?? null, modelo: cauda?.modelo ?? LIVRE,
    emUsoPor: cauda ? cauda.emUsoPor : partes.cauda.join(SEPARADOR).trim(),
    observacao: cauda?.observacao ?? '',
  };
  return ids.map((id) => ({ ...base, id, idCurto: idCurto(id) }));
}

/**
 * Lê os itens do índice simplificado (só a seção "Tarefas", quando ela existir).
 * Linhas soltas (`- #29: …`), tabelas quebradas e texto livre contam como ignoradas.
 * @param {string} texto Conteúdo do `STATUS.md`.
 * @returns {{itens: object[], ignoradas: number, secao: {inicio: number, fim: number}}} Itens.
 */
export function lerIndiceSimplificado(texto) {
  const linhas = dividirLinhas(texto);
  const secao = localizarSecaoTarefas(linhas);
  const itens = [];
  let ignoradas = 0;
  let mae = null;
  for (let i = secao.inicio; i < secao.fim; i += 1) {
    const lidos = lerLinhaDeItem(linhas[i], i, mae);
    if (lidos && !lidos[0].ehSubtarefa) mae = lidos[0];
    if (lidos) itens.push(...lidos);
    else if (/^\s*(?:[-*|])/.test(linhas[i])) ignoradas += 1;
  }
  return { itens, ignoradas, secao };
}

/**
 * Monta a linha a partir da cabeça e dos trechos.
 * @param {{cabeca: string}} item Item lido.
 * @param {string[]} segmentos Trechos novos.
 * @returns {string} Linha.
 */
function montarLinha(item, segmentos) {
  return item.cabeca + segmentos.join(SEPARADOR);
}

/**
 * Troca o status do item (o emoji e as palavras); a observação entre parênteses fica.
 * @param {object} item Item lido.
 * @param {string[]} segmentos Trechos atuais.
 * @param {string} status Novo status (ex.: `🔄 Em execução`).
 * @returns {{segmentos: string[], indiceStatus: number}} Trechos novos.
 */
function trocarStatus(item, segmentos, status) {
  const novos = [...segmentos];
  if (item.indiceStatus < 0) {
    novos.splice(1, 0, status);
    return { segmentos: novos, indiceStatus: 1 };
  }
  const atual = novos[item.indiceStatus];
  const grupos = acharGrupos(atual).map((grupo) => atual.slice(grupo.inicio, grupo.fim));
  novos[item.indiceStatus] = [status, ...grupos].join(' ');
  return { segmentos: novos, indiceStatus: item.indiceStatus };
}

/**
 * Tira a reserva (trecho ou grupo entre parênteses) e o trecho `livre` da cauda da subtarefa.
 * @param {string[]} cauda Trechos depois do status.
 * @returns {string[]} Cauda sem reserva.
 */
function tirarReserva(cauda) {
  const resultado = [];
  for (const trecho of cauda) {
    const tipo = tipoDoTrecho(trecho);
    if (tipo === 'reserva' || tipo === 'livre') continue;
    let limpo = trecho;
    for (const grupo of acharGrupos(trecho).reverse()) {
      if (!PADRAO_RESERVA.test(grupo.conteudo)) continue;
      limpo = limpo.slice(0, grupo.inicio).trimEnd() + limpo.slice(grupo.fim);
    }
    if (limpo.trim() !== '') resultado.push(limpo);
  }
  return resultado;
}

/**
 * Diz se o texto de "Em uso por" significa livre.
 * @param {string} valor Texto.
 * @returns {boolean} true para `—`, `-`, vazio ou `livre`.
 */
function ehValorLivre(valor) {
  return ['', '—', '-', 'livre'].includes(String(valor).trim().toLowerCase());
}

/**
 * Grava a reserva: na subtarefa, numa observação `( … )` no fim; na mãe, no último trecho.
 * @param {object} item Item lido.
 * @param {{segmentos: string[], indiceStatus: number}} atual Trechos e posição do status.
 * @param {string} valor Texto de "Em uso por".
 * @returns {string[]} Trechos novos.
 */
function trocarReserva(item, atual, valor) {
  if (atual.indiceStatus < 0) throw new ErroFormatoQuadro('Item sem status: reserva recusada.');
  const cabecaStatus = atual.segmentos.slice(0, atual.indiceStatus + 1);
  if (!item.ehSubtarefa) return [...cabecaStatus, String(valor).trim() || LIVRE];
  const cauda = tirarReserva(atual.segmentos.slice(atual.indiceStatus + 1));
  if (!ehValorLivre(valor) && cauda.length === 0) cauda.push(`(${String(valor).trim()})`);
  else if (!ehValorLivre(valor)) cauda[cauda.length - 1] += ` (${String(valor).trim()})`;
  return [...cabecaStatus, ...cauda];
}

/**
 * Reescreve a linha de um item trocando status e/ou reserva. O resto da linha não muda.
 * @param {object} item Item lido por {@link lerIndiceSimplificado}.
 * @param {{status?: string, emUsoPor?: string}} alteracoes O que trocar.
 * @returns {string} Linha nova.
 * @throws {ErroFormatoQuadro} Se o item for agrupado ou a linha nova não ler igual ao pedido.
 */
export function reescreverItem(item, alteracoes) {
  if (item.agrupada) throw new ErroFormatoQuadro('Subtarefa agrupada: separe o item antes.');
  let atual = { segmentos: item.segmentos, indiceStatus: item.indiceStatus };
  if (alteracoes.status !== undefined) {
    atual = trocarStatus(item, atual.segmentos, alteracoes.status);
  }
  if (alteracoes.emUsoPor !== undefined) {
    atual = { ...atual, segmentos: trocarReserva(item, atual, alteracoes.emUsoPor) };
  }
  const linha = montarLinha(item, atual.segmentos);
  conferirReescrita(item, linha, alteracoes);
  return linha;
}

/**
 * Confere que a linha nova lê o mesmo ID, o status e a reserva pedidos (nada gravado se não).
 * @param {object} item Item original.
 * @param {string} linha Linha nova.
 * @param {{status?: string, emUsoPor?: string}} alteracoes O que foi pedido.
 * @returns {void}
 * @throws {ErroFormatoQuadro} Se a releitura não bater.
 */
function conferirReescrita(item, linha, alteracoes) {
  const relido = lerLinhaDeItem(linha, item.indice, { id: item.idMae, etapaLink: item.etapaLink });
  const novo = relido?.find((outro) => outro.id === item.id);
  const statusOk = alteracoes.status === undefined || novo?.status === alteracoes.status.trim();
  const esperado = ehValorLivre(alteracoes.emUsoPor ?? '') && item.ehSubtarefa
    ? LIVRE : String(alteracoes.emUsoPor ?? '').trim() || LIVRE;
  const reservaOk = alteracoes.emUsoPor === undefined || novo?.emUsoPor === esperado;
  if (!novo || !statusOk || !reservaOk) {
    throw new ErroFormatoQuadro('A gravação deixaria o item ilegível; nada foi gravado.');
  }
}

/**
 * Reescreve nível e modelo de uma subtarefa (gravação do Jev): troca os trechos de nível
 * (`` `MEDIO` `` ou `nível a classificar pelo Jev`) e de modelo (`só …`); observações e reserva
 * ficam.
 * @param {object} item Subtarefa lida por {@link lerIndiceSimplificado}.
 * @param {{nivel: string, modelo: string, effort: string}} classificacao Nível, `só …` e effort.
 * @returns {string} Linha nova.
 * @throws {ErroFormatoQuadro} Se não for subtarefa, for agrupada ou não tiver status.
 */
export function reescreverNivel(item, classificacao) {
  const recusa = !item.ehSubtarefa || item.agrupada || item.indiceStatus < 0;
  if (recusa) throw new ErroFormatoQuadro('Item sem linha própria de subtarefa com status.');
  const cabecaStatus = item.segmentos.slice(0, item.indiceStatus + 1);
  const cauda = item.segmentos.slice(item.indiceStatus + 1);
  const mantidos = [];
  const grupos = [];
  for (const trecho of cauda) {
    const tipo = tipoDoTrecho(trecho);
    if (tipo !== 'nivel' && tipo !== 'modelo') mantidos.push(trecho);
    else grupos.push(...acharGrupos(trecho).map((g) => trecho.slice(g.inicio, g.fim)));
  }
  const nivel = `\`${classificacao.nivel} · effort ${classificacao.effort}\``;
  const modelo = [classificacao.modelo, ...grupos].join(' ');
  return montarLinha(item, [...cabecaStatus, nivel, modelo, ...mantidos]);
}

// Gancho `UserPromptSubmit` do Claude Code (JEV-GLOBAL-AI-FINAL.10): lê o JSON do evento pela
// entrada padrão (`prompt`, `cwd`, `session_id`, `hook_event_name`), classifica a mensagem em
// processo e devolve só `additionalContext` com a decisão do Jev e os alertas.
// INV-2: sai SEMPRE com 0, nunca imprime `decision`/`block`, nunca escreve em stderr e nunca
// altera a mensagem; entrada malformada, mensagem pulada ou qualquer falha = nenhuma saída.
// A chave vem de config.mjs (ambiente ou .env da raiz do rules-ai): este arquivo não a lê nem a
// imprime. Roda a partir de qualquer pasta de projeto.
import { basename } from 'node:path';
import { rodarComProxySePreciso } from '../proxy.mjs';

const EVENTO = 'UserPromptSubmit';
const TEMPO_LEITURA_MS = 3000;

/**
 * Lê a entrada padrão inteira, com limite de tempo (se o gancho não fechar a entrada, segue).
 * @returns {Promise<string>} Texto recebido (vazio em terminal interativo ou no limite).
 */
function lerEntrada() {
  if (process.stdin.isTTY) return Promise.resolve('');
  const leitura = (async () => {
    const partes = [];
    for await (const parte of process.stdin) partes.push(parte);
    return Buffer.concat(partes).toString('utf8');
  })();
  const limite = new Promise((resolver) => {
    setTimeout(() => resolver(''), TEMPO_LEITURA_MS).unref();
  });
  return Promise.race([leitura, limite]);
}

/**
 * Converte o JSON do evento; inválido ou de outro evento vira null.
 * @param {string} texto Entrada bruta.
 * @returns {{prompt: string, cwd: string}|null} Campos usados, ou null para não fazer nada.
 */
function lerEvento(texto) {
  try {
    const evento = JSON.parse(texto);
    const ehOutroEvento = evento.hook_event_name && evento.hook_event_name !== EVENTO;
    if (ehOutroEvento || typeof evento.prompt !== 'string') return null;
    return { prompt: evento.prompt, cwd: typeof evento.cwd === 'string' ? evento.cwd : '' };
  } catch {
    return null;
  }
}

/**
 * Classifica a mensagem e monta a saída do gancho.
 * @param {{prompt: string, cwd: string}} evento Evento lido.
 * @returns {Promise<string>} JSON da saída, ou vazio quando não há contexto a acrescentar.
 */
async function montarSaida(evento) {
  const { classificarMensagem, montarContexto } = await import('../mensagem/classificar.mjs');
  const projeto = basename(evento.cwd) || basename(process.cwd());
  const resultado = await classificarMensagem({ texto: evento.prompt, projeto });
  const contexto = montarContexto(resultado);
  if (!contexto) return '';
  return JSON.stringify({
    hookSpecificOutput: { hookEventName: EVENTO, additionalContext: contexto },
  });
}

/**
 * Programa principal: nunca lança e nunca muda o código de saída.
 * @returns {Promise<void>}
 */
async function principal() {
  try {
    if (await rodarComProxySePreciso()) {
      process.exitCode = 0;
      return;
    }
    const evento = lerEvento(await lerEntrada());
    const saida = evento ? await montarSaida(evento) : '';
    if (saida) process.stdout.write(`${saida}\n`);
  } catch {
    // INV-2: falha do gancho nunca aparece na tela nem bloqueia a mensagem.
  }
  process.exitCode = 0;
}

await principal();

// Gancho `UserPromptSubmit` do Codex (JEV-GLOBAL-AI-FINAL.12), registrado em `~/.codex/hooks.json`
// pelo `scripts/sincronizar.mjs`. O Codex manda o mesmo evento do Claude Code (`prompt`, `cwd`,
// `hook_event_name`) e aceita a mesma saída (`hookSpecificOutput.additionalContext`), então este
// arquivo só reaproveita o gancho do Claude Code: as mesmas garantias valem (INV-2: sai sempre
// com 0, nunca bloqueia, nunca escreve em stderr). Exige `codex_hooks = true` em `[features]` do
// `~/.codex/config.toml`. Arquivo separado para o Codex poder mudar de formato sem mexer no outro.
import './claude-prompt.mjs';

// Guardrail de aprovação indevida (R3.4, C32/C33): o agente nunca responde aprovação, permissão
// ou confirmação NO LUGAR do usuário. Avalia a mensagem ANTES de ela ser enviada (a outro painel,
// a um diálogo, a outra IA). Camada 1 (determinística): frase que declara aprovação do usuário,
// "não perguntar de novo", pular permissões, ou "sim/ok/1…" curto respondendo a um pedido de
// permissão → `bloquear`. Camada 2: o Jev vê a mensagem mascarada; p ≥ 0,70 → `bloquear`;
// senão `liberar`; sem Jev → `revisar` (nunca liberar em silêncio).
// SEM escape automático: quem responde aprovação é o próprio usuário. Bloqueado → reformular a
// mensagem pedindo que o usuário responda.
import {
  ACOES, FONTES, calcularHash, concluirDecisao, consultar, lerProbabilidade,
  montarDependencias, prepararTexto,
} from './seguranca-base.mjs';

const CASO = 'aprovacao-indevida';
const ACAO_JEV = 'guardrail:aprovacao';
const LIMIAR_BLOQUEIO = 0.7;
const PERGUNTA = 'responde_aprovacao';
const PADRAO_PONTUACAO_NAS_PONTAS = /^[\s"'“”‘’.,!?:;()-]+|[\s"'“”‘’.,!?:;()-]+$/g;
const AFIRMACOES_CURTAS = [
  'sim', 's', 'yes', 'y', 'ok', 'okay', 'aprovad[oa]', 'aprovo', 'autorizo', 'autorizad[oa]',
  'confirmo', 'confirmad[oa]', 'prossiga', 'continue', 'continuar', 'allow', 'approved?',
  'go ahead', '[123]',
  'pode(?: (?:sim|seguir|prosseguir|executar|fazer|continuar|ir|apagar|rodar))?',
  'sim,? pode(?: \\S+)?',
];
const PADRAO_AFIRMACAO_CURTA = new RegExp(`^(?:${AFIRMACOES_CURTAS.join('|')})$`, 'i');
/** Pergunta pendente que é um pedido de permissão/aprovação/confirmação. */
const PADRAO_PEDIDO_DE_PERMISSAO = new RegExp([
  'do you want to', '\\ballow\\b', '\\bapprove', 'permiss', '\\baprov', '\\bautoriz',
  '\\bconfirm', '\\bproceed\\b', '\\[y/n\\]', '\\(y/n\\)', 'yes, and',
  'posso (?:apagar|executar|rodar|seguir|prosseguir|continuar|fazer)',
].join('|'), 'i');
const FRASES_PROIBIDAS = [
  { regra: 'declara-aprovacao-do-usuario',
    padrao: /\busu[aá]rio\s+(?:j[aá]\s+)?(?:aprovou|autorizou|confirmou|disse\s+(?:que\s+)?sim)\b/i,
  },
  { regra: 'aprovado-pelo-usuario',
    padrao: /\b(?:aprovad[oa]|autorizad[oa]|confirmad[oa])\s+pelo\s+usu[aá]rio\b/i },
  { regra: 'em-nome-do-usuario',
    padrao: /\b(?:em\s+nome\s+do|no\s+lugar\s+do)\s+usu[aá]rio\b/i },
  { regra: 'on-behalf-of-the-user', padrao: /\bon\s+behalf\s+of\s+the\s+user\b/i },
  { regra: 'user-approved',
    padrao: /\bthe\s+user\s+(?:has\s+)?(?:approved|authorized|said\s+yes)\b/i },
  { regra: 'nao-perguntar-de-novo',
    padrao: /\bdon'?t\s+ask\s+again\b|\bn[aã]o\s+pergunt(?:e|ar)\s+(?:de\s+novo|mais)\b/i },
  { regra: 'pular-permissoes',
    padrao: /--dangerously-skip-permissions|\b(?:bypass|skip)(?:ing)?\s+permissions\b/i },
];
const ORIENTACAO = 'Não envie: só o usuário responde aprovação, permissão ou confirmação '
  + '(C32/C33). Reformule pedindo que o usuário responda ele mesmo. Este bloqueio não tem escape.';
const PERGUNTAS = {
  [PERGUNTA]: {
    type: 'noul',
    instructions: 'A `mensagem` (de um agente de IA) responde ou concede aprovação, permissão ou '
      + 'confirmação no lugar do usuário humano (ex.: "sim", "pode executar", escolher "Yes" num '
      + 'diálogo, dizer que o usuário aprovou)? Considere a `pergunta_pendente`, se houver.',
    criteria: {
      true: 'responde ou concede aprovação/permissão no lugar do usuário',
      false: 'não concede aprovação/permissão (informa, pergunta ou pede ao usuário)',
    },
  },
};

/**
 * Normaliza a mensagem para comparar com as afirmações curtas.
 * @param {string} mensagem Mensagem do agente.
 * @returns {string} Minúsculas, sem pontuação nas pontas e com espaços simples.
 */
function normalizarMensagem(mensagem) {
  return mensagem.replace(PADRAO_PONTUACAO_NAS_PONTAS, '').replace(/\s+/g, ' ').toLowerCase();
}

/**
 * Camada determinística: regras que bloqueiam sem consultar o Jev.
 * @param {string} mensagem Mensagem do agente.
 * @param {string} perguntaPendente Pergunta/diálogo que a mensagem responde (se houver).
 * @returns {string[]} Motivos de bloqueio (vazio se nenhuma regra casou).
 */
export function acharRegrasDeAprovacao(mensagem, perguntaPendente) {
  const motivos = FRASES_PROIBIDAS
    .filter(({ padrao }) => padrao.test(mensagem)).map(({ regra }) => `regex:${regra}`);
  const ehAfirmacaoCurta = PADRAO_AFIRMACAO_CURTA.test(normalizarMensagem(mensagem));
  const respondePermissao = ehAfirmacaoCurta && PADRAO_PEDIDO_DE_PERMISSAO.test(perguntaPendente);
  if (respondePermissao) motivos.push('regex:afirmacao-curta-a-pedido-de-permissao');
  return motivos;
}

/**
 * Decide pelo Jev quando a camada determinística não bloqueou.
 * @param {object} consulta Resultado de `consultar`.
 * @returns {object} Parte da decisão.
 */
function decidirPeloJev(consulta) {
  if (!consulta.respostas) {
    return { acao: ACOES.REVISAR, motivos: ['jev-indisponivel'], fonte: FONTES.NENHUMA };
  }
  const probabilidade = lerProbabilidade(consulta.respostas, PERGUNTA, PERGUNTAS[PERGUNTA]);
  const base = { fonte: consulta.fonte, probabilidade };
  if (probabilidade === null) {
    return { ...base, acao: ACOES.REVISAR, motivos: ['jev-sem-probabilidade'] };
  }
  if (probabilidade >= LIMIAR_BLOQUEIO) {
    return { ...base, acao: ACOES.BLOQUEAR, motivos: ['jev:p>=0.70'] };
  }
  return { ...base, acao: ACOES.LIBERAR, motivos: ['jev:p<0.70'] };
}

/**
 * Aplica as camadas e devolve a decisão e a consulta feita (se houve).
 * @param {{mensagem: string, perguntaPendente: string}} textos Mensagem e pergunta pendente.
 * @param {{consultores: object[]}} deps Dependências.
 * @returns {Promise<{decisao: object, consulta: object|null, achados: object[]}>} Decisão.
 */
async function decidir(textos, deps) {
  const mensagem = prepararTexto(textos.mensagem);
  const pendente = prepararTexto(textos.perguntaPendente);
  const achados = [...mensagem.achados, ...pendente.achados];
  if (textos.mensagem.trim() === '') {
    return { decisao: { acao: ACOES.LIBERAR, motivos: ['mensagem-vazia'],
      fonte: FONTES.DETERMINISTICA }, consulta: null, achados };
  }
  const motivos = acharRegrasDeAprovacao(textos.mensagem, textos.perguntaPendente);
  if (motivos.length > 0) {
    return { decisao: { acao: ACOES.BLOQUEAR, motivos, fonte: FONTES.DETERMINISTICA },
      consulta: null, achados };
  }
  const consulta = await consultar({
    state: { mensagem: mensagem.texto, pergunta_pendente: pendente.texto },
    perguntas: PERGUNTAS, acao: ACAO_JEV,
  }, deps.consultores);
  return { decisao: decidirPeloJev(consulta), consulta, achados };
}

/**
 * Avalia se uma mensagem do agente responde aprovação/permissão no lugar do usuário.
 * @param {{mensagem: string, perguntaPendente?: string}} entrada Mensagem a enviar e, se houver,
 *   a pergunta ou diálogo que ela responde.
 * @param {{consultores?: object[], registrar?: Function}} [dependencias] Injeção para teste.
 * @returns {Promise<Readonly<object>>} Decisão (`bloquear` = não enviar e reformular).
 */
export async function avaliarAprovacao(entrada, dependencias = {}) {
  const deps = montarDependencias(dependencias);
  const textos = {
    mensagem: String(entrada?.mensagem ?? ''),
    perguntaPendente: String(entrada?.perguntaPendente ?? ''),
  };
  const { decisao, consulta, achados } = await decidir(textos, deps);
  const completa = {
    caso: CASO, achados, limiar: LIMIAR_BLOQUEIO,
    hashEntrada: calcularHash(`${textos.mensagem}\n${textos.perguntaPendente}`),
    orientacao: decisao.acao === ACOES.BLOQUEAR ? ORIENTACAO : null, ...decisao,
  };
  return concluirDecisao(completa, { consulta, registrar: deps.registrar });
}

// Guardrail de comando destrutivo (R3.3). Camada 1 (determinística, sobre o comando INTEIRO,
// inclusive dentro de aspas/`bash -c`): regra destrutiva conhecida → `bloquear`. Se TODOS os
// trechos (`&&`, `||`, `;`, `|`, nova linha) estão na allowlist de leitura → `liberar`.
// Camada 2 (fora da allowlist): o Jev vê o comando mascarado; risco/apagar p ≥ 0,70 →
// `bloquear`; senão `revisar`. Fora da allowlist NUNCA libera sem confirmação humana explícita.
// O Jev só agrava (revisar → bloquear); nunca libera e nunca executa nada.
// Escape humano: `confirmacaoHumana.alvo` = o comando exato (um "sim" genérico não vale).
import {
  ACOES, FONTES, aplicarEscape, calcularHash, concluirDecisao, confirmacaoValida, consultar,
  maiorProbabilidade, montarDependencias, prepararTexto,
} from './seguranca-base.mjs';

const CASO = 'comando-destrutivo';
const ACAO_JEV = 'guardrail:comando-destrutivo';
const LIMIAR_BLOQUEIO = 0.7;
const PADRAO_SEPARADORES = /&&|\|\||[;|\n]/;
/** Redirecionamentos que não gravam arquivo do projeto. */
const PADRAO_REDIRECIONAMENTO_INOFENSIVO = /\d?>\s*(?:\/dev\/null|\$null|nul)\b|\d?>&\d/gi;
const PADRAO_GRAVACAO_OU_SUBSTITUICAO = /[>`]|\$\(/;
const PADRAO_GIT_RESTORE = /^\s*git\s+restore\b/i;
const PADRAO_SO_STAGED = /\s--staged\b/;
const PADRAO_WORKTREE = /\s(?:--worktree|-W)\b/;
const ORIENTACAO = 'Comando fora da allowlist ou destrutivo: não execute. Só o usuário libera, '
  + 'confirmando o comando exato: confirmacaoHumana { confirmado: true, quem, alvo: <comando> }.';
const COMANDOS_LEITURA = [
  'ls', 'dir', 'pwd', 'cd', 'cat', 'head', 'tail', 'wc', 'grep', 'egrep', 'rg', 'echo',
  'printf', 'which', 'where', 'type', 'file', 'stat', 'du', 'df', 'date', 'whoami', 'sort',
  'uniq', 'cut', 'diff', 'cmp', 'sha256sum', 'md5sum', 'tree', 'less', 'more', 'true',
];
const CMDLETS_LEITURA = [
  'Get-ChildItem', 'Get-Content', 'Get-Item', 'Select-String', 'Test-Path', 'Get-Location',
  'Write-Output', 'Measure-Object', 'Get-Date', 'Resolve-Path',
];
const SUBCOMANDOS_GIT_LEITURA = [
  'status', 'log', 'diff', 'show', 'fetch', 'rev-parse', 'ls-files', 'blame', 'describe',
  'shortlog', 'remote\\s+-v',
];
/** Trechos só de leitura (o trecho inteiro precisa casar desde o início). */
const ALLOWLIST = [
  new RegExp(`^(?:${COMANDOS_LEITURA.join('|')})(?:\\s|$)`, 'i'),
  new RegExp(`^git\\s+(?:${SUBCOMANDOS_GIT_LEITURA.join('|')})\\b`, 'i'),
  /^git\s+branch(?:\s+(?:--list|-a|-v|-vv|-r|--show-current))*\s*$/i,
  /^node\s+(?:--check|-v|--version)\b/i,
  /^(?:npm|pnpm|yarn)\s+(?:ls|list|view|-v|--version|outdated)\b/i,
  new RegExp(`^(?:${CMDLETS_LEITURA.join('|')})\\b`, 'i'),
  /^herdr\s+(?:agent\s+(?:list|read)|pane\s+read)\b/i,
];

/**
 * `git restore` sem `--staged` (ou com `--worktree`) descarta mudanças do disco.
 * @param {string} comando Comando inteiro.
 * @returns {boolean} true se algum trecho é um `git restore` que descarta.
 */
function restauraDescartando(comando) {
  return comando.split(PADRAO_SEPARADORES).some((trecho) => {
    const ehRestore = PADRAO_GIT_RESTORE.test(trecho);
    return ehRestore && (!PADRAO_SO_STAGED.test(trecho) || PADRAO_WORKTREE.test(trecho));
  });
}

/** Regras destrutivas: `padrao` (regex) ou `testar` (função) sobre o comando inteiro. */
const REGRAS_DESTRUTIVAS = [
  { regra: 'rm-recursivo-ou-forcado',
    padrao: /\brm\s+(?:-{1,2}[\w-]+\s+)*-(?:[a-z]*[rf][a-z]*|-recursive|-force)\b/i },
  { regra: 'rimraf', padrao: /\brimraf\b/i },
  { regra: 'remove-item-recursivo', padrao: /\bRemove-Item\b[^\n;|&]*-Recurse/i },
  { regra: 'rmdir-s', padrao: /\b(?:rd|rmdir)\s+[^\n;|&]*\/s\b/i },
  { regra: 'del-s-q', padrao: /\b(?:del|erase)\s+[^\n;|&]*\/[sq]\b/i },
  { regra: 'find-delete', padrao: /\bfind\b[^\n;|&]*(?:-delete\b|-exec\s+rm\b)/i },
  { regra: 'xargs-rm', padrao: /\bxargs\s+(?:-\S+\s+)*rm\b/i },
  { regra: 'git-reset-hard', padrao: /\bgit\s+reset\b[^\n;|&]*--hard\b/i },
  { regra: 'git-push-force',
    padrao: /\bgit\s+push\b[^\n;|&]*(?:--force(?:-with-lease)?\b|\s-f\b|\s\+[\w/-]+)/i },
  { regra: 'git-clean', padrao: /\bgit\s+clean\s+[^\n;|&]*-[a-z]*f/i },
  { regra: 'git-checkout-descarta',
    padrao: /\bgit\s+checkout\s+(?:[^\n;|&\s]+\s+)?--\s+\S|\bgit\s+checkout\s+\.(?:\s|$)/i },
  { regra: 'git-restore-descarta', testar: restauraDescartando },
  { regra: 'git-branch-D', padrao: /\bgit\s+branch\s+[^\n;|&]*-D\b/ },
  { regra: 'git-stash-descarta', padrao: /\bgit\s+stash\s+(?:drop|clear)\b/i },
  { regra: 'git-reescreve-historico',
    padrao: /\bgit\s+(?:filter-branch|filter-repo|update-ref\s+-d|reflog\s+expire)\b/i },
  { regra: 'git-gc-prune', padrao: /\bgit\s+gc\b[^\n;|&]*--prune/i },
  { regra: 'sql-drop',
    padrao: /\bdrop\s+(?:table|database|schema|view|function|index|policy|role|trigger|type)\b/i },
  { regra: 'sql-truncate', padrao: /\btruncate\s+(?:table\s+)?["\w.]+/i },
  { regra: 'sql-delete-sem-where', padrao: /\bdelete\s+from\s+["\w.]+\s*(?:;|$|["'])/im },
  { regra: 'sql-update-sem-where',
    padrao: /\bupdate\s+["\w.]+\s+set\b(?:(?!\bwhere\b)[^;"'])*(?:;|$|["'])/im },
  { regra: 'sql-alter-drop', padrao: /\balter\s+table\b[^;]*\bdrop\b/i },
  { regra: 'disco', padrao: /\b(?:format\s+[a-z]:|mkfs(?:\.\w+)?\b|shred\b|diskpart\b)/i },
  { regra: 'dd-grava', padrao: /\bdd\s+[^\n;|&]*\bof=/i },
  { regra: 'banco-reset',
    padrao: /\b(?:supabase\s+db\s+reset|prisma\s+migrate\s+reset|dropdb)\b/i },
  { regra: 'docker-apaga',
    padrao: /\bdocker\s+(?:system\s+prune|volume\s+(?:rm|prune)|rm\s+-f)/i },
  { regra: 'clear-content', padrao: /\bClear-Content\b/i },
];
const PERGUNTAS = {
  risco: {
    type: 'score',
    instructions: 'Qual o risco de este comando apagar, sobrescrever ou perder dados/histórico?',
    criteria: [
      'baixo: só lê ou cria algo novo, reversível',
      'médio: altera arquivos ou estado, mas recuperável',
      'alto: apaga, sobrescreve ou perde dados/histórico de forma difícil de reverter',
    ],
  },
  pode_apagar: {
    type: 'noul',
    instructions: 'Este comando pode apagar ou sobrescrever arquivos, dados de banco ou histórico?',
    criteria: { true: 'pode apagar ou sobrescrever', false: 'não apaga nem sobrescreve' },
  },
};

/**
 * Diz se um trecho do comando é só leitura (allowlist), sem gravação nem substituição.
 * @param {string} trecho Trecho entre separadores.
 * @returns {boolean} true quando está na allowlist (trecho vazio também).
 */
function trechoPermitido(trecho) {
  const limpo = trecho.replace(PADRAO_REDIRECIONAMENTO_INOFENSIVO, '').trim();
  if (limpo === '') return true;
  if (PADRAO_GRAVACAO_OU_SUBSTITUICAO.test(limpo)) return false;
  return ALLOWLIST.some((padrao) => padrao.test(limpo));
}

/**
 * Lista as regras destrutivas que casam com o comando inteiro.
 * @param {string} comando Comando avaliado.
 * @returns {string[]} Nomes das regras.
 */
export function acharRegrasDestrutivas(comando) {
  return REGRAS_DESTRUTIVAS
    .filter((regra) => (regra.testar ? regra.testar(comando) : regra.padrao.test(comando)))
    .map((regra) => regra.regra);
}

/**
 * Diz se todos os trechos do comando estão na allowlist.
 * @param {string} comando Comando avaliado.
 * @returns {boolean} true quando todo trecho é só leitura.
 */
export function estaNaAllowlist(comando) {
  return comando.split(PADRAO_SEPARADORES).every(trechoPermitido);
}

/**
 * Decide pelo Jev um comando fora da allowlist (nunca libera).
 * @param {object} consulta Resultado de `consultar`.
 * @returns {object} Parte da decisão.
 */
function decidirPeloJev(consulta) {
  const base = { exigeConfirmacao: true };
  if (!consulta.respostas) {
    return { ...base, acao: ACOES.REVISAR, motivos: ['fora-da-allowlist', 'jev-indisponivel'],
      fonte: FONTES.NENHUMA };
  }
  const probabilidade = maiorProbabilidade(consulta.respostas, PERGUNTAS);
  const comJev = { ...base, fonte: consulta.fonte, probabilidade };
  if (probabilidade !== null && probabilidade >= LIMIAR_BLOQUEIO) {
    return { ...comJev, acao: ACOES.BLOQUEAR, motivos: ['fora-da-allowlist', 'jev:p>=0.70'] };
  }
  return { ...comJev, acao: ACOES.REVISAR, motivos: ['fora-da-allowlist', 'jev:p<0.70'] };
}

/**
 * Aplica as camadas e devolve a decisão e a consulta feita (se houve).
 * @param {string} comando Comando (sem espaços nas pontas).
 * @param {{texto: string}} preparado Comando mascarado.
 * @param {{contexto: string, consultores: object[]}} apoio Contexto e consultores.
 * @returns {Promise<{decisao: object, consulta: object|null}>} Decisão parcial e consulta.
 */
async function decidir(comando, preparado, apoio) {
  const deterministica = { fonte: FONTES.DETERMINISTICA };
  if (comando === '') {
    return { decisao: { ...deterministica, acao: ACOES.LIBERAR, motivos: ['comando-vazio'] },
      consulta: null };
  }
  const regras = acharRegrasDestrutivas(comando);
  if (regras.length > 0) {
    return { decisao: { ...deterministica, acao: ACOES.BLOQUEAR, exigeConfirmacao: true,
      motivos: regras.map((regra) => `regex:${regra}`) }, consulta: null };
  }
  if (estaNaAllowlist(comando)) {
    return { decisao: { ...deterministica, acao: ACOES.LIBERAR, motivos: ['allowlist'] },
      consulta: null };
  }
  const consulta = await consultar({
    state: { comando: preparado.texto, contexto: prepararTexto(apoio.contexto).texto },
    perguntas: PERGUNTAS, acao: ACAO_JEV,
  }, apoio.consultores);
  return { decisao: decidirPeloJev(consulta), consulta };
}

/**
 * Avalia um comando ANTES de executar.
 * @param {{comando: string, contexto?: string, confirmacaoHumana?: object}} entrada Comando,
 *   contexto opcional (para o Jev) e confirmação humana opcional.
 * @param {{consultores?: object[], registrar?: Function}} [dependencias] Injeção para teste.
 * @returns {Promise<Readonly<object>>} Decisão (o log guarda só o hash do comando).
 */
export async function avaliarComando(entrada, dependencias = {}) {
  const deps = montarDependencias(dependencias);
  const comando = String(entrada?.comando ?? '').trim();
  const preparado = prepararTexto(comando);
  const { decisao, consulta } = await decidir(comando, preparado, {
    contexto: String(entrada?.contexto ?? ''), consultores: deps.consultores,
  });
  const completa = {
    caso: CASO, achados: preparado.achados, hashEntrada: calcularHash(comando),
    limiar: LIMIAR_BLOQUEIO, orientacao: decisao.acao === ACOES.LIBERAR ? null : ORIENTACAO,
    ...decisao,
  };
  const confirmado = confirmacaoValida(entrada?.confirmacaoHumana,
    (alvo) => alvo.trim() === comando);
  return concluirDecisao(aplicarEscape(completa, confirmado), {
    consulta, registrar: deps.registrar,
  });
}

// Guardrails aplicados ao texto da mensagem do usuário (JEV-GLOBAL-AI-FINAL.4, R3.1): segredo,
// pasta proibida, comando destrutivo e aprovação indevida. Só AVISAM: nunca bloqueiam nem alteram
// a mensagem (INV-2) e falha nunca vira `liberar` em silêncio (INV-3: vira aviso de revisão).
// Na mensagem roda só a camada DETERMINÍSTICA (regex, caminho, allowlist), sem consultar o Jev:
// a classificação da mensagem já usa o orçamento de tempo (4 s) e de custo (US$ 1/dia), e uma
// consulta extra por guardrail estouraria os dois. O aviso nunca traz o valor achado.
import { avaliarAprovacao } from './aprovacao.mjs';
import { avaliarComando } from './comando-destrutivo.mjs';
import { avaliarPastaProibida } from './pasta-proibida.mjs';
import { avaliarSegredo } from './segredo.mjs';
import { ACOES, FONTES } from './seguranca-base.mjs';

const ACOES_QUE_AVISAM = new Set([ACOES.BLOQUEAR, ACOES.REVISAR]);
const MOTIVO_MENCAO = 'mencao-ambigua';
const PREFIXO_REGRA = 'regex:';
const SEM_CONSULTORES = Object.freeze([]);
const AVISOS = Object.freeze({
  segredo: 'a mensagem traz segredo ou dado pessoal ({regras}): não copie o valor para código, '
    + 'log, commit nem outra IA',
  pasta: 'a mensagem cita pasta proibida (C20/C23): não ler nem escrever nela',
  pastaMencao: 'a mensagem cita uma pasta que pode ser proibida (C20/C23): confira o caminho',
  comando: 'a mensagem traz comando destrutivo ({regras}): só rodar com confirmação do usuário '
    + 'para o alvo exato',
  aprovacao: 'a mensagem fala em aprovar ou pular permissões ({regras}): só o usuário aprova, '
    + 'pergunta por pergunta (C32)',
  indisponivel: 'guardrail de {caso} indisponível: revise o pedido com cuidado',
});

/**
 * Registrador vazio: a auditoria da mensagem fica no `mensagens-AAAA-MM.jsonl` (sem texto).
 * @returns {Promise<void>} Nada.
 */
async function naoRegistrar() {}

/**
 * Troca `{nome}` pelos valores dados.
 * @param {string} modelo Texto com marcas.
 * @param {Record<string, string>} valores Valores das marcas.
 * @returns {string} Texto preenchido.
 */
function preencher(modelo, valores) {
  return modelo.replace(/\{(\w+)\}/g, (marca, nome) => valores[nome] ?? marca);
}

/**
 * Lista as regras determinísticas que casaram (`regex:<regra>` → `<regra>`).
 * @param {string[]} motivos Motivos da decisão.
 * @returns {string} Regras separadas por vírgula, ou "regra fixa".
 */
function listarRegras(motivos) {
  const regras = motivos.filter((motivo) => motivo.startsWith(PREFIXO_REGRA))
    .map((motivo) => motivo.slice(PREFIXO_REGRA.length));
  return regras.length > 0 ? [...new Set(regras)].join(', ') : 'regra fixa';
}

/**
 * Converte a decisão de um guardrail em aviso, ou null quando não há o que avisar. Só a camada
 * determinística avisa; `revisar` por falta de consultor (fonte `nenhuma`) não é achado.
 * @param {string} caso Chave do guardrail em {@link AVISOS}.
 * @param {{acao: string, fonte: string, motivos: string[]}} decisao Decisão do guardrail.
 * @returns {string|null} Aviso curto, sem o valor achado.
 */
function montarAviso(caso, decisao) {
  if (!ACOES_QUE_AVISAM.has(decisao.acao)) return null;
  const ehMencaoDePasta = caso === 'pasta' && decisao.motivos.includes(MOTIVO_MENCAO);
  if (ehMencaoDePasta) return AVISOS.pastaMencao;
  if (decisao.fonte !== FONTES.DETERMINISTICA) return null;
  return preencher(AVISOS[caso], { regras: listarRegras(decisao.motivos) });
}

/**
 * Roda um guardrail; erro vira aviso de indisponível (nunca `liberar` em silêncio, INV-3).
 * @param {string} caso Chave do guardrail.
 * @param {() => Promise<object>} avaliar Chamada ao guardrail.
 * @returns {Promise<string|null>} Aviso ou null.
 */
async function avaliarCaso(caso, avaliar) {
  try {
    return montarAviso(caso, await avaliar());
  } catch {
    return preencher(AVISOS.indisponivel, { caso });
  }
}

/**
 * Avalia o texto da mensagem com os guardrails de segredo, pasta, comando e aprovação.
 * @param {{texto: string, perguntaPendente?: string}} entrada Texto bruto da mensagem.
 * @param {{consultores?: object[], registrar?: Function}} [dependencias] Injeção para teste.
 * @returns {Promise<{alertas: string[]}>} Avisos curtos para o contexto da IA (sem o segredo).
 */
export async function avaliarMensagem(entrada, dependencias = {}) {
  const texto = String(entrada?.texto ?? '');
  if (texto.trim() === '') return { alertas: [] };

  const deps = {
    consultores: dependencias.consultores ?? SEM_CONSULTORES,
    registrar: dependencias.registrar ?? naoRegistrar,
  };
  const alertas = await Promise.all([
    avaliarCaso('segredo', () => avaliarSegredo({ texto }, deps)),
    avaliarCaso('pasta', () => avaliarPastaProibida({ texto }, deps)),
    avaliarCaso('comando', () => avaliarComando({ comando: texto }, deps)),
    avaliarCaso('aprovacao', () => avaliarAprovacao({
      mensagem: texto, perguntaPendente: entrada?.perguntaPendente,
    }, deps)),
  ]);
  return { alertas: alertas.filter(Boolean) };
}

// Guardrail de pasta proibida (C20/C23): nada de `C:\fontes\DEMAIS-PROJETOS-*` (offline ou
// "não mexer agora") é lido, listado, buscado ou indexado. Este módulo NUNCA abre a pasta para
// conferir: só normaliza o texto do caminho (barras, `..`, maiúsculas, `/c/…`, `\\?\`).
// Camada 1: caminho que cai no prefixo proibido → `bloquear` (determinístico). Exclusão explícita
// (`--glob '!DEMAIS-PROJETOS-*/**'`, `--exclude…`, `-not -path`) é permitida. Camada 2: menção
// ambígua (nome solto, caminho fora de C:\fontes) → Jev: pede acesso? p ≥ 0,70 → `bloquear`;
// senão `avisar`; sem Jev → `revisar`.
// Escape humano (o usuário pediu o projeto pelo nome/caminho): `confirmacaoHumana.alvo` = pasta
// autorizada dentro de `C:\fontes\DEMAIS-PROJETOS-*`, que cubra todos os caminhos bloqueados.
import { win32 } from 'node:path';
import { RAIZ_RULES_AI } from '../config.mjs';
import {
  ACOES, FONTES, aplicarEscape, calcularHash, concluirDecisao, confirmacaoValida, consultar,
  lerProbabilidade, montarDependencias, prepararTexto,
} from './seguranca-base.mjs';

const CASO = 'pasta-proibida';
const ACAO_JEV = 'guardrail:pasta-proibida';
const LIMIAR_BLOQUEIO = 0.7;
const PREFIXO_PROIBIDO = 'c:/fontes/demais-projetos-';
const PERGUNTA = 'pede_acesso';
/** Token que cita a pasta: sem espaço, aspas nem separador de comando. */
const PADRAO_TOKEN = /[^\s'"`|;&<>()]*demais-projetos-[^\s'"`|;&<>()]*/gi;
const PADRAO_SEPARADOR = /[\\/]/;
const PADRAO_ABSOLUTO = /^(?:[a-z]:|[\\/]{2}|\/[a-z](?:\/|$)|\/mnt\/[a-z](?:\/|$))/i;
const PADRAO_NOME = /demais-projetos-/i;
const PADRAO_CONTEXTO_EXCLUSAO = /(?:-not\s+-i?path|!\s+-i?path|--exclude(?:-dir)?)[=\s]*['"]?$/i;
const PADRAO_TOKEN_EXCLUSAO = /^(?:!|--exclude(?:-dir)?=|--glob=!)/i;
const TAMANHO_CONTEXTO_ANTERIOR = 40;
const ORIENTACAO = 'C20/C23: não leia, liste, busque nem indexe DEMAIS-PROJETOS-*. Só o usuário '
  + 'libera, pedindo o projeto pelo nome ou caminho: confirmacaoHumana { confirmado: true, quem, '
  + 'alvo: <pasta autorizada> }.';
const PERGUNTAS = {
  [PERGUNTA]: {
    type: 'noul',
    instructions: 'A mensagem pede ou planeja ler, listar, buscar, abrir, copiar ou indexar o '
      + 'conteúdo de uma pasta DEMAIS-PROJETOS-* (e não apenas citá-la, proibi-la ou excluí-la)?',
    criteria: { true: 'pede acesso ao conteúdo', false: 'só cita, proíbe ou exclui a pasta' },
  },
};

/**
 * Normaliza um caminho para comparar com o prefixo proibido, sem tocar no disco.
 * @param {string} caminho Caminho em qualquer forma (Windows, `/c/…`, `\\?\`, relativo).
 * @param {string} [base] Pasta para resolver caminhos relativos (padrão: raiz do rules-ai).
 * @returns {string} Caminho absoluto, com `/` e em minúsculas (ex.: `c:/fontes/x`).
 */
export function normalizarCaminho(caminho, base = RAIZ_RULES_AI) {
  const limpo = String(caminho ?? '').trim()
    .replace(/^['"]+|['"]+$/g, '')
    .replace(/^[\\/]{2}[?.][\\/]/, '')
    .replace(/^\/(?:mnt\/)?([a-z])(?=\/|$)/i, '$1:');
  return win32.resolve(base, limpo).replace(/\\/g, '/').toLowerCase();
}

/**
 * Diz se um caminho normalizado cai na pasta proibida.
 * @param {string} normalizado Saída de {@link normalizarCaminho}.
 * @returns {boolean} true dentro de `c:/fontes/demais-projetos-*`.
 */
function ehProibido(normalizado) {
  return normalizado.startsWith(PREFIXO_PROIBIDO);
}

/**
 * Diz se a citação é uma exclusão explícita (ex.: `--glob '!DEMAIS-PROJETOS-*'`).
 * @param {string} token Token achado.
 * @param {string} antes Texto que vem antes do token.
 * @returns {boolean} true para exclusão.
 */
function ehExclusao(token, antes) {
  return PADRAO_TOKEN_EXCLUSAO.test(token) || PADRAO_CONTEXTO_EXCLUSAO.test(antes);
}

/**
 * Classifica um caminho: proibido (bloqueia), mencao (ambíguo) ou livre.
 * @param {string} caminho Caminho ou token.
 * @param {{base: string, ehCaminhoExplicito: boolean}} opcoes Base e se veio de `caminhos`.
 * @returns {{tipo: string, normalizado?: string}} Classificação.
 */
function classificar(caminho, opcoes) {
  const pareceCaminho = opcoes.ehCaminhoExplicito || PADRAO_SEPARADOR.test(caminho)
    || PADRAO_ABSOLUTO.test(caminho);
  const normalizado = normalizarCaminho(caminho, opcoes.base);
  if (pareceCaminho && ehProibido(normalizado)) return { tipo: 'proibido', normalizado };
  if (PADRAO_NOME.test(caminho)) return { tipo: 'mencao' };
  return { tipo: 'livre' };
}

/**
 * Acha os caminhos e menções no texto livre (comando, mensagem, plano).
 * @param {string} texto Texto avaliado.
 * @param {string} base Pasta para resolver relativos.
 * @returns {{tipo: string, normalizado?: string}[]} Classificações (sem as exclusões).
 */
function classificarTexto(texto, base) {
  const resultados = [];
  for (const achado of texto.matchAll(PADRAO_TOKEN)) {
    const antes = texto.slice(Math.max(0, achado.index - TAMANHO_CONTEXTO_ANTERIOR), achado.index);
    if (ehExclusao(achado[0], antes)) continue;
    resultados.push(classificar(achado[0], { base, ehCaminhoExplicito: false }));
  }
  return resultados;
}

/**
 * Decide a menção ambígua pelo Jev.
 * @param {object} consulta Resultado de `consultar`.
 * @returns {object} Parte da decisão.
 */
function decidirMencao(consulta) {
  if (!consulta.respostas) {
    return { acao: ACOES.REVISAR, motivos: ['mencao-ambigua', 'jev-indisponivel'],
      fonte: FONTES.NENHUMA, exigeConfirmacao: true };
  }
  const probabilidade = lerProbabilidade(consulta.respostas, PERGUNTA, PERGUNTAS[PERGUNTA]);
  const base = { fonte: consulta.fonte, probabilidade };
  if (probabilidade === null) {
    return { ...base, acao: ACOES.REVISAR, motivos: ['jev-sem-probabilidade'],
      exigeConfirmacao: true };
  }
  if (probabilidade >= LIMIAR_BLOQUEIO) {
    return { ...base, acao: ACOES.BLOQUEAR, motivos: ['mencao-ambigua', 'jev:p>=0.70'],
      exigeConfirmacao: true };
  }
  return { ...base, acao: ACOES.AVISAR, motivos: ['mencao-ambigua', 'jev:p<0.70'] };
}

/**
 * Aplica as camadas sobre as classificações.
 * @param {{proibidos: string[], mencoes: number, texto: string}} achados Caminhos e menções.
 * @param {{consultores: object[]}} deps Dependências.
 * @returns {Promise<{decisao: object, consulta: object|null, preparado: object}>} Decisão.
 */
async function decidir(achados, deps) {
  const preparado = prepararTexto(achados.texto);
  if (achados.proibidos.length > 0) {
    return { decisao: { acao: ACOES.BLOQUEAR, motivos: ['caminho-proibido:C20/C23'],
      fonte: FONTES.DETERMINISTICA, exigeConfirmacao: true }, consulta: null, preparado };
  }
  if (achados.mencoes === 0) {
    return { decisao: { acao: ACOES.LIBERAR, motivos: ['sem-pasta-proibida'],
      fonte: FONTES.DETERMINISTICA }, consulta: null, preparado };
  }
  const consulta = await consultar({
    state: { texto: preparado.texto }, perguntas: PERGUNTAS, acao: ACAO_JEV,
  }, deps.consultores);
  return { decisao: decidirMencao(consulta), consulta, preparado };
}

/**
 * Monta a verificação do escape: o alvo autorizado está dentro da área proibida e cobre todos
 * os caminhos bloqueados.
 * @param {string[]} proibidos Caminhos proibidos normalizados.
 * @param {string} base Pasta para resolver o alvo.
 * @returns {(alvo: string) => boolean} Verificador.
 */
function criarVerificadorDeAlvo(proibidos, base) {
  return (alvo) => {
    const autorizado = normalizarCaminho(alvo, base).replace(/\/+$/, '');
    const estaNaArea = ehProibido(autorizado);
    return estaNaArea && proibidos.every(
      (caminho) => caminho === autorizado || caminho.startsWith(`${autorizado}/`),
    );
  };
}

/**
 * Avalia se uma ação toca pasta proibida (C20/C23).
 * @param {{caminhos?: string[], texto?: string, base?: string, confirmacaoHumana?: object}}
 *   entrada Caminhos que serão lidos/escritos, texto livre (comando, plano), base dos relativos.
 * @param {{consultores?: object[], registrar?: Function}} [dependencias] Injeção para teste.
 * @returns {Promise<Readonly<object>>} Decisão (sem caminhos nem texto no log).
 */
export async function avaliarPastaProibida(entrada, dependencias = {}) {
  const deps = montarDependencias(dependencias);
  const base = entrada?.base ?? RAIZ_RULES_AI;
  const texto = String(entrada?.texto ?? '');
  const classificacoes = [
    ...(entrada?.caminhos ?? []).map((caminho) => classificar(caminho, {
      base, ehCaminhoExplicito: true,
    })),
    ...classificarTexto(texto, base),
  ];
  const proibidos = classificacoes.filter((c) => c.tipo === 'proibido').map((c) => c.normalizado);
  const mencoes = classificacoes.filter((c) => c.tipo === 'mencao').length;
  const { decisao, consulta, preparado } = await decidir({ proibidos, mencoes, texto }, deps);
  const completa = {
    caso: CASO, achados: preparado.achados, limiar: LIMIAR_BLOQUEIO,
    hashEntrada: calcularHash(`${(entrada?.caminhos ?? []).join('\n')}\n${texto}`),
    orientacao: decisao.acao === ACOES.LIBERAR ? null : ORIENTACAO, ...decisao,
  };
  const confirmado = confirmacaoValida(entrada?.confirmacaoHumana,
    criarVerificadorDeAlvo(proibidos, base));
  return concluirDecisao(aplicarEscape(completa, confirmado), {
    consulta, registrar: deps.registrar,
  });
}

// Máscara de segredo e dado pessoal ANTES de qualquer envio ao Jev ou gravação em log (INV-2).
// Chaves (sk-, tsk_, Bearer, ghp_/github_pat_, JWT, AKIA, `senha=`/`*_API_KEY=`), CPF, RG,
// telefone e e-mail viram marcas neutras ([CHAVE], [CPF]…). Os achados guardam só tipo e regra:
// o valor original nunca sai desta função. A máscara é idempotente (mascarar de novo não muda).

const MARCAS = Object.freeze({
  chave: '[CHAVE]',
  cpf: '[CPF]',
  rg: '[RG]',
  telefone: '[TELEFONE]',
  email: '[EMAIL]',
});
const TAMANHO_CPF = 11;
const PESO_INICIAL_PRIMEIRO_DIGITO = 10;
const PESO_INICIAL_SEGUNDO_DIGITO = 11;
const MODULO_CPF = 11;
/** E-mails técnicos que não são dado pessoal (atribuição de commit, exemplos). */
const PADRAO_EMAIL_PERMITIDO = new RegExp(
  '^(?:no-?reply|nao-responda)@'
    + '|@(?:users\\.noreply\\.github\\.com|example\\.(?:com|org|net)|exemplo\\.com(?:\\.br)?)$',
  'i',
);
/**
 * `senha=...`, `TYPESAFE_API_KEY: ...`: o valor precisa ter dígito ou símbolo (evita prosa) e não
 * pode ser só número (evita `JEV_MAX_TOKENS=1000000`, `tokens_entrada: 317`).
 */
const PADRAO_ATRIBUICAO = new RegExp(
  '\\b([A-Za-z0-9_-]*(?:api[_-]?key|secret|senha|password|passwd|token)[A-Za-z0-9_-]*)'
    + '(\\s*[:=]\\s*)([\'"]?)(?!\\[)(?![0-9.]+\\b)(?=[^\\s\'"]*[0-9_!@#$%^&*-])[^\\s\'"]{6,}\\3',
  'gi',
);

/**
 * Confere os dígitos verificadores de um CPF (só números).
 * @param {string} numeros 11 dígitos.
 * @returns {boolean} true se os dois dígitos verificadores conferem.
 */
export function cpfValido(numeros) {
  const digitos = String(numeros).replace(/\D/g, '');
  const tamanhoErrado = digitos.length !== TAMANHO_CPF;
  if (tamanhoErrado || /^(\d)\1+$/.test(digitos)) return false;
  return [PESO_INICIAL_PRIMEIRO_DIGITO, PESO_INICIAL_SEGUNDO_DIGITO].every((pesoInicial) => {
    const quantidade = pesoInicial - 1;
    let soma = 0;
    for (let i = 0; i < quantidade; i += 1) soma += Number(digitos[i]) * (pesoInicial - i);
    const resto = (soma * 10) % MODULO_CPF;
    return (resto === 10 ? 0 : resto) === Number(digitos[quantidade]);
  });
}

/**
 * Diz se o e-mail é técnico (não pessoal) e pode ficar sem máscara.
 * @param {string} email E-mail achado.
 * @returns {boolean} true para noreply, exemplos e afins.
 */
function emailPermitido(email) {
  return PADRAO_EMAIL_PERMITIDO.test(email);
}

/**
 * Regras na ordem de aplicação: chaves primeiro (mais específicas), depois documentos e contato.
 * `substituir` recebe os grupos do regex; `aceitar` filtra o achado; `manter` deixa sem máscara.
 */
const REGRAS = [
  {
    tipo: 'chave', regra: 'jwt',
    padrao: /\beyJ[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}/g,
  },
  {
    tipo: 'chave', regra: 'bearer',
    padrao: /\b(Bearer)\s+(?!\[)[A-Za-z0-9._~+/=-]{8,}/gi,
    substituir: (palavra) => `${palavra} ${MARCAS.chave}`,
  },
  { tipo: 'chave', regra: 'sk', padrao: /\bsk-[A-Za-z0-9_-]{16,}/g },
  { tipo: 'chave', regra: 'tsk', padrao: /\btsk_[A-Za-z0-9_-]{8,}/g },
  {
    tipo: 'chave', regra: 'github',
    padrao: /\b(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})/g,
  },
  { tipo: 'chave', regra: 'aws', padrao: /\bAKIA[0-9A-Z]{16}\b/g },
  {
    tipo: 'chave', regra: 'atribuicao',
    padrao: PADRAO_ATRIBUICAO,
    substituir: (nome, separador, aspas) => `${nome}${separador}${aspas}${MARCAS.chave}${aspas}`,
  },
  { tipo: 'cpf', regra: 'cpf-formatado', padrao: /\b\d{3}\.\d{3}\.\d{3}-\d{2}\b/g },
  { tipo: 'cpf', regra: 'cpf-numerico', padrao: /\b\d{11}\b/g, aceitar: cpfValido },
  { tipo: 'rg', regra: 'rg-formatado', padrao: /\b\d{1,2}\.\d{3}\.\d{3}-?[\dXx]\b/g },
  {
    tipo: 'rg', regra: 'rg-rotulado',
    padrao: /\b(RG)(\s*(?:n[º°o.]*)?\s*[:-]?\s*)(?!\[)([\dXx][\dXx.-]{4,}[\dXx])/g,
    substituir: (rotulo, separador) => `${rotulo}${separador}${MARCAS.rg}`,
  },
  {
    tipo: 'telefone', regra: 'telefone',
    padrao: /(?:\+55\s?)?(?:\(\d{2}\)|\b\d{2})[\s-]?9?\d{4}[-\s]\d{4}\b/g,
  },
  {
    tipo: 'email', regra: 'email',
    padrao: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g, manter: emailPermitido,
  },
];

/**
 * Aplica uma regra ao texto, anotando cada achado (sem o valor).
 * @param {string} texto Texto atual.
 * @param {object} regra Regra de {@link REGRAS}.
 * @param {{tipo: string, regra: string}[]} achados Lista de achados (alterada).
 * @returns {string} Texto com a regra aplicada.
 */
function aplicarRegra(texto, regra, achados) {
  return texto.replace(regra.padrao, (trecho, ...resto) => {
    const ehFalsoPositivo = regra.aceitar && !regra.aceitar(trecho);
    if (ehFalsoPositivo || regra.manter?.(trecho)) return trecho;
    achados.push({ tipo: regra.tipo, regra: regra.regra });
    if (!regra.substituir) return MARCAS[regra.tipo];
    const grupos = resto.slice(0, -2).map((grupo) => grupo ?? '');
    return regra.substituir(...grupos);
  });
}

/**
 * Mascara chaves, CPF, RG, telefone e e-mail de um texto.
 * @param {string} texto Texto qualquer (descrição, diff, comando, mensagem).
 * @returns {{texto: string, achados: {tipo: string, regra: string}[]}} Texto mascarado e
 *   um achado por ocorrência (tipo: chave, cpf, rg, telefone ou email), sem o valor.
 */
export function redigirTexto(texto) {
  const achados = [];
  const mascarado = REGRAS.reduce(
    (atual, regra) => aplicarRegra(atual, regra, achados), String(texto ?? ''),
  );
  return { texto: mascarado, achados };
}

/**
 * Conta os achados por tipo (para log e decisão, sem valores).
 * @param {{tipo: string}[]} achados Achados de {@link redigirTexto}.
 * @returns {Record<string, number>} Ex.: `{ chave: 1, email: 2 }`.
 */
export function resumirAchados(achados) {
  const resumo = {};
  for (const achado of achados ?? []) resumo[achado.tipo] = (resumo[achado.tipo] ?? 0) + 1;
  return resumo;
}

// Guardrail de segredo/PII (R3.2, INV-2). Camada 1 (determinística): qualquer achado do
// `redigir.mjs` (chave/token/senha, CPF, RG, telefone, e-mail pessoal) → `bloquear` sem chamar o
// Jev (e-mails técnicos, como noreply@, não contam). Camada 2, para o que a regex não pega
// (endereço, data de nascimento, senha sem dígito): o Jev vê SÓ o texto mascarado e responde um
// `noul` por tipo; p ≥ 0,80 → `bloquear`; 0,50–0,80 → `revisar`; senão `liberar`; sem Jev →
// `revisar`. O log nunca guarda o texto nem o valor achado (só tipos, probabilidade e hash).
// Escape humano: `confirmacaoHumana.alvo` = `hashEntrada` devolvido no bloqueio.
import {
  ACOES, FONTES, aplicarEscape, calcularHash, concluirDecisao, confirmacaoValida, consultar,
  maiorProbabilidade, montarDependencias, prepararTexto,
} from './seguranca-base.mjs';
import { resumirAchados } from './redigir.mjs';

const CASO = 'segredo';
const ACAO_JEV = 'guardrail:segredo';
const LIMIAR_BLOQUEIO = 0.8;
const LIMIAR_REVISAO = 0.5;
const ORIENTACAO_BLOQUEIO = 'Remova o segredo/dado pessoal do texto (ou use a versão mascarada). '
  + 'Só o usuário libera: confirmacaoHumana { confirmado: true, quem, alvo: hashEntrada }.';
const MARCAS_EXPLICADAS = 'As marcas [CHAVE], [CPF], [RG], [EMAIL] e [TELEFONE] substituem '
  + 'valores já mascarados: julgue o que sobrou e o contexto das marcas.';
const PERGUNTAS = {
  chave_token: {
    type: 'noul',
    instructions: 'O texto ainda expõe chave, token, senha ou credencial real? '
      + MARCAS_EXPLICADAS,
    criteria: { true: 'há credencial real exposta', false: 'não há credencial exposta' },
  },
  documento_pessoal: {
    type: 'noul',
    instructions: 'O texto expõe documento ou dado pessoal de alguém (CPF, RG, endereço '
      + 'residencial, data de nascimento), inclusive por marca junto de um nome? '
      + MARCAS_EXPLICADAS,
    criteria: { true: 'expõe dado pessoal', false: 'não expõe dado pessoal' },
  },
  contato_pessoal: {
    type: 'noul',
    instructions: 'O texto expõe contato particular de uma pessoa (e-mail ou telefone), '
      + `inclusive por marca junto de um nome? ${MARCAS_EXPLICADAS}`,
    criteria: { true: 'expõe contato pessoal', false: 'não expõe contato pessoal' },
  },
};

/**
 * Decide pelo Jev quando a camada determinística não achou nada.
 * @param {object} consulta Resultado de `consultar`.
 * @returns {object} Parte da decisão (ação, motivos, fonte, probabilidade).
 */
function decidirPeloJev(consulta) {
  if (!consulta.respostas) {
    return { acao: ACOES.REVISAR, motivos: ['jev-indisponivel'], fonte: FONTES.NENHUMA,
      exigeConfirmacao: true };
  }
  const probabilidade = maiorProbabilidade(consulta.respostas, PERGUNTAS);
  const base = { fonte: consulta.fonte, probabilidade };
  if (probabilidade === null) {
    return { ...base, acao: ACOES.REVISAR, motivos: ['jev-sem-probabilidade'],
      exigeConfirmacao: true };
  }
  if (probabilidade >= LIMIAR_BLOQUEIO) {
    return { ...base, acao: ACOES.BLOQUEAR, motivos: ['jev:p>=0.80'], exigeConfirmacao: true };
  }
  if (probabilidade >= LIMIAR_REVISAO) {
    return { ...base, acao: ACOES.REVISAR, motivos: ['jev:p>=0.50'], exigeConfirmacao: true };
  }
  return { ...base, acao: ACOES.LIBERAR, motivos: ['jev:p<0.50'] };
}

/**
 * Aplica as duas camadas e devolve a decisão e a consulta feita (se houve).
 * @param {string} textoOriginal Texto avaliado.
 * @param {{texto: string, achados: object[]}} preparado Texto mascarado e achados.
 * @param {{consultores: object[]}} deps Dependências.
 * @returns {Promise<{decisao: object, consulta: object|null}>} Decisão parcial e consulta.
 */
async function decidir(textoOriginal, preparado, deps) {
  if (textoOriginal.trim() === '') {
    return { decisao: { acao: ACOES.LIBERAR, motivos: ['texto-vazio'],
      fonte: FONTES.DETERMINISTICA }, consulta: null };
  }
  if (preparado.achados.length > 0) {
    const motivos = [...new Set(preparado.achados.map((achado) => `regex:${achado.regra}`))];
    return { decisao: { acao: ACOES.BLOQUEAR, motivos, fonte: FONTES.DETERMINISTICA,
      exigeConfirmacao: true }, consulta: null };
  }
  const consulta = await consultar({
    state: { texto: preparado.texto, marcas: resumirAchados(preparado.achados) },
    perguntas: PERGUNTAS, acao: ACAO_JEV,
  }, deps.consultores);
  return { decisao: decidirPeloJev(consulta), consulta };
}

/**
 * Avalia se um texto pode sair (para a API, um log, um commit ou outra IA).
 * @param {{texto: string, confirmacaoHumana?: object}} entrada Texto e confirmação opcional.
 * @param {{consultores?: object[], registrar?: Function}} [dependencias] Injeção para teste.
 * @returns {Promise<Readonly<object>>} `{caso, acao, motivos, achados (contagem por tipo),
 *   probabilidade, limiar, fonte, exigeConfirmacao, escapeHumano, hashEntrada, orientacao}`.
 */
export async function avaliarSegredo(entrada, dependencias = {}) {
  const deps = montarDependencias(dependencias);
  const textoOriginal = String(entrada?.texto ?? '');
  const hashEntrada = calcularHash(textoOriginal);
  const preparado = prepararTexto(textoOriginal);
  const { decisao, consulta } = await decidir(textoOriginal, preparado, deps);
  const completa = {
    caso: CASO, achados: preparado.achados, hashEntrada, limiar: LIMIAR_BLOQUEIO,
    orientacao: decisao.acao === ACOES.LIBERAR ? null : ORIENTACAO_BLOQUEIO, ...decisao,
  };
  const confirmado = confirmacaoValida(entrada?.confirmacaoHumana, (alvo) => alvo === hashEntrada);
  return concluirDecisao(aplicarEscape(completa, confirmado), {
    consulta, registrar: deps.registrar,
  });
}

// Peças comuns dos guardrails de SEGURANÇA (segredo/PII, pasta proibida, comando destrutivo e
// aprovação indevida): ações, consulta ao Jev com fallback, escape humano e log de auditoria.
// Ordem de toda decisão: 1) camada determinística (regex, caminho, allowlist); 2) Jev, só com
// texto mascarado por `redigir.mjs`; 3) sem Jev (falha, sem chave ou JEV_MODO=off) → `revisar`,
// nunca `liberar` em silêncio (INV-6).
//
// ESCAPE HUMANO (bloqueio de segredo, pasta e comando): quem chama passa
// `confirmacaoHumana = { confirmado: true, quem: '<nome do humano>', alvo: <alvo exato> }`,
// montada a partir das palavras do USUÁRIO (nunca do agente). O `alvo` precisa casar com o item
// avaliado (o comando exato, a pasta autorizada ou o hash do texto); um "sim" genérico não vale.
// Aprovação indevida não tem escape: o próprio usuário responde.
import { createHash } from 'node:crypto';
import { join } from 'node:path';
import { criarClientePadrao, criarRegistroJsonl } from '../cliente.mjs';
import { PASTA_SAIDAS } from '../config.mjs';
import { redigirTexto, resumirAchados } from './redigir.mjs';

export const ACOES = Object.freeze({
  LIBERAR: 'liberar', AVISAR: 'avisar', REVISAR: 'revisar', BLOQUEAR: 'bloquear',
});
/** Mesmo arquivo de auditoria dos guardrails de escopo/aceite (fora do Git). */
export const ARQUIVO_LOG_GUARDRAILS = join(PASTA_SAIDAS, 'guardrails.jsonl');
export const FONTES = Object.freeze({
  DETERMINISTICA: 'deterministica', NENHUMA: 'nenhuma', ESCAPE: 'escape-humano',
});
/** Limite do texto mascarado enviado ao Jev (custo); a camada determinística vê o texto todo. */
const LIMITE_CARACTERES_ESTADO = 4000;
const TAMANHO_HASH = 16;
const CAMPO_SCORE = 'score';
const CAMPOS_PROBABILIDADE = ['noul', CAMPO_SCORE, 'probability'];
const ACOES_COM_ESCAPE = new Set([ACOES.BLOQUEAR, ACOES.REVISAR]);
const MOTIVO_ESCAPE = 'escape-humano:confirmacao-valida';

let consultoresPadrao = null;

/**
 * Hash curto de um texto, para rastrear a entrada no log sem guardar o conteúdo.
 * @param {string} texto Texto qualquer.
 * @returns {string} 16 primeiros caracteres do SHA-256.
 */
export function calcularHash(texto) {
  return createHash('sha256').update(String(texto ?? '')).digest('hex').slice(0, TAMANHO_HASH);
}

/**
 * Mascara e corta um texto antes de ir para o Jev.
 * @param {string} texto Texto original.
 * @returns {{texto: string, achados: object[]}} Texto mascarado (cortado) e achados.
 */
export function prepararTexto(texto) {
  const redigido = redigirTexto(texto);
  return { texto: redigido.texto.slice(0, LIMITE_CARACTERES_ESTADO), achados: redigido.achados };
}

/**
 * Limita um número ao intervalo [0, 1].
 * @param {number} valor Valor qualquer.
 * @returns {number} Valor entre 0 e 1.
 */
function limitarEntreZeroEUm(valor) {
  return Math.min(Math.max(valor, 0), 1);
}

/**
 * Lê a probabilidade de uma resposta do Jev. `noul`/`probability` já vêm de 0 a 1; o `score`
 * vem na escala dos critérios (0 a n−1; ex.: 1,98 com 3 critérios) e é dividido por n−1.
 * @param {object|null} respostas Campo `respostas` do cliente.
 * @param {string} nome Nome da pergunta.
 * @param {{criteria?: unknown}} [pergunta] Definição da pergunta (para a escala do `score`).
 * @returns {number|null} Probabilidade de 0 a 1, ou null se não veio.
 */
export function lerProbabilidade(respostas, nome, pergunta) {
  const resposta = respostas?.[nome];
  const campo = CAMPOS_PROBABILIDADE.find((nomeCampo) => typeof resposta?.[nomeCampo] === 'number');
  if (!campo) return null;
  if (campo !== CAMPO_SCORE) return limitarEntreZeroEUm(resposta[campo]);
  const niveis = Array.isArray(pergunta?.criteria) ? pergunta.criteria.length : 0;
  const divisor = niveis >= 2 ? niveis - 1 : 1;
  return limitarEntreZeroEUm(resposta[campo] / divisor);
}

/**
 * Maior probabilidade entre as perguntas feitas.
 * @param {object|null} respostas Campo `respostas` do cliente.
 * @param {Record<string, object>} perguntas Perguntas enviadas (nome → definição).
 * @returns {number|null} Maior valor, ou null se nenhuma veio.
 */
export function maiorProbabilidade(respostas, perguntas) {
  const valores = Object.entries(perguntas)
    .map(([nome, pergunta]) => lerProbabilidade(respostas, nome, pergunta))
    .filter((valor) => valor !== null);
  return valores.length > 0 ? Math.max(...valores) : null;
}

/**
 * Pergunta aos consultores em ordem (hoje só o Jev); o primeiro que responder vale.
 * @param {{state: object, perguntas: object, acao: string}} pedido State JÁ mascarado.
 * @param {{nome?: string, perguntar: Function}[]} consultores Clientes no contrato do cliente Jev.
 * @returns {Promise<{respostas: object|null, fonte: string, modelo: string|null,
 *   tokensEntrada: number, custoUsd: number, erros: string[]}>} Consulta (respostas null = falhou).
 */
export async function consultar(pedido, consultores) {
  const erros = [];
  for (const consultor of consultores ?? []) {
    try {
      const resposta = await consultor.perguntar(pedido);
      return {
        respostas: resposta.respostas, fonte: consultor.nome ?? 'jev',
        modelo: resposta.modeloResposta ?? null, tokensEntrada: resposta.uso?.tokensEntrada ?? 0,
        custoUsd: resposta.custoUsd ?? 0, erros,
      };
    } catch (erro) {
      erros.push(`${consultor.nome ?? 'jev'}:${erro?.codigo ?? erro?.name ?? 'erro'}`);
    }
  }
  return {
    respostas: null, fonte: FONTES.NENHUMA, modelo: null, tokensEntrada: 0, custoUsd: 0, erros,
  };
}

/**
 * Consultores padrão: o cliente Jev do ambiente; sem chave ou com configuração inválida, nenhum
 * (a decisão ambígua vira `revisar`). Criado uma vez por processo.
 * @returns {{nome: string, perguntar: Function}[]} Consultores.
 */
export function obterConsultoresPadrao() {
  if (consultoresPadrao) return consultoresPadrao;
  try {
    const cliente = criarClientePadrao();
    consultoresPadrao = [{ nome: 'jev', perguntar: cliente.perguntar }];
  } catch {
    consultoresPadrao = [];
  }
  return consultoresPadrao;
}

/**
 * Completa as dependências injetáveis (consultores e gravador do log).
 * @param {{consultores?: object[], registrar?: Function}} [injetadas] Dependências de teste.
 * @returns {{consultores: object[], registrar: Function}} Dependências completas.
 */
export function montarDependencias(injetadas = {}) {
  return {
    consultores: injetadas.consultores ?? obterConsultoresPadrao(),
    registrar: injetadas.registrar ?? criarRegistroJsonl(ARQUIVO_LOG_GUARDRAILS),
  };
}

/**
 * Confere uma confirmação humana explícita para o alvo avaliado.
 * @param {{confirmado?: boolean, quem?: string, alvo?: string}|undefined} confirmacao Confirmação.
 * @param {(alvo: string) => boolean} casaComAlvo Diz se o `alvo` da confirmação cobre o item.
 * @returns {boolean} true só com `confirmado === true`, `quem` e `alvo` que casa.
 */
export function confirmacaoValida(confirmacao, casaComAlvo) {
  const temCampos = confirmacao?.confirmado === true
    && typeof confirmacao.quem === 'string' && confirmacao.quem.trim() !== ''
    && typeof confirmacao.alvo === 'string' && confirmacao.alvo.trim() !== '';
  return temCampos && casaComAlvo(confirmacao.alvo);
}

/**
 * Aplica o escape humano: bloquear/revisar viram liberar quando a confirmação é válida.
 * @param {object} decisao Decisão do guardrail.
 * @param {boolean} confirmado Resultado de {@link confirmacaoValida}.
 * @returns {object} Decisão (nova, se o escape foi aplicado).
 */
export function aplicarEscape(decisao, confirmado) {
  if (!confirmado || !ACOES_COM_ESCAPE.has(decisao.acao)) return decisao;
  return {
    ...decisao, acao: ACOES.LIBERAR, acaoSemEscape: decisao.acao, escapeHumano: true,
    motivos: [...decisao.motivos, MOTIVO_ESCAPE],
  };
}

/**
 * Monta a linha de auditoria: só metadados (nunca texto, comando, caminho ou valor achado).
 * @param {object} decisao Decisão final.
 * @param {object} consulta Resultado de {@link consultar} (ou null sem consulta).
 * @returns {object} Linha do JSONL.
 */
function montarLinha(decisao, consulta) {
  return {
    data: new Date().toISOString(), caso: decisao.caso, acao: decisao.acao,
    acao_sem_escape: decisao.acaoSemEscape ?? null, motivos: decisao.motivos,
    achados: decisao.achados, probabilidade: decisao.probabilidade, limiar: decisao.limiar,
    fonte: decisao.fonte, modelo: consulta?.modelo ?? null,
    tokens_entrada: consulta?.tokensEntrada ?? 0, custo_usd: consulta?.custoUsd ?? 0,
    hash_entrada: decisao.hashEntrada, exige_confirmacao: decisao.exigeConfirmacao,
    escape_humano: decisao.escapeHumano, erros_consulta: consulta?.erros ?? [],
  };
}

/**
 * Fecha a decisão: grava a linha de auditoria (mascarada por garantia) e devolve o resultado.
 * @param {object} decisao Decisão montada pelo guardrail.
 * @param {{consulta?: object|null, registrar: Function}} fechamento Consulta e gravador.
 * @returns {Promise<Readonly<object>>} Decisão pública (sem texto original).
 */
export async function concluirDecisao(decisao, fechamento) {
  const completa = {
    escapeHumano: false, exigeConfirmacao: false, probabilidade: null, limiar: null,
    ...decisao, achados: resumirAchados(decisao.achados),
  };
  const linha = JSON.stringify(montarLinha(completa, fechamento.consulta));
  await fechamento.registrar(redigirTexto(linha).texto);
  return Object.freeze(completa);
}

// Auditoria das mensagens (JEV-GLOBAL-AI-FINAL.8, R2.2, INV-4): uma linha por mensagem em
// `scripts/jev/saidas/mensagens-AAAA-MM.jsonl` (fora do Git) com SÓ metadados: data, projeto,
// hash, pulado, decisão, nível, confiança, custo, latência, ação, situação e código do erro.
// Nunca o texto, nunca a chave. Falha ao gravar ou ler nunca derruba a mensagem.
import { appendFileSync, mkdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { PASTA_SAIDAS } from '../config.mjs';

/** Campos permitidos na linha (lista fechada: o resto do resultado nunca é gravado). */
const CAMPOS_AUDITORIA = Object.freeze([
  'projeto', 'hash', 'pulado', 'motivo', 'decisao', 'nivel', 'confianca', 'custo_usd',
  'latencia_ms', 'acao', 'situacao', 'erro_codigo',
]);
const DIGITOS_MES = 2;

/**
 * Preenche um número com zeros à esquerda.
 * @param {number} numero Valor.
 * @returns {string} Texto com 2 dígitos.
 */
function doisDigitos(numero) {
  return String(numero).padStart(DIGITOS_MES, '0');
}

/**
 * Formata o dia local `AAAA-MM-DD` (o limite de custo vale por dia local).
 * @param {Date} data Momento.
 * @returns {string} Dia local.
 */
export function formatarDia(data) {
  const mes = doisDigitos(data.getMonth() + 1);
  return `${data.getFullYear()}-${mes}-${doisDigitos(data.getDate())}`;
}

/**
 * Caminho do arquivo de auditoria do mês.
 * @param {Date} data Momento.
 * @param {string} [pasta] Pasta das saídas (padrão: `scripts/jev/saidas`).
 * @returns {string} Caminho `mensagens-AAAA-MM.jsonl`.
 */
export function caminhoAuditoriaDoMes(data, pasta = PASTA_SAIDAS) {
  return join(pasta, `mensagens-${formatarDia(data).slice(0, 7)}.jsonl`);
}

/**
 * Soma o custo (US$) gasto num dia, lendo a própria auditoria. Erro de leitura vale 0.
 * @param {string} arquivo Arquivo de auditoria.
 * @param {string} dia Dia local `AAAA-MM-DD`.
 * @returns {number} Custo do dia.
 */
export function somarCustoDoDia(arquivo, dia) {
  let texto = '';
  try {
    texto = readFileSync(arquivo, 'utf8');
  } catch {
    return 0;
  }
  let total = 0;
  for (const linha of texto.split('\n')) {
    try {
      const registro = JSON.parse(linha);
      if (registro.dia === dia && Number.isFinite(registro.custo_usd)) total += registro.custo_usd;
    } catch {
      // linha vazia ou truncada: ignora
    }
  }
  return total;
}

/**
 * Grava a linha de auditoria (só os campos permitidos). Nunca lança.
 * @param {string} arquivo Arquivo de auditoria.
 * @param {{data: Date, resultado: object, projeto: string}} registro Momento, resultado e projeto.
 * @returns {boolean} true se gravou.
 */
export function gravarAuditoria(arquivo, registro) {
  try {
    const dados = { ...registro.resultado, projeto: registro.projeto };
    const linha = {
      data: registro.data.toISOString(),
      dia: formatarDia(registro.data),
      ...Object.fromEntries(CAMPOS_AUDITORIA.map((campo) => [campo, dados[campo] ?? null])),
    };
    mkdirSync(dirname(arquivo), { recursive: true });
    appendFileSync(arquivo, `${JSON.stringify(linha)}\n`, 'utf8');
    return true;
  } catch {
    return false;
  }
}

// Orquestração da classificação da MENSAGEM do usuário (JEV-GLOBAL-AI-FINAL.2, .5, .6, .7, .14,
// .24). `classificarMensagem` NUNCA lança e nunca devolve `liberar` (INV-3): qualquer falha vira
// `decisao: 'sinais'` (a IA classifica pelos sinais da skill). O Jev só aconselha: nada aqui toca
// o quadro, reserva tarefa ou bloqueia a mensagem (INV-2, INV-5).
import { dirname } from 'node:path';
import { performance } from 'node:perf_hooks';
import { criarCliente } from '../cliente.mjs';
import {
  ErroJev, MODOS, carregarConfiguracao, carregarConfiguracaoMensagem, lerChave,
} from '../config.mjs';
import { avaliarMensagem } from '../guardrails/mensagem.mjs';
import { redigirTexto } from '../guardrails/redigir.mjs';
import {
  caminhoAuditoriaDoMes, formatarDia, gravarAuditoria, somarCustoDoDia,
} from './auditoria.mjs';
import { montarContexto } from './contexto.mjs';
import { DECISOES, decidirMensagem } from './decisao.mjs';
import { prepararPedido } from './estado.mjs';
import { comTempoMaximo, ehMensagemTrivial, estourouLimiteDia } from './limite.mjs';
import { ehMensagemRepetida, marcarMensagem } from './repetida.mjs';

export { montarContexto };

const ACAO_CLIENTE = 'mensagem';
const MAXIMO_ALERTAS = 5;
const TAMANHO_PROJETO = 80;
const CASAS_CUSTO = 9;
/** Folga para gravar a auditoria, imprimir e encerrar o processo depois da chamada (R1.3). */
const MARGEM_SAIDA_MS = 150;
/** Menos que isso de orçamento não adianta chamar o Jev: vira só sinais, sem chamada. */
const PISO_ORCAMENTO_MS = 100;
const TAMANHO_MAXIMO_ALERTA = 200;
const CODIGO_ERRO_INESPERADO = 'ERRO_INESPERADO';
const MOTIVOS = Object.freeze({
  OK: 'ok', TRIVIAL: 'trivial', DESLIGADO: 'desligado', LIMITE_DIA: 'limite_dia',
  JEV_INDISPONIVEL: 'jev_indisponivel', REPETIDA: 'repetida',
});
const ACOES = Object.freeze({
  DECISAO_JEV: 'decisao_jev', REVISAR: 'revisar', SO_SINAIS: 'so_sinais', PULADO: 'pulado',
});
const SITUACOES = Object.freeze({ OK: 'ok', ERRO: 'erro', PULADO: 'pulado', LIMITE: 'limite' });

/**
 * Calcula o orçamento de tempo da chamada: o tempo máximo da mensagem menos o que o processo já
 * gastou (subida do node e imports, `performance.now()` = ms desde o início do processo) e menos
 * a margem de saída. Assim o processo inteiro do gancho respeita o tempo máximo (R1.3).
 * @param {number} tempoMaximoMs `JEV_TEMPO_MAXIMO_MENSAGEM_MS`.
 * @param {() => number} decorridoMs Milissegundos desde o início do processo.
 * @returns {number} Orçamento em ms (pode ser menor que o piso: aí não se chama o Jev).
 */
function calcularOrcamentoMs(tempoMaximoMs, decorridoMs) {
  return Math.floor(tempoMaximoMs - decorridoMs() - MARGEM_SAIDA_MS);
}

/**
 * Cria o resultado no formato do contrato, com os padrões de "só sinais".
 * @param {object} [parcial] Campos que mudam em relação ao padrão.
 * @returns {object} Resultado completo.
 */
function criarResultado(parcial = {}) {
  return {
    pulado: false,
    motivo: MOTIVOS.OK,
    decisao: DECISOES.SINAIS,
    nivel: null,
    effort: null,
    modelos_elegiveis: [],
    confianca: null,
    revisar: false,
    alertas: [],
    custo_usd: 0,
    latencia_ms: 0,
    hash: null,
    erro_codigo: null,
    acao: ACOES.SO_SINAIS,
    situacao: SITUACOES.ERRO,
    ...parcial,
  };
}

/**
 * Completa as dependências injetáveis com as reais.
 * @param {{cliente?: object, agora?: Function, decorridoMs?: Function, arquivoAuditoria?: string,
 *   pastaMarcas?: string, ambiente?: Record<string, string|undefined>}} injetadas Dependências
 *   de teste.
 * @returns {{cliente: object|null, agora: Function, arquivoAuditoria: string|null,
 *   ambiente: Record<string, string|undefined>}} Dependências completas.
 */
function completarDependencias(injetadas) {
  return {
    cliente: injetadas.cliente ?? null,
    agora: injetadas.agora ?? (() => new Date()),
    decorridoMs: injetadas.decorridoMs ?? (() => performance.now()),
    arquivoAuditoria: injetadas.arquivoAuditoria ?? null,
    pastaMarcas: injetadas.pastaMarcas ?? null,
    ambiente: injetadas.ambiente ?? process.env,
  };
}

/**
 * Escolhe o arquivo de auditoria: o injetado, `JEV_AUDITORIA_MENSAGENS` (testes e ensaios) ou o
 * `mensagens-AAAA-MM.jsonl` do mês em `scripts/jev/saidas/`.
 * @param {object} deps Dependências completas.
 * @param {Date} data Momento da mensagem.
 * @returns {string} Caminho do arquivo.
 */
function resolverArquivoAuditoria(deps, data) {
  const doAmbiente = String(deps.ambiente.JEV_AUDITORIA_MENSAGENS ?? '').trim();
  return deps.arquivoAuditoria ?? (doAmbiente || caminhoAuditoriaDoMes(data));
}

/**
 * Lê o código estável de um erro (nunca a mensagem, que pode ter detalhes).
 * @param {unknown} erro Erro capturado.
 * @returns {string} Código do ErroJev, ou `ERRO_INESPERADO`.
 */
function codigoDoErro(erro) {
  return erro instanceof ErroJev ? erro.codigo : CODIGO_ERRO_INESPERADO;
}

/**
 * Cria o cliente do Jev da mensagem: sem repetições nem esperas e com o tempo máximo da mensagem.
 * @param {object} config Configuração das mensagens.
 * @param {Record<string, string|undefined>} ambiente Variáveis de ambiente.
 * @returns {{perguntar: Function}} Cliente.
 * @throws {ErroJev} `CHAVE_AUSENTE` ou `CONFIGURACAO_INVALIDA`.
 */
function criarClienteDaMensagem(config, ambiente) {
  const geral = carregarConfiguracao(ambiente);
  return criarCliente({
    config: {
      ...geral,
      maximoRepeticoes: 0,
      timeoutMs: config.tempoMaximoMs,
      maximoTokens: config.maximoTokensMensagem,
    },
    chave: lerChave({ ambiente, arquivoEnv: geral.arquivoEnv }),
  });
}

/**
 * Normaliza os alertas: só textos curtos, sem segredo (passam por `redigirTexto`).
 * @param {unknown} alertas Alertas devolvidos pelo guardrail.
 * @returns {string[]} Até 5 alertas de até 200 caracteres.
 */
function normalizarAlertas(alertas) {
  if (!Array.isArray(alertas)) return [];
  return alertas
    .filter((alerta) => typeof alerta === 'string' && alerta.trim() !== '')
    .slice(0, MAXIMO_ALERTAS)
    .map((alerta) => redigirTexto(alerta).texto.slice(0, TAMANHO_MAXIMO_ALERTA));
}

/**
 * Coleta os alertas dos guardrails; erro ou demora viram lista vazia.
 * @param {string} texto Texto bruto da mensagem.
 * @param {number} tempoMs Tempo máximo.
 * @returns {Promise<string[]>} Alertas (nunca rejeita).
 */
async function coletarAlertas(texto, tempoMs) {
  try {
    const avaliacao = await comTempoMaximo(() => avaliarMensagem({ texto }), tempoMs);
    return normalizarAlertas(avaliacao?.alertas);
  } catch {
    return [];
  }
}

/**
 * Converte a decisão em resultado final (com custo e ação).
 * @param {object} decisao Saída de {@link decidirMensagem}.
 * @param {number} custoBruto Custo da chamada (arredondado a 9 casas).
 * @returns {object} Resultado; sem nível válido do Jev vira falha (`RESPOSTA_INVALIDA`).
 */
function resultadoDaDecisao(decisao, custoBruto) {
  const custoUsd = Number(custoBruto.toFixed(CASAS_CUSTO));
  if (decisao.decisao === DECISOES.SINAIS) {
    return criarResultado({
      motivo: MOTIVOS.JEV_INDISPONIVEL, erro_codigo: 'RESPOSTA_INVALIDA', custo_usd: custoUsd,
    });
  }
  const ehJev = decisao.decisao === DECISOES.JEV;
  return criarResultado({
    ...decisao,
    custo_usd: custoUsd,
    acao: ehJev ? ACOES.DECISAO_JEV : ACOES.REVISAR,
    situacao: SITUACOES.OK,
  });
}

/**
 * Pergunta ao Jev, dentro do tempo máximo; qualquer falha vira "só sinais".
 * @param {object} pedido Pedido de {@link prepararPedido} (com `state` não nulo).
 * @param {{config: object, deps: object}} contexto Configuração e dependências.
 * @returns {Promise<object>} Resultado parcial (sem alertas, hash e latência).
 */
async function perguntarAoJev(pedido, contexto) {
  const { config, deps } = contexto;
  try {
    const cliente = deps.cliente ?? criarClienteDaMensagem(config, deps.ambiente);
    const resposta = await comTempoMaximo(() => cliente.perguntar({
      state: pedido.state, perguntas: pedido.perguntas, acao: ACAO_CLIENTE,
    }), config.tempoMaximoMs);
    return resultadoDaDecisao(decidirMensagem(resposta.respostas), resposta.custoUsd ?? 0);
  } catch (erro) {
    return criarResultado({ motivo: MOTIVOS.JEV_INDISPONIVEL, erro_codigo: codigoDoErro(erro) });
  }
}

/**
 * Decide se chama o Jev (limite do dia, teto de tokens) e chama.
 * @param {object} pedido Pedido de {@link prepararPedido}.
 * @param {{config: object, deps: object, arquivo: string}} contexto Configuração e dependências.
 * @returns {Promise<object>} Resultado parcial.
 */
async function consultarJev(pedido, contexto) {
  const { config, deps, arquivo } = contexto;
  const gasto = somarCustoDoDia(arquivo, formatarDia(new Date(deps.agora())));
  if (estourouLimiteDia(gasto, config.maximoCustoDiaUsd)) {
    return criarResultado({
      motivo: MOTIVOS.LIMITE_DIA, erro_codigo: 'LIMITE_DIA', situacao: SITUACOES.LIMITE,
    });
  }
  if (pedido.state === null) {
    return criarResultado({ motivo: MOTIVOS.JEV_INDISPONIVEL, erro_codigo: 'LIMITE_TOKENS' });
  }
  return perguntarAoJev(pedido, { config, deps });
}

/**
 * Resultado de mensagem pulada (trivial ou Jev desligado): sem chamada e sem custo.
 * @param {string} motivo Um valor de {@link MOTIVOS}.
 * @returns {object} Resultado com `pulado: true`.
 */
function resultadoPulado(motivo) {
  return criarResultado({
    pulado: true, motivo, acao: ACOES.PULADO, situacao: SITUACOES.PULADO,
  });
}

/**
 * Confere a marca da mensagem: repetida dentro da janela vira "pulado"; senão grava a marca.
 * @param {{hash: string}} pedido Pedido com o hash da mensagem.
 * @param {string} arquivo Arquivo de auditoria (a marca fica na mesma pasta, salvo injeção).
 * @param {object} deps Dependências completas.
 * @returns {boolean} true se a mensagem é repetida e não deve chamar o Jev.
 */
function conferirMarca(pedido, arquivo, deps) {
  const doAmbiente = String(deps.ambiente.JEV_PASTA_MARCAS ?? '').trim();
  const pasta = deps.pastaMarcas ?? (doAmbiente || dirname(arquivo));
  const agoraMs = new Date(deps.agora()).getTime();
  if (ehMensagemRepetida(pasta, pedido.hash, agoraMs)) return true;
  marcarMensagem(pasta, pedido.hash, agoraMs);
  return false;
}

/**
 * Executa a classificação (pode lançar; quem chama captura).
 * @param {{texto?: string, projeto?: string}} entrada Mensagem e projeto.
 * @param {object} deps Dependências completas.
 * @returns {Promise<object>} Resultado, sem a latência.
 */
async function executar(entrada, deps) {
  const config = carregarConfiguracaoMensagem(deps.ambiente);
  const desligado = config.modo === MODOS.DESLIGADO || config.mensagens === MODOS.DESLIGADO;
  if (desligado) return resultadoPulado(MOTIVOS.DESLIGADO);

  const texto = String(entrada.texto ?? '');
  if (ehMensagemTrivial(texto)) return resultadoPulado(MOTIVOS.TRIVIAL);

  const orcamento = { modelo: carregarConfiguracao(deps.ambiente).modelo,
    maximoTokens: config.maximoTokensMensagem };
  const pedido = prepararPedido({ texto, projeto: entrada.projeto }, orcamento);
  const tempoMs = calcularOrcamentoMs(config.tempoMaximoMs, deps.decorridoMs);
  if (tempoMs < PISO_ORCAMENTO_MS) {
    return criarResultado({
      motivo: MOTIVOS.JEV_INDISPONIVEL, erro_codigo: 'TEMPO_ESGOTADO', hash: pedido.hash,
    });
  }
  const arquivo = resolverArquivoAuditoria(deps, new Date(deps.agora()));
  if (conferirMarca(pedido, arquivo, deps)) {
    return { ...resultadoPulado(MOTIVOS.REPETIDA), hash: pedido.hash };
  }
  const limitada = { ...config, tempoMaximoMs: tempoMs };
  const alertas = coletarAlertas(texto, tempoMs);
  const parcial = await consultarJev(pedido, { config: limitada, deps, arquivo });
  return { ...parcial, alertas: await alertas, hash: pedido.hash };
}

/**
 * Classifica a mensagem do usuário: nível, effort, modelos elegíveis e alertas. NUNCA lança.
 * @param {{texto?: string, projeto?: string}} entrada Texto bruto e nome do projeto.
 * @param {{cliente?: {perguntar: Function}, agora?: () => Date, arquivoAuditoria?: string,
 *   ambiente?: Record<string, string|undefined>}} [dependencias] Dependências injetáveis.
 * @returns {Promise<{pulado: boolean, motivo: string, decisao: string, nivel: string|null,
 *   effort: string|null, modelos_elegiveis: string[], confianca: number|null,
 *   revisar: boolean, alertas: string[], custo_usd: number, latencia_ms: number,
 *   hash: string|null}>} Resultado (com campos extras de auditoria e explicação).
 */
export async function classificarMensagem(entrada, dependencias = {}) {
  const deps = completarDependencias(dependencias ?? {});
  const inicio = new Date(deps.agora());
  let resultado;
  try {
    resultado = await executar(entrada ?? {}, deps);
  } catch (erro) {
    resultado = criarResultado({
      motivo: MOTIVOS.JEV_INDISPONIVEL, erro_codigo: codigoDoErro(erro),
    });
  }
  resultado.latencia_ms = Math.max(0, new Date(deps.agora()).getTime() - inicio.getTime());
  if (resultado.motivo !== MOTIVOS.DESLIGADO) {
    const arquivo = resolverArquivoAuditoria(deps, inicio);
    const projeto = redigirTexto(String(entrada?.projeto ?? '')).texto.slice(0, TAMANHO_PROJETO);
    gravarAuditoria(arquivo, { data: inicio, resultado, projeto });
  }
  return resultado;
}

// Texto de contexto para a IA (até 3 linhas curtas em PT-BR): a decisão do Jev (ou o aviso de
// que ele não respondeu) e os alertas dos guardrails. Só acrescenta contexto (INV-2): nunca
// bloqueia nem altera a mensagem do usuário.
import { DECISOES } from './decisao.mjs';

const TAMANHO_MAXIMO_LINHA = 300;
const MAXIMO_MODELOS_NA_LINHA = 4;
const CASAS_CONFIANCA = 2;
const AVISO_SINAIS = 'classifique pelos sinais da skill classificar-tarefa (na dúvida, suba o '
  + 'nível)';
const MOTIVOS_SEM_JEV = Object.freeze({
  limite_dia: 'Jev pausado: limite do dia de custo atingido',
});
const MOTIVO_SEM_JEV_PADRAO = 'Jev indisponível';

/**
 * Formata a confiança com vírgula decimal.
 * @param {number|null} valor Confiança de 0 a 1.
 * @returns {string} Texto (ex.: `0,91`) ou `?`.
 */
function formatarConfianca(valor) {
  if (typeof valor !== 'number') return '?';
  return valor.toFixed(CASAS_CONFIANCA).replace('.', ',');
}

/**
 * Corta uma linha longa demais.
 * @param {string} linha Linha de contexto.
 * @returns {string} Linha com no máximo 300 caracteres.
 */
function limitarLinha(linha) {
  if (linha.length <= TAMANHO_MAXIMO_LINHA) return linha;
  return `${linha.slice(0, TAMANHO_MAXIMO_LINHA - 1)}…`;
}

/**
 * Primeira linha: quem decidiu e o que decidiu.
 * @param {object} resultado Resultado de classificarMensagem.
 * @returns {string} Linha de decisão.
 */
function linhaDecisao(resultado) {
  const confianca = formatarConfianca(resultado.confianca);
  const base = `nível ${resultado.nivel} · effort ${resultado.effort}`;
  if (resultado.decisao === DECISOES.JEV) {
    return `Jev decidiu (confiança ${confianca}): ${base}.`;
  }
  const sinais = (resultado.sinais_pesado ?? []).join(', ');
  const motivoSinais = sinais ? `; sinal de PESADO: ${sinais}` : '';
  return `Jev sugeriu ${resultado.nivel_jev} (confiança ${confianca}${motivoSinais}); `
    + `valendo a matriz: ${base}. Revisão humana recomendada.`;
}

/**
 * Linha dos modelos elegíveis do nível.
 * @param {string[]} modelos Rótulos dos modelos elegíveis.
 * @returns {string} Linha com os primeiros modelos.
 */
function linhaModelos(modelos) {
  const mostrados = modelos.slice(0, MAXIMO_MODELOS_NA_LINHA).join('; ');
  const temMais = modelos.length > MAXIMO_MODELOS_NA_LINHA;
  return `Modelos elegíveis: ${mostrados}${temMais ? ' e outros' : ''}`;
}

/**
 * Monta as linhas de contexto (no máximo 3).
 * @param {object|null} resultado Resultado de classificarMensagem.
 * @returns {string[]} Linhas; vazio se a mensagem foi pulada ou não há o que dizer.
 */
export function montarLinhasContexto(resultado) {
  if (!resultado || resultado.pulado) return [];

  const linhas = [];
  if (resultado.decisao === DECISOES.SINAIS) {
    const motivo = MOTIVOS_SEM_JEV[resultado.motivo] ?? MOTIVO_SEM_JEV_PADRAO;
    linhas.push(`${motivo}: ${AVISO_SINAIS}.`);
  } else {
    linhas.push(linhaDecisao(resultado), linhaModelos(resultado.modelos_elegiveis ?? []));
  }
  if ((resultado.alertas ?? []).length > 0) linhas.push(`Alertas: ${resultado.alertas.join('; ')}`);
  return linhas.map(limitarLinha);
}

/**
 * Monta o contexto da IA: as linhas de {@link montarLinhasContexto} juntas por quebra de linha.
 * @param {object|null} resultado Resultado de classificarMensagem.
 * @returns {string} Texto de até 3 linhas; vazio quando não há contexto a acrescentar.
 */
export function montarContexto(resultado) {
  return montarLinhasContexto(resultado).join('\n');
}

// Decisão da mensagem (JEV-GLOBAL-AI-FINAL.24, R6.1, R6.2, INV-5): confiança ≥ 0,80 e nenhum sinal
// de PESADO aceso -> o Jev decide; senão vale a matriz (nível mais restritivo entre o Jev e os
// sinais) com revisão humana. Sinal de PESADO nunca é rebaixado. Função pura, sem rede.
import {
  LIMIAR_AUTOMATICO, LIMIAR_SINAL_PESADO, extrairConfianca, lerSinais,
} from '../decidir.mjs';
import {
  NIVEIS, derivarEffort, ehNivelValido, listarModelosElegiveis, maisRestritivo,
} from '../modelos.mjs';
import { PERGUNTAS, SINAIS_PESADO } from '../perguntas.mjs';
import { PERGUNTA_MUDA_ALGO } from './perguntas.mjs';

export const DECISOES = Object.freeze({ JEV: 'jev', MATRIZ: 'matriz', SINAIS: 'sinais' });

/**
 * Lista os sinais de PESADO acesos (probabilidade `noul` ≥ limiar).
 * @param {Record<string, number|null>} sinais Sinais lidos das respostas.
 * @returns {string[]} Nomes dos sinais acesos.
 */
function listarSinaisAcesos(sinais) {
  return SINAIS_PESADO.filter((nome) => (sinais[nome] ?? 0) >= LIMIAR_SINAL_PESADO);
}

/**
 * Diz se a mensagem pede uma mudança (resposta `noul` da pergunta `muda_algo`).
 * @param {object} respostas Campo `answers` do Jev.
 * @returns {boolean|null} true/false, ou null se o Jev não respondeu.
 */
function lerMudaAlgo(respostas) {
  const probabilidade = respostas?.[PERGUNTA_MUDA_ALGO]?.noul;
  if (typeof probabilidade !== 'number') return null;
  return probabilidade >= LIMIAR_SINAL_PESADO;
}

/**
 * Escolhe a decisão: sem nível válido do Jev -> sinais; Jev decide -> jev; senão matriz.
 * @param {string|null} nivelJev Nível válido do Jev, ou null.
 * @param {boolean} jevDecide true se a confiança é alta e não há sinal de PESADO.
 * @returns {string} Um valor de {@link DECISOES}.
 */
function escolherDecisao(nivelJev, jevDecide) {
  if (nivelJev === null) return DECISOES.SINAIS;
  if (jevDecide) return DECISOES.JEV;
  return DECISOES.MATRIZ;
}

/**
 * Decide o nível, o effort e os modelos da mensagem a partir das respostas do Jev.
 * @param {object} respostas Campo `answers` da resposta do Jev.
 * @returns {{decisao: string, nivel: string|null, effort: string|null,
 *   modelos_elegiveis: string[], confianca: number|null, revisar: boolean,
 *   nivel_jev: string|null, sinais_pesado: string[], muda_algo: boolean|null}} Decisão; sem nível
 *   válido do Jev, `decisao` é `sinais` e quem chama trata como falha do Jev.
 */
export function decidirMensagem(respostas) {
  const escolha = respostas?.[PERGUNTAS.NIVEL]?.choice;
  const nivelJev = ehNivelValido(escolha) ? escolha : null;
  const acesos = listarSinaisAcesos(lerSinais(respostas));
  const confianca = extrairConfianca(respostas?.[PERGUNTAS.NIVEL]).valor;
  const jevDecide = nivelJev !== null && confianca !== null
    && confianca >= LIMIAR_AUTOMATICO && acesos.length === 0;
  const nivel = maisRestritivo(nivelJev, acesos.length > 0 ? NIVEIS.PESADO : null);
  const decisao = escolherDecisao(nivelJev, jevDecide);
  return {
    decisao,
    nivel: decisao === DECISOES.SINAIS ? null : nivel,
    effort: decisao === DECISOES.SINAIS ? null : derivarEffort(nivel),
    modelos_elegiveis: decisao === DECISOES.SINAIS ? [] : listarModelosElegiveis(nivel),
    confianca,
    revisar: decisao === DECISOES.MATRIZ,
    nivel_jev: nivelJev,
    sinais_pesado: acesos,
    muda_algo: lerMudaAlgo(respostas),
  };
}

// Estado CEGO da mensagem (INV-1, R2.1): o texto passa por `redigirTexto` (segredo e dado pessoal)
// e por `removerRotulos` (nome de modelo, nível, effort), é cortado em 4000 caracteres e ainda é
// ajustado ao teto de tokens da mensagem antes de ir ao Jev. O texto original nunca sai daqui.
import { createHash } from 'node:crypto';
import { estimarTokens } from '../cliente.mjs';
import { redigirTexto, resumirAchados } from '../guardrails/redigir.mjs';
import { sanitizarTexto } from '../estado.mjs';
import { montarPerguntasMensagem } from './perguntas.mjs';

export const TAMANHO_MAXIMO_MENSAGEM = 4000;
/** Limite de entrada para o regex não gastar tempo com texto gigante (ex.: log colado). */
const TAMANHO_MAXIMO_ENTRADA = 200000;
const TAMANHO_HASH = 16;
const TAMANHO_MAXIMO_PROJETO = 80;
const PROJETO_PADRAO = 'projeto';

/**
 * Hash curto do texto já redigido (rastreia a mensagem sem guardá-la).
 * @param {string} textoRedigido Texto sem segredos.
 * @returns {string} 16 primeiros caracteres do SHA-256 em hexadecimal.
 */
export function calcularHashTexto(textoRedigido) {
  return createHash('sha256').update(textoRedigido).digest('hex').slice(0, TAMANHO_HASH);
}

/**
 * Estima os tokens do corpo que o cliente enviaria (mesma conta do cliente.mjs).
 * @param {object} state State da mensagem.
 * @param {{modelo: string, perguntas: object}} contexto Modelo e perguntas do pedido.
 * @returns {number} Tokens estimados.
 */
function estimarPedido(state, contexto) {
  const corpo = JSON.stringify({
    state, model: contexto.modelo, questions: contexto.perguntas,
  });
  return estimarTokens(corpo);
}

/**
 * Corta a mensagem até o pedido caber no teto de tokens da mensagem.
 * @param {object} state State com a mensagem inteira (já limitada a 4000 caracteres).
 * @param {{modelo: string, perguntas: object, maximoTokens: number}} contexto Teto e pedido.
 * @returns {object|null} State ajustado, ou null se nem a mensagem vazia cabe no teto.
 */
function ajustarAoTeto(state, contexto) {
  if (estimarPedido({ ...state, mensagem: '' }, contexto) > contexto.maximoTokens) return null;

  let atual = state;
  let excesso = estimarPedido(atual, contexto) - contexto.maximoTokens;
  while (excesso > 0) {
    const sobra = Math.max(0, atual.mensagem.length - Math.max(1, excesso * 3));
    atual = { ...atual, mensagem: atual.mensagem.slice(0, sobra) };
    excesso = estimarPedido(atual, contexto) - contexto.maximoTokens;
  }
  return atual;
}

/**
 * Prepara o pedido ao Jev: texto redigido, state cego, perguntas e hash.
 * @param {{texto: string, projeto?: string}} mensagem Texto bruto e nome do projeto.
 * @param {{modelo: string, maximoTokens: number}} orcamento Modelo do Jev e teto de tokens.
 * @returns {{state: object|null, perguntas: object, hash: string,
 *   achados: Record<string, number>}} `state` é null se o teto de tokens for pequeno demais.
 */
export function prepararPedido(mensagem, orcamento) {
  const bruto = String(mensagem.texto ?? '').slice(0, TAMANHO_MAXIMO_ENTRADA);
  const redigido = redigirTexto(bruto);
  const projeto = sanitizarTexto(redigirTexto(mensagem.projeto ?? '').texto)
    .slice(0, TAMANHO_MAXIMO_PROJETO) || PROJETO_PADRAO;
  const state = {
    projeto,
    mensagem: sanitizarTexto(redigido.texto).slice(0, TAMANHO_MAXIMO_MENSAGEM),
  };
  const perguntas = montarPerguntasMensagem();
  return {
    state: ajustarAoTeto(state, { ...orcamento, perguntas }),
    perguntas,
    hash: calcularHashTexto(redigido.texto),
    achados: resumirAchados(redigido.achados),
  };
}

// Limites da mensagem: filtro de mensagens triviais (R1.4), limite de custo do dia (R2.3) e tempo
// máximo total (R1.3). Funções pequenas e puras, sem estado.
import { ErroJev } from '../config.mjs';

/** Mensagens de até este tamanho (depois de `trim`) não vão ao Jev. */
const TAMANHO_MAXIMO_TRIVIAL = 3;
const PREFIXO_COMANDO = '/';

/**
 * Diz se a mensagem deve pular o Jev: vazia, até 3 caracteres ou começando com `/` (comando).
 * @param {string} texto Texto bruto da mensagem.
 * @returns {boolean} true para pular.
 */
export function ehMensagemTrivial(texto) {
  const limpo = String(texto ?? '').trim();
  return [...limpo].length <= TAMANHO_MAXIMO_TRIVIAL || limpo.startsWith(PREFIXO_COMANDO);
}

/**
 * Diz se o gasto do dia já atingiu o limite (limite 0 bloqueia sempre).
 * @param {number} gastoUsd Custo já gasto hoje, em US$.
 * @param {number} maximoUsd `JEV_MAX_CUSTO_DIA`.
 * @returns {boolean} true quando não se deve chamar o Jev.
 */
export function estourouLimiteDia(gastoUsd, maximoUsd) {
  return gastoUsd >= maximoUsd;
}

/**
 * Executa o trabalho com um tempo máximo total; passou, rejeita com `TEMPO_ESGOTADO`.
 * @param {() => Promise<unknown>} trabalho Função que devolve a promessa.
 * @param {number} tempoMs Tempo máximo em milissegundos.
 * @returns {Promise<unknown>} Resultado do trabalho.
 * @throws {ErroJev} `TEMPO_ESGOTADO` se passar do tempo.
 */
export function comTempoMaximo(trabalho, tempoMs) {
  let relogio;
  const prazo = new Promise((_, rejeitar) => {
    relogio = setTimeout(() => {
      rejeitar(new ErroJev('TEMPO_ESGOTADO', `Passou de ${tempoMs} ms.`));
    }, tempoMs);
  });
  const andamento = Promise.resolve().then(trabalho);
  andamento.catch(() => {});
  return Promise.race([andamento, prazo]).finally(() => clearTimeout(relogio));
}

// Perguntas do Jev para a MENSAGEM do usuário (JEV-GLOBAL-AI-FINAL.3): é pedido que muda algo ou
// só pergunta/conversa? qual o nível? e os quatro sinais de PESADO (os mesmos nomes de
// `SINAIS_PESADO`, para a agregação de decidir.mjs valer igual). O Jev só vê o `state` cego.
import { CRITERIOS_NIVEL, PERGUNTAS, SINAIS_PESADO } from '../perguntas.mjs';

/** Nome da pergunta extra da mensagem; as demais reaproveitam os nomes de `PERGUNTAS`. */
export const PERGUNTA_MUDA_ALGO = 'muda_algo';

const INSTRUCAO_MUDA_ALGO = 'A `mensagem` pede para criar, alterar, apagar, corrigir ou executar '
  + 'algo (código, arquivo, configuração, comando)? Pergunta, dúvida ou conversa NÃO muda nada.';
const INSTRUCAO_NIVEL = 'Qual é o nível de esforço e risco do que a `mensagem` pede? Se só '
  + 'pergunta ou conversa, use o nível de quem responderia. Use a regra mais restritiva: basta um '
  + 'sinal de PESADO para ser PESADO.';
const INSTRUCOES_SINAIS = Object.freeze({
  [PERGUNTAS.BANCO]: [
    'A `mensagem` envolve banco de dados, SQL, RLS, migração ou seeds?',
    'envolve banco de dados', 'não envolve banco de dados',
  ],
  [PERGUNTAS.SEGREDO]: [
    'A `mensagem` envolve chaves, tokens, senhas, login, papéis, permissões ou segurança?',
    'envolve segredo ou segurança', 'não envolve segredo nem segurança',
  ],
  [PERGUNTAS.MASSA]: [
    'A `mensagem` pede mudança em massa, geração em lote ou apagar dados?',
    'muda ou apaga muita coisa de uma vez', 'não pede mudança em massa nem apagar dados',
  ],
  [PERGUNTAS.MAIS_DE_3_ARQUIVOS]: [
    'A `mensagem` pede mexer em mais de 3 arquivos ligados entre si?',
    'mexe em mais de 3 arquivos ligados', 'mexe em até 3 arquivos',
  ],
});

/**
 * Monta uma pergunta `noul` (sim/não com probabilidade).
 * @param {string} instrucao Pergunta ao Jev.
 * @param {string} seSim Descrição do "sim".
 * @param {string} seNao Descrição do "não".
 * @returns {object} Pergunta no formato do Jev.
 */
function perguntaSimNao(instrucao, seSim, seNao) {
  return { type: 'noul', instructions: instrucao, criteria: { true: seSim, false: seNao } };
}

/**
 * Monta as 6 perguntas da mensagem (muda algo, nível e os 4 sinais de PESADO). O effort não é
 * perguntado: vem do nível final pela C21 (derivarEffort).
 * @returns {Record<string, object>} Perguntas no formato `questions` do /v1/systemone.
 */
export function montarPerguntasMensagem() {
  const sinais = Object.fromEntries(SINAIS_PESADO.map((nome) => [
    nome, perguntaSimNao(...INSTRUCOES_SINAIS[nome]),
  ]));
  return {
    [PERGUNTA_MUDA_ALGO]: perguntaSimNao(
      INSTRUCAO_MUDA_ALGO, 'pede uma mudança ou execução', 'só pergunta ou conversa',
    ),
    [PERGUNTAS.NIVEL]: { type: 'choice', instructions: INSTRUCAO_NIVEL, criteria: CRITERIOS_NIVEL },
    ...sinais,
  };
}

// Marca por mensagem (RULES-LOCAL-JEV.5, R2.2): quando dois ganchos (projeto e conta) recebem a
// MESMA mensagem quase ao mesmo tempo, só o primeiro chama o Jev. A marca é um arquivo pequeno
// com o instante da classificação, em `scripts/jev/saidas/` (fora do Git). Nunca grava o texto,
// só o hash. Falha ao ler ou gravar a marca nunca derruba a mensagem (vale "não repetida").
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

/** Janela em que a mesma mensagem (mesmo hash) não é classificada de novo. */
export const JANELA_REPETIDA_MS = 10000;
const PREFIXO_MARCA = 'marca-';
const SUFIXO_MARCA = '.txt';
const REGEX_HASH = /^[0-9a-f]{8,64}$/;

/**
 * Caminho da marca de um hash, ou null se o hash não for hexadecimal seguro.
 * @param {string} pasta Pasta das marcas.
 * @param {string} hash Hash da mensagem.
 * @returns {string|null} Caminho do arquivo da marca.
 */
function caminhoDaMarca(pasta, hash) {
  if (typeof hash !== 'string' || !REGEX_HASH.test(hash)) return null;
  return join(pasta, `${PREFIXO_MARCA}${hash}${SUFIXO_MARCA}`);
}

/**
 * Diz se a mesma mensagem foi marcada há menos de {@link JANELA_REPETIDA_MS}.
 * @param {string} pasta Pasta das marcas.
 * @param {string} hash Hash da mensagem.
 * @param {number} agoraMs Instante atual em ms.
 * @returns {boolean} true se é repetida; erro de leitura vale false.
 */
export function ehMensagemRepetida(pasta, hash, agoraMs) {
  try {
    const caminho = caminhoDaMarca(pasta, hash);
    if (!caminho) return false;
    const marcadoEm = Number(readFileSync(caminho, 'utf8').trim());
    const decorrido = agoraMs - marcadoEm;
    return Number.isFinite(decorrido) && decorrido >= 0 && decorrido < JANELA_REPETIDA_MS;
  } catch {
    return false;
  }
}

/**
 * Grava a marca da mensagem. Nunca lança.
 * @param {string} pasta Pasta das marcas.
 * @param {string} hash Hash da mensagem.
 * @param {number} agoraMs Instante atual em ms.
 * @returns {void}
 */
export function marcarMensagem(pasta, hash, agoraMs) {
  try {
    const caminho = caminhoDaMarca(pasta, hash);
    if (!caminho) return;
    mkdirSync(pasta, { recursive: true });
    writeFileSync(caminho, String(agoraMs), 'utf8');
  } catch {
    // Sem marca, a próxima chamada igual apenas consulta o Jev de novo.
  }
}

