import { PREVIDENCIA_FIESC, CHAVE_ANALISE_PREVIDENCIA } from './previdenciaFiesc.js';
import {
  criarElemento,
  criarLista,
  criarSecaoModal,
  ligarFechamentoModal,
} from './elementosUi.js';
import { PROJETO_NOMADE, CHAVE_ANALISE_NOMADE } from './projetoNomade.js';
import { BOT_TELEGRAM, CHAVE_ANALISE_BOT_TELEGRAM } from './botTelegram.js';
import { prepararModalDocumentos } from './documentosPrevidencia.js';
import { prepararModalCalculos } from './calculosPrevidencia.js';
import { obterAnaliseFinanceira, criarSeloStatus } from './analisesFinanceiras.js';

/**
 * Cria o bloco de um dado do card (rótulo + valor).
 * @param {string} rotulo - Nome do dado.
 * @param {string} valor - Valor do dado.
 * @returns {HTMLElement} Bloco do dado.
 */
function criarDadoCard(rotulo, valor) {
  const bloco = criarElemento('div', 'ideia-dado');
  bloco.append(criarElemento('dt', 'ideia-dado-rotulo', rotulo));
  bloco.append(criarElemento('dd', 'ideia-dado-valor', valor));
  return bloco;
}

/**
 * Cria um botão de ação do card.
 * @param {string} texto - Texto do botão.
 * @param {() => void} aoClicar - Chamado ao clicar.
 * @returns {HTMLButtonElement} Botão pronto.
 */
function criarBotaoAcao(texto, aoClicar) {
  const botao = criarElemento('button', 'btn ideia-detalhes', texto);
  botao.type = 'button';
  botao.addEventListener('click', aoClicar);
  return botao;
}

/**
 * Monta o card da Previdência Privada FIESC.
 * @param {() => void} aoAbrirDetalhes - Chamado ao clicar em Detalhes.
 * @param {() => void} aoAbrirCalculos - Chamado ao clicar em Cálculos.
 * @param {() => void} aoAbrirDocumentos - Chamado ao clicar em Documentos.
 * @returns {HTMLElement} Card pronto.
 */
function criarCardPrevidencia(aoAbrirDetalhes, aoAbrirCalculos, aoAbrirDocumentos) {
  const card = criarElemento('article', 'dashboard-card');
  const topo = criarElemento('div', 'ideia-topo');
  topo.append(
    criarElemento('h2', 'dashboard-card-titulo', PREVIDENCIA_FIESC.nome),
    criarSeloStatus(CHAVE_ANALISE_PREVIDENCIA),
  );
  card.append(topo);

  const dados = criarElemento('dl', 'ideia-dados');
  PREVIDENCIA_FIESC.resumoCard.forEach(([rotulo, valor]) => dados.append(criarDadoCard(rotulo, valor)));
  card.append(dados);

  const acoes = criarElemento('div', 'dashboard-card-acoes');
  acoes.append(
    criarBotaoAcao('Cálculos', aoAbrirCalculos),
    criarBotaoAcao('Documentos', aoAbrirDocumentos),
    criarBotaoAcao('Detalhes', aoAbrirDetalhes),
  );
  card.append(acoes);
  return card;
}

/**
 * Monta um card de projeto simples: título, status, dados e (se houver) link do site.
 * @param {{nome: string, site: string|null, resumoCard: string[][]}} projeto - Dados do card.
 * @param {string} chave - Chave da análise financeira (define o status).
 * @returns {HTMLElement} Card pronto.
 */
function criarCardProjeto(projeto, chave) {
  const card = criarElemento('article', 'dashboard-card');
  const topo = criarElemento('div', 'ideia-topo');
  topo.append(
    criarElemento('h2', 'dashboard-card-titulo', projeto.nome),
    criarSeloStatus(chave),
  );
  card.append(topo);

  const dados = criarElemento('dl', 'ideia-dados');
  projeto.resumoCard.forEach(([rotulo, valor]) => dados.append(criarDadoCard(rotulo, valor)));
  card.append(dados);

  if (projeto.site) card.append(criarLinkSite(projeto.site));
  return card;
}

/**
 * Cria o bloco com o botão "Abrir site".
 * @param {string} endereco - Endereço do site.
 * @returns {HTMLElement} Bloco de ações com o link.
 */
function criarLinkSite(endereco) {
  const acoes = criarElemento('div', 'dashboard-card-acoes');
  const link = criarElemento('a', 'btn ideia-detalhes', 'Abrir site');
  link.href = endereco;
  link.target = '_blank';
  link.rel = 'noopener noreferrer';
  acoes.append(link);
  return acoes;
}

/**
 * Preenche o modal com os dados do plano, a análise (se existir) e as perguntas.
 * @param {HTMLElement} corpo - Elemento que recebe o conteúdo.
 * @returns {void}
 */
function preencherModal(corpo) {
  const analise = obterAnaliseFinanceira(CHAVE_ANALISE_PREVIDENCIA);
  const secaoAnalise = analise
    ? [criarSecaoModal('Análise financeira (CFO)', [criarElemento('pre', 'ideia-analise', analise)])]
    : [];
  const secoesPlano = PREVIDENCIA_FIESC.secoes.map(secao =>
    criarSecaoModal(secao.titulo, [criarLista(secao.itens)]));

  corpo.replaceChildren(
    ...secaoAnalise,
    ...secoesPlano,
    criarSecaoModal('Dados a informar para a análise', [criarLista(PREVIDENCIA_FIESC.dadosAInformar)]),
    criarSecaoModal('O que a análise precisa responder', [criarLista(PREVIDENCIA_FIESC.perguntasDaAnalise)]),
    criarElemento('p', 'ideia-aviso', 'Fontes: Regulamento do FIESCprev e Cartilha do Participante 2025. [CONFIRMAR] = dado que nenhum dos dois traz (fica no Plano de Custeio).'),
  );
}

/**
 * Abre o modal (<dialog>) com os detalhes do plano.
 * @param {HTMLDialogElement} modal - Elemento do modal.
 * @returns {void}
 */
function abrirModal(modal) {
  modal.querySelector('#ideia-modal-titulo').textContent = PREVIDENCIA_FIESC.nome;
  preencherModal(modal.querySelector('#ideia-modal-corpo'));
  modal.showModal();
}

/**
 * Inicializa a página: desenha o card e liga o modal.
 * @returns {void}
 */
function iniciar() {
  const area = document.getElementById('dashboard-cards');
  const modal = document.getElementById('ideia-modal');
  const modalCalculos = document.getElementById('calculos-modal');
  const modalDocumentos = document.getElementById('documentos-modal');
  if (!area || !modal || !modalCalculos || !modalDocumentos) return;

  ligarFechamentoModal(modal);
  ligarFechamentoModal(modalCalculos);
  ligarFechamentoModal(modalDocumentos);
  const abrirDocumentos = prepararModalDocumentos(modalDocumentos);
  const abrirCalculos = prepararModalCalculos(modalCalculos);
  area.replaceChildren(
    criarCardPrevidencia(() => abrirModal(modal), abrirCalculos, abrirDocumentos),
    criarCardProjeto(PROJETO_NOMADE, CHAVE_ANALISE_NOMADE),
    criarCardProjeto(BOT_TELEGRAM, CHAVE_ANALISE_BOT_TELEGRAM),
  );
}

iniciar();

// ============================================================================
// DOCUMENTOS DA PREVIDÊNCIA - modal com abas e um iframe para cada PDF
// ============================================================================
import { DOCUMENTOS_PREVIDENCIA } from './previdenciaFiesc.js';
import { criarElemento } from './elementosUi.js';

/**
 * Confere se o endereço realmente entrega um PDF. Se o arquivo não existir, o servidor
 * pode devolver a página do próprio sistema, que não deve aparecer dentro do iframe.
 * @param {string} arquivo - Endereço do PDF.
 * @returns {Promise<boolean>} true se a resposta for um PDF.
 */
async function ehPdf(arquivo) {
  try {
    const resposta = await fetch(arquivo, { method: 'HEAD' });
    return resposta.ok && (resposta.headers.get('content-type') || '').includes('pdf');
  } catch {
    return false;
  }
}

/**
 * Mostra um documento no iframe (ou um aviso, se o PDF não estiver disponível).
 * @param {object} el - Elementos do modal (abas, iframe, link, aviso).
 * @param {{titulo: string, arquivo: string}} documento - Documento exibido.
 * @returns {Promise<void>}
 */
async function mostrarDocumento(el, documento) {
  el.abas.querySelectorAll('button').forEach(aba => {
    aba.setAttribute('aria-selected', String(aba.textContent === documento.titulo));
  });
  el.link.href = documento.arquivo;
  el.iframe.title = documento.titulo;

  const disponivel = await ehPdf(documento.arquivo);
  el.iframe.hidden = !disponivel;
  el.aviso.hidden = disponivel;
  el.iframe.src = disponivel ? documento.arquivo : 'about:blank';
}

/**
 * Liga o modal de documentos: cria as abas e abre o primeiro documento ao abrir.
 * @param {HTMLDialogElement} modal - Elemento do modal de documentos.
 * @returns {() => void} Função que abre o modal.
 */
export function prepararModalDocumentos(modal) {
  const el = {
    abas: modal.querySelector('#documentos-abas'),
    iframe: modal.querySelector('#documentos-iframe'),
    link: modal.querySelector('#documentos-link'),
    aviso: modal.querySelector('#documentos-aviso'),
  };
  DOCUMENTOS_PREVIDENCIA.forEach(documento => {
    const aba = criarElemento('button', 'documentos-aba', documento.titulo);
    aba.type = 'button';
    aba.setAttribute('role', 'tab');
    aba.addEventListener('click', () => mostrarDocumento(el, documento));
    el.abas.append(aba);
  });

  modal.addEventListener('close', () => { el.iframe.src = 'about:blank'; });
  return () => {
    modal.showModal();
    mostrarDocumento(el, DOCUMENTOS_PREVIDENCIA[0]);
  };
}

// ============================================================================
// ELEMENTOS DE INTERFACE - pequenos construtores de DOM usados pelas páginas
// ============================================================================

/**
 * Cria um elemento com classe e texto.
 * @param {string} tag - Nome da tag.
 * @param {string} classe - Classe CSS (pode ser vazia).
 * @param {string} [texto] - Texto do elemento.
 * @returns {HTMLElement} Elemento criado.
 */
export function criarElemento(tag, classe, texto = '') {
  const elemento = document.createElement(tag);
  if (classe) elemento.className = classe;
  elemento.textContent = texto;
  return elemento;
}

/**
 * Cria uma lista (<ul>) a partir de textos.
 * @param {string[]} itens - Textos dos itens.
 * @returns {HTMLUListElement} Lista pronta.
 */
export function criarLista(itens) {
  const lista = criarElemento('ul', 'ideia-lista');
  itens.forEach(item => lista.append(criarElemento('li', '', item)));
  return lista;
}

/**
 * Cria uma seção do modal (título + conteúdo).
 * @param {string} titulo - Título da seção.
 * @param {HTMLElement[]} conteudo - Elementos da seção.
 * @returns {HTMLElement} Seção pronta.
 */
export function criarSecaoModal(titulo, conteudo) {
  const secao = criarElemento('section', 'ideia-secao');
  secao.append(criarElemento('h3', '', titulo));
  secao.append(...conteudo);
  return secao;
}

/**
